\section{Two-dimensional non-invertible symbolic dynamics}
\label{sec:prelim}

We use the convention that $0 \in \NN$ (see Remark~\ref{rmk:niscat} below).
The standard generators of $\NN^2$ (resp.\ $\ZZ^2$) are denoted $\varepsilon_1,\varepsilon_2$, and we write $n_i$ for the $i^{\textrm{th}}$ coordinate of $n \in \NN^2$. We define a partial order on $\NN^2$ by $m\leq n$ if $m_i \leq n_i$ for $i=1, 2$.
For $m,n \in \mathbb{N}^2$, we write $m \vee n$ for their coordinatewise maximum and $m \wedge n$ for their coordinatewise minimum. 

For completeness, we include a brief overview of two-dimensional one-sided shifts of finite type, as systematic treatments of this topic are scarce in the literature. We assume familiarity with the basic theory of one-dimensional shifts of finite type, as found in \cite{lind-marcus} and \cite{Kitchens}.



To fix notation, we begin with a discussion of one-dimensional dynamical systems.

\subsection{One-dimensional preliminaries}




\begin{definitions}
A \emph{directed graph} is a quadruple $E= (E^0,E^1,r,s)$, where $E^0, E^1$ are sets of vertices and edges, respectively, and $r, s: E^1 \to E^0$ are maps giving the range and source of each edge respectively. We say that $E$ is {\em source-free} or {\em has no sources} if $r$ is onto; it is \emph{essential} if both $r,s$ are onto.
\label{defs:directed}
\end{definitions} 

\begin{example}
\label{ex:bouquet}
From a finite set $X$, we construct an essential (directed) graph $B_X$, the ``bouquet of $X$ loops''. This graph has one vertex and $B_X^1 = \{ e_x: x \in X\}$; the range and source maps are uniquely defined.
\end{example}

For a directed graph $E$ and $n \in \NN$, $E^n$ denotes the directed paths of length $n$ in $E$:
\begin{equation}
    \label{eq:def-En}
    E^n = \{ e_1 \cdots e_n: e_i \in E^1, \ r(e_i) = s(e_{i-1}) \ \text{for all }i\}.
\end{equation}
We denote the collection of finite directed paths in $E$ by $E^* := \bigcup_{n \ge 0} E^n$. The range and source maps $r, s: E^1 \to E^0$ extend naturally to $E^*$ 
(where $r(v)=s(v)=v$ for all $v \in E^0$). 
Given $v,w \in E^0$ and $F \subseteq E^*$ define $vF := r^{-1}(v) \cap F$, $Fw := s^{-1}(w) \cap F$, and $vFw := vF \cap Fw$. 

\begin{remark} \label{rmk:1graph2b}
The set $E^*$ becomes a category where the objects are the vertices $E^0$ and the domain of a morphism (path) is its source %range
and the range of a morphism (path) is its categorical range. 
%  source
In \cite{maclane} this is called the \emph{free (or path) category generated by $E$} since there are no relations required.
\end{remark}

\begin{remark} \label{rmk:niscat}
One can identify $\NN$ with the path category of the directed graph $B_X$ where $X$ has one element.
\end{remark}


Let $E=(E^0,E^1,r,s)$ be an essential directed graph. Then,
as in \cite[Definition 2.2.5 and Section 13.8]{lind-marcus}, we define
\begin{equation}\label{eq:inf-path-space-defn}
\textsf{X}_E^+ = \{ x=(x_n) \in (E^1)^{\NN} : r(x_n) = s(x_{n-1}) \text{ for all } n \in \NN \}
\end{equation}
to be the one-sided, one-dimensional shift of finite type associated to the directed graph $E$.



\subsection{One-sided, two-dimensional shifts of finite type}

The following definition is adapted from \cite[\S 2]{Schmidt}.

Let $\mathcal{A}$ be a finite set (alphabet).  Define
$\mathcal{A}^{\NN^2} = \{ x : \NN^2 \to \mathcal{A}\}$. A typical point $x \in \mathcal{A}^{\NN^2}$ is written as $x= ( x_n : n \in \NN^2)$, where $x_n \in \mathcal{A}$ denotes the value of $x$ at $n \in \NN^2$. 

We equip $\mathcal A^{\NN^2}$ with the product topology.  That is, the basic open sets of $\mathcal A^{\NN^2}$ are the {\em cylinder sets} $Z(x[0,m]),$ for $x \in \mathcal A^{\NN^2}$ and $m \in \NN^2$, defined by
\[ Z(x[0,m]) = \{ y \in \mathcal A^{\NN^2} : x_n = y _n \text{ for all } 0 \leq n \leq m\}.\]
There is an action $\sigma$ of $\NN^2$ on $\mathcal{A}^{\NN^2}$ defined by
\begin{equation} \label{eq:shift}
( \sigma^m (x))_n = x_{n+m}
\end{equation}
for every $x=(x_n) \in \mathcal{A}^{\NN^2}$ and $m \in \NN^2$. 

\begin{definitions}
A subset $X \subset \mathcal{A}^{\NN^2}$ is called \emph{shift-invariant} if $\sigma^m(X) =X$ for every $m \in \NN^2$, and a closed shift-invariant subset $X \subset \mathcal{A}^{\NN^2}$ is called a \emph{(one-sided) subshift}. If $X \subset \mathcal{A}^{\NN^2}$ is a subshift then we write $\sigma = \sigma_X$ for the restriction of the shift action \eqref{eq:shift} to $X$, and we say that $(X,\sigma)$ is a \emph{shift space}. 

For any subset $S \subset \NN^2$, we denote by $\pi_S : \mathcal{A}^{\NN^2} \to \mathcal{A}^S$ the projection map which restricts every $x \in \mathcal{A}^{\NN^2}$ to $S$. A subshift $X \subset \mathcal{A}^{\NN^2}$ is a {\em one-sided subshift of finite type (SFT)} if there exist a finite set $Z \subset \NN^2$ and a finite collection $\mathcal F$ of functions $f: Z \to \mathcal A$, such that
\begin{equation} \label{eq:sftdef}
X = \{ x \in \mathcal{A}^{\NN^2} : \pi_Z(\sigma^m(x)) \in \mathcal F
\text{ for every } m \in \NN^2 \} .
\end{equation}
\end{definitions}


\noindent
This definition resembles the ``allowed blocks" model of shift spaces described in \cite[Section 2.1]{lind-marcus}: A configuration $x \in \mathcal{A}^{\NN^2}$ belongs to the shift space $X$ if whenever $x$ is restricted to some translate of $Z$ the values of $\mathcal{A}$ found there match those allowed in $Z$.


\subsection{Sliding-block codes, conjugacy, inversion} \label{sec:sbc}

\begin{definition}[Blocks, block map]
Let $m \in \NN^2$ and 
$X \subset \mathcal{A}^{\NN^2}$ be a one-sided SFT. The collection of $m$-\emph{blocks} in $X$ is defined by
\[
B_m (X) = \{ x[a,a+m] : %\text{ some } 
x \in X , %\text{ some } 
a \in \NN^2 \} .
\]
\end{definition}

\noindent
Without loss of generality $B_0(X)= \mathcal{A}$. 


The following is adapted from Kitchens \cite[page 25]{Kitchens}. Let $X$ be a SFT over the alphabet $\mathcal A$, and $Y$ be a SFT over the alphabet $\mathcal B$. Fix $\ell \in \NN^2$. An $\ell$-\emph{block map} $\phi: (X, \sigma_X) \to (Y, \sigma_Y)$ is determined by a map $\Phi : B_\ell (X) \to B_0 (Y)$ that is consistent with $X$ and $Y$ in the following sense: For every $x \in X, a \in \NN^2$, and $i=1,2$, we have
\begin{equation}
    \label{eq:l-block-map}
\Phi ( x [a,a+\ell] ) \Phi ( x[a+\varepsilon_i , a+\ell+\varepsilon_i ] ) \in B_{\varepsilon_i} (Y), 
\end{equation}

\noindent
then %given a map $\Phi$ satisfying Equation \eqref{eq:l-block-map}, 
the associated $\ell$-block map $\phi  : (X,\sigma_X) \to (Y,\sigma_Y)$
is given by
\[
(\phi (x))_n = \Phi(x[ n, n+ \ell]) .
\]


\begin{lemma}
    \label{lem:block-map-cts}
    Every block map $\phi: (X, \sigma_X) \to (Y, \sigma_Y)$ is continuous and shift commuting, that is, $\sigma_Y \circ \phi = \phi \circ \sigma_X.$
\end{lemma}
\begin{proof}
Suppose $\phi: X \to Y$ is an $\ell$-block map.  Fix $n \in \NN^2$ and consider a basic open set $Z(y[0, n])$ in $Y$. 
Note that 
\begin{align*} 
\phi^{-1}(Z(y[0,n]))&  = \{ x \in X : \Phi(x[j, j+\ell]) = y_j \ \text{for all } 0\leq j\leq n\}\\
&= \bigcup \{ Z(x[0, n+\ell]): \Phi(x[j, j+\ell]) = y_j \ \text{for all } 0\leq j\leq n\},
\end{align*}
being a union of cylinder sets, is open. Hence $\phi$ is continuous.


To see that $\sigma_Y \circ \phi = \phi \circ \sigma_X,$ let $x\in X$, $n \in \NN^2$ and  $i= 1,2.$  Then 
\[ \sigma_Y^{\varepsilon_i}(\phi(x))_n = \phi(x)_{n+\varepsilon_i} = \Phi(x[n+ \varepsilon_i, n + \varepsilon_i + \ell]), \]
while $\phi(\sigma^{\varepsilon_i}_X(x))_n = \phi((x_{k+\varepsilon_i})_k)_n = \Phi(x[n+\varepsilon_i, n+\varepsilon_i +\ell]).$
\end{proof}


The argument of \cite[Theorem 1.4.9]{Kitchens} generalizes to show that any continuous shift commuting map between shift spaces is a block map.
In particular, every conjugacy %arises from 
can be viewed as a block map.

\noindent
\textbf{Standing assumption}
In the same way that Lind and Marcus reduce arguments to using $1$-block maps for shifts of finite maps in \cite[\S 2]{lind-marcus}, we may do the same here:
 By considering the sizes of all the forbidden blocks and then applying a suitable higher block presentation (cf. \cite[p.27]{Kitchens}), we may assume that 
\begin{equation} \label{eq:bestF}
Z = \{ 0,1 \}^2 \subset \NN^2 
\end{equation}
in \eqref{eq:sftdef}. 



\begin{definition}[Conjugacy]
\label{def:conjugacy}
 The shift spaces $(X,\sigma_X)$ and $(Y,\sigma_Y)$ are \emph{conjugate} if there is a homeomorphism $h : X \to Y$ satisfying 
 \[ h \circ \sigma_X = \sigma_Y \circ h.\]

\end{definition}


In two dimensions, the choice of horizontal and vertical directions is somewhat arbitrary. 
Hence (following \cite{johnson-madden}) we define an operation on a shift space which swaps these directions.

\begin{definition}[Inversion] \label{dfn:inversion}
Fix an alphabet $\mathcal A$.
The {\em inversion} of the shift space $(X, \sigma)$ is $(\theta(X), \sigma')$, where 
\begin{align}\label{eq:inversiondef}
    \theta(X)= \{x: \NN^2 \to \mathcal A \ |  \text{ there is }  y \in X 
   & \text{ such that } \\ 
   &\text{ for all } n= (n_1, n_2) \in \NN^2,
    x_{(n_1, n_2)} = y_{(n_2, n_1)}\}.
    \nonumber
\end{align} 
We write $x = \theta(y)$.  The shift map is also inverted in $\theta(X)$; that is, $\sigma'$ is given by 
 $$(\sigma')^{(m_1, m_2)}(\theta(y))_{(n_1, n_2)} := \theta(y)_{(n_1 + m_2, n_2 + m_1)} = y_{(n_2 + m_1, n_1 + m_2)}.$$

\end{definition}

%\noindent
For $x\in \theta(X)$, we write $x= \theta(y)$ for some $y\in X$, and observe that $X$ is a SFT if and only if $\theta(X)$ is.

\begin{lemma}
Let $(X, \sigma)$ be a shift space and $( \theta(X), \sigma' )$ be the inversion of $X$.  Then $\theta : X \to \theta(X)$ is a conjugacy.
\end{lemma}

\begin{proof}
Evidently, $\theta^{-1} $ and $\theta$ are given by the same formula; in particular, $\theta$ is a bijection. Moreover, $\theta \circ \sigma = \sigma' \circ \theta,$ since for any $m, n \in \NN^2,$
\begin{align*} 
(\sigma') ^{(m_1, m_2)}(\theta(y))_{(n_1, n_2)} &  =  \theta(y)_{(n_1 + m_2, n_2 + m_1)} = y_{(n_2 + m_1, n_1 + m_2)}, \text{ while }\\
  \theta (\sigma^{(m_1, m_2)}(y))_{(n_1, n_2)} & = (\sigma^{(m_1, m_2)}(y))_{(n_2, n_1)} = y_{(n_2 + m_1, n_1 + m_2)}.
  \end{align*}
  It is straightforward to see that $\theta$ is continuous; for instance, the inverse image of the cylinder set %$B([0,m]) \in \theta(X)$ is $B([0,m'])$ where $m'=(m_2,m_1)$ if $m=(m_1,m_2)$. 
  $Z(x[(0,(m_1, m_2))])$ is 
  \begin{eqnarray*}
  \{ y \in X: y_{(n_2, n_1)} = x_{(n_1, n_2)} \text{ for all } n = (n_1, n_2) \text{ with } (n_1, n_2) \leq (m_1, m_2)\},
  \end{eqnarray*}
which is $Z(\theta(x)[(0, (m_2, m_1))])$, another cylinder set. We conclude that $\theta$ is a homeomorphism, which completes the proof.
\end{proof}










\section{Textile systems and their dynamical systems} \label{sec:textile}

Just as every one-dimensional SFT can be realized as the edge shift of a directed graph \cite[Theorem 2.3.2]{lind-marcus}, every 2-dimensional SFT can be realized using a pair of graphs woven together into the form of a {\em textile system}. Johnson and Madden establish in \cite[Proposition 2.3]{johnson-madden} that every (two-sided) $2$-dimensional shift of finite type is conjugate to a textile system SFT, by using a higher block argument similar to that given in Section~\ref{sec:sbc}. 

The definition that follows is an adaptation of the original definition given by \cite{nasu}.

\begin{definition}\label{def:textile}
A {\em textile system} $T=(p,q:F \to E)$ consists of two directed graphs $F, E$ and two graph homomorphisms $p, q: F \to E$ such that the  function $A : F^1 \to F^0 \times E^1 \times F^0 \times E^1$ given by
\[
 A(f) = (r(f), p(f), s(f), q(f)) 
\]
is injective. 
\end{definition}


\begin{remark}
In \cite{johnson-madden}, Johnson and Madden restrict their attention to textile systems where $E=B_X$ for some set $X$. We find this condition too restrictive for our aims and shall not enforce this restriction in this paper.   
\end{remark}



A \emph{square} in the textile system $T=(p,q :F \to E)$ is a four-sided object, whose edges are labeled using the edges of $E$  and vertices of $F$ as shown below. 
\begin{equation} \label{eq:square-labels} 
\begin{array}{l}
