\node at (-3.35,0.3) {\text{labeled by $f \in F^1$:}};
% \node at (-5,0) {$\l (T_f) = r(f) , \ \r ( T_f) = s(f) .$};
\node at (0.5,0.5) {$T_f$};
\node[inner sep=0.8pt] (00) at (0,0) {$.$};
\node[inner sep=0.8pt] (10) at (1,0) {$.$}
	edge[->] node[auto,black] {$q(f)$} (00);
\node[inner sep=0.8pt] (01) at (0,1) {$.$}
	edge[->] node[auto,black,swap] {$r(f)$} (00);
\node[inner sep=0.8pt] (11) at (1,1) {$.$}
	edge[->] node[auto,black,swap] {$p(f)$} (01)
	edge[->] node[auto,black] {$s(f)$} (10);

\end{tikzpicture}
\end{array}
\end{equation}

\noindent
Let $W_T = \{ T_f : f \in F^1 \}$ denote the collection of squares associated to $T$. 



\begin{remark} \label{rmk:square-convention}
Here our conventions for labeling the squares associated to a textile system are different from those in \cite{nasu} and \cite{johnson-madden}. 
This is the first visible sign of our categorical preferences mentioned in the introduction.
To be precise, we use the convention that $r(f)$ lies on the left of the square denoting the edge $f$ and $s(f)$ on the right so that (with concatenation of paths as composition of morphisms) $F^*$ is a category. To maintain consistency with Nasu's definition of LR textile systems (in particular, so that we measure the path lifting properties of $p$ with respect to $r$ and not $s$ in Definitions~\ref{dfn:resolving}) this choice forces us to place $p(f)$ on the top of the square $T_f$ and $q(f)$ on the bottom.
\end{remark}





\begin{definitions} \label{dfn:resolving}
A graph homomorphism $p: F \to E$ is said to have {\em (unique) $r$-path lifting} if, for all $v \in F^0,$ whenever $p(v) = r(e) \in E^0$ {for some $e\in E^1$}, there exists (a unique) $f \in F^1$ with $p(f) = e$ and $r(f) = v.$  Having unique $r$-path lifting is sometimes referred to being {\em left resolving} in the dynamics literature.
Similarly, $p$ has {\em (unique) $s$-path lifting} if, for all $v\in F^0$, whenever $p(v) = s(e) \in E^0$ for some $e\in E^1$, there exists (a unique) $f \in F^1$ with $p(f) = e$ and $s(f) = v$. Having unique $s$-path lifting is sometimes referred to as being {\em right resolving} in the dynamics literature 


A textile system $T= (p, q: F\to E)$ is called {\em LR} if $p$ has unique $r$-path lifting and $q$ has unique $s$-path lifting. 
\end{definitions}

