\begin{lemma}\label{lem:upl gives texsys}
Let $E$ and $F$ be directed graphs and $p,q:F\to E$ be graph morphisms. If $p$ has unique $r$- or unique $s$-path lifting, then $(p,q:F \to E)$ is a textile system for any $q$. Similarly, if $q$ has unique $r$- or unique $s$-path lifting, then $(p,q:F \to E)$ is a textile system for any $p$.
\end{lemma}

\begin{proof}
Suppose that $p$ has unique $r$-path lifting. We check that $f\mapsto ((r(f),p(f),s(f),q(f))$ is injective. Let $f , g \in F^1$ be such that $((r(f),p(f),s(f),q(f)) = ((r(g),p(g),s(g),q(g))$. Then $p(f) = p(g)$ and $r(f)=r(g)$, hence $f=g$. The other cases are proved \emph{mutatis mutandis}.
\end{proof}

\noindent
However, Example~\ref{ex:tex} shows that the converse of Lemma~\ref{lem:upl gives texsys} does not hold.



The following is adapted from \cite[\S 4]{Schmidt}.

\begin{definition}[Textile tiling]\label{dfn:textiletiling}
Let $T = ( p,q : F \to E)$ be a 
textile system, with the associated collection $W_T = \{ T_f : f \in F^1 \}$ of squares.  A (one-sided) \emph{textile %tiling
weaved by $T$} %$\textsf{X}_T^+$ 
is a covering of $\RR_{\ge 0}^2$ by translating copies of elements of $W_T$ with non-overlapping interiors such that the following conditions are satisfied:
\begin{enumerate}[label = (\roman*)]
\item every corner of each square lies in $\NN^2 \subset \RR_{\ge 0}^2 $; 
\item two squares are only allowed to touch along edges %of the same color 
in the following sense:
\begin{itemize}
\item[(T1)] $s(f) = r(f')$ whenever $T_f, T_{f'}$ are horizontally adjacent squares with $T_f$ to the left of $T_{f'}$, or 
\item[(T2)] $p(f) = q(f')$ if $T_f, T_{f'}'$ are vertically adjacent with $T_{f'}$ above $T_f$.
\end{itemize}
\end{enumerate}
We write $\textsf{X}_T^+ $ for the subshift of $W_T^{\N^2}$ (with the usual horizontal and vertical shift maps) consisting of all textiles weaved by $T$. %, with the usual horizontal and vertical shifts. 
That is, 
\begin{equation}
\label{eq:textiles}
\textsf{X}_T^+ = \{ x \in W_T^{\NN^2} : s(x_{v})= r(x_{v+\varepsilon_1}), p(x_w)=q(x_{w+\varepsilon_2}), \;\; \forall v,w \in \mathbb{N}^2\} .
\end{equation}
\end{definition}

\begin{remark} \label{rmk:textilesysissft}
It is straightforward to show that $\textsf{X}_{T}^+ \subset W_T^{\NN^2}$ is closed and shift invariant. %, under the usual horizontal and vertical shift maps. 
When the graph $F$ is finite, $\textsf{X}_T^+$ is a shift of finite type as it is of the form \eqref{eq:sftdef} for $Z=\{0,1\}^2$:
the restrictions of \eqref{eq:textiles} specify which $2\times 2$ blocks of tiles are allowed.

For simplicity we shall identify $W_T$ with $F^1$, that is, the alphabet of the shift space $\textsf{X}_T^+$ is $F^1$.
\end{remark}

We now proceed to give sufficient conditions for $\textsf{X}_T^+$ to be nonempty.






\begin{theorem}\label{lem:basic}
    [cf.~\cite[Proposition 4.6]{Yuxiang-Tang}  ]\label{thm:cantile}
Let $T = (p,q : F \to E)$ be a textile system in which 
$F$ is source-free, $q|_{F^0}$ is onto, 
and $q$ has $r$-path lifting. Then $\textsf X_T^+$ is nonempty. 
\end{theorem} 

