\noindent
The next result, which is a major foundation for the research in this paper, is a generalization of \cite[Theorem 3.8]{Yuxiang-Tang}.

\begin{theorem} \label{thm:PST}
Let $T=(p,q:F \to E)$ be a textile system with $p,q$  surjective. Let $(G_T,d)$  %$\Cc_T$
be the associated $2$-colored graph  and %corresponding collection of commuting squares 
 $\sim$ be the equivalence relation on $G_T^*$ from Definition \ref{dfn:2colgraph from T}. 
Then %$\Cc_T$ is a complete collection of commuting squares for $E_T$ 
$ \Lambda_T:= G_T^*/\sim$ is a 2-graph
if and only if $T$ is LR (that is, $p$ has unique $r$-path lifting and $q$ has unique $s$-path lifting).
\end{theorem}

\begin{proof}
First suppose that $p$ has unique $r$-path lifting and $q$ has unique $s$-path lifting. Let $\alpha\beta$ be a $2$-colored path in $G_T^2$. Suppose, without loss of generality, that %$c(\alpha\beta) = c_1c_2$. 
$d(\alpha) = \varepsilon_1$ %has color 1 
and $d(\beta) = \varepsilon_2$. %\beta$ has color 2.
By Definition~\ref{dfn:2colgraph from T} this implies $\alpha \in E^1$ and $\beta \in F^0$, and the fact that $\alpha \beta$ is a path in $G_T$ implies that $s_E(\alpha) = s_{G_T}(\alpha) =  r_{E_T}(\beta) = q(\beta)$. 

Since $q$ has unique $s$-path lifting, there is a unique $f\in F^1\beta$ with $q(f) = \alpha$. %Then $\phi_f$ satisfies $r(f) f \sim q(f)s(f) = \alpha \beta$ as required. 
By definition of $\sim$, we have $r(f) p(f) \sim \alpha \beta$; the uniqueness of $f$ guarantees that $\sim$ satisfies (KG2).
If %$c(\alpha\beta) = c_2c_1$ 
$\alpha$ has color 2 and $\beta$ has color 1 the same argument applies, using unique $r$-path lifting of $p$ in place of unique $s$-path lifting of $q$. %So $\Cc_T$ is complete.
Thus $\Lambda_T = G_T^*/\sim$ is a 2-graph.

Now suppose that %$\Cc_T$ is complete.
$G_T^*/\sim$ is a 2-graph, that is, $\sim$ satisfies (KG2).
We will show that $p$ has unique $r$-path lifting. The argument for $q$ having unique $s$-path lifting is similar. Fix $e \in E^1$, $w \in F^0$  with $r_E(e) = p(w)$, that is, with $r_{G_T}(e) = s_{G_T}(w)$. Then %r_{G_T}(e) = r_E(e)  s_{G_T}(w)$, so 
$we$ is a 2-colored composable path in $G_T$, %. As $\Cc_T$ is complete, there exists a unique $we \in \Cc_T$. By Lemma~\ref{lem:F1 bij to squares}, 
so by (KG2), there is a unique 2-colored path $e' v$ such that $d(e') = d(e)$, $d(v) = d(w)$,
%of degree $\varepsilon_1 + \varepsilon_2$ 
and $we \sim e'v$.  That is, 
there exists a unique $f \in F^1$ with $r_F(f) = w$, and $p(f) =e$. So $p$ has unique $r$-path lifting. 
\end{proof}

In other words, an LR textile system $T = (p, q: F\to E)$ yields a 2-graph $\Lambda_T$ by identifying $F^1$ with $\Lambda_T^{\varepsilon_1 + \varepsilon_2}.$  Conversely, given a 2-graph $\Lambda$, we can define a textile system $T_\Lambda = (p, q: F_\Lambda \to E_\Lambda)$ by 
\begin{equation} 
\label{eq:textile-from-2graph}
E_\Lambda = (\Lambda^0, \Lambda^{\varepsilon_1}, r, s), \quad F_\Lambda = (\Lambda^{\varepsilon_2}, \Lambda^{\varepsilon_1 + \varepsilon_2}, \ev_{0, \varepsilon_2}, \ev_{\varepsilon_1, \varepsilon_1 + \varepsilon_2}), \quad p = \ev_{\varepsilon_2, \varepsilon_1 + \varepsilon_2}, \quad q = \ev_{0, \varepsilon_1}. \end{equation}
The uniqueness guaranteed by the factorization property implies that $T_\Lambda$ is an LR textile system, and we have $\Lambda_{T_\Lambda} = \Lambda$ and $T_{\Lambda_T} = T$.


 \begin{remark}
     \label{rmk:Lambda-T-range-source}
     By Definition \ref{dfn:2colgraph from T}, if $\Lambda = G^*/\sim$ is a 2-graph with associated textile system $T = (p,q: F \to E)$, then $\Lambda^0 = E^0$ and $\Lambda^{ 1} = E^1 \sqcup F^0.$ For any $v \in F^0$,
     \[ s_\Lambda(v) = p(v), \quad r_\Lambda(v) = q(v), \]
     whereas $s_\Lambda(e) = s(e), r_\Lambda(e) = r(e)$ for $e \in E^1.$
 \end{remark}

Next, we show that the notion of \textit{essentiality} translates well between LR textile systems and rank-2 graphs. 
Recall (Definition \ref{def:2graph}) that a 2-graph $\Lambda$ is called \textit{essential} if $v \Lambda^m$ and $\Lambda^m v$ are nonempty for all $m \in \mathbb{N}^2$ and $ v \in \Lambda^0$. We now introduce an analogous notion of \textit{essential} textile systems as follows:

\begin{definition}[Essential textile system] \label{def: essential textile system}
A textile system $T= (p,q: F \to E)$ is said to be \textit{essential} if $F$ is essential (as in Definitions \ref{defs:directed}) and $p$ and $q$ are surjective maps.

\end{definition}
Note that if $T$ is an essential textile system, it follows immediately that $E$ is also essential. We extensively use this fact in the following proposition to prove that essential  LR textile systems are equivalent to essential rank-2 graphs. 

\begin{proposition}\label{essential equivalence}
An LR textile system $T= (p,q: F \to E)$ is essential if and only if its corresponding 2-graph $\Lambda = \Lambda_T$ is essential.
\end{proposition}

\begin{proof}
First assume that the textile system $T= (p,q: F \to E)$ is essential. Since $p,q,r_E,s_E, r_F, s_F$ are all surjective, we have that for each $z \in \Lambda^0 = E^0$,
\begin{equation*}
z \Lambda^{(1,0)} = r_E^{-1}(z) \ne \emptyset, \;\;\;\;
 \Lambda^{(1,0)} z = s_E^{-1}(z) \ne \emptyset,\;\;\;\;
\end{equation*}
\begin{equation*} %\label{eq: p and q are onto}
z \Lambda^{(0,1)}  = q^{-1}(z) \ne \emptyset,\;\;
 \Lambda^{(0,1)} z = p^{-1}(z) \ne \emptyset. 
 \end{equation*}
It follows that $z \Lambda^m$ and $\Lambda^m z$ are nonempty for all $m \in \mathbb{N}^2$. Thus, $\Lambda$ is essential when $T$ is essential.

Conversely, assume that $\Lambda$ is essential. 
Then, for each $z \in E^0$, we have 
\[ p^{-1}(z) = \Lambda^{(0,1)} z \ne \emptyset, \;\;\;\; q^{-1}(z) = z \Lambda^{(0,1)}  \ne \emptyset.\]
\[ r_E^{-1}(z) = z \Lambda^{(1,0)} \ne \emptyset, \;\;\;\; s_E^{-1}(z) = \Lambda^{(1,0)} z  \ne \emptyset.\]
Similarly, if $e \in E^1$ with $s_E(e) =z$, the fact that $z\Lambda^{(0,1)}\not= \emptyset$ implies that there exists $w \in F^0$ with $q(w) = z = s_E(e). $ As $T$ is LR, there exists (a unique) $f \in F^1$ with $q(f) = e$; that is, $q$ is surjective.   An analogous argument, using $r$-path lifting of $p$, will show that $p$ is surjective. 

 We have shown that $p$ and $q$ are surjective and $E$ is essential. Now, suppose $v \in F^0$ and $z = p(v)$. 
Since $E$ is essential, there exists $e \in E^1$ such that $r_E(e) = z = p(v)$.
By $r$-path lifting  of $p$, there exists $f \in F^1$ such that $p(f) = e$ and $r_F(f) = v$.
So, $r_F^{-1}(v) \ne \emptyset$ for any $v \in F^0$ and hence $r_F$ is surjective.
Similarly, suppose $v \in F^0$ and $z = q(v)$. 
Since $E$ is essential, there exists $e \in E^1$ such that $s_E(e) = z = q(v)$.
By $s$-path lifting  of $q$, there exists $f \in F^1$ such that $q(f) = e$ and $s_F(f) = v$.
So, $s_F^{-1}(v) \ne \emptyset$ for any $v \in F^0$ and hence $s_F$ is surjective.
Thus, $F$ is also essential.
\end{proof}


\subsection{The shift space associated to a rank two graph}

\begin{definitions}
Let $\Lambda$ be a $2$-graph. The \emph{one-sided infinite path space of $\Lambda$} is 
\[
\Lambda^\infty ~=~ \{ x : \Omega_2  \rightarrow \Lambda  : x \;
\mbox{is a degree preserving functor} \} .
\]



\noindent
For each $p \in \NN^2$, define $\sigma^p : \Lambda^\infty
\rightarrow \Lambda^\infty$ by $\sigma^p (x) (m,n) = x(m+p,n+p)$
for $x \in \Lambda^\infty$ and $(m,n) \in \Omega$. Note that
$\sigma^{p+q} = \sigma^p \circ \sigma^q$.

For $\lambda \in \Lambda$ define
\[
Z ( \lambda ) =  %\{ \lambda x \in \Lambda^\infty : s ( \lambda ) = x (0)  \} = 
\{ y  \in \Lambda^\infty: y ( 0 , d ( \lambda ) ) = \lambda \} .
\]
We endow $\Lambda^\infty$ with the topology generated by the basic open sets $\{ Z(\lambda): \lambda \in \Lambda\}$.  With this topology, the shift maps $\sigma^p$ are local homeomorphisms (cf.~\cite[Remarks 2.5]{kp}).
\end{definitions}



\noindent


Moreover, if we associate to $\Lambda$ the textile system $T_\Lambda$ as in Equation \eqref{eq:textile-from-2graph}, and construct the associated shift of finite type ${\sf X}_{T_\Lambda}^+$ as in Equation \eqref{eq:textiles}, we obtain the following result.

\begin{lemma}
Let $\Lambda$ be a 2-graph with $%\Lambda^{\varepsilon_1 + \varepsilon_2} := 
\Lambda^{\varepsilon_1} \sqcup \Lambda^{\varepsilon_2}$ finite. Then the shift space $( \Lambda^\infty , \sigma )$ is finite-type.  In particular, we can identify $\Lambda^\infty$ with ${\sf X}^+_{T_\Lambda}$.
\label{lem:same-path-spaces}
\end{lemma}

\begin{proof}
Recall that ${\sf X}_{T_\Lambda}^+$ consists of all tilings of $\RR^2_{\geq 0}$, using squares from $F_\Lambda^1 = \Lambda^{\varepsilon_1 + \varepsilon_2}$, which satisfy Definition \ref{dfn:textiletiling}.  In particular, thanks to the factorization property in $\Lambda$ and the fact that adjacent squares in a tiling must coincide on their common edges, whenever $m \leq n$ in $\N^2$ and $x \in {\sf X}_{T_\Lambda}^+$, the squares $\{ x_{m+v}\}_{0\leq v \leq n-m}$ identify a unique morphism in $\Lambda$ of degree $n-m$.  We denote this morphism by $x(m,n),$ for coherence with the definition of $\Lambda^\infty.$ 

Indeed, we can define $\psi: {\sf X}_{T_\Lambda}^+ \to \Lambda^\infty$ by $\psi(x)(m,n) = x(m,n)$ whenever $m \leq n$, and the
inverse map $\varphi: \Lambda^\infty \to {\sf X}_{T_\Lambda}^+$ is given by (for $n \in \N^2$)
\[ \varphi(y)_n = y(n, n + (1,1)). \]
It is straightforward to check that $\psi$ and $\varphi$ are shift commuting and take cylinder sets to cylinder sets.  That is, $\psi$ is a conjugacy, giving the desired identification of $\Lambda^\infty$ with ${\sf X}_{T_\Lambda}^+$ as dynamical systems.
\end{proof}



\begin{remarks}
    [Dynamics results concerning higher-rank graphs] 
    We briefly summarize here some results in the literature related to applications of higher-rank graphs to dynamics.
\begin{enumerate}[leftmargin=19pt,label=(\roman*)]
\item In \cite{Skalski-Zacharias} the authors compute the topological entropy of the shift associated to a higher-rank graph. The factorization property ensures that it is zero. They also compute the entropy induced in the associated $C^*$-algebra (which is also zero).
\item In \cite{KumjianPask3} the authors study the dynamical system arising from a higher-rank graph. They show that the action of shift map on the path space of a  higher-rank graph is an expansive action. Additionally they show that if the higher-rank graph is primitive, then the shift map is topologically mixing. The existence of the Parry measure described in \cite[Proposition 4.2]{KumjianPask3} led to the work by others on the KMS states on higher-rank graphs (cf.~\cite{aHLRS,aHLRS14,FGKP,FGLP}).
\item In \cite{pask-raeburn-weaver} the authors use a set of basic data coming from algebraic information (inspired by the work of Schmidt) to create a set of 2-dimensional tiles. Using a standard overlap condition from dynamics they construct a $2$-graph from such tiles and show that, in many situations, the associated $C^*$-algebras are purely infinite and simple. Moreover, their shift spaces tally with the one coming from the data applied to the Schmidt examples (see \cite{Schmidt}). In \cite{Lewin-Pask} the authors verify that the entropy of these shifts are zero using different techniques to \cite{Skalski-Zacharias}. 
\item In \cite{carlsen-rout-kgraph,brownlowe-carlsen-whittaker,CEOR} the authors consider orbit equivalence of rank one and higher-rank dynamical systems.
\end{enumerate}

\end{remarks}




\section{Insplitting for textile systems and rank-2 graphs} \label{sec:2ginsplit}

In the literature, one can find both a definition for insplitting a textile system \cite{johnson-madden} and for insplitting a higher-rank graph \cite{EFGGGP}.  Unfortunately, when the higher-rank graph is the 2-graph associated to an LR textile system as in Theorem \ref{thm:PST}, these definitions do not agree.  We briefly review their definitions before moving on to the main results of this paper in Sections 
\ref{sec:ghinsp-JM} and \ref{sec:JM-ghinsp} below, which address the 
problem of reconciling the two notions of insplitting.

\subsection{Insplitting of textile systems} 
\label{sec:jm-insplits}

%\subsection{Insplitting}

\begin{definition}\cite[Definition 2.4.7]{lind-marcus}
    For a directed graph $F$, an {\em insplitting partition} of $F$ is a partition of $r^{-1}(v)\subseteq F^1$, for each $v \in F^0$, into $m(v)$ (nonempty) subsets $\mathcal F_v^1, \ldots, \mathcal F_v^{m(v)}$, for some $m(v) \geq 1$.  The {\em insplit graph} $F_I$ has \[
F_I^0 = \{ v^i : v \in F^0 , 1 \le i \le m(v) \} \text{ and }
F_I^1 =\{ f^j : 1 \leq j \leq m(s(f)) , f \in F^1 \} = \bigcup_{f\in F^1} \bigcup_{i=1}^{m(s(f))} \{ f^i \}  ,
\]
with $s(f^j) = s(f)^j$ and $r(f^j) = r(f)^k$ if $f \in \mathcal F_{r(f)}^k$.
\label{def:graph insplitting}
\end{definition}


\vspace{3mm}

In \cite[\S 3]{johnson-madden}, Johnson and Madden give the definition of  insplitting for textile systems with $E = B_X$ being a one-vertex graph. %they consider (in particular, with $E = B_X$ being a one-vertex graph). 
Here we have adapted their definition to textile systems with %general graph 
no restrictions on $E$.



\begin{definition}[Textile insplitting] \label{dfn:textile-insplit}
Let $T = (p,q : F \to E )$ be a textile system.  
An {\em insplit textile system} is $T_I = (p_I, q_I: F_I \to E_I)$, where $E_I = E$ and $F_I$ is an insplit of $F$ as in Definition \ref{def:graph insplitting}. 

We have $p_I(f^j) = p(f), p_I(v^i) = p(v)$, and $q_I$ is similarly induced from $q$. 

We sometimes call $T_I$ a {\em Johnson--Madden insplit} of $T$, to distinguish from the 2-graph insplits of Definition \ref{def:2-graph-insplit}.
\end{definition}


\smallskip
\noindent
It is straightforward to check that $p_I, q_I$ are graph homomorphisms, and if $T$ is a textile system, then so is $T_I$. 


\begin{remarks}[The effect of insplitting on squares] \label{rmk:upisOK} \hfill
\begin{enumerate}[leftmargin=0.7cm, label=(\roman*)]

\item Let $T=(p,q:F \to E)$ be a textile system. 
Suppose square $T_f$ is below square $T_g$, that is $p(f)=q(g)$.  Then this connection persists in any textile insplit $T_I = ( p_I , q_I : F_I \to E )$ of $T$, that is, $p_I ( f^j) = p(f) = q(g) = q_I (g^k)$ regardless of the values of $j,k$.

\item Let $T=(p,q:F \to E)$ be a textile system. Fix a partition $\{ \mathcal{F}_v^i : 1 \le i \le m(v) , v \in F^0 \}$ to give an insplitting $T_I$. Suppose $f,g \in F^1$ are such that $s(f)=r(g)$, so squares $T_f$ and $T_g$ are adjacent, and suppose $g \in \mathcal{F}_{r(g)}^\ell$. In order that $f^j , g^k \in F_I^1$ be  consecutive edges in $T_I$ we must have
\[
s(f)^j= s( f^j )\stackrel{!}{=} r( g^k )= r(g)^\ell ;
\]
that is $j=\ell$.
\end{enumerate}
\end{remarks}


