\begin{theorem}[Insplitting always removes LR]
\label{thm:JM-insplit-not-LR}
Let $T = ( p,q : F \to E )$ be a textile system which is LR. Fix a partition $\{ \mathcal{F}_v^i :  1 \le i \le m(v), v \in F^0 \}$ with $m(v) \ge2$ for some $v$. Then the insplit textile system $T_I$ is not LR.
\end{theorem}

\begin{proof}
Let $v$ be a vertex with $m(v) \ge 2$. Let $1 \le i < j \le m(v)$, and fix an edge $f \in \mathcal{F}^k$ with source $v$. Consider the edges $f^i \neq f^j$ in $F_I$. By definition $r_I ( f^i) = r_I ( f^j ) = r(f)^k$. But $p_I( f^i )= p(f)= p_I( f^j )$ and 
\[
p_I ( r_I ( f^i ) ) = p_I ( r(f)^k ) = r(f).  %=  p_I ( r(f)^k ) = p_I ( r_I ( f^j ) ) .
\]
Hence $p_I$ is not left-resolving.
\end{proof}


Recall from Definition~\ref{dfn:textiletiling} a textile system $T = ( p,q : F \to E )$ gives rise to a textile tiling $\textsf{X}_T^+$. By Remark~\ref{rmk:textilesysissft} we may consider this as a one-sided 2-dimensional shift of finite type with alphabet $\mathcal{A}=F^1$. The following result was stated in \cite[Lemma 3.4]{johnson-madden} for textile systems with $E = B_X$; for completeness, we include a proof of the general result here.

\begin{theorem}[Textile insplitting induces conjugacy] \label{thm:insplit-conjugacy}
Let $T= (p,q : F \to E )$ be a textile system. Fix a partition $\{ \mathcal{F}_v^i : 1 \le i \le m(v), v \in F^0 \}$ to form an insplitting $T_I$. Then $\textsf{X}_T^+$ is conjugate to $\textsf{X}_{T_I}^+$.
\end{theorem}

\begin{proof}
Define a $0$-block map $\Phi : B_{0}( \textsf{X}_{T_{I}}^+ ) \to B_0 ( \textsf{X}_T^+ )$ by $\Phi ( f^j)=f$
for $f \in F^1$, $1 \le j \le  m(s(f))$. Let $\phi : \textsf{X}_{T_I}^+ \to \textsf{X}_T^+$ be the induced map. %(with $0$ memory and anticipation). 
To define the inverse map $\psi: \textsf{X}_T^+ \to \textsf{X}_{T_I}^+$, we use an $\varepsilon_1$ block map.
That is, we define $\Psi: B_{\varepsilon_1}(X_T^+) \to B_0(X_{T_I}^+)$ by 
\[ \Psi \begin{pmatrix}
   f & g
\end{pmatrix} = f^j \text{ where }g \in \mathcal F^j_{s(f)}.\]


To see  that $\psi \circ \phi = \text{id}$, let $x \in \textsf{X}^+_{T_I}$.  Then for each $m \in \NN^2, \ x_m = f^{j_m}$ for some $f\in F^1, 1 \leq j_m \leq m(s(f))$. As $s(f^{j_m}) = s(f)^{j_m}$, we must have $r(x_{m+\varepsilon_1}) = s(f)^{j_m},$ that is, 
\[ \Phi(x_{m+\varepsilon_1}) \in \mathcal F^{j_m}_{s(f)} \, \text{ for all }m.\]
Consequently, for all $m$, $ \Psi(\Phi(x_m) \Phi(x_{m +\varepsilon_1})) = \Phi(x_m)^{j_m} = x_m,$ i.e.,~$\psi \circ \phi = \text{id}.$

To see that $\phi \circ \psi = \text{id},$ let $y \in \textsf{X}_T^+.$  For each $m \in \N^2,$ we have $y_{m+\varepsilon_1} \in \mathcal F^{j_m}_{s(y_m)}$ for a unique $j_m$.  We then have  
\[ (\psi(y))_m = y_m^{j_m}\]
and so $(\phi(\psi(y)))_m = y_m;$ that is, $\phi \circ \psi = \text{id}.$  As both $\phi, \psi$ are block maps, Lemma \ref{lem:block-map-cts} and Definition \ref{def:conjugacy} imply that $\phi, \psi$ are conjugacies, as claimed. 

\end{proof}



