\noindent
An insplitting partition of a 2-graph gives rise to a new 2-graph (the {\em insplit 2-graph $\Lambda_I$ of $\Lambda$}), as follows.
Given an insplitting partition $\mathcal G$ of $G$, 
we define a $2$-colored graph $G_I = \big( (G^0_I, G^1_I, r_I, s_I),d_I\big)$, 
where
\begin{align*}
G_I^0 &= \{ v^1, v^2, \ldots, v^{m(v)}: v \in G^0\} 
\text{ and } \,
%\Lambda_I^{\varepsilon_1} \sqcup \Lambda_I^{\varepsilon_2} 
G^1_I= \bigcup_{f \in %\Lambda^{\varepsilon_1} \sqcup \Lambda^{\varepsilon_2} 
G^1  }    \{f^1, f^2, \ldots,  f^{m(s(f))} \}
\end{align*}
with $d_I(f^i)= d(f)$ for all $1 \le i \le m(v)$. 


\noindent
The range and source maps in the directed graph $G_I$ are defined as follows:
\begin{align*}
r_I ( f^i ) & =  r ( f )^j \text{ where } f \in \mathcal G_{r(f)}^{j}  , \label{eq:rdef} \\
s_I (f^i) & = s(f)^i .   %\label{eq:sdef} 
\end{align*}

The equivalence relation in 
 $G_I$ is given by $f^i g^k \sim_I  a^j b^k$ if and only if $(g \in \mathcal G_{s(f)}^i, b \in \mathcal G_{s(a)}^j)$, and $ab \sim  fg \in \Lambda.$ (The fact that the two paths in a commuting square are required to have the same source forces $g, b$ to have the same superscript.)


\end{definitions}

\begin{remark}
    Requiring that the  partition $\mathcal G$ satisfies the pairing condition is equivalent to specifying that the edges $\lambda(0, \varepsilon_1)$ and $\lambda(0, \varepsilon_2)$ lie in the same partition set $\mathcal G^j_{r(\lambda)}$ for each $\lambda \in \Lambda^{\varepsilon_1 + \varepsilon_2}$.
\end{remark}


The fact that $\Lambda_I := G_I^*/\sim_I$ is indeed a 2-graph is established in the following Theorem.

\begin{theorem}[$2$-graph insplitting produces $2$-graph] \label{thm:inplitcomplete}
Let $\Lambda$ be an essential row-finite $2$-graph with associated $2$-colored graph $(G,d)$. Let $\mathcal G$ be  an insplitting partition of $(G,d)$. % satisfying the pairing condition.
Then the associated quotient $G_I^*/\sim_I$ is a 2-graph $\Lambda_I$. \end{theorem}

\begin{proof}
Recall from Remark \ref{rmk:2-skel-2colograph} that we denote by $\sim_I$ the equivalence relation satisfying (KG0) and (KG1) which is generated by the set of commuting squares specified in Definitions \ref{def:2-graph-insplit}. To see that  $G_I^*/\sim_I$ is a 2-graph, 
it suffices to show that every 2-colored path $f^i g^k$ in $G_I$ is equivalent to a unique $2$-colored path $a^j b^k$.  If $f^i g^k \in G_I^2$, then $g \in \mathcal G_{s(f)}^i$; in particular $s(f) =  r(g)$, so $fg \in G^2$.  Since $\Lambda$ is a 2-graph, there is a unique path $ab \in G^2$ with $d(a) = d(g), d(b) = d(f)$ and $ab \sim fg$. In particular, $s(b) = s(g) $ and $r(b) = s(a)$.  There is a unique $j$ such that $b \in \mathcal G_{s(a)}^j$; therefore, $a^j b^k$ is the unique 2-colored path with $d(a^j) = d(g^k)$ and $a^j b^k \sim f^i g^k$.

\end{proof}



We prove in Appendix \ref{sec:$C^*$} that Definitions \ref{def:2-graph-insplit}  yield the same $C^*$-algebraic properties as the original definition of 2-graph insplitting from \cite{EFGGGP}.



\begin{remark}
    \label{rmk:squares-in-insplit}
    Thanks to the definition of the equivalence relation $\sim_I$ given at the end of Definitions \ref{def:2-graph-insplit}, every commuting square in $\Lambda_I$ arises from a (unique) commuting square in $\Lambda$.  In fact, each commuting square $\lambda = a b \sim f g$ in $\Lambda$ yields $m(s(g)) = m(s_\Lambda(\lambda))$ commuting-square ``children'' in $\Lambda_I$.
\end{remark}

