\subsection{Which textile insplits yield 2-graph insplits?} \label{Sami sec}

The following Theorem explains how to identify when a Johnson--Madden insplitting of an LR textile system could alternatively be obtained from  a 2-graph insplitting. In other words, while we know from Theorem \ref{thm:JM-insplit-not-LR} that Johnson--Madden insplitting never yields an LR textile system,  Theorem \ref{thm:lr-insplit=2g-insplit} identifies which Johnson--Madden insplittings of an LR textile system can be combined with a directed-graph insplitting of the base graph $E$ to yield an LR textile system. 
% (namely, that associated with the 2-graph insplitting of the original LR system). 
Thus, the insplittings described in the theorem below take an LR textile system to an LR textile system.


\begin{theorem}\label{thm:lr-insplit=2g-insplit}
    Let $T = (p,q: F \to  E)$ be an LR textile system  in which $p$ is surjective and $F$ is source-free, and let $\La = \La_T$ be the corresponding 2-graph. Suppose for each $v \in F^0$ we have a partition $\mathcal F_v = \{ \mc{F}_v^1, \dots, \mc{F}_v^{m(v)}\}$ of $vF^1$, and let $\mc{F} = \{\mc{F}_v\}_{v\in F^0}$. Suppose that $\mc{F}$ satisfies 
    \begin{enumerate}
        \item\label{lr-is-hyp-1} If $v, w \in F^0$ and $p (\mathcal F^i_v) \cap p(\mathcal F^j_w) \not= \emptyset$, then $p(\mathcal F^i_v) = p(\mathcal F^j_w);$ and
        \item\label{lr-is-hyp-2} For all $v \in F^0$, there exists $w \in F^0$ and $1 \leq j \leq m(w)$ such that $q(v F^1) \subseteq p(\mathcal F^j_w)$.
    \end{enumerate}
    Let $T_{JM}= (p_{JM}, q_{JM}:F_{JM} \to E_{JM})$ be the result of performing Johnson--Madden insplitting with respect to the partition $\mathcal F$. Then there is a directed graph insplit $\widetilde E$ of $E_{JM}$, together with graph homomorphisms $\wt p, \wt q: F_{JM} \to \widetilde E$, so that the textile system $\widetilde T := (\wt{p}, \wt{q}: F_{JM}\to \widetilde E)$ is LR. 

    Moreover, $\widetilde T$ can be identified as the textile system $T_{\La_I}$ of %  alt: the
    a 
    2-graph $\La_I$ which arises from 2-graph insplitting on $\La$ 

    using a partition $\mathcal G$ (described in Proposition  \ref{lr-insplit-3} below) of $\Lambda^{1}$ which arises from $\mathcal F.$
\end{theorem}

Theorem \ref{thm:lr-insplit=2g-insplit} will be proved in a series of propositions.





\begin{proposition}\label{prop:lr-ptn}
    Let $T=(p,q:F\to E)$ be an LR textile system, and for each $v \in F^0$, $\mc{F}_v = \{ \mc{F}_v^i : i=1, \dots, m(v)\}$ be a partition of $vF^1$. Then:
    \begin{enumerate}
        \item\label{lr-ptn-1} if $v \in F^0$ and $p(\mc{F}_v^i) \cap p(\mc{F}_v^j) \neq \emptyset$, then $i=j$, and
        \item\label{lr-ptn-2} if $v, w \in F^0$ and $p(v) = p(w)$, then for every $i \in \{1, \dots, m(v)\}$, there exists $j \in \{1, \dots, m(w)\}$ such that $p(\mc{F}_v^i) \cap p(\mc{F}_w^j) \neq \emptyset$.
    \end{enumerate}
\end{proposition}
\begin{proof}
    (\ref{lr-ptn-1}): Let $e \in p(\mc{F}_v^i) \cap p(\mc{F}_v^j)$. Then there are $\lambda \in \mc{F}_v^i$ and $\mu \in \mc{F}_v^j$ such that $p(\la) = p(\mu) = e$. %Since $\mc{F}_v^i \sse vF^1$, $r(\la) = v$, and similarly $r(\mu)=v$. 
    Because $p$ is a graph homomorphism, $p(r(\lambda)) = r(p(\lambda)) = r(e) = p(r(\mu))$, so by unique $r$-path lifting of $p$ (since $T$ is LR), $\la = \mu$. Thus, $\mc{F}_v^i \cap \mc{F}_v^j \not= \emptyset$. Since $\{\mc{F}_v^k : k=1, \dots, m(v)\}$ is a partition of $vF^1$, this implies $i=j$.  

    (\ref{lr-ptn-2}): Let $e \in p(\mc{F}_v^i)$. Then $r(e) = p(v) = p(w)$, %and by assumption, $p(v) = p(w)$, 
    so by unique $r$-path lifting for $p$, there exists a unique $\eta \in F^1$ such that $r(\eta) = w$ and $p(\eta) = e$. %Since $\eta \in wF^1$, it must be in 
    We have $\eta \in \mc{F}_w^j$ for some $j \in \{1, \dots, m(w)\}$. Hence, $e \in p(\mc{F}_v^i) \cap p(\mc{F}_w^j)$.
\end{proof}

\begin{proposition}\label{prop:lr-insplit-1'}
    Let $T=(p,q:F\to E)$ be an LR textile system with a partition $\mc{F}$ of $F^1$ satisfying condition (\ref{lr-is-hyp-1}) of Theorem \ref{thm:lr-insplit=2g-insplit}. If $v, w \in F^0$ with $p(v) = p(w)$, then $m(v) = m(w)$.
\end{proposition}


\begin{proof}
    By Proposition \ref{prop:lr-ptn}(\ref{lr-ptn-2}) and condition (\ref{lr-is-hyp-1}) of Theorem \ref{thm:lr-insplit=2g-insplit}, if $p(v) = p(w)$, then for each $i \in \{1, \dots, m(v)\}$, there exists $j_i \in \{1, \dots, m(w)\}$ such that $p(\mc{F}_v^i) = p(\mc{F}_w^{j_i})$. If $i, k \in \{1, \dots, m(v)\}$ and $J:= j_i = j_k$, then $p(\mc{F}_v^i) = p(\mc{F}_w^J) = p(\mc{F}_v^k)$, so $i = k$, hence $i \mapsto j_i$ is injective. The map is surjective because for each $k \in \{1, \dots, m(w)\}$, there is $i_k \in \{1, \dots, m(v)\}$ such that $p(\mc{F}_w^k) = p(\mc{F}_v^{i_k})$ (again, by combining Proposition \ref{prop:lr-ptn}(\ref{lr-ptn-2}) and condition (\ref{lr-is-hyp-1}) of Theorem \ref{thm:lr-insplit=2g-insplit}) so $k = j_{i_k}$.
    Hence, $m(v) = m(w)$.
\end{proof}

\begin{remark}
We can thus assume without loss of generality that for each $z \in E^0$, for all $v, w \in p\inv(z)$ and $i=1,\dots,m(v)$, $p(\mc{F}_v^i) = p(\mc{F}_w^i)$, and we are justified in setting $m(z) = m(v)$.
\label{rmk:same-index}
\end{remark}



\begin{proposition}\label{lr-insplit-2} 
    Under the assumptions of Theorem \ref{thm:lr-insplit=2g-insplit}, the collection $$\mc{E}_z =\{ \mathcal E^{i}_z := p(\mathcal F^i_v) \mid p(v)=z, i=1, \dots, m(z) \}$$ 
    is a partition of $zE^1$ for each $z \in E^0$. If $\widetilde E$ is the insplit of $E$ with respect to this partition,
    %the partition $\mc{E} = \{\mc{E}_z^{[v_i]} : z \in E^0, [v^i] \in \mc{L}_z\},$ 
    then the maps $\wt p, \wt q : F_{JM} \to \widetilde E$ defined, 
    % for $v \in F^0$ and $\la \in F^1 v$, by
