Thus, we can perform 2-graph insplitting on $\Lambda_T$ with respect to the partition $\mathcal G$.  Recall from Definitions \ref{dfn:2colgraph from T} and \ref{def:2-graph-insplit}  that the resulting 2-graph $\Lambda_I$ has $\Lambda_I^0 = \{ z^i: z \in E^0, 1 \leq i \leq m(z)\}$ and 
\[ \Lambda_I^{\varepsilon_1} = \{ e^i: e \in E^1, 1 \leq i \leq m(s(e))\}, \quad \Lambda_I^{\varepsilon_2} = \{ v^i: v \in F^0, 1 \leq i \leq m(p(v))\}, \]
with $s_I(e^i) = s(e)^i, s_I(v^i) = p(v)^i, r_I(e^i) = r(e)^j$ if $e \in \mathcal E^j_z$, and $r_I(v^i) = q(v)^k$ if $v \in r_F(q^{-1}(\mathcal E^k_z)),$ that is, if $q(vF^1) \subseteq p(\mathcal F^k_u)$ for some $u$ with $p(u) = q(v) = z.$  We have 
\[ v^j e^i \sim_I f^\ell w^k \iff i = k, e \in \mathcal E^j_{r(e)}, w \in r_F(q^{-1}(\mathcal E^\ell_{s(f)})), \text{ and } ve \sim f w \in \Lambda_T. \]
That is,  $v^j e^i \sim_I f^\ell w^i$ if and only if
\begin{itemize} 
\item there is $\lambda \in F^1$ with $r_F(\lambda) = v, s_F(\lambda) = w, p(\lambda) = e, q(\lambda) = f;$ 
\item we have $q(wF^1) \subseteq p(\mathcal F^\ell_{u})$ for some $u \in F^0$ with $p(u) = q(w)$;
\item and  $\lambda \in \mathcal F^j_v$ (so that $e = p(\lambda) \in \mathcal E^j_{r(e)} = \mc{E}^j_{p(v)}$).
\end{itemize}
In other words, each $\lambda = ve \sim_\Lambda f w \in F^1$ yields commuting squares $\{ \lambda^i:= v^j e^i \sim_I f^\ell w^i : i=1, \dots, m(s(e)) \}$  in $\Lambda_I$ (note that $m(s(e)) = m(p(w))$); the indices $j, \ell$ are determined by $\lambda$ and are the same for each $\lambda^i$.



\begin{theorem}\label{lr-insplit-4}
Under the assumptions of Theorem \ref{thm:lr-insplit=2g-insplit} above, let $\La_I$ be the 2-graph insplitting (see ~Definitions \ref{def:2-graph-insplit}) of $\La_T$ with respect to the partition {$ \{\mc{G}_z^i: z\in \Lambda^0, i= 1, \ldots, m(z)\}$} from Proposition \ref{lr-insplit-3}, and  let $T_I = (p_I, q_I: F_I \to E_I)$ be the textile system built from $\La_I$ as in  \eqref{eq:textile-from-2graph}. Then $T_I \cong \widetilde T = (\wt{p}, \wt{q}: \widetilde{F} := F_{JM} \to \widetilde{E})$, the textile system given in Proposition \ref{lr-insplit-2}. \end{theorem}
\begin{proof}
By  \eqref{eq:textile-from-2graph} and Remark \ref{rmk:same-index}, the  LR textile system $T_{I} = (p_I, q_I: F_{I} \to E_{I})$ has 
\[ F_I^0 = \{ v^i: v \in F^0, 1 \leq i \leq m (p(v))\}, \ F_I^1 = \{ \lambda^i: \lambda \in F^1, 1 \leq i \leq m(s(p(\lambda)))\}, \]
$s_{F_1}(\lambda^i) = s_F(\lambda)^i$, and $ \ r_{F_I}(\lambda^i) = r_F(\lambda)^j \text{ if } \lambda \in \mathcal F^j_v.$
When we compare $F_I$ with the construction of $F_{JM}$ as in Definition \ref{dfn:textile-insplit}, the fact that $m(p(v)) = m(v)$ for all $v \in F^0$ implies that $F_I = F_{JM}.$ Similarly, we observe that the definitions of $\widetilde E, \wt p, \wt q$ in Proposition \ref{lr-insplit-2} exactly match the definitions of $E_I, p_I, q_I$ from Equation \eqref{eq:textile-from-2graph}. % More explanation needed here re q.
The fact that $\widetilde E = E_I$ follows from the fact that the insplitting partition $\mathcal E$ used to create $\widetilde E$ satisfies $\mathcal E^i_z = \Lambda^{\varepsilon_1}_I \cap \mathcal G^i_z ,$ and the source and range maps in $\widetilde E$ coincide with the 2-graph insplitting source and range maps. Moreover,  $\wt p = p_I$ and $\wt q = q_I$, since for any $\lambda^i = r_F(\lambda)^k p(\lambda)^i \sim_I q(\lambda)^\ell  s_F(\lambda)^i \in F_I^1$ and any $v^i \in F_I^0 = \Lambda_I^{\varepsilon_2},$

\[ p_I(\lambda^i) = p(\lambda)^i, \quad p_I(v^i) = s_{\Lambda_I}(v^i) = p(v)^i, \quad q_I(v^i) = r_{\Lambda_I}(v^i) = q(v)^k \]
if $v \in \mc{G}^k_{q(v)}$, or equivalently, $v \in r_F(q^{-1}(\mathcal E^k_{q(v)}).$  That is, $q_I(v^i) = \widetilde q(v^i).$
Finally, 
to compare $q_I(\lambda^i)$ and $\wt q(\lambda^i)$, recall that  $\lambda^i = r_F(\lambda)^k p(\lambda)^i \sim_I q(\lambda)^\ell  s_F(\lambda)^i \in F_I^1$ where $p(\lambda) \in \mc E^k_{p(r_F(\lambda)))}$ and $s_F(\lambda) \in \mc G^\ell_{q(s_F(\lambda))}$. By construction, then, $q_I(\lambda^i) = q(\lambda)^\ell$.  On the other hand, $s_F(\lambda) \in \mc G^\ell_{q(s_F(\lambda))}$ implies that $s_F(\lambda) \in r_F(q^{-1}(\mc E^\ell_z))$, so (thanks to Lemma \ref{lem:p-and-q}) $q(s_F(\lambda) F^1) \subseteq p(\mathcal F^\ell_w)$ for some $w \in F^0$.
Consequently, $\wt q(\lambda^i) = q(\lambda)^\ell = q_I(\lambda^i)$ as desired. 

   In other words, $T_I = \widetilde T;$ since $T_I$ is LR, being a textile system arising from a 2-graph, it follows that $\widetilde T$ is also LR.
\end{proof}
The above Theorem completes the proof of Theorem \ref{thm:lr-insplit=2g-insplit}.






