where $\lambda \in F^1$, $v \in F^0$, $s(\lambda) = v$ and $j$ %is the unique index such that 
satisfies $q(vF^1) \subseteq \E^j_{q(v)}$. Then 
\begin{enumerate}
\item The maps $\tilde{p}, \tilde{q}:  \widetilde{F}  \to  \widetilde{E}$ are %well-defined 
graph homomorphisms and $\widetilde{T} := (\tilde{p}, \tilde{q} : \wt{F} \to \wt{E} )$ is an LR textile system.
\item The collection $\{ \mathcal{G}^i_z := \E^i_z \sqcup r(q^{-1}(\E_z^i)) : z \in E^0, 1\le i \le m(z) \}$ satisfies the pairing condition. 
\item The 2-graph associated to $\widetilde{T}$ (denoted by $\widetilde{\Lambda}$) is identical to the 2-graph ${\Lambda}_I$ resulting from insplitting $\Lambda$ using the partition % $\{ \mathcal G^j_z: z \in E^0, 1 \leq j \leq m(z)\}$. 
$\{ \G^j_z\}_{j,z}.$ 
\end{enumerate}

\end{theorem}

\begin{proof}
