\begin{theorem}[Theorem \ref{Thm: Main result III} $\longrightarrow$ Theorem \ref{thm:Priyanga}]
Let $T= (p,q: F \to E)$ be an LR textile system with associated 2-graph $\Lambda$. Further, assume that $p$ is surjective and $F$ is source free.
Let $\{ \E^i_z: z \in E^0, 1 \le i \le m(z)\}$ be a partition of $E^1$ as in Theorem \ref{Thm: Main result III}, so that for each $u \in F^0$, there exist $ z = q(u) \in E^0$ and a unique $j \in \{ 1, 2, \ldots, m(z)\}$ such that $q(uF^1) \subseteq \E^j_z$. 

Define partitions of $F^1$ and $\Lambda^{1}$ as in Theorem \ref{Thm: Main result III}, namely: For each  $v \in F^0$ and $ z \in E^0$, let
\begin{equation}
\mathcal{F}^i_v := vF^1 \cap p^{-1}(\E^i_{p(v)}), \;\;\; \text{ for } 1\le i\le m(p(v)),
\label{eq:defne F from E}
\end{equation}
\begin{equation} \label{eq: defne G from E}
\mathcal{G}^i_z := \E^i_z \sqcup r_F(q^{-1}(\E_z^i)), \;\;\; \text{ for } 1\le i\le m(z).
\end{equation}

\noindent Then, 
\begin{enumerate}
\item The partition of $E^1$ constructed in Theorem \ref{thm:Priyanga} from the 2-graph partition \eqref{eq: defne G from E} agrees with the original partition $\{\mathcal{E}^i_z \}$, that is 
\[ \mathcal{E}^i_z = \mathcal{G}^i_z \cap z E^1. \]
\item The partition of $F^1$ constructed in Theorem \ref{thm:Priyanga} from $\{\mathcal{G}^i_z\}_{i,z}$ agrees with the partition of Equation \eqref{eq:defne F from E}, that is
\[ \mathcal{F}^i_v = \{ \lambda \in vF^1  :  p(\lambda) \in \mathcal{G}^i_{ p(v)} \}. \]
\item The constructions of the textile system $\wt{T} = (\tilde{p}, \tilde{q}: \wt{F}\to \wt{E})$ in Theorems \ref{thm:Priyanga} and  \ref{Thm: Main result III} coincide.
\end{enumerate}
\end{theorem}

\begin{proof}
Following the fact that $\mathcal{G}^i_z \cap z E^1 = \bigg(\E^i_z \sqcup r(q^{-1}(\E_z^i)) \bigg) \cap z E^1 = \E^i_z \cap z E^1 = \mathcal{E}^i_z$, we obtain (1).
For (2), we have $f \in \F^i_v$ if and only if $f \in \{ \lambda \in vF^1 :  p(\lambda) \in \E^i_{p(v)}\}$ which is equivalent to $f \in \{ \lambda \in vF^1 :  p(\lambda) \in \G^i_{p(v)}\}$ as $p(f)\in E^1$ but $p(f) \notin r_F(q^{-1}(\E_z^i))$.

For (3), it is sufficient to show that the maps $\tilde{q}$ defined in Theorem \ref{thm:Priyanga} and Theorem \ref{Thm: Main result III} are the same. To this end, we note that for $v \in F^0$,
\begin{eqnarray*}
v \in \mathcal{G}^m_{q(v)} & \iff & v \in r_F(q^{-1}(\E^m_{q(v)}))  \iff \exists \lambda \in vF^1 \text{ such that } q(\la) \in \E^m_{q(v)} \\
& \iff & q(vF^1) \subseteq \mathcal{E}^m_{q(v)},
\end{eqnarray*}
where the last equivalence follows from the hypothesis.
%Thus, the graph homomorphisms $\tilde{q}$ defined in \textcolor{red}{Main result III and Main result I} coincide, namely \[ \tilde{q}(v^i) = q(v)^j, \text{ and } \ \tilde{q}(\lambda^i) = q(\lambda)^j,\]
%where  %$v \in F^0$, $\lambda \in F^1$, $s(\lambda) = v$, $ 1 \le i \le m(v)$ and 
%$v \in \mathcal{G}^j_{q(v)}$ or equivalently, $q(vF^1) \subseteq \mathcal{E}^j_{q(v)}$.
%Hence, the resulting textile systems are the same.
So, the definition of $\tilde{q}$ in Theorem \ref{thm:Priyanga} and Theorem \ref{Thm: Main result III} coincide, and hence the textile systems are the same.
% \end{enumerate}
 \end{proof}




