\subsection{Matrix shifts}

\begin{definition}
\label{def:shift-space}
Fix a (finite) set $\mathcal A$, which we will call an {\em alphabet}.
A {\em one-sided, 2-dimensional shift space} over $\mathcal A$ is a subset $X$ of $\mathcal A^{\N^2}$ which is closed under the horizontal and vertical shift maps $\sigma^{\varepsilon_1}, \sigma^{\varepsilon_2}:\mathcal A^{\N^2} \to \mathcal A^{\N^2},$ given by 
    \[ \sigma^{\varepsilon_1}(x)_{i,j} = x_{i+1, j} \quad \text{ and } \quad \sigma^{\varepsilon_2}(x)_{i,j} = x_{i, j+1}.\]
    \end{definition}

This paper will focus on one-sided, 2-dimensional shifts of {\em finite type} or SFTs.  These are more commonly described in terms of a finite set of forbidden patterns; however, the following definition can be shown (cf.~\cite[\S 13.10]{lind-marcus}
%\cite[Proposition 2.3.9]{lind-marcus}
) to be equivalent, and highlights certain properties of SFTs which will be key to our investigation.
\begin{definition}
\label{def:SFT}
Two matrices $A_1, A_2 \in M_{\mathcal A}(\NN )$ determine a {\em 2-dimensional shift of finite type} $X$, sometimes denoted $X_{A_1, A_2}$.  To be precise,
\[ X_{A_1, A_2} = \{ x \in \mathcal A^{\N^2}: A_i(x_{j}, x_{j + \varepsilon_i}) > 0 \text{ for } i = 1,2 \text{ all } j \}.  \]
    \end{definition}

\begin{definitions}[Wang tiles associated to a textile system] \label{def:WTdef}
Let $T = (p,q:F \to E)$ be a textile system. For each $f \in F^1$ we may define a tile $T_f$ such that 
\[
\begin{tikzpicture}
\node at (-5,1) {$\t ( T_f) = p(f) , \ \b( T_f)=q(f) ,$};
\node at (-5,0) {$\l (T_f) = r(f) , \ \r ( T_f) = s(f) .$};

\node at (0.5,0.5) {$T_f$};
\node[inner sep=0.8pt] (00) at (0,0) {$ $};
\node[inner sep=0.8pt] (10) at (1,0) {$ $}
	edge[] node[auto,black] {$q(f)$} (00);
\node[inner sep=0.8pt] (01) at (0,1) {$ $}
	edge[] node[auto,black,swap] {$r(f)$} (00);
\node[inner sep=0.8pt] (11) at (1,1) {$ $}
	edge[] node[auto,black,swap] {$p(f)$} (01)
	edge[] node[auto,black] {$s(f)$} (10);

\end{tikzpicture}
\]

\noindent Let $W_T = \{ T_f : f \in F^1 \}$ be the collection of Wang tiles associated to the textile system $T$.
\end{definitions}

\begin{lemma}
Let $T=(p,q : F\to E )$ be a textile system. Then $W_T$ is a collection of Wang tiles. Moreover if $T$ is $LR$ then $W_T$ is $LR$. 
\end{lemma}

\begin{proof}
Let $T=(p,q : F\to E )$ be a textile system. Since the map $A$ is injective it follows that $T_f$ is uniquely determined by $f \in F^1$. For each $f \in F^1$, the colors of the vertical sides of $T_f$ are elements of $F^0$ and the horizontal sides of $T_f$ are elements of $E^1$, and hence are different.
Therefore $W_T$ is a collection of Wang tiles.

For the second statement, observe that for $f \in F^1$ we have $TL ( T_f ) = ( p(f) , r(f) )$ and $BL( T_f )=(q(f),s(f))$, so the maps $TL$ and $BL$ are injective as $T$ is an LR textile system.
\end{proof}

\noindent Note that in the course of the above proof we established that $C ( W_T ) = F^0 \cup E^1$. Of course, if the Textile system comes from a $2$-graph $\Lambda$ then the associated textile system $T_\Lambda = ( p_\Lambda , q_\Lambda : F_\Lambda \to E_\Lambda )$ is LR and the corresponding Wang tiles $T_\Lambda = \{ T_f : f \in \Lambda^{\varepsilon_2} \}$ are LR; finally $C ( W_{T_\Lambda} ) = \Lambda^{\varepsilon_1} \sqcup \Lambda^{0}$

