\section{Cross-correlation between EPT and LPT}
\label{app:EPTvsLPT}

\noindent The cross-correlation between the leading order EPT and LPT fields is given by
\begin{align}\label{eq:deriv1}
\langle \delta_{\rm EPT}^{\rm LO}(\k_1) \delta_{\rm LPT}^{\rm LO}(\k_2) \rangle & = \int d^3 \q_1 d^3 \q_2 \, \langle \delta_1(\q_1) e^{-i\k_2\cdot\boldsymbol\psi_1(\q_2)} \rangle \, e^{-i\k_1\cdot\q_1- i\k_2\cdot\q_2} \nonumber \\
& = i \frac{d}{d\lambda} \int d^3 \q_1d^3 \q_2 \, \langle e^{-i(\lambda \delta_1(\q_1) +\k_2\cdot\boldsymbol\psi_1(\q_2))} \rangle \, e^{-i\k_1\cdot\q_1 - i\k_2\cdot\q_2} \Big|_{\lambda=0} \;.
\end{align}
The expectation value can be computed using the cumulant theorem. For a random variable $X$, we have
\begin{equation}
\langle e^{-iX} \rangle = \exp \left( \sum_{n=0}^\infty \frac{(-i)^n}{n!} \langle X^n \rangle_c \right) \;,
\end{equation}
where the cumulants $\langle X^n \rangle_c$ in our case represent the connected $n$-point functions. Since at LO all fields in the exponent are Gaussian, the only nontrivial cumulant is the power spectrum. After taking the derivative and setting $\lambda=0$ we get
\begin{align}
i \frac{d}{d\lambda} \langle e^{-i(\lambda \delta_1(\q_1) +\k_2\cdot\boldsymbol\psi_1(\q_2))} \rangle \Big|_{\lambda=0} & = i \frac{d}{d\lambda} e^{-\frac 12 \left( \lambda^2 \langle \delta_1^2(\q_1) \rangle + 2 \lambda \k_2 \cdot \langle \delta_1(\q_1) \boldsymbol\psi_1(\q_2) \rangle + k_2^ik_2^j \langle \psi_{1i}(\q_2) \psi_{1j}(\q_2) \rangle \right) } \Big|_{\lambda=0} \nonumber \\
& = -i \k_2 \cdot  \langle\delta_1(\q_1)\boldsymbol \psi_1(\q_2)\rangle e^{-\frac{1}{2}k_2^2\sigma_v^2 } \;.
\end{align}
Using this in the Eq.~\eqref{eq:deriv1} gives the following exact result for the LO cross correlation 
\begin{equation}
\langle \delta_{\rm EPT}^{\rm LO}(\k) \delta_{\rm LPT}^{\rm LO}(-\k) \rangle' = P_{\rm lin}(k) e^{-\frac{1}{2}k^2\sigma_v^2} \;.
\end{equation}
Assuming that at LO all power spectra are approximately equal to the linear power spectrum on large scales, we get the following LO cross-correlation coefficient
\begin{equation}
r^{\rm LO}(k)  \approx e^{-\frac{1}{2}k^2 \sigma_v^2} \;,
\end{equation}
which is the Eq.~\eqref{eq:cross_linear} in the main text.

The NLO cross-correlation can be derived in a similar way. It is clear from the generic structure of the LPT expressions that it must be exponentially suppressed on small scale, but keeping the cubic terms in the Eulerian perturbation theory guaranties partial cancellation of large displacement effects on large scales.  

\section{Trispectrum shot noise terms}
\label{app:noise}
\noindent Here we show all the possible contributions to the trispectrum shot noise. The total galaxy field can indeed be expressed as a sum of the perturbative solution and the stochastic contribution
\begin{equation}
    \delta_g(\x) = \delta_g^{\rm PT}(\x) + \epsilon(\x)\;.
    \label{eq:App_dtot}
\end{equation}
We expand the noise field using 
\begin{equation}
\epsilon(\x)= \epsilon_0(\x) + \epsilon_1(\x) \delta(\x) + \frac 12 \epsilon_2(\x)(\delta^2(\x)-\langle \delta^2 \rangle) + \epsilon_{\mathcal G_2}(\x) \mathcal G_2 (\x) + \ldots \;,
\end{equation}
and, since it is well-known that the spectra of the noise in the Poissonian limit satisfy
\begin{equation}
    B_{\epsilon} = P^2_\epsilon = \frac{1}{\bar{n}_g^2}\;,
\end{equation}
we define the correlation among different noise operators as
\begin{align}
\langle\epsilon_i(\x)\epsilon_j(\x')\rangle &\equiv \frac{c_{ij}}{\bar{n}_g}\delta^D(\x - \x')\,, \label{eq:App_cij}\\
\langle\epsilon_i(\x_1)\epsilon_j(\x_2)\epsilon_k(\x_3)\rangle &\equiv \frac{c_{ijk}}{\bar{n}_g^2}\delta^D(\x_1 - \x_2)\delta^D(\x_2 - \x_3)\,, \label{eq:App_cijk}\\
\langle\epsilon_i(\x_1)\epsilon_j(\x_2)\epsilon_k(\x_3)\epsilon_l(\x_4)\rangle &\equiv \frac{c_{ijkl}}{\bar{n}_g^3}\delta^D(\x_1 - \x_2)\delta^D(\x_2 - \x_3)\delta^D(\x_3 - \x_4)\;. \label{eq:App_cijkl}
\end{align}
As a warm-up, we compute the power spectrum and bispectrum stochastic terms: the power spectrum of Eq.~\eqref{eq:App_dtot} is
\begin{equation}
    P_{gg}(\k) = \langle\delta_g(\k)\delta_g(\k')\rangle' + \langle\epsilon(\k)\epsilon(\k')\rangle'\;,
\end{equation}
where we have exploited $\langle\delta \epsilon\rangle = 0$. The leading stochastic contribution for the galaxy power spectrum is then
\begin{equation}
    \langle\epsilon_0 (\k)\epsilon_0 (\k')\rangle' = \frac{c_{00}}{\bar{n}_g}\;,
\end{equation}
with $c_{00}$ being defined in Equation~\eqref{eq:App_cij}. Notice that additional terms in the expansion could arise that will eventually renormalize the $c_{00}$ coefficient, e.g. the term $\langle \epsilon_1(\x)\delta(\x)\epsilon_1(\x')\delta(\x')\rangle'$. For the bispectrum the leading shot noise terms are
\begin{equation}
    \langle \delta_g^{\rm PT}(\k_1)\epsilon(\k_2)\epsilon(\k_3)\rangle' + 2 \;\text{perms.} = \frac{c_{01}}{\bar{n}_g} b_1\big(P(k_1) +P(k_2) + P(k_3)\big)\;,
\end{equation}
and 
\begin{equation}
\langle\epsilon(\k_1)\epsilon(\k_2)\epsilon(\k_3)\rangle' = \frac{c_{000}}{\bar{n}_g^2}\;.
\end{equation}
For the trispectrum we can write all the possible terms in the perturbative expansion as
\begin{align}
\label{eq:App_Ttot}
T_g(\k_1,\k_2,\k_3,\k_4)=& \langle\delta_g(\k_1)\delta_g(\k_2)\delta_g(\k_3)\delta_g(\k_4)\rangle' \\
=& \langle\delta_g^{\rm PT}(\k_1)\delta_g^{\rm PT}(\k_2)\delta_g^{\rm PT}(\k_3)\delta_g^{\rm PT}(\k_4)\rangle' \nonumber\\
&+ \langle\delta_g^{\rm PT}(\k_1)\delta_g^{\rm PT}(\k_2)\delta_g^{\rm PT}(\k_3)\epsilon(\k_4)\rangle' + 3 \; \text{perms}\nonumber\\
& + \langle\delta_g^{\rm PT}(\k_1)\delta_g^{\rm PT}(\k_2)\epsilon(\k_3)\epsilon(\k_4)\rangle' + 5 \; \text{perms}\nonumber\\
& + \langle\delta_g^{\rm PT}(\k_1)\epsilon(\k_2)\epsilon(\k_3)\epsilon(\k_4)\rangle' + 3 \; \text{perms}\nonumber\\
& + \langle\epsilon(\k_1)\epsilon(\k_2)\epsilon(\k_3)\epsilon(\k_4)\rangle' \;.\nonumber
\end{align}
The first line of Equation~\eqref{eq:App_Ttot} is simply the tree-level perturbative expression for the galaxy trispectrum. The second line is automatically zero, since $\langle\epsilon\rangle = 0$. The third line gives rise to a number of possible stochastic terms (up to 1-loop order):
\begin{align}
    &\langle\delta_g^{\rm PT}(\k_1)\delta_g^{\rm PT}(\k_2)\epsilon(\k_3)\epsilon(\k_4)\rangle' = \langle b_1 \delta(\k_1)b_1 \delta(\k_2)\epsilon_0(\k_3)\epsilon_0 (\k_4)\rangle'\nonumber\\
    &+ \langle b_1\delta(\k_1)b_1\delta(\k_2)\epsilon_0(\k_3)\int_\p\epsilon_1(\p)\delta(\k_4 - \p)\rangle' +  \langle b_1\delta(\k_1)b_1\delta(\k_2)\epsilon_0(\k_3)\int_\p\epsilon_2(\p)\delta^2(\k_4 - \p)\rangle' \nonumber\\
    &+  \langle b_1\delta(\k_1)b_1\delta(\k_2)\epsilon_0(\k_3)\int_\p\epsilon_{\mathcal{G}_2}(\p)\mathcal{G}_2(\k_4 - \p)\rangle' +  \langle b_1\delta(\k_1)b_1\delta(\k_2)\int_\p\epsilon_1(\p)\delta(\k_3 - \p)\int_\p\epsilon_1(\p)\delta(\k_4 - \p)\rangle'\\
    & \langle b_1 \delta(\k_1)b_2\delta^2(\k_2)\epsilon_0(\k_3)\epsilon_0(\k_4)\rangle' + \langle b_1 \delta(\k_1)b_{\mathcal{G}_2}\mathcal{G}_2(\k_2)\epsilon_0(\k_3)\epsilon_0(\k_4)\rangle'\nonumber\\
    & + \langle b_1 \delta(\k_1)b_2 \delta^2(\k_2)\epsilon_0(\k_3)\int_\p \epsilon_1(\p)\delta(\k_3 - \p)\rangle' + \langle b_1 \delta(\k_1)b_{\mathcal{G}_2}\mathcal{G}_2(\k_2)\epsilon_0(\k_3)\int_\p \epsilon_1(\p)\delta(\k_3 - \p)\rangle'\;,\nonumber
\end{align}
that eventually give the $\propto \bar{n}_g^{-1}$ contribution
\begin{equation}
    \langle\delta_g^{\rm PT}(\k_1)\delta_g^{\rm PT}(\k_2)\epsilon(\k_3)\epsilon(\k_4)\rangle' = \frac{c_{01}}{\bar{n}_g}B_{mgg}(\k_{12},\k_3, \k_4) + \frac{2 b_1^2}{\bar{n}_g}\left(c_{02} + c_{0\mathcal{G}_2}\sigma^2(\k_1, \k_2) + c_{11}\right) P(k_1) P(k_2)\;.
\end{equation}
The fourth line of Equation~\eqref{eq:App_Ttot} produces contributions of order $\sim \bar{n}_g^2$
\begin{align}
    \langle\delta_g^{\rm PT}(\k_1)\epsilon(\k_2)\epsilon(\k_3)\epsilon(\k_4)\rangle' \simeq \frac{b_1 c_{001}}{\bar{n}_g^2}P(k_1) + 3 \, \text{perms.}\;. 
\end{align}
at leading perturbative order.
The last contribution is given by the noise trispectrum
\begin{equation}
\langle\epsilon(\k_1)\epsilon(\k_2)\epsilon(\k_3)\epsilon(\k_4)\rangle' = \frac{c_{0000}}{\bar{n}_g^3}\;.
\end{equation}

\section{Estimators and covariance matrices}
\label{app:covariances}
\begin{comment}

\noindent Working in the ideal world of Fisher forecasts or simulation boxes allows us to use simple estimators and derivation of corresponding covariance matrices is relatively straightforward. For simplicity we will start with the continuum limit and derive the $\chi^2$ in terms of the standard binning.

We begin by considering the power spectrum. Let us assume that we have a simulation box with volume $V$ and that the estimate of the galaxy density field in this box is given by $\hat\delta_g$. The standard power spectrum estimator is then given by 
\begin{equation}
\hat P_g(k) = \frac1{VV_s} \int_{\q\in k} \hat\delta_g(\q) \hat\delta_g(-\q) \;,
\end{equation}
where the volume of a spherical shell in the $k$-bin of thickness $\Delta k$ is $V_s=4\pi k^2 \Delta k$. Note that $\int_{\q\in k}$ indicates that the integration is done only in the shell of radius $k$ and thickness $\Delta k$. 
By taking the expectation value and using $V=(2\pi)^3 \delta^D(0)$ we can see that the estimator is unbiased
\begin{equation}
\langle \hat P_g(k) \rangle = \frac 1{VV_s} \int_{\q\in k} P_g(q) (2\pi)^3 \delta^D(0) \approx P_g(k) \;.
\end{equation}
The last equality is approximate, since we assume that $P(k)$ is approximately constant within the bin $k$ (or in other words that the bins are narrow).
The power spectrum covariance matrix $C_{PP'}$ in the Gaussian approximation is given by
\begin{align}
C_{PP'} & = \langle \hat P_g(k) \hat P_g(k') \rangle - \langle \hat P_g(k) \rangle \langle \hat P_g(k') \rangle = \frac {(2\pi)^3}V \frac{P_g^2(k)}{2\pi k^2 \Delta k} \delta^K_{kk'} \;.
\end{align}
This is a well-known formula where the covariance matrix is diagonal (different bins are uncorrelated).  

Let us now turn to the bispectrum. The bins in the data vector correspond to triangles of different shape labeled by the three sides $T=\{ k_1,k_2,k_3 \}$. Since each bin has a unique shape, the momenta are ordered $k_1\geq k_2 \geq k_3$. The standard estimator is 
\begin{equation}
\hat B(k_1,k_2,k_3) = \frac1{VV_{123}} \int_{\q_i\in k_i} \hat\delta_g(\q_1) \hat\delta_g(\q_2) \hat\delta_g(\q_3) \,\delta^D(\q_{123}) \;.
\end{equation}
Using the well-known result for the volume $V_{123}$ 
\begin{equation}
V_{123} = \int_{\q_i\in k_i} \,\delta^D(\q_{123}) = 8\pi^2 k_1 k_2 k_3 \Delta k^3 \;,
\end{equation}
one can check that the estimator is unbiased $\langle \hat B_g \rangle = B_g$. In the Gaussian approximation, the covariance matrix for the bispectrum estimator is given by
\begin{align}
C_{BB'} & = \langle \hat B_g(k_1,k_2,k_3) \hat B_g(k_1',k_2',k_3') \rangle - \langle \hat B_g(k_1,k_2,k_3) \rangle \langle \hat B_g(k_1',k_2',k_3') \rangle \nonumber \\
& = \frac{(2\pi)^3}{V} \frac{\pi s_{123}}{k_1k_2k_3 \Delta k^3} P_g(k_1) P_g(k_2) P_g(k_3) \;,
\end{align}
where $s_{123}$ equals 1, 2 or 6 for general, isosceles and equilateral triangles respectively.
\end{comment}

\noindent In this appendix we derive the expression for the trispectrum covariance matrix. The trispectrum configurations are labeled by quadrilaterals $Q$ defined by the four momenta and the two diagonals $Q=\{ k_1, k_2, k_3, k_4, D_1, D_2 \}$. In order to avoid  double counting and take into account all possible quadrilaterals, we have to order the momenta $k_1\geq k_2 \geq k_3 \geq k_4$ but we leave the diagonals free, subject to the constraint that the first diagonal is always the sum of the two largest momenta $\boldsymbol{D_1}+\k_1+\k_2=0$ and the second diagonal is always the sum of second and third largest momenta $\boldsymbol{D_2}+\k_2+\k_3=0$. The estimator for the connected trispectrum can be then written as 
\begin{align}
\hat T_c(k_1,k_2,k_3,k_4,D_1,D_2) & = \frac1{VV_{1234}} \int_{\q_i\in k_i} \int_{\p_i\in D_i} \hat\delta_g(\q_1) \hat\delta_g(\q_2) \hat\delta_g(\q_3)
\hat\delta_g(\q_4) \,\delta^D(\q_{1234}) \delta^D(\q_{12}+\p_1) \delta^D(\q_{23}+\p_2) \nonumber \\
& \qquad - {\rm disconnected \; terms} \;,
\end{align}
where the ``disconnected terms'' are chosen such that the estimator is unbiased $\langle \hat T_c \rangle = T_c$. Their explicit form is not of interest in the Gaussian likelihood, since they cancel in the covariance matrix.


Let us first compute the volume for the thin momentum shell containing all quadrilaterals with given momenta and diagonals. It is defined as
\beq
V_{1234} = \int_{p_i\in D_i} d^3 \p_i \int_{q_j \in k_j} d^3 \q_j \, \delta^D(\q_1+\q_2+\q_3+\q_4) \delta^D(\q_1+\q_2+\p_1) \delta^D(\q_2+\q_3+\p_2) \; .
\eeq
Note that the symmetry among six edges of the tetrahedron is broken the moment these particular delta functions are chosen. What complicates the evaluation of the integral is that~$\q_2$ appears three times as an argument of delta functions. When doing angular integrals this will lead to Wigner 3j symbols. Therefore, it is more convenient to rewrite the previous formula as follows
\beq
V_{1234} = \int_{p_i\in D_i} d^3 \p_i \int_{q_j \in k_j} d^3 \q_j \,  \delta^D(\q_1+\q_4-\p_2) \delta^D(\q_1+\q_2+\p_1) \delta^D(\q_2+\q_3+\p_2) \;,
\eeq
which we can always do using the delta functions. This form is simpler, since any of the momenta enter the arguments of the delta functions at most twice. Next we can write
\beq
V_{1234} = \int_{p_i\in D_i} d^3 \p_i \int_{q_j \in k_j} d^3 \q_j \int \frac{d^3\r}{(2\pi)^3} \frac{d^3\x}{(2\pi)^3} \frac{d^3\y}{(2\pi)^3} \, e^{- i\r \cdot(\q_1+\q_4-\p_2) -i\x \cdot (\q_1+\q_2+\p_1) - i\y \cdot(\q_2+\q_3+\p_2) } \;.
\eeq 
Angular integration over $\p_1$, $\q_4$ and $\q_3$ can be done easily. 
\begin{align}
V_{1234} & = \frac{1}{8\pi^6} \int_{p_i\in D_i} p_i^2 dp_i  \int_{q_j \in k_j} q_j^2 dq_j  \int_0^\infty r^2 dr \int_0^\infty x^2 dx \int_0^\infty y^2 dy \, j_0(p_1x) j_0(q_4 r) j_0(q_3 y) \nonumber \\
& \qquad \times \int d\Omega_{p_2} \int d\Omega_{q_1} \int d\Omega_{q_2} \int d\Omega_{r} \int d\Omega_{x} \int d\Omega_{y}  \, e^{- i\r \cdot(\q_1-\p_2) -i\x \cdot (\q_1+\q_2) - i\y \cdot(\q_2+\p_2) } \; .
\end{align}
In order to perform the other angular integrals, we will use the expansion of plane waves in spherical Bessel functions and spherical harmonics
\beq
e^{\pm i \r \cdot \q} = 4\pi \sum_{\ell m} (\pm i)^\ell j_\ell (q r) Y_{\ell m}(\hat{\r}) Y^*_{\ell m}(\hat{\q}) \;. 
\label{eq:exp}
\eeq
It follows that
\beq
\int d\Omega_{q_1} e^{- i \r \cdot \q_1 - i\x \cdot \q_1} = (4\pi)^2 \sum_{\ell_1 m_1} \sum_{\ell_2 m_2} (- i)^{\ell_1+\ell_2} j_{\ell_1} (q_1 r) j_{\ell_2} (q_1 x) Y_{\ell_1 m_1}(\hat{\r}) Y_{\ell_2 m_2}^*(\hat{\x}) \int d\Omega_{q_1} Y^*_{\ell_1 m_1}(\hat{\q}_1) Y_{\ell_2 m_2}(\hat{\q}_1) \;. 
\eeq
By orthonormality of the spherical harmonic this integral leads to
\beq
\int d\Omega_{q_1} e^{- i \r \cdot \q_1 - i\x \cdot \q_1} = (4\pi)^2 \sum_{\ell m} (-1)^{\ell} j_{\ell} (q_1 r) j_{\ell} (q_1 x) Y_{\ell m}(\hat{\r}) Y_{\ell m}^*(\hat{\x}) \;. 
\eeq
We can to the other angular integrals in the similar way. In particular,
\beq
\int d\Omega_{q_2} e^{- i \x \cdot \q_2 - i\y \cdot \q_2} = (4\pi)^2 \sum_{\ell m} (-1)^{\ell} j_{\ell} (q_2 x) j_{\ell} (q_2 y) Y_{\ell m}(\hat{\x}) Y_{\ell m}^*(\hat{\y}) \;,
\eeq
\beq
\int d\Omega_{p_2} e^{+ i \r \cdot \p_2 - i\y \cdot \p_2} = (4\pi)^2 \sum_{\ell m} j_{\ell} (p_2 r) j_{\ell} (p_2 y) Y_{\ell m}(\hat{\y}) Y_{\ell m}^*(\hat{\r}) \;. 
\eeq
Once all the angular integrals are done, the volume of the shell is a complicated radial integral of product of spherical Bessel functions
\begin{align}
V_{1234}  & = 8^3 \int_{p_i\in D_i} p_i^2 dp_i  \int_{q_j \in k_j} q_j^2 dq_j  \int_0^\infty r^2 dr \int_0^\infty x^2 dx \int_0^\infty y^2 dy \sum_{\ell} (2\ell+1) \,  \nonumber \\
& \qquad \times j_0(p_1x) j_0(q_4 r) j_0(q_3 y) j_{\ell} (q_1 r) j_{\ell} (q_1 x) j_{\ell} (q_2 x) j_{\ell} (q_2 y) j_{\ell} (p_2 r) j_{\ell} (p_2 y) \; .
\end{align}
Luckily, the radial integrals can be also done relatively straightforwardly. First, we can use 
\beq\label{eq:legendre}
\int_0^\infty r^2 dr \, j_0(q_4 r) j_{\ell} (q_1 r) j_{\ell} (p_2 r) = \frac{\pi}{4q_1q_4p_2} \mathcal P_\ell \left( \frac{q_1^2+p_2^2-q_4^2}{2q_1p_2} \right)\;,
\eeq
where~$\mathcal P_\ell(x)$ are the Legendre polynomials. The volume of the shell then becomes
\begin{align}
V_s & = (2\pi)^3 \int_{p_i\in D_i} p_i^2 dp_i  \int_{q_j \in k_j} q_j^2 dq_j \sum_{\ell} (2\ell+1) \,  \nonumber \\
& \qquad \times \frac{1}{q_1q_4p_2} \mathcal P_\ell \left( \frac{q_1^2+p_2^2-q_4^2}{2q_1p_2} \right) \frac{1}{q_1q_2p_1} \mathcal P_\ell \left( \frac{q_1^2+q_2^2-p_1^2}{2q_1q_2} \right) \frac{1}{q_2q_3p_2} \mathcal P_\ell \left( \frac{q_2^2+p_2^2-q_3^2}{2q_2p_2} \right) \; .
\end{align}
Finally, the sum over $\ell$ can be done using 
\beq
\sum_\ell (2\ell+1) \mathcal{P}_\ell (\mu_1) \mathcal{P}_\ell (\mu_2) \mathcal{P}_\ell (\mu_3) = \frac{2}{\pi} \frac{1}{\sqrt{1 + 2\mu_1 \mu_2 \mu_3-\mu_1^2-\mu_2^2 -\mu_3^2}} \;.
\eeq
This equation has a nice geometric interpretation. It is related to the volume of the tetrahedron with three edges $q_1$, $q_2$ and $p_2$ 
\beq
V_{\rm tetra} = \frac{q_1 q_2 p_2}{6} {\sqrt{1 + 2\mu_1 \mu_2 \mu_3-\mu_1^2-\mu_2^2 -\mu_3^2}} \;,
\eeq
where $\mu_i$ are cosines of plane angles between three edges meeting in a common vertex. In our formula for $V_{1234}$ we have exactly the same form after closer inspections of all angles. Therefore, we can finally write (assuming that all bins are~$\Delta k$ wide)
\begin{align}\label{eq:shell}
V_s & = \frac83 \pi^2 \frac{k_1 k_2 k_3 k_4 D_1 D_2}{V_{\rm tetra}} \Delta k^6  \; .
\end{align}
The volume $V_{\rm tetra}$ can be computed in terms of six edges and this expression is manifestly symmetric in~$k_1,\ldots,k_4$ and~$D_1,D_2$. 


Now we are ready to compute the trispectrum covariance matrix:

\begin{equation}
\begin{gathered}
\text{Cov}(k_1,k_2,k_3,k_4,D_1,D_2) = \langle\hat{T}(k_1,k_2,k_3,k_4,D_1,D_2)\hat{T}(k_a,k_b,k_c,k_d,D_a,D_b)\rangle-\\\langle\hat{T}(k_1,k_2,k_3,k_4,D_1,D_2)\rangle\langle\hat{T}(k_a,k_b,k_c,k_d,D_a,D_b)\rangle\\
=\frac{(2\pi)^{12}}{V^2 V_{1234} V_{abcd}} P(k_1)P(k_2)P(k_3)P(k_4)\prod_{i=1,a}^{4,d}\prod_{j=1,a}^{2,b} \int_{\bq_i\in\bk_i}d^3q_i\int_{\bp_j\in \mathbf{D}_j}d^3p_j\\
\times\delta_D(\bq_{1234})\delta_D(\bq_{12}+\p_1)\delta_D(\bq_{23}+\p_2)\delta_D(\bq_{abcd})\delta_D(\bq_{ab}+\p_a)\delta_D(\bq_{bc}+\p_b)\delta_D(\bq_{1a})\delta_D(\bq_{2b})\delta_D(\bq_{3c})\delta_D(\bq_{4d})+\text{23 perm.}\\
=\frac{(2\pi)^9}{V V_{1234} V_{abcd}} P(k_1)P(k_2)P(k_3)P(k_4)\delta^K_{\bk_1,\bk_a}\delta^K_{\bk_2,\bk_b}\delta^K_{\bk_3,\bk_c}\delta^K_{\bk_4,\bk_d}\delta^K_{\bp_1,\bp_a}\delta^K_{\bp_2,\bp_b}\prod_{i=a}^{d}\prod_{j=a}^{b} \int_{\bq_i\in\bk_i}d^3q_i\int_{\bp_j\in \mathbf{D}_j}d^3p_j\\
\times\delta_D(\bq_{abcd})\delta_D(\bq_{ab}+\p_a)\delta_D(\bq_{bc}+\p_b)+\text{23 perm.}\\
=\frac{(2\pi)^9}{V V_{1234}} P(k_1)P(k_2)P(k_3)P(k_4)\delta^K_{\bk_1,\bk_a}\delta^K_{\bk_2,\bk_b}\delta^K_{\bk_3,\bk_c}\delta^K_{\bk_4,\bk_d}\delta^K_{\bp_1,\bp_a}\delta^K_{\bp_2,\bp_b}+\text{23 perm.}\\
=\frac{(2\pi)^9R_{1234}}{V V_{1234}} P(k_1)P(k_2)P(k_3)P(k_4)\;,
\end{gathered}
\end{equation}
where $V_{1234}$ is given by Equation~\eqref{eq:shell}.
\subsection{PT cross terms}\label{app:PTterms}
\noindent In the Gaussian approximation some PT cross-terms survive.
We have:
\begin{equation}
    \begin{gathered}
        \langle T(k_1,k_2,k_3,k_4,D_1,D_2)P(k)\rangle - \langle T(k_1,k_2,k_3,k_4,D_1,D_2)\rangle \langle P(k)\rangle=\\
        \frac{1}{V^2V_{1234}V_P}\prod_{i=1}^{4}\prod_{j=1,2}\prod_{n=a,b} \int_{q_i\in k_i}{d^3q_i}\int_{p_i\in D_j}{d^3p_j}\int_{q_n\in k_n}{d^3q_n}\delta_D(\bq_{1234}) \delta_D(\bq_{ab}) \delta_D(\bq_{12}+\bp_1) \delta_D(\bq_{23}+\bp_2)\times \\
        \langle(\delta(\bq_1) \delta(\bq_2) \delta(\bq_3) \delta(\bq_4) \delta(\bq_a) \delta(\bq_b)\rangle_c   \\
        =2\frac{(2\pi)^9}{V^2V_{1234}V_P}\prod_{i=1}^{4}\prod_{j=1,2}\prod_{n=a,b} \int_{q_i\in k_i}{d^3q_i}\int_{p_i\in D_j}{d^3p_j}\int_{q_n\in k_n}{d^3q_n}\delta_D(\bq_{1234}) \delta_D(\bq_{ab}) \delta_D(\bq_{12}+\bp_1) \delta_D(\bq_{23}+\bp_2)\times \\
       \delta_D(\bq_{1a}) \delta_D(\bq_{3b})\delta_D(\bq_{24})P(q_1)P(q_3)P(q_2)\\
       = 2\frac{(2\pi)^6}{VV_{1234}V_P}P^2(k)P(k_2)\delta_{\bk_,\bk_1}\delta_{\bk_,\bk_3}\delta_{\bk_2,\bk_4}\prod_{i=3,4}\prod_{j=1,2} \int_{q_i\in k_i}{d^3q_i}\int_{p_i\in D_j}{d^3p_j}\delta_D(-\bq_3-\bq_4+\bp_1)\delta_D(\bq_3-\bq_4+\bp_2)\;,      
    \end{gathered}
\end{equation}
all the other contractions will give $\bp_{1,2}=0$ which do not fall in any bin. Now we want to evaluate:
\beq
\begin{gathered}
    \prod_{i=3,4}\prod_{j=1,2} \int_{q_i\in k_i}{d^3q_i}\int_{p_i\in D_j}{d^3p_j}\delta_D(-\bq_3-\bq_4+\bp_1)\delta_D(\bq_3-\bq_4+\bp_2)\\
    =\frac{1}{(2\pi^2)^2} \int d^3q_3\int d^3q_4\int dp_1p_1^2\int dp_2p_2^2\int d^3 x\int d^3y e^{i\bq_3(\bx-\mathbf{y})}e^{-i\bq_4(\bx+\mathbf{y})}j_0(p_1y)j_0(p_2x)\;,
\end{gathered}
\eeq
where we performed angular integrations over $\bp_1$ and $\bp_2$. Using Equation~\eqref{eq:exp} leads to
\beq
\begin{gathered}
    2^6\sum_{\ell}(2\ell+1)\int dq_3 dq_4 dp_1dp_2 dxdyq_3^2q_4^2p_1^2p_2^2x^2y^2 j_{\ell}(q_3x)j_{\ell}(q_3y)j_{\ell}(q_4x)j_{\ell}(q_4y)j_0(p_1x)j_0(p_2y)\;,
\end{gathered}
\eeq

and using Equation~\eqref{eq:legendre} we get:
\beq\label{eq:eq}
\begin{gathered}
    4\pi^2\sum_{\ell}(2\ell+1)\int p_1p_2 dq_3 dq_4 dp_1dp_2\mathcal{P}_{\ell}\left(\frac{q_3^2+q_4^2-p_1^2}{2q_3q_4}\right)\mathcal{P}_{\ell}\left(\frac{q_3^2+q_4^2-p_2^2}{2q_3q_4}\right)\;.
\end{gathered}
\eeq
Now it is known that
\beq
\begin{gathered}
\sum_{\ell}\frac{(2\ell+1)}{2}\mathcal{P}_{\ell}(\mu_1)\mathcal{P}_{\ell}(\mu_2)=\delta_D(\mu_1-\mu_2)\;.
\end{gathered}
\eeq

So Equation~\eqref{eq:eq} reads
\beq
\begin{gathered}
    2(4\pi^2)\delta_{D_1,D_2}\int p_1^2dp_1\int dq_3\int dq_4= 8 \pi^2\delta_{D_1,D_2}D_1^2\Delta k^3\;.
\end{gathered}
\eeq
So PT terms are non-zero only for quadrilaterals which have $k_1=k_3$,  $k_2=k_4$, $D_1=D_2$; given that we are considering quadrilaterals with ordered sides, the only possible configurations are the equilateral shapes, i.e. $k_1 = k_2= k_3 = k_4$ and $D_1 = D_2$. They are $\sim 0.1\%$ of the total number.



