    \nonumber \\ & + &
    A_3 \sin\theta\cos\phi + A_4 \cos\theta + A_5 \sin^2\theta\sin 2\phi + A_6 \sin 2\theta\sin\phi + A_7 \sin\theta\sin\phi \Bigg)\, . \nonumber \\
\end{eqnarray}
