%%%%
\begin{eqnarray}
I_{T_p} (z,\qv,z\kv) = |C_f^G|^2 \, 2 g^G_{V,f} g^G_{A,f} \Big\{ (2-z) \bPhi^2 + z \Phi_0^2 \Big\} ,
\end{eqnarray}
%%%%
while $I_{\Delta \Delta_p} \equiv 0$. For the longitudinal polarizations we have
%%%
\begin{eqnarray}
   I_L(z,\qv,z\kv) &=& I^{(0,0)}(z,\qv,z\kv) \, \nonumber \\
   &=& \frac{|C_f^G|^2}{zM^2} \Big\{ \Big( (g_{V,f}^G)^2 \Lambda_V^2 + (g_{A,f}^G)^2 \Lambda_A^2 \Big) \Phi_0^2 \nonumber \\
&&+ z^2 \Big( (g_{V,f}^G)^2 (m_b - m_a)^2 + (g_{A,f}^G)^2 (m_b + m_a)^2 \Big) \bPhi^2  \Big\}\, . 
  \end{eqnarray}
%%%
As far as the longitudinal-transverse interference structure functions are concerned, the identities of Eq. (\ref{eq:LT_identity}) immediately yield the vanishing of%
\begin{eqnarray}
 I_\nabla = I_{\Delta_p} \equiv 0 \, .   
\end{eqnarray}
%%%%
We obtain one nonvanishing parity even LT-interference structure function with the kernel
%%%%
\begin{eqnarray}
    I_{\Delta}(z,\qv,z\kv)  &=& \frac{|C_f^G|^2}{M} \Big\{ \frac{2-z}{z} \Big( (g^G_{A,f})^2 \Lambda_A - (g^G_{V,f})^2 \Lambda_V \Big)  \nonumber \\
    &&+ z \Big( (g^G_{V,f})^2 \Gamma_V (m_b - m_a) - (g^G_{A,f})^2 \Gamma_A(m_b + m_a) \Big) \Big \}   \, \Phi_0 \frac{\qv \cdot \bPhi}{|\qv|}, 
\end{eqnarray}
%%%%
and a parity odd one;
%%%%
\begin{eqnarray}
    I_{\nabla_p}(z,\qv,z\kv) = \frac{|C_f^G|^2}{M} \, g^G_{V,f} g^G_{A,f} \Big\{ \Lambda_V - \Lambda_A + z \Big( (m_b - m_a) \Gamma_A - (m_b + m_a) \Gamma_V\Big) \Big\} \, \Phi_0 \frac{\qv \cdot \bPhi}{|\qv|} . \nonumber \\
\end{eqnarray}
%%%%
For the case of virtual photons, our results are in agreement with the results of \cite{Schafer:2016qmk}. Notice that for massless quarks $\Gamma_{V,A} \to 0$, and the parity- conserving structure functions of electroweak gauge bosons become proportional to the ones for virtual photons. For finite quark masses this is evidently not the case, due to the non-conservation of the axial current.
Substantial simplifications occur in the limit of massless quarks, which is relevant for the practical applications.
In particular, in the massless quark limit, parity even structure functions will be proportional to $(g_{V,f}^G)^2 + (g_{A,f}^G)^2 $, while for finite masses also the combination $(g_{V,f}^G)^2 - (g_{A,f}^G)^2 $ will enter.
