\section{Light front wave functions and helicity density matrix elements}\label{app:LFWF}
%*****************************


For the convenience of the reader, in this appendix we collect the explicit expression for the relevant LFWFs obtained in \cite{Bandeira:2024zjl}.

We will use that the light front wave functions in the coordinate space can be obtained by a Fourier transform of  the corresponding WF in the momentum space 
\begin{eqnarray}
\Psi_{\eta\eta'}^{(\lambda)}(z,\rr) \Bigg\vert_{V}  &=\  & \int\frac{\dd^{2}\qv}{(2\pi)^{2}}e^{-i \rr\qv} \, \Psi_{\eta\eta'}^{(\lambda)}(z,\qv) \Bigg\vert_{V} \, , \nonumber \\
&=\  & C_{f}^{G}g_{V,f}^{G}\sqrt{z(1-z)}\int\frac{\dd^{2}\qv}{(2\pi)^{2}}e^{- i\rr\qv}\frac{E^*_\mu(q,\lambda)\Gamma_V^\mu}{\qv^{2}+\epsilon^{2}},
\end{eqnarray}
and
\begin{eqnarray}
\Psi_{\eta\eta'}^{(\lambda)}(z,\rr) \Bigg\vert_{A} &=\  & \int\frac{\dd^{2}\qv}{(2\pi)^{2}}e^{-i\rr\qv}\Psi_{\eta\eta'}^{(\lambda)}(z,\qv)\Bigg\vert_{A}\, , \nonumber \\
&=\  & C_{f}^{G}g_{A,f}^{G}\sqrt{z(1-z)}\int\frac{\dd^{2}\qv}{(2\pi)^{2}}e^{-i\rr\qv}\frac{E^*_\mu(q,\lambda)\Gamma_A^\mu}{\qv^{2}+\epsilon^{2}},
\end{eqnarray}
with $\epsilon^{2}=(1-z)M^{2}+z(m_{b}^{2}-m_{a}^{2})+z^{2}m_{a}^{2}$ and
\begin{eqnarray}
    \Gamma_V^\mu &=&     \bar u(1-z,\qv,\lambda') \Big\{ \gamma^\mu  +  (m_b - m_a) \frac{k^\mu}{M^2_G} \Big \} u(1,\pmb 0, \lambda) \, \nonumber \\
    \Gamma_A^\mu &=&    \bar u(1-z,\qv,\lambda') \Big\{ \Big(\gamma^\mu  + (m_a + m_b)\frac{k^\mu}{M^2_G} \Big) \gamma_5   \Big \} u(1,\pmb 0, \lambda) \, ,
\end{eqnarray}
where $m_a$ and $m_b$ are the masses of the quarks before and after the gauge boson emission, and the polarization vectors to be used are  
\begin{eqnarray}
    E_\mu(q,\pm 1) = E_\mu^{\perp}(\pm 1) - \frac{E^{\perp}(\pm 1)\cdot q}{q^+} n^-_\mu \, ,\quad   E_\mu(q,0) = - \frac{M_G}{q^+} \, n^-_\mu \, . 
\end{eqnarray}

%(For $Z$ and $\gamma$ emissions, one has $m_a = m_b$).

Then the LFWF, understood as a $2 \times 2$ matrix in the space of (anti--)quark polarizations, reads
\begin{eqnarray}
\Psi^{(\lambda)}(z,\kv) = C_f^G  \Big\{ g^G_{V,f} \Psi_V^{(\lambda)}(z,\kv) + g^G_{A,f} \Psi_A^{(\lambda)}(z,\kv) \Big\} \, , 
\end{eqnarray}
%%%
with 
\begin{align}
\begin{split}
    \Psi_{V}^{(\pm)}(z,\boldsymbol{k})=\  & \frac{C_{f}^{G}g_{V,f}^{G}\sqrt{z}}{\kv^2 + \epsilon^2} \chi_{\eta'}^{\dagger}\Big\{ \frac{2-z}{z}\left(\boldsymbol{k}\cdot\be^{*}(\pm)\right)\openone 
    + i\left(\boldsymbol{k}\times\be^{*}(\pm)\right)_{\hat{z}}\sigma_{3}
    \\ & 
    -\Gamma_{V}\left(\boldsymbol{\sigma}\cdot\be^{*}(\pm)\right)\sigma_{3} \Big\} \chi_{\eta}\label{eq:MS-LFWF-V+-}    
\end{split}\\
\Psi_{V}^{(0)}(z,\boldsymbol{k})=\  & \frac{C_{f}^{G}g_{V,f}^{G}}{\sqrt{z}M [\kv^2 + \epsilon^2]} \chi_{\eta'}^{\dagger}\left\{ \Lambda_{V}\openone+z(m_{b}-m_{a})\left(\boldsymbol{\sigma}\cdot\boldsymbol{k}\right)\sigma_{3}\right\} \chi_{\eta}\label{eq:MS-LFWF-V0}\\
\begin{split}
\Psi_{A}^{(\pm)}(z,\boldsymbol{k})=\  & \frac{C_{f}^{G}g_{A,f}^{G}\sqrt{z}}{\kv^2 + \epsilon^2} \chi_{\eta'}^{\dagger}\Big\{ \frac{2-z}{z}\left(\boldsymbol{k}\cdot\be^{*}(\pm)\right)\sigma_{3}
+i\left(\boldsymbol{k}\times\be^{*}(\pm)\right)_{\hat{z}}\openone
\\ &
-\Gamma_{A}\left(\boldsymbol{\sigma}\cdot\be^{*}(\pm)\right)\Big\} \chi_{\eta}\label{eq:MS-LFWF-A+-}    
\end{split}
\\
\Psi_{A}^{(0)}(z,\boldsymbol{k})=\  & \frac{C_{f}^{G}g_{A,f}^{G}}{\sqrt{z}M [\kv^2 + \epsilon^2]} \, \chi_{\eta'}^{\dagger}\left\{ -\Lambda_{A}\sigma_{3}-z(m_{b}+m_{a})\left(\boldsymbol{\sigma}\cdot\boldsymbol{k}\right)\openone \right\} \chi_{\eta} .
\label{eq:MS-LFWF-A0}
\end{align}

