\label{sec:frame transformation}
%****************************
In Eq.~\eqref{eq:angular_distribution} we present the full expression for the angular distribution in terms of density matrix elements, however using the Eq.~\eqref{eq:structure_func_def} one can connect the density matrix elements with the structure functions elements. Therefore, the angular distribution in terms of the structure functions at a given production plane frame $F$ is:
\begin{eqnarray}\label{appx:lep-ang-dist}
    \frac{d N}{d \Omega} &=&  \frac{3}{8\pi} \frac{1}{2W_T + W_L}
    \Bigg[ g_T W_T + g_L W_L + g_\Delta W_\Delta  + g_{\Delta\Delta} W_{\Delta\Delta} \nonumber \\ 
    & & + c_G g_{T_P} W_{T_P} + c_G g_{\nabla_P} W_{\nabla_P} + c_G g_\nabla W_\nabla + g_{\Delta\Delta_P} W_{\Delta\Delta_P} + g_{\Delta_P} W_{\Delta_P}
    \Bigg]\, ,
\end{eqnarray}
where 
\begin{eqnarray}
    g_T = 1 + \cos^2\theta \, , \quad & g_L = 1 - \cos^2\theta \, , \quad & g_{T_P} = 2 \cos\theta \, , \nonumber\\ 
    g_{\Delta\Delta} = \sin^2\theta\cos 2\phi \, , \quad & g_\Delta = \sin 2\theta\cos\phi \, , \quad & g_{\nabla_P} = 2\sin\theta\cos\phi \, , \nonumber\\
    g_{\Delta\Delta_P} = \sin^2\theta\sin 2\phi \, , \quad & g_{\Delta_P} = \sin 2\theta\sin\phi \, , \quad & g_{\nabla} = 2 \sin\theta\sin\phi \, . 
\end{eqnarray}
\par 
We can parameterize the transformation from one observation frame to another by a single angle, describing a rotation around the $y$ axis. The rotation matrix 
\begin{eqnarray}
    R_y(\gamma) &=& 
    \begin{pmatrix}
        \cos\gamma &  0 & - \sin \gamma \\ 
        0 & 1 & 0 \\ 
        \sin\gamma & 0 & \cos\gamma
    \end{pmatrix}
\end{eqnarray}
transforms the components of a vector, reproducing the effect of a rotation of the $Z$ and $x$ axis in the production plane. The coordinates of the unit vector indicating the positive lepton direction in the \emph{old} frame, 
\begin{eqnarray}
    \hat r &=& 
    \left( 
        \sin\theta\cos\phi,\,\sin\theta\sin\phi,\,\cos\theta 
    \right)\,,
\end{eqnarray}
can be expressed as a function of the coordinates in the new frame as 
\begin{eqnarray}\label{appx:coor-rel}
    \sin\theta\cos\phi &=& \cos\gamma\sin\theta'\cos\phi'+\sin\gamma\cos\theta' \, , \\
    \sin\theta\sin\phi &=& \sin\theta\sin\phi  \, , \\ 
    \cos\theta &=& -\sin\gamma\sin\theta'\cos\phi' + \cos\gamma\cos\theta' \, .
\end{eqnarray}

Substituting Eq.~\eqref{appx:coor-rel} into Eq.~\eqref{appx:lep-ang-dist}, we obtain the angular distribution in the rotated frame
\begin{eqnarray}\label{appx:rot-lep-ang-dist}
    \frac{d N}{d \Omega} &=&  \frac{3}{8\pi} \frac{1}{2W_T + W_L} \Bigg\{ 
    g_T
        \Big[
            \Big(1- {\sin^2\gamma \over 2}\Big) W_T + {\sin^2\gamma \over 2} W_L + {\sin2\gamma \over 2} W_\Delta + {\sin^2 \gamma \over 2}W_{\Delta\Delta}
        \Big] \nonumber \\ 
&+&
    g_L 
        \Big[
            \sin^2\gamma W_T + \cos^2\gamma W_L - \sin2\gamma W_\Delta - \sin^2\gamma W_{\Delta\Delta}
        \Big] \nonumber \\ 
&+&
    g_{\Delta} 
        \Big[ 
            -{\sin2\gamma \over 2}W_T + {\sin2\gamma \over 2}W_L + \cos2\gamma W_\Delta + {\sin2\gamma \over 2}W_{\Delta\Delta}
        \Big] \nonumber \\ 
&+&
    g_{\Delta\Delta}
        \Big[ 
            {\sin^2\gamma \over 2}W_T - {\sin^2\gamma \over 2}W_L - {\sin2\gamma \over 2}W_{\Delta} + \Big({1 - \sin^2\gamma \over 2}\Big)W_{\Delta\Delta}
        \Big] \nonumber \\ 
&+&
    c_G g_{T_p}
        \Big[ 
            \cos\gamma W_{T_p} + \sin\gamma W_{\nabla_p}
        \Big] \nonumber \\
&+& 
    c_G g_{\nabla_p} 
        \Big[ 
            -\sin\gamma W_{T_p} + \cos\gamma W_{\nabla_p}
        \Big]\nonumber \\ 
&+&
   g_{\Delta\Delta_p} 
        \Big[ 
            \cos\gamma W_{\Delta\Delta_p} - \sin\gamma W_{\Delta_p}
        \Big]\nonumber \\ 
&+&
   g_{\Delta_p} 
        \Big[ 
            \sin\gamma W_{\Delta\Delta_p} + \cos\gamma W_{\Delta_p}
        \Big]\nonumber \\         
&+&
    c_G g_{\nabla} W_{\nabla} \Bigg\}\,.
\end{eqnarray}

Therefore, comparing Eq.~\eqref{appx:lep-ang-dist} and Eq.~\eqref{appx:rot-lep-ang-dist}, we obtain the relation between the structure function in different frames.
