    \begin{pmatrix}
        W_T \\ W_L \\ W_\Delta \\ W_{\Delta\Delta} \\ W_{T_p} \\ W_{\nabla_p} \\ W_{\Delta\Delta_p} \\ W_{\Delta_p} \\ W_\nabla
