\section{The angular coefficients}\label{appx-sec:angular-coeff}
%*****************************
In Eq.~\eqref{eq:ang-dist-A} we present the angular distribution parametrization, nevertheless one need connects it with the angular distribution which given us the $A_i$ ($i=0,1,2,3,4,5,6,7$) values in terms of the structure functions $W_j$ ($j=T,L,\Delta,\Delta\Delta,T_P,\nabla_P,\nabla,\Delta\Delta_P,\Delta_P$). In what follows, we'll show how to obtain such connection. Therefore, starting from the angular distribution which is written as
\begin{eqnarray}
    \frac{d N}{d \Omega} &=&  \frac{3}{8\pi} \frac{1}{2W_T + W_L}
    \Bigg[ g_T W_T + g_L W_L + g_\Delta W_\Delta  + g_{\Delta\Delta} W_{\Delta\Delta} \nonumber \\ 
    & & + c_G g_{T_P} W_{T_P} + c_G g_{\nabla_P} W_{\nabla_P} + c_G g_\nabla W_\nabla + g_{\Delta\Delta_P} W_{\Delta\Delta_P} + g_{\Delta_P} W_{\Delta_P}
    \Bigg]\, ,
\end{eqnarray}
where 
\begin{eqnarray}
    g_T = 1 + \cos^2\theta \, , \quad & g_L = 1 - \cos^2\theta \, , \quad & g_{T_P} = 2 \cos\theta \, , \nonumber\\ 
    g_{\Delta\Delta} = \sin^2\theta\cos 2\phi \, , \quad & g_\Delta = \sin 2\theta\cos\phi \, , \quad & g_{\nabla_P} = 2\sin\theta\cos\phi \, , \nonumber\\
    g_{\Delta\Delta_P} = \sin^2\theta\sin 2\phi \, , \quad & g_{\Delta_P} = \sin 2\theta\sin\phi \, , \quad & g_{\nabla} = 2 \sin\theta\sin\phi \, . 
\end{eqnarray}
\par 
Multiplying the angular distribution by $(W_T +W_L)/(W_T +W_L)$, \ one gets
\begin{eqnarray}\label{eq:theo-parametrization}
    \frac{d N}{d \Omega} &=&  \frac{3}{4\pi} \frac{1}{\lambda+3}
    \Bigg[
        1 + \lambda\cos^2\theta + \mu\sin2\theta\cos\phi + {\nu \over 2}\sin^2\theta\cos2\phi 
\nonumber \\ &&
        + \tau\sin\theta\cos\phi + \eta\cos\theta + \xi\sin^2\theta\sin2\phi
        + \zeta\sin2\theta\sin\phi + \chi\sin\theta\sin\phi
    \Bigg]\, ,
\end{eqnarray}
where 
\begin{eqnarray}
    \lambda = {W_T - W_L \over W_T + W_L} \, , \, \,  \mu = {W_\Delta \over W_T + W_L}\, , \, \, \nu = {2W_{\Delta\Delta} \over W_T + W_L} \, , \, \, 
    \tau = {2c_{G} W_{\nabla_P} \over W_T + W_L}\, , 
\nonumber \\
    \eta = {2c_GW_{T_P} \over W_T + W_L} \, ,  \, \, \xi = {W_{\Delta\Delta_P} \over W_T + W_L}\, , \, \,
    \zeta = {W_{\Delta_P} \over W_T + W_L} \, , \, \, \chi = {2c_GW_\nabla \over W_T + W_L}\, .   
\end{eqnarray}

The Eq.~\eqref{eq:theo-parametrization} is an usual parametrization for the angular distribution, quite often present in theoretical papers (see for instance \cite{Boer:2006eq,Lyubovitskij:2024jlb}). However, the most used parametrization found in experimental works is the one presented in Eq.~\eqref{eq:ang-dist-A}. Therefore, by comparison, one has that these two parametrization connects trough
\begin{eqnarray}
     A_0 = { 2(1-\lambda) \over \lambda + 3 } = {2W_L \over 2W_T + W_L}\, , \,\, &&\, \,
     A_1 =  {4\mu \over \lambda + 3} = {2W_\Delta \over 2W_T + W_L} \, , \,\,
 \nonumber \\ 
     A_2 = {4\nu \over \lambda + 3} = {4W_{\Delta\Delta} \over 2W_T + W_L}\, , \, \, &&\, \,
     A_3 = {4\tau \over \lambda + 3} = {4 c_G W_{\nabla_P} \over 2W_T + W_L}\, , \, \, 
 \nonumber \\ 
     A_4 = {4\eta \over \lambda + 3} = {4 c_G W_{T_P} \over 2W_T + W_L}\, , \, \, &&\, \,
     A_5 = {4\xi \over \lambda + 3} = {2 W_{\Delta\Delta_P} \over 2W_T + W_L} \, , \, \, 
 \nonumber \\ 
    A_6 = {4\zeta \over \lambda + 3} = {2W_{\Delta_P} \over 2W_T + W_L}\, , \, \, &&\, \,
    A_7 = {4\chi \over \lambda + 3} = {4 c_G W_\nabla \over 2W_T + W_L}\, .
\end{eqnarray}
where we have used that 
\begin{eqnarray}
    {4 \over \lambda + 3}\left( 1 + \lambda \cos^2\theta \right) &=&
    {1 \over \lambda + 3}\left( 4+ (\lambda + 3\lambda)\cos^2\theta \right)\, ,
\nonumber \\ 
    {4 \over \lambda + 3}\left( 1 + \lambda \cos^2\theta \right) &=&
    {1 \over \lambda + 3}\left( 4 +\lambda - \lambda  + (\lambda + 3\lambda + 3 - 3)\cos^2\theta \right)\, ,
\nonumber \\ 
    \therefore {4 \over \lambda + 3}\left( 1 + \lambda \cos^2\theta \right) &=&
    1 + \cos^2\theta + {(1-\lambda)\over \lambda + 3}(1-3\cos^2\theta)\, .
\end{eqnarray}








