\section{Preliminaries} \label{section:preliminaries}
\subsection{Borel equivalence relations and Borel graphs} \label{ss:Borel} Let $X$ be a standard Borel space. An equivalence relation $E$ on $X$ is \emph{Borel} if $E \subseteq X^2$ is Borel.
The \emph{$E$-class} of a point $x \in X$ is denoted $[x]_E$.
A Borel equivalence relation is \emph{finite} (respectively \emph{countable}) if all its equivalence classes are finite (respectively countable), and it is \emph{hyperfinite} if it can be written as union of an increasing sequence of finite Borel equivalence relations. Finally,  countable Borel equivalence relation $E$ over $X$ is \emph{measure-hyperfinite} if, for every probability measure $\mu$ over $X$, there exists some Borel subset $A \subseteq X$, with $\mu(A) = 1$, such that the restriction of $E$ to $A$ is hyperfinite.


Let $X$ be a standard Borel space and let $\rho$ be a \emph{Borel extended metric} on $X$, that is a Borel metric $\rho \colon X \times X \to [0, \infty]$ that can also take value $\infty$. In this case, we call $(X, \rho)$ a \emph{Borel extended metric space}. For $A \subseteq X$ and $x \in X$, we define
\begin{equation*}
\rho(x,A)\coloneqq \inf_{y \in A} \rho(x,y).
\end{equation*}
For $r > 0$ and $x \in X$, we let $B_\rho(x, r)$ denote the closed ball of radius $r$ centered in $x$ with respect to $\rho$. A Borel extended metric space is \emph{proper} if $| B_\rho(x,r) |< \infty$ for all $x \in X$ and $r > 0$. %Similarly, for a set $A \subseteq X$, we define
%\begin{equation*}
%B_\rho(A,r) \coloneqq \{ x\in X : \rho(x, A) \le r \}.
%\end{equation*}
Denote by $E_\rho$ the Borel equivalence relation of finite distance $\rho$ between points in $X$, that is
\begin{equation*}
E_\rho \coloneqq \{ (x,y) \in X^2 : \rho(x,y) < \infty \}.
\end{equation*}
An equivalence relation $E$ on a Borel extended metric space $(X, \rho)$ is \emph{$\rho$-uniformly bounded} if there exists $r > 0$ such that
every $E$-class has $\rho$-diameter smaller than $r$.

Given a subset $R \subseteq X^2$, we let $R^{-1} \coloneqq \{ (x,y) \in X^2 : (y,x) \in R \}$ and we write $xRy$ as an abbreviation of $(x,y) \in R$, and $x \neg R y$ for $(x,y) \notin R$. A \emph{Borel graph} on $X$ is a graph $\cG \coloneqq (X, R)$ where $R$ is a Borel subset of $X^2$ that is \emph{symmetric}, that is $R = R^{-1}$, and \emph{irreflexive}, meaning that $x \neg R x$ for all $x \in R$. Two vertices $x,y \in X$ are \emph{$R$-adjacent}
if $xRy$. Given a vertex $x \in X$ and an edge $(y,z) \in R$, we say that they are \emph{$R$-adjacent} if either $x=y$ or $x =z$. In both cases, we might drop `$R$-' and simply write \emph{adjacent} if no confusion arises.

If $\cG$ is a Borel graph on $X$, let $\rho_\cG$ denote the Borel extended metric on $X$ induced by the path distance, and abbreviate $E_{\rho_\cG}$ as $E_\cG$.
In this case, the equivalence class $[x]_{E_\cG}$ of $x \in X$, which we abbreviate as $[x]_\cG$, is the connected component of $x$ in $\cG$.
%We abbreviate $B_{\rho_\cG}(x,r)$ as $B_{\cG}(x, r)$, and $B_{\rho_\cG}(A,r)$ as $B_{\cG}(A, r)$.

For a vertex $x \in X$, the \emph{degree} of $x$ is the value
\begin{equation*} 
\deg_\cG(x) \coloneqq |\{ y \in X : xRy\}|.
\end{equation*}
Vertices of degree 1 are called \emph{leaves} and the set of all leaves in $\cG$ is denoted $\leaves(\cG)$. The \emph{degree} of $\cG$ is
\begin{equation*}
\deg(\cG) \coloneqq \sup_{x \in X} \deg_\cG(x).
\end{equation*}
%We say that a Borel graph $\cG$ has \emph{finite degree} if $\deg(\cG) < \infty$.

A \emph{(Borel) graphing} of a Borel equivalence relation $E \subseteq X^2$ is a Borel graph $\cG$ on $X$ such that $E_\cG = E$. We say that $E$ is \emph{treeable} if there exists an acyclic graphing of $E$. The \emph{complete graphing} of $E$ is the Borel graph $(X, E \setminus \Delta(X))$, where $\Delta(X) = \{(x, x) \in X^2 : x \in X\}$ is the diagonal of $X^2$.

Finally, for a subset $Y \subseteq X$ and $R \subseteq X^2$, we write $R|_Y$ for the restriction $R \cap Y^2$, and for a graph $\cG \coloneqq (X, R)$, we write $\cG|_Y$ for the graph $(Y, R|_Y)$.

\subsection{Borel orientations and out-degree}

A \emph{Borel orientation} of $\cG= (X, R)$ is a Borel subset $\vv{R} \subseteq R$ such that $\vv{R} \cap \vv{R}^{-1} = \emptyset$ and $\vv{R} \cup \vv{R}^{-1} = R$. In other words, for every $xRy$, exactly one among
$x\vv{R}y$ and $y\vv{R}x$ holds. The \emph{out-degree} of a vertex $x \in X$ is the value
\begin{equation*} 
\degout(x) \coloneqq \abs{\left\{y \in X : x\vv{R} y\right\}}.
\end{equation*}
We also define the \emph{out-degree} of the pair $(X, \vv{R})$ as
\begin{equation*}
\Degout(X,\vv{R}) \coloneqq \sup_{x \in X}\degout(x). 
\end{equation*}

\begin{remark} \label{remark:degree_maps}
Let $\cG \coloneqq (X, R)$ be a Borel graph. Note that, in case $\deg(\cG) \in \bbN \cup \{\aleph_0\}$, a standard application of the Lusin--Novikov uniformization theorem (\cite[Theorem 18.10]{Kechris:CDST}) shows that the maps $\deg_\cG \colon X \to \bbN \cup \{\aleph_0\}$ and $\degout \colon X \to \bbN \cup \{\aleph_0\}$ are Borel. In particular, $\leaves(\cG) = (\deg_\cG)^{-1}(1)$ is a Borel subset of $X$.

We moreover point out that, given a constant $C > 0$, the set
\begin{equation*}
Y \coloneqq \{ x \in X : |[x]_\cG | > C \}
\end{equation*}
is Borel.
Indeed, if $\cG_0$ is the complete graphing of $E_\cG$, then $Y = (\deg_{\cG_0})^{-1}((C, \infty])$.
\end{remark}

\subsection{Borel asymptotic dimension}
We recall the definition of Borel asymptotic dimension from \cite{CJMST-D}.

\begin{definition}[{\cite[Definition 3.2]{CJMST-D}}]\label{def: asdim}
  Let $(X,\rho)$ be a Borel extended metric space such that $E_\rho$
    is countable. The \emph{Borel
    asymptotic dimension} of $(X, \rho$), denoted $\asdim(X,\rho)$, is the smallest $d \in \bbN$
    such that, for every $r > 0$, there exists a 
    $\rho$-uniformly bounded Borel equivalence relation $E$ on $X$ with the property that, for
    every $x \in X$, the ball $B_\rho(x,r)$ intersects at most $d+1$ classes of $E$,
    and it is $\infty$ if no such $d$ exists.
\end{definition}

Finite Borel asymptotic dimension will be one of the main tools for accessing hyperfiniteness in this paper. Finite Borel asymptotic dimension provides, moreover, a tame framework where certain instances of the Union Problem can be solved affirmatively. This is synthesized in a precise manner in \cite[Theorem 7.3]{CJMST-D}. The proposition below isolates a specific instance of this result, in the context of Borel graphs.

\begin{proposition}\label{prop:union}
Let $\cG_n \coloneqq (X, R_n)$ be Borel graphs such that $(X, \rho_{\cG_n})$ is proper and $R_n \subseteq R_{n+1}$, for all $n \in \bbN$. Suppose that $\asdim (X, \rho_{\cG_n}) < \infty$ for all $n \in \bbN$. Then $E \coloneqq \bigcup_{n \in \bbN} E_{\cG_n}$ is hyperfinite.
\end{proposition}
\begin{proof}
Since $R_n \subseteq R_{n+1}$, we have
\[
\rho_{\cG_{n+1}} \le \rho_{\cG_n}.
\]
The conclusion then directly follows from \cite[Theorem 7.3]{CJMST-D}.
\end{proof}

\subsection{Schreier graphs and orbit equivalence relations}
Let $G$ be a group, let $X$ be a standard Borel space, and let $G \curvearrowright X$ be an action. The \emph{orbit equivalence relation} $E_G^X$ on $X$ is defined as
\begin{equation*}
x E_G^X y \text{ if and only if there is }g \in G \text{ such that }gx = y.
\end{equation*}
The relation $E_G^X$ is countable if $G$ is countable, and it is Borel if $G \curvearrowright X$ is a {Borel action}.

If $S$ is a subset of $G$, the induced \emph{Schreier graph} $ \sch(X, S)$ on $X$ is defined by putting an edge between any distinct $x,y \in X$ such that there is $s \in S \cup S^{-1} \setminus \{ e \}$ with $sx = y$. If $S$ is a generating set for $G$ then $E_{\sch(X,S)} = E_G^X$.
We recall that if $G$ is the free group on two or more generators and the action $G \curvearrowright X$ is free, the Schreier graph associated to the canonical set of generators witnesses that $E_G^X$ is treeable.

\section{U-amenability and hyper-u-amenability}\label{section: u-amenability}
In this section we introduce \emph{u-amenability} and \emph{hyper-u-amenability} and provide some examples of equivalence relations with these properties.

\begin{definition} \label{def:uniform_amenability}
Let $(X,\rho)$ be a Borel extended metric space and let $E$ be a countable Borel equivalence relation on $X$.
We say that $E$ is \emph{u-amenable with respect to $\rho$} if  $E \subseteq E_\rho$ and if there are Borel maps
\begin{equation*}
\lambda_n \colon E \to \mathbb{R}_{\ge 0}, \quad n \in \bbN,
\end{equation*}
such that, with the convention $\lambda_{n,x}(\cdot) \coloneqq \lambda_n(x, \cdot)$,
\begin{enumerate}
\item $\lambda_{n,x} \in \ell^1([x]_{E})$ and $\| \lambda_{n,x} \|_1 = 1$ for every $n \in \bbN$ and $x \in X$,
\item \label{item2:ua} $\sup_{\{ (x,y) \in E  : \rho(x,y) < r \}} \| \lambda_{n,x} - \lambda_{n,y} \|_1 \to 0$ as $n \to \infty$, for every $r > 0$.
\end{enumerate}

A Borel graph $\cG$ is \emph{u-amenable} if $E_\cG$ is u-amenable with respect to $\rho_\cG$. 
\end{definition}
The prefix `u-' stands for \emph{uniform}, and emphasizes the difference between our definition and the more well-known \emph{1-amenability} -- or simply \emph{amenability} -- for a countable Borel equivalence relation $E$ introduced in \cite[Definition 2.12]{JKL}, which requires the existence of Borel functions $\lambda_n \colon E \to \mathbb{R}_{\ge 0}$ as in Definition \ref{def:uniform_amenability}, but where condition \eqref{item2:ua} above is replaced by a weaker and, so to speak, \emph{pointwise} condition, which is reported below.
\begin{definition}[{\cite[Definitions 2.11 and 2.12]{JKL}}] \label{def:amenability}
Let $X$ be a standard Borel space and let $E$ be a countable Borel equivalence relation on $X$.
We say that $E$ is \emph{1-amenable}, or simply \emph{amenable}, if there are Borel maps
\begin{equation*}
\lambda_n \colon E \to \mathbb{R}_{\ge 0}, \quad n \in \bbN,
\end{equation*}
such that, with the convention $\lambda_{n,x}(\cdot) \coloneqq \lambda_n(x, \cdot)$,
\begin{enumerate}
\item $\lambda_{n,x} \in \ell^1([x]_{E})$ and $\| \lambda_{n,x} \|_1 = 1$ for every $n \in \bbN$ and $x \in X$,
\item $\| \lambda_{n,x} - \lambda_{n,y} \|_1 \to 0$, as $n \to \infty$, whenever $xEy$.
\end{enumerate}
\end{definition}

The next lemma, which we isolate for later use, implies that u-amenability is preserved when taking sub-equivalence relations or subgraphs.
\begin{lemma}\label{lemma:subgraph_ua}
Let $X_0$ be a standard Borel space and let $E_0 \subseteq X_0^2$ be a countable Borel equivalence relation. Let $X_1 \subseteq X_0$ be a Borel set and let $\rho_1$ be an extended metric on $X_1$. Let finally $E_1 \subseteq E_0 \cap E_{\rho_1}$ be a countable Borel equivalence relation. Suppose that there are Borel maps
\begin{equation*}
\lambda_n \colon E_0 \to \bbR_{\ge 0}, \quad n \in \bbN,
\end{equation*}
such that $\lambda_{n,x} \in \ell^1([x]_{E_0})$, $\| \lambda_{n,x} \|_1 = 1$ and, for every $r > 0$,
\begin{equation}\label{eq:ua_Y}
\sup_{\{ (x,y) \in E_1  : \rho_1(x,y) < r \}} \| \lambda_{n,x} - \lambda_{n,y} \|_1 \to 0, \quad n \to \infty.
\end{equation}
Then $E_1$ is u-amenable with respect to $\rho_1$. In particular, if $\cG_0 \coloneqq (X_0, R_0)$ is a u-amenable Borel graph and $\cG_1 \coloneqq (X_1, R_1)$ is a Borel graph with $R_1 \subseteq R_0$, then $\cG_1$ is also u-amenable.
\end{lemma}

\begin{proof}
Use the Lusin--Novikov uniformization theorem (\cite[Theorem 18.10]{Kechris:CDST}) to find Borel functions $F_k \colon X \to X$, for $k\in \bbN$, such that $E_0 = \{(x,y) \in X^2 : \exists k \, (y = F_k(x)) \}$. Consider the following two Borel functions
\begin{equation*}
\begin{aligned}[c]
N \colon E_0 & \to \bbN  \\
(x,y) &\mapsto \min \{k : x E_1 F_k(y) \},
\end{aligned}
\qquad
\begin{aligned}[c]
P \colon E_0 &\to X \\
(x,y) &\mapsto F_{N(x,y)}(y).
\end{aligned}
\end{equation*}
%Both functions are Borel: for every $k \in \bbN$, the function $H_k\colon E_\cG \to \bbN \cup \{ \infty \}$ that is constantly $k$ on the preimage of $E_\cG$ via the Borel map $(x,y) \mapsto (x, F_k(y))$ and $\infty$ elsewhere is Borel, and since $N= \inf_{k \in \bbN} H_k$, we have that $N$ is Borel as well.
For every $n \in \bbN$, define finally the Borel functions
\begin{align*}
\lambda'_n \colon E_1 &\to \bbR_{\ge 0} \\
(x,y) & \mapsto   \sum_{\substack{z \in [x]_{E_0}, \\ P(x, z) = y }}\lambda_{n,x}(z). 
\end{align*}

The sequence $(\lambda'_n)_{n \in \bbN}$ witnesses that $E_1$ is u-amenable with respect to $\rho_1$.
Indeed, given $n\in \bbN$ and $x \in Y$, we have
\begin{equation*}
\| \lambda'_{n,x} \|_1 = \sum_{y \in [x]_{E_1}} \lambda'_{n,x}(y) = \sum_{y \in [x]_{E_1}}  \sum_{\substack{z \in [x]_{E_0}, \\ P(x, z) = y }}\lambda_n(x, z) = \sum_{y \in [x]_{E_0}} \lambda_{n,x}(y) = \| \lambda_{n,x} \|_1 = 1.
\end{equation*}

Finally, to verify that the sequence $(\lambda'_n)_{n \in \bbN}$ satisfies item \eqref{item2:ua} of Definition \ref{def:uniform_amenability}, note that if $xE_1y$ and $w \in [x]_{E_0}$ then $N(x, w) = N(y,w)$ by definition of $N$, hence $P(x,w) = P(y, w)$. This, in particular, implies that
\begin{equation} \label{eq:lambda_n}
 \sum_{\substack{w \in [x]_{{E_0}}, \\ P(x,w) = z}} \lambda_{n,x}(w) - \sum_{\substack{\bar w \in [y]_{{E_0}}, \\ P(y,\bar w) = z}} \lambda_{n,y} (\bar w) =
  \sum_{\substack{w \in [x]_{{E_0}}, \\ P(x,w) = z}} \lambda_{n,x}(w) - \lambda_{n,y}(w),
  \end{equation}
which in turn gives
\begin{align*}
\| \lambda'_{n,x} - \lambda'_{n,y} \|_1 & \stackrel{\mathclap{\eqref{eq:lambda_n}}}{\le} \sum_{z \in [x]_{E_1}}  \sum_{\substack{w \in [x]_{E_0}, \\ P(x,w) = z}} | \lambda_{n,x}(w) - \lambda_{n,y}(w)| \\
&= \sum_{z \in [x]_{E_0}} | \lambda_{n,x}(z) - \lambda_{n,y}(z)| \\
&= \| \lambda_{n,x} - \lambda_{n,y} \|_1
\end{align*}
Item \eqref{item2:ua} of Definition \ref{def:uniform_amenability} for $(\lambda'_n)_{n \in \bbN}$ hence follows by \eqref{eq:ua_Y}.
\end{proof}
%Note that an action of a countable group $G \curvearrowright X$ on a $\sigma$-compact Polish space is topologically amenable if and only if it is amenable in the sense of \cite[Definition 2.12]{DJK} (see \cite[Theorem A.3.1]{FKSV}). In particular, Proposition \ref{prop:topologically_amenable} also applies to continuous actions that are amenable in the following sense.
\begin{definition} \label{def:hyper-u-amenable}
Let $X$ be a standard Borel space. A countable Borel equivalence relation $E$ on $X$ is \emph{hyper-u-amenable} if it admits a graphing $\cG \coloneqq (X, R)$ which is an increasing union of Borel u-amenable graphs on $X$, in the sense that, for $n \in \bbN$, there are u-amenable Borel graphs $\cG_n \coloneqq (X, R_n)$ such that $R_n \subseteq R_{n+1}$ and $R = \bigcup_{n \in \bbN} R_n$.
\end{definition}

The definition of hyper-u-amenability appears to rely on the existence of a special graphing of $E$. We show however, in the next proposition, that if $E$ has a graphing which is increasing union of u-amenable graphs, then all graphings of $E$ have this property. We moreover prove that the u-amenable graphs can always be assumed to have finite degree.

\begin{proposition}\label{prop: increasing union graphings}
Let $X$ be a standard Borel space and let $E \subseteq X^2$ be a countable Borel equivalence relation. Suppose that $E$ is hyper-u-amenable and let $\cG$ be \emph{any} graphing of $E$. Then $\cG$ is increasing union of u-amenable Borel graphs of finite degree.
\end{proposition}

\begin{proof}
Let $\cH \coloneqq (X, S)$ be a graphing witnessing u-amenability of $E$. There exist therefore, for $n \in \bbN$, u-amenable Borel graphs  $\cH_n \coloneqq (X, S_n)$ such that
\[
S = \bigcup_{n=1}^\infty S_n, \quad S_n \subseteq S_{n+1}, \quad n \in \bbN.
\]

Without loss of generality, we may assume that each $\cH_n$ has finite degree. To see this, note that by \cite{FM} there is a countable group $G$, enumerated as $\{ g_n \} _{ n\in \bbN}$, and a Borel action $G \curvearrowright X$ such that $E = E_G^X$. Denote by $T_n$ the edge relation of the Schreier graph $\sch(X, \{ g_0, \dots, g_{n} \})$. Given $n \in \bbN$, the graph $\cH'_n \coloneqq (X, S_n \cap T_n)$ has finite degree since $\sch(X, \{ g_0, \dots, g_{n} \})$ does, it is u-amenable by Lemma \ref{lemma:subgraph_ua} since $\cH_n$ is, and we moreover have both $S_n \cap T_n \subseteq S_{n+1} \cap T_{n+1}$ and $S = \bigcup_{n \in \bbN} (S_n \cap T_n)$.

Suppose next that $\cG \coloneqq (X, R)$ is another graphing of $E$, define 
\[
R_n  \coloneqq \{(x, y) \in R : \rho_{\cH_n}(x, y) \le n\}, \quad n \in \bbN,
\]
and set $\cG_n \coloneqq (X, R_n)$. We show that $\cG$ is increasing union of the $\cG_n$'s, and that these are u-amenable and with finite degree.

The inclusion $R_n \subseteq R_{n+1}$ follows since
\begin{equation}\label{eq: distance G_n}
\rho_{\cH_{n+1}} \le \rho_{\cH_n}.
\end{equation}
Since $E = E_\cG = E_\cH$, for every edge $xRy$ there is a sufficiently large $n$ such that $xE_{\cH_n}y$, that is, $\rho_{\cH_n}(x, y) < \infty$. By \eqref{eq: distance G_n}, it then follows that $x R_m y$ with $m = \max\{ n, \rho_{\cH_n}(x, y) \}$, and thus $R = \bigcup_{n \in \bbN} R_n$.
Moreover, the inequality
\begin{equation}\label{eq: distance R_n}
\rho_{\cG_n} \ge \frac{1}{n}\rho_{\cH_n}.
\end{equation}
implies $\deg(\cG_n) \le \deg(\cH_n)^n < \infty$. Finally, \eqref{eq: distance R_n} and Lemma \ref{lemma:subgraph_ua}, applied to  $E_{\cH_n}$ and $E_{\cG_n}$,
imply that the graphs $\cG_n$ are u-amenable.
\end{proof}

\subsection{Examples} 
\subsubsection{Topologically amenable actions}
The first class of u-amenable equivalence relations that we consider comes from continuous, \emph{topologically amenable} actions of finitely generated groups on compact spaces, of which we briefly recall the definition.
\begin{definition}
Let $G$ be a countable group and $X$ a Polish space. A continuous action $G \curvearrowright X$ is \emph{topologically amenable} if for every compact subset $K \subseteq X$ there are continuous maps
\begin{equation*}
p_n \colon X \times G \to \bbR_{\ge 0}, \quad n \in \bbN,
\end{equation*}
such that, with the convention $p_{n,x}(\cdot) \coloneqq p_n(x, \cdot)$,
\begin{enumerate}
\item $p_{n,x} \in \ell^1(G)$ and $\| p_{n,x} \|_1 = 1$ for every $n \in \bbN$ and $x\in X$,
\item $\sup_{x \in K} \| g\cdot p_{n,x} - p_{n,gx} \|_1 \to 0$ as $n \to \infty$, for every $g \in G$, and where $g \cdot p_{n,x}(h) = p_{n,x}(g^{-1}h)$.
\end{enumerate}
\end{definition}

\begin{proposition} \label{prop:topologically_amenable}
Let $G$ be a countable group and $X$ a Polish space. Suppose that $G \curvearrowright X$ is a continuous, topologically amenable action, let $K \subseteq X$ be a compact set, and let $S \subseteq G$ be finite. Then the graph $\sch(X, S)|_K$ is u-amenable.
\end{proposition}
\begin{proof}
Let $(p_n)_{n \in \bbN}$ is a sequence of maps witnessing topological amenability of $G \curvearrowright X$ for $K \subseteq X$, and define the Borel maps
\begin{align*}
\lambda_n \colon E_G^X &\to \bbR_{\ge 0} \\
(x,y) &\mapsto \sum_{\substack{g \in G \\ g^{-1}x = y}} p_{n,x}(g).
\end{align*}
Then the sequence $\lambda_n$ satisfies the assumption of Lemma \ref{lemma:subgraph_ua} with $E_0 = E_G^X$, $E_1 = E_{\sch(X, S)|_K}$ and $\rho_1 = \rho_{\sch(X, S)|_K}$, hence the graph $\sch(X, S)|_K$ is u-amenable.
\end{proof}

We report a result from \cite[Appendix A]{FKSV} which, when combined with the Connes--Feldman--Weiss theorem, relates topological amenability to measure-hyperfiniteness of $E_G^X$ in the case of continuous actions on Polish spaces. 

\begin{theorem}[{\cite{CFW},\cite[Appendix A]{FKSV}}] \label{theorem:appendix}
Let $G \curvearrowright X$ be a continuous action of a countable group on a Polish space. The following are equivalent:
\begin{enumerate}
\item $G \curvearrowright X$ is topologically amenable,
\item $E_G^X$ is measure-hyperfinite and every stabilizer is amenable.
\end{enumerate}
\end{theorem}

We use the equivalence above to prove the following corollary of Proposition \ref{prop:topologically_amenable}.

\begin{corollary}\label{cor: continuous action}
Let $G \curvearrowright X$ be a continuous action of a countable group on a $\sigma$-compact Polish space. If the stabilizer of every point is amenable and $E_G^X$ is measure-hyperfinite, then $E_G^X$ is hyper-u-amenable.  In particular,  $E_G^X$ is hyper-u-amenable whenever $E_G^X$ is measure-hyperfinite (e.g. if $E_G^X$ is amenable) and the action is free.
\end{corollary}

\begin{proof}
By Theorem \ref{theorem:appendix}, the action $G \curvearrowright X$ is topologically amenable. Since $X$ is $\sigma$-compact, there is an increasing sequence of compact sets $K_n$ such that $X = \bigcup_{n \in \bbN} K_n$. Let $\{ g_n \}_{n \in \bbN}$ be an enumeration of $G$ and define
\[
\cG_n \coloneqq \sch(X, \{g_0, \ldots, g_n\})|_{K_n}, \quad n \in \bbN.
\]
Each $\cG_n$ is u-amenable by Proposition \ref{prop:topologically_amenable}, and since the sequence $(\cG_n)_{n \in \bbN}$ is increasing and its union is the complete graphing of $E_G^X$, it follows that $E_G^X$ is hyper-u-amenable.
\end{proof}

\subsubsection{Actions of amenable groups}
\begin{proposition} \label{prop:group_action}
Let $G$ be a countable amenable group, let $X$ be a standard Borel space and let $G \curvearrowright X$ be a Borel action. Then $E_G^X$ is hyper-u-amenable. 
\end{proposition}

\begin{proof}
Let $\{ g_n \}_{n \in \bbN}$ be an enumeration of $G$ and let $\cG \coloneqq (X, E_G^X \setminus \Delta(X))$ be the complete graphing of $E$. For every $m\in \bbN$ consider the subgroup $G_m \coloneqq \langle g_0, \dots, g_m \rangle$ and the corresponding Schreier graph $\cG_m \coloneqq \sch(X, \{g_0, \ldots, g_m\})$. Denote the edge relation on $\cG_m$ as $R_m$. Note that the graphs $\cG_m$ have finite degree, that $R_m \subseteq R_{m+1}$ for all $m \in \bbN$, and that $E_G^X \setminus \Delta(X) = \bigcup_{m \in \bbN} R_m$. To see that $E_G^X$ is hyper-u-amenable, it remains to show that all $\cG_m$'s are u-amenable.

To do this, fix $m \in \bbN$, and let $(F_{n})_{n \in \bbN}$ be a F{\o}lner sequence for the subgroup $G_m$. U-amenability of $\cG_m$ is then witnessed by the family $(\lambda_n)_{n \in \bbN}$ of Borel functions defined as \begin{align*}
\lambda_n \colon E_{\cG_m} &\to \bbR_{\ge 0} \\
(x,y) &\mapsto \frac{1}{|F_n|} \abs{ \{ g \in F_n : gx = y \}}.
\end{align*}
\end{proof}

We remark that the proof above actually shows that if $G$ is a finitely generated amenable group and $S$ is some finite generating set, then the Schreier graph $\sch(X, S)$ is u-amenable.


\subsubsection{Borel bounded equivalence relations} The last class of examples of hyper-u-amenable equivalence relations that we provide is that of amenable Borel bounded equivalence relations, of which we recall the definition below. For $f , g \in \bbN^\bbN$, we write $f=^\ast g$ (and $f \le ^\ast g$) if $f(n) = g(n)$ (respectively $f(n) \le g(n)$) for all but finitely many $n \in \bbN$. 
\begin{definition}[{\cite{BJ}}]
Let $X$ be a standard Borel space. A countable Borel equivalence relation $E \subseteq X^2$ is \emph{Borel bounded}, if for every Borel function $\phi \colon X \to \bbN^\bbN$, there is a function $\psi \colon X \to \bbN^\bbN$ such that $\phi(x) \le^* \psi(x)$ for all $x \in X$, and that $\psi(x) =^*\psi(y)$ whenever $xEy$.
\end{definition}

Hyperfinite equivalence relations are Borel bounded (\cite{BJ}) and, remarkably, it is not known whether \emph{every} countable Borel equivalence relation is Borel bounded, although Thomas proved in \cite[Theorem 5.2]{thomas} that equivalence relations that are not Borel bounded exist, if Martin's conjecture on degree invariant Borel maps holds.

\begin{proposition}\label{prop: Borel bounded}
Let $X$ be a standard Borel space and let $E \subseteq X^2$ be an amenable, Borel bounded, countable Borel equivalence relation. Then $E$ is hyper-u-amenable. 
\end{proposition}

\begin{proof}
Let $\lambda_n \colon E \to \bbR_{\ge 0}$ be a sequence of Borel functions witnessing amenability of $E$, so in particular $\lambda_{n,x} \in \ell^1([x]_{E})$ and $\| \lambda_{n,x} \|_1 = 1$ for every $n \in \bbN$ and $x \in X$, and
\[
\| \lambda_{n,x} - \lambda_{n,y} \|_1 \to 0, \quad n \to \infty,  \text{ whenever }xEy.
\]

Fix a graphing $\cG \coloneqq (X, R)$ of $E$ and let $G$ be a countable group, enumerated as $\{ g_n \}_{n\in \bbN}$, along with a Borel action $G \curvearrowright X$ such that $E = E_G^X$ (\cite{FM}). Define the Borel function $\phi \colon X \to \bbN^ \bbN$ as
\[
\phi(x)(n) \coloneqq \min\left\{m \in \bbN : \forall j \ge m, \, \forall  i \le n \text{ if }  (x, g_i x) \in R  \text{ then }  \|\lambda_{j, x} - \lambda_{j, g_i x}\|_1 < 1/n \right\}.
\]
By Borel boundedness there exists a Borel map $\psi : X \to \bbN^\bbN$ such that $\psi(x) =^* \psi(y)$ if $x E y$, and that $\phi(x) \le^* \psi(x)$ for all $x \in X$. 

For $k \in \mathbb{N}$, define a graph $\cG_k \coloneqq (X, R_k)$ by setting $x R_k y$ if $xRy$ and
\begin{enumerate}[label=(\alph*)]
\item $y = g_ix$ and $x = g_jy$, for some $i, j \le k$,
\item $\psi(x)(n) = \psi(y)(n)$, for all $n \ge k$,
\item $\max \{\phi(x)(n), \phi(y)(n)\} \le \psi(x)(n)$, for all $n \ge k$.
\end{enumerate}

It is clear that $R_k \subseteq R_{k+1}$ for all $k \in \bbN$ and that $R = \bigcup_{k \in \bbN} R_k$. It remains to show that each subgraph $\cG_k$ is u-amenable. To do so, given $n \in \mathbb{N}$ and $x \in X$, define  $\lambda^\prime_{n, x} \coloneqq \lambda_{\psi(x)(n), x}$. 
We claim that this sequence witnesses u-amenability of $\cG_k$, for any $k\in \bbN$. Indeed, note that if $x R_k y$ and $n \ge k$, then $\psi(x)(n) = \psi(y)(n)$ and $\phi(x)(n) \le \psi(x)(n)$, hence
\[
\|\lambda^\prime_{n, x} - \lambda^\prime_{n, y}\|_1 = \|\lambda_{\psi(x)(n), x} - \lambda_{\psi(x)(n), y}\|_1 < \frac1n.
\]
By triangular inequality we thus get that 
\[
 \|\lambda^\prime_{n, x} - \lambda^\prime_{n, y}\|_1 \le \frac{r}{n}, \quad n \ge k, \, x, y \in X \text{ s.t. } \rho_{\cG_k}(x,y) \le r,
 \]
 and therefore $\sup_{\{ (x,y) \in E_{\cG_k}  : \rho_{\cG_k}(x,y) < r \}} \| \lambda'_{n,x} - \lambda'_{n,y} \|_1 \to 0$ as $n \to \infty$, for every $r > 0$.
\end{proof}

\section{Graphs with partial orientations} \label{section:partial_orientations}
Given a Borel graph $\cG \coloneqq (X, R)$ with finite degree, in this section we provide technical conditions sufficient to deduce $\asdim(X, \rho_\cG) < \infty$.

This is done gradually: we first consider the case where there is a Borel orientation $\vv{R} \subseteq R$ with  $\Degout(X, \vv{R}) \le 1$, in which case a direct application of some results in \cite{CJMST-D} implies that $\asdim (X,\rho_\cG) \le 1$ (Proposition \ref{prop:oriented}). We then relax our assumptions and show that $\asdim(X, \rho_\cG) \le 3$ if $R$ admits partial Borel orientations such that the non-oriented edges can be chosen to be arbitrarily far away from each other (Lemma \ref{lemma:delete_edges}).

Finally, in Lemma \ref{lemma:quasi-oriented} we relax even further our assumptions and prove the main technical result of the paper: $\asdim(X, \rho_\cG) \le 3$ holds if $R$ can be partitioned in two sets, $R_0 \sqcup R_1$, such that $R_0$ admits a Borel orientation with out-degree at most 1 and $\cG_1 \coloneqq (X, R_1)$ is an acyclic Borel graph with $\deg(\cG_1) \le 2$ verifying a series of other conditions. The resulting criterion will be essential to deduce finite Borel asymptotic dimension for treeable u-amenable equivalence relations in Theorem \ref{thm:ua_asdim}.

\subsection{Orientation with out-degree at most 1} In this subsection we focus on graphs where a Borel orientation, or a partial, yet rather large, Borel orientation, exists.

\begin{proposition} \label{prop:oriented}
Let $\cG \coloneqq (X, R)$ be a Borel graph with $\deg(\cG) < \infty$. Suppose that there exists a Borel orientation $\vv{R} \subseteq R$ such that $\Degout(X, \vv{R}) \le 1$. Then $\asdim (X,\rho_\cG) \le 1$.
\end{proposition}

\begin{proof}
Since $\vv{R}$ has out-degree at most one, the following bounded-to-one Borel function $f : X \to X$ is well-defined:
\begin{equation*}
f(x) \coloneqq 
\begin{cases}
    y & \text{if} \ x\vv{R}y, \\
    x & \text{otherwise}.
\end{cases}
\end{equation*}
Since $\vv{R} \cup \vv{R}^{-1} = R$, we see that the Borel set
\begin{equation*}
R_f \coloneqq \{(x, y) \in X^2 : x \ne y \text{ and either } f(x) = y \ \text{or} \ f(y) = x\}
\end{equation*}
is equal to $R$. This means that the Borel graph $\cG_f \coloneqq (X, R_f)$ is equal to $\cG$, hence $\asdim (X,\rho_\cG) \le 1$ by \cite[Corollary 8.3]{CJMST-D}.
\end{proof}

\begin{lemma}\label{lemma:delete_edges}
Let $\cG \coloneqq (X, R)$ be a Borel graph with $\deg(\cG) < \infty$. Suppose that for each $r > 0$ there is a symmetric Borel subset $Q \subseteq R$ such that
\begin{enumerate}
    \item \label{item1:delete_edges} $\rho_\cG(x_0, x_1) > r$ whenever $x_0, x_1 \in X$ and there are two distinct $q_0, q_1 \in Q$ such that $x_i$ is adjacent to $q_i$, for $i = 0,1$,
    \item \label{item2:delete_edges} the graph $\cG_0 \coloneqq (X, R \setminus Q)$ admits a Borel orientation with out-degree at most 1.
\end{enumerate}
Then $\asdim (X,\rho_\cG) \le 3$.
\end{lemma}

\begin{proof}
Fix $r > 0$. We aim to build a $\rho_\cG$-uniformly bounded Borel equivalence relation $E \subseteq E_\cG$ such that $B_{\rho_\cG}(x, r)$ intersects at most four $E$-classes, for every $x \in X$. To do so, let $Q \subseteq R$ be satisfying the assumptions of the lemma for $2r$, so in particular, given $x_0, x_1 \in X$
\begin{equation} \label{eq:2r}
\text{ $\rho_\cG(x_0, x_1) > 2r$ if there are $q_0, q_1 \in Q$, $q_0 \ne q_1$ and $x_i$ is adjacent to $q_i$, for $i = 0,1$.} \tag{1'}
\end{equation}

Consider $\cG_0 \coloneqq (X, R \setminus Q)$. By \eqref{item2:delete_edges} and Proposition \ref{prop:oriented} we have $\asdim (X,\rho_{\cG_0}) \le 1$, which means that there is a $\rho_{\cG_0}$-uniformly bounded (and thus $\rho_\cG$-uniformly bounded) Borel equivalence relation $E$ such that for every $x \in X$ the ball $B_{\rho_{\cG_0}}(x, 2r)$ intersects at most two distinct $E$-classes. We claim that, for every $x \in X$, the ball $B_{\rho_\cG}(x, r)$ intersects at most 4 $E$-classes.

To see this, let $Y \subseteq X$ be the set of all vertices that are adjacent to some edge in $Q$. Fix $x \in X$. If $B_{\rho_{\cG}}(x, r) \cap Y = \emptyset$, then 
\begin{equation*}
B_{\rho_{\cG}}(x, r) = B_{\rho_{\cG_0}}(x, r) \subseteq B_{\rho_{\cG_0}}(x, 2r)
\end{equation*}
and thus $B_{\rho_{\cG}}(x, r)$ intersects at most two $E$-classes.

Suppose next that $B_{\rho_{\cG}}(x, r) \cap Y \ne \emptyset$. Then by \eqref{eq:2r} there is  (up to symmetry) a unique edge $ (y, z) \in Q$ such that at least one among $y$ and $z$ belongs to  $B_{\rho_{\cG}}(x, r)$. Without loss of generality, we may assume $y \in B_{\rho_{\cG}}(x, r)$. In this case, again by \eqref{eq:2r}, we have 
\[
B_{\rho_{\cG}}(x, r) \subseteq B_{\rho_{\cG}}(y, 2r) \subseteq B_{\rho_{\cG_0}}(y, 2r) \cup B_{\rho_{\cG_0}}(z, 2r).
\]
We deduce that $B_{\rho_{\cG}}(x, r)$ intersects at most 4 different $E$-classes.
\end{proof}

\subsection{Acyclic graphs with degree at most 2}
If $\cG \coloneqq (X, R)$ is an acyclic Borel graph with $\deg(\cG) \le 2$, then it is always possible to remove a very sparse set of edges so that the resulting graph has connected components whose size is uniformly bounded by a given constant. In Lemma \ref{lemma:choose_edges} we prove that this can be done while also ensuring that the set of removed edges is Borel and far away from leaves.

\begin{remark}
 Let $\cG\coloneqq (X, R)$ be an acyclic Borel graph with $\deg(\cG) \le 2$. Then each non-trivial connected component $[x]_\cG$ of $\cG$ is isomorphic to one of the following graphs, depending on the number of leaves it has:
\begin{enumerate}[label=(\roman*)]
\item \label{item:Z} if $|\leaves([x]_\cG)| = 0$ then $[x]_\cG \cong (\bbZ, S_\bbZ \cup S_\bbZ^{-1})$, where $S_\bbZ \coloneqq \{(k, k+1) : k \in \bbZ\}$,
\item \label{item:N}  if $|\leaves([x]_\cG)| = 1$ then $[x]_\cG \cong (\bbN, S_\bbN \cup S_\bbN^{-1})$, where $S_\bbN \coloneqq \{(k, k+1) : k \in \bbN\}$.
\item \label{item:n} if $|\leaves([x]_\cG)| = 2$ then there is $n \in \bbN$ such that $[x]_\cG \cong (\{1 ,\dots, n \}, S_n \cup S_n^{-1})$, where $S_n \coloneqq \{ (k, k+1) : k < n \}$.
\end{enumerate}
We will implicitly use this fact in the next proofs.
\end{remark}

\begin{lemma}\label{lemma:choose_edges}
Let $\cG \coloneqq (X, R)$ be an acyclic Borel graph with $\deg(\cG) \le 2$. Fix $r > 0$ and let
\[
Y \coloneqq \{x \in X \colon \abs{[x]_\cG} > 4r +6\}.
\]
Then there is a symmetric Borel set $Q \subseteq R|_Y$ such that
\begin{enumerate}
    \item \label{item1:choose_edges}  $\rho_\cG(x_0, x_1) > r$ whenever $x_0, x_1 \in X$ and there are two distinct $q_0, q_1 \in Q$ such that $x_i$ is adjacent to $q_i$, for $i = 0,1$,
        \item \label{item2:choose_edges} $\rho_\cG(x,y) \ge r$ whenever $x \in X$ is adjacent to an edge in $Q$, and $y \in \leaves(\cG)$,
    \item \label{item3:choose_edges} $\abs{[x]_{\cG_0}} \le 4r + 6$, with $\cG_0 \coloneqq (X, R \setminus Q)$, for any $x \in X$.
\end{enumerate}
\end{lemma}

\begin{proof}
Note that $Y$ is Borel by Remark \ref{remark:degree_maps}. We can therefore define a Borel graph $(R|_Y, S)$ as follows: given two distinct $q_0, q_1 \in R|_Y$, we write $q_0 S q_1$ if there are vertices $x_0, x_1 \in Y$ such that $x_i$ is $R$-adjacent to $q_i$ for $i= 0,1$ and $\rho_\cG(x_0, x_1) \le r$. The graph $(R|_Y, S)$ has finite degree since $\cG$ does, hence by \cite[Propositions 4.2 and 4.3]{KST} there exists a maximal \emph{$S$-independent} Borel set $Q_0 \subseteq R|_Y$, that is
\begin{equation} \label{eq:S-indep}
q_0 \neg S q_1 \text{ for all } q_0, q_1 \in Q_0 \text{ and every } q \in R|_Y \text{ is $S$-adjacent to some element of $Q_0$}.
\end{equation}

Consider next the Borel set
\begin{equation*}
Q \coloneqq \{ (x,y) \in Q_0 \cup Q_0^{-1} : \min \{ \rho_\cG(x, \leaves(\cG)), \rho_\cG(y, \leaves(\cG)) \} \ge r \}.
\end{equation*}
We have that $Q$ satisfies condition \eqref{item1:choose_edges} by \eqref{eq:S-indep}, and \eqref{item2:choose_edges} by definition. We verify \eqref{item3:choose_edges} for $x \in Y$, since the conclusion is automatic for $x \in X \setminus Y$.

Set $\cG_0 \coloneqq (X, R \setminus Q)$.  Note first that, by construction, we have $|[x ]_{\cG_0}| < \infty$, hence the latter (if non-trivial) is a finite graph of degree at most 2 with two leaves, say $x_0$ and $x_1$. We moreover point out that $\rho_\cG(y, z) = \rho_{\cG_0}(y,z)$ for every $y,z \in [x]_{\cG_0}$, as $\cG$ is acyclic.

Since $\deg(\cG) \le 2$, for every $y \in [x]_{\cG_0} \setminus \{x_0, x_1\}$, the only two vertices in $\cG$ that are $R$-adjacent  to $y$ are necessarily in $[x]_{\cG_0}$. This implies
\begin{equation} \label{eq:distance}
\rho_\cG(y,z) = \min \{ \rho_\cG(y,x_0) + \rho_\cG(x_0,z),  \rho_\cG(y,x_1) + \rho_\cG(x_1,z) \}, \quad y \in [x]_{\cG_0}, \, z \notin [x]_{\cG_0}.
\end{equation}

There are thus two cases: the first one is that $[x]_{\cG_0}$ contains no edge from $Q_0$. In this case, by \eqref{eq:S-indep} and \eqref{eq:distance}, we necessarily have that each $y \in [x]_{\cG_0}$ has distance at most $r$ from either $x_0$ or $x_1$, and therefore
\begin{equation*}
|[x]_{\cG_0}| \le \rho_{\cG_0}(x_0, x_1) + 1 \le 2r +2.
\end{equation*}

On the other hand, suppose that some edges in $Q_0 \setminus Q$ occur in $[x]_{\cG_0}$. This can only happen if at least one among $x_0$ and $x_1$ belongs to $\leaves(\cG)$. Note that there can be at most two edges  in $Q_0 \setminus Q$ appearing in $[x]_{\cG_0}$, as a third one would necessarily belong to $Q$ by construction. By \eqref{eq:S-indep}, all possible scenarios are in the pictures below.
