\subsection{Main criterion}
\begin{lemma} \label{lemma:quasi-oriented}
Let $\cG \coloneqq (X, R)$ be a Borel graph with $\deg(\cG) < \infty$. Suppose that for every $r > 0$ there exist two Borel  graphs $\cG_0 \coloneqq (X, R_0)$ and $\cG_1 \coloneqq (X, R_1)$ such that
\begin{enumerate}[label=(C.\arabic*)]
\item \label{quasi-oriented:item1} $R = R_0 \sqcup R_1$,
\item \label{quasi-oriented:item2} $\cG_0$ admits a Borel orientation $\vv{R}_0 \subseteq R_0$ with out-degree at most 1,
\item \label{quasi-oriented:item3} $\deg_{\cG_1}(x) + \degoutz(x) \le 2$ for all $x \in X$,
\item \label{quasi-oriented:item4} $\cG_1$ is acyclic,
\item \label{quasi-oriented:item5} if $1 < |[x]_{\cG_1}| < \infty$ and $\degoutz(y) = 1$ for every $y \in \leaves(\cG_1 \cap [x]_{\cG_1})$, then $ |[x]_{\cG_1}| > r$.
\end{enumerate}
Then $\asdim(X, \rho_\cG) \le 3$.
\end{lemma}

\begin{proof}
We aim to apply Lemma \ref{lemma:delete_edges} to $\cG$. In order to do so, fix $r > 0$ and find Borel graphs  $\cG_0 \coloneqq (X, R_0)$ and $\cG_1 \coloneqq (X, R_1)$ satisfying the assumptions of the present lemma for the value $4r+6$. In particular, $\cG_0$ and $\cG_1$ satisfy \ref{quasi-oriented:item1}-\ref{quasi-oriented:item4} and
\begin{equation} \label{eq:5a}
 |[x]_{\cG_1}| > 4r +6, \text{ if } 1 < |[x]_{\cG_1}| < \infty \text{ and } \degoutz(y) = 1, \, \forall y \in \leaves(\cG_1 \cap [x]_{\cG_1}). \tag{C.5'}
 \end{equation}


Condition \ref{quasi-oriented:item3} entails $\deg(\cG_1) \le 2$, hence we can apply Lemma \ref{lemma:choose_edges} to find a symmetric Borel subset $Q \subseteq R_1$ such that
\begin{enumerate}[label=(\roman*)]
    \item \label{item1:reflemma} $\rho_{\cG_1}(x_0, x_1) > r$ whenever $x_0, x_1 \in X$ and there are two distinct $q_0, q_1 \in Q$ such that $x_i$ is adjacent to $q_i$, for $i = 0,1$,
    \item \label{item2:reflemma} $\rho_{\cG_1}(x,y) \ge r$ whenever $x \in X$ is $R_1$-adjacent to an edge in $Q$, and $y \in \leaves(\cG_1)$,
    \item \label{item3:reflemma} $\abs{[x]_{(X, R_1 \setminus Q)}} \le 4r+6$ for any $x \in X$.
\end{enumerate}

Define $\cG_2 \coloneqq( X, R_1 \setminus Q)$. We show now how to construct a Borel orientation $\vv{R}_2$ on $\cG_2$ such that $\vv{R}_0 \cup \vv{R}_2$ is a Borel orientation of $(X, R \setminus Q)$ with out-degree at most 1. In order to define such $\vv{R}_2$, consider the Borel sets (see Remark \ref{remark:degree_maps})
\begin{align*}
Y_0 &\coloneqq \left\{ x \in X : |[x]_{\cG_2} | > 1 \text{ and there is } y \in [x]_{\cG_2} \text{ such that}\, \degoutz(y) =1 \right\}, \\
Y_1 &\coloneqq \left\{ x \in X : |[x]_{\cG_2} | > 1 \right\} \setminus Y_0.
\end{align*}
%A standard application of the Lusin--Novikov uniformization theorem (\cite[Theorem 18.10]{Kechris:CDST}) shows that $Y$ and $Z$ are Borel. Indeed, if $F_n \colon X \to X$, for $n \in \bbN$, are Borel functions such that
%\begin{equation*}
%[x]_\cG = \{F_n(x) : n \in \bbN\},
%\end{equation*}
%then
%\begin{equation*}
%x \in Y_0 \Leftrightarrow \exists n,m \text{ such that } (x , F_n(x)) \in R_1 \setminus Q, \, (x, F_m(x)) \in E_{\cG_2} , \, \degoutz(F_m(x)) = 1,
%\end{equation*}
%\begin{equation*}
%x \in Y_1 \Leftrightarrow x \notin Y_0 \text{ and } \exists n \text{ such that } (x , F_n(x)) \in R_1 \setminus Q.
%\end{equation*}
%It then follows by Remark \ref{remark:degree_maps} that $Y_0$, and thus $Y_1$, are Borel.

Condition \ref{quasi-oriented:item3} implies that if $x \in Y_0$ and $y \in [x]_{\cG_1}$ has $\degoutz(y) = 1$, then $y\in \leaves(\cG_1)$. If there were two distinct leaves $y_0,y_1\in [x]_{\cG_1}$ with $\degoutz(y_i) = 1$, for $i = 0,1$, then by \eqref{eq:5a} we would get $|[x]_{\cG_1}| > 4r +6$. This fact, combined with  \ref{item3:reflemma}, is sufficient to deduce that, for every $x \in X$, there exists at most one vertex $y \in [x]_{\cG_2}$ with $\degoutz(y) = 1$. In other words, if $A_0 \coloneqq (\degoutz)^{-1}(1) \cap Y_0$, then $|A_0 \cap [x]_{\cG_2}| = 1$ for every $x \in Y_0$.

On other hand, since $E_{\cG_2}$ is a finite equivalence relation by \ref{item3:reflemma}, and since finite Borel equivlence relations admit Borel selectors whose image is Borel (see \cite[Theorem 12.16 and Exercise 18.14]{Kechris:CDST}), there exists a Borel set $A_1 \subseteq Y_1$ such that $|A_1 \cap [x]_{\cG_2}| = 1$ for every $x\in Y_1$.

Set $A \coloneqq A_0 \cup A_1$. Since $\deg(\cG_2) \le 2$, the following is a well-defined orientation on $\cG_2$
\begin{equation*}
(x,y) \in \vv{R}_2 \Leftrightarrow \rho_{\cG_2}(y, A) < \rho_{\cG_2}(x, A).
\end{equation*}
By construction $\vv{R}_0 \cup \vv{R}_2$ is a Borel orientation of $(X, R \setminus Q)$ with out-degree at most 1.

In order to apply Lemma \ref{lemma:delete_edges} and conclude the proof, it suffices to show that if $(x_0, y_0), (x_1, y_1) \in Q$ are such that $x_0 \ne x_1$ and $x_0 \ne y_1$, then $\rho_\cG(x_0, x_1) > r$. Without loss of generality, we may assume that the shortest path in $\cG$ connecting $x_0$ to $x_1$ only has edges in $R \setminus Q$ (note that the shortest path connecting $x_0$ to $x_1$ cannot be composed exclusively of edges in $Q$ by \ref{item1:reflemma}, unless $r < 1$, in which case $\rho_\cG(x_0, x_1) > r$ is automatic). Arguing as in  Proposition \ref{prop:oriented}, one sees that the Borel function $f \colon X \to X$
\begin{equation*}
f(x) \coloneqq
\begin{cases}
    y & \text{if } (x,y) \in \vv{R}_0 \sqcup \vv{R}_2, \\
    x & \text{otherwise},
\end{cases}
\end{equation*}
is well-defined. Since $x_0, x_1$, as well as the shortest path connecting them, are in the same connected component of $(X,R \setminus Q)$, and since $\vv{R}_0 \sqcup \vv{R}_2$ has out-degree at most 1, it is possible to prove by induction on $\rho_\cG(x_0,x_1)$ that
\begin{equation} \label{eq:geodesic}
\rho_\cG(x_0, x_1) = \min \{ n+m : f^n(x_0) = f^m(x_1) \}.
\end{equation}

Note that, by \ref{item2:reflemma}, $x_0$ is not a leaf of $\cG_1$,  hence by \ref{quasi-oriented:item3} we deduce that $\degoutz(x_0) = 0$. This implies in particular that either $x_0 = f(x_0)$ or $x_0 R_1 f(x_0)$, and thus $f(x_0) \in [x_0]_{\cG_1}$. The same argument can be inductively repeated to infer that
\begin{equation*}
f^k(x_0) \in [x_0]_{\cG_1} \text { and either } f^k(x_0) = f^{k+1}(x_0) \text{ or } f^k(x_0) R_1 f^{k+1}(x_0), \quad k= 0,\dots,  \lceil r \rceil .
\end{equation*}
The same statement can be proved verbatim for $x_1$.

Thus, if $[x_0]_{\cG_1} \ne [x_1]_{\cG_1}$, then $f^k(x_0) \ne f^j(x_1)$ for all $0 \le k, j \le r$. If, on the other hand,  $[x_0]_{\cG_1} = [x_1]_{\cG_1}$, then condition \ref{item1:reflemma} implies $f^k(x_0) \ne f^j(x_1)$ whenever $k+j \le r$. In either case, using \eqref{eq:geodesic}, we conclude that $\rho_\cG(x_0, x_1) > r$.
\end{proof}

\section{U-amenability and finite Borel asymptotic dimension} \label{section:asdim}
In this section we prove the main result of the paper, Theorem \ref{thm:ua_asdim}, asserting that a u-amenable acyclic Borel graph with finite degree has finite Borel asymptotic dimension, and thus induces a hyperfinite equivalence relation.

Before proceeding with the proof, we introduce some useful notation. Given a graph $\cG \coloneqq (X, R)$ and $xRy$, define the graph
\begin{equation} \label{eq:Gxy}
\cG_{x,y} \coloneqq (X, R \setminus \{ (x,y), (y,x) \}),
\end{equation}
which is the graph obtained from $\cG$ after removing the edge $xRy$. Note that, in case $\cG$ is acyclic, then
\begin{equation*}
[x]_{\cG_{x,y}} = \{z \in [x]_\cG \colon \rho_\cG(z, x) < \rho_\cG(z, y)\}, \, [y]_{\cG_{x,y}} = \{z \in [x]_\cG \colon \rho_\cG(z, y) < \rho_\cG(z,x)\},
\end{equation*}
and moreover
\begin{equation} \label{eq:partition}
[x]_\cG = [y]_\cG = [x]_{\cG_{x,y}} \sqcup [y]_{\cG_{x,y}}.
\end{equation}

\begin{lemma}\label{lemma:theta_maps}
Let $\cG \coloneqq (X, R)$ be an acyclic Borel graph and let $\lambda : E_\cG \to \mathbb{R}_{\ge 0}$ be a Borel function such that $\lambda(x, \cdot)$, which we abbreviate as $\lambda_x$, belongs to $\ell^1([x]_\cG)$ for all $x \in X$. Then the maps
\[
\begin{aligned}[c]
\theta_0 \colon R &\to \bbR \\
(x,y) &\mapsto \lambda_{x}([x]_{\cG_{x,y}})
\end{aligned}
\qquad
\begin{aligned}[c]
\theta_1 \colon R &\to \bbR \\
(x,y) &\mapsto \lambda_{y}([y]_{\cG_{x,y}})
\end{aligned}
\]
are Borel.
\end{lemma}

\begin{proof}
It sufficies to prove the statement for $\theta_0$, since $\theta_1(x,y) =\theta_0(y,x)$. By the Lusin--Novikov uniformization theorem (\cite[Theorem 18.10]{Kechris:CDST}) there are Borel functions $F_n \colon X \to X$, for $n \in \bbN$, such that $E_\cG = \{(x,y) \in X^2 : \exists n \, (y = F_n(x)) \}$.
We inductively define a sequence of Borel functions $w_n \colon R \to \bbR$ as follows:
\begin{align*}
w_0(x,y) & \coloneqq 0 \text{ for all }  xRy\\
w_{n+1}(x,y) &\coloneqq \begin{cases} w_n(x,y) + \lambda_x(F_{n+1}(x)) & \smash{\raisebox{1.2ex}{if $F_{n+1}(x) \ne F_j(x)$ for all $j \le n$,}} \\
&\smash{\raisebox{1.5ex}{$\rho_\cG(x, F_{n+1}(x)) < \rho_\cG(y, F_{n+1}(x))$}} \\
w_n(x,y) &\text{otherwise.}
\end{cases}
\end{align*}
Since $\cG$ is acyclic, the sequence $(w_n)_{n \in \bbN}$ pointwise converges to $\theta_0$, which is therefore Borel.
\end{proof}


\begin{theorem}\label{thm:ua_asdim}
Let $\cG \coloneqq(X, R)$ be an acyclic Borel graph with $\deg(\cG) < \infty$. If $\cG$ is u-amenable then $\asdim(X, \rho_\cG) \le 1$. In particular, $E_\cG$ is hyperfinite.
\end{theorem}

\begin{proof}
We aim to apply Lemma \ref{lemma:quasi-oriented} to $\cG$. To do so, fix $r > 0$. By u-amenability there exists a 
Borel map
\[
\lambda \colon E_\cG \to \bbR_{\ge 0}
\]
such that $\lambda_x \in \ell^1([x]_{\cG})$ with $\| \lambda_x \|_1 = 1$ for all $x \in X$, and such that
\begin{equation} \label{eq:amenable}
\| \lambda_x - \lambda_y \|_1 < \frac{1}{12}, \quad \text{if } \rho_\cG(x, y) \le r +2, \, x,y \in X.
\end{equation}

Let $\theta_0, \theta_1 \colon R \to \bbR_{\ge 0}$ be the maps defined as
\begin{equation*}
\theta_0(x, y) \coloneqq \lambda_x([x]_{\cG_{x,y}}) \text{ and } \theta_1(x, y) \coloneqq \lambda_y([y]_{\cG_{x,y}}), \quad (x,y) \in R,
\end{equation*}
which are Borel by Lemma \ref{lemma:theta_maps} (see \eqref{eq:Gxy} for the definition of $\cG_{x,y}$).

Consider the set of edges
\begin{equation*}
R_0 \coloneqq \left\{ (x,y) \in R \colon  \theta_0(x, y), \theta_1(x, y) \notin  [5/12,7/12 ] \right\}.
\end{equation*}
The set $R_0$ is Borel since $\theta_0$ and $\theta_1$ are. Given $xRy$ we have 
\begin{equation*}
\abs{(1 - \theta_0(x, y)) - \theta_1(x, y)} \stackrel{\eqref{eq:partition}}{=} \abs{\lambda_x([y]_{\cG_{x,y}}) - \lambda_y([y]_{\cG_{x,y}})} \stackrel{\eqref{eq:amenable}}{<} 1/12.
\end{equation*}
Hence, if $xR_0y$, then exactly one between either
\begin{equation} \label{eq:1}
\theta_0(x, y) > 7/12\ \text{ and }\ \theta_1(x, y) < 5/12
\end{equation}
or
\begin{equation} \label{eq:2}
\theta_0(x, y) < 5/12 \ \text{ and }\  \theta_1(x, y) > 7/12
\end{equation}
holds. Using \eqref{eq:1}-\eqref{eq:2}, along with $\theta_0(x,y) = \theta_1(y,x)$, we define a Borel orientation $\vv{R}_0 \subset R_0$ by setting
\begin{equation*}
\vv{R}_0 \coloneqq \{ (x,y) \in R_0 : \theta_0(x, y) < 5/12, \, \theta_1(x, y) > 7/12 \}.
\end{equation*}


Let $R_1 \coloneqq R \setminus R_0$ and $\cG_1 \coloneqq (X, R_1)$. We verify now that $\cG_0 = (X, R_0)$ with orientation $\vv{R}_0$ and $\cG_1$ satisfy the five conditions of Lemma \ref{lemma:quasi-oriented}, which is enough to conclude the proof, since $\asdim(X, \rho_\cG) \le 3$ implies that $\asdim(X, \rho_\cG) \le 1$, by \cite[Theorem 1.1]{CJMST-D}.

\textbf{\ref{quasi-oriented:item1}:} this condition holds by definition.

\textbf{\ref{quasi-oriented:item2}:} let $x \in X$ and suppose that $y_0, y_1 \in X$ are distinct such that $x \vv{R}_0 y_0$ and $x \vv{R}_0 y_1$. As $\cG$ is acyclic, the trees $[y_0]_{\cG_{x, y_0}}$
and $[y_1]_{\cG_{x, y_1}}$ are disjoint subsets of $[x]_\cG$, and therefore we have
\begin{equation*}
\begin{split}
1 &\ge \lambda_x([y_0]_{\cG_{x, y_0}}) + \lambda_x([y_1]_{\cG_{x, y_1}})\\
&\stackrel{\mathclap{\eqref{eq:amenable}}}{>} \lambda_{y_0}([y_0]_{\cG_{x, y_0}}) + \lambda_{y_1}([y_1]_{\cG_{x, y_1}}) - 2/12 \\
& > 7/12+7/12-2/12 = 1,
\end{split}
\end{equation*}
which is a contradiction.

\textbf{\ref{quasi-oriented:item3}:} suppose that $y_0, y_1$ and $y_2$ are three distinct points in $[x]_\cG$ such that either $x \vv{R}_0 y_i$ or $x R_1 y_i$ holds for all $i=0, 1, 2$. Then $[y_0]_{\cG_{x, y_0}}, [y_1]_{\cG_{x, y_1}}$ and $[y_2]_{\cG_{x, y_2}}$ are disjoint and we have
\begin{align*}
1 &\ge \lambda_x([y_0]_{\cG_{x, y_0}}) + \lambda_x([y_1]_{\cG_{x, y_1}}) + \lambda_x([y_2]_{\cG_{x, y_2}})\\
&\stackrel{\mathclap{\eqref{eq:amenable}}}{>} \lambda_{y_0}([y_0]_{\cG_{x, y_0}}) + \lambda_{y_1}([y_1]_{\cG_{x, y_1}}) + \lambda_{y_2}([y_2]_{\cG_{x, y_2}}) - 3/12 \\
& \ge 5/12+5/12+5/12 - 3/12 = 1.
\end{align*}

\textbf{\ref{quasi-oriented:item4}:} this condition is automatic since $\cG$ is acyclic.

\textbf{\ref{quasi-oriented:item5}:} assume that there are two leaves $x_0, x_1$ in the same connected component $[x]_{\cG_1}$ of $\cG_1$ such that there are $y_0, y_1 \in X$ with $x_0 \vv{R}_0 y_0$ and $x_1 \vv{R}_0 y_1$. Note that $[y_0]_{\cG_{x_0, y_0}}$ and $[y_1]_{\cG_{x_1, y_1}}$ are disjoint. If $\rho_{\cG_1}(x_0, x_1) \le r$ then $\rho_{\cG_1}(y_0, y_1) \le r+2$ hence
\begin{align*}
1 &\ge \lambda_{y_0}([y_0]_{\cG_{x_0, y_0}}) + \lambda_{y_0}([y_1]_{\cG_{x_1, y_1}})\\
&\stackrel{\mathclap{\eqref{eq:amenable}}}{>} \lambda_{y_0}([y_0]_{\cG_{x_0, y_0}}) + \lambda_{y_1}([y_1]_{\cG_{x_1, y_1}}) - 1/12 \\
& > 7/12+7/12-1/12 > 1.
\end{align*}
This is a contradiction, hence $\rho_{\cG_1}(x_0, x_1) > r$ which in turn gives $|[x]_{\cG_1}| > r$.

Hyperfiniteness of $E_\cG$ follows by \cite[Theorem 1.7]{CJMST-D}.
\end{proof}

We put finally all pieces together and deduce Theorem \ref{thm_main:hyper_treeable}, and its corollaries Theorem \ref{thm_main:Fk}, Corollary \ref{cor_intro:group} and Corollary \ref{cor_intro:bounded}.
\begin{corollary}\label{cor: main result}
Let $E$ be a countable Borel equivalence relation which is treeable and hyper-u-amenable. Then $E$ is hyperfinite.
\end{corollary}

\begin{proof}
Let $\cG$ be an acyclic Borel graph such that $E_\cG = E$. By Proposition \ref{prop: increasing union graphings} the graph $\cG$ is a union of an increasing sequence of u-amenable subgraphs $\cG_n$ that have finite degree. The graphs $\cG_n$ are acyclic, and therefore $\asdim(X, \rho_{\cG_n}) < \infty$ for all $n \in \bbN$, by Theorem \ref{thm:ua_asdim}. The conclusion then follows by Proposition \ref{prop:union}.
\end{proof}

\begin{corollary} \label{cor:applications}
Let $X$ be a standard Borel space and let $E \subseteq X^2$ be a treeable countable Borel equivalence relation. Suppose that either one of the following three assumptions holds:
\begin{enumerate}
\item $E$ is measure-hyperfinite and $E = E_G^X$ for an action $G \curvearrowright X$ by a countable group such that the stabilizer of every point is amenable, and there is a Polish $\sigma$-compact topology on $X$ for which such action is continuous,
\item $E = E_G^X$ for some Borel action $G \curvearrowright X$ by a countable amenable group $G$,
\item $E$ is amenable and Borel bounded.
\end{enumerate}
Then $E$ is hyperfinite.
\end{corollary}
\begin{proof}
The equivalence relation $E$ is hyper-u-amenable under either of the three assumptions in the statement, respectively by Corollary \ref{cor: continuous action}, Proposition \ref{prop:group_action}, and Proposition \ref{prop: Borel bounded}. The conclusion then follows by Corollary \ref{cor: main result}.
\end{proof}


