\title{Optimal Execution and Macroscopic Market Making}


\author{Ivan Guo}
\thanks{\hspace{0.2cm} Ivan Guo, Email: ivan.guo@monash.edu, Address: Centre for Quantitative Finance and Investment Strategies, School of Mathematics, Monash University, Wellington Rd, Clayton VIC 3800, Australia}
\author{Shijia Jin} 
