\section{Almgren-Chriss-Avellaneda-Stoikov Model}
\label{paper 3 section 4}
\noindent Built upon the previous discussion, a particular example is presented in this section. In regard to the liquidity consuming part, we consider a single trader and set the linear temporary impact $\lambda^1(u) = \beta_t \, (u)^2$ as in the second session, for some bounded and positive $\beta \in \mathbb{S}^2$. Then, the cash account of trader $(i, \e)$ becomes
\begin{equation*}
    X_t^{i, \e} = - \int_0^t \big(S_u^{i,\e} + \beta_t \, v_u^{i,e} \big) \, v_u^{i,e} \, du.
\end{equation*}
Because the transaction price comprises the market price and a linear temporary impact term---similar to \cite{almgren2001optimal}, we consider this trader to be of the \textit{`Almgren-Chriss type.'}

Concerning the liquidity providing side, there are two market makers competing for the order flow under the exponential intensity $\Lambda(\delta) = \exp(-\gamma \, \delta)$, for some $\gamma > 0$. The inventory process of agent $(i, \m)$ reads
\begin{equation*}
    Q_t^{i, \m} = q_0^{i, \m} - \int_0^t \tilde{a}_u \cdot \exp\Big(-\gamma \big( \delta_u^{i,a} - \bar{\delta}_u^{i,a} \big) \Big) \, du + \int_0^t \tilde{b}_u \cdot \exp \Big(-\gamma \big(\delta_u^{i,b} - \bar{\delta}_u^{i,b} \big) \Big) \, du.
\end{equation*}
The work of \cite{avellaneda2008high} can be interpreted as a discrete version of the above (refer to \cite{guo2023macroscopic}), under the assumption that the best price from the others is always the reference price. Therefore, we regard this market maker as being of the \textit{`Avellaneda-Stoikov type.'}

The individual quadratic temporary impact and the exponential intensity inspire the name \textit{`Almgren-Chriss-Avellaneda-Stoikov model.'} Besides, we consider the homogeneous penalty parameters:
\begin{equation*}
    \phi^{1,\e} = \phi^{i,\m} = \phi \text{ \; and \; } A^{1,\e} = A^{i,\m} = A
\end{equation*}
for all $i$. For convenience, let us set $q_0^{1,\e} < 0$ and $q_0^{1,\m} \geq q_0^{2,\m}$. An advantage of such settings is that Lipschitz mappings $\psi^a, \psi^b$, and $\varphi$ in the implicit function theorem can be explicitly derived. We introduce the FBSDE characterization of the equilibrium as follows, paying attention to the removal of the truncation $\xi$ and $\Tilde{\xi}$.

\kong

\begin{theorem}
\label{paper 3 first character}
    Given $\xi, \Tilde{\xi}$ are large enough, an admissible strategy profile $(\hat{v}^{1,\e}, (\boldsymbol{\hat{\delta}}^j)_{j=1}^2)$ forms a Nash equilibrium if and only if
    \begin{equation}
        \hat{\delta}_t^{i, a}= \frac{1}{\gamma} + Y_t^{i,\m}, \quad \hat{\delta}_t^{i, b}= \frac{1}{\gamma} - Y_t^{i,\m}, \text{ \; and \; } \hat{v}_t^{1, \e} = \frac{1}{2 \, \beta_t} \, \big( Y_t^{1, \e} - Y_t^{1, \m} -\frac{1}{\gamma} \big) \vee \epsilon,
    \label{paper 3 big game feedback}
\end{equation}
    where adjoint processes solve the FBSDE system
    \begin{gather}
    \left\{
    \begin{aligned}
     dQ_t^{1, \m} &= - \hat{a}_t \, \exp\big(- \gamma \, ( Y_t^{1 ,\m} -  Y_t^{2 ,\m} )\big) \, dt + b_t \, \exp\big(- \gamma \, ( Y_t^{2 ,\m} - Y_t^{1,\m}) \big) \, dt,\\
    \, dY_t^{1, \m} &= 2 \phi_t \, Q_t^{1, \m} \, dt + dM_t^{1, \m},\\
    Q_0^{1, m} &= q_0^{1, \m}, \quad Y_T^{1, \m} = -2A \, Q_T^{1, \m};
    \end{aligned}
    \right.
    \label{paper 3 big FBSDE 1}\\
    \left\{
    \begin{aligned}
     dQ_t^{1, \e} &= \frac{1}{2 \, \beta_t} \, \Big( Y_t^{1, \e} - Y_t^{1,\m} -\frac{1}{\gamma} \Big) \vee \epsilon \,dt,\\
    \, dY_t^{1,\e} &= 2\phi_t \, Q_t^{1,\e} \, dt + dM_t^{1,\e},\\
    Q_0^{1,\e} &= q_0^{1, \e}, \quad Y_T^{1,\e} = -2A\,Q_T^{1,\e},
    \end{aligned}
    \right.
    \label{paper 3 big FBSDE 2}
\end{gather}
where 
\begin{equation*}
    \hat{a}_t = a_t + \frac{1}{2 \, \beta_t} \, \Big( Y_t^{1, \e} - Y_t^{1, \m} -\frac{1}{\gamma} \Big) \vee \epsilon.
\end{equation*}
The equation for $(Q^{2, \m}, Y^{2, \m}, M^{2, \m})$ is symmetric.
\end{theorem}

\begin{proof}
Suppose $(\hat{v}^{1, \e}, (\hat{\boldsymbol{\delta}}^j)_{j = 1}^2)$ is a Nash equilibrium. Provided with $\hat{v}^{1,\e}$, we know market makers solve the market making game. The Hamiltonian of market maker $(i, \m)$ reads
\begin{equation*}
\begin{aligned}
    \Big[ -\tilde{a}_t \, \exp &\big( - \gamma( \delta^{i,a} - \bar{\delta}^{i,a} ) \big )  + \tilde{b}_t \, \exp \big( - \gamma (\delta^{i,b} - \bar{\delta}^{i,b})  \big ) \Big] \, y^{i, \m} \\
    &+ \delta^{i,a} \, \tilde{a}_t \,\exp \big( - \gamma( \delta^{i,a} - \bar{\delta}^{i,a} ) \big )  + \delta^{i,b} \, \tilde{b}_t \, \exp \big( - \gamma( \delta^{i,b} - \bar{\delta}^{i,b} ) \big )  - \phi_t^{i, \m} \, \big( q^{i, \m} \big)^2.
\end{aligned}
\end{equation*}
To maximize the Hamiltonian, the tractability of exponential functions allows $(\hat{\delta}^{i,a}, \hat{\delta}^{i,b})$ to be dependent only on $y^{i,\m}$:
\begin{equation*}
    \hat{\delta}^{i, a} = \big( \frac{1}{\gamma} + y^{i, \m} \big) \vee (-\xi) \wedge \xi \text{ \, and \, } \hat{\delta}^{i, b} = \big( \frac{1}{\gamma} - y^{i, \m} \big) \vee (-\xi) \wedge \xi.
\end{equation*}
The stochastic maximum principle tells us that $(Y^{j, \m})_{j=1}^2$ solves an FBSDE system, the forward equation of which reads
\begin{equation}
\begin{aligned}
     dQ_t^{i, \m} = - \tilde{a}_t \, &\exp \Big\{-\gamma \, \Big[ (\frac{1}{\gamma} + Y_t^{i, \m}) \vee (-\xi) \wedge \xi - \min_{k \neq i}(\frac{1}{\gamma} + Y_t^{k, \m}) \vee (-\xi) \wedge \xi \Big] \Big\} \, dt,\\
     &+ b_t \, \exp \Big\{-\gamma \, \Big[ (\frac{1}{\gamma} - Y_t^{i, \m}) \vee (-\xi) \wedge \xi - \min_{k \neq i}(\frac{1}{\gamma} - Y_t^{k, \m}) \vee (-\xi) \wedge \xi \Big] \Big\} \, dt.
    \label{paper 3 big FBSDE _1}
\end{aligned}
\end{equation}
Here, the backward equation is omitted for short. Due to the homogeneity of penalty parameters, the ordering property---Lemma 5.2 in \cite{guo2024macroscopicmarketmakinggames}---yields 
\begin{equation*}
Y_t^{1, \m} \leq Y_t^{2, \m}
\end{equation*}
for all $t$. From the estimation
\begin{equation*}
\begin{aligned}
    Q_t^{1, \m} &\leq q_0^{1,m} + \int_0^t b_u \, \exp \Big\{-\gamma \, \Big[ (\frac{1}{\gamma} - Y_u^{1, \m}) \vee (-\xi) \wedge \xi - (\frac{1}{\gamma} - Y_u^{2, \m}) \vee (-\xi) \wedge \xi \Big] \Big\} \, du\\
    &\leq q_0^{1,m} + \int_0^t b_u \, du,
\end{aligned}
\end{equation*}
we learn that $Q^{1,\m}$ is bounded above by some constant depending on $q_0^{1,m}$ and the upper bound of $b$. Combined with
\begin{equation*}
    Y_t^{1, \m} = -\mathbb{E}_t \Big[ 2A \,Q_T^{1,\m} + 2 \int_t^T \phi_u \, Q_u^{1,\m} \, du\Big],
\end{equation*}
it follows $Y^{1, \m}$ is bounded below by some constant independent of $\xi$ and $\Tilde{\xi}$. Therefore, we first set $\xi$ large enough such that 
\begin{equation*}
    -\xi \leq \frac{1}{\gamma} + Y_t^{1, \m} \leq \frac{1}{\gamma} + Y_t^{2, \m} \text{ \; and \; } \xi \geq \frac{1}{\gamma} - Y_t^{1, \m} \geq \frac{1}{\gamma} - Y_t^{2, \m}
\end{equation*}
for all $t$. On the other hand, equipped with $(Y^{k, \m})_{k=1}^2$, the trader is dealing with an optimal execution problem. Examining her Hamiltonian 
\begin{equation*}
\begin{aligned}
    v^{1,\e} \, y^{1,\e} - v^{1, \e} \, \min_{1 \leq j \leq 2} \delta^{j, a} &- \beta_t \, (v^{1,\e})^2 - \phi_t^{i, \e} \, \big( q^{i,\e} \big)^2\\
    &= v^{1,\e} \, y^{1,\e} - v^{1, \e}\cdot \Big[ \big( \frac{1}{\gamma} + Y_t^{1, \m} \big) \wedge \xi \Big] - \beta_t \, (v^{1,\e})^2 - \phi_t^{i, \e} \, \big( q^{i,\e} \big)^2,
\end{aligned}
\end{equation*}
the optimal feedback control reads
\begin{equation*}
    v^{1, \e} = \frac{1}{2 \, \beta_t} \, \Big( y^{1, \e} - \big(\frac{1}{\gamma} + Y_t^{1, \m} \big) \wedge \xi \Big) \vee \epsilon \wedge \Tilde{\xi}.
\end{equation*}
The stochastic maximum principle infers that $Y^{j, \e}$ solves an FBSDE with the forward equation
\begin{equation}
     dQ_t^{1,\e} = \frac{1}{2 \,\beta_t} \, \Big( Y_t^{1, \e} - \big(\frac{1}{\gamma} + Y_t^{1, \m} \big) \wedge \xi \Big) \vee \epsilon \wedge \Tilde{\xi} \,dt.
    \label{paper 3 big FBSDE _2}
\end{equation}
Since $Q^{1, \e}$ is increasing, a similar argument yields that $Y^{1, \e}$ is upper bounded by some constant independent of $\xi$ and $\Tilde{\xi}$. Combined with the lower bound of $Y^{1,\m}$, we are able to pick $\Tilde{\xi}$ large enough such that this truncation is of no impact. Note that such choice of $\Tilde{\xi}$ is independent of $\xi$. Consequently, the resulting order flow $v^{1,\e} + a$ is also bounded above by some constant independent of $\xi$. Therefore, Proposition 5.3 in \cite{guo2024macroscopicmarketmakinggames} enables us to pick $\xi$ sufficiently large to additionally ensure that
\begin{equation*}
    \xi \geq \frac{1}{\gamma} + Y_t^{2, \m} \geq \frac{1}{\gamma} + Y_t^{1, \m} \text{ \; and \; } -\xi \leq \frac{1}{\gamma} - Y_t^{2, \m} \leq \frac{1}{\gamma} - Y_t^{1, \m}
\end{equation*}
for all $t$. System \eqref{paper 3 big FBSDE _1}-\eqref{paper 3 big FBSDE _2} finally leads to \eqref{paper 3 big FBSDE 1}-\eqref{paper 3 big FBSDE 2} since both $\xi$ and $\Tilde{\xi}$ have been removed.
\end{proof}

\kong

To solve system \eqref{paper 3 big FBSDE 1}-\eqref{paper 3 big FBSDE 2}, we introduce the following notations:
\begin{equation*}
\begin{aligned}
    \begin{pmatrix}
        \mathcal{Q}^{1,\m} \\
        \mathcal{Q}^{2, \m} \\
        \mathcal{Q}^{1, \e} \\
    \end{pmatrix}
    :=
    \begin{pmatrix}
        1 & 0 & 0\\
        1 & -1 & 0\\
        -1 & 0 & 1\\
    \end{pmatrix}
    \begin{pmatrix}
        Q^{1,\m} \\
        Q^{2, \m} \\
        Q^{1, \e} \\
    \end{pmatrix}, \hspace{0.4cm}
    \begin{pmatrix}
        \mathcal{Y}^{1,\m} \\
        \mathcal{Y}^{2, \m} \\
        \mathcal{Y}^{1, \e} \\
    \end{pmatrix}
    :=
     \begin{pmatrix}
        1 & 0 & 0\\
        1 & -1 & 0\\
        -1 & 0 & 1\\
    \end{pmatrix}
    \begin{pmatrix}
        Y^{1,\m} \\
        Y^{2, \m} \\
        Y^{1, \e} \\
    \end{pmatrix}.
\end{aligned}
\end{equation*}
By direct calculations, we can see $(\mathcal{Q}^{1, \e}, \mathcal{Y}^{1, \e})$ and $(\mathcal{Q}^{i, \m}, \mathcal{Y}^{i, \m})_{i = 1}^2$ satisfy another FBSDE system:
\begin{equation}
\begin{aligned}
    d\mathcal{Q}_t^{1, \m} &= - \Big( a_t +\frac{1}{2 \, \beta_t} \, \big( \mathcal{Y}_t^{1, \e} - \frac{1}{\gamma} \big) \vee \epsilon \Big) \cdot \exp(-\gamma \,\mathcal{Y}_t^{2,\m}) \,dt + b_t \, \exp(\gamma \,\mathcal{Y}_t^{2,\m}) \,dt, \\
     d\mathcal{Q}_t^{2, \m} &= \Big( a_t + b_t + \frac{1}{2 \, \beta_t} \, \big( \mathcal{Y}_t^{1, \e} - \frac{1}{\gamma} \big) \vee \epsilon \Big) \cdot \Big[ \exp(\gamma \,\mathcal{Y}_t^{2,\m}) - \exp(-\gamma \,\mathcal{Y}_t^{2,\m}) \Big] \, dt,\\
    d\mathcal{Q}_t^{1, \e} &= \Big( \frac{1}{2 \, \beta_t} \, \big( \mathcal{Y}_t^{1, \e} - \frac{1}{\gamma} \big) \vee \epsilon \Big) \cdot \Big[ 1 + \exp( - \gamma \, \mathcal{Y}_t^{2,\m}) \Big] \, dt \\
    &\hspace{4.5cm} + a_t \, \exp( - \gamma \, \mathcal{Y}_t^{2,\m}) \, dt - b_t \, \exp( \gamma \, \mathcal{Y}_t^{2,\m}) \, dt,
\label{paper 3 equiv big FBSDE}
\end{aligned}
\end{equation}
with $\mathcal{Q}_0^{1, \m} = q_0^{1,\m}, \mathcal{Q}_0^{2, \m} = q_0^{1, \m} - q_0^{2, \m}$, and $\mathcal{Q}_0^{1, \e} = q_0^{1, \e} - q_0^{1, \m}$. Again, we omit the backward equations because they are more straightforward. On account of the non-singularity of the transformation matrix, systems \eqref{paper 3 big FBSDE 1}-\eqref{paper 3 big FBSDE 2} and \eqref{paper 3 equiv big FBSDE} are equivalent from the perspective of well-posedness. Further, since we already know that $(Y^{1,\m}, Y^{2,\m}, Y^{1,\e})$ are bounded, the same is true for $(\mathcal{Y}^{1,\m}, \mathcal{Y}^{2,\m}, \mathcal{Y}^{1,\e})$. We thus regard \eqref{paper 3 equiv big FBSDE} as a Lipschitz FBSDE system. The following theorem transfer the well-posedness of the FBSDE system to the one of BSRE. In one-dimensional case, such equation is known as the \textit{characteristic BSDE} introduced by \cite{ma1999forward}.

\kong

\begin{theorem}
    The system \eqref{paper 3 big FBSDE 1}-\eqref{paper 3 big FBSDE 2} accepts a unique solution if the following BSRE 
    \begin{equation}
        dR_t = \big( 2\phi_t \, I - R_t \, G_t \, R_t\big)\,dt + dM_t, \quad R_T = - 2A \,I,
        \label{paper 3 M_+ BSRE}
    \end{equation}
    has a unique bounded solution $R$, where $I\in \mathbb{R}^{2 \times 2}$ is the identity matrix. Here, adapted matrix-valued process $G$ is continuous, bounded, and belongs to $M_+$-matrix in $\mathbb{R}^{2 \times 2}$ for all $t$.
\end{theorem}
\begin{proof}
    Given $q_0^{1, \m} \geq  q_0^{2, \m}$, Lemma 5.2 in \cite{guo2024macroscopicmarketmakinggames} infers that $Q_t^{1, \m} \geq Q_t^{2, \m}$ and $Y_t^{1, \m} \leq Y_t^{2, \m}$ for any $t$ as long as the solution exists. Equivalently, if $\mathcal{Q}_0^{2, \m} \geq 0$, then $\mathcal{Q}_t^{2, \m} \geq 0$ and $\mathcal{Y}_t^{2, \m} \leq 0$ for all $t$. It suffices to study the initial condition with $\mathcal{Q}^{2,\m}$ being non-negative. Due to its Lipschitz property, we know the regular decoupling field as well as \eqref{paper 3 equiv big FBSDE} is well-posed on $[s, T]$ for some $s > 0$, which refers to
    \begin{equation*}
    \begin{aligned}
    d\mathcal{Q}_t^{2, \m} &= \Big( a_t + b_t + \frac{1}{2 \, \beta_t} \, \big( \mathcal{Y}_t^{1, \e} - \frac{1}{\gamma} \big) \vee \epsilon \Big) \cdot \Big[ \exp(\gamma \,\mathcal{Y}_t^{2,\m}) - \exp(-\gamma \,\mathcal{Y}_t^{2,\m}) \Big] \, dt,\\
    &=: \mathcal{U}^1(t, \mathcal{Y}_t^{2, \m}, \mathcal{Y}_t^{1, \e}) \,dt\\
    d\mathcal{Q}_t^{1, \e} &= \Big( \frac{1}{2 \, \beta_t} \, \big( \mathcal{Y}_t^{1, \e} - \frac{1}{\gamma} \big) \vee \epsilon \Big) \cdot \Big[ 1 + \exp( - \gamma \, \mathcal{Y}_t^{2,\m}) \Big] \, dt \\
    &\hspace{4.5cm} + a_t \, \exp( - \gamma \, \mathcal{Y}_t^{2,\m}) \, dt - b_t \, \exp( \gamma \, \mathcal{Y}_t^{2,\m}) \, dt,\\
    &=: \mathcal{U}^2(t, \mathcal{Y}_t^{2, \m}, \mathcal{Y}_t^{1, \e}) \,dt
\end{aligned}
\end{equation*}
with $\mathcal{Q}_s^{2, \m} = \iota^{2, \m} \geq 0$ and $\mathcal{Q}_s^{1, \e} = \iota^{1, \e} \in \mathbb{R}$. Here, we only need to study $(\mathcal{Q}^{2, \m}, \mathcal{Y}^{2, \m})$ and $(\mathcal{Q}^{1, \e}, \mathcal{Y}^{1, \e})$, provided with which $(\mathcal{Q}^{1, \m}, \mathcal{Y}^{1, \m})$ is immediately obtained. Given two initial conditions $(\iota^{2, \m}, \iota^{1, \e})$ and $(\tilde{\iota}^{2, \m}, \tilde{\iota}^{1, \e})$ with $\iota^{2, \m}, \tilde{\iota}^{2, \m} \geq 0$, denote by $(\mathcal{Q}^{2, \m}, \mathcal{Y}^{2, \m})$, $(\mathcal{Q}^{1, \e}, \mathcal{Y}^{1, \e})$, and $(\tilde{\mathcal{Q}}^{2, \m}, \tilde{\mathcal{Y}}^{2, \m})$, $ (\tilde{\mathcal{Q}}^{1, \e}, \tilde{\mathcal{Y}}^{1, \e})$ the corresponding solutions. Let us write
\begin{gather*}
    \mathcal{U}(t, y^{2, \m}, y^{1, \e}) := \begin{pmatrix}
        \mathcal{U}^1\\
        \mathcal{U}^2
    \end{pmatrix}(t, y^{2, \m}, y^{1, \e})\\
    \mathscr{Q}:= \begin{pmatrix}
        \tilde{\mathcal{Q}}^{2, \m} \\
        \tilde{\mathcal{Q}}^{1, \e}
    \end{pmatrix} - \begin{pmatrix}
        \mathcal{Q}^{2, \m} \\
        \mathcal{Q}^{1, \e}
    \end{pmatrix}, \text{ \; and \; } \mathscr{Y}:= \begin{pmatrix}
        \tilde{\mathcal{Y}}^{2, \m} \\
        \tilde{\mathcal{Y}}^{1, \e}
    \end{pmatrix} - \begin{pmatrix}
        \mathcal{Y}^{2, \m} \\
        \mathcal{Y}^{1, \e}
    \end{pmatrix}.
\end{gather*}
We intend to derive a linear FBSDE for $(\mathscr{Q}, \mathscr{Y})$. The Jacobian matrix of $\mathcal{U}$ with respect to $(y^{2, \m}, y^{1, \e})$ is either
\begin{equation}
    \begin{bmatrix}
    \gamma \, \big(\Breve{a}_t + b_t \big) \cdot \big( \exp(\gamma \, y^{2, \m}) + \exp(-\gamma \, y^{2, \m})\big) & -\frac{1}{2 \, \beta_t} \, \big(\exp(-\gamma \, y^{2, \m}) - \exp(\gamma \, y^{2, \m})\big)
    \\
    -\gamma \, \breve{a}_t\, \exp(- \gamma \, y^{2, \m}) -\gamma \, b_t\, \exp(\gamma \, y^{2, \m}) & \frac{1}{2\,\beta_t}\,\big(1 + \exp(-\gamma \, y^{2, \m}) \big)
    \label{paper 3 jacob matrix 1}
    \end{bmatrix}
\end{equation}
for the case when $\frac{1}{2 \, \beta_t} \, ( y^{1, \e} - \frac{1}{\gamma} ) > \epsilon$, or otherwise
\begin{equation}
    \begin{bmatrix}
    \gamma \, \big(a_t + b_t + \epsilon \big) \cdot \big( \exp(\gamma \, y^{2, \m}) + \exp(-\gamma \, y^{2, \m})\big) & 0
    \\
    -\gamma \, (a_t + \epsilon)\, \exp(- \gamma \, y^{2, \m}) -\gamma \, b_t\, \exp(\gamma \, y^{2, \m}) & 0
    \end{bmatrix},
    \label{paper 3 jacob matrix 2}
\end{equation}
where $\Breve{a}_t = a_t + \frac{1}{2 \, \beta_t} \, ( y^{1, \e} - \frac{1}{\gamma} )$. Given $\iota^{2, \m}, \tilde{\iota}^{2, \m} \geq 0$, it follows for all $t$ that $\max(\mathcal{Y}_t^{2, \m}, \tilde{\mathcal{Y}}_t^{2, \m}) \leq 0$. Equipped with the non-positive $y^{2, \m}$, it is straightforward to check that both \eqref{paper 3 jacob matrix 1} and \eqref{paper 3 jacob matrix 2} are $M_+$-matrices. The non-smooth mean value theorem gives 
\begin{equation*}
    \mathcal{U}(t, \tilde{\mathcal{Y}}_t^{2, \m}, \tilde{\mathcal{Y}}_t^{1, \e}) - \mathcal{U}(t, \mathcal{Y}_t^{2, \m}, \mathcal{Y}_t^{1, \e}) = G_t \, \mathscr{Y}_t,
\end{equation*}
where $G_t$ is an $M_+$-matrix for any $t\in[s, T]$. Indeed, the non-negative column sum remains under convex combination. The linear system for $(\mathscr{Q}, \mathscr{Y})$ reads
\begin{equation*}
\left\{
    \begin{aligned}
     d\mathscr{Q}_t &= G_t \, \mathscr{Y}_t \, dt,\\
    \, d\mathscr{Y}_t &= 2 \phi_t \, \mathscr{Q}_t \, dt + d\mathscr{M}_t,\\
    \mathscr{Q}_0 &= \begin{pmatrix}
        \tilde{\iota}^{2, \m} - \iota^{2, \m}\\
        \tilde{\iota}^{1, \e} - \iota^{1, \e}
    \end{pmatrix}, \quad \mathscr{Y}_T = -2A \, \mathscr{Q}_T,
    \end{aligned}
    \right.
\end{equation*}
which is known as the \textit{variation FBSDE} introduced in \cite{ma2015well} for one-dimensional equation. To solve this system, consider the affine ansatz $\mathscr{Y}_t = R_t \, \mathscr{Q}_t$. The BSRE is obtained by matching the coefficients. There exists a bounded solution $R$ on $[s,T]$ because of the regularity of the decoupling field. The only case when the decoupling field can not be extended to $[0,T]$ is that $R$ may explode if $s$ approaches some $t_{\min} \geq 0$. Hence, both the decoupling field and \eqref{paper 3 equiv big FBSDE} are well-posed if BSRE \eqref{paper 3 M_+ BSRE} accepts a unique bounded solution on $[0,T]$.
\end{proof}

\kong

The next theorem looks at a specific case when the well-posedness of \eqref{paper 3 M_+ BSRE} is derived. Moreover, the remaining truncation $\epsilon$ is eliminated.

\kong

\begin{theorem}
If the following conditions hold:\\
\vspace{-0.2cm}

\begin{itemize}
    \item order flow $a, b$ and terminal penalty $A$ are all deterministic; \\
    \vspace{-0.2 cm}
    \item agents are risk-neutral, i.e., running penalty $\phi = 0$,\\
    \vspace{-0.2 cm}    
\end{itemize}
the BSRE \eqref{paper 3 M_+ BSRE} accepts a unique bounded solution such that $R_t$ has non-positive entries for all $t$. Moreover, provided $a = b =0$ and $ - q_0^{1, \e} + q_0^{1, \m} \geq (2 A \gamma)^{-1}$, it holds for all $t$ that
\begin{equation}
\frac{1}{2 \, \beta_t} \, \big( Y_t^{1, \e} - Y_t^{1, \m} - \frac{1}{\gamma} \big) \geq \frac{\mathfrak{p}}{2\, \beta_t} \, \Big( -q_0^{1, \e} + q_0^{1, \m} - \frac{1}{2 A \gamma} \Big) \geq 0,
\label{paper 3 low trun}
\end{equation}
where $\mathfrak{p}>0$ is some constant depending only on model parameters.
\end{theorem}

\begin{proof}
    Given that all the coefficients are deterministic, it follows that $G$ is also deterministic and BSRE \eqref{paper 3 M_+ BSRE} reduces to the deterministic Riccati equation
    \begin{equation}
         R'(t) = - R(t) \, G_t \, R(t), \quad R(T) = - 2A \,I,
        \label{paper 3 M_+ deter riccati}
    \end{equation}
where the martingale term vanishes. By the Radon's lemma, Riccati equation \eqref{paper 3 M_+ deter riccati} will not explode on $[0, T]$ if and only if $V$ from the following linear system is non-singular on $[0, T]$:
    \begin{equation*}
        \begin{pmatrix}
            V(t)\\
            U(t)
        \end{pmatrix}' = \begin{pmatrix}
            0 & G_t\\
            0 & 0
        \end{pmatrix} \,
        \begin{pmatrix}
            V(t)\\
            U(t)
        \end{pmatrix}, \quad
        \begin{pmatrix}
            V(T)\\
            U(T)
        \end{pmatrix} = \begin{pmatrix}
            I\\
            -2A \, I
        \end{pmatrix}.
    \end{equation*}
The solution $V$ can be written explicitly as
\begin{equation*}
     V(t) = I + 2A\int_t^T G(s) \,ds.
\end{equation*}
Here, we can see that $V(t)$ is non-singular for all $t \leq T$ because both $I$ and $G$ are $M_+$-matrices. Consequently, the Radon lemma yields
\begin{equation*}
    R(t) = U(t) \, V(t)^{-1} = -2A\, \Big[ I + 2A\int_t^T G(s) \,ds \Big]^{-1} =: -2A \, \mathcal{E}(t).
\end{equation*}
Note that $\mathcal{E}(t)$ is element-wise non-negative since it is the inverse of an $M$-matrix. Hence, in addition to the well-posedness, solution $R_t$ is a non-positive matrix. 

Consider the following auxiliary system by setting $a = b = 0$ and $\epsilon = 0$ intentionally:
\begin{equation}
\begin{aligned}
    d\mathcal{Q}_t^{2, \m} &= \Big( \frac{1}{2 \, \beta_t} \, \big( \mathcal{Y}_t^{1, \e} - \frac{1}{\gamma} \big) \vee 0 \Big) \cdot \Big[ \exp(\gamma \,\mathcal{Y}_t^{2,\m}) - \exp(-\gamma \,\mathcal{Y}_t^{2,\m}) \Big]\, dt, \quad \mathcal{Q}_0^{2, \m} = q_0^{1, \m} - q_0^{2, \m},\\
    d\mathcal{Q}_t^{1, \e} &= \Big( \frac{1}{2 \, \beta_t} \, \big( \mathcal{Y}_t^{1, \e} - \frac{1}{\gamma} \big) \vee 0 \Big) \cdot \Big[ 1 + \exp( - \gamma \, \mathcal{Y}_t^{2,\m}) \Big] \, dt,
\end{aligned}
\label{paper 3 Spec three player sys}
\end{equation}
where $\mathcal{Y}_t^{2, \m} = -2A \, \mathcal{Q}_T^{2, \m}$, $\mathcal{Y}_t^{1, \e} = -2A \, \mathcal{Q}_T^{1, \e}$ for all $t$. If $\mathcal{Q}_0^{1, \e}= -(2 A \gamma)^{-1}$, it can be checked directly that the (unique) solution $(\mathcal{Q}^{2, \m}, \mathcal{Y}^{2, \m})$, $(\mathcal{Q}^{1, \e}, \mathcal{Y}^{1, \e})$ reads 
\begin{equation*}
    \mathcal{Q}_t^{2, \m} = q_0^{1, \m} - q_0^{2, \m}, \quad \mathcal{Y}_t^{2, \m} = -2A \, (q_0^{1, \m} - q_0^{2, \m}), \quad \mathcal{Q}_t^{1, \e} = -\frac{1}{2 A \gamma}, \quad \mathcal{Y}^{1, \e} = \frac{1}{\gamma}.
\end{equation*}
For any $\tilde{\mathcal{Q}}_0^{1, \e} < -(2 A \gamma)^{-1}$ and $\tilde{\mathcal{Q}}_0^{2, \m} = \mathcal{Q}_0^{2, \m} = q_0^{1, \m} - q_0^{2, \m}$, let us denote the corresponding solution by $(\tilde{\mathcal{Q}}^{2, \m}, \tilde{\mathcal{Y}}^{2, \m})$, $( \tilde{\mathcal{Q}}^{1, \e}, \tilde{\mathcal{Y}}^{1, \e})$. We omit the subscript $t$ for the adjoint processes since $\mathcal{Y}^{1,\e}$ does not depend on $t$. According to the construction of the variational FBSDE and the Riccati equation, we know
\begin{equation*}
    \begin{pmatrix}
        \, \tilde{\mathcal{Y}}^{2, \m} - \mathcal{Y}^{2, \m}\,\\
        \, \tilde{\mathcal{Y}}^{1, \e} - \mathcal{Y}^{1, \e}\,
    \end{pmatrix}
    = R(0)
    \begin{pmatrix}
        \, \tilde{\mathcal{Q}}^{2, \m}_0-\mathcal{Q}^{2, \m}_0\,\\
        \, \tilde{\mathcal{Q}}^{1, \e}_0-\mathcal{Q}^{1, \e}_0\,
    \end{pmatrix}
    = R(0)
    \begin{pmatrix}
        \, 0 \, \\
        \, \tilde{\mathcal{Q}}_0^{1, \e} + (2 A \gamma)^{-1}\,
    \end{pmatrix},
\end{equation*}
with $R$ solving an equation of the type \eqref{paper 3 M_+ deter riccati}. The fact that $R(0)$ is non-positive yields
\begin{equation}
\begin{aligned}
    \tilde{\mathcal{Y}}^{2, \m} - \mathcal{Y}^{2, \m} = R_{12}(0) \, \Big( \tilde{\mathcal{Q}}_0^{1, \e} + \frac{1}{2 A \gamma} \Big) \geq 0,\\
    \tilde{\mathcal{Y}}^{1, \e} - \mathcal{Y}^{1, \e} = R_{22}(0) \, \Big( \tilde{\mathcal{Q}}_0^{1, \e} + \frac{1}{2 A \gamma} \Big) \geq 0,
    \label{paper 3 y and new y}
\end{aligned}
\end{equation} 
where $R_{ij}(0)$ denotes $(i, j)$-entry of the matrix $R(0)$. We can then conclude that both $(\tilde{\mathcal{Q}}^{2, \m}, \tilde{\mathcal{Y}}^{2, \m})$, $(\tilde{\mathcal{Q}}^{1, \e}, \tilde{\mathcal{Y}}^{1, \e})$ and $(\mathcal{Q}^{2, \m}, \mathcal{Y}^{2, \m})$, $(\mathcal{Q}^{1, \e}, \mathcal{Y}^{1, \e})$ solve the system \eqref{paper 3 Spec three player sys} without the term `$\vee \, 0$'. Consequently, the Jacobian matrix of the forward equations of \eqref{paper 3 Spec three player sys} takes only the form
\begin{equation}
\begin{aligned}
    &\frac{1}{2 \, \beta_t} \,  \begin{pmatrix}
        \, \gamma \, \big( y^{1, \e} - 1/\gamma \big) \cdot \big[ \exp(- \gamma \, y^{2, \m}) + \exp(\gamma \, y^{2, \m} ) \big] & - \big[ \exp(- \gamma \, y^{2, \m}) - \exp(\gamma \, y^{2, \m} ) \big] \, \\
        \, - \gamma \, \big( y^{1, \e} - 1/\gamma \big) \cdot \exp\big(- \gamma \, y^{2, \m} \big) & 1 + \exp( - \gamma\, y^{2, \m})
    \end{pmatrix}\\
    &=: \frac{1}{2 \, \beta_t} \, \mathcal{J}(y^{1,\e}, y^{2, \m}).
    \label{paper 3 smooth jacob}
\end{aligned}
\end{equation}
In view of the mean-value theorem, it suffices to study the `average' of matrices \eqref{paper 3 smooth jacob} with  $(y^{2, \m}, y^{1, \m}) \in \mathbb{R}^2$ lying in the line segment $\mathfrak{T}$ connecting $(\mathcal{Y}^{2, \m}, \mathcal{Y}^{1, \e})$ and $(\tilde{\mathcal{Y}}^{2, \m}, \tilde{\mathcal{Y}}^{1, \e})$:
\begin{equation*}
    G(t) =  \frac{1}{2 \, \beta_t} \int_0^1 \mathcal{J} \Big( \mathcal{Y}^{1, \e} + s \, (\tilde{\mathcal{Y}}^{1, \e} - \mathcal{Y}^{1, \e}), \mathcal{Y}^{2, \m} + s \, (\tilde{\mathcal{Y}}^{2, \m} - \mathcal{Y}^{2, \m}) \Big) \, ds.
\end{equation*}
Built upon \eqref{paper 3 y and new y}, in the line segment $\mathfrak{T}$ it holds that $y^{1, \e} \geq 1/\gamma$ and $0 \geq y^{2, \m} \geq -2A \, (q_0^{1, \m}-q_0^{2, \m})$. Hence, matrix $G(t)$ is an $M_+$-matrix. Recall that
\begin{equation*}
    R(0) = -2A\, \Big[ I + 2A\int_0^T G(s) \,ds 
    \Big]^{-1} =: -2A \cdot \mathcal{G}^{-1},
\end{equation*}
and direct calculations yield
\begin{equation*}
    R_{22}(0) = -2A \, \frac{\mathcal{G}_{11}}{\det(\mathcal{G})}.
\end{equation*}
While $\mathcal{G}$ is still an $M_+$-matrix due to positive column sums, we deduce
\begin{equation*}
\begin{aligned}
    \frac{\mathcal{G}_{11}}{\det(\mathcal{G})} &= \frac{\mathcal{G}_{11}}{ \mathcal{G}_{11} \cdot \mathcal{G}_{22}  - \mathcal{G}_{11} \cdot (-\mathcal{G}_{12}) + \mathcal{G}_{11}\cdot (-\mathcal{G}_{12}) - (-\mathcal{G}_{12}) \cdot (-\mathcal{G}_{21}) }\\
    &= \Big( \mathcal{G}_{22} + \mathcal{G}_{12} +(-\mathcal{G}_{12}) \cdot \frac{\mathcal{G}_{11}+ \mathcal{G}_{21}}{\mathcal{G}_{11}}\Big)^{-1}\\
    &\geq \frac{1}{ \mathcal{G}_{22} }.
\end{aligned}  
\end{equation*}
Denoting by $\uline{\beta} > 0$ the lower bound of $\beta$, it follows
\begin{equation*}
    R_{22}(0) \leq - \frac{ 2A }{ \mathcal{G}_{22} } \leq (-2) \, \Big\{ \frac{1}{A} + \frac{T}{\uline{\beta}} \, \Big[ 1  + e^{2A\gamma\,(q_0^{1,\m} - q_0^{2,\m} ) } \Big] \Big\}^{-1} =: -\mathfrak{p},
\end{equation*}
where $\mathfrak{p} > 0$. A review of \eqref{paper 3 y and new y} implies
\begin{equation}
    \tilde{\mathcal{Y}}^{1, \e}-\mathcal{Y}^{1, \e} = \tilde{\mathcal{Y}}^{1, \e} - \frac{1}{\gamma} = R_{22}(0) \, \Big( \tilde{\mathcal{Q}}_0^{1, \e} + \frac{1}{2 A \gamma} \Big) \geq \mathfrak{p} \cdot \Big( -\tilde{\mathcal{Q}}_0^{1, \e} - \frac{1}{2 A \gamma} \Big).
    \label{paper 3 constant v}
\end{equation}
To connect the auxiliary system \eqref{paper 3 Spec three player sys} to the original one, it suffices to let
\begin{equation*}
    \epsilon \leq \frac{\mathfrak{p}}{2 \, \bar{\beta}} \cdot \Big( -\tilde{\mathcal{Q}}_0^{1, \e} - \frac{1}{2 A \gamma} \Big),
\end{equation*}
where $\bar{\beta}$ is the upper bound of the process $\beta$. The proof is complete by recalling that $\tilde{\mathcal{Q}}_0^{1, \e} = q_0^{1,\e} - q_0^{1,\m}$.
\end{proof}

\kong

\noindent On account of this theorem, we now remove the lower truncation $\epsilon$ as follows.

\kong

\begin{assumption}
\label{paper 3 assum q^e}
 We let $q_0^{1, \e} - q_0^{1, \m} < -(2 A \gamma)^{-1}$ and set $\epsilon \leq \mathfrak{p} \cdot ( - q_0^{1, \e} + q_0^{1, \m} - \frac{1}{2 A \gamma} ) / (2 \, \Bar{\beta} )$ so that the lower truncation by $\epsilon$ is of no effect.
\end{assumption}

\kong

Given the above assumption and theorem, let us denoted by $(\hat{Q}^{1,\e}, \hat{Y}^{1,\e})$, $(\hat{Q}^{1,\m}, \hat{Y}^{1,\m})$, $(\hat{Q}^{2,\m}, \hat{Q}^{2,\m})$ the solution of the system \eqref{paper 3 big FBSDE 1}-\eqref{paper 3 big FBSDE 2}. In addition, the previous theorem enables us to further study the case when there are infinitely many traders. Consider an infinite number of traders indexed by $(i,\e)$ with $i\in \mathbb{N} \, \backslash \, \{1\}$, along with two market makers as before. The initial inventories $(q_0^{i,\e})_{i = 2}^\infty$ is a sequence of independent and identically distributed negative random variables with mean $q_0^{1, \e}$. In others words, agent $(1, \e)$ in the previous discussion can be regarded as the representative player. While traders and two market makers follows almost the same settings described in the beginning of the this section, the only difference lies in 
\begin{equation*}
    \Tilde{a}_t = a_t + \lim_{n \to \infty} \frac{1}{n} \sum_{i = 2}^{n + 1} \, v_t^{i,\e},
\end{equation*}
assuming the limit exists. To look for a Nash equilibrium, let us consider the ansatz that an equilibrium profile $((\hat{v}^{i, \e})_{i = 2}^\infty, (\hat{\boldsymbol{\delta}}^j)_{j = 1}^2)$ satisfies
\begin{equation}
    \lim_{n \to \infty} \frac{1}{n} \sum_{i = 2}^{n + 1} \, \hat{v}_t^{i,\e} = \frac{1}{2 \, \beta_t} \, \big( \hat{Y}_t^{1, \e} - \hat{Y}_t^{1, \m} - \frac{1}{\gamma} \big).
    \label{paper 3 mean field ansatz}
\end{equation}

\noindent Provided with the average trading rates \eqref{paper 3 mean field ansatz}, market makers are decoupled from traders, solving a market making game. Equipped with the consequent quoting strategies, the traders are decoupled from each other, engaging in the individual optimal execution problem. Hence, it suffices to verify the ansatz \eqref{paper 3 mean field ansatz}.

\kong

\begin{proposition}
    If we further assume
    \begin{equation}
        q_0^{j,\e} \leq q_0^{1, \e} + \frac{\beta_t}{A} \, \Big[ \frac{1}{2 \, \beta_t} \, \big( \hat{Y}_t^{1, \e} - \hat{Y}_t^{1, \m} - \frac{1}{\gamma} \big) - \epsilon \Big]
        \label{paper 3 iid lower bound}
    \end{equation}
    for all $j$ and $t$, there exists an equilibrium profile $((\hat{v}^{i, \e})_{i = 2}^\infty, (\hat{\boldsymbol{\delta}}^j)_{j = 1}^2)$ such that \eqref{paper 3 mean field ansatz} holds.
\end{proposition}

\begin{proof}
If there exists an equilibrium profile $((\hat{v}^{i, \e})_{i = 2}^\infty, (\hat{\boldsymbol{\delta}}^j)_{j = 1}^2)$ such that \eqref{paper 3 mean field ansatz} holds, then market makers solve the market making game. It is straightforward to see
\begin{equation*}
    \delta_t^{i, a}= \frac{1}{\gamma} + \hat{Y}_t^{i,\m} \text{ \; and \; } \delta_t^{i, b}= \frac{1}{\gamma} - \hat{Y}_t^{i,\m},
\end{equation*}
due to \eqref{paper 3 big game feedback} and the uniqueness of solution to \eqref{paper 3 big FBSDE 1}. Given such $(\hat{\boldsymbol{\delta}}^j)_{j = 1}^2$, each trader solves a stochastic control problem individually. For $i \in \mathbb{N} \, \backslash \, \{1\}$, the optimal control of agent $(i, \e)$ reads
\begin{equation*}
    v_t^{i, \e} = \frac{1}{2 \, \beta_t} \, \Big( Y_t^{i, \e} - \hat{Y}_t^{1, \m} -\frac{1}{\gamma} \Big) \vee \epsilon,
\end{equation*}
    where the adjoint process $Y^{i, \e}$ solve the forward-backward system
    \begin{equation}
     dQ_t^{i, \e} = \frac{1}{2\lambda} \, \Big( Y_t^{i, \e} - \hat{Y}_t^{1,\m} -\frac{1}{\gamma} \Big) \vee \epsilon \, dt, \quad Q_0^{i, \e} = q_0^{i, \e},
     \label{paper 3 mean field fbode}
\end{equation}
with $Y_t^{i,\e} = -2A \, Q_T^{i, \e}$. Define $(\Delta Q, \Delta Y) := (Q^{i, \e}-\hat{Q}^{1, \e}, Y^{i, \e} - \hat{Y}^{1, \e})$. Recalling that $(\hat{Q}^{1, \e}, \hat{Y}^{1, \e})$ satisfies \eqref{paper 3 big FBSDE 2}, an application of the mean value theorem gives
\begin{equation*}
    d\Delta Q_t = \ell_t \, \Delta Y_t \, dt, \quad \Delta Q_0 = q_0^{i,\e} - q_0^{1,\e}; \quad \Delta Y_t = -2A\, \Delta Q_T,
\end{equation*}
where $0 \leq \ell_t \leq 1 / (2\lambda)$ for all $t$. While the monotonicity argument in \cite{peng1999fully} implies the uniqueness, the solution of above system has the representation $\Delta Y_t = \varrho_t\, \Delta Q_t$, where $\varrho$ solves
\begin{equation}
    d \varrho_t = -\ell_t\, (\varrho_t)^2\,dt; \quad \varrho_T=-2A.
    \label{paper 3 simple riccati}
\end{equation}
As a simple case of \cite{guo2023macroscopic}, equation \eqref{paper 3 simple riccati} is well-posed and the solution $\varrho$ satisfies $\varrho_t \in [-2A, 0)$ for all $t$. If $q_0^{j, \e} \leq q_0^{1, \e}$, the above argument suggests
\begin{equation*}
    Y^{j,\e}_t - \hat{Y}^{1, \e}_t =  Y^{j,\e}_0 - \hat{Y}^{1, \e}_0 = \Delta Y_0 = \varrho_0 \, (q_0^{j,\e} - \bar{q}_0^\e) \geq 0,
\end{equation*}
which immediately yields
\begin{equation*}
    \frac{1}{2 \, \beta_t} \, \Big( Y_t^{j, \e} - \hat{Y}_t^{1, \m} - \frac{1}{\gamma} \Big) \geq \frac{1}{2 \, \beta_t} \, \Big( \hat{Y}_t^{1, \e} - \hat{Y}_t^{1, \m} - \frac{1}{\gamma} \Big) \geq \epsilon.
\end{equation*}
Regarding the case $q_0^{j, \e} > q_0^{1, \e}$, from \eqref{paper 3 iid lower bound} we can see
\begin{equation*}
    \hat{Y}^{1,\e}_t - Y^{j, \e}_t = -\varrho_0\,( q_0^{j, \e} - q_0^{1, \e}) \leq 2 \, \beta_t \, \Big(\frac{1}{2 \, \beta_t} \, \big( \hat{Y}_t^{1, \e} - \hat{Y}_t^{1, \m} -\frac{1}{\gamma} \big) - \epsilon \Big).
\end{equation*}
This helps deduce
\begin{equation*}
    \frac{1}{2 \, \beta_t} \, \Big( \hat{Y}_t^{1, \e} - \hat{Y}_t^{1, \m} - \frac{1}{\gamma} \Big) - \frac{1}{2 \, \beta_t} \, \Big( Y_t^{j, \e} - \hat{Y}_t^{1, \m} -\frac{1}{\gamma} \Big) \leq \frac{1}{2 \, \beta_t} \, \Big( \hat{Y}_t^{1, \e} - \hat{Y}_t^{1, \m} -\frac{1}{\gamma} \Big) - \epsilon.
\end{equation*}
Hence, we can conclude that the $\epsilon$ in \eqref{paper 3 mean field fbode} can be removed for all $j \in \mathbb{N} \,\backslash\, \{1\}$, rendering system \eqref{paper 3 mean field fbode} linear:
\begin{equation*}
     dQ_t^{j, \e} = \frac{1}{2 \, \beta_t} \, \Big( Y_t^{j, \e} - \hat{Y}_t^{1, \m} -\frac{1}{\gamma} \Big) \,dt, \quad Q_0^{j, \e}=q_0^{j, \e}; \quad Y_t^{j, \m} = -2A \, Q_T^{j,\e}.
\end{equation*}
Similarly, the (unique) solution of above system accepts the affine representation $Y_t^{j,\e} = \mathcal{A}_t^j \, Q_t^{j,\e} + \mathcal{B}_t^j$, where $\mathcal{A}^j$ and $\mathcal{B}^j$ solve
\begin{equation}
\begin{aligned}
    d\mathcal{A}_t^j &= -\frac{1}{2 \, \beta_t}\,(\mathcal{A}_t^j)^2 \, dt, \quad \mathcal{A}_T^j = -2A;\\
    d\mathcal{B}_t^j &= \frac{\mathcal{A}_t^j}{2 \, \beta_t} \, \big( \hat{Y}_t^{1, \m} + \frac{1}{\gamma} - \mathcal{B}_t^j \big) \, dt, \quad \mathcal{B}_T^j = 0.
\end{aligned}
\label{paper 3 alpha and beta}
\end{equation}
While system \eqref{paper 3 alpha and beta} is independent of the index, we can write $\mathcal{A}$ and $\mathcal{B}$ for short. Since \eqref{paper 3 alpha and beta} has a unique bounded solution, it follows
\begin{equation*}
    Y_t^{j, \e} = Y_0^{j, \e} = \mathcal{A}_0 \, q_0^{j,\e} + \mathcal{B}_0.
\end{equation*}
Because for agent $(1, \e)$ we also have
\begin{equation*}
    \hat{Y}_t^{1,\e} =  \mathcal{A}_0 \, q_0^{1,\e} + \mathcal{B}_0,
\end{equation*}
the ansatz \eqref{paper 3 mean field ansatz} is a result of the law of large numbers.
\end{proof}

\kong

For convenience in the discussion, we pick
\begin{equation*}
    \epsilon = \frac{\mathfrak{p}}{4 \, \bar{\beta}} \, \Big( -q_0^{1, \e} + q_0^{1, \m} - \frac{1}{2 A \gamma} \Big).
\end{equation*}
To verify condition \eqref{paper 3 iid lower bound} more directly, we can combine it with the estimate \eqref{paper 3 low trun} to introduce a more stringent condition. Indeed, since 
    \begin{equation*}
       \frac{\mathfrak{p}}{4 \, \beta_t} \, \Big( -q_0^{1, \e} + q_0^{1, \m} - \frac{1}{2 A \gamma} \Big) \leq \frac{1}{2\, \beta_t} \, \Big( \hat{Y}_t^{1, \e} - \hat{Y}_t^1 -\frac{1}{\gamma} \Big) - \epsilon,
    \end{equation*}
a sufficient condition for \eqref{paper 3 iid lower bound} would be
\begin{equation}
    q_0^{j, \e}  - q_0^{1, \e} \leq \frac{\mathfrak{p}}{4A} \, \big( -q_0^{1, \e} + q_0^{1, \m} - \frac{1}{2 A \gamma} \big) 
    \label{paper 3 iid low bound 2}
\end{equation}
for any $j \in \mathbb{N} \,\backslash\, \{1\}$. In practice, the optimal execution problem is concerned with scenarios where there is an intention to trade a substantial volume of assets. This implies that $-q_0^{1, \e} \gg 0$ and also $-q_0^{1, \e} \gg |q_0^{1, \m}|$. Otherwise, the market maker essentially becomes another distressed trader, who primarily focuses on reducing her inventory to zero in fear of inventory penalties. Assumption \ref{paper 3 assum q^e} is thus reasonable from a practical standpoint. From \eqref{paper 3 iid low bound 2} we can also see that: the greater the value $-q_0^{1, \e}$ is, the more `freedom' the random variable $q_0^{j, \e}$ enjoys.

\vspace{0.2cm}

\section{Approximation Game}
\label{paper 3 section 5}
\noindent The challenge in the general stochastic game between executors and market makers lies in the system \eqref{paper 3 big FBSDE market maker}-\eqref{paper 3 big FBSDE optimal execution}. Even in the Almgren-Chriss-Avellaneda-Stoikov model, the BSRE
characterizing the well-posedness of the FBSDE system is beyond the scope of current literature. With this motivation, we introduce an approximate game to circumvent this issue. On the other hand, the market-making competition discussed in the preceding sections adheres to the style in \cite{guo2024macroscopicmarketmakinggames}. Competitions of such kind are rarely studied, with two notable recent exception \cite{cont2022dynamics} and \cite{luo2021dynamic}. Their approach will also be considered in this section. Let us start by the following definition.

\kong

\begin{definition}
 A set of functions $(\zeta^i)_{i=1}^N$ belongs to the class $\beth$ if the following holds for all $i$:   
\begin{itemize}
    \item[1.] function $\zeta^i: \mathbb{R}^N \to \mathbb{R}_+$ is twice continuously differentiable;\\
    \vspace{-0.2cm}

    \item[2.] for all $(\delta^1, \dots, \delta^N) \in \mathbb{R}^N$, it holds that
    \begin{equation*}
        \frac{\partial \zeta^i}{\partial \delta^i} < 0, \quad \frac{\partial \zeta^i}{\partial \delta^j} \geq 0, \quad \text{and \;} \zeta^i \cdot \frac{\partial^2 \zeta^i}{\partial (\delta^i)^2} \leq 2 \, \big( \frac{\partial \zeta^i}{\partial \delta^i} \big)^2
    \end{equation*}
    for $j \neq i$;\\
    \vspace{-0.2cm}

    \item[3.] for all $(\delta^1, \dots, \delta^N) \in \mathbb{R}^N$, it holds that
    \begin{equation}
        \Big(\frac{\partial \zeta^i}{\partial \delta^{i}} \Big)^{-2} \cdot \bigg\{ 2 \, \Big( \frac{\partial \zeta^i}{\partial \delta^{i}} \Big)^2 - \zeta^i \, \frac{\partial^2 \zeta^i}{\partial (\delta^{i})^2} - \sum_{k \neq 1} \big| \frac{\partial \zeta^i}{\partial \delta^{i}} \, \frac{\partial \zeta^i}{\partial \delta^{k}} - \zeta \, \frac{\partial^2 \zeta^i}{\partial \delta^{1} \partial \delta^{k}} \big|  \bigg\} \geq C
        \label{paper 3 market maker growth cond}
    \end{equation}
    for some $C > 0$.
\end{itemize}
\label{paper 3 inten_assu extend}
\end{definition}

\kong

\begin{remark}
    Compared with the discussion of Section 2 \ref{paper 3 section 3}, the Definition \eqref{paper 3 inten_assu extend}---borrowed and revised from \cite{luo2021dynamic} and \cite{cont2022dynamics}---essentially introduces a different description of market makers' competition. Indeed, in previous discussions the agent competes with the one who provides the best price throughout the time, while the above definition infers that the agent will contend against all the others in a pre-specified manner.

    For any $i$, function $\zeta^i$ returns the portion of the order flow captured by market maker $i$. The intuition follows similarly: the portion decreases with respect to the gap of the agent $i$, but increases with respect to the gaps of her competitors. Inequality \eqref{paper 3 market maker growth cond} is a technical condition for the implicit function theorem. Our first example would be
    \begin{equation*}
        \zeta^i(\delta^1, \dots, \delta^N) = \frac{e^{-\varsigma \, \delta^i + o^i}}{\sum_{k=1}^N e^{-\varsigma \, \delta^k + o^k}} = \Big( 1 + \sum_{k \neq i} e^{-\varsigma \, \delta^k + o^k + \varsigma \, \delta^i - o^i} \Big)^{-1}
    \end{equation*}
    for constants $\varsigma>0$ and $(o^i)_{i=1}^N \in \mathbb{R}^N$, which further satisfies the market clearance condition since $\sum_{j = 1}^N \zeta^j = 1$. More flexible examples can be
    \begin{equation*}
        \zeta^i(\delta^1, \dots, \delta^N) = \Lambda^i(\delta^i) \cdot \mathcal{G}^i(\delta^{-i}).
    \end{equation*}
    Here, function $\Lambda^i: \mathbb{R} \to \mathbb{R}_+$ is a twice continuously differentiable decreasing function, such that 
    \begin{equation*}
        \frac{\Lambda^i \cdot \frac{\partial^2 \Lambda^i}{\partial \delta^2}}{\big( \frac{\partial \Lambda^i}{\partial \delta} \big)^2} \leq 2 - \epsilon
    \end{equation*}
    for some $\epsilon > 0$, and function $\mathcal{G}^i: \mathbb{R}^{N - 1} \to \mathbb{R}_+$ is twice continuously differentiable and increasing in all variables, satisfying $\inf_{\boldsymbol{\delta}}\mathcal{G}^i(\boldsymbol{\delta})>0$.
\end{remark}

\kong

\noindent Consider $N \in\mathbb{N}$ market makers indexed by $(i, \m)$. Given any admissible strategy $\boldsymbol{\delta}^i \in \mathbb{A}^\m \times \mathbb{A}^\m$ as before, let us write $\boldsymbol{\delta}^a:=(\delta^{1,a}, \dots, \delta^{N,a})$ and $\boldsymbol{\delta}^b$ is similarly defined. The inventory and cash of market maker $(i, \m)$ read
\begin{gather*}
    X_t^{i, \m} = \int_0^t(P_u + \delta_u^{i,a}) \cdot \tilde{a}_u \cdot \zeta^i \big( \boldsymbol{\delta}^a_u \big) \, du - \int_0^t (P_u - \delta_u^{i,b}) \cdot \tilde{b}_u \cdot \zeta^i \big( \boldsymbol{\delta}^b_u \big) \, du,\\
    Q_t^{i, \m} = q_0^{i, \m} - \int_0^t \tilde{a}_u \cdot \zeta^i \big( \boldsymbol{\delta}^a_u \big) \, du + \int_0^t \tilde{b}_u \cdot \zeta^i \big( \boldsymbol{\delta}^b_u \big) \, du  + \epsilon \, W_t^{i, \m},
    \nonumber   
\end{gather*}
where $\epsilon > 0$ is some constant and $\vec{W}^\m := (W^{1, \m}, \dots, W^{N, \m})$ consists of $N$ independent Brownian motions. Processes $\Tilde{a}, \tilde{b}$ will be specified later on. The player $(i, \m)$ aims at maximizing the similar objective functional
\begin{equation*}
\begin{aligned}
    &J^{i, \m} ( \boldsymbol{\delta}^i ; \boldsymbol{\delta}^{-i}, \boldsymbol{v}^\e )\\
    :&=\mathbb{E}\Big[X_T^{i, \m} + P_T \, Q_T^{i, \m} - \int_0^T \phi_t^{i, \m} \, \big( Q_t^{i, \m} \big)^2 \, dt - A^{i, \m}\,\big(Q_T^{i, \m} \big) ^2 \Big]\\
     &= P_0 \,q_0^{i, \m} + \mathbb{E} \Big[ \int_0^T d\langle P_{\cdot}, \, \epsilon \, W_{\cdot}^{i, \m} \rangle_t \Big]\\
     & \; + \mathbb{E}\Big[\int_0^T \Big( \delta_t^{i,a} \, \tilde{a}_t \, \zeta^i \big( \boldsymbol{\delta}^a_t \big) + \delta_t^{i,b} \, \tilde{b}_t \, \zeta^i \big( \boldsymbol{\delta}^b_t \big) \Big) \, dt - \int_0^T \phi_t^{i, \m} \, \big( Q_t^{i, \m} \big)^2\,dt - A^{i, \m} \, \big( Q_T^{i, \m} \big)^2 \Big].
\end{aligned}
\end{equation*}

\noindent Simultaneously, the market includes $N$ traders indexed by indices $\{(i, \e)\}_{i = 1}^N$. Again, we assume the same number of population for notational convenience. Intending to trade $q_0^{i, \e} \neq 0$ amount of assets, the inventory and cash of agent $(i, \e)$ now follow 
\begin{gather*}
    Q_t^{i,\e} = q_0^{i, \e} + \int_0^t v_u^{i, \e} \, du + \epsilon \, W_t^{i,\e},\\
    X_t^{i, \e} = -\int_0^t \Big( S_u^{i,\e} \, v_u^{i,e} + \lambda^i(\boldsymbol{v}_u^{\e}) \Big) \, du,
\end{gather*}
where $v^{i, \e}\in\mathbb{A}^{i,\e}$ represents the trading strategy, $S^{i,\e}$ indicates the market price in view of agent $(i,\e)$---see \eqref{paper 3 different market price}, and $(\lambda^i)_{i=1}^N \in \Upsilon$ as previously stated. Here, process $\vec{W}^\e := (W^{1, \e}, \dots, W^{N, \e})$ consists of $N$ independent Brownian motions that are also independent of $\Vec{W}^\m$. The agent $(i,\e)$ aims at maximizing the functional

\begin{equation*}
\begin{aligned}
    J^{i, \e}(v^i &; v^{-i}, (\boldsymbol{\delta}^{j})_{j = 1}^N)\\
    :& = \mathbb{E}\Big[X_T^{i,\e} + P_T \, Q^{i,\e}_T - \int_0^T \phi_t^{i, \e} \, \big( Q_t^{i,\e} \big)^2\,dt - A^{i, \e}\, \big(Q_T^{i, \e} \big)^2 \Big]\\
    & = P_0 \, q_0^{i, \e} + \mathbb{E} \Big[ \int_0^T d\langle P_{\cdot}, \, \epsilon \, W_{\cdot}^{i, \e} \rangle_t \Big]\\
    &\hspace{1.5cm} - \mathbb{E} \Big[ \int_0^T \Big( \mathbb{I}(q_0^{i,\e} < 0) 
    \, v_t^{i,\e} \min_{1 \leq j \leq N} \delta^{j, a}_t + \mathbb{I}(q_0^{i,\e} > 0) \, v_t^{i,\e}  \min_{1 \leq j \leq N} \delta^{j, b}_t \Big) \, dt\Big].\\
    & \hspace{2.4cm} - \mathbb{E} \Big[  \int_0^T \lambda^i(\boldsymbol{v}_t^{\e}) \, d_t + \int_0^T \phi_t^{i, \e} \, \big( Q_t^{i,\e} \big)^2\,dt + A^{i, \e}\, \big(Q_T^{i, \e} \big)^2 \Big].
\end{aligned}
\end{equation*}
Finally, processes $\Tilde{a}$ and $\Tilde{b}$ are defined as
\begin{equation*}
\begin{aligned}
        \Tilde{a}_t &= \kappa^{a}(L_t) + \sum_{i = 1}^N v_t^{i,\e} \, \mathbb{I}(q_0^{i,e} < 0),\\
        \Tilde{b}_t &= \kappa^{b}(L_t) - \sum_{i = 1}^N v_t^{i,\e} \, \mathbb{I}(q_0^{i,e} > 0),
\end{aligned}
\end{equation*}
where $L$ is the (unique) solution of the stochastic differential equation
\begin{equation}
    dL_t = \Gamma(t, L_t) \, dt + \Sigma(t, L_t) \, d\vec{W}_t^0, \hspace{1cm} L_0 = l_0 \in \mathbb{R}^N,
    \label{paper 3 noise sde}
\end{equation}
for continuous functions $\Gamma : [0, T] \times \mathbb{R}^N \to \mathbb{R}^N$ and $\Sigma : [0, T] \times \mathbb{R}^N \to \mathbb{R}^{N \times N}$. Here, process $\vec{W}^0$ is a $N$-dimensional Brownian motion independent of both $\Vec{W}^\e$ and $\Vec{W}^\m$. Again, we set the same dimension for convenience. Properties of functions $\kappa^a, \kappa^b: \mathbb{R}^N \to \mathbb{R}_+$ will be specified in the following assumption. Moreover, the original Brownian motion $W$ is defined as $W := (\Vec{W}^0, \Vec{W}^\e, \Vec{W}^\m)$.

\kong

\begin{assumption}
(1) Functions $\Gamma$ and $\Sigma$ also satisfy the following conditions:
\kong
\begin{itemize}
\item for $G\in\{\Gamma, \Sigma \}$, there exists a constant $C > 0$ such that
\begin{equation*}
    |G(t,x)-G(t,y)|\leq C \, |x-y|;
\end{equation*}
for all $t\in[0,T]$ and $x,y\in\mathbb{R}^N$;\\
\vspace{-0.2cm}

\item function $\Sigma$ is uniformly elliptic in the sense that, for any $t \in[0, T]$ and $x\in \mathbb{R}^N$, it holds that $(\Sigma \Sigma^*)(t,x) \geq C^{-1} I_N$ in the sense of symmetric matrices, where $C>0$ is some constant and $I_N$ is the $N$-dimensional identity matrix;\\
\vspace{-0.2cm}

\item there exists $C > 0$ such that $|\Gamma(t, x)| \leq C$ for all $t$ and $x$.
\end{itemize}

\kong

(2) If $G\in\{\kappa^a, \kappa^b \}$, then $G$ is a positive-valued function such that there exists some constant $C>0$ satisfying
\begin{equation*}
    |G(x) - G(y)| \leq C \, |x-y| \text{ \; and \; } |G(x)| \leq C
\end{equation*}
for all $x, y \in \mathbb{R}^N$.\\
\vspace{-0.2cm}

(3) In this section, we set all penalties (which are all $\phi$s and $A$s) to be deterministic. Generalizations can be made at the cost of heavier notations.
\label{paper 3 sde_assumption}
\end{assumption}

\kong

Our goal is to find the Nash equilibrium. Although diffusion terms have been added to the inventory dynamics, they are not controlled and in fact have no influence on the Hamiltonian of every agent. Hence, the Nash equilibrium can be similarly characterized by an FBSDE system.

\kong

\begin{theorem}
    The strategy profile $\big( \hat{\boldsymbol{v}}^\e, (\hat{\boldsymbol{\delta}}^j)_{j = 1}^N \big) \in \big( \Pi_{j = 1}^N \mathbb{A}^{j, \e} \big) \times (\mathbb{A}^\m \times \mathbb{A}^\m)^N$ forms a Nash equilibrium if and only if
    \begin{equation*}
        \hat{v}^{j, \e}_t = \varphi^j(\boldsymbol{Y}_t^\e, \boldsymbol{Y}_t^\m), \quad \hat{\delta}^{i,a}_t = \psi^{i,a}(\boldsymbol{Y}_t^\m), \text{\quad and \quad} \hat{\delta}^{i,b}_t = \psi^{i,b}(\boldsymbol{Y}_t^\m)
    \end{equation*}
    for all $i,j \in \{1, \dots, N\}$, where $\psi^a, \psi^b: \mathbb{R}^N \to \mathbb{R}^N$ and $\varphi: \mathbb{R}^{2N} \to \mathbb{R}^N$ are some Lipschitz functions. Here, adjoint processes $\boldsymbol{Y}^\m$ and $\boldsymbol{Y}^\e$ solve the FBSDE system
    \begin{equation}
    \left\{
    \begin{aligned}
     dQ_t^{i, \m} &= - \hat{a}_t \, \zeta^i \big(\psi^{a}(\boldsymbol{Y}_t^\m) \big) \, dt + \hat{b}_t \, \zeta^i \big( \psi^{b}(\boldsymbol{Y}_t^\m) \big) \, dt + \epsilon \,dW_t^{i,\m},\\
    \, dY_t^{i, \m} &= 2\phi_t^{i, \m} \, Q_t^{i, \m} \, dt + dM_t^{i, \m},\\
    Q_0^{i, \m} &= q_0^{i, \m}, \quad Y_T^{i, \m} = -2A^{i,\m} \, Q_T^{i,\m};
    \end{aligned}
    \right.
    \label{paper 3 big FBSDE market maker approx}
    \end{equation}
    \begin{equation}
        \left\{
    \begin{aligned}
     dQ_t^{j, \e} &= \varphi^j(\boldsymbol{Y}_t^\e, \boldsymbol{Y}_t^\m) \, dt + \epsilon \, dW_t^{j,\e},\\
    \, dY_t^{j, \e} &= 2\phi_t^{j, \e} \, Q_t^{j, \e} \, dt + dM_t^{j, \e},\\
    Q_0^{j, \e} &= q_0^{j, \e}, \quad Y_T^{j, \m} = -2A^{j,\e}\,Q_T^{j, \e},
    \end{aligned}
    \right.
    \label{paper 3 big FBSDE optimal execution approx}
\end{equation}
for all $i,j$, where $\hat{a}_t, \hat{b}_t$ are defined as
\begin{equation*}
\begin{aligned}
    \hat{a}_t &= \kappa^a(L_t) + \sum_{i = 1}^N \varphi^i(\boldsymbol{Y}_t^\e, \boldsymbol{Y}_t^\m) \, \mathbb{I}(q_0^{i,e} < 0),\\
    \hat{b}_t &= \kappa^b(L_t) - \sum_{i = 1}^N \varphi^i(\boldsymbol{Y}_t^\e, \boldsymbol{Y}_t^\m) \, \mathbb{I}(q_0^{i,e} > 0).
\end{aligned}
\end{equation*}
\end{theorem}

\begin{proof}
In view of objective functionals, the addition of diffusion terms invites an extra term that is indifferent to the strategies. Combined with the fact that diffusion terms are not controlled, the Hamiltonian of each agent remains the same. The proof basically follows the line of Theorem \ref{paper 3 big maximum principle}, while the only difference lies in the new function $(\zeta^i)_{i=1}^N$. Let the strategy profile $\big( \hat{\boldsymbol{v}}^\e, (\hat{\boldsymbol{\delta}}^j)_{j = 1}^N \big)$ be a Nash equilibrium.
Given the trading profile $\hat{\boldsymbol{v}}^\e$, the Hamiltonian of market maker $(i, \m)$ reads
\begin{equation*}
    \Big( - \tilde{a}_t \, \zeta^i \big( \boldsymbol{\delta}^{a} \big) + \tilde{b}_t \, \zeta^i \big(\boldsymbol{\delta}^{b} \big) \Big) \, y^{i, \m} + \delta^{i,a} \cdot \tilde{a}_t \cdot \zeta^i \big( \boldsymbol{\delta}^{a} \big) + \delta^{i,b} \cdot \tilde{b}_t \cdot \zeta^i \big( \boldsymbol{\delta}^{b} \big) - \phi_t^{i, \m} \, \big( q^{i, \m} \big)^2.
\end{equation*}
Take the ask side for example. Equivalently, we intend to find $\delta^{i, a}$ that maximizes 
\begin{equation*}
    - \zeta^i \big( \boldsymbol{\delta}^{a} \big) \, y^{i, \m} + \delta^{i,a} \, \zeta^i \big( \boldsymbol{\delta}^{a} \big),
\end{equation*}
of which the derivative with respect to $\delta^{i,a}$ reads
\begin{equation}
    \frac{\partial \zeta^i}{\partial \delta^{i,a}} \big( \boldsymbol{\delta}^{a} \big) \cdot \Big[ \delta^{i,a} + \frac{ \zeta^i \big( \boldsymbol{\delta}^{a} \big)}{\frac{\partial \zeta^i}{\partial \delta^{i,a} } \big( \boldsymbol{\delta}^{a} \big)} - y^{i,\m} \Big].
    \label{paper 3 maker deriva}
\end{equation}
Properties of $\zeta^i$ infers the square bracket part of \eqref{paper 3 maker deriva} is increasing in $\delta^{i, a}$. Hence, the first order condition and the truncation by $\xi$ yield 
\begin{equation}
    \delta^{i,a} - \Big( y^{i,\m} - \frac{ \zeta^i \big( \boldsymbol{\delta}^{a}\big) }{ \frac{ \partial \zeta^i }{\partial \delta^{i,a} } \big(\boldsymbol{\delta}^{a} \big)} \Big) \vee (-\xi) \wedge \xi = 0.
    \label{paper 3 maker hamilt}
\end{equation}
Because \eqref{paper 3 maker hamilt} should apply for every $(i,\m)$, we have
\begin{equation}
    \mathfrak{F}^\m(\boldsymbol{\delta}^a, \boldsymbol{y}^\m) = 0,
    \label{paper 3 maker implicit function}
\end{equation}
where the $i$-th entry of function $\mathfrak{F}^\m: \mathbb{R}^{N} \times \mathbb{R}^{N} \to \mathbb{R}^{N}$ is given by the left hand side of \eqref{paper 3 maker hamilt}. In view of the proof in Theorem \ref{paper 3 first character}, to apply the implicit function theorem it suffices to prove that $\nabla_{\boldsymbol{\delta}^a}\mathfrak{F}^\m (\boldsymbol{\delta}^a, \boldsymbol{y}^\m)$
has positive diagonals and the diagonal dominance gap is bounded away from $0$,  whenever differentiable. Cases when truncation $\pm \xi$ takes into effect are straightforward. Let us then pay attention to the untruncated case. Observe that
\begin{equation*}
    \frac{\partial \mathfrak{F}^{i,\m}}{\partial \delta^{i,a}} = 2 - \frac{\zeta^i \big( \boldsymbol{\delta}^{a} \big) \cdot \frac{\partial^2 \zeta^i}{\partial (\delta^{i,a})^2} \big( \boldsymbol{\delta}^{a}\big) }{ \big[ \frac{\partial \zeta^i}{\partial \delta^{i,a}} \big( \boldsymbol{\delta}^{a}\big) \big]^2} > 0
\end{equation*}
and
\begin{equation*}
     \frac{\partial \mathfrak{F}^{i,\m}}{\partial \delta^{k,a}} = \frac{\frac{\partial \zeta^i}{\partial \delta^{k, a}} \big( \boldsymbol{\delta}^{a} \big)}{\frac{\partial \zeta^i}{\partial \delta^{i,a}} \big( \boldsymbol{\delta}^{a} \big) } - \frac{\zeta^i \big( \boldsymbol{\delta}^{a} \big) \cdot \frac{\partial^2 \zeta^i}{\partial \delta^{i,a} \partial \delta^{k,a}} \big( \boldsymbol{\delta}^{a}\big)}{ \big[ \frac{\partial \zeta^i}{\partial \delta^{i,a}} \big( \boldsymbol{\delta}^{a} \big) \big]^2}
\end{equation*}
for $k\neq 1$. Calculating
\begin{equation*}
\begin{aligned}
    \frac{\partial \mathfrak{F}^{i,\m}}{\partial \delta^{i,a}} &- \sum_{k \neq i}  \big| \frac{\partial \mathfrak{F}^{i,\m}}{\partial \delta^{k,a}} \big| \\
    &= \Big( \frac{\partial \zeta^i}{\partial \delta^{i,a}} \Big)^{-2} \cdot \bigg\{ 2 \, \Big(\frac{\partial \zeta^i}{\partial \delta^{i,a}} \Big)^2 - \zeta^i \, \frac{\partial^2 \zeta^i }{\partial (\delta^{i,a})^2} - \sum_{k \neq i} \big| \frac{\partial \zeta^i}{\partial \delta^{i, a}} \, \frac{\partial \zeta^i}{\partial \delta^{k, a}} - \zeta^i \, \frac{\partial^2 \zeta^i}{\partial \delta^{i,a} \, \partial \delta^{k,a}} \big|   \bigg\},
\end{aligned}
\end{equation*}
the gap computed above is bounded away from $0$ according to the definition of $\zeta^i$. Therefore, by the implicit function theorem, we know there exists a unique Lipschitz mapping $\psi^{a}: \mathbb{R}^{N} \to \mathbb{R}^{N}$ such that \eqref{paper 3 maker implicit function} is equivalent to
\begin{equation*}
   \boldsymbol{\delta}^a = \psi^a (\boldsymbol{y}^\m).
\end{equation*}
The bid side can be discussed in a similar way and we obtain the (unique) Lipschitz mapping $\psi^{b}: \mathbb{R}^{N} \to \mathbb{R}^{N}$ such that $\boldsymbol{\delta}^b = \psi^b( \boldsymbol{y}^\m )$. By stochastic maximum principle, the adjoint processes $\boldsymbol{Y}^\m$ solves the FBSDE
\begin{equation*}
    \left\{
    \begin{aligned}
     dQ_t^{i, \m} &= - \tilde{a}_t \, \zeta^i \big(\psi^{a}(\boldsymbol{Y}_t^\m) \big) \, dt + \tilde{b}_t \, \zeta^i \big(\psi^{b}(\boldsymbol{Y}_t^\m) \big) \, dt + \epsilon \,dW_t^{i,\m},\\
    \, dY_t^{i, \m} &= 2\phi_t^{i, \m} \, Q_t^{i, \m} \, dt + dM_t^{i, \m},\\
    Q_0^{i, \m} &= q_0^{i, \m}, \quad Y_T^{i, \m} = -2A^{i,\m} \, Q_T^{i,\m},
    \end{aligned}
    \right.
\end{equation*}
leading to the equilibrium profile $(\psi^a (\boldsymbol{Y}_t^\m), \psi^b (\boldsymbol{Y}_t^\m))_{t\in[0,T]}$. Here, we assume the global solution exists, which will be proved soon.

The rest follows the proof of Theorem \ref{paper 3 big maximum principle}. Provided with the quoting strategy profile $(\psi^a (\boldsymbol{Y}_t^\m), \psi^b (\boldsymbol{Y}_t^\m))_{t \in [0, T]}$, the traders engage in an optimal execution game. There exist a Lipschitz mapping $\varphi: \mathbb{R}^N \times \mathbb{R}^N \to \mathbb{R}^N$ such that the equilibrium trading profile satisfies
\begin{equation*}
    v_t^{i,\e} = \varphi^i(\boldsymbol{Y}_t^\e, \boldsymbol{Y}_t^\m)
\end{equation*}
where the adjoint processes solve the FBSDE
\begin{equation*}
        \left\{
    \begin{aligned}
     dQ_t^{i, \e} &= \varphi^i(\boldsymbol{Y}_t^\e, \boldsymbol{Y}_t^\m) \, dt + \epsilon \, dW_t^{i, \e},\\
    \, dY_t^{i, \e} &= 2\phi_t^{i, \e} \, Q_t^{i, \e} \, dt + dM_t^{i, \e},\\
    Q_0^{i, \e} &= q_0^{i, \e}, \quad Y_T^{i, \m} = -2A^{i,\e}\,Q_T^{i, \e},
    \end{aligned}
    \right.
\end{equation*}
for all $i$. A fixed point argument completes the proof.
\end{proof}

\kong

Although the FBSDE system \eqref{paper 3 big FBSDE market maker approx}-\eqref{paper 3 big FBSDE optimal execution approx} is non-Markovian due to the noise $L$, the extended system \eqref{paper 3 noise sde}-\eqref{paper 3 big FBSDE optimal execution approx} is Markovian if we regard \eqref{paper 3 noise sde} as a $N$-dimensional trivial FBSDE. Moreover, the extended system is non-degenerate because of the additional diffusion terms. The combination of non-degeneracy and Markovian nature enables us to apply tools from a more extensive literature.

\begin{theorem}
    System \eqref{paper 3 noise sde}-\eqref{paper 3 big FBSDE optimal execution approx} has a unique bounded solution.
\end{theorem}

\begin{proof}
Let us consider \eqref{paper 3 noise sde} as a $N$-dimensional trivial FBSDE, where the backward process is zero. Then, the extended system \eqref{paper 3 noise sde}-\eqref{paper 3 big FBSDE optimal execution approx} is Markovian. The complexity of our system lies in the forward equation. For the market making system \eqref{paper 3 big FBSDE market maker approx}, the drift caused by the ask side is the product of
\begin{equation*}
    -\hat{a}_t \text{ \; with \; } \zeta^i \big(\psi^{a}(\boldsymbol{Y_t}^\m)\big),
\end{equation*}
where $\hat{a}_t = \kappa^a(L_t) + \sum_{i = 1}^N \varphi^{i} \big( \boldsymbol{Y}^\e_t, \boldsymbol{Y}^\m_t \big) \, \mathbb{I}(q_0^{i,e} < 0)$. In precis, process $\hat{a}$ can be regard as a function of $L, \boldsymbol{y}^\m$, and $\boldsymbol{y}^\e$. Based on Lipschitz property of $\kappa^a$ and $\varphi$, it follows that $\hat{a}$ is Lipschitz with respect to $L$, $\boldsymbol{y}^\m$, and $\boldsymbol{y}^\e$. On the other hand, in spite of unbounded derivatives, the truncation in the definition of $\psi^a$ allows us to treat $\zeta^i$ as a Lipschitz function. Consequently, function $\zeta^i (\psi^{a}(\boldsymbol{y}^\m))$ is Lipschitz in $\boldsymbol{y}^\m$. Moreover, the truncation $\tilde{\xi}$ and boundedness of $\kappa^a$ infers that $\hat{a}$ is also bounded; similarly the truncation $\xi$ guarantees the boundedness of $\zeta^i (\psi^{a}(\boldsymbol{y}^\m))$. Being aware that the product of bounded Lipschitz functions is still Lipschitz, we obtain the Lipschitz property of the ask-side drift with respect to $L, \boldsymbol{y}^\m$, and $\boldsymbol{y}^\e$. After a similar discussion on the bid side, the forward equation of \eqref{paper 3 big FBSDE market maker approx} is hence Lipschitz. Part of previous discussion already implies the forward equation of \eqref{paper 3 big FBSDE optimal execution approx} is Lipschitz regarding both $\boldsymbol{y}^\e$ and $\boldsymbol{y}^\m$. 

Introduce the extended forward process $\bdX_t := (L_t, \boldsymbol{Q}_t^\e, \boldsymbol{Q}_t^\m)$ and backward process $\bdY_t = ( \Vec{0}, \bdY^\e_t, \bdY^\m_t)$. Define the following vector-valued functions and matrix-valued functions:
\begin{equation*}
\begin{aligned}
    g^\m (L, \boldsymbol{y}^\e, \boldsymbol{y}^\m) &= 
    \begin{pmatrix}
        -\hat{a} \, \zeta^1 \big(\psi^{a}(\boldsymbol{y}^\m)\big) + \hat{b} \, \zeta^1 \big( \psi^{b}(\boldsymbol{y}^\m) \big)  \\
        \vdots \\
        -\hat{a} \, \zeta^N \big(\psi^{a}(\boldsymbol{y}^\m)\big) + \hat{b} \, \zeta^N \big( \psi^{b}(\boldsymbol{y}^\m) \big)\\
    \end{pmatrix}, \quad
    g (t, L, \boldsymbol{y}^\e, \boldsymbol{y}^\m) =
    \begin{pmatrix}
        \Gamma(t, L) \\
        \varphi(\boldsymbol{y}^\e, \boldsymbol{y}^\m) \\
        g^\m (L, \boldsymbol{y}^\e, \boldsymbol{y}^\m)
    \end{pmatrix},\\
    \sigma(t, L) &= \begin{bmatrix}
        \Sigma(t, L) & \boldsymbol{0}\\
        \boldsymbol{0} & \epsilon \, I_{N+N}
    \end{bmatrix},\\
    k^\m(t) & = \begin{bmatrix}
    \phi_t^{1,\m} & &\\
     & \ddots & \\
    & & \phi_t^{N,\m}
  \end{bmatrix}, \;
  k^\e(t) = \begin{bmatrix}
    \phi_t^{1,\e} & &\\
     & \ddots & \\
    & & \phi_t^{N,\e}
  \end{bmatrix}, \; k(t) = \begin{bmatrix}
    \boldsymbol{0} & & \\
    & k^\e(t) & \\
    & & k^\m(t)
  \end{bmatrix},\\
  h^\m & = \begin{bmatrix}
    A^{1,\m} & &\\
     & \ddots & \\
    & & A^{N,\m}
  \end{bmatrix}, \; 
  h^\e = \begin{bmatrix}
    A^{1,\e} & &\\
     & \ddots & \\
    & & A^{N,\e}
  \end{bmatrix}, \; 
  h = \begin{bmatrix}
    \boldsymbol{0} & & \\
    & h^\e & \\
    & & h^\m
  \end{bmatrix}, 
\end{aligned}
\end{equation*}
where $\boldsymbol{0}$ and $I_{N \times N}$ are respectively zero and identity matrices of proper dimensions. Our FBSDE system can be concisely represented by
\begin{equation}
    \left\{
    \begin{aligned}
     d\bdX_t &= \sigma(t, \bdX_t) \cdot \sigma^{-1}(t, \bdX_t) \, g(t,\bdX_t, \bdY_t) + \sigma(t, \bdX_t) \, dW_t, \\
    \, d\bdY_t &= k(t) \, \bdX_t \, dt + dM_t,\\
    \bdX_0 &= \bdx_0, \quad \bdY_T = -2 h\, \bdX_T.
    \end{aligned}
    \right.
    \label{paper 3 non-deg concise FBSDE}
\end{equation}
We intend to apply Theorem 2.3 in \cite{nam2022coupled} for the well-posedness of \eqref{paper 3 non-deg concise FBSDE}. For the existence of solutions, we check the condition (F1) and (B1). The condition (F1) is clear based on the Lipschitz property of function $\sigma$. The observation of:
\kong
\begin{itemize}
    \item matrices $h$ and $k(t)$ are bounded linear coefficients;\\
    \vspace{-0.2cm}
    \item function $g$ is bounded and continuous in $\bdy$,
\end{itemize}
\kong
infers condition (B1). Concerning the uniqueness, the integrability of $\bdX$ is sufficient to guarantee the uniqueness of equation (4.14) in Lemma 4.1 of \cite{nam2022coupled}, implying the uniqueness of the FBSDE \eqref{paper 3 non-deg concise FBSDE}.
\end{proof}

