\section{Appendix}
\label{sec:appendices}

\subsection{Exact Steady-State Distribution Derivation}
\label{app:b}

The grain area evolution follows the stochastic differential equation:
\begin{equation}
dA = \kappa \sqrt{A} \left(1 - \frac{A}{A_{\text{max}}}\right) dt + \sigma \sqrt{A} dW_t
\end{equation}
Applying Itô's lemma to the transformation $z = \sqrt{A}$ yields:
\begin{align}
dz &= \frac{1}{2}A^{-1/2} dA - \frac{1}{8}A^{-3/2} (dA)^2 \\
&= \left[ \frac{\kappa}{2}\left(1 - \frac{z^2}{A_{\text{max}}}\right) - \frac{\sigma^2}{8z} \right] dt + \frac{\sigma}{2} dW_t
\end{align}
The stationary Fokker-Planck equation for $P(z)$ is:
\begin{equation}
0 = -\frac{d}{dz} \left[ a(z)P_{ss} \right] + \frac{1}{2} \frac{d^2}{dz^2} \left[ b^2(z)P_{ss} \right]
\end{equation}
with drift $a(z) = \frac{\kappa}{2}(1 - z^2/A_{\text{max}}) - \sigma^2/(8z)$ and diffusion $b(z) = \sigma/2$. Integrating once:
\begin{equation}
\frac{\sigma^2}{8} \frac{dP_{ss}}{dz} = \left[ \frac{\kappa}{2}\left(1 - \frac{z^2}{A_{\text{max}}}\right) - \frac{\sigma^2}{8z} \right] P_{ss}
\end{equation}
Solving the logarithmic derivative:
\begin{align}
\frac{d}{dz} \ln P_{ss} &= \frac{4\kappa}{\sigma^2} - \frac{4\kappa}{\sigma^2 A_{\text{max}}}z^2 - \frac{1}{z} \\
\implies \ln P_{ss} &= \frac{4\kappa}{\sigma^2} z - \frac{4\kappa}{3\sigma^2 A_{\text{max}}} z^3 - \ln z + C
\end{align}
Transforming back to $A = z^2$ gives the steady-state distribution:
\begin{equation}
\boxed{P_{ss}(A) = \mathcal{N} A^{-1} \exp\left( \frac{4\kappa}{\sigma^2} A^{1/2} - \frac{4\kappa}{3\sigma^2 A_{\text{max}}} A^{3/2} \right)}
\end{equation}
The distribution is normalizable: integrable at $A \to 0^+$ ($\int_0^\epsilon A^{-1} dA < \infty$) and decays exponentially as $A \to \infty$.

\subsection{Rigorous Bimodality Threshold Derivation}
\label{app:c}

The extrema of $P_{ss}(A)$ satisfy $dP_{ss}/dA = 0$:
\begin{equation}
\frac{2\kappa}{\sigma^2} A^{-1/2} - \frac{2\kappa}{\sigma^2 A_{\text{max}}} A^{1/2} - \frac{1}{A} = 0
\end{equation}
Substitute $y = \sqrt{A}$:
\begin{equation}
\frac{2\kappa}{\sigma^2} y^{-1} - \frac{2\kappa}{\sigma^2 A_{\text{max}}} y - y^{-2} = 0
\end{equation}
Multiply by $\frac{\sigma^2}{2\kappa} y^2$:
\begin{equation}
y - \frac{1}{A_{\text{max}}} y^3 - \frac{\sigma^2}{2\kappa} = 0
\end{equation}
Introduce dimensionless variables $x = y/\sqrt{A_{\text{max}}}$ and $\Pi = \sigma^2/(\kappa A_{\text{max}}^{1/2})$:
\begin{equation}
x - x^3 - \frac{\Pi}{2} = 0 \implies x^3 - x + \frac{\Pi}{2} = 0
\end{equation}
The discriminant for cubic equation $x^3 + px + q = 0$ is $\Delta = -4p^3 - 27q^2$ where $p = -1$, $q = \Pi/2$:
\begin{equation}
\Delta = -4(-1)^3 - 27(\Pi/2)^2 = 4 - \frac{27}{4}\Pi^2
\end{equation}
Bimodality occurs when $\Delta > 0$ (three real roots), with critical point at $\Delta = 0$:
\begin{equation}
\boxed{\Pi_c = \frac{4}{3\sqrt{3}} \approx 0.7698}
\end{equation}
This exact threshold represents a noise-driven phase transition where stochastic fluctuations overcome curvature-driven growth.

\subsection{Boundary Current Regularization and Scaling Law}
\label{app:d}

The probability current for grain loss at $A \to 0^+$ requires careful treatment due to the singular boundary. For Fokker-Planck equations with absorbing boundaries, the regularized flux is given by the well-established expression \cite{Gardiner2009Stochastic,Risken1996FokkerPlanck}:
\begin{equation}
J_{\text{loss}} = \frac{\kappa \sigma^2}{8} \lim_{A \to 0^+} A^{-1/2} P_{ss}(A)
\end{equation}
Physically, this represents the rate at which grains disappear due to stochastic fluctuations overwhelming the weak curvature-driven growth near the origin. The balance between nucleation and loss is:
\begin{equation}
\Gamma_0 = \frac{A_{\text{total}}}{\langle A \rangle} J_{\text{loss}}
\end{equation}
Substituting the asymptotic form $P_{ss}(A) \sim \mathcal{N} A^{-1}$:
\begin{equation}
\Gamma_0 = \frac{A_{\text{total}}}{\langle A \rangle} \cdot \frac{\kappa \sigma^2}{8} \mathcal{N} \lim_{A \to 0^+} A^{-3/2}
\end{equation}
Using physical dependencies $\sigma^2 = 2\Phi a^4$, $\rho_{\text{def}} = C_\rho \Phi^{1/2}$, and $\Gamma_0 \propto e^{-E_b/k_B T_s}$:
\begin{align}
\langle A \rangle &= \frac{\mathcal{C} \kappa^2}{\Gamma_0^2 \rho_{\text{def}}^2} \\
&= \mathcal{C}' \kappa^2 \Phi^{-1} \exp\left( +\frac{2E_b}{k_B T_s} \right)
\end{align}
where $\mathcal{C}'$ is a material constant. This resolves the scaling paradox by incorporating defect saturation and nucleation-loss balance.




