\section{Introduction}

A bounded, measurable set $A \sbt \R^d$ is called 
\emph{spectral} if it admits an orthogonal basis 
consisting of  exponential functions.
Fuglede  famously conjectured \cite{Fug74} that $A$ is a spectral set
if and only if it can tile the space by translations.
This conjecture inspired extensive research over the years,
see \cite{Kol24} for the history of the
problem and an overview of the known (positive as well as negative)
related results.

A major recent result  states that the Fuglede conjecture 
holds for convex domains in all dimensions  \cite{LM22}.
 A key role in the proof is played by the concept of weak tiling, 
 introduced in the same paper as a relaxation of proper tiling.

\begin{definition}
We say that a bounded, measurable set $A \sbt \R^d$
\emph{weakly tiles its complement}  $A^\cm = \R^d \setminus A$,
if there  exists a positive, locally finite measure $\nu$
on $\R^d$ such that $\1_{A} \ast \nu = \1_{A^\cm}$ a.e.
In this case, $\nu$ is called a \emph{weak tiling measure}
for the set $A$.
\end{definition}

If the measure $\nu$ is a sum of unit masses, then
the weak tiling becomes a proper tiling of the complement $A^\cm$
by translated copies of $A$.

The role of weak tiling in the theory of spectral sets is
due to the fact that every spectral
set must weakly tile its complement, see \cite[Theorem 1.5]{LM22}.
This can be viewed as a weak form of the
``spectral implies tile'' part of  Fuglede's conjecture.


In the present paper we revisit the notion of weak tiling, 
and establish some geometric properties of sets that weakly tile their complement.
In particular, these include all  the spectral sets, as well as the
sets which can tile properly by translations. 

In \secref{sec2} we consider the case where $A$ is a convex polytope, and give a new self-contained proof of the fact that $A$ must be centrally symmetric and have centrally symmetric facets. In \secref{sec3} we consider the case where $A\subset \R$ is a finite union of intervals, and give a necessary condition on the lengths of the gaps appearing between the intervals. Finally, in \secref{sec4} we pose some open problems.




% =========================================================



\section{Weak tiling by convex polytopes}
\label{sec2}


\subsection{}
In this section  we focus on  the case where
$A \sbt \R^d$ is a convex body, that is,
a compact, convex set with nonempty interior.
Note that  while in general, a set that weakly tiles
its complement need not tile properly, 
it was shown in \cite{KLM23} that for the
class of convex bodies weak tiling implies tiling.

\begin{thm}[{\cite[Theorem 1.4]{KLM23}}]
\label{thmCVXBWT}
    Let $A$ be a convex body in $\R^d$, and assume that
    $A$ weakly tiles its complement. Then $A$ is a convex
 polytope which can also tile $\R^d$ properly by translations.
\end{thm}

The proof of this result consists of several ingredients. First,
due to \cite{Ven54}, \cite{McM80}, in order
to prove that a convex body $A \sbt \R^d$ tiles  by translations,
 it suffices to show that $A$ satisfies the following four conditions:
\begin{enumerate-num}
\item \label{vm:i} $A$ is a convex polytope;
\item \label{vm:ii} $A$ is centrally symmetric;
\item \label{vm:iii} all the facets of $A$ are centrally symmetric;
\item \label{vm:iv} each belt of $A$ consists of either $4$ or $6$ facets.
\end{enumerate-num}



It was proved in \cite[Theorem 4.1]{LM22} that
if $A$ is a  convex body in $\R^d$, then
the weak tiling assumption implies condition \ref{vm:i}. It was also proved
\cite[Theorem 6.1]{LM22} that the
weak tiling assumption together with \ref{vm:i}, \ref{vm:ii}
and \ref{vm:iii} implies  \ref{vm:iv}.


Conditions  \ref{vm:ii} and  \ref{vm:iii} were
shown in \cite{Kol00}, \cite{KP02}, \cite{GL17}
to follow from the assumption
that the convex polytope $A$ is spectral, but these proofs
do not work if we only
assume that $A$ weakly tiles its complement.


The fact that
the weak tiling assumption together with \ref{vm:i}
implies both  \ref{vm:ii} and  \ref{vm:iii},
was proved in \cite{KLM23}, based on an elaborate machinery developed in \cite{LL21}. In fact, conditions \ref{vm:ii} and  \ref{vm:iii} were obtained as a consequence of \cite[Theorem 1.3]{KLM23},
which states that if a (convex or non-convex) polytope
$A \sbt \R^d$ weakly tiles its complement, then $A$ is equidecomposable
by translations to a cube of the same volume.



Our goal in the present section is to give a more direct and self-contained proof of
the fact that
the weak tiling condition together with \ref{vm:i}
implies both  \ref{vm:ii} and  \ref{vm:iii}.


\begin{thm}
\label{thmB1}
Let $A$ be a convex polytope in $\R^d$. If
$A$   weakly tiles its complement, then $A$ must be centrally symmetric and have
centrally symmetric facets.
\end{thm}

The proof requires some auxiliary results, which 
we will introduce first.  Then, we will proceed with
the proof of \thmref{thmB1}.


\subsection{Zero-free regions of the Fourier transform}
If $f \in L^1(\R^d)$ then 
its Fourier transform  is defined by
\begin{equation}
\label{eq:Z1.1}
\ft f (\xi)=\int_{\R^d} f (x) \, e^{-2\pi i\langle \xi,x\rangle} dx, \quad \xi \in \R^d.
\end{equation}

Given a vector $v \in \R^d$,
a positive integer $R$,  and $\eps > 0$,  we define the set
\begin{equation}
\label{eqSdef}
    S = S(v, R, \eps) =
    \{ nv + w : n \in \Z, \; |n| \notin \{1,2,\dots,R-1\}, \; w \in \R^d, \; |w|< \eps\}.
\end{equation}
The set $S$ is thus a union of open balls
of radius $\eps$ centered at integral multiples 
of the vector $v$, but only those multiples $nv$
for which either $n=0$ or $|n| \ge R$. 
We observe 
that $S(v, R, \eps)$ is contained in a cylinder of width $\eps$ along the vector $v$.



\begin{thm}
\label{thmFA}
Let $A$ be a convex polytope in $\R^d$. Assume
that $A$ is not centrally symmetric, or that at least
one of the facets of $A$ is not centrally symmetric.
Then there exist
a nonzero vector $v \in \R^d$, a positive integer $R$
and $\eps > 0$, such that
the Fourier transform $\ft{\1}_A$
has no zeros in the set $S =  S(v, R, \eps)$.
\end{thm}

\begin{proof}
This result was essentially established
in \cite[Sections 3 and 4]{GL17}. The proof is based on
Minkowski's theorem, which states that a
convex polytope $A$ is centrally symmetric
if and only if each facet $F$ of $A$
has a parallel facet $F'$ such that $|F|=|F'|$
(see, for instance, \cite[Corollary 18.1]{Gru07}).


If $A$ is not centrally symmetric, then
the   conclusion of \thmref{thmFA} 
follows from standard estimates, see 
 equation (3.5) in \cite[Section 3]{GL17}, 
 where an even larger zero-free region is given,
which is obtained from a cylinder of width $\eps$
 by the removal of a large ball around the origin.


The case where $A$ is centrally symmetric
but has a non-centrally symmetric facet, is more intricate.
In this case, the conclusion of \thmref{thmFA}
is obtained as a combination of equations (4.6), (4.15) and (4.16) in
\cite[Section 4]{GL17}.

It remains to notice that $\ft{\1}_A$ also has no zeros
in some neighborhood of the origin, which is obvious
as $\ft{\1}_A$ is a continuous function with
 $\ft{\1}_A(0) = m(A) > 0$.
\end{proof}


\subsection{Translation-bounded measures}


A (complex) measure $\mu$ on $\R^d$  is said to be \emph{translation-bounded}
 if for every (or equivalently, for some) open ball $B$ we have
\begin{equation}
\sup_{x \in \R^d} |\mu|(B+x) < +\infty.
\end{equation}
If  $\mu$ is a translation-bounded measure on $\R^d$,
then $\mu$ is a tempered distribution.

If $f$ is a function in $L^1(\R^d)$ and
$\mu$ is a translation-bounded measure on $\R^d$,
then the convolution $f \ast \mu$ is
a translation-bounded measure which is also
a locally integrable function on $\R^d$,
which can be
defined (uniquely up to equality a.e.)
by the condition that
$(f \ast \mu) \ast \varphi =
f \ast (\mu \ast \varphi)$
for every continuous, compactly supported
function $\varphi$.



If $f \in L^1(\R^d)$ then we denote by
\begin{equation}
Z(f) := \{ \xi \in \R^d : \ft{f}(\xi)=0\}
\end{equation}
the (closed) set of   zeros of 
the Fourier transform   $\ft{f}$.



\begin{thm}
\label{thmC1}
Let $f\in L^1(\R^d)$, $\int f \neq 0$,
and let $\mu$ be
a translation-bounded measure on $\R^d$.
If we have $f \ast \mu = 1$ a.e., then
$\ft{\mu} = (\int f)^{-1} \cdot \delta_0$
in the open set
$Z(f)^\complement$.
\end{thm}

\begin{proof}


This result can be proved in a similar way to
\cite[Theorem 4.1]{KL16}. The details are as follows.
First we observe that it
 suffices to prove the following claim:
Let $B$ be an open ball contained in 
$Z(f)^\cm$, and let  $\psi$ be a smooth function 
whose closed 
support is contained in $B$. Then
$\ft\mu( \psi ) = (\int f)^{-1} \psi(0)$.

To prove this, let
 $K \sbt B$ be a closed ball containing
$\supp( \psi)$. Since $\ft f$ does not vanish on $K$, then
due to Wiener's theorem
there exists  $g\in L^1(\R^d)$ such that $\ft{f}\cdot \ft{g}=1$ on $K$
(see \cite[pp.\ 150--152]{Hel10}
for a proof in the one-dimensional case; the
multi-dimensional case is similar).
There is a Schwartz  function $\varphi$ 
such that $\ft\varphi=\psi$, so this function $\varphi$  satisfies 
$\ft{\varphi}\cdot \ft{g} \cdot \ft{f}=\ft{\varphi}$.
This implies that 
$\varphi\ast g\ast f=\varphi$, hence
\begin{align}
\label{eqTB.1}
  \ft\mu(\psi)  &= \mu(\ft \psi) 
= \int \varphi(-t)d\mu(t)
=\int (\varphi \ast g\ast f )(-t) d\mu(t)\\
&=\int \Big( \int ( \varphi\ast g)(-x) f(x-t)dx \Big) d\mu(t).
\end{align}
If we can exchange the order of integrals, we obtain 
\begin{equation}
\label{eqTB.2}
  \ft\mu(\psi) =  \int 
  (\varphi\ast g) (-x) \Big( \int f(x-t) d\mu(t) \Big) dx= \int ( \varphi\ast g) (-x) dx,
\end{equation}
because the inner integral is $(f \ast \mu ) (x) $, 
which is $1$ a.e.\ by assumption. 
Furthermore,  
\begin{equation}
\label{eqTB.3}
\int (\varphi\ast g)(-x) dx=\ft\varphi(0)\ft g(0)= \ft f(0)^{-1} \ft\varphi(0)
= ({\textstyle \int f})^{-1} \psi(0),
\end{equation}
where the second equality holds since we have
$\ft{\varphi}\cdot \ft{g} \cdot \ft{f}=\ft{\varphi}$,
and $\ft f(0) = \int f \neq 0$.


It thus remains to justify the exchange of integrals.
Indeed, observe that
\begin{align}
\label{eqTB.5}
&\int \Big( \int ( |\varphi|\ast |g| ) (-x) \cdot |f(x-t)|dx \Big) |d\mu(t)| \\
& \qquad\qquad =\int (|f|\ast |g|)(-x)  \Big( \int |\varphi(x-t)| \, |d\mu(t)| \Big) dx,
\end{align}
and the latter integral is finite, 
because $|f|\ast |g|\in L^1(\R^d)$, and the inner integral is a bounded function of $x$ since 
$\varphi$ is a Schwartz function and $\mu$ is a translation-bounded measure.
This justifies the exchange of integrals and completes the proof.
\end{proof}


\subsection{}
After these preliminary results we are ready to prove the main theorem.

\begin{proof}[Proof of \thmref{thmB1}]
Let $A$ be a convex polytope in $\R^d$, 
and assume that $A$ weakly 
 tiles its complement, so there is a positive
measure $\nu$ such that
$\1_A \ast \nu = \1_{A^\complement}$ a.e.
According to \cite[Lemma 2.4]{LM22} the measure $\nu$
must be  translation-bounded. Hence the
measure $\mu := \delta_0 + \nu$ is also translation-bounded,
and satisfies $\1_A \ast \mu = 1$ a.e.
In turn, \thmref{thmC1}  implies that
$\ft{\mu} = m(A)^{-1} \cdot \delta_0$
in the open set $Z(\1_A)^\cm$.


We must prove that
$A$ is centrally symmetric and has
centrally symmetric facets.
Suppose to the contrary that this is not the case.
Then by \thmref{thmFA}
there exist
a nonzero vector $v \in \R^d$, a positive integer $R$
and $\eps > 0$, such that $\ft{\1}_A$
has no zeros in the set $S =  S(v, R, \eps)$.
It follows  that
$\ft{\mu} = m(A)^{-1} \cdot \delta_0$
in the open set $S$.

Now suppose that we are given a real-valued
Schwartz function
$g$ on $\R^d$ satisfying
\begin{equation}
\label{eqGC1}
    \supp(g) \sbt S,
    \quad
    \ft{g} \geq 0.
\end{equation}
Then we have
\begin{equation}
\label{eqGineq}
    \int_{\R^d} g(x) dx = \ft{g}(0) \leq
    \ft{g}(0) + \int \ft{g}(\xi) d \nu(\xi) =
     \int \ft{g}(\xi) d \mu(\xi),
\end{equation}
where the inequality in \eqref{eqGineq} is due to $\ft{g}$
being a nonnegative function and $\nu$
being a positive measure. On the  other hand,
we have
\begin{equation}
     \int \ft{g}(\xi) d \mu(\xi)= \mu(\ft{g}) =
     \ft{\mu}(g) = m(A)^{-1} g(0),
\end{equation}
where the last equality holds since we have
$\supp(g) \sbt S$ and
$\ft{\mu} = m(A)^{-1} \cdot \delta_0$
in the open set $S$. We conclude that
\begin{equation}
\label{eqGC2}
\int_{\R^d} g(x) dx \leq m(A)^{-1} g(0)
\end{equation}
for every real-valued Schwartz function $g$
satisfying \eqref{eqGC1}.
We will show that this leads to a contradiction,
by constructing an example of a
real-valued Schwartz function $g$ satisfying
 \eqref{eqGC1}, but such that
 \eqref{eqGC2} does not hold.

We choose a nonnegative Schwartz function $\varphi$
such that $\int \varphi =1$,
$\varphi$ is supported in
 the open ball of radius
$\eps$ centered at the origin,
and $\ft{\varphi} \geq 0$. We
 define also the trigonometric polynomial
$p_N(t) := K_N(R \, t)$,
where $K_N$ is the classical Fej\'{e}r kernel,
\begin{equation}
\label{eqFej}
K_N(t) = \sum_{|n| < N} \Big(1 - \frac{|n|}{N} \Big)
e^{2 \pi i n t}, \quad t \in \R.
\end{equation}
Then $p_N$ is nonnegative, $p_N(0) = N$,
the Fourier coefficients $\ft{p}_N(n)$,
$n \in \Z$, are also nonnegative,
$\ft{p}_N(0)=1$, and we
have  $\ft{p}_N(n)=0$ if $0 < |n| < R$.

Finally, we define the function
\begin{equation}
\label{eqGN1}
g_N(x) := \sum_{n \in \Z}
\ft{p}_N(n) \, \varphi(x - n v),
\quad x \in \R^d.
\end{equation}
Notice that there are only finitely many
nonzero terms in the sum \eqref{eqGN1}, and that the nonzero
terms correspond to integers $n$ such that either $n=0$
or $|n| \ge R$.
Hence $g_N$ is a real-valued (in fact, nonnegative)
Schwartz function such that
$\supp(g_N)$ is contained in the set
$S =  S(v, R, \eps)$. The Fourier transform
of $g_N$ is given by
\begin{equation}
\label{eqGN2}
\ft{g}_N(\xi) = \ft{\varphi}(\xi) \sum_{n \in \Z}
\ft{p}_N(n) \, e^{-2 \pi i n \dotprod{v}{\xi}}
= \ft{\varphi}(\xi) \, p_N(- \dotprod{v}{\xi}),
\end{equation}
hence $\ft{g}_N$ is a nonnegative function. We
conclude that $g_N$ satisfies the conditions
\eqref{eqGC1}.

To complete the proof
we will show that if $N$
is sufficiently large, then $g_N$ does not
satisfy \eqref{eqGC2}. Indeed, we may assume
that $\eps < \frac1{2} |v|$ which ensures
that the terms in the sum
\eqref{eqGN1} have pairwise disjoint supports.
This implies that
\begin{equation}
\label{eqGN4}
g_N(0) = \varphi(0),
\end{equation}
so that the value $g_N(0)$ does not depend on $N$.
On the other hand, using \eqref{eqGN2} we have
\begin{equation}
\label{eqGC5}
\int_{\R^d} g_N(x) dx = \ft{g}_N(0)
= \ft{\varphi}(0) p_N(0) = N,
\end{equation}
which can be arbitrarily large,
contradicting \eqref{eqGC2}. We therefore
arrive at the desired contradiction, and
\thmref{thmB1} is thus proved.
\end{proof}




