\subsection{The Agent Closure}
\label{subsec:the_agent_closure}


In this section, we focus on minimal agent-dependent type structures. We begin by defining them to then establish their existence through a constructive argument. In doing so, we provide a formal foundation for the broader concept of agent-dependent type structures.

To this end, we introduce the definition of a minimal agent-dependent type structure, which can be understood as the minimal (in a precise sense to be introduced) \say{standard} type structure that qualifies as an agent-dependent type structure while containing only the following:  
%
\begin{enumerate}[leftmargin=*,label=$\bullet$]
\item the types required to construct the CHBs of interest, as determined by the original state space under consideration, and  

\item the types necessary to ensure that the structure remains a well-defined \say{standard} type structure from a topological standpoint.  
\end{enumerate}
%
The second condition follows from the requirement that type spaces in a \say{standard} type structure must be compact and nonempty, as stipulated in \Sref{sec:background_knowledge}, and therefore also shows up in \Mref{def:agent-dependent_type_structure}.

\begin{definition}[Minimal Agent-Dependent Type Structure]
\label{def:minimal_agent-dependent_type_structure}
Given a state space $\States := \prod_{j \in \Agents} \SNatures \times \Types_j$ and an agent $i \in \Agents$, an agent-$i$-dependent type structure 
%
\begin{equation*}
\ADTypeSt^i (\Types_i) := 
\Angles { \Agents, \SNatures , \Rounds {\ADTypes^{i}_j , \ADbelfun^{i}_j }_{j \in \Agents} } \in \FamADTypeSt^i (\Types_i),
\end{equation*}
%
is \emph{minimal} if it is minimal with respect to set inclusion within $\FamADTypeSt^i (\Types_i)$, that is, if $\ADTypeSt^i (\Types_i) \subseteq \ADTypeSt^{\prime,i} (\Types_i)$ for every $\ADTypeSt^{\prime,i} (\Types_i) \in \FamADTypeSt^i (\Types_i)$.
\end{definition}

Anticipating the main result of this section, we let 
%
\begin{equation*}
\minADTypeSt^{i} (\Types_i) := 
\Angles { \Agents, \SNatures , \Rounds {\minADTypes^{i}_j , \minADbelfun^{i}_j }_{j \in \Agents} } ,
\end{equation*}
%
denote the minimal agent-$i$-dependent type structure, with $\minADStates^{i}$ denoting the corresponding minimal agent-$i$-dependent state space. Furthermore, a profile of agent-dependent type structures $\big( \ADTypeSt^j (\Types_j) \big)_{j \in \Agents}$ is \emph{minimal} if $\ADTypeSt^i (\Types_i)$ is minimal for every $i \in \Agents$, i.e., if $\ADTypeSt^i (\Types_i) = \minADTypeSt^{i} (\Types_i)$ for every $i \in \Agents$.


\begin{example}[continues=ex:misalignment, name=Taking Care of Misalignment with a Profile of Minimal Agent-Dependent Type Structures]
%
As before, we have 
%
\begin{equation*}
\States := %
\Sets { \state^1 , \state^2 } \equiv %
\SNatures \times \{\type^{\rain}_\Ann\} \times \{ \type^{\sun}_\Bob\} ,
\end{equation*}
%
as the actual state space of interest for us as analysts. Now, it is immediate to observe that regarding Ann we have 
%
%
\begin{equation*}
\minADTypeSt^{\Ann} (\Types_\Ann) := 
\Angles { \Agents, \SNatures , \Rounds {\minADTypes^{\Ann}_j , \minADbelfun^{\Ann}_j }_{j \in \Agents} } ,
\end{equation*}
%
with  
%
\begin{align*}
\minADTypes^{\Ann}_{\Ann} & := \{ \type^{\rain}_{\Ann} \} ,\\
\minADTypes^{\Ann}_{\Bob} & := \{ \type^{\rain}_{\Bob} \} ,
\end{align*}
%
and
%
\begin{align*}
\ADbelfun^{\Ann}_{\Ann} (\type^{\rain}_{\Ann}) & := 1 (\snature^\rain, \type^{\rain}_{\Bob}) ,\\
\ADbelfun^{\Ann}_{\Bob} (\type^{\rain}_{\Bob}) & := 1 (\snature^\rain, \type^{\rain}_{\Ann}) ,
\end{align*}
%
such that $\minADStates^\Ann := \{\state^{\rain}\}$. Also, regarding Bob we have
%
\begin{equation*}
\minADTypeSt^{\Bob} (\Types_\Bob) := 
\Angles { \Agents, \SNatures , \Rounds {\minADTypes^{\Bob}_j , \minADbelfun^{\Bob}_j }_{j \in \Agents} } ,
\end{equation*}
%
with  
%
\begin{align*}
\minADTypes^{\Bob}_{\Bob} & := \{ \type^{\sun}_{\Bob} \} ,\\
\minADTypes^{\Bob}_{\Ann} & := \{ \type^{\sun}_{\Ann} \} ,
\end{align*}
%
and
%
\begin{align*}
\ADbelfun^{\Bob}_{\Bob} (\type^{\sun}_{\Bob}) & := 1 (\snature^\sun, \type^{\sun}_{\Ann}) ,\\
\ADbelfun^{\Bob}_{\Ann} (\type^{\sun}_{\Ann}) & := 1 (\snature^\sun, \type^{\sun}_{\Bob}) ,
\end{align*}
%
such that $\minADStates^\Bob := \{\state^{\sun}\}$. At least intuitively, it should be clear that the profile of agent-dependent type structures is indeed minimal, \emph{and} non-common and non-degenerate.
\end{example}

Having introduced the notion of minimal agent-dependent type structure, a rather natural question to ask is if this object always exists. Anf if so, if there is a more constructive description of this object. Thus, to answer these questions, given a state space $\States := \SNatures \times T$ and an arbitrary agent $i \in \Agents$, we let
%
\begin{equation}
\label{eq:closure_operator}
\Closure_i (\States) := \SNatures \times \Types_i \times \overline{\Rounds{\bigcup_{\type_i \in \Types_i} \supp \typehom_i (\type_i) }} 
\end{equation}
%
denote the \emph{closure operator of agent} $i$ that we use to define the following notion of closure of a state space from the perspective of an agent $i$.\footnote{A similar idea is hinted in \citet[Chapter III.1.b(5), p.137]{Mertens_et_al_2015}. See also \citet{Gossner_Veiel_2024}.}


\begin{definition}[Agent Closure with Respect to a State Space]
\label{def:agent_closure}
Given a state space $\States := \prod_{j \in \Agents} \SNatures \times \Types_j$ and an agent $i \in \Agents$, the \emph{agent closure with respect to $\States$ of $i$} is the state space 
%
\begin{equation}
\label{eq:agent_closure}
\ac_i (\States) := %
\overline{\Rounds{ \bigcup_{\ell \in \Naturals} \widehat{\States}^\ell }} ,\footnote{Here, by employing standard notation, given a topological space $\ArbSet$, we let $\overline{\ArbSet}$ denote its (topological) closure.}
\end{equation}
%
inductively defined on $\Naturals$ as:
%
\begin{itemize}[leftmargin=*]
\item {$[n =1]$} $\widehat{\States}^1  := \States \cup \Closure_i (\States)$;

\item {$[n \geq 1]$} for every $n \in \Naturals$, assuming that $\widehat{\States}^{n}$ has been defined, we let
%
\begin{equation}
\label{eq:agent_closure_inductive}
\widehat{\States}^{n+1} := %
\widehat{\States}^{n} \cup \bigcup_{j \in \Agents} \Closure_j (\widehat{\States}^n) .
\end{equation}
%
\end{itemize}
\end{definition}

Letting $\ac_i (T_j)$ denote the $j$-component of $\ac_i (\States)$ for every $j \in \Agents$, we have 
%
\begin{equation*}
\ac_i (\States) = \SNatures \times \prod_{j \in \Agents} \ac_i (T_j) .
\end{equation*}
%
With an abuse of the terminology (although innocent by the result that follows), the set $\Types_i$ is the set of \emph{real types} of agent $i$, while the set of types $\ac_i (\Types_i) \setminus \Types_i$ is the set of \emph{imaginary types} of agent $i$. Moreover, an agent closure $\ac_i (\States)$ is \emph{degenerate} if $\ac_i (\States) \setminus \States = \emptyset$ and is \emph{non-degenerate} otherwise. Finally, from \Mref{rem:belief-closed_type_structure}, we let $\ADTypeSt^{i} (\ac_i (\States))$ denote agent-$i$-dependent type structure induced by $\ac_i (\States)$.

Now, we are ready to state the main result of this section, namely, that minimal agent-dependent type structures and agent closures are essentially the same, they exist, are unique, and are belief-closed. The result essentially follows from a sort of usual dual argument in order theory, which we present in detail in \Sref{subapp:proof_a_framework_for_misalignment}.

\begin{theorem}
\label{th:characterization_minimality}
Fix a state space $\States := \prod_{j \in \Agents} \SNatures \times \Types_j$. For every $i \in \Agents$,
%
\begin{enumerate}[leftmargin=*,label=\arabic*)]
    \item $\ac_i (\States)$ is compact (hence, measurable) and belief-closed,
    \item $\ac_i (\States)$  and $\minADTypeSt^{i} (\Types_i)$ are nonempty,
    \item $\ac_i (\States)$  and $\minADTypeSt^{i} (\Types_i)$ are unique,
\end{enumerate}
and
\begin{align*}
\minADTypeSt^{i} (\Types_i) & = \ADTypeSt^{i} (\ac_i (\States)) ,\\
\minADStates^i & = \ac_i (\States) .
\end{align*}
%
\end{theorem}

Having provided a foundation for the notion of agent-dependent type structure via the notion of agent closure, we now see how the agent closure works in our example.

\begin{example}[continues=ex:misalignment, name=Taking Care of Misalignment with the Agent Closure]
%
As before, we have 
%
\begin{equation*}
\States := %
\Sets { \state^1 , \state^2 } \equiv %
\SNatures \times \{\type^{\rain}_\Ann\} \times \{ \type^{\sun}_\Bob\} ,
\end{equation*}
%
as the actual state space of interest for us as analysts. Now, it is immediate to observe that we have 
%
\begin{align*}
\ac_\Ann (\States) & := \{\snature^{\rain}\} \times \{t^{\rain}_\Ann\} \times \{t^{\rain}_\Bob\} \hspace{0.9mm} \equiv \{ \state^{\rain} \} \\
%
\ac_\Bob (\States) & := \{\snature^{\sun}\} \times \{\type^{\sun}_\Ann\} \times \{\type^{\sun}_\Bob\} \equiv \{ \state^{\sun} \} ,
\end{align*}
%
from which we define for every $i \in \Agents$ the corresponding agent-dependent type structure $\ADTypeSt^i (\ac_i (\States))$. In particular, regarding Ann we have
%
\begin{align*}
\ac_\Ann (\Types_\Ann) & := \{ \type^{\rain}_{\Ann} \} ,\\
\ac_\Ann (\Types_\Bob) & := \{ \type^{\rain}_{\Bob} \} ,
\end{align*}
%
with 
%
\begin{align*}
\acADbelfun^{\Ann}_{\Ann} (\type^{\rain}_{\Ann}) & := 1 (\snature^\rain, \type^{\rain}_{\Bob}) ,\\
\acADbelfun^{\Ann}_{\Bob} (\type^{\rain}_{\Bob}) & := 1 (\snature^\rain, \type^{\rain}_{\Ann}) ,
\end{align*}
%
while regarding Bob we have 
%
\begin{align*}
\ac_\Bob (\Types_\Bob) & := \{ \type^{\sun}_{\Bob} \} ,\\
\ac_\Bob (\Types_\Ann) & := \{ \type^{\sun}_{\Ann} \} .
\end{align*}
%
with
%
\begin{align*}
\acADbelfun^{\Bob}_{\Bob} (\type^{\sun}_{\Bob}) & := 1 (\snature^\sun, \type^{\sun}_{\Ann}) ,\\
\acADbelfun^{\Bob}_{\Ann} (\type^{\sun}_{\Ann}) & := 1 (\snature^\sun, \type^{\sun}_{\Bob}) .
\end{align*}
%
Once more, it is immediate to observe that the profile of agent-dependent type structures induced by the profile $\big( \ac_j (\States) \big)_{j \in \Agents}$ is non-common and non-degenerate.
\end{example}



