\subsection{\texorpdfstring{Proofs of \Sref{sec:defining_misalignment}}{Proof of Section 3}}
\label{subapp:proof_defining_misalignment}

It has to be observed that the construction of the space of CHBs can be performed as in \cite{Mertens_Zamir_1985} with an arbitrary agent $i \in \Agents$ having beliefs over herself: when we add---as it is customary---the additional assumption that $\marg_{\UTypes_i} \belhom_i (\type_i) = \delta_{\type_i}$, we end up with the same object we obtained in \Sref{sec:background_knowledge}. Now, for the proof that follows we assume to have performed the construction with agents having beliefs over themselves. In particular, this leads to the definition of the $m^{\text{th}}$-order universal hierarchy function of agent $i \in \Agents$ as 
%
\begin{equation*}
\label{eq:app_mth_hierarchy_function}
    \hierfun^{m}_i : \UTypes_i \to \Delta (\SNatures \times \Types^{m-1}) ,
\end{equation*}
%
which is in the spirit of \Mref{eq:hierarchy_function} for $m \geq 2$. 

We can now proceed with the proof of \Mref{th:state_space_characterization}.

\begin{proof}[Proof of \Mref{th:state_space_characterization}]
Note that the statement is logically equivalent to the following: a state space $\States$ is aligned if and only if it is
belief-closed. This is the statement we prove.\\
%
\noindent $[\Rightarrow]$ Suppose the state space $\States := \SNatures \times \Types$ is aligned. That is, for every agent $i \in \Agents$, every type $\type_i \in \Types_i$, every $m \in \Naturals \setminus \{1\}$, and every agent $j \in \Agents \setminus \{i\}$ such that 
%
\begin{equation}
\label{eq:alignment}
\Big( \supp \marg_{\Hiers^{m-1}_{j}} \hierfun^{m}_i (\type_i) \Big) \not\subseteq \projstfun^{m-1}_j\Types_j .
\end{equation}
%
Thus, we can follow exactly the arguments (modulo the differences just mentioned above), of \citet[Proof of Porperty 5]{Mertens_Zamir_1985} to establish belief-closedness.

\noindent $[\Leftarrow]$ Suppose the state space $\States := \SNatures \times \Types$ is misaligned, but belief-closed. Then, there exist agents $i, j \in \Agents$ with $i \neq j$, $m \in \Naturals \setminus \{1\}$, $\type_i \in \Types_i$, and $\type_j^* \in \UTypes_j \setminus \Types_j$ such that
%
\begin{equation*}
%\label{eq:alignment}
\projstfun^{m-1}_j\type_j^* \in  \supp \marg_{\Hiers^{m-1}_{j}} \hierfun^{m}_i (\type_i),
\end{equation*}
%
which is in direct contradiction to belief-closedness.
\end{proof}



