\subsection{\texorpdfstring{Proofs of \Sref{sec:a_framework_for_misalignment}}{Proof of Section 4}}
\label{subapp:proof_a_framework_for_misalignment}

In order to prove \Mref{th:characterization_minimality}, we employ order theoretical arguments. For this, we need a pointed complete lattice $\big((L,\leq), \star\big)$  (i.e., $\star \in L$). Recall that a map $F: L \to L$ is \emph{extensive} if $x \leq F (x)$ for every $x \in L$. $F : L \to L$ is \emph{$\omega$-continuous}\footnote{To differentiate the order-theoretic notion of continuity from our notion of continuity in the main text, we use the terminology \Say{$\omega$-continuity} here. We decided to use that expression in line with the terminology employed in category theory to refer to the same notion.} if for any ascending chain $(D_n)_{n \in \mathbb{N}}$, we have
%
\begin{equation*}
    F \Rounds {\bigvee_{n \in \mathbb{N}} D_n} = \bigvee_{n \in \mathbb{N}} F (D_n).
\end{equation*}

Now, we consider a map $F: L \to L$ that is extensive and $\omega$-continuous map. Set $K_{0} := \star$ and define inductively
%
\begin{equation*}
K_{n+1} := F(K_{n})
\end{equation*}
%
for every $n \in \Naturals_0$. Also, let
%
\begin{align*}
\mathcal{P}_{n}&:=
\left\{X \in L\mid  \star \leq X, \ F^{n}(\star)\leq X\right\},\\ %\text{ and}\\
%
A_{n} & :=
\bigwedge_{X \in \mathcal{P}_{n}} X.
\end{align*}
%
Finally, let
%
\begin{equation*}
K_{\infty} := \bigvee_{n \in \Naturals_0}K_{n} ,
\end{equation*}
%
which is well-defined because $L$ is complete.



\begin{lemma} 
The meet $A_{n}$ exists in $L$ with $A_{n}\in \mathcal{P}_{n}$.
\end{lemma}


\begin{proof}
Since $L$ is complete, the meet exists in $L$.  Moreover, each $X\in\mathcal{P}_{n}$ satisfies $\star \leq X$ and $F^{n}(\star)\leq X$, hence, their meet $A_{n}$ also satisfies these two conditions. Thus, $A_{n}\in\mathcal{P}_{n}$.
\end{proof}

\begin{lemma}
    For every $n \in \Naturals_0$, $A_{n}=K_{n}$.
\end{lemma}

\begin{proof}
First, $K_{n}\in\mathcal{P}_{n}$ because $\star \leq K_{n}$ (from the fact that $F$ is extensive) and $F^{n}(\star)=K_{n}\leq K_{n}$. Hence,
%
\begin{equation*}
A_{n}
=
\bigwedge_{\,X\in\mathcal{P}_{n}}X
\;\leq\; K_{n}.
\end{equation*}
%
Conversely, for each $X\in\mathcal{P}_{n}$ we have $F^{n}(\star)=K_{n}\leq X$, so $K_{n}$ is a lower bound of $\mathcal{P}_{n}$.  Since $A_n$ is the greatest lower bound $K_{n} \leq A_n$
\end{proof}


\begin{lemma}
    The set $K_{\infty}$ is the least fixed point of $F$.
\end{lemma}

\begin{proof}
Note that $(K_n)_{n \in \mathbb{N}}$ is an ascending chain. Since F is $\omega$-continuous, we have 
%
\begin{equation*}
    F \Rounds { \bigvee_{n \in \Naturals_0} K_{n} }
=
\bigvee_{n \in \Naturals_0} F \big(K_{n} \big),
\end{equation*}
%
where the LHS is equal to $F\big(K_{\infty}\big)$ by definition and the RHS is equal to $\bigvee_{n \in \Naturals_0} K_{n+1} = \bigvee_{n \in \Naturals_0} K_{n} = K_{\infty}$. Thus, $F\big(K_{\infty}\big)=K_{\infty}$ 
%
To establish that $K_{\infty}$ is the least fixed point of $F$ let
\begin{align*}
\mathcal{F}&:=
\big\{X\in L \mid \star\leq X, F(X)=X\bigr\}, \\ %\text{ and}\\
A_{\infty}&:=
\bigwedge_{X \in \mathcal{F}} X.
\end{align*}
%
Since $L$ is complete, the meet $\bigwedge_{X\in\mathcal{F}} X$ exists.  For every $X \in \mathcal{F}$, we have
%
\begin{equation*}
K_{n} = F^{n}(\star) \leq F^{n}(X) = X .
\end{equation*}
%
Thus, taking joins over $n$ gives
%
\begin{equation*}
K_{\infty} = \bigvee_{n \in \Naturals_0}K_{n}\leq X.
\end{equation*}
%
Hence, $K_{\infty}$ is a lower bound of $\mathcal{F}$, so
%
\begin{equation*}
K_{\infty} \leq \bigwedge_{X \in \mathcal{F}}X
=
A_{\infty}.
\end{equation*}
%
On the other hand, $A_{\infty}\in\mathcal{F}$, because $\star \leq A_{\infty}$, and
%
\begin{equation*}
F\big(A_{\infty}\big)
\leq
\bigwedge_{\,X\in\mathcal{F}}F(X)
=
\bigwedge_{\,X\in\mathcal{F}}X
=
A_{\infty} \leq F\big(A_{\infty}\big),
\end{equation*}
%
where the last inequality uses the fact that $F$ is extensive.
\end{proof}

We now transpose the result obtained above in an abstract order theoretical framework to our game theoretical setting. Thus, for this purpose we fix a state space $\States$ and we work with compact sets and the lattice induced by set inclusion (component-wise with respect to the cartesian product indexed by $\Agents$). Note that all our sets are subsets of the universal state space $\UStates$, which is compact itself: as a result, we only need to establish the closedness of the subsets to get compactness. However, the lattice with unions as joins is not complete, because only finite unions of closed sets are closed. Thus, we define the following join operation to make our lattice complete:
%
\begin{equation}
\label{eq:join_operation}
    \bigvee_{\lambda \in \Lambda} D_\lambda := \overline{\bigcup_{\lambda \in \Lambda} D_\lambda},
\end{equation}
%
for any family of compact sets indexed by $\Lambda$. Let $\CompactFam(\UStates)$ denote the collection of compact subsets of $\UStates$, i.e., $\States := \SNatures \times \prod_{j \in \Agents} \Types_j \in \CompactFam (\UStates)$ if $\Types_i \subseteq \UTypes_i$ is compact for every $i \in \Agents$.

\begin{lemma}
\label{lem:join_operation}
The tuple  $(\CompactFam(\UStates), \subseteq)$ with join operation as defined in \Mref{eq:join_operation} and meet given by intersection is a complete lattice.
\end{lemma}

\begin{proof}
Let $(\States_{\lambda})_{\lambda\in\Lambda}\subseteq \CompactFam(\UStates)$ be any family of compact sets.  Now, their union  $U = \bigcup_{\lambda\in\Lambda} \States_{\lambda}$ is not necessarily closed, but it is contained in the compact space $\UStates$. Let
%
\begin{equation*}
\bigvee_{\lambda\in\Lambda} \States_{\lambda}
:=
\overline{\,U\,}
=
\overline{\bigcup_{\lambda\in\Lambda} \States_{\lambda}}.
\end{equation*}
%
Since $U\subseteq \UStates$ and $\UStates$ is compact, $\overline{U}$ is closed in $\UStates$ and hence compact.  Clearly for every $\States_{\lambda}$ we have $\States_{\lambda} \subseteq U \subseteq \overline{U}$. Hence, $\overline{U}$ is an upper bound.  If any compact $Y\subseteq \UStates$ satisfies $\States_{\lambda}\subseteq Y$ for every $\lambda \in \Lambda$, then $U\subseteq Y$, and $Y$ being closed forces $\overline{U}\subseteq Y$.  Therefore
%
\begin{equation*}
\overline{\bigcup_{\lambda\in\Lambda} \States_{\lambda}}
\end{equation*}
%
is the least upper bound of $(\States_{\lambda})$ in $\CompactFam(\UStates)$.  The infimum case is automatically satisfied, because arbitrary intersections are closed. 
\end{proof} 

Now, to apply our order-theoretic setting we also need the pointed element $\star$ in the lattice and the mapping $F$. Thus, for this we fix an arbitrary $i \in \Agents$, we set
%
\begin{equation*}
    \star := \overline{\States \cup \Closure_i (\States)}
\end{equation*}
%
(which does depend on the arbitrary agent $i$), and we let
%
\begin{equation}
\label{eq:extensive_map}
    F\left(\States'\right) := \States' \cup \bigcup_{j \in \Agents}\Closure_j (\States') 
\end{equation}
%
for every $\States' \in \CompactFam(\UStates)$, which is by construction an element in $\CompactFam(\UStates)$, i.e., it is compact. Furthermore, it is immediate that $F$ is extensive. Thus, we only need to establish that $F$ is also $\omega$-continuous.

\begin{lemma}
The map $F$ as defined in \Mref{eq:extensive_map} is $\omega$‐continuous in $\CompactFam(\UStates)$.
\end{lemma}

\begin{proof}
Let $(\States^{n})_{n \in \Naturals_0}$ be an ascending chain in $\CompactFam(\UStates)$, where
%
\begin{align*}
    \States^{n} = 
\SNatures \times \prod_{j\in\Agents} \Types_{j}^{n},
\end{align*}
%
and $\Types_{i}^{n}\subseteq \Types_{i}^{n+1}$ for every $i \in \Agents$ and $n \in \Naturals_0$.  Thus, by our definition of the join, we have
%
\begin{align*}
\bigvee_{n \in \Naturals_0} \States^{n}
=
\SNatures  \times 
\prod_{j\in\Agents}\overline{\bigcup_{n \in \Naturals_0} \Types_{j}^{n}}
=
\SNatures  \times 
\prod_{j\in\Agents}\bigvee_{n \in \Naturals_0} \Types_{j}^{n}.
\end{align*}
%
Letting $\Types_i := \bigvee_{n \in \Naturals_0} \Types_{i}^{n}$ for every $i \in \Agents$, we have
%
\begin{align*}
    \Closure_i \left(\bigvee_{n \in \Naturals_0}\States^{n} \right) =
    \SNatures \times \Types_i \times \overline{\supp \typehom_i (\Types_i)}
\end{align*}
%
and
%
\begin{align*}
    F\left(\bigvee_{n \in \Naturals_0}\States^{n} \right)=\bigvee_{n \in \Naturals_0}\States^{n} \cup \bigcup_{j \in \Agents} \left(\SNatures \times \Types_j \times \overline{\supp \typehom_j (\Types_j)}\right).
\end{align*}
%
Furthermore,
%
\begin{align*}
    F\left(\States^{n} \right)=\States^{n} \cup \bigcup_{j \in \Agents} \left(\SNatures \times \Types_j^{n} \times \overline{\supp \typehom_j (\Types_j^{n})}\right).
\end{align*}
%
Thus, we only need to show that 
%
\begin{equation*}
    \overline{\supp \typehom_i (\Types_i)} = \bigvee_{n \in \Naturals_0} \overline{\supp \typehom_i (\Types_i^{n})} = \overline{\bigcup_{n \in \Naturals_0} \overline{\supp \typehom_i (\Types_i^{n})}} 
\end{equation*}
%
for every $i \in \Agents$. Thus, let $i \in \Agents$ be arbitrary. First, we establish 
%
\begin{equation*}
    \overline{\bigcup_{n \in \Naturals_0} \overline{\supp \typehom_i (\Types_i^{n})}} \subseteq \overline{\supp \typehom_i (\Types_i)} .
\end{equation*}
%
Since $\Types_{i}^{n}\subseteq \Types_i$, we have $\supp\typehom_{i} (\Types_{i}^{n}) \subseteq \supp\typehom_{i} (\Types_i)$ and also $\overline{\supp\typehom_{i}(\Types_{i}^{n})} \subseteq \overline{\supp\typehom_{i} (\Types_i)}$. Hence
%
\begin{align*}
    \bigcup_{n \in \Naturals_0}  \overline{\supp\typehom_{i} (\Types_{i}^{n})} \subseteq \overline{\supp\typehom_{i}(\Types_i)}.
\end{align*}
%
Taking the closure (together with their idempotence) gives the result.

\noindent We now prove the reverse inclusion
%
\begin{equation*}
    \overline{\supp \typehom_i (\Types_i)} \subseteq %
    \overline{\bigcup_{n \in \Naturals_0} \overline{\supp \typehom_i (\Types_i^{n})}} .
\end{equation*}
%
Thus, consider $\type_{-i} \in \supp\typehom_{i} (T_i)$. From the fact that the $\supp$ operator is lower hemicontinuous and from the continuity of $\typehom_{i}$, there exists a sequence $t_i^{m} \in \Types_i$ with $t_i^{m} \to t_i \in \Types_i$ and $\type_{-i}^{m} \in \supp \typehom_{i} (t_i^{m})$ such that $\type_{-i}^{m} \to \type_{-i}$. By the property of closure, we can (by introducing more sequences if needed) make sure that each $t_i^{m} \in \bigcup_{n \in \Naturals_0} \Types_i^{n}$. With this, each $t^{m}_i$ lies in some $\Types_{i}^{n_{m}}$. Because we consider an increasing sequence of sets, we can assume that $n_1 \leq n_2 \leq \ldots$ without loss. Thus, for every $m \in \Naturals$,
%
\begin{align*}
    \type_{-i}^{m} \in \supp\typehom_{i} (\Types_{i}^{n_m}) \subseteq \overline{\supp\typehom_{i} (\Types_{i}^{n_m})}.
\end{align*}
%
As $\type_{-i}^{m} \to \type_{-i}$, we conclude that
%
\begin{align*}
    \type_{-i} \in \overline{\bigcup_{n \in \Naturals_0} \overline{\supp \typehom_i (\Types_i^{n})}}.
\end{align*}
%
Since $\type_{-i}$ was arbitrary, we actually have
%
\begin{align*}
    \supp \typehom_{i} (\Types_i) \subseteq \overline{\bigcup_{n \in \Naturals_0} \overline{\supp \typehom_i(\Types_i^{n})}}.
\end{align*}
%
Taking the closure (together with their idempotence) gives the result again.
\end{proof}




