\begin{lemma}\label{lem:monomial-orthogonality}
In the Fock space $F_\alpha^2$, the monomials $\{z^n\}_{n=0}^\infty$ form an orthogonal system with
\[
\langle z^s, z^t \rangle = \delta_{st} \frac{s!}{\alpha^s},
\]
where $\delta_{st}$ denotes the Kronecker delta.
\end{lemma}

\begin{proof}
Using polar coordinates $z = re^{i\theta}$ and the Gaussian measure $d\mu(z) = \frac{\alpha}{\pi} e^{-\alpha |z|^2} dA(z)$, we compute:
\begin{align*}
\langle z^s, z^t \rangle &= \frac{\alpha}{\pi} \int_{\mathbb{C}} z^s \overline{z}^t e^{-\alpha |z|^2} dA(z) \\
&= \frac{\alpha}{\pi} \int_0^{2\pi} e^{i(s-t)\theta} d\theta \int_0^\infty r^{s+t+1} e^{-\alpha r^2} dr.
\end{align*}

The angular integral vanishes when $s \neq t$:
\[
\int_0^{2\pi} e^{i(s-t)\theta} d\theta = 2\pi \delta_{st}.
\]

For the radial integral when $s = t$, we make the substitution $u = \alpha r^2$:
\begin{align*}
\int_0^\infty r^{2s+1} e^{-\alpha r^2} dr &= \frac{1}{2\alpha^{s+1}} \int_0^\infty u^s e^{-u} du \\
&= \frac{\Gamma(s+1)}{2\alpha^{s+1}} = \frac{s!}{2\alpha^{s+1}}.
\end{align*}

Combining these results yields:
\[
\langle z^s, z^t \rangle = \delta_{st} \cdot \frac{\alpha}{\pi} \cdot 2\pi \cdot \frac{s!}{2\alpha^{s+1}} = \delta_{st} \frac{s!}{\alpha^s}. \qedhere
\]
\end{proof}
\begin{lemma}\label{lem:projection-monomials}
Let $k, \ell \in \mathbb{N}_0$ be non-negative integers. The orthogonal projection $P$ in $F_\alpha^2$ satisfies:
\begin{enumerate}[label=(\alph*)]
    \item For $k \geq \ell$, the projection is given by
    \[
    P(z^{n+k}\overline{z}^\ell) = \frac{(n+k)!}{\alpha^{n+k} }\sqrt{\frac{\alpha^{n+k-\ell}}{(n+k-\ell)!}} \, e_{n+k-\ell}.
    \]

    \item For $\ell > k$, the projection vanishes when $n < \ell - k$ and equals
    \[
     P(z^{n+k}\overline{z}^\ell) = \frac{(n+k)!}{\alpha^{n+k} }\sqrt{\frac{\alpha^{n+k-\ell}}{(n+k-\ell)!}} \, e_{n+k-\ell},
    \]
    when $n \geq \ell - k$.
\end{enumerate}
\end{lemma}

\begin{proof}
We analyze both cases using the orthonormal basis $e_m(z) = \sqrt{\frac{\alpha^m}{m!}} z^m$ of $F_\alpha^2$.

\noindent\textbf{Case (a): $k \geq \ell$} \\
For any $m \geq 0$, the inner product decomposes as:
\begin{align*}
\langle z^{n+k}\overline{z}^\ell, e_m \rangle 
&= \sqrt{\frac{\alpha^m}{m!}} \langle z^{n+k}, z^{m+\ell} \rangle_{F_\alpha^2} \\
&= \sqrt{\frac{\alpha^m}{m!}} \cdot \frac{(n+k)!}{\alpha^{n+k}} \delta_{n+k,m+\ell}.
\end{align*}
By Lemma~\ref{lem:monomial-orthogonality}, the projection is nonzero only when $m = n+k-\ell \geq 0$, yielding:
\begin{align*}
P(z^{n+k}\overline{z}^\ell) &= \sqrt{\frac{\alpha^{n+k-\ell}}{(n+k-\ell)!}} \frac{(n+k)!}{\alpha^{n+k}} e_{n+k-\ell}. \\
\end{align*}

\noindent\textbf{Case (b): $\ell > k$} \\
The same calculation applies, but now
\begin{itemize}
    \item[(i)] For $0 \leq n < \ell - k$, the condition $m = n+k-\ell < 0$ is impossible, so the projection vanishes.
    \item[(ii)] For $n \geq \ell - k$, we recover the same expression as in Case (a) since $m = n+k-\ell \geq 0$.
\end{itemize}
\end{proof}
\section{Operator Matrices on Fock Space}

We now establish detailed matrix representations for fundamental operators on the Fock space $F_\alpha^2$ with respect to the orthonormal basis $\left\{e_n(z) = \sqrt{\frac{\alpha^n}{n!}}z^n\right\}_{n=0}^\infty$.


\subsection{Toeplitz Operators}

\begin{theorem}[Matrix of Toeplitz Operator]
For a bounded harmonic symbol $\phi(z) = \displaystyle\sum_{i=0}^\infty a_i z^i + \sum_{j=1}^\infty b_j \overline{z}^j \in L^\infty(\mathbb{C})$, the matrix elements of $T_\phi$ are given by
\[
\langle T_\phi e_n, e_m \rangle = 
\begin{cases}
\sqrt{\frac{\alpha^{n-m} m!}{n!}} \, a_{m-n} & \text{for } m \geq n \\
\sqrt{\frac{\alpha^{m-n} n!}{m!}} \, b_{n-m} & \text{for } n > m \, 
\end{cases}
\]
for non-negative integers $m$ and $n$.
\end{theorem}

\begin{proof}
Here,
\begin{align*}
\langle T_\phi \, e_n, e_m \rangle&= \langle P_\phi \, e_n, e_m \rangle \cr
&=\sqrt{\frac{\alpha^n}{n!}} \sqrt{\frac{\alpha^m}{m!}} \left(\sum\limits_{i=0}^\infty a_i \langle z^{i+n}, z^m \rangle+\sum\limits_{j=1}^\infty b_j \langle z^n, z^{m+j} \rangle \right).
\end{align*}
The matrix elements decompose into two cases: \\
Case 1.  For $m \geq n$, only the analytic part contributes:
\begin{align*}
\langle T_\phi \, e_n, e_m \rangle&=\sqrt{\frac{\alpha^n}{n!}} \sqrt{\frac{\alpha^m}{m!}} \left(\sum\limits_{i=0}^\infty a_i \langle z^{i+n}, z^m \rangle \right)\cr
&=\sqrt{\frac{\alpha^n}{\alpha^m}} \times \sqrt{\frac{m!}{n!}} \,\,\, a_{m-n}\cr&=\sqrt{\frac{\alpha^{n-m} m!}{n!}} \, a_{m-n} .
\end{align*}
Case 2.  For $n > m$, only the anti-analytic part contributes:
\begin{align*}
\langle T_\phi \, e_n, e_m \rangle&=\sqrt{\frac{\alpha^n}{n!}} \sqrt{\frac{\alpha^m}{m!}} \left(\sum\limits_{j=1}^\infty b_j \langle z^n, z^{m+j} \rangle \right)\cr
&=\sqrt{\frac{\alpha^m}{\alpha^n}} \times \sqrt{\frac{n!}{m!}} \,\,\, b_{n-m}\cr&=\sqrt{\frac{\alpha^{m-n} n!}{m!}} \, b_{n-m}
\end{align*}
for non-negative integers $m$ and $n$.
 Its matrix with respect to the orthonormal basis is given by
\[
T_\phi=
\begin{bmatrix}
a_0 & \frac{1}{\sqrt{\alpha}}b_1 & \frac{\sqrt{2}}{\sqrt{\alpha^2}}b_2 & \frac{\sqrt{6}}{\sqrt{\alpha^3}}b_3 & \hdots \\
\frac{1}{\sqrt{\alpha}}a_1 & a_0 & \frac{\sqrt{2}}{\sqrt{\alpha}}b_1 & \frac{\sqrt{6}}{\sqrt{\alpha^2}}b_2 & \hdots \\
\frac{\sqrt{2}}{\sqrt{\alpha^2}}a_2 & \frac{\sqrt{2}}{\sqrt{\alpha}}a_1 & a_0 & \frac{\sqrt{3}}{\sqrt{\alpha}}b_1 & \hdots \\
\frac{\sqrt{6}}{\sqrt{\alpha^3}}a_3 & \frac{\sqrt{6}}{\sqrt{\alpha^2}}a_2 & \frac{\sqrt{3}}{\sqrt{\alpha}}a_1 & a_0 & \hdots \\
\vdots & \vdots & \vdots & \vdots & \ddots
\end{bmatrix}
\]
and the adjoining of the matrix of $T_\phi$ is given by 
\[
T_\phi^*=
\begin{bmatrix}
\overline{a_0} & \frac{1}{\sqrt{\alpha}}\overline{a_1} & \frac{\sqrt{2}}{\sqrt{\alpha^2}}\overline{a_2} & \frac{\sqrt{6}}{\sqrt{\alpha^3}}\overline{a_3} & \hdots \\
\frac{1}{\sqrt{\alpha}}\overline{b_1} & \overline{a_0} & \frac{\sqrt{2}}{\sqrt{\alpha}}\overline{a_1} & \frac{\sqrt{6}}{\sqrt{\alpha^2}}\overline{a_2} & \hdots \\
\frac{\sqrt{2}}{\sqrt{\alpha^2}}\overline{b_2} & \frac{\sqrt{2}}{\sqrt{\alpha}}\overline{b_1} & \overline{a_0} & \frac{\sqrt{3}}{\sqrt{\alpha}}\overline{a_1} & \hdots \\
\frac{\sqrt{6}}{\sqrt{\alpha^3}}\overline{b_3} & \frac{\sqrt{6}}{\sqrt{\alpha^2}}\overline{b_2} & \frac{\sqrt{3}}{\sqrt{\alpha}}\overline{b_1} & \overline{a_0} & \hdots \\
\vdots & \vdots & \vdots & \vdots & \ddots
\end{bmatrix}
\]
which is nothing but the matrix of $T_{\overline{\phi}}$ and therefore $T_\phi^*=T_{\overline{\phi}}$ \,.
\end{proof}
\subsection{Hankel Operators}

\begin{theorem}[Matrix of Hankel Operator]
The Hankel operator $H_\phi$ has matrix elements:
\[
\langle H_\phi e_n, e_m \rangle = \frac{(m+n+1)!}{\sqrt{\alpha^{m+n+1} m! (n+1)!}} a_{m+n+1}\, 
\]
for non-negative integers $m$ and $n$.
\end{theorem}

\begin{proof}
Using the anti-analytic projection
\begin{align*}
 \langle H_\phi e_n, e_m \rangle &= \langle P M_\phi J e_n, e_m \rangle \\
&=\sqrt{\frac{\alpha^{n+m+1}}{(n+1)! m!}} \left(\sum^\infty_{i=0} a_i \langle z^i, z^{m+n+1} \rangle+\sum^\infty_{j=1} \langle \overline{z}^j, z^{m+n+1} \rangle\right)\\
&= \frac{(m+n+1)!}{\sqrt{\alpha^{m+n+1} m! (n+1)!}} a_{m+n+1}   
\end{align*}
for non-negative integers $m$ and $n$.
\end{proof}
The Hankel matrix exhibits a distinct pattern
\[
H_\phi=
\begin{bmatrix}
\frac{1}{\sqrt{\alpha}}a_1 &  \frac{\sqrt{2}}{\sqrt{\alpha^2}}a_2 & \frac{\sqrt{6}}{\sqrt{\alpha^3}}a_3 & \frac{2\sqrt{6}}{\sqrt{\alpha^4}}a_4 & \hdots \\
\frac{2}{\sqrt{\alpha^2}}a_2 & \frac{3\sqrt{2}}{\sqrt{\alpha^3}}a_3 & \frac{4\sqrt{6}}{\sqrt{\alpha^4}}a_4 & \frac{10\sqrt{6}}{\sqrt{\alpha^5}}a_5 & \hdots \\
\frac{3\sqrt{2}}{\sqrt{\alpha^3}}a_3 & \frac{12}{\sqrt{\alpha^4}}a_4 & \frac{20\sqrt{3}}{\sqrt{\alpha^5}}a_5 & \frac{60\sqrt{3}}{\sqrt{\alpha^6}}a_6 & \hdots \\
\frac{4\sqrt{6}}{\sqrt{\alpha^4}}a_4 & \frac{20\sqrt{3}}{\sqrt{\alpha^5}}a_5 & \frac{120}{\sqrt{\alpha^6}}a_6 & \frac{210\sqrt{4}}{\sqrt{\alpha^7}}a_7 & \hdots \\
\vdots & \vdots & \vdots & \vdots & \ddots 
\end{bmatrix}
\]
and the adjoining of the matrix of $H_\phi$ is given by
\[
H_\phi^*=
\begin{bmatrix}
\frac{1}{\sqrt{\alpha}}\overline{a_1} & \frac{2}{\sqrt{\alpha^2}}\overline{a_2} & \frac{3\sqrt{2}}{\sqrt{\alpha^3}}\overline{a_3} & \frac{4\sqrt{6}}{\sqrt{\alpha^4}}\overline{a_4} & \hdots \\
\frac{\sqrt{2}}{\sqrt{\alpha^2}}\overline{a_2} & \frac{3\sqrt{2}}{\sqrt{\alpha^3}}\overline{a_3} & \frac{12}{\sqrt{\alpha^4}}\overline{a_4} & \frac{20\sqrt{3}}{\sqrt{\alpha^5}}\overline{a^5} & \hdots \\
\frac{\sqrt{6}}{\sqrt{\alpha^3}}\overline{a_3} & \frac{4\sqrt{6}}{\sqrt{\alpha^4}}\overline{a_4} & \frac{20\sqrt{3}}{\sqrt{\alpha^5}}\overline{a_5} & \frac{120}{\sqrt{\alpha^6}}\overline{a_6} & \hdots \\
\frac{2\sqrt{6}}{\sqrt{\alpha^4}}\overline{a_4} & \frac{10\sqrt{6}}{\sqrt{\alpha^5}}\overline{a_5} & \frac{60\sqrt{3}}{\sqrt{\alpha^6}}\overline{a_6} & \frac{210\sqrt{4}}{\sqrt{\alpha^7}}\overline{a_7} & \hdots \\
\vdots & \vdots & \vdots & \vdots & \ddots
\end{bmatrix}
\]
and therefore $H_\phi^*=H_{\overline{\phi}}$\,.

