We study H-Toeplitz operators on the Fock space $F_\alpha^2$ through their matrix representations. First, we define the dilation operator $K: F_\alpha^2 \rightarrow L^2(\mathbb{C}, d\lambda_\alpha)$ by:
\[
K(e_{2n})(z) = e_n(z) = \sqrt{\frac{\alpha^n}{n!}} z^n, \quad 
K(e_{2n+1})(z) = \overline{e_{n+1}}(z) = \sqrt{\frac{\alpha^{n+1}}{(n+1)!}} \overline{z}^{n+1}
\]
for $n \geq 0$, $z \in \mathbb{C}$. This bounded linear operator ($\|K\|=1$) has adjoint $K^*$ satisfying:
\[
K^*(e_n) = e_{2n}, \quad K^*(\overline{e_{n+1}}) = e_{2n+1}
\]
with the properties $KK^* = I_{L^2}$ and $K^*K = I_{F_\alpha^2}$.

For $\phi \in L^\infty(\mathbb{C})$, the H-Toeplitz operator $S_\phi: F_\alpha^2 \rightarrow F_\alpha^2$ is defined as
\[
S_\phi(f) = P M_\phi K(f),
\]
where $P$ is the orthogonal projection and $M_\phi$ is multiplication by $\phi$. Its matrix elements are:

\begin{align*}
\langle S_\phi e_{2n}, e_m \rangle &= \langle T_\phi e_n, e_m \rangle \\
&= \begin{cases}
\sqrt{\frac{\alpha^n}{\alpha^m}} \sqrt{\frac{m!}{n!}} a_{m-n} & m \geq n \\
\sqrt{\frac{\alpha^m}{\alpha^n}} \sqrt{\frac{n!}{m!}} b_{n-m} & n > m
\end{cases} \\ {\rm and} \,\,\,
\langle S_\phi e_{2n+1}, e_m \rangle &= \langle H_\phi e_n, e_m \rangle \\
&= \frac{1}{\sqrt{\alpha^{m+n+1}}} \frac{(m+n+1)!}{\sqrt{m!(n+1)!}} a_{m+n+1}
\end{align*}
for non-negative integers $m$ and $n$.
The explicit matrix representation is given by

\[
S_\phi=
\begin{bmatrix}
a_0 &\frac{1}{\sqrt{\alpha}}a_1 & \frac{1}{\sqrt{\alpha}}b_1 & \frac{\sqrt{2}}{\sqrt{\alpha^2}}a_2 &\frac{\sqrt{2}}{\sqrt{\alpha^2}}b_2& \frac{\sqrt{6}}{\sqrt{\alpha^3}}a_3 & \frac{\sqrt{6}}{\sqrt{\alpha^3}}b_3&\frac{2\sqrt{6}}{\sqrt{\alpha^4}}a_4 & \hdots \\
\frac{1}{\sqrt{\alpha}}a_1 &\frac{2}{\sqrt{\alpha^2}}a_2 &a_0& \frac{3\sqrt{2}}{\sqrt{\alpha^3}}a_3 &\frac{\sqrt{2}}{\sqrt{\alpha}}b_1& \frac{4\sqrt{6}}{\sqrt{\alpha^4}}a_4 & \frac{\sqrt{6}}{\sqrt{\alpha^2}}b_2&\frac{10\sqrt{6}}{\sqrt{\alpha^5}}a_5 & \hdots \\
\frac{\sqrt{2}}{\sqrt{\alpha^2}}a_2 & \frac{3\sqrt{2}}{\sqrt{\alpha^3}}a_3 & \frac{\sqrt{2}}{\sqrt{\alpha}}a_1&\frac{12}{\sqrt{\alpha^4}}a_4 & a_0&\frac{20\sqrt{3}}{\sqrt{\alpha^5}}a_5 & \frac{\sqrt{3}}{\sqrt{\alpha}}b_1&\frac{60\sqrt{3}}{\sqrt{\alpha^6}}a_6 & \hdots \\
\frac{\sqrt{6}}{\sqrt{\alpha^3}}a_3 & \frac{4\sqrt{6}}{\sqrt{\alpha^4}}a_4 &\frac{\sqrt{6}}{\sqrt{\alpha^2}}a_2& \frac{20\sqrt{3}}{\sqrt{\alpha^5}}a_5 & \frac{\sqrt{3}}{\sqrt{\alpha}}a_1&\frac{120}{\sqrt{\alpha^6}}a_6 & a_0&\frac{210\sqrt{4}}{\sqrt{\alpha^7}}a_7 & \hdots \\
\vdots & \vdots & \vdots & \vdots &\vdots &\vdots &\vdots &\vdots & \ddots 
\end{bmatrix}
\]
and the adjoining of the matrix of $S_\phi$ is given by
\[
S_\phi^*=
\begin{bmatrix}
\overline{a_0}& \frac{1}{\sqrt{\alpha}}\overline{a_1} & \frac{\sqrt{2}}{\sqrt{\alpha^2}}\overline{a_2} & \frac{\sqrt{6}}{\sqrt{\alpha^3}}\overline{a_3} & \hdots \\
\frac{1}{\sqrt{\alpha}}\overline{a_1} & \frac{2}{\sqrt{\alpha^2}}\overline{a_2} & \frac{3\sqrt{2}}{\sqrt{\alpha^3}}\overline{a_3} &\frac{4\sqrt{6}}{\sqrt{\alpha^4}}\overline{a_4}  & \hdots \\
\frac{1}{\sqrt{\alpha}}\overline{b_1}  & \overline{a_0} & \frac{\sqrt{2}}{\sqrt{\alpha}}\overline{a_1} & \frac{\sqrt{6}}{\sqrt{\alpha^2}}\overline{a_2}& \hdots \\
 \frac{\sqrt{2}}{\sqrt{\alpha^2}}\overline{a_2} & \frac{3\sqrt{2}}{\sqrt{\alpha^3}}\overline{a_3} & \frac{12}{\sqrt{\alpha^4}}\overline{a_4} & \frac{20\sqrt{3}}{\sqrt{\alpha^5}}\overline{a_5}& \hdots \\
\frac{\sqrt{2}}{\sqrt{\alpha^2}}\overline{b_2} & \frac{\sqrt{2}}{\sqrt{\alpha}}\overline{b_1} & \overline{a_0} & \frac{\sqrt{3}}{\sqrt{\alpha}}\overline{a_1} & \hdots \\
\frac{\sqrt{6}}{\sqrt{\alpha^3}}\overline{a_3}  & \frac{4\sqrt{6}}{\sqrt{\alpha^4}}\overline{a_4} &\frac{20\sqrt{3}}{\sqrt{\alpha^5}}\overline{a_5}  & \frac{120}{\sqrt{\alpha^6}}\overline{a_6} & \hdots \\
\vdots & \vdots & \vdots & \vdots & \ddots 
\end{bmatrix}.
\] 
with $S_\phi^*=S_{\overline{\phi}}$ .\\
\begin{remark}
    Clearly, we can see that the matrix of $T_\phi$ can be obtained by deleting every odd column of the matrix of $S_\phi$ and the matrix of $H_\phi$ can be obtained by deleting every even column of the matrix of $S_\phi$.
\end{remark}

\section{Commutativity of H-Toeplitz operator on Fock-space $F_{\alpha}^2$}
In this section, we study the commutativity of H-Toeplitz operators for analytic and harmonic symbols. We explicitly demonstrate the non-commutative nature of H-Toeplitz operators through a carefully constructed example with polynomial symbols.

\begin{example}
 Consider the Fock space $F_\alpha^2$ with basis $\{e_n(z)\}_{n=0}^\infty$ where $e_n(z) = \sqrt{\frac{\alpha^n}{n!}}z^n$, and define two operators:
\begin{itemize}
    \item[(a)] $S_\phi$ with analytic symbol $\phi(z) = z^2$.
    \item[(b)] $S_\psi$ with anti-analytic symbol $\psi(z) = \overline{z}$.
\end{itemize}

\noindent\textbf{Step 1: Compute $S_\phi(e_2)$}
\begin{align*}
S_\phi(e_2(z))&=S_{z^2}\, (e_2(z))\cr 
&=P M_{z^2}\, K (e_2) \cr
&=P (z^2 \, K(e_2))\cr
&=\sqrt{\alpha}\, z^3.
\end{align*}

\noindent\textbf{Step 2: Compute $S_\psi(e_2)$}
\begin{align*}
S_\psi(e_2)&=P M_{\overline{z}}\, K (e_2) \cr
&=P\,( \overline{z} \, \sqrt{\alpha} \, z)\cr
&=\sqrt{\alpha}\, P(z\, \overline{z}) \cr
&=\sqrt{\alpha} \times \frac{1}{\alpha}
=\frac{1}{\sqrt{\alpha}}.
\end{align*}

\noindent\textbf{Step 3: Composition $S_\phi S_\psi(e_2)$}
\begin{align*}
S_\phi S_\psi(e_2) &= S_\phi\left(\frac{1}{\sqrt{\alpha}}\right) \\
&= P M_{z^2}\left(\frac{1}{\sqrt{\alpha}}\right) \\
&= \frac{1}{\sqrt{\alpha}} z^2 = \sqrt{\frac{2}{\alpha^3}}\, e_2.
\end{align*}

\noindent\textbf{Step 4: Composition $S_\psi S_\phi(e_2)$}
\begin{align*}
S_\psi S_\phi(e_2) &= S_\psi\left(\sqrt{\alpha}\, z^3 \right) \\
&=\sqrt{\frac{3}{\alpha^2}} \, e_1.
\end{align*}

\noindent\textbf{Conclusion:} The distinct results
\[
S_\phi S_\psi(e_2) = \sqrt{\frac{2}{\alpha^3}} e_2 \quad \text{and} \quad S_\psi S_\phi(e_2) = \sqrt{\frac{3}{\alpha^2}} e_1
\]
provide an explicit verification that $S_\phi S_\psi \neq S_\psi S_\phi$, confirming the non-commutative algebra of H-Toeplitz operators.
\end{example}

\begin{theorem}
Let $\phi(z) = \displaystyle\sum_{n=0}^\infty a_n z^n$ and $\psi(z) = \displaystyle\sum_{m=0}^\infty b_m z^m$ be bounded analytic functions on the complex plane $\mathbb{C}$, satisfying $\phi(0) = 0 = \psi(0)$. Suppose that each coefficient $a_n$ and $b_m$ is non-zero. Further, assume that for all non-negative integers $n$ and for a fixed integer $k$, the following inequality holds
\[
\frac{b_{n+k}}{a_{n+k}} \geq \frac{b_{2n+1}}{a_{2n+1}}.
\]
Then, the H-Toeplitz operators $S_\phi$ and $S_\psi$ on the Fock space $F_\alpha^2$ commute if and only if the functions $\phi$ and $\psi$ are linearly dependent.   
\end{theorem}

\begin{proof}
If $\phi$ and $\psi$ are linearly dependent, then clearly $S_\phi$ and $S_\psi$ commute.

For the converse, assume $S_\phi S_\psi = S_\psi S_\phi$. We analyze the action on the constant function $1 \in F_\alpha^2$:

\begin{align*}
S_\phi S_\psi(1) &= S_\psi S_\phi(1) \\
\Rightarrow P M_\phi k P M_\psi (1) &= P M_\psi k P M_\phi (1) \\
\Rightarrow P M_\phi k \left( \sum_{m=0}^\infty b_m z^m \right) &= P M_\psi k \left( \sum_{n=0}^\infty a_n z^n \right).
\end{align*}

Expressing in terms of the orthonormal basis $\{e_n\}$ where $e_n(z) = \sqrt{\frac{\alpha^n}{n!}} z^n$, we obtain:

\begin{align*}
P M_\phi \left[ \sum_{m=0}^\infty \sqrt{\frac{(2m)!}{\alpha^{2m}}} b_{2m} e_m + \sqrt{\frac{(2m+1)!}{\alpha^{2m+1}}} b_{2m+1} \overline{e_{m+1}} \right] \\
= P M_\psi \left[ \sum_{n=0}^\infty \sqrt{\frac{(2n)!}{\alpha^{2n}}} a_{2n} e_n + \sqrt{\frac{(2n+1)!}{\alpha^{2n+1}}} a_{2n+1} \overline{e_{n+1}} \right].
\end{align*}

Projecting onto $F_\alpha^2$ and equating coefficients gives

\begin{align*}
\sum_{n,m} \sqrt{\frac{(2m)!}{m! \alpha^m}} a_n b_{2m} z^{n+m} &+ \sum_{n,m} \sqrt{\frac{(2m+1)!}{(m+1)! \alpha^{m+1}}} a_n b_{2m+1} P(z^n \overline{z}^{m+1}) \\
&= \sum_{n,m} \sqrt{\frac{(2n)!}{n! \alpha^n}} a_{2n} b_m z^{n+m} \\
&+ \sum_{n,m} \sqrt{\frac{(2n+1)!}{(n+1)! \alpha^{n+1}}} a_{2n+1} b_m P(z^m \overline{z}^{n+1}).
\end{align*}
\textbf{Step 1: Constant term.} The coefficient of $z^0$ yields
\[
\sum_{m=0}^\infty \sqrt{\frac{(2m+1)!}{\alpha^{2m+1}}} \sqrt{\frac{(m+1)!}{\alpha^{m+1}}} (a_{m+1} b_{2m+1} - a_{2m+1} b_{m+1}) = 0,
\]
which implies $\frac{b_{m+1}}{a_{m+1}} = \frac{b_{2m+1}}{a_{2m+1}}$ for all $m \geq 0$.\\
\textbf{Step 2: Linear term.} The coefficient of $z^1$ gives
\[
a_1 b_0 + \sum_{m=0}^\infty \sqrt{\frac{(2m+1)! \alpha}{(m+1)! \alpha^{2m+2}}} (m+2)! (a_{m+2} b_{2m+1} - a_{2m+1} b_{m+2}) = 0,
\]
enforcing $\frac{b_{m+2}}{a_{m+2}} = \frac{b_{2m+1}}{a_{2m+1}}$.
By induction, we conclude $\frac{b_{n+k}}{a_{n+k}} = \frac{b_{2n+1}}{a_{2n+1}}$ for all $n,k \geq 0$. Setting $n=0$ gives $\frac{b_k}{a_k} = \frac{b_1}{a_1}$ for all $k \geq 1$, proving $\psi = \lambda \phi$ where $\lambda = \frac{b_1}{a_1}$.
\end{proof}



\section{The compactness of H-Toeplitz operators}

In this section, we investigate the compactness properties of H-Toeplitz operators acting on the Fock space $F_\alpha^2$. We establish fundamental results concerning their operator norms and compactness characteristics.

%\section{Basic Properties}

\begin{proposition}\label{prop:basic}
For $\phi, \psi \in L^\infty(\mathbb{C})$ and $a, b \in \mathbb{C}$, the following hold:
\begin{enumerate}
\item[(a)] Linearity: $S_{a\phi + b\psi} = aS_\phi + bS_\psi$
\item[(b)] Boundedness: $\|S_\phi\| \leq \|\phi\|_\infty$
\end{enumerate}
\end{proposition}

\begin{proof}
(a) For any $f \in F_\alpha^2$, we compute:
\begin{align*}
S_{a\phi+b\psi}(f) &= PM_{a\phi+b\psi}k(f) \\
&= aP(\phi k(f)) + bP(\psi k(f)) \\
&= aS_\phi(f) + bS_\psi(f).
\end{align*}

(b) The operator norm satisfies:
\begin{align*}
\|S_\phi\| &= \sup_{\|f\|=1} \|PM_\phi k f\| \\
&\leq \sup_{\|f\|=1} \|M_\phi\|\|k f\| \\
&= \|\phi\|_\infty \sup_{\|f\|=1} \|f\| \\
&= \|\phi\|_\infty \,.
\end{align*}
\end{proof}

%\section{Compactness Results}

The following lemma provides a crucial compactness property:

\begin{lemma}\label{lem:compact_embedding}\cite{lee}
The identity embedding $I: F_\alpha^2 \to L^2(\mathbb{C}, d\lambda_\alpha)$ is compact.
\end{lemma}

\begin{remark}
As an immediate consequence, any weakly convergent sequence $f_n \to 0$ in $F_\alpha^2$ satisfies $\|f_n\| \to 0$.
\end{remark}
%Our main result characterizes the compactness of certain operator differences

\begin{theorem}\label{thm:main_compactness}
For any $\phi \in L^\infty(\mathbb{C})$, the operator \hspace{0.15cm} $S_\phi^* - K^*PM_{\overline{\phi}} $  \hspace{0.15cm} is compact on $F_\alpha^2$.
\end{theorem}

\begin{proof}
For $f, g \in F_\alpha^2$, consider the sesquilinear form:
\begin{align*}
\langle (S_\phi^* - K^*PM_{\overline{\phi}})\, f, g \rangle &= \langle S_\phi^* f, g \rangle - \langle K^*PM_{\overline{\phi}}f, g \rangle \\
&= \langle f, S_\phi g \rangle - \langle PM_{\overline{\phi}}f, K g \rangle \\
&= \langle f, \phi K g \rangle - \langle \overline{\phi}f, K g \rangle .
\end{align*}

This yields the estimate:
\begin{align*}
|\langle (S_\phi^* - K^*PM_{\overline{\phi}})\, f, g  \rangle| &\leq \|f\| \, \|\phi\|_\infty\|K g\| + \|\overline{\phi}\|_\infty\|f\| \, \|K g\| \\
&= 2\|\phi\|_\infty\|f\| \, \|g\|.
\end{align*}

Now let $\{f_n\}$ be a sequence with $f_n \to 0$ weakly. Setting $f = f_n$ and $g = (S_\phi^* - K^*PM_{\overline{\phi}}) f_n$ gives
\[
\|(S_\phi^* - K^*PM_{\overline{\phi}}) f_n\|^2 \leq 2\|\phi\|_\infty\|f_n\| \, \|(S_\phi^* - K^*PM_{\overline{\phi}}) f_n\|
\]

By Lemma \ref{lem:compact_embedding}, $\|f_n\| \to 0$ weakly as $n\to \infty$, which implies $\|(S_\phi^* - K^*PM_{\overline{\phi}}) f_n\| \to 0$.\\ Thus, $S_\phi^* - K^*PM_{\overline{\phi}}$ maps weakly convergent sequences to norm convergent ones, proving its compactness.
\end{proof}



We now investigate the compactness of H-Toeplitz operators $S_\phi$ on $F_\alpha^2$ using the Berezin transform technique.

\begin{definition}
For a bounded linear operator $T$ on a reproducing kernel Hilbert space $\mathcal{H}$ with normalized reproducing kernels $\{k_z\}_{z\in\mathcal{H}}$, the \emph{Berezin transform} of $T$ is the function
\[
\widetilde{T}(z) = \langle Tk_z, k_z \rangle, \quad z \in \mathcal{H}.
\]
\end{definition}
For the Fock space $F_\alpha^2$, the normalized reproducing kernel is given by

\begin{lemma}
The normalized reproducing kernel for $F_\alpha^2$ has the explicit form:
\begin{align*}
k_z(w) &= \frac{K_z(w)}{\|K_z\|} = e^{-\frac{\alpha|z|^2}{2}} e^{\alpha\overline{z}w} \\
&= e^{-\frac{\alpha|z|^2}{2}} \sum_{n=0}^\infty \frac{(\alpha\overline{z}w)^n}{n!}, \quad z, w \in \mathbb{C}.
\end{align*}
Moreover, $k_z \to 0$ weakly as $|z| \to \infty$.
\end{lemma}

\begin{proposition}\label{prop:berezen_bound}
For any harmonic symbol $\psi \in L^\infty(\mathbb{C})$, the Berezin transform satisfies
\[
\|\widetilde{S_\psi}\|_\infty \leq \|\psi\|_\infty.
\]
\end{proposition}

\begin{proof}
For fixed $z \in \mathbb{C}$, we compute:
\begin{align*}
|\widetilde{S_\psi}(z)| &= |\langle S_\psi k_z, k_z \rangle| \\
&\leq \|S_\psi k_z\| \, \|k_z\| \\
&\leq \|S_\psi\| \\
&= \|PM_\psi K\| \\
&\leq \|M_\psi\| \, \|K\| \\
&= \|\psi\|_\infty.
\end{align*}
The last equality follows since $\|K\| = 1$ and $\|M_\psi\| = \|\psi\|_\infty$.
\end{proof}

%\section{Dilation Operator Analysis}

%The dilation operator $K$ plays a crucial role in our analysis.

\begin{lemma}\label{lem:dilation_action}
The dilation operator $K$ acts on normalized kernel as
\[
K(k_z)(w) = e^{-\frac{\alpha|z|^2}{2}} \left[ \sum_{n=0}^\infty \sqrt{\frac{\alpha^{3n}}{(2n)!n!}} \overline{z}^{2n} w^n + \sum_{n=0}^\infty \sqrt{\frac{\alpha^{3n+2}}{(2n+1)!(n+1)!}} \overline{z}^{2n+1} \overline{w}^{n+1} \right]  for \,\, z, w \in \mathbb{C}.
\]
\end{lemma}

\begin{proof}
Using the orthonormal basis representation, we compute:
\begin{align*}
K(k_z)(w) &= e^{-\frac{\alpha|z|^2}{2}} \sum_{n=0}^\infty \frac{\alpha^n}{n!} \overline{z}^n K(e_n)(w) \\
&= e^{-\frac{\alpha|z|^2}{2}} \left[ \sum_{n=0}^\infty \sqrt{\frac{\alpha^{2n}}{(2n)!}} \overline{z}^{2n} e_n(w) + \sum_{n=0}^\infty \sqrt{\frac{\alpha^{2n+1}}{(2n+1)!}} \overline{z}^{2n+1} \overline{e_{n+1}}(w) \right] \\
&=\frac{1}{e^{\alpha \frac{|z|^2}{2}}} \left[\sum\limits^\infty_{n=0} \sqrt{\frac{\alpha^{2n}}{(2n)!}} \overline{z}^{2n} \sqrt{\frac{\alpha^n}{n!}} w^n+\sum\limits^\infty_{n=0} \sqrt{\frac{\alpha^{2n+1}}{(2n+1)!}} \overline{z}^{2n+1} \sqrt{\frac{\alpha^{n+1}}{(n+1)!}} \overline{w}^{n+1} \right]\cr
&=\frac{1}{e^{\alpha \frac{|z|^2}{2}}} \left[\sum\limits^\infty_{n=0} \sqrt{\frac{\alpha^{2n} \, \alpha^n}{(2n)! \, n!}} \overline{z}^{2n} w^n+\sum\limits^\infty_{n=0} \sqrt{\frac{\alpha^{2n+1}\, \alpha^{n+1}}{(2n+1)! \, (n+1)!}} \overline{z}^{2n+1} \overline{w}^{n+1} \right]\\
&= e^{-\frac{\alpha|z|^2}{2}} \left[ \sum_{n=0}^\infty \sqrt{\frac{\alpha^{3n}}{(2n)!n!}} \overline{z}^{2n} w^n + \sum_{n=0}^\infty \sqrt{\frac{\alpha^{3n+2}}{(2n+1)!(n+1)!}} \overline{z}^{2n+1} \overline{w}^{n+1} \right]
\end{align*}
which hold for all $w \in \mathbb{C}$.
This completes the proof of the lemma.
\end{proof}

\begin{definition}
For $z, w \in \mathbb{C}$, define the kernel function
\[
I(z,w) := K(k_z)(w).
\]
\end{definition}

The boundary behavior of $I(z,w)$ as $|z| \to \infty$ will be discussed in the subsequent analysis.



\begin{lemma}\label{lem:kernel_decay}
For each fixed $w \in \mathbb{C}$, the kernel function $I(z,w) \to 0$ as $|z| \to \infty$.
\end{lemma}

\begin{proof}
From Lemma \ref{lem:dilation_action}, we have the explicit representation:
\[
I(z,w) = e^{-\frac{\alpha|z|^2}{2}} \left[ \sum_{n=0}^\infty c_n \overline{z}^{2n} w^n + \sum_{n=0}^\infty d_n \overline{z}^{2n+1} \overline{w}^{n+1} \right],
\]
where $c_n = \sqrt{\frac{\alpha^{3n}}{(2n)!n!}}$ and $d_n = \sqrt{\frac{\alpha^{3n+2}}{(2n+1)!(n+1)!}}$. 

The exponential decay term $e^{-\alpha|z|^2/2}$ dominates the polynomial growth in $z$, ensuring that $I(z,w) \to 0$ as $|z| \to \infty$ for any fixed $w \in \mathbb{C}$.
\end{proof}

\begin{proposition}\label{prop:berezin_integral}
For $\phi \in L^\infty(\mathbb{C})$, the Berezin transform of $S_\phi$ admits the integral representation:
\[
\widetilde{S_\phi}(z) = e^{-\frac{\alpha|z|^2}{2}} \int_{\mathbb{C}} \phi(w) I(z,w) e^{\alpha z\overline{w}} d\lambda_\alpha(w).
\]
Moreover, $\widetilde{S_\phi}(z) \to 0$ as $|z| \to \infty$.
\end{proposition}

\begin{proof}
We compute directly using the reproducing kernel property:
\begin{align*}
\widetilde{S_\phi}(z) &= \langle S_\phi k_z, k_z \rangle \\
&= \langle P M_\phi Kk_z, k_z \rangle \\
&= \langle \phi(w) I(z,w), k_z(w) \rangle \\
&= \int_{\mathbb{C}} \phi(w)\, I(z,w)\, \overline{k_z(w)}\, d\lambda_\alpha(w) \\
&= e^{-\frac{\alpha|z|^2}{2}} \int_{\mathbb{C}} \phi(w)\, I(z,w) e^{\alpha z\overline{w}} d\lambda_\alpha(w).
\end{align*}
The decay follows from Lemma \ref{lem:kernel_decay} and clearly we can see that \, $\widetilde{S_\phi}(z) \to 0$ as $|z| \to \infty$.
\end{proof}

\begin{lemma}\label{lem:compact_support}
Let $M \subset \mathbb{C}$ be a compact subset and $\phi \in L^\infty(\mathbb{C})$ with $\phi= 0$ on $\mathbb{C} \setminus M$. Then the Toeplitz operator $T_\phi$ is compact on $F_\alpha^2$.
\end{lemma}


\begin{theorem}\label{thm:compact_harmonic}
Let $\phi$ be a uniformly continuous harmonic function on $\mathbb{C}$. Then the H-Toeplitz operator $S_\phi$ is compact on $F_\alpha^2$ if and only if 
\[
\lim_{|z|\to\infty} \phi(z) = 0.
\]
\end{theorem}


\begin{remark}
The Hilbert-Schmidt criterion provides an alternative perspective:
\begin{itemize}
\item[(i)] Non-zero H-Toeplitz operators cannot be Hilbert-Schmidt on $F_\alpha^2$.
\item[(ii)] This follows from the direct computation of the Hilbert-Schmidt norm.
\end{itemize}
\end{remark}

\begin{theorem}
For any bounded harmonic function $\phi \in L^\infty(\mathbb{C})$, the H-Toeplitz operator $S_\phi$ is Hilbert-Schmidt on $F_\alpha^2$ if and only if $\phi \equiv 0$.
\end{theorem}

\begin{proof}
($\Rightarrow$) Assume $S_\phi$ is Hilbert-Schmidt. Then its Hilbert-Schmidt norm must be finite

\begin{equation}\label{eq:HSnorm}
\sum_{n=0}^\infty \|S_\phi e_n\|^2 < \infty ,
\end{equation}

where $\{e_n\}_{n=0}^\infty$ is the standard orthonormal basis of $F_\alpha^2$. For a harmonic symbol $\phi(z) = \displaystyle\sum_{i=0}^\infty a_i z^i + \sum_{j=1}^\infty b_j \overline{z}^j$, we compute:

\begin{align*}
\|S_\phi e_n\|^2 &= \|P M_\phi K e_n\|^2 \\
&= \begin{cases}
\|P M_\phi e_{n/2}\|^2 & \text{if } n \text{ even} \\
\|P M_\phi \overline{e_{(n+1)/2}}\|^2 & \text{if } n \text{ odd} .
\end{cases}
\end{align*}

Expanding these terms using the basis representation

\begin{align*}
\sum_{n=0}^\infty \|S_\phi e_n\|^2 &= \sum_{n=0}^\infty \|P M_\phi e_n\|^2 + \sum_{n=0}^\infty \|P M_\phi \overline{e_{n+1}}\|^2 \\
&= \sum_{n=0}^\infty \left\|P\left(\sum_{i=0}^\infty a_i z^i + \sum_{j=1}^\infty b_j \overline{z}^j\right)\sqrt{\frac{\alpha^n}{n!}}z^n\right\|^2 \\
&\quad + \sum_{n=0}^\infty \left\|P\left(\sum_{i=0}^\infty a_i z^i + \sum_{j=1}^\infty b_j \overline{z}^j\right)\sqrt{\frac{\alpha^{n+1}}{(n+1)!}}\overline{z}^{n+1}\right\|^2.
\end{align*}

Computing the projections yields

\begin{align*}
&= \sum_{n=0}^\infty \frac{\alpha^n}{n!} \left\|\sum_{i=0}^\infty a_i z^{i+n} + \sum_{j=1}^n b_j \frac{n!}{\alpha^j (n-j)!} z^{n-j}\right\|^2 \\
&\quad + \sum_{n=0}^\infty \frac{\alpha^{n+1}}{(n+1)!} \left\|\sum_{i=n+1}^\infty a_i \frac{i!}{\alpha^{n+1}(i-n-1)!} z^{i-n-1}\right\|^2.
\end{align*}

Calculating the norms explicitly

\begin{align*}
&= \sum_{n=0}^\infty \frac{\alpha^n}{n!} \left(\sum_{i=0}^\infty |a_i|^2 \frac{(i+n)!}{\alpha^{i+n}} + \sum_{j=1}^n |b_j|^2 \frac{(n!)^2}{\alpha^{2j}(n-j)!^2} \frac{(n-j)!}{\alpha^{n-j}}\right) \\
&\quad + \sum_{n=0}^\infty \frac{\alpha^{n+1}}{(n+1)!} \sum_{i=n+1}^\infty |a_i|^2 \frac{(i!)^2}{\alpha^{2n+2}(i-n-1)!^2} \frac{(i-n-1)!}{\alpha^{i-n-1}}.
\end{align*}

Simplifying the expressions

\begin{align*}
&= \sum_{n=0}^\infty \left(\sum_{i=0}^\infty |a_i|^2 \frac{(i+n)!}{n! \alpha^i} + \sum_{j=1}^n |b_j|^2 \frac{n!}{\alpha^{n+j}(n-j)!}\right) \\
&\quad + \sum_{n=0}^\infty \sum_{i=n+1}^\infty |a_i|^2 \frac{\alpha^{n+1} i!^2}{(n+1)! \alpha^{2n+2} (i-n-1)! \alpha^{i-n-1}}.
\end{align*}

For this sum to converge, each coefficient must vanish:

\begin{itemize}
\item[(a)] The $a_i$ terms require $\sum_{i=0}^\infty |a_i|^2 \frac{(i+n)!}{n! \alpha^i} < \infty$ for all $n$, which forces $a_i = 0$ for all $i \geq 0$.
\item[(b)] The $b_j$ terms require $\sum_{j=1}^\infty |b_j|^2 \frac{n!}{\alpha^{n+j}(n-j)!} < \infty$ for all $n$, which forces $b_j = 0$ for all $j \geq 1$.
\end{itemize}

Thus $\phi \equiv 0$.

($\Leftarrow$) The zero operator is trivially Hilbert-Schmidt.
\end{proof}
\section{Graphical  analysis}

With the introduction of the concept of \textit{H-Toeplitz operators on Fock space}, a novel and compelling intersection has emerged between \textit{Operator Theory} and \textit{Graph Theory}. The structural characteristics of these operators, when examined through the lens of their associated graphs, exhibit intricate patterns that encapsulate the underlying algebraic  properties of the operators. The graphical representations of H-Toeplitz operators on Fock space offer valuable insights into their functional behavior, thereby enriching the broader dialogue between operator-theoretic analysis and combinatorial graph structures.

This avenue of research draws on foundational developments in the theory of classical Toeplitz operators~\cite{va}, the formulation of directed Toeplitz graphs~\cite{ma}, and further generalizations such as the investigation of compactness and non-compactness in $k^{th}$-order slant Toeplitz graphs~\cite{mp}. These prior contributions have played a pivotal role in bridging the realms of functional analysis and discrete mathematics, providing the essential theoretical scaffolding for the current exploration of H-Toeplitz operators and their graphical counterparts within the Fock space framework.

In the subsequent discussion, we undertake a comparative graphical analysis of H-Toeplitz operators associated with symbols of varying analytic nature. Specifically, we consider cases where the symbol $\phi(z)$ is  purely non-analytic, purely analytic, and a combination of both analytic and non-analytic components.
This classification enables a clearer understanding of how the analytic structure of the symbol influences the graphical behavior of the corresponding operator.


\begin{definition}A directed H-Toeplitz graph \( W \) is defined as $W_n \langle x_1, x_2, \ldots, x_p; y_1, y_2, y_3, \ldots, y_q \rangle$
with vertex set \( \{1, 2, 3, \ldots, n\} \) is a digraph whose adjacency matrix is an H-Toeplitz matrix in which the arc \( (i, j) \) occurs if and only if 
\[
j = (2i - 1) + x_k \quad \text{or} \quad i = \frac{j + 1}{2} + y_l
\]
for some \( 1 \leq k \leq p \) and \( 1 \leq l \leq q \).
\end{definition}
The main diagonal of an H-Toeplitz adjacency matrix of order \( n \times n \) is labelled 0. The \( n - 1 \) distinct diagonals above the main diagonal are labelled \( 1, 2, \ldots, n - 1 \), and those below are also labeled \( 1, 2, \ldots, n - 1 \). Let \( x_1, x_2, \ldots, x_p \) be the upper diagonals containing ones and \( y_1, y_2, \ldots, y_q \) be the lower diagonals containing ones, such that $0 < x_1 < x_2 < \ldots < x_p < n$
and $0 < y_1 < y_2 < \ldots < y_q < n$. Then the corresponding H-Toeplitz operator graph will be denoted by $W_n \langle x_1, x_2, \ldots, x_p; y_1, y_2, y_3, \ldots, y_q \rangle$.
.
\begin{example}
%\textbf{Non-analytic}. 
Let $\phi({z})=2\overline{z}^1+3\overline{z}^2+\overline{z}^3$ and take $\alpha=1$ in the definition of $S_\phi$, then the matrix representation of $S_\phi$ with respect to the orthonormal basis $\left\{e_n \right\}^\infty_{n=0}$ of Fock space $F_\alpha^2$ is given by
\[ S_\phi =
\begin{pmatrix}
0 & 0 & 2 & 0 & 3 & 0 & 1 & 0 & 0 & \cdots \\
0 & 0 & 0 & 0 & 2 & 0 & 3 & 0 & 1 & \cdots \\
0 & 0 & 0 & 0 & 0 & 0 & 2 & 0 & 3 & \cdots \\
0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & 2 & \cdots \\
0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & \cdots \\
0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & \cdots \\
0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & \cdots \\
0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & \cdots \\
\vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \ddots \\
\end{pmatrix}.
\]
The indicator binary matrix is given by 
\[ S_\phi =
\begin{pmatrix}
0 & 0 & 1 & 0 & 1 & 0 & 1 & 0 & 0 & \cdots \\
0 & 0 & 0 & 0 & 1 & 0 & 1 & 0 & 1 & \cdots \\
0 & 0 & 0 & 0 & 0 & 0 & 1 & 0 & 1 & \cdots \\
0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & 1 & \cdots \\
0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & \cdots \\
0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & \cdots \\
0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & \cdots \\
0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & 0 & \cdots \\
\vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \vdots & \ddots \\
\end{pmatrix}.
\]
Clearly, we can see that the above matrix is an upper triangular matrix in which all the diagonals are zero.
The corresponding H-Toeplitz graph of the above matrix will be \( W_{\infty}\langle 2,4,6;0\rangle\)  as given below

\begin{figure}[h]
\centering
\includegraphics[width=1\textwidth]{graph_Htoe.pdf}
\caption{\( W_{\infty}\langle 2,4,6;0\rangle\) }
\end{figure}
Consider the infinite digraph \( W_\infty \), where for any vertex \( n \), its out-degree are determined by the relation
\[
j = 2n + x_r - 1, \quad \text{with } x_r \in \{2, 4, 6\}.
\]
This generates the three outgoing edges $j = 2n + 1,  2n + 3, 2n + 5.$
Consequently, every vertex \( n \) has a constant out-degree of \( 3 \), resulting in the out-degree sequence:
\[
\text{Out-degree sequence: } (3, 3, 3, \dots).
\]
The indegree of a vertex \( n \) is derived by inverting the adjacency relation. The predecessors of \( n \) are obtained by solving for \( i \) in
$n = 2i - 1 + x_r, \quad x_r \in \{2, 4, 6\}.$
This yields $i = \frac{n - x_r + 1}{2}.$
For \( i \) to be a valid vertex, \( n - x_r + 1 \) must be a positive even integer. We analyze the indegree on a case-by-case basis
\begin{itemize}%[leftmargin=*]
 \begin{multicols}{5}
 \item[(a)] \(\text{indeg}(1) = 0\).
    \item[(b)] \(\text{indeg}(2) = 0\).
    \item [(c)]\(\text{indeg}(3) = 1\).
    \item [(d)]\(\text{indeg}(4) = 0\).
    \item[(e)] \(\text{indeg}(5) = 2\).   

\end{multicols}
\end{itemize}
For \( n \geq 6 \), the indegree depends on the parity of \( n \)
\[
\text{indeg}(n) = 
\begin{cases}
0 & \text{if } n \text{ is even}, \\
3 & \text{if } n \text{ is odd}.
\end{cases}
\]
Thus, the indegree sequence is
$(0, 0, 1, 0, 2, 0, 3, 0, 3, \dots).$ We can see there is no loop in the above digraph.
\end{example}
