\item \emph{The first method for consistent change point detection in the dense regime.} In a similar spirit to McScan \citep{cho2024detection}, which is shown to be minimax optimal in the sparse regime (\Cref{sec:sparse}), % designed for the sparse regime, 
we introduce the \emph{quadratic covariance scanning} (QcScan) that evaluates the $\ell_2$-aggregation of the contrasts in local sample covariances between regressors and responses.  
QcScan is the first method that achieves minimax optimality, up to a factor of $\sqrt{\log\log(n)}$, in detection and estimation of the change point in the dense regime. % (see \Cref{tab:minimax}). 
As a by-product, we also obtain an estimator for $\vert\bm\Sigma\bm\delta\vert_2^2$, which serves as a surrogate of the strength of the signal $\bm\delta^\top\bm\Sigma\bm\delta$ for the change point problem in~\eqref{eq:amoc}. See \Cref{sec:dense} for details. 

\item \emph{Adaptation to inherent sparsity.} % To address both sparse and dense regimes, 
We introduce OcScan which, by combining McScan and QcScan, adapts to the unknown level of sparsity and thus achieves optimal statistical performance uniformly across all $\mathfrak{s}$, providing a complete treatment of the change point detection problem in high-dimensional linear models. See \Cref{sec:adaptive} for details. 

\item \emph{Refinement of change point localisation.} We propose a procedure for further refinement of the change point estimator by incorporating the direct estimation of the differential parameter alongside covariance scanning. This refinement can improve the estimation rate by {up to a factor of $\sqrt p$}, provided that $\bm\delta$ itself is sufficiently sparse. See \Cref{sec:refine}. 

\item \emph{Computational efficiency.} In contrast to a plethora of existing methods that require repeated estimation of local regression parameters, the proposed methods based on covariance scanning, namely McScan, QcScan and OcScan, exhibit ideal worst-case computation complexity of $O(np)$, see \Cref{ss:comp}. 
This demonstrates that for the detection and estimation of a change point, computationally costly operations may be avoided without losing statistical efficiency. 
\end{enumerate}

We further corroborate our theoretical findings with simulation studies in \Cref{sec:sim}, and provide all proofs and technical details in the appendix.

\paragraph{Notations.}
For a matrix $\mbf A \in \R^{m \times n}$, we denote by $\Vert \mbf A \Vert$ and $\Vert \mbf A \Vert_F$ its operator and Frobenius norms, respectively.
For $0 \le a < b \le m$, we write $\mbf A_{a, b}$ to denote a sub-matrix of $\mbf A$ containing its $i$th rows for $a + 1 \le i \le b$; when $\mbf A$ is a vector, $\mbf A_{a, b}$ denotes the corresponding sub-vector.
For sequences $\{a_m\}$ and $\{b_m\}$ of positive numbers, we write $a_m \lesssim b_m$ or equivalently $a_m = O(b_m)$, if $a_m \le C b_m$ for some finite constant $C > 0$. If $a_m \lesssim b_m$ and $b_m \lesssim a_m$, we write $a_m \asymp b_m$. We write $a \vee b = \max(a, b)$ for $a, b \in \R$.
By $\mbf 0$ and $\mbf I$, we denote the vector of zeros and the identity matrix, respectively, whose dimensions depend on the context.

\section{Minimax lower bounds}
\label{sec:minimax}

% Important papers: \citet{Bar02,VeVi10,VeGa18}

\subsection{Isotropic case}
\label{sec:isotropic}

Let us define a model space under~\eqref{eq:amoc} as
\begin{multline*}
\mc P_{\bm\Sigma, \sigma}^{\mathfrak{s}, n, p}(\tau) = \Bigl\{ \p_{\cp, \bm\beta_0, \bm\beta_1} \;:\; \{(\mbf x_t, Y_t)\}_{t \in [n]} \sim \p_{\cp, \bm\beta_0, \bm\beta_1} \text{ \ such that \ } \mbf x_t \sim_{\iid} \mc N_p(\mbf 0, \bm\Sigma) \text{ and}\\
\text{independently \ }  \vep_t \sim_{\iid}\mc N (0,\sigma^2), \; 
Y_t = \mbf x_t^\top \bigl( \bm\beta_0 \cdot \mathbb{I}_{\{t \le \cp\}} + \bm\beta_1 \cdot \mathbb{I}_{\{t > \cp\}} \bigr) + \vep_t,
\\
\bm\delta = \bm\beta_1 - \bm\beta_0, \,
\Delta = \min(\cp, n - \cp), \,
 \, \Psi = \max(\vert \bm\Sigma^{1/2} \bm\beta_0 \vert_2, \vert \bm\Sigma^{1/2} \bm\beta_1 \vert_2, \sigma), 
\\
\vert \bm\Sigma^{1/2} \bm\delta\vert_0 = \mathfrak{s}
\text{ \ and \ } \vert \bm\Sigma^{1/2}\bm\delta\vert_2^2 \Delta \ge \tau \Psi^2\mathfrak{s} \log\bigl(1 + \tfrac{p}{\mathfrak{s}^2}\vee\tfrac{\sqrt{p}}{\mathfrak{s}}\bigr)\Bigr\}. 
\end{multline*} 
% \begin{multline*}
% \mc P_{\mathfrak{s}, \sigma}^{\tau, n, p} = \Bigl\{ \{(\mbf x_t, Y_t)\}_{t = 1}^n \text{ from model~\eqref{eq:model}} \;:\; q = 1,\;\mbf x_t \sim_{\iid} \mc N_p(\bm0, \mbf I), \text{ and }\\
% \text{ independently }  \vep_t \sim_{\iid}\mc N (0,\sigma^2), \; \vert\bm\delta\vert_0 = \mathfrak{s}
% \text{ and } \Delta\vert\bm\delta\vert_2^2 \ge \tau \sigma^2\mathfrak{s} \log\bigl(1 + \tfrac{p}{\mathfrak{s}^2}\vee\tfrac{\sqrt{p}}{\mathfrak{s}}\bigr)\Bigr\}. 
% \end{multline*} 

\begin{thm}
\label{th:gaussid}
Let $\sigma > 0$ and $1 \le \Delta \le n/4$, and suppose that $\bm\Sigma = \mbf I$.
\begin{enumerate}[label = (\roman*)]
\item\label{lem:lb:id:detect}
If $\mathfrak{s}\log\bigl(1 + \tfrac{p}{\mathfrak{s}^2}\vee\tfrac{\sqrt{p}}{\mathfrak{s}} \bigr) \le \sqrt{ \tfrac{25}{2}\log\l(\tfrac{17}{12\sqrt{2}}\r){\Delta}}$ and $0< \tau \le \tfrac{2}{5}\log\l(\tfrac{17}{12\sqrt{2}}\r)$, then
$$
\inf_{\wh\theta}\; \sup_{\p \in \mc P_{\mbf I, \sigma}^{\mathfrak{s}, n, p}(\tau)} \;\p\l(\bigl\vert\wh\theta -\theta(\p) \bigr\vert \ge {\Delta}\r)\; \ge\; \frac{1}{25}.
$$   
\item\label{lem:lb:id:locate}
Let $\tau$ be a large enough constant, or $\tau \to \infty$ (at an arbitrary rate) as $n\to \infty$. If \(\mathfrak{s}\log\bigl(1 + \tfrac{p}{\mathfrak{s}^2}\vee\tfrac{\sqrt{p}}{\mathfrak{s}}\bigr) \le \sqrt{ \tfrac{5}{2}\log\l(\tfrac{3}{2\sqrt{2}}\r)\tfrac{\Delta}{\tau}}\), then
\[
\inf_{\wh\theta}\; \sup_{\p \in \mc P_{\mbf I, \sigma}^{\mathfrak{s}, n, p}(\tau)} \;\p\l(\bigl\vert\wh\theta -\theta(\p) \bigr\vert \ge \frac{ \sigma^2\mathfrak{s}\log\l(\frac{3}{2\sqrt{2}}\r) \log\l(1 + \frac{p}{\mathfrak{s}^2}\vee \tfrac{\sqrt{p}}{\mathfrak{s}}\r)}{5\vert\bm\delta\vert_2^2}\r)\; \ge\; \frac{1}{4}.
\]
\end{enumerate}
\end{thm}

Theorem~\ref{th:gaussid} provides the minimax lower bounds on both the detection boundary and the rate of estimation for the change point problem in~\eqref{eq:amoc}, which reveals a phase transition with respect to the sparsity.  In an isotropic Gaussian setting with $\bm\Sigma = \mbf I$, the sparsity is determined by $\mathfrak{s} = \vert \bm\Sigma^{1/2} \bm\delta \vert_0 = \vert \bm\delta \vert_0 = \mathfrak{s}_\delta$, and the minimax lower bounds undergo a phase transition at $\mathfrak{s} = \sqrt{p}$, from that $\mathfrak{s} \log\bigl( 1 + \tfrac{p}{\mathfrak{s}^2} \vee \tfrac{\sqrt p}{\mathfrak{s}} \bigr) \asymp \mathfrak{s} \log(ep/\mathfrak{s}^2) \mathbb{I}_{\{\mathfrak{s} < \sqrt p\}} + \sqrt{p} \; \mathbb{I}_{\{\mathfrak{s} \ge \sqrt p\}}$. This phenomenon has hitherto been unknown in the literature, with the existing minimax lower bounds focusing on the sparse regime of $\mathfrak{s} < \sqrt{p}$ \citep{rinaldo2020localizing, cho2024detection}. Notably, one striking observation in the dense regime is that the minimax rate of estimation becomes a trivial one when $p \gtrsim n^2$. This stands in sharp contrast to the sparse regime, where consistent change point detection remains feasible even in ultra-high dimensions.

Figure~\ref{f:iderrex} numerically illustrates the phase transition as the sparsity ($x$-axis, in a log scale) and the sample size vary (left to right), while $\vert \bm\delta \vert_2 = 8$, $p = 900$ and other model parameters remains constant and $\bm\Sigma = \mbf I$.
The figure reports the scaled estimation errors ($y$-axis, in a square root scale) attained by various change point detection methods, including McScan (Section~\ref{sec:sparse}; a variant of \citealp{cho2024detection}) and QcScan (Section~\ref{sec:dense}) which are shown to be minimax (near-)optimal in the sparse and the dense regimes, respectively. 
While QcScan's estimation error remains roughly constant regardless $\mathfrak{s}$, McScan achieves a smaller error for the sparse situations which increases with $\mathfrak{s}$ until it cross that of QcScan near $\mathfrak{s} = \sqrt{p}$; similar behaviour is also observed from the competing methods (MOSEG and CHARCOAL) tailored for the sparse regime. 
The OcScan (Section~\ref{sec:adaptive}) which combines the outputs from McScan and QcScan, and its refinement OcScan.R (Section~\ref{sec:sim}), are able to adaptively enjoy the optimal performance of McScan and QcScan regardless of the regimes determined by $\mathfrak{s}$.
In particular, OcScan.R improves upon the estimators of McScan and OcScan in the sparse regime, which demonstrates the efficacy of the refinement proposed in Section~\ref{sec:refine}. 

