\section{Connection to the covariance change detection problems}
\label{sec:cov}

% In Introduction, we have extensively discussed existing results on change point analysis in linear models. 
The change point problem in linear models can be viewed as a special case of changes in covariances. Specifically, the AMOC model~\eqref{eq:amoc} is equivalent to  
\[
\bmx
\mbf x_t\\
Y_t
\emx
\sim_{\mathrm{ind.}} 
\begin{cases}
\mc N_{p+1}\l(\mbf 0, \bm\Sigma_0\r) & \text{for \ } 1 \le t \le \cp, \\
\mc N_{p+1}\l(\mbf 0, \bm\Sigma_1\r) & \text{for \ } \cp + 1 \le t \le n, 
\end{cases}
\quad\text{ with }\quad \bm\Sigma_i =\bmx\bm\Sigma & \bm\Sigma\bm\beta_i \\
\bm\beta_i^\top\bm\Sigma & \bm\beta_i^\top \bm\Sigma\bm\beta_i  + \sigma^2\emx.
\]
This perspective allows us to draw connections with the literature on covariance change detection in high dimensions.

\citet{wang2021optimal} proposed a projection-based binary segmentation method and established its consistency.
Their Assumption~3 on detection requirement translates to our setting~as % follows:
\begin{align}
\label{eq:cov:dlb}
\Delta \kappa^2 \gtrsim  B^2 p\log(n)
\end{align}
where $B = \max(\Vert \bm\Sigma \Vert, \Psi^2)$ and $\kappa = \Vert \bm\Sigma_1 - \bm\Sigma_0 \Vert$, which satisfies 
\begin{align*}
\max(\vert \bm\Sigma \bm\delta \vert_2^2, \vert \bm\beta_0^\top \bm\Sigma \bm\beta_0 - \bm\beta_1^\top \bm\Sigma \bm\beta_1 \vert^2) \le \kappa^2 &\le 2\max(\vert \bm\Sigma \bm\delta \vert_2^2, \vert \bm\beta_0^\top \bm\Sigma \bm\beta_0 - \bm\beta_1^\top \bm\Sigma \bm\beta_1 \vert^2).
% \\
% &\le 2\max(\vert \bm\Sigma \bm\delta \vert_2^2, 2 \Psi \vert \bm\Sigma^{1/2} \bm\delta \vert_2).
\end{align*}
To ease comparison, assume that $\Var(Y_t)$ remains invariant before and after the change, i.e.\ 
\begin{equation}\label{e:ev}
\bm\beta_0^\top \bm\Sigma \bm\beta_0 = \bm\beta_1^\top \bm\Sigma \bm\beta_1.
\end{equation} 
Ignoring logarithmic factors, our detection requirement~\eqref{eq:sparse:dlb} is weaker than~\eqref{eq:cov:dlb} by a factor of $p / \min(\Vert \bm\Sigma \Vert \sigma_*^{-1} \mathfrak{s}, \mathfrak{s}_*)$, with $\mathfrak{s}_* = \vert\bm\Sigma \bm\delta\vert_0$, and~\eqref{eq:dense:dlb} is weaker by a factor of $\sqrt{p}$. 
Thus, with OcScan (\Cref{sec:adaptive}), we achieve an improvement by a factor of 
\begin{align*}
\frac{p}{\min(\Vert \bm\Sigma \Vert \sigma_*^{-1} \mathfrak{s}, \, \mathfrak{s}_*, \, \sqrt{p})}.
\end{align*}
It is important to note that the requirement~\eqref{eq:cov:dlb} is minimax optimal, up to $\log(n)$, for the covariance change point problem in general \citep[Lemma~3.1]{wang2021optimal}.
The improved detection performance of OcScan arises from leveraging the specific structure of the linear model, which also enables the careful analysis of the phase transition with respect to the inherent sparsity $\mathfrak{s}$.
Additionally, the estimation rate achieved by our refined procedure described in \Cref{sec:refine}, nearly matches the minimax lower bound of order $\kappa^{-2} B^2$ reported in \citet[Lemma~3.2]{wang2021optimal}.

\cite{moen2024minimax} investigated the minimax optimality in covariance change point testing over the class of parameters that are \textit{$d$-sparse} for any $d \in [p]$, defined as
\begin{align*}
\Lambda^d_{\max}(\bm\Sigma_1 - \bm\Sigma_0) := \sup_{\substack{\mbf v: \, \vert \mbf v \vert_2 = 1, \\ \vert \mbf v \vert_0 = d}} \vert \mbf v^\top (\bm\Sigma_1 - \bm\Sigma_0) \mbf v \vert,
\end{align*}
which implies that the leading eigenvector of $\bm\Sigma_1 - \bm\Sigma_0$ is sparse with $d$ non-zero elements.
Their (computationally intractable) test matches the minimax lower bound on the detection boundary, which requires
\begin{align}
\l( \frac{\Lambda^d_{\max}(\bm\Sigma_1 - \bm\Sigma_0)}{\Lambda^d_{\max}(\bm\Sigma_0) \vee \Lambda^d_{\max}(\bm\Sigma_1)} \r)^2 \Delta\; \gtrsim\; d\log(ep/d) \vee \log\log(8n)
\label{eq:moen}
\end{align}
for \textit{some} $d$.
Some elementary calculations show that
\begin{align*}
& \Lambda^d_{\max}(\bm\Sigma_0) \vee \Lambda^d_{\max}(\bm\Sigma_1) \ge \max\l\{\Psi^2, \max_{i \in [p]} (\bm\Sigma)_{i, i} \r\},
\\
& \Lambda^d_{\max}(\bm\Sigma_1 - \bm\Sigma_0) \le \Vert \bm\Sigma_1 - \bm\Sigma_0 \Vert \le \Vert \bm\Sigma_1 - \bm\Sigma_0 \Vert_F \lesssim \vert \bm\Sigma \bm\delta \vert_2 + \vert \bm\beta_1^\top \bm\Sigma \bm\beta_1 - \bm\beta_0^\top \bm\Sigma \bm\beta_0 \vert,
% \\
% & \Lambda^d_{\max}(\bm\Sigma_1 - \bm\Sigma_0) \le d \vert \bm\Sigma \bm\delta \vert_\infty,
\end{align*}
where $(\bm\Sigma)_{i, i'}$ denotes the element in the $i$th row and $i'$th column of $\bm\Sigma$.
To facilitate the comparison between~\eqref{eq:moen} and our results, we relate the notion of $d$-sparsity and the sparsity of $\bm\Sigma \bm\delta$, as $d = \mathfrak{s}_* + 1$.
Then, again assuming~\eqref{e:ev}, our requirement that either~\eqref{eq:sparse:dlb} or~\eqref{eq:dense:dlb} holds, is weaker than~\eqref{eq:moen} by a factor of $\max(d/\sqrt{p}, 1)$, save logarithmic factors. 
That is, the detection boundary of OcScan is more favourable in the scenario where $d \ge \sqrt{p}$. 

Finally, \citet{DePaYa22} investigated the covariance change point estimation problem by imposing the sparsity directly on $\bm\Sigma_1 - \bm\Sigma_0$.
For estimation consistency, their proposed method requires that 
$\vert\bm\Sigma_j\vert_{\infty}\lesssim 1$, $(\bm\Sigma_j)_{i,i} \lesssim 1$, for $i \in[p+1]$ and $j\in\{0,1\}$, and 
$$
\min\bigl\{\vert(\bm\Sigma_0 - \bm\Sigma_1)_{i,j}\vert :  (\bm\Sigma_0 - \bm\Sigma_1)_{i,j} \neq 0\bigr\} \Delta^2  \; \gtrsim\; n^{3/2}\log(p\vee n),
$$
which translates to $\min\bigl\{\vert(\bm\Sigma\bm\delta)_{i}\vert : (\bm\Sigma\bm\delta)_{i} \neq 0\bigr\} \Delta^2 \gtrsim n^{3/2} \log(p\vee n)$, in our setting. 
This is stricter than our requirement~\eqref{eq:sparse:dlb}, which is $\vert\bm\Sigma\bm\delta\vert_{\infty}^2 \Delta \gtrsim \log(p \log(n))$, since  $1/\sqrt{\Delta} \le n^{3/2}/\Delta^2$ due to $\Delta \le n$.


\section{Proofs}

\subsection{Proofs for the results in Section~\ref{sec:minimax}}

\subsubsection{Proof of Theorem~\ref{th:gaussid}}

\begin{proof}[Proof of \ref{lem:lb:id:detect}]
Let $\mathbf{1}^{\pm}_S$ denote a $p$-dimensional vector with its $i$-th entry being $1$ or $-1$ if $i \in S$ and being zero if $i \not\in S$, and introduce $\mathcal{U} = \bigl\{\bm{u} = ({\kappa}/{\sqrt{\mathfrak{s}}})\mathbf{1}^{\pm}_S \in \R^p:  S \subseteq [p],  \; \vert S \vert = \mathfrak{s} \bigr\}$, whose cardinality  is $2^{\mathfrak s}{p \choose \mathfrak s}$. Define
\[
\p_1 = 2^{-\mathfrak{s}}{p \choose \mathfrak{s}}^{-1} \sum_{\bm{u} \in \mathcal{U}}\p_{\Delta, \bm u, \bm 0} \quad \text{and}\quad \p_2 = 2^{-\mathfrak{s}}{p \choose \mathfrak{s}}^{-1} \sum_{\bm{u} \in \mathcal{U}}\p_{n-\Delta, \bm 0, \bm u}.
\]
Note that $\p_{\Delta, \bm u, \bm 0}$ and $\p_{n-\Delta, \bm 0, \bm u}$ lie in $\mc P_{\mathfrak{s}, \sigma}^{\tau, n, p}$ under proper choices of $\kappa$ and $\Delta$, see \eqref{e:rho} below. By the method of fuzzy hypotheses (see e.g.\ Section~2.7.4 in \citealp{Tsy09}), we have
$$
\inf_{\wh\theta}\; \sup_{\p \in \mc P_{\mbf I, \sigma}^{\mathfrak{s}, n, p}(\tau)} \;\p\l(\bigl\vert\wh\theta -\theta(\p)\bigr\vert \ge \Delta\r)\; 
\ge\;  \frac{1-\sqrt{2\alpha}}{2} \qquad \text{with}\quad \alpha := \chi^2(\p_{1},\p_{0}) = \chi^2(\p_{2},\p_{0}),
$$
where $\p_{0}$ denotes the distribution of $\{(\mbf x_t,  Y_t)\}_{t\in [n]}$ such that  $\mbf x_t \sim_{\iid} \mc N_p(\mbf 0, \mbf I)$ and
independently  $Y_t \sim_{\iid}\mc N (0,\sigma^2)$.  
Define $\p_{\bm u}$ as in Lemma~\ref{l:cross}, and $Z_k$ as the sum of $k$ independent Rademacher random variables. Then, by Lemma~\ref{l:cross},  we have%\footnote{Here we require $2\kappa^2< \sigma^2$. }
\begin{align*}
\alpha + 1 &=2^{-2\mathfrak{s}}{p \choose \mathfrak{s}}^{-2}\sum_{\bm u, \bm v \in \mc U} \l[\E_{\p_{\bm0}}\l(\frac{\mathrm{d}\p_{\bm u}}{\mathrm{d}\p_{\bm 0}}\frac{\mathrm{d}\p_{\bm v}}{\mathrm{d}\p_{\bm 0}}\r)\r]^{\Delta}  \\
& = {p \choose \mathfrak{s}}^{-2}\sum_{S, T \subseteq [p],\, \vert S\vert = \vert T\vert = \mathfrak{s}} \E \l[\l(\l(1-\frac{Z_{\vert S \cap T\vert}}{\mathfrak{s}}\frac{\kappa^2}{\sigma^2}\r)^2 - \l(\frac{\kappa^2}{\sigma^2}\r)^2\r)^{-\Delta/2}\r] \\
& = {p \choose \mathfrak{s}}^{-1}\sum_{S \subseteq [p],\, \vert S\vert = \mathfrak{s}} \E\l[\l(\l(1-\frac{Z_{\vert S \cap [\mathfrak s]\vert}}{\mathfrak{s}}\frac{\kappa^2}{\sigma^2}\r)^2 - \l(\frac{\kappa^2}{\sigma^2}\r)^2\r)^{-\Delta/2}\r].
\end{align*}
Let $\rho := \kappa^2 / \sigma^2$ and consider %\footnote{Here we require \(4\kappa^2 \le \sigma^2\).} 
$\rho \le 1/4$. Then, by Lemma~\ref{l:basic},
\begin{align*}
\E\l[\l(\l(1-\frac{Z_{\vert S \cap [\mathfrak s]\vert}}{\mathfrak{s}}\frac{\kappa^2}{\sigma^2}\r)^2 - \l(\frac{\kappa^2}{\sigma^2}\r)^2\r)^{-\Delta/2}\r] & \le \E\l[\l(1-2\rho\cdot\frac{Z_{\vert S \cap [\mathfrak s]\vert}}{\mathfrak{s}}- \rho^2\r)^{-\Delta/2}\r] \\
& \le \exp(\Delta \rho^2)\E\l[\l(1-\frac{2\rho}{1-\rho^2}\cdot\frac{ Z_{\vert S \cap [\mathfrak s]\vert}}{\mathfrak{s}}\r)^{-\Delta/2}\r].
\end{align*}
By symmetry of Rademacher distribution, we can find an event $A$ such that $\p(A) = 1/2$, $A \subseteq \{Z_{\vert S \cap [\mathfrak s]\vert} \ge 0\}$ and $A^c \subseteq \{Z_{\vert S \cap [\mathfrak s]\vert} \le 0\}$. As $2\rho/(1-\rho^2)\le 8/15 \le 3/4$, we apply again Lemma~\ref{l:basic} and obtain
\begin{align*}
&\E\l[\l(1-\frac{2\rho}{1-\rho^2}\cdot\frac{ Z_{\vert S \cap [\mathfrak s]\vert}}{\mathfrak{s}}\r)^{-\Delta/2}\r] \\ 
\le \; &  \E\l[\mathbf{1}_{A}\cdot\exp\l( \Delta \cdot \frac{2\rho}{1-\rho^2}\cdot\frac{Z_{\vert S \cap [\mathfrak s]\vert}}{\mathfrak{s}}\r)\r] +  \E\l[\mathbf{1}_{A^c}\cdot\exp\l( \frac{\Delta}{4} \cdot \frac{2\rho}{1-\rho^2}\cdot\frac{Z_{\vert S \cap [\mathfrak s]\vert}}{\mathfrak{s}}\r)\r]\\
\le \; &   \l(\frac{1}{2} \E\l[\exp\l(2 \Delta \cdot \frac{2\rho}{1-\rho^2}\cdot\frac{Z_{\vert S \cap [\mathfrak s]\vert}}{\mathfrak{s}}\r)\r]\r)^{1/2} + \l(\frac{1}{2} \E\l[\exp\l(\frac{\Delta}{2} \cdot \frac{2\rho}{1-\rho^2}\cdot\frac{Z_{\vert S \cap [\mathfrak s]\vert}}{\mathfrak{s}}\r)\r]\r)^{1/2}\\
=  \; & \frac{\sqrt{2}}{2} \l[\cosh\l( \frac{2\Delta }{\mathfrak{s}}\cdot\frac{2\rho}{1-\rho^2}\r)\r]^{\vert S \cap [\mathfrak s]\vert/2} + \frac{\sqrt{2}}{2}\l[\cosh\l( \frac{\Delta }{\mathfrak{2s}}\cdot\frac{2\rho}{1-\rho^2}\r)\r]^{\vert S \cap [\mathfrak s]\vert/2}\\
\le \; & \sqrt{2} \l[\cosh\l( \frac{2\Delta }{\mathfrak{s}}\cdot\frac{2\rho}{1-\rho^2}\r)\r]^{\vert S \cap [\mathfrak s]\vert/2},
\end{align*}
where the second inequality is by Hölder's inequality. Note that the summation involving $\vert S \cap [\mathfrak s]\vert$ can be seen as the expectation of the hypergeometric distribution with parameters $(p, \mathfrak{s}, \mathfrak{s})$. Let $\xi \sim \mathrm{Bin}(\mathfrak{s}, \mathfrak{s}/p)$. Combining the above calculation and applying Lemma~\ref{l:dila}, we obtain
\begin{align*}
\alpha + 1 \le\; & \sqrt{2}\exp(\Delta \rho^2)\cdot \E \l[\cosh\l( \frac{2\Delta }{\mathfrak{s}}\cdot\frac{2\rho}{1 - \rho^2}\r)^{\xi /2}\r]\\
=\; & \sqrt{2}\exp(\Delta \rho^2)\cdot\exp \l[\mathfrak{s}\log\l(1+\frac{\mathfrak{s}}{p}\l\{\cosh\l(\frac{2\Delta }{\mathfrak{s}}\cdot\frac{2\rho}{1 - \rho^2}\r)^{1/2}-1\r\}\r)\r] \\
\le \; &  \sqrt{2}\exp(\Delta \rho^2)\cdot\exp \l[\mathfrak{s}\log\l(1+\frac{\mathfrak{s}}{p}\l\{\cosh\l(\frac{5\Delta\rho }{\mathfrak{s}}\r)^{1/2}-1\r\}\r)\r].
\end{align*}
We set \(\rho\) such that
\begin{equation}\label{e:rho}
\frac{5\Delta \rho}{\mathfrak{s}} = \log \l(1 + \frac{p}{\mathfrak{s}^2}\log\l(\frac{17}{12\sqrt{2}}\r) + \sqrt{\l(1 + \frac{p}{\mathfrak{s}^2}\log\l(\frac{17}{12\sqrt{2}}\r)\r)^2 - 1}\r) 
\end{equation}
It together with $\mathfrak{s}\log\bigl(1 + \tfrac{p}{\mathfrak{s}^2}\vee\tfrac{\sqrt{p}}{\mathfrak{s}}\bigr) \le \sqrt{ \tfrac{25}{2}\log\l(\tfrac{17}{12\sqrt{2}}\r){\Delta}}$ implies
%\footnote{This guarantees the requirement by the previous footnotes, i.e.\ $\rho\le1/4$.}
\[
 \Delta \rho^2   = \frac{\Delta^2\rho^2}{\Delta} \le \frac{\mathfrak{s}^2\log^2\l(1+\frac{p}{\mathfrak{s}^2}\vee\frac{\sqrt{p}}{\mathfrak{s}}\r)}{25\Delta} \le 
 \frac{1}{2}\log\l(\frac{17}{12\sqrt{2}}\r). \label{e:rho2}
\]
Further, by the identity $\cosh\bigl(\log(1+x+\sqrt{x^2+2x})\bigr) = 1+x$ and the inequality $\sqrt{1 +x }\le 1 + x/2$, for $x\ge 0$, we have
\begin{equation*}
\alpha + 1 \le \sqrt{2}\exp(\Delta \rho^2)\cdot \l(1 + \frac{1}{2\mathfrak{s}} \log\l(\frac{17}{12\sqrt{2}}\r)\r)^{\mathfrak{s}}
\le  \frac{17}{12},
\end{equation*}
which leads to $\alpha \le 5/12$, and thus
\[
\inf_{\wh\theta}\; \sup_{\p \in \mc P_{\mbf I, \sigma}^{\mathfrak{s}, n, p}(\tau)} \;\p\l(\bigl\vert\wh\theta -\theta(\p)\bigr\vert \ge \Delta\r)\; 
\ge\;  \frac{1-\sqrt{2\alpha}}{2} \; \ge \; \frac{1-\sqrt{5/6}}{2} \;>\;\frac{1}{25}. 
\]
Since $\log(1+ux)\ge u\log(1+x)$ for $x \ge 0$ and $u\in[0,1]$, we derive from \eqref{e:rho} that
\[
\frac{\Delta \rho}{\mathfrak{s}}\ge \frac{2}{5}\log\l(\frac{17}{12\sqrt{2}}\r)\log\l(1 + \frac{p}{\mathfrak{s}^2} \vee \frac{\sqrt{p}}{\mathfrak{s}}\r).
\]
\end{proof}

\begin{proof}[Proof of \ref{lem:lb:id:locate}] We adopt the notation from Part \ref{lem:lb:id:detect} and consider now the following fuzzy hypotheses 
\[
\p_1 = 2^{-\mathfrak{s}} {p \choose \mathfrak{s}}^{-1} \sum_{\bm u\in \mc U}\p_{\Delta, \bm u, \bm 0}\quad\text{and}\quad
\p_2 =2^{-\mathfrak{s}} {p \choose \mathfrak{s}}^{-1} \sum_{\bm u\in \mc U}\p_{\Delta+2\gamma,  \bm u, \bm 0},
\]
where $\Delta\rho = \tau \mathfrak{s} \log\bigl(1 + \tfrac{p}{\mathfrak{s}^2}\vee\tfrac{\sqrt{p}}{\mathfrak{s}}\bigr)$ and $\gamma \le \Delta/2$. Then, similarly, we have
\[
\inf_{\wh\theta}\; \sup_{\p \in \mc P_{\mbf I, \sigma}^{\mathfrak{s}, n, p}(\tau)} \;\p\l(\bigl\vert\wh\theta -\theta(\p)\bigr\vert \ge \gamma\r)\;
\ge\;\frac{1-\sqrt{\alpha/2}}{2},
\]
where $\alpha = \chi^2(\p_{2},\p_{1})$ and thus 
\[
\alpha \; =\; {p \choose \mathfrak{s}}^{-1}\sum_{S \subseteq [p],\, \vert S\vert = \mathfrak{s}} \l(\l(1-\frac{Z_{\vert S \cap [\mathfrak s]\vert}}{\mathfrak{s}}\rho\r)^2 -\rho^2\r)^{-\gamma} - 1.
\]
Again by the similar calculation as in Part~\ref{lem:lb:id:detect}, we have
\begin{equation*}
 \alpha + 1 \;  \le \;  \sqrt{2}\exp(2\gamma \rho^2)\cdot\exp \l[\mathfrak{s}\log\l(1+\frac{\mathfrak{s}}{p}\l\{\cosh\l(\frac{10\gamma\rho }{\mathfrak{s}}\r)^{1/2}-1\r\}\r)\r].
\end{equation*}
We set $\gamma$ such that 
\begin{equation}\label{e:gamma}
\frac{10\gamma \rho}{\mathfrak{s}} = \log \l(1 + \frac{p}{\mathfrak{s}^2}\log\l(\frac{3}{2\sqrt{2}}\r) + \sqrt{\l(1 + \frac{p}{\mathfrak{s}^2}\log\l(\frac{3}{2\sqrt{2}}\r)\r)^2 - 1}\r), 
\end{equation}
which together with \(\mathfrak{s}\log\bigl(1 + \tfrac{p}{\mathfrak{s}^2}\vee\tfrac{\sqrt{p}}{\mathfrak{s}}\bigr) \le \sqrt{ \tfrac{5}{2}\log\l(\tfrac{3}{2\sqrt{2}}\r)\tfrac{\Delta}{\tau}}\) implies
\[
2\gamma\rho^2 \le\frac{\mathfrak{s}\log\l(1+\frac{p}{\mathfrak{s}^2}\vee\frac{\sqrt{p}}{\mathfrak{s}}\r) \rho}{5} = \frac{\tau\mathfrak{s}^2\log^2\l(1+\frac{p}{\mathfrak{s}^2}\vee\frac{\sqrt{p}}{\mathfrak{s}}\r)}{5\Delta}\le \frac{1}{2}\log\l(\frac{3}{2\sqrt{2}}\r).
\]
As in Part~\ref{lem:lb:id:detect}, we obtain $\alpha \le 1/2$, and thus $\inf_{\wh\theta}\; \sup_{\p \in \mc P_{\mbf I, \sigma}^{\mathfrak{s}, n, p}(\tau)} \;\p\l(\bigl\vert\wh\theta -\theta(\p)\bigr\vert \ge \gamma\r) \ge 1/4$. Also we can derive from \eqref{e:gamma} that 
\[
\frac{\gamma\rho}{\mathfrak{s}} \ge \frac{1}{5}\log\l(\frac{3}{2\sqrt{2}}\r)\log\l(1 + \frac{p}{\mathfrak{s}^2} \vee \frac{\sqrt{p}}{\mathfrak{s}}\r).
\]
Note also that \eqref{e:gamma} implies $\gamma \le \Delta/(10\tau) \le \Delta /2$.
\end{proof}

\subsubsection{Supporting lemmas}

\begin{lem}\label{l:basic}
For $0 \le x \le 3/4$, it holds that $1/(1 -x)\le \exp(2x)$ and $1/(1+x) \le \exp(x/2)$.
\end{lem}


\begin{lem}\label{l:cross}
 For $\bm u \in \R^p$, let $\p_{\bm u}$ denote the centred Gaussian distribution with covariance matrix
\[
\bmx
    \mbf I & \bm u \\
    \bm u^\top & \bm u^\top\bm u + \sigma^2
\emx \in \R^{(p+1)\times(p +1)}.
\]
If $\vert\bm u\vert_2 = \vert\bm v\vert_2 = \kappa < \sigma/\sqrt{2}$, then%\footnote{This reveals that the computation in \citet{VeVi10} is wrong, see equation (8.5) therein. } 
\begin{equation*}%\label{eq:uv}
\E_{\p_{\bm 0}}\l(\frac{\mathrm{d}\p_{\bm u}}{\mathrm{d}\p_{\bm 0}}\frac{\mathrm{d}\p_{\bm v}}{\mathrm{d}\p_{\bm 0}}\r)= \l(\l(1-\frac{\langle\bm u, \bm v\rangle}{\sigma^2}\r)^2 - \l(\frac{\kappa^2}{\sigma^2}\r)^2\r)^{-1/2}.
\end{equation*}
\end{lem}
\begin{proof}
It follows from a general result for centred multivariate Gaussians (see e.g.\ Lemma~11 in \citealp{CaGu17}). For completeness, we give below a direct computation: 
\begin{align*}
\E_{\p_{\bm 0}}\l(\frac{\mathrm{d}\p_{\bm u}}{\mathrm{d}\p_{\bm 0}}\frac{\mathrm{d}\p_{\bm v}}{\mathrm{d}\p_{\bm 0}}\r) & = \E_{\p_{\bm0}}\l(\frac{\mathrm{d}\p_{\bm u}^{\bm Y \vert \mbf x}\mathrm{d}\p_{\bm u}^{\mbf x}}{\mathrm{d}\p_{\bm 0}^{\bm Y \vert \mbf x}\mathrm{d}\p_{\bm 0}^{\mbf x}}\frac{\mathrm{d}\p_{\bm v}^{\bm Y \vert \mbf x}\mathrm{d}\p_{\bm v}^{\mbf x}}{\mathrm{d}\p_{\bm 0}^{\bm Y \vert \mbf x}\mathrm{d}\p_{\bm 0}^{\mbf x}}\r) =\E_{\p_{\bm0}}\l(\frac{\mathrm{d}\p_{\bm u}^{\bm Y \vert \mbf x}}{\mathrm{d}\p_{\bm 0}^{\bm Y \vert \mbf x}}\frac{\mathrm{d}\p_{\bm v}^{\bm Y \vert \mbf x}}{\mathrm{d}\p_{\bm 0}^{\bm Y \vert \mbf x}}\r) \nonumber \\
& = \mathrm{det}\l(\mbf I - \frac{1}{\sigma^2}\l(\bm u \bm v^{\top} + \bm v \bm u^{\top}\r)\r)^{-1/2} \nonumber \\
& = \l(\l(1-\frac{\langle\bm u, \bm v\rangle}{\sigma^2}\r)^2 - \l(\frac{\kappa^2}{\sigma^2}\r)^2\r)^{-1/2},
\end{align*}
where the last equality can be seen from the fact that 
\[
\l(\mbf I - \frac{1}{\sigma^2}\l(\bm u \bm v^{\top} + \bm v \bm u^{\top}\r)\r) (\bm u \pm \bm v) =  \l(1-\frac{\langle\bm u, \bm v\rangle}{\sigma^2} \mp  \frac{\kappa^2}{\sigma^2}\r)(\bm u \pm \bm v).
\]
\end{proof}

\begin{rem}
Note that in Lemma~\ref{l:cross} the condition $\kappa < \sigma/\sqrt{2}$ is only needed to ensure the invertibility of the matrix $\mbf I - \frac{1}{\sigma^2}\l(\bm u \bm v^{\top} + \bm v \bm u^{\top}\r)$. In the special case of $\kappa^2+\langle \bm u,\bm v\rangle = \sigma^2$, by the same calculation, we have 
\[
\E_{\p_{\bm 0}}\l(\frac{\mathrm{d}\p_{\bm u}}{\mathrm{d}\p_{\bm 0}}\frac{\mathrm{d}\p_{\bm v}}{\mathrm{d}\p_{\bm 0}}\r) = \l(1-\frac{\langle\bm u, \bm v\rangle}{\sigma^2} + \frac{\kappa^2}{\sigma^2}\r)^{-1/2}.
\]
However, if $\kappa^2+\langle \bm u,\bm v\rangle > \sigma^2$, we have $\E_{\p_{\bm 0}}\l(\tfrac{\mathrm{d}\p_{\bm u}}{\mathrm{d}\p_{\bm 0}}\tfrac{\mathrm{d}\p_{\bm v}}{\mathrm{d}\p_{\bm 0}}\r) = \infty$.
\end{rem}

\begin{lem}[Dilatation]\label{l:dila}
If $X \sim \mathrm{Hypergeometric}(N, K, n)$ and $Y \sim \mathrm{Bin}(n, K/N)$, then $\E{f(X)}\le\E{f(Y)}$ for every convex function $f:\R \to \R$. 
\end{lem}

\begin{proof}
See either the first proof in \citet[Theorem~4 on pages 21--23]{Hoe63}, or a more explicit one in \citet[Proposition~(20.6) on pages 171--172]{Ald85}, or a systematic treatment in \citet[Section~3]{Kem73}. \end{proof}

\subsection{Proofs for the results in Section~\ref{sec:upper}}

Let $\mathbb{B}_d(r) = \{\mbf a: \, \vert \mbf a \vert_d \le 1\}$ denote the $\ell_d$-ball of radius $r$ with the dimension of $\mbf a$ determined within the context. 
Also $\mbf e_\ell, \, \ell \in [p]$ denote the canonical basis vectors of $\R^p$.

\subsubsection{Proof of Theorem~\ref{thm:mcscan}}

\begin{prop}
\label{prop:sparse}
Under the AMOC model~\eqref{eq:amoc}, suppose that there exists some $\eps_n \to \infty$ that satisfies $n^{-1} \eps_n \to 0$ such that $\cp \in (\eps_n, n - \eps_n)$ if $\bm\beta_0 \neq\bm\beta_1$, and $\cp = n$ if $\bm\beta_0 = \bm\beta_1$. 
Define \begin{align}
\bar{\mbf f}_k := \sqrt{\frac{k (n - k)}{n}} \l( \frac{n - \cp}{n - k} \mathbb{I}_{\{k \le \cp\}} + \frac{\cp}{k} \mathbb{I}_{\{k > \cp\}} \r) \bm\Sigma \bm\delta
\label{eq:f:bar}
\end{align}
and recall $\wt{\mbf Y}(k)$ from~\eqref{eq:tilde}. Then there exist some constants $\bar{C}_0, \bar{C}_1 \in (0, \infty)$ such that
\begin{align*}
\p\l\{ \vert \mbf X^\top \wt{\mbf Y}(k) - \bar{\mbf f}_k \vert_\infty \ge \bar{C}_0 \Vert \bm\Sigma\Vert^{1/2}  \Psi z \r\} \le \bar{C}_1 p \exp(-z^2)
\end{align*}
for any $z \in (0, \eps_n^{1/2})$ and $k \in (\eps_n, n - \eps_n)$.
\end{prop}

\begin{proof}
Let us write the eigendecomposition of $\bm\Sigma$ by $\bm\Sigma = \sum_{j \in [p]} \mu_j \mbf v_j \mbf v_j^\top$, where $\mu_1 \ge \cdots \ge \mu_p \ge 0$ and $\mbf v_j^\top \mbf v_{j'} = \mathbb{I}_{\{j = j'\}}$. 
Then, $\bm\Sigma^{1/2} = \sum_{j \in [p]} \mu_j^{1/2} \mbf v_j \mbf v_j^\top$ and its (generalised) inverse is $(\bm\Sigma^{1/2})^\dagger = \sum_{j \in [m]} \mu_j^{-1/2} \mbf v_j \mbf v_j^\top$ with $m = \text{rank}(\bm\Sigma)$, such that
\begin{align}
\label{eq:x:circ}
\mbf x^\circ_t = (\bm\Sigma^{1/2})^\dagger \mbf x_t \sim_{\iid} \mc N_p\l( \mbf 0, (\bm\Sigma^{1/2})^\dagger \bm\Sigma (\bm\Sigma^{1/2})^\dagger \r),
\end{align}
where $(\bm\Sigma^{1/2})^\dagger \bm\Sigma (\bm\Sigma^{1/2})^\dagger$ is a diagonal matrix with $m$ ones and $p - m$ zeros on its diagonal.
By Lemma~\ref{lem:hw} and $\Vert \bm\Sigma^{1/2}\Vert = \mu_1^{1/2} = \Vert \bm\Sigma\Vert^{1/2} $, we have for any $0 \le s < e \le n$ with $e - s \ge \eps_n$,
\begin{align}
& \p\l\{ \frac{1}{\sqrt{e - s}} \l\vert \sum_{t = s + 1}^e \mbf x_t \vep_t \r\vert_\infty \ge C \Vert \bm\Sigma \Vert^{1/2} \sigma z \r\}
\nn \\
=& \, \p\l\{ \frac{1}{\sqrt{e - s}} \max_{i \in [p]} \l\vert \sum_{t = s + 1}^e ( \bm\Sigma^{1/2} \mbf e_i )^\top \mbf x^\circ_t \vep_t \r\vert \ge C \Vert \bm\Sigma\Vert^{1/2} \sigma z \r\}
\le 2p \exp( - z^2),
\label{eq:xe:bound}
\end{align}
and
\begin{align}
& \p\l\{ \frac{1}{\sqrt{e - s}} \l\vert \sum_{t = s + 1}^e (\mbf x_t \mbf x_t^\top - \bm\Sigma) \bm\beta_j \r\vert_\infty \ge C \Vert \bm\Sigma \Vert^{1/2} \Psi z \r\}
\nn \\
=& \, \p\l\{ \frac{1}{\sqrt{e - s}} \max_{i \in [p]} \l\vert \sum_{t = s + 1}^e (\bm\Sigma^{1/2} \mbf e_i)^\top \l[ \mbf x^\circ_t (\mbf x^\circ_t)^\top - (\bm\Sigma^{1/2})^\dagger \bm\Sigma (\bm\Sigma^{1/2})^\dagger \r] \bm\Sigma^{1/2} \bm\beta_j \r\vert \ge C \Vert \bm\Sigma \Vert^{1/2} \Psi z \r\}
\nn \\
\le& \, 2p \exp( - z^2)
\label{eq:xx:bound}
\end{align}
for any $j \in \{0, 1\}$, where the constant $C$ is from Lemma~\ref{lem:hw}.
Let $\wh{\bm\gamma}_{a, b} = (b - a)^{-1} \sum_{t = a + 1}^b \mbf x_tY_t$ and $\bm\gamma_{a, b} = \E(\wh{\bm\gamma}_{a, b})$ for any $0 \le a < b \le n$.
For any $k \le \cp$, we can write
\begin{align}
& \p\l\{ \vert \mbf X^\top \wt{\mbf Y}(k) - \bar{\mbf f}_k \vert_\infty \ge \bar{C}_0 \Vert \bm\Sigma \Vert^{1/2} \Psi z \r\}
\nn \\
= & \, \p\l\{ \sqrt{\frac{k(n - k)}{n}} \Biggl\vert \frac{1}{n - k} \sum_{t = k + 1}^n \mbf x_t \mbf x_t^\top \bm\beta_1  - \frac{1}{n - k} \sum_{t = k + 1}^{\cp} \mbf x_t \mbf x_t^\top \bm\delta - \frac{1}{k} \sum_{t = 1}^k \mbf x_t \mbf x_t^\top \bm\beta_0 - \frac{n - \cp}{n - k} \bm\Sigma \bm\delta \r.
\nn \\
& \qquad \qquad \qquad \qquad \qquad \l. - \frac{1}{k} \sum_{t = 1}^k \mbf x_t \vep_t + \frac{1}{n - k} \sum_{t = k + 1}^n \mbf x_t \vep_t \Biggr\vert_\infty  \ge \bar{C}_0 \Vert \bm\Sigma \Vert^{1/2} \Psi z \r\}
\nn \\
\le & \, \p\l\{ \frac{1}{\sqrt{n - k}} \l\vert \sum_{t = k + 1}^n (\mbf x_t \mbf x_t^\top - \bm\Sigma) \bm\beta_1 \r\vert_\infty \ge \frac{\bar{C}_0}{5} \Vert \bm\Sigma\Vert^{1/2}  \Psi z \r\}
\nn \\
& \, + \p\l\{ \frac{1}{\sqrt{n - k}} \l\vert \sum_{t = k + 1}^\cp (\mbf x_t \mbf x_t^\top - \bm\Sigma) \bm\delta \r\vert_\infty \ge \frac{\bar{C}_0}{5} \Vert \bm\Sigma \Vert^{1/2} \Psi  z \r\}
\nn \\
& \, + \p\l\{ \frac{1}{\sqrt{k}} \l\vert \sum_{t = 1}^k (\mbf x_t \mbf x_t^\top - \bm\Sigma) \bm\beta_0 \r\vert_\infty \ge \frac{\bar{C}_0}{5} \Vert \bm\Sigma \Vert^{1/2} \Psi z \r\}
\nn \\
& \, + \p\l\{ \frac{1}{\sqrt{k}} \l\vert \sum_{t = 1}^k \mbf x_t \vep_t^\top \r\vert_\infty \ge \frac{\bar{C}_0}{5} \Vert \bm\Sigma \Vert^{1/2} \sigma z \r\} 
\nn \\
& \, + \p\l\{ \frac{1}{\sqrt{n - k}} \l\vert \sum_{t = k + 1}^n \mbf x_t \vep_t^\top \r\vert_\infty \ge \frac{\bar{C}_0}{5} \Vert \bm\Sigma \Vert^{1/2} \sigma z \r\}.
\label{eq:mcscan:decomp}
\end{align}
Note that by Lemma~\ref{lem:hw},
\begin{align*}
& \p\l\{ \frac{1}{\sqrt{n - k}} \l\vert \sum_{t = k + 1}^\cp (\mbf x_t \mbf x_t^\top - \bm\Sigma) \bm\delta \r\vert_\infty \ge C \Vert \bm\Sigma \Vert^{1/2} \Psi  z \r\} \\
= \; &  \p\l\{ \frac{1}{\sqrt{\cp - k}} \l\vert \sum_{t = k + 1}^\cp (\mbf x_t \mbf x_t^\top - \bm\Sigma) \bm\delta \r\vert_\infty \ge C \Vert \bm\Sigma \Vert^{1/2} \Psi  z  \frac{\sqrt{n - k}}{\sqrt{\cp - k}} \r\} \\
\le \; & 2p \exp\l[-\min\l( z^2\frac{n-k}{\cp-k}, z\sqrt{n-k} \r) \r]  \le 2p\exp(-z^2),
\end{align*}
where the last inequality is due to $\tfrac{n-k}{\cp-k} \ge 1$ and $z \le \sqrt{\eps_n} \le \sqrt{n-k}$.
This, together with~\eqref{eq:xe:bound} and~\eqref{eq:xx:bound}, leads to the following upper bound on the RHS of~\eqref{eq:mcscan:decomp}, by $10 p \exp( - z^2)$, provided that $\bar{C}_0 \ge 5C$. The case of $k > \cp$ is handled analogously.
\end{proof}

The rest of the proof follows from the arguments analogous to those adopted in the proof of Theorem~\ref{thm:qcscan}, in combination with Proposition~\ref{prop:sparse}, Lemma~\ref{lem:f:bar} and the observation that
\begin{align*}
\p\l( \bar{T}_m \ge \bar{T}_k \r) 
\le \p\l( \vert \mbf X^\top \wt{\mbf Y}(k) - \bar{\mbf f}_k \vert_\infty + \vert \mbf X^\top \wt{\mbf Y}(m) - \bar{\mbf f}_m \vert_\infty \ge
\vert \bar{\mbf f}_k - \bar{\mbf f}_m \vert_\infty \r);
\end{align*}
we omit the detailed arguments.

\subsubsection{Proof of Proposition~\ref{prop:dense}}

Let us write $\mbf Y = (Y_1, \ldots, Y_n)^\top$ and $\bm\vep = (\vep_1, \ldots, \vep_n)^\top$.
WLOG, we regard $\eps_n$ as an integer and focus on $k$ satisfying $k \le \cp$; the case with $k > \cp$ is handled analogously.
Let us define 
\begin{align*}
\mbf C(k) = \bmx - \frac{1}{k} \mbf I_k & \mbf O \\
\mbf O & \frac{1}{n - k} \mbf I_{n - k} \emx.
\end{align*}
Then we may write
\begin{align*}
\frac{n}{k(n - k)} T_k =& \, \mbf Y^\top \mbf C(k) \l( \mbf X\mbf X^\top - \frac{1}{n}\tr(\mbf X\mbf X^\top) \mbf I_n \r) \mbf C(k) \mbf Y
\\
= & \, \mbf Y^\top \mbf C(k) \l( \tr(\bm\Sigma) \mbf I_n - \frac{1}{n}\tr(\mbf X\mbf X^\top) \mbf I_n \r) \mbf C(k) \mbf Y
\\
& +  \E(\mbf Y \vert \mbf X)^\top \mbf C(k) \l( \mbf X\mbf X^\top - \tr(\bm\Sigma) \mbf I_n \r) \mbf C(k) \E(\mbf Y \vert \mbf X)
\\
& +  \bm\vep^\top \mbf C(k) \l( \mbf X\mbf X^\top - \tr(\bm\Sigma) \mbf I_n \r) \mbf C(k) \bm\vep
\\
& +  2 \E(\mbf Y \vert \mbf X)^\top \mbf C(k) \l( \mbf X\mbf X^\top - \tr(\bm\Sigma) \mbf I_n \r) \mbf C(k) \bm\vep 
\\
=: & \, U_1(k) + U_2(k) + U_3(k) + U_4(k).
\end{align*}

\paragraph{Bound on $U_1(k)$.} With some $\mbf Z \sim \mc N_n(\mbf 0, \mbf I_n)$, we have $\mbf Y^\top \mbf C(k)^2 \mbf Y = \mbf Z^\top \wt{\mbf C}(k)^2 \mbf Z$ where
\begin{align*}
\wt{\mbf C}(k) = \text{diag}\l( \sqrt{ \vert \bm\Sigma^{1/2} \bm\beta_0 \vert_2^2 + \sigma^2 } \, \mbf I_\cp, \, \sqrt{ \vert \bm\Sigma^{1/2} \bm\beta_1 \vert_2^2 + \sigma^2} \, \mbf I_{n - \cp} \r) \mbf C(k).
\end{align*}
Noting that
