\p\l[  \mbf Z^\top \wt{\mbf C}(k)^2 \mbf Z  \ge \frac{7 (\vert \bm\Sigma^{1/2} \bm\beta_0 \vert_2^2 + \vert \bm\Sigma^{1/2} \bm\beta_1 \vert_2^2 + \sigma^2)}{\min(k, n - k)}
