		&\qquad\qquad\qquad\qquad\qquad\cdot e^{-N(p+(1-p)(p_A\al_A+(1-p_A)\al_B))}\label{eq:2A}.
\end{align}
\end{proof}

\begin{proof}[Proof of Theorem~\ref{th:mixed}]
Recall that $(y_A,y_B)$ is a mixed equilibrium if and only if the conditions
\begin{align}
	c&=\tfrac12\bigl(\0F1(;1,(x_A+y_A)(x_B+y_B))\notag\\
		&\qquad\qquad+(x_B+y_B)\,\0F1(;2,(x_A+y_A)(x_B+y_B))\bigl)e^{-x_A-y_A-x_B-y_B}\label{eq:1G}\\
	c&=\tfrac12\bigl(\0F1(;1,(x_A+y_A)(x_B+y_B))\notag\\
		&\qquad\qquad+(x_A+y_A)\,\0F1(;2,(x_A+y_A)(x_B+y_B))\bigl)e^{-x_A-y_A-x_B-y_B}\label{eq:2G}
\end{align}
are satisfied. 
Subtracting the two equations and using the facts that $\exp$ is always positive and that
$\0F1$ is positive for non-negative arguments yields
$$
	0 = x_A-x_B+y_A-y_B.
$$
Hence, we have proved the last point of the lemma.
Inserting this into either one of the two equations yields
\begin{equation}\label{eq:3}
	c = \tfrac12\bigl(I_0(2(x_A+y_A))+I_1(2(x_A+y_A))\bigr)e^{-2(x_A+y_A)}.
\end{equation}
Define the function $g(z):=(I_0(z)+I_1(z))e^{-z}$. Corollary~\ref{co:Bessdiff} yields for all $z\in\Cz$,
\begin{equation}
\begin{aligned}
g(z) = (I_0(z)+I_0'(z))e^{-z}.
\end{aligned}
\end{equation}
Hence,
\begin{equation}\label{eq:usediff}
\begin{aligned}
zg(z)' &= z(I_0''(z) - I_0(z))e^{-z} \\
&= - I'_0(z) e^{-z},
\end{aligned}
\end{equation}
which is negative for all $z>0$, since $I_1(z)$ is a positive function on $\Rz_+$. Thus, $g$ is monotonically decreasing and satisfies $g(0)=1$. Next, we study the asymptotic behavior of $g$. Lemma~\ref{le:Bessasymp} immediately yields that 
\begin{equation}
I_0(z) + I_1(z) =_{+\infty} \frac{\sqrt{2} e^z}{\sqrt{\pi z}} + O\biggl(\frac{e^z}{z^\frac{3}{2}}\biggr)
\end{equation}
and, thus, 
\begin{equation}\label{eq:gasymp}
g(z) =_{+\infty} \sqrt{\frac{2}{\pi z}} + O\biggl(\frac{1}{z^\frac{3}{2}}\biggr).
\end{equation}
In particular, $\lim_{z\to\infty}g(z)=0$, therefore, for every $c\in(0,\tfrac12)$, there exists a unique $z_c$
satisfying $g(z_c)=2c$. 

However, not all of those $z_c$ are admissible equilibria. Since 
\begin{equation}
\begin{aligned}
x_A+y_A &= Np_A(p+(1-p)\al_A) \\
&= x_B+y_B = N(1 - p_A)(p+(1-p)\al_B),
\end{aligned}
\end{equation}
 $0<p,\al_A, \al_B<1$, and $\tfrac12<p_A<1$
there exists a solution $\al_A$ if and only if
\begin{equation}\label{eq:4}
	2Npp_A < z_c < 2N(1-p_A),
\end{equation}
i.e., the number of $A$--voters must always be greater than the number of $A$--partisan--voters and smaller than the total amount of $B$--supporters. Hence, 
\begin{equation}
	g(2x_A) > 2c > g(2N(1-p_A))
\end{equation}
needs to be satisfied.

In that case, there is a unique $\al^*_A$, and hence also
$$
	\al^*_B = \frac{p(2p_A-1)+p_A(1-p)\al_A^*}{(1-p)(1-p_A)}.
$$
So, if equation (\ref{eq:4}) is satisfied, there exists a unique mixed equilibrium.

The lower and upper bounds' asymptotics follow immediately from (\ref{eq:gasymp}).

\end{proof}


\begin{proof}[Proof of Proposition~\ref{pr:partmixsat}]
Let us suppose that a partial saturation equilibrium of the form
\begin{align}
	&R_1(N(1-p)p_A,y_B)\\ &\qquad= \tfrac12 e^{-Np_A-x_B-y_B}(\0F1(;1,Np_A(x_B+y_B))+(x_B+y_B)\;\0F1(;2,Np_A(x_B+y_B))) > c \\
	&R_2(N(1-p)p_A,y_B)\\ &\qquad= \tfrac12 e^{-Np_A-x_B-y_B}(\0F1(;1,Np_A(x_B+y_B))+Np_A\;\0F1(;2,Np_A(x_B+y_B))) = c ,
\end{align}
exists.
Then, subtracting the equations yields
\begin{align}
	R_2(N(1-p)p_A,y_B)&-R_1(N(1-p)p_A,y_B) \notag\\
	 &=\tfrac12(Np_A - (x_B + y_B))\0F1(;2,Np_A(x_B+y_B))e^{-Np_A-x_B-y_B} < 0.\label{eq:3Bbis}
\end{align}
But $Np_A > x_B + y_B$, and the argument of the generalized hypergeometric function $\0F1$ in
(\ref{eq:3Bbis}) is positive, so $R_2(N(1-p)p_A,y_B)-R_1(N(1-p)p_A,y_B)\geq 0$, a contradiction. 

Hence,
no partially mixed equilibrium with $\al_A=1$ exists and we have proved the first point of the theorem.

If $\al_B = 1$, (\ref{eq:1G}) must
be satisfied with equality, and $R_2(y_A,N(1-p)(1-p_A)) > c$ in the case of an equilibrium. Hence,
\begin{align}
	&R_2(y_A,N(1-p)(1-p_A))-R_1(y_A,N(1-p)(1-p_A)) \notag\\
	 &\qquad=\tfrac12(x_A+y_A-N(1-p_A))\0F1(;2,N(1-p_A)(x_A+y_A))e^{-x_A-y_A-N(1-p_A)} > 0\notag\\
\end{align}
and we conclude 
\begin{align}
	x_A+y_A-N(1-p_A) > 0.
\end{align}
\end{proof}

\begin{proof}[Proof of Proposition~\ref{pr:partmixedex}]
Again, (\ref{eq:2G}) must
be satisfied with equality, and $$c\geq R_1(0,y_B).$$ Since
\begin{align}
	R_2(0,y_B)&-R_1(0,y_B)
	 =\tfrac12(x_A-x_B-y_B)\0F1(;2,x_A(x_B+y_B))e^{-x_A-x_B-y_B}\notag\\
	 &=\tfrac12 N\bigl(p(2p_A-1)-(1-p)(1-p_A)\al_B\bigr)\notag\\
	 &\qquad\cdot\0F1\bigl(;2,N^2pp_A(1-p_A)(p+(1-p)\al_B)\bigr)e^{-N(p+(1-p)(1-p_A)\al_B)},\label{eq:3C}
\end{align}
in the case of an equilibrium,
\begin{align}
	x_A-x_B-y_B&\geq 0,\label{eq:3D}\\
	p(2p_A-1)-(1-p)(1-p_A)\al_B &\geq 0,\label{eq:3D2}
\end{align}
yielding
\begin{equation}\label{eq:3E}
	\al_B\leq \frac{p(2p_A-1)}{(1-p)(1-p_A)}.
\end{equation}
From (\ref{eq:2G}), we obtain
\begin{equation}\label{eq:partcond}
\begin{aligned}
	c &= \tfrac12\bigl(\0F1(;1,x_A(x_B+y_B))+x_A\,\0F1(;2,x_A(x_B+y_B))\bigr)e^{-x_A-x_B-y_B} \\
	&= h(x_A, x_B + y_B), 
\end{aligned}
\end{equation}
by Lemma~\ref{le:hgeomdiff}. Let us study $h(x_A, \ )$ in detail. We have $h(x_A,0)=\tfrac12(x_A+1)e^{-x_A}$. Furthermore, Lemma~\ref{le:hgeomdiff} yields  
\begin{equation}
h(x_A, z) = \tfrac12\bigl(\0F1(;1,x_Az)+x_A\,\0F1'(;1,x_Az)\bigr)e^{-x_A-z}.
\end{equation}
Thus, again by Lemma~\ref{le:hgeomdiff},
\begin{equation}
\begin{aligned}
z\frac{\d}{\d z} h(x_A, z) &= \tfrac12\bigl(-z\0F1(;1,x_Az)+x_A^2z\,\0F1''(;1,x_Az)\bigr)e^{-x_A-z} \\
&= \tfrac12\bigl((x_A - z)\0F1(;1,x_Az) - x_A\,\0F1'(;1,x_Az)\bigr)e^{-x_A-z}.
\end{aligned}
\end{equation}
Note that the additional factor $z$ does not change the sign of the above expression. Now, we verify readily that for all $z \in \Rz_+$, 
\begin{equation}\label{eq:auxfunc1}
i(z) := (x_A - z)\0F1(;1,x_Az) - x_A\,\0F1'(;1,x_Az) = \sum_{k\geq 1} \frac{- k(k^2 + k - x_A^2) }{x_A k! (k+1)!} (x_A z)^k.
\end{equation}
The polynomial $P(x_A,X) := -X(X^2 + X - x_A^2)$ has three---not necessarily distinct---roots $x_0 = 0$ and $x_{1,2} = \frac{-1 \pm \sqrt{1 + 4x_A^2}}{2}$. Furthermore, it is non--decreasing on $[0, \frac{-1 + \sqrt{1 + 3x_A^2}}{3}[$ and decreasing on $]\frac{-1 + \sqrt{1 + 3x_A^2}}{3}, +\infty[$. Therefore, $P(x_A,z)$ is in particular positive on $[0, \frac{-1 + \sqrt{1 + 4x_A^2}}{2}[$ and negative on $]\frac{-1 + \sqrt{1 + 4x_A^2}}{2}, +\infty[$.


For $x_A\leq\sqrt{2}$, all roots of $P(x_A,X)$ are smaller than or equal to $1$ and, hence, all coefficients of $i(z)$ are non--positive.  Hence, the function $h(x_A,z)$ monotonically decreases in $z$.

For $x_A>\sqrt{2}$, the above observations on $P(x_A,z)$ yield that there exists $N \in \Nz$ such that the coefficients $a_n := \frac{- k(k^2 + k - x_A^2) }{x_A k! (k+1)!}$ of the series in (\ref{eq:auxfunc1}) satisfy $a_n > 0$ for $1 \leq n \leq N+1$, $a_{N+2} \leq 0$ and $a_n < 0$ for $n > N+2$. Hence, the derivative of $i(z)$ satisfies the hypotheses of Lemma~\ref{le:incdec} and is positive in $0$. Thus, there exists $y_0 \in \Rz_+$ such that $i'(z)$ is positive for $z < y_0$ and negative for $z > y_0$. Hence, there exists $x_0 > y_0$ such that $i(z)$ is positive for $z < x_0$ and negative for $z > x_0$. Therefore, the function $h(x_A,z)$ has a unique global maximum $x_A^*$ on $\Rz_+$ for fixed $x_A$. We have $x_A\frac{\d}{\d z} h(x_A, x_A) < 0$, hence, $x_A^* < x_A$.

Now, we study the existence of partial absenteeism equilibria depending on $c$. As in the case of coin--toss equilibria, not all $z_c \in \Rz_+$ satisfying the equilibrium condition $h(x_A,z_c) = c$ are valid equilibria. The additional condition
\begin{equation}
x_B = Np(1-p_A) \leq z_c \leq Npp_A = x_A
\end{equation}
must be satisfied---where the second inequality follows from (\ref{eq:3D}).

Now, the following cases can occur if $x_A > \sqrt{2}$:

\begin{enumerate}

\item
If $c>h(x_A,x_A^*)$, then no partial absenteeism equilibrium exists.

\item 
For $c=h(x_A,x_A^*)$, there exists the unique equilibrium $(0,\al_B)$ with
$\al_B=\frac{x_A^*-Np(1-p_A)}{N(1-p)(1-p_A)}$ if $Np(1-p_A)\leq x_A^*$.

\item
For $\max(h(x_A,x_B), h(x_A,x_A)) \leq c<h(x_A,x_A^*)$ and $x_B < x_A^* < x_A$, 
there are two possible solutions, $z_1$ and $z_2$, of the equation $h(x_A,z)=c$, with
$x_B\leq z_1<x_A^*$ and $x_A \geq z_2>x_A^*$. These lead to the equilibria $(0,\al_{B,i})_{i \in {1,2}}$, with $\al_{B,1}=\frac{z_1-Np(1-p_A)}{N(1-p)(1-p_A)}$ and $\al_{B,2}=\frac{z_2-Np(1-p_A)}{N(1-p)(1-p_A)}$.

\item
For $\max(h(x_A,x_B), h(x_A,x_A)) \leq c<h(x_A,x_A^*)$ and $x_A^* < x_B < x_A$, the two above solutions are not admissible. Hence, no partial absenteeism equilibrium exists.

\item
For $\min(h(x_A,x_B), h(x_A,x_A)) \leq c <\max(h(x_A,x_B), h(x_A,x_A))$, only one of the above equilibria is admissible.

\item
If $0 \leq c <\min(h(x_A,x_B), h(x_A,x_A))$ no partial absenteeism equilibrium exists. 

\end{enumerate}
For $x_A\leq\sqrt{2}$, the cost $c$ needs to satisfy $2h(x_A,x_A)\leq 2c\leq 2h(x_A, x_B)$ for a partial absenteeism equilibrium of the form $(0,\al_B)$ to exist. Note that both these bounds are smaller than $2h(x_A,0) = (x_A+1)e^{-x_A}$.

\end{proof}

\begin{proof}[Proof of  Lemma~\ref{le:partmixedasymp}]
We have 
\begin{equation}
\begin{aligned}
h(x_A, qx_A) &= \tfrac12\bigl(\0F1(;1,qx_A^2)+x_A\,\0F1(;2,qx_A^2)\bigr)e^{-(q+1)x_A} \\
&= \tfrac12\bigl(I_0(2\sqrt{q}x_A) + \frac{1}{\sqrt{q}}I_1(2\sqrt{q}x_A)\bigr)e^{-(q+1)x_A}.
\end{aligned}
\end{equation}
Now, Lemma~\ref{le:Bessasymp} yields the second point. To show that there exists $x_0 \in \Rz_+$ such that $h(x_A,qx_A)$ is decreasing in $x_A$ on $[x_0, + \infty[$, we compute the derivative of $h(x_A,qx_A)$ with respect to $x_A$. Then, we proceed as in (\ref{eq:usediff}), using the first two terms of the asymptotic expansions in Lemma~\ref{le:Bessasymp} and verifying that there exists $x_0 \in \Rz_+$, such that $\frac{\d}{\d x_A}h(x_A,qx_A)$ is negative on $[x_0, + \infty[$.

For the third point we note that $q x_A\leq x_A$ and, hence, 
\begin{equation}
\begin{aligned}
h(x_A, qx_A) &= \tfrac12\bigl(\0F1(;1,qx_A^2)+x_A\,\0F1(;2,qx_A^2)\bigr)e^{-(q+1)x_A} \\
&\geq \tfrac12\bigl(\0F1(;1,qx_A^2)+qx_A\,\0F1(;2,qx_A^2)\bigr)e^{-(q+1)x_A} = h(qx_A,x_A).
\end{aligned}
\end{equation}

Finally, for $q>1$, $h(x_A,qx_A) = h(\tfrac1q (qx_A),qx_A)$, and the previous point gives 
\begin{equation}
h(\tfrac1q (qx_A),qx_A) =_{x_A \to + \infty} \frac{\cosh(\tfrac14\log(q))}{2\sqrt{\pi x_A}}e^{-(q+1 - 2\sqrt{q})x_A} + O\biggl(\frac{e^{-(q+1 - 2\sqrt{q})x_A}}{x_A^{\frac{3}{2}}}\biggr).
\end{equation}
\end{proof}

\begin{proof}[Proof of Theorem~\ref{th:partmixedexsat}]
This time, (\ref{eq:1G}) must
be satisfied with equality, and $R_2(y_A,N(1-p)(1-p_A)) > c$. Since
\begin{align}
	&R_2(y_A,N(1-p)(1-p_A))-R_1(y_A,N(1-p)(1-p_A)) \notag\\
	 &\qquad=\tfrac12(x_A+y_A-N(1-p_A))\0F1(;2,N(1-p_A)(x_A+y_A))e^{-x_A-y_A-N(1-p_A)}\notag\\
	 &\qquad=\tfrac12 N\bigl((p+1)p_A - 1 + (1-p)p_A\al_A \bigr)\notag\\
	 &\qquad \qquad\cdot\0F1\bigl(;2,N^2(1-p_A)(pp_A + (1-p)p_A\al_A))\bigr)e^{-N((p-1)p_A +(1-p)p_A\al_A +1)},\label{eq:3Cbis}
\end{align}
in the case of an equilibrium,
\begin{align}
	x_A+y_A-N(1-p_A)& > 0,\label{eq:3Dbis}\\
	(p+1)p_A - 1 + (1-p)p_A\al_A &> 0,\label{eq:3D2bis}
\end{align}
yielding
\begin{equation}\label{eq:3Ebis}
	\al_A > \frac{1 - (p+1)p_A}{(1-p)p_A}.
\end{equation}
From (\ref{eq:1G}), we obtain
\begin{equation}\label{eq:partcondbis}
\begin{aligned}
	c &= \tfrac12\bigl(\0F1(;1,N(1-p_A)(x_A+y_A))+N(1-p_A)\,\0F1(;2,N(1-p_A)(x_A+y_A))\bigr)e^{-x_A-y_A-N(1-p_A)} \\
	&= h(N(1-p_A), x_A + y_A), 
\end{aligned}
\end{equation}
by Lemma~\ref{le:hgeomdiff}. 

As in the proof of Proposition~\ref{pr:partmixedex} for $N(1-p_A)\leq\sqrt{2}$, the function $h(N(1-p_A),z)$ monotonically decreases in $z$.

Again, as in the proof of Proposition~\ref{pr:partmixedex}, for $N(1-p_A)>\sqrt{2}$, the function $h(N(1-p_A),z)$ is increasing from $0$ to its unique global maximum $z^*$ and decreasing afterwards, with $\lim_{z \to +\infty} h(N(1-p_A),z) = 0$ for fixed $N(1-p_A)$. Furthermore, we have, $z^* < N(1-p_A)$.

Now, we study the existence of partially mixed equilibria depending on $c$. As previously, not all $z_c \in \Rz_+$ satisfying (\ref{eq:partcondbis}) are valid equilibria. The additional condition
\begin{equation}
z^* < N(1-p_A) \leq z_c \leq Np_A
\end{equation}
must be satisfied---where the first inequality follows from (\ref{eq:3Dbis}).

Now, since $z^* < N(1-p_A)$ the following cases can occur:

\begin{enumerate}

\item
For $h(N(1-p_A), Np_A) \leq c \leq h(N(1-p_A),N(1-p_A))$ there exists exactly one solution $z_0$ of the equation $h(N(1-p_A),z) = c$ in the admissible interval $[N(1-p_A),Np_A]$. Hence, there exists a unique partial saturation equilibrium $(\al_A,1)$, with $\al_A = \frac{z_0 - Npp_A}{N(1-p)p_A}$.

\item
Otherwise, no partial saturation equilibrium exists.

\end{enumerate}
\end{proof}

\begin{proof}[Proof of  Corollary~\ref{th:allswipe}]

For the existence of the all--swipe equilibrium, the inequalities
\begin{align}
	&R_1(N(1-p)p_A,N(1-p)(1-p_A)) \\ &\qquad = \tfrac12 e^{-N}(\0F1(;1,N^2p_A(1-p_A))+N(1-p_A)\;\0F1(;2,N^2p_A(1-p_A))) \geq c \label{eq:1Hbis}\\
	&R_2(N(1-p)p_A,N(1-p)(1-p_A)) \\ &\qquad= \tfrac12 e^{-N}(\0F1(;1,N^2p_A(1-p_A))+Np_A\;\0F1(;2,N^2p_A(1-p_A))) \geq c \label{eq:2Hbis}
\end{align}
need to be satisfied. Since, $R_1(Np_A,N(1-p_A)) \leq R_2(Np_A,N(1-p_A))$, this is equivalent to merely requiring (\ref{eq:1Hbis}), i.e.,
\begin{equation}
h(N(1-p_A), Np_A) \geq c.
\end{equation} 
The asymptotic behavior of $h(N(1-p_A), Np_A)$ for $N \to +\infty$ has already been shown in Theorem~\ref{th:partmixed}.
\end{proof}

\subsection{Some additional useful results}

The following Lemma is used several times.

\begin{lem}\label{le:incdec}
Let $(a_n)_{n\in\Nz}$ be a sequence of real numbers such that there exists an integer $N \geq 1$ such that for all $n \leq N$, $a_n > 0$, $a_{N+1} \leq 0$ and for all $n > N + 1$, $a_n < 0$. Let 
\begin{equation}
\begin{aligned}
f: &\Rz_+ \to \Rz \\
&x \mapsto \sum_{n \geq 0} a_n x^n,
\end{aligned}
\end{equation}
and suppose that $f$ is well--defined on $\Rz$. Then there exists $x_0 \in \Rz$, such that $f$ is increasing on $[0, x_0[$ and decreasing on $]x_0, \infty[$. 
\end{lem}
\begin{proof}
We prove the result by induction on $N$. 

If $N = 1$, then $f''$ is a power series with all non--positive coefficients and negative coefficients of non--zero order, hence in particular negative. Thus $f'$ is decreasing and satisfies $f'(0) = a_1 > 0$. The other terms of order greater or equal to $2$ of $f'$ are all negative, so $\lim_{x \to \infty} f'(x) = -\infty$. Hence, $f$ is first increasing and then decreasing.

Now, suppose we have proved the result for some $N\in \Nz$ and let us prove the result for $N+1$. By induction hypothesis, there exists $x_0 \in \Rz$ such that $f'$ is increasing on $[0, x_0[$ and decreasing on $]x_0, \infty[$. Now, $f'(0) = a_1 > 0$. Furthermore, $\sum_{i=0}^N (i+1)a_{i+1} x^i = o(x_{N+2})$ and the coefficient of the term of order $N+2$ in $f'$ is negative, just as the rest of the series — except the coefficient of order $N+1$, which might also be zero. Hence, $\lim_{x \to \infty} f'(x) = -\infty$. Hence, there exists a unique $y_0 > x_0$ such that $f'$ is positive on $[0, y_0[$ and negative on $]y_0, \infty[$. Thus, $f$ is increasing on $[0, y_0[$ and decreasing on $]y_0, \infty[$.
\end{proof}

