        & $L$ conserving$\quad$ & $L$ non-conserving \\
        \midrule
        $[\tilde\varphi]$ $\quad$    & $(2-\alpha_n)/(\alpha_n+\alpha_L) + d/2$ & $2/\alpha_n + d/2 - 1 $ \\[1mm]
        $[\varphi]$           & $-\alpha_n/(\alpha_n+\alpha_L) + d/2$  & $d/2-1$ \\[1mm]
        $[\tilde{\ell}]$  & $(2-2\alpha_L-\alpha_n)/(\alpha_n + \alpha_L) + d/2$ & $2/\alpha_n +d/2 - 1$ \\[1mm]
        $[\ell]$          & $\alpha_n/(\alpha_n + \alpha_L) + d/2$ & $d/2+1$ \\[1mm]
