\section{Generation of markovian perturbations}
\label{App:GeneratingMarkovianPerturbations}

In this Appendix, we assess how the presence of interactions can generate markovian perturbations in the ordered phase. To this extent, we include non-linearities back in Eqs.~\eqref{Eq:linearized_equations} and neglect the equation for the amplitude mode. Note that a more precise treatment would be to eliminate $\sigma$ adiabatically, which would lead to new interactions and renormalization of existing interactions. This is however not relevant, as we only want to show that a markovian term can be generated.  
The equations then read $(\alpha,\beta = 2, \dots,N)$:
%
\begin{subequations}
   \begin{align}
       \gamma_n* \dot{\varphi}_\alpha & = D_n\nabla^2\varphi_\alpha - g\bar{n} D_L\ell_{\alpha}  -g D_L L_{\alpha\beta}\varphi_\beta +\xi_\alpha,\\
       %
       \gamma_L*\dot{\ell}_{\alpha} & = D_L\nabla^2 L_{1\alpha}  - g\bar{n}D_n\nabla^2\varphi_\alpha +\eta_{\alpha1}, \\
       %
       \gamma_L*\dot{L}_{\alpha\beta} & = D_L\nabla^2 L_{\alpha\beta} + g D_n(\varphi_\alpha\nabla^2\varphi_\beta - \varphi_\beta \nabla^2\varphi_\alpha)  +\eta_{\alpha\beta}.
   \end{align}
\end{subequations}
%
Within this approximation, the only non-linear coupling is between $\varphi_\alpha$ and $L_{\alpha\beta}$, while $\ell_{\alpha}$ is only linearly coupled to $\varphi_\alpha$. 
In order to show that markovian contributions can be generated by interactions, we focus only on $\varphi_\alpha$ and $L_{\alpha\beta}$, and neglect $L_{1\alpha}$ for now.
We can then write down the corresponding MSR action, which reads: 
%
\begin{multline}
   S=\int_{\rr,t}\!\bigg\{
   \tilde{\varphi}_{\al} \Big[\gamma_n*\dot{\varphi}_{\al}- D_n \nabla^2 \varphi_{\al} + gD_LL_{\al\bb}\varphi_{\bb} -T \tilde{n}_{\al}\Big] \\
+\tilde{L}_{\bb\al}\Big[\gamma_L*\dot{L}_{\al\bb}-gD_n\big\{\!(\nabla^2 \varphi_{\bb})\varphi_{\al}-(\nabla^2 \varphi_{\al})\varphi_{\bb}\!\big\}
   -
   D_L\nabla^2 L_{\al\bb}- T\nabla^2\tilde{L}_{\al\bb}\Big]
    \!\bigg\}\!\label{Eq:FullAction}.
\end{multline}
%
We now compute the one-loop correction to the retarded self-energy of the field $\varphi_\alpha$.

To this end, we split the retarded self-energy in two parts as $\Sigma_R=\Sigma_R^{(1)}+\Sigma_R^{(2)}$, with:
%
\begin{figure}[h!]
	\centering
	\includegraphics[width=0.7
	\linewidth]{FigApp1.pdf}
\end{figure}
%

\noindent with the Feynman rules reported in Fig.~\ref{Fig:App2} and the Gaussian response ($R$) and correlation functions ($C$) are given by
%
\begin{subequations}
\label{eq:Gaussian_propagator}
\begin{align}
    C^L(\mathbf{q},\omega) & =\frac{2T_L \text{Re}[\gamma_L(\omega)]\mathbf{q}^2}{|-i\gamma_L(\omega)\omega + D_Lq^2|^2}\qquad\qquad
    R^L(\mathbf{q},\omega)=\frac{1}{-i\gamma_L(\omega)\omega+D_L\mathbf{q}^2}\\
    C^n(\mathbf{q},\omega) & =\frac{2T_n \text{Re}[\gamma_n(\omega)]}{|-i\gamma_n(\omega)\omega +D_n\mathbf{q}^2|^2} \qquad\qquad
    R^n(\mathbf{q},\omega)=\frac{1}{-i\gamma_n(\omega)\omega+D_n\mathbf{q}^2}.
\end{align}
\end{subequations}
%

%
\begin{figure}[h!]
	\centering
	\includegraphics[width=0.88\linewidth]{FigApp2.pdf}
    \label{Fig:FeynmanRulesApp}
    \caption{Definition of Feynman rules for \textbf{(a)} the correlation (C) and response (R) functions, and \textbf{(b)} the vertices.}
    \label{Fig:App2}
\end{figure}
%
In order to single out the generated markovian contribution $-i\gamma_\text{mkv}\omega$ we need to compute:
%
\begin{align}
\gamma_\text{mkv}
& =  \frac{\partial }{\partial\omega}\text{Im}[\Sigma_R (\omega, \mathbf{q})]\bigg|_{\omega = 0, \mathbf{q} = 0} \\
& =  g^2 \text{Im}\bigg[\int_{\mathbf{p},\nu} \left[ \frac{\partial C^L(\mathbf{p},\nu)}{\partial \nu}R^n(\mathbf{p},\nu) -\mathbf{p}^2 \frac{\partial R^L(\mathbf{p},\nu)}{\partial \nu}C^n(\mathbf{p},\nu) \right]\bigg] \\
&=g^2 \int_{\mathbf{p},\nu} \left[ \frac{\partial C^L(\mathbf{p},\nu)}{\partial \nu}\text{Im}[R^n(\mathbf{p},\nu)] -\mathbf{p}^2 \frac{\partial \text{Im}[R^L(\mathbf{p},\nu)]}{\partial \nu}C^n(\mathbf{p},\nu) \right]\bigg] 
\end{align}
%
Now, assuming this contribution to be evaluated within an RG step (say, Wilson's momentum shell scheme), the correlations and response functions would be those of fast degrees of freedom living within the momentum shell: accordingly, we can replace $\mathbf{p} \approx \Lambda$, with $\Lambda$ the UV cutoff, and the computation is simplified as:
%
\begin{equation}
    \gamma_\text{mkv} = d\Lambda \Lambda^{d-1} g^2 \int_{\nu} \left[ \frac{\partial C^L(\Lambda,\nu)}{\partial \nu}\text{Im}[R^n(\Lambda,\nu)] -\Lambda^2 \frac{\partial \text{Im}[R^L(\Lambda,\nu)]}{\partial \nu}C^n(\Lambda,\nu) \right] 
\end{equation}
%
with $d\Lambda$ the width of the momentum shell. By inserting in the previous equation the values~\eqref{eq:Gaussian_propagator}, together with the expression for $\gamma(\omega)$ in Eq.~\eqref{eq:gamma_expression}, one finds that the integral in $\nu$ converges, proving that markovian corrections are indeed generated. 



