In this article, we are interested in problems that count primitive vectors under the given congruence condition. 
Our first result is an analog of Schmidt's random counting theorem.

\begin{theorem}\label{thm: Analog of Schmidt}
Let $\{A_T\}$
%{\color{magenta} we use $t=\det$. Change T for the parameter of a family of Borel sets} 
be an increasing family of Borel sets by inclusion and suppose that
\[
V_T:=\vol(A_T)\rightarrow \infty\;\text{as}\;T\rightarrow \infty.
\]
Let $\psi:\RR_{>0}\rightarrow \RR_{>0}$ be a non-decreasing function satisfying $\int \psi(x)^{-1} dx<\infty$.
%Let $\{A_t\}$ be an increasing family of Borel sets of $\RR^2$ with $\vol(A_t)\rightarrow \infty$ as $t\rightarrow \infty$. Let $\psi:\RR_{>0}\rightarrow \RR_{>0}$ be a non-decreasing function.
For a given $N\in \NN$, take an integer vector $\bf{v}_0\in \ZZ^2$ for which $\gcd(\bf{v}_0, N)=1$.

For almost all unimodular lattice $g\mathbb Z^2 \subseteq \RR^2$, where $g$ varies in $\SL_2(\RR)$ with respect to the Haar measure, it follows that
\[
\# \left(g\{\bf{v}\in P(\mathbb Z^2):\bf{v}\equiv \bf{v}_0\;(\mod N)\}\cap A_T\right)=\frac{V_T} {\zeta_N(2)N^2}+O\left(V_T^{1/2}(\log V_T)^2\psi(V_T)^{1/2}\right),
\]
where $\zeta_N(d)$ for $d\in \NN$ is defined as
\[\zeta_N(d)=\prod_{\scriptsize \begin{array}{c}
p:\text{prime}\\
p\nmid N\end{array}} \left(1-\frac 1 {p^d}\right)^{-1}.
\]
\end{theorem}

Adopting the tactic of Schmidt \cite{Schmidt1960}, we will derive Theorem~\ref{thm: Analog of Schmidt} by establishing the first and second moment formulas for a new Siegel transform defined as follows: let us denote the congruence condition by $\sigma=(\bf{v}_0, N)$, where $N\in \NN$ and $\bf{v}_0\in \ZZ^2$ with $\gcd(\bf{v}_0, N)=1$. For a bounded function $f:\RR^2\rightarrow \RR$ of compact support, the Siegel transform $\widehat{f}^{(\sigma)}$ relative to the congruence condition $\sigma$ is an integral function on $\SL_2(\RR)/\Gamma(N)$ given as
\[
\widehat{f}^{(\sigma)}(g\Gamma(N))=\sum_{\scriptsize \begin{array}{c}
\bf{v}\in P(\ZZ^2),\\
\bf{v}\equiv \bf{v}_0\;(\mod N)\end{array}} f(g\bf{v}),\quad \forall g\Gamma(N)\in \SL_2(\RR)/\Gamma(N),
\]
where $\Gamma(N)=\left\{g\in \SL_2(\ZZ): g\equiv \Id_2 \;(\mod N)\right\}$ is the principal congruence subgroup of level $N$.
Note that $\widehat{f}^{(\sigma)}$ is well-defined since the set $\{\bf{v}\in \ZZ^2: \bf{v} \equiv \bf{v}_0\;(\mod N)\}$ is $\Gamma(N)$-invariant.

\begin{theorem}\label{thm: moment formulas} Let $f:\RR^2\rightarrow \RR$ be a bounded function of compact support. For a congruence condition $\sigma=(\bf{v_0}, N)$ as above, we obtain the integral formulas below.

\noindent (1) (The first moment formula) It holds that
\[
\int_{\SL_2(\RR)/\Gamma(N)} \Siegel{f}{\sigma}(g\Gamma(N)) d\nu_N(g)
%=\frac 1 {\zeta(2) N^2\prod_{p|N} \left(1-\frac 1 {p^2}\right)} \int_{\RR^2} f({\bf v}) d{\bf v}
=\frac 1 {\zeta_N(2) N^2} \int_{\RR^2} f({\bf v}) d{\bf v}.
\]

Here $\nu_N$ is the $\SL_2(\RR)$-invariant probability measure on $\SL_2(\RR)/\Gamma(N)$.


\noindent (2) (The second moment formula)
Denote by $f\otimes f$ the function on $\RR^2\times \RR^2$ which is given as $f\otimes f(\bf{v}_1, \bf{v}_2)=f(\bf{v}_1)f(\bf{v}_2)$ for any $\bf{v}_1,\bf{v}_2\in \RR^2$. It follows that

\begin{equation}\label{eqn: second moment}\begin{split}
\int_{\SL_2(\RR)/\SL_2(\ZZ)} \widehat{f}^{(\sigma)}(g\Gamma(N))^2 d\nu_N(g)
&=\sum_{n\in N\ZZ-\{0\}} \frac {\varphi(n)} {\zeta_N(2)N^3\varphi(N)}\int_{\SL_2(\RR)} f\otimes f(gJ_n) d\eta(g) \\
&+\frac 1 {\zeta_N(2) N^2} \int_{\RR^2} f(\bf{v})f(\bf{v})+f(\bf{v})f(-\bf{v}) d\bf{v},
\end{split}\end{equation}
where for each $n\in N\ZZ-\{0\}$, $J_n=\left(\begin{array}{cc}
1 & 0 \\
0 & n\end{array}\right)$, $\varphi(\cdot)$ is Euler totient function,
and $\eta$ is the $\SL_2(\RR)$-invariant measure inherited from the Lebesgue measure under the canonical embedding $\SL_2(\RR)\hookrightarrow \RR^2\times \RR^2$. 
%Here we regard an element $gJ_n$ of $\GL_2(\RR)$ as a pair of vectors in $\RR^2\times \RR^2$.
\end{theorem}

