The first part of (R.H.S) in \eqref{eqn: second moment} is the summation of integrals over $\SL_2(\RR)$-embedded images in $\RR^2\times \RR^2$, and each integral is obtained by a folding-unfolding argument and change of $\SL_2(\RR)$-invariant measures of $\SL_2(\RR)$.
To derive Theorem~\ref{thm: Analog of Schmidt} from moment formulas, the formula in \eqref{eqn: second moment} is inappropriate. Instead, we will introduce the notion of \emph{the cone} of $\SL_2(\RR)/\Gamma(N)$ and establish the moment formulas of the variable
\[
t^{1/2}\widehat{f}^{(\sigma)} (t^{1/2}g):=\hspace{-0.1in}\sum_{\scriptsize \begin{array}{c}
\bf{v}\in P(\ZZ^2)\\
\bf{v}\equiv \bf{v}_0\end{array}} f(t^{1/2}g\bf{v}), 
\]
where $t\in (0,1]$ and $g$ lies in any given fundamental domain of $\SL_2(\RR)/\Gamma(N)$.

\begin{theorem}\label{thm: moment formulas over the cone}
Let $f:\RR^2\rightarrow \RR$ be a bounded function of compact support. For a congruence condition $\sigma=(\bf{v_0}, N)$ as above, we obtain the integral formulas below.

\noindent (1) (The first moment formula) It holds that
\[
\int_0^1\int_{\SL_2(\RR)/\Gamma(N)} t\widehat{f}^{(\sigma)} (t^{1/2}g)d\nu_N dt
=\frac 1 {\zeta_N(2) N^2} \int_{\RR^2} f(\bf{v}) d\bf{v}.
\]

\noindent (2) (The second moment formula) There is a function $\Phi_N(x)$ on $\RR$ whose approximate value is $1/\zeta_N(2)N$ as $|x|\rightarrow \infty$ and
\[\begin{split}
\int_0^1 \int_{\SL_2(\RR)/\Gamma(N)} \left(t^{1/2} \widehat{f}^{(\sigma)} (t^{1/2}g)\right)^2 d\nu_N dt
&=\frac 1 {\zeta_N(2) N^3} \int_{\RR^2\times \RR^2} \Phi_N(\det(\bf{v}_1, \bf{v}_2)) f(\bf{v}_1)f(\bf{v}_2) d\bf{v}_1 d\bf{v}_2\\
&+\frac 1 {\zeta_N(2)N^2} \int_{\RR^2} f(\bf{v})f(\bf{v}) + f(\bf{v})f(-\bf{v}) d\bf{v}.
\end{split}\]
\end{theorem}

Finally, we state the quantitative version of Khintchine theorem having congruence and primitive conditions, as a corollary of Theorem~\ref{thm: Analog of Schmidt}.

\begin{theorem}\label{thm: quantitative K}
Let $\psi:\RR_{>0}\rightarrow\RR_{>0}$ be a non-increasing function such that $\sum_{t\in \NN} \psi(t)=\infty$. Let $\sigma=((p_0,q_0)^T, N)$ be as above. It follows that for almost all $x\in \RR$, as $T\rightarrow \infty$,
\[
\#\left(\left\{\left(\begin{array}{c} p \\ q \end{array}\right)\in P(\ZZ^2): \begin{array}{c}
\left|qx-p\right|<\psi(|q|), |q|\le T\\[0.05in]
(p,q)^T\equiv (p_0,q_0)^T\;(\mod N) \end{array}\right\}\right)\sim\frac 1 {\zeta_N(2)N^2}\sum_{1\le t\le T} \psi(t).
\]
\end{theorem}


\subsection*{Organization}
In Section 2, we review relevant previous works on counting problems and Diophantine approximation under congruence conditions.
In Section 3, we establish moment formulas (Theorem~\ref{thm: moment formulas}) for Siegel transforms with both primitive and congruence conditions. A central component of this section is to derive the second moment formula. To this end, we determine the set of possible determinants of $(\bf{v}_1, \bf{v}_2)\in P(\ZZ^2)\times P(\ZZ^2)$ (as $2\times 2$ matrices) with $\bf{v}_1\equiv\bf{v}_2\;(\mod N)$, and compute the number of $\Gamma(N)$-orbits in an $\SL_2(\RR)$-orbit at $(\bf{v}_1, \bf{v}_2)$ (see Proposition~\ref{pr:no.inv}). This computation plays a crucial role in establishing the second moment formula over the cone in the next section.
In Section 4, we introduce the cone $\mathfrak C$ of (a fundamental domain of) $\SL_2(\RR)/\Gamma(N)$, and derive moment formulas over the cone $\mathfrak C$ (Theorem~\ref{thm: moment formulas over the cone}). 
Finally in Section 5, we outline the proofs of the random counting theorem under primitive and congruence conditions (Theorem~\ref{thm: Analog of Schmidt}) and quantitative Khintchine theorem under congruence conditions (Theorem~\ref{thm: quantitative K}).
