Let $G$ be a Lie group and let $\Gamma$ be a discrete subgroup of $G$.
If $\mathfrak{F}$ is a fundamental domain of $G/\Gamma$, then for any $g\in G$, the left translate $g\mathfrak{F}$ is also a fundamental domain.
In contrast, the right translate $\mathfrak{F}g$ is not, in general, a fundamental domain of $G/\Gamma$. However, if $g\in N_G(\Gamma)$, the normalizer of $\Gamma$ in $G$, then $\mathfrak {F}g$ is again a fundamental domain for $G/\Gamma$.

\begin{proposition} \label{pr:fund}
Let $G$ be a Lie group and let $\Gamma$ be a discrete subgroup of $G$. Denote by $\mathfrak F$ a fundamental domain for $G/\Gamma$. 
For any element $g\in N_G(\Gamma)$, the right translate $\mathfrak Fg$ is again a fundamental domain for $G/\Gamma$. 
\end{proposition}

\begin{proof}
Since $G =\bigsqcup_{\gamma\in \Gamma}\mathfrak{F}\gamma$ and $g^{-1}\Gamma g=\Gamma$, it follows that
$$G = Gg = \bigsqcup_{\gamma\in \Gamma}\mathfrak{F}\gamma g  
= \bigsqcup_{\gamma\in \Gamma}\mathfrak{F}g(g^{-1}\gamma g)
= \bigsqcup_{\gamma'\in \Gamma}\mathfrak{F}g \gamma'.$$
Thus $\mathfrak{F}g$ is a fundamental domain for $G/\Gamma$.
\end{proof}


\begin{proof}[Proof of Theorem~\ref{thm: moment formulas} (the 1st moment)]
For a bounded function $f:\RR^2\rightarrow \RR$ of compact support, we aim to show that
\[
\int_{\SL_2(\RR)/\Gamma(N)} \Siegel{f}{\sigma}(g\Gamma(N)) d\nu_N(g)
=\frac 1 {\zeta(2) N^2\prod_{p|N} \left(1-\frac 1 {p^2}\right)} \int_{\RR^2} f({\bf v}) d{\bf v}
=\frac 1 {\zeta_N(2) N^2} \int_{\RR^2} f({\bf v}) d{\bf v}.
\]

By Riesz-Markov-Kakutani representation theorem (which applies to $f\in C_c(\RR^2)$, and can be extended to bounded and compactly supported functions), there exists $\omega_\sigma>0$ for each $P^{(\sigma)}\in \mathcal P_N$ such that
$$\int_{\mathrm{SL}_2(\mathbb R)/\Gamma(N)}\widehat{f}^{(\sigma)}(g\Gamma(N))d\nu_N(g)= \omega_\sigma\int_{\mathbb R^2}f(\mathbf v)d\mathbf v.$$
%Note that $\widehat{f}^{(\sigma)}$ is bounded by $\widehat{f}$, which is absolutely integrable, hence $\widehat{f}^{(\sigma)}$ is also an absolutely integrable function.


Observe that $\widehat{f}$ and $\widehat{f}^{(\sigma)}$ for any $\sigma\in\mathcal P_N$ are bounded thus absolutely integrable, and
%, for the canonical extension of $\widetilde{f}$ to $\mathrm{SL}_2(\mathbb R)/\Gamma(N)$, 
$\widehat{f}(g\Gamma(N)) = \sum_{\sigma\in\mathcal P_N}\widehat{f}^{(\sigma)}(g\Gamma(N))$ for $g\in\mathrm{SL}_2(\mathbb R)$. By Fubini lemma, it follows from the first moment formula for the primitive Siegel transform (see Eq.~(20) in \cite{Siegel45}) that
\begin{align*}
\frac{1}{\zeta(2)}\int_{\mathbb R^2}f(\mathbf v)d\mathbf v 
& = \int_{\mathrm{SL}_2(\mathbb R)/\mathrm{SL}_2(\mathbb Z)}\widehat{f}(g\SL_2(\mathbb Z))d\mu(g) = \int_{\mathrm{SL}_2(\mathbb R)/\Gamma(N)}\widehat{f}(g\Gamma(N))d\nu_N(g) \\
& = \sum_{ \sigma\in\mathcal{P}_N}\int_{\mathrm{SL}_2(\mathbb R)/\Gamma(N)}\widehat{f}^{(\sigma)}(g\Gamma(N))d\nu_N(g) = \sum_{\sigma\in\mathcal{P}_N}\omega_\sigma\int_{\mathbb R^2}f(\mathbf v)d\mathbf v.
\end{align*}
Here, $\mu$ is the Haar probability measure on $\mathrm{SL}_2(\mathbb R)/\mathrm{SL}_2(\mathbb Z)$.
Thus we obtain the equality
$$\sum_{\sigma\in\mathcal{P}_N} \omega_\sigma = \frac{1}{\zeta(2)}.$$

Now we claim that $\omega_\sigma=\omega_\tau$ for all $\sigma,\;\tau\in\mathcal{P}_N$, so that the theorem follows from Lemma~\ref{le:no.PN}.

Choose $(m_1,n_1)\in P^{(\tau)}$ and $(m_2,n_2)\in P^{(\sigma)}$.
There exist $a,b,c,d\in\mathbb Z$ such that $am_1+bn_1=1$ and $cm_2+dn_2=1$.
If we take $g_{\sigma\tau}=\begin{pmatrix}m_2&-d\\n_2&c\end{pmatrix}\begin{pmatrix}a&b\\-n_1&m_1\end{pmatrix}$,
then
$$g_{\sigma\tau}\begin{pmatrix}m_1\\n_1\end{pmatrix} = \begin{pmatrix}m_2&-d\\n_2&c\end{pmatrix}\begin{pmatrix}1\\0\end{pmatrix}=\begin{pmatrix}m_2\\n_2\end{pmatrix} \text{ and }g_{\sigma\tau}\in\mathrm{SL}_2(\mathbb R).$$
Since $g_{\sigma\tau}$ preserves the set $N\ZZ^2$ and sends primitive vectors to primitive vectors, we obtain that $g_{\sigma\tau}P^{(\tau)}=P^{(\sigma)}$.

Let $\mathfrak{F}$ be a fundamental domain of $\mathrm{SL}_2(\mathbb R)/\Gamma(N)$.
By unimodularity of $\mathrm{SL}_2(\mathbb R)$ and Lemma~\ref{pr:fund}, it holds that for any bounded and compactly supported function $f$ on $\RR^2$,
\begin{align*}
\omega_\sigma\int_{\mathbb R^2}f(\mathbf v)d\mathbf v 
& = \int_{\mathrm{SL}_2(\mathbb R)/\Gamma(N)}\widehat{f}^{(\sigma)}(g\Gamma(N))d\nu_N(g) = \int_{\mathfrak{F}}\sum_{\mathbf v\in\mathcal{P}^{(\sigma)}}f(g\mathbf v)d\nu_N(g) \\
& = \int_{\mathfrak{F}}\sum_{\mathbf v\in\mathcal{P}^{(\tau)}}f(gg_{\sigma\tau}\mathbf v)d\nu_N(g) = \int_{\mathfrak{F}g_{\sigma\tau}}\sum_{\mathbf v\in\mathcal{P}^{(\tau)}}f(g'\mathbf v)d\nu_N(g') \\
& = \int_{\mathrm{SL}_2(\mathbb R)/\Gamma(N)}\widehat{f}^{(\tau)}(g\Gamma(N))d\nu_N(g) = \omega_\tau\int_{\mathbb R^2}f(\mathbf v)d\mathbf v.
\end{align*}
Thus $\omega_\sigma = \omega_\tau$ for any $\sigma, \tau \in \mathcal P_N$. From the definition of zeta functions $\zeta(d)$ and $\zeta_N(d)$, it follows that
\[
\zeta(2)N^2\prod_{p|N} \left( 1 - \frac 1 {p^2} \right)= \zeta_N(2)N^2.
\]
\end{proof}

