\subsection{Second Moment Formulas}

Let $F$ be a bounded and compactly supported function on $\RR^2\times \RR^2$. For $N\in \NN$ and $\sigma\in \mathcal P_N$, define $\widehat{F}^{(\sigma)}$, a function on $\SL_2(\RR)/\Gamma(N)$ by
\[
\widehat{F}^{(\sigma)}(g\Gamma(N))=\sum_{\bf{v}_1, \bf{v}_2\in P^{(\sigma)}} F(g\bf{v}_1, g\bf{v}_2).
\]

Note that if we take $F=f\otimes f$, i.e., $F(\bf{v}_1, \bf{v}_2)=f(\bf{v}_1)f(\bf{v}_2)$, then
\[
\widehat{F}^{(\sigma)}(g\Gamma(N))=\widehat{f}^{(\sigma)}(g\Gamma(N))^2.
\]
Hence we obtain the absolute integrability of $\widehat{F}^{(\sigma)}$ by choosing an appropriate bounded and compactly supported function $f:\RR^2\rightarrow \RR$ satisfying that $|F|\le f\otimes f$.
%Since $\widehat{F}^{(\sigma)}$ is bounded by $\widehat{F}$, where $\widehat{F}(g):=\sum_{\bf{v}_1, \bf{v}_2\in P(\ZZ^2)} F(g\bf{v}, g\bf{v})$, one deduce the integrability of $\widehat{F}^{(\sigma)}$ form that of $\widehat{F}$ (see \cite{Schmidt1960}). 

For the next theorem, let us introduce the Haar measure $\eta$ on $\SL_2(\RR)$, inherited from $\RR^2\times \RR^2$, defined as $dadbdc$ if we denote a (generic) element $g$ of $\SL_2(\RR)$ by
\[
g=\left(\begin{array}{cc}
1 & 0 \\
c & 1\end{array}\right)\left(\begin{array}{cc}
a & b \\
0 & a^{-1}\end{array}\right).
\]
It is easy to verify that
\[
\nu_N=\frac 1 {[\SL_2(\ZZ):\Gamma(N)]} \mu= \frac 1 {N^3 \prod_{p|N} \left(1 -\frac 1 {p^2}\right)}\cdot \frac 1 {\zeta(2)} \eta=\frac 1 {\zeta_N(2)N^3} \eta.
\]




\begin{theorem}\label{thm: second moment 2}
Let $N\in \NN_{\ge 2}$ and fix a congruence class $\sigma\in \mathcal P_N$. For a bounded and compactly supported function $F:\RR^2\times \RR^2\rightarrow \RR$, it follows that
\[\begin{split}
\int_{\SL_2(\RR)/\Gamma(N)} \widehat{F}^{(\sigma)} (g\Gamma(N)) d\nu_N (g)
&=\sum_{n\in N\ZZ-\{0\}} \frac {\varphi(n)} {\zeta_N(2)N^3\varphi(N)}\int_{\SL_2(\RR)} F(gJ_n) d\eta(g) \\
&+\frac 1 {\zeta_N(2) N^2} \int_{\RR^2} F(\bf{v},\bf{v})+F(\bf{v},-\bf{v}) d\bf{v},
\end{split}\]
where for each $n\in N\ZZ-\{0\}$, $J_n=\left(\begin{array}{cc}
1 & 0 \\
0 & n\end{array}\right)$.
\end{theorem}

\begin{proof}[Proof of Theorem~\ref{thm: moment formulas} (the 2nd moment).] This is the special case of Theorem~\ref{thm: second moment 2}, where we take $F=f\otimes f$.
\end{proof}

For any $n\in \ZZ-\{0\}$ and $\sigma_i,\; \sigma\in \mathcal P_N$, define
\begin{equation}\label{def: admissible det}
D^{(\sigma_1, \sigma_2)}_n=\left\{({\bf{v_1}}, {\bf{v_2}})\in P^{(\sigma_1)}\times P^{(\sigma_2)}: 
\det({\bf{v_1}}, {\bf{v_2}})=n \right\}
\end{equation}
and $D^{(\sigma)}_n=D^{(\sigma, \sigma)}_n$.

%{\color{blue} emphasize this proposition in the section of organization}
\begin{proposition}\label{pr:no.inv}
The set $D_n^{(\sigma)}\neq \emptyset$ only when $n\in N\ZZ-\{0\}$. The number of $\Gamma(N)$-invariant irreducible sets in $D_n^{(\sigma)}$ for $n\in N\ZZ-\{0\}$ is $N \varphi(n)/\varphi(N)$, where $\varphi(n):=\varphi(|n|)$ is the Euler totient function. 

\end{proposition}

It is worth noting that when $N=2$, stronger results are available:
\[
D_n^{(\sigma_1, \sigma_2)}\neq \emptyset\; \text{if and only if}\; \left\{\begin{array}{ll}
\sigma_1=\sigma_2  &\text{when}\;n\in 2\ZZ-\{0\}; \\
\sigma_1\neq \sigma_2  &\text{when}\;n\in 2\ZZ+1. \\
\end{array}\right.
\]
%For $n\in 2\ZZ-\{0\}$, only $D_n^{(\sigma)}$ for $\sigma=0,1,\infty$ are non-empty, and for $n\in 2\ZZ+1$, only and every $D_n^{(\sigma_1, \sigma_2)}$ are non-empty for $\sigma_1\neq \sigma_2$.

For any $\sigma\in \mathcal P_N$, if $(\bf{v}_1, \bf{v}_2)\in D_n^{(\sigma)}$, then $\bf{v}_1\equiv \bf{v}_2$ modulo $N$ so that $n=\det(\bf{v}_1, \bf{v}_2)\in N\ZZ$, which proves the first assertion of Proposition~\ref{pr:no.inv}. For the second assertion, we need the following lemma.


\begin{lemma}[Chinese remainder theorem (non-coprime version)]\label{le:CRT}
For $a,b,m,n\in\mathbb Z$ such that $a\equiv b \pmod{\mathrm{gcd}(m,n)}$, the system
$$\begin{cases}x\equiv a\pmod{m},\\
x\equiv b\pmod{n}\end{cases}$$
has a solution, which is unique up to being modulo $\mathrm{lcm}(m,n)$.
\end{lemma}

\begin{proof}[Proof of Proposition~\ref{pr:no.inv}]
