Denote $n=Nm$ for some $m\in \ZZ-\{0\}$. We claim that
\begin{equation*}
\begin{pmatrix}a\ell\\b\ell\end{pmatrix}\equiv \begin{pmatrix}a\\ b\end{pmatrix}\pmod{N}\quad\text{ if and only if }\quad\ell= kN+1\text{ for some }1\le k\le m-1,
\end{equation*}
where the reverse direction is trivial.

Suppose that $a(\ell-1)\equiv b(\ell-1)\equiv 0\pmod{N}$.
If $N\nmid\ell-1$, there exists a divisor $p\not=1$ of $N$ such that $p$ divides both $a$ and $b$, which contradicts to $\mathrm{gcd}(a,b)=1$.
Thus we have $N|\ell-1$. Since $1\le\ell\le Nm$, we have $0\le k \le m-1$.

Set
\begin{equation*}\label{eq:SNm1}
S_N(m):=\{1\le \ell\le Nm: \ell\equiv 1\ (\mathrm{mod} \ {N}),~\mathrm{gcd}(\ell,Nm)=1\}
\end{equation*}
(the second condition comes from the fact that $(\ell, n)$ is a primitive vector).
Hence the number of $\Gamma(N)$-invariant irreducible sets in $D^{(\sigma)}_n$ is 
\begin{equation}\label{eqn 2:no.inv}
\frac{[\mathrm{SL}_2(\mathbb Z):\Gamma(N)]}{\# \mathcal P_N}\cdot|S_N(m)|=N\cdot|S_N(m)|.
\end{equation}

Now, let us show that
\begin{equation}\label{eq:no.inv}
|S_N(m)|=\frac{\varphi(Nm)}{\varphi(N)}=\frac{\varphi(n)}{\varphi(N)}.
\end{equation}


Under the assumption that $\ell\equiv 1\pmod{N}$, the condition
$\mathrm{gcd}(\ell,Nm)=1$ is equivalent to the condition $\mathrm{gcd}(\ell,m)=1$
since $\mathrm{gcd}(\ell,N)=1$.
Thus
$$S_N(m) = \{1\le \ell \le Nm: \ell\equiv 1\ (\mathrm{mod} \ {N}),~\mathrm{gcd}(\ell,m)=1\}.$$


We will achieve \eqref{eq:no.inv} by induction on $d := \mathrm{gcd}(N,m)$, starting with two base cases: i) $d=1$ and ii) $d=m$.

\vspace{0.1in}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\noindent i)
Suppose that $d=1$.

If $m=1$, then $S_N(1) = \{1\}$ and automatically \eqref{eq:no.inv} holds.

Suppose $m\not=1$. Consider the projection map
\[
\ZZ/n\ZZ \rightarrow \ZZ/N\ZZ \times \ZZ/m\ZZ:\;\ell \mapsto (\ell \;\mod N, \ell \;\mod m)=(x_\ell,y_\ell).
\]
Then if $\ell\in S_N(m)$, then $x_\ell=1$ and $\gcd(y_\ell, m)=1$. 
On the other hand, it follows from the Chinese remainder theorem that for any integer $y$, the system
\begin{equation*}\begin{cases}
\ell\equiv 1 \pmod N,\\
\ell\equiv y \pmod m
\end{cases}\end{equation*}
has a solution $\ell$ which is unique up to being modulo $n=Nm$.
Thus
$$|S_N(m)|=\#(\mathbb Z/m\mathbb Z)^\times=\varphi(m).$$
By our assumption that $d=\gcd(N,m)=1$, we conclude that
$$\frac{\varphi(Nm)}{\varphi(N)} = \frac{\varphi(N)\varphi(m)}{\varphi(N)}=\varphi(m)=|S_N(m)|.$$

\vspace{0.1in}
\noindent ii) $d=m$, i.e., $m|N$. 

Note that $\ell\equiv 1 \pmod{N}$ implies $\mathrm{gcd}(\ell,N)=1$.
Thus we have $\mathrm{gcd}(\ell,Nm)=1$ and hence $|S_N(m)|=m$.
%We recall two formulae of Euler totient function as
