\psi:& S_N(m) & \to & S_d(m')=\{1\le \ell\le dm': \ell\equiv 1 \;(\mathrm{mod}\; d),\;\gcd(\ell, m')=1\} \\[0.05in]
& \ell & \mapsto & \hspace{-2.9in}\ell \mathrm{~mod~} m.
\end{matrix}
\end{equation*}
