Notice that we reduce the problem counting $|S_N(m)|$ to counting $|S_d(m')|$, where $1\le m'<m$. Repeating this process, we eventually end up in finite steps to the base case, either i) or ii). 
Therefore, we can apply an induction hypothesis which asserts that 
$$|S_d(m')|=\frac{\varphi (dm')}{\varphi(d)}=\frac{\varphi(m)}{\varphi(d)},$$
thus
$|S_N(m)|={d\varphi(m)}/{\varphi(d)}.$
Consequently, we achieve the claim \eqref{eq:no.inv} by observing
$$\frac{\varphi(n)}{\varphi(N)} = \frac{\varphi(Nm)}{\varphi(N)}=\frac{\varphi(N)\varphi(m)d}{\varphi(N)\varphi(d)} = \frac{\varphi(m)d}{\varphi(d)}=|S_N(m)|.$$
%which shows the claim \eqref{eq:no.inv}.
%We conclude that the second assertion of the proposition is derived from \eqref{eqn 2:no.inv} and \eqref{eq:no.inv}.
\end{proof}


