We now ready to prove Theorem~\ref{thm: second moment 2}.
\begin{proof}[Proof of Theorem~\ref{thm: second moment 2}]
By \Cref{pr:no.inv}, for each $\sigma\in \mathcal P_N$, one can decompose $P^{(\sigma)}\times P^{(\sigma)}$ into disjoint $\Gamma(N)$-invariant sets
\[
P^{(\sigma)}\times P^{(\sigma)}=\left\{({\bf v}, {\bf v}): {\bf v}\in P^{(\sigma)}\right\}\sqcup \left\{({\bf v}, -{\bf v}): {\bf v}\in P^{(\sigma)}\right\}\sqcup \bigsqcup_{n\in N\ZZ-\{0\}} D^{(\sigma)}_n,
\]
where $D^{(\sigma)}_n$ is defined as in \eqref{def: admissible det}. One can apply Fubini lemma so that
\begin{align}
&\int_{\SL_2(\RR)/\Gamma(N)} \Siegel{F}{\sigma}(g\Gamma(N)) d\nu_N (g)
=\int_{\SL_2(\RR)/\Gamma(N)} \sum_{
%\scriptsize\begin{array}{c} ({\bf v}_1, {\bf v}_2)\in\\ P^{(\sigma)}\times P^{(\sigma)}\end{array}
\bf v_1, \bf v_2\in P^{(\sigma)}
} F(g{\bf v}_1, g{\bf v}_2) d\nu_N(g) \nonumber\\
&\hspace{0.4in}=\int_{\SL_2(\RR)/\Gamma(N)} \sum_{{\bf v}\in P^{(\sigma)}} F(g{\bf v}, g{\bf v}) d\nu_N(g)+\int_{\SL_2(\RR)/\Gamma(N)} \sum_{{\bf v}\in P^{(\sigma)}} F(g{\bf v}, -g{\bf v}) d\nu_N(g) \label{dependent}
\\
&\hspace{0.6in}+\sum_{n\in N\ZZ-\{0\}}\int_{\SL_2(\RR)/\Gamma(N)} \sum_{
({\bf v}_1, {\bf v}_2)\in
D^{(\sigma)}_n} F(g{\bf v}_1, g{\bf v}_2) d\nu_N(g). \label{independent}
\end{align}
%{\color{magenta} change $\nu$ to $\nu_N$}

Applying the first moment formula (Theorem~\ref{thm: moment formulas} (1)) to bounded and compactly supported functions
\begin{equation}\label{eq:F.fun}
{\bf x} \mapsto F({\bf x}, {\bf x})
\quad\text{and}\quad
{\bf x} \mapsto F({\bf x}. -{\bf x}) 
\end{equation}
on $\RR^2$, it follows that
\[
\eqref{dependent}=\frac 1 {\zeta_N(2)N^2} \int_{\RR^2} F({\bf v}, {\bf v}) d{\bf v}
+\frac 1 {\zeta_N(2)N^2} \int_{\RR^2} F({\bf v}, -{\bf v}) d{\bf v}.
\] 

For integrals in \eqref{independent}, it follows from \Cref{pr:no.inv} that for each $n\in N\ZZ-\{0\}$, $D^{(\sigma)}_n$ consists of $N\varphi(n)/\varphi(N)$ number of $\Gamma(N)$-orbits. Denote by $D^{(\sigma)}_n=\bigsqcup_{i=1}^{N\varphi(n)/\varphi(N)} \Gamma(N) X_i$, where each $X_i\in \ZZ^2\times \ZZ^2$ with $\det X_i=n$.

Applying the folding-unfolding argument,
\[\begin{split}
\int_{\SL_2(\RR)/\Gamma(N)} \sum_{
({\bf v}_1, {\bf v}_2)\in
D^{(\sigma)}_n} F(g{\bf v}_1, g{\bf v}_2) d\nu_N(g)
&=\sum_{i=1}^{N\frac{\varphi(n)}{\varphi(N)}} \int_{\SL_2(\RR)/\Gamma(N)} \sum_{
({\bf v}_1, {\bf v}_2)\in
\Gamma(N)X_i} F(g{\bf v}_1, g{\bf v}_2) d\nu_N(g)\\
&=\sum_{i=1}^{N\frac{\varphi(n)}{\varphi(N)}} \int_{\SL_2(\RR)} F(gX_i) d\nu_N(g).
\end{split}\]

Thus the result follows from the change of variables $gX_i\mapsto gJ_n$ ($\nu_N$: unimodular) and the relation $\nu_N=1/(\zeta(2)N^3\prod_{p|N} (1-\frac 1 {p^2}))\eta=1/(\zeta_N(2)N^3)\eta$.
\end{proof}


