\section{Moment Formulas over the Cone}
In this section, we fix a fundamental domain $\mathfrak F_N$ of $\SL_2(\RR)/\Gamma(N)$. Note that $\mathfrak F_N$ can be considered as the subset of $\RR^2\times \RR^2$. 
We define the cone $\mathfrak C=\mathfrak C_{\mathfrak F_N}$ of $\SL_2(\RR)/\Gamma$ by the embedded image of the map
\[
(t, g) \in (0,1]\times \mathfrak F_N \mapsto t^{1/2}g\in \RR^2\times \RR^2
\]
and assign the product measure $\mathrm{Leb}|_{(0,1]}\times \nu_N$.

Note that the Siegel transform $\Siegel{f}{\sigma}$ and $\Siegel{F}{\sigma}$ can be extended to the cone $\mathfrak C$. However, in this setting, it is more convenient to work with a normalized version of the Siegel transform, defined as follows.
\[\begin{gathered}
t\Siegel{f}{\sigma}(t^{1/2}g):=t\sum_{{\bf v}\in P^{(\sigma)}} f(t^{1/2}g{\bf v})\\
t^2\Siegel{F}{\sigma}(t^{1/2}g):=t^2\hspace{-0.25in}\sum_{\scriptsize \begin{array}{c}
({\bf v}_1, {\bf v}_2)\\
\in P^{(\sigma)}\times P^{(\sigma)}\end{array}} F(t^{1/2}g{\bf v}_1, t^{1/2}g{\bf v}_2)
\end{gathered}\]
for $(t,g)\in (0,1]\times \mathfrak F_N$.

\begin{theorem}\label{thm: First moment on C}
Let $f:\RR^2 \rightarrow \RR$ be a bounded and compactly supported function.
For $P^{(\sigma)}\in \mathcal P_N$, the function $t^{1/2}g\in \mathfrak C\mapsto t\widehat{f}^\sigma(t^{1/2}g)$ is integrable and we have the integral formula
\[
\int_{\mathfrak C} t\Siegel{f}{\sigma} (t^{1/2}g) d\nu_N dt
=\frac 1 {\zeta_N(2)N^2} \int_{\RR^2} f({\bf v}) d{\bf v}.
\]
\end{theorem}
\begin{proof} 
We will assume that $f$ is a non-negative function. The formula for a general function $f$ can be easily obtained since one can decompose $f=f_{+}-f_{-}$ by two non-negative, bounded, and compactly supported functions $f_+:=\max\{f, 0\}$ and $f_-:=\max\{-f, 0\}$.
Applying Tonelli's theorem,
\[
\int_{\mathfrak C} t\Siegel{f}{\sigma} (t^{1/2}g) d\nu_N dt=\int_0^1 t\int_{\SL_2(\RR)/\Gamma(N)}
\widehat{f_t}^{(\sigma)}(g)\nu_Ndt,
\]
where $f_t(\bf{v}):=f(t^{1/2}\bf{v})$.
The formula as well as the integrability follows directly from applying \Cref{thm: moment formulas} (1) in the inner integral, with the fact that
\begin{equation}\label{eq:ch.v}
\int_{\mathbb R^2} f(t^{1/2}\mathbf v)d\mathbf v = \int_{\mathbb{R}^2}t^{-1}f(\mathbf w)d\mathbf w.
\end{equation}
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}\label{thm: Second moment on C}
For $N\in \NN_{\ge 2}$, define a function $\Phi_N$ on $\RR$ as
\begin{equation}\label{def: Phi_N}
\Phi_N(x)=\:|x|\hspace{-0.12in}\sum_{\scriptsize \begin{array}{c} 
n\in N\NN\\
n\ge |x|\end{array}} \frac {N\varphi(n)} {\varphi(N)n^3}.
\end{equation}
%
Let $F:\RR^2\times \RR^2 \rightarrow \RR$ be a bounded and compactly supported function.
For $P^{(\sigma)}\in \mathcal P_N$, we have the integral formula
\begin{equation}\label{eq 1: Cone second moment}\begin{split}
\int_{\mathfrak C} t^2\Siegel{F}{\sigma} (t^{1/2}g) d\nu_N dt
&=\frac 1 {\zeta_N(2)N^3} \int_{\RR^2} \Phi_N(\det({\bf v}_1, {\bf v}_2)) F({\bf v}_1, {\bf v}_2) d{\bf v}_1 d{\bf v}_2\\
&+\frac 1 {2\zeta_N(2)N^2} \int_{\RR^2} F({\bf v}, {\bf v}) + F({\bf v}, -{\bf v}) d{\bf v}.
\end{split}\end{equation}
\end{theorem}

\begin{proof}
As in the proof of \Cref{thm: First moment on C}, we will assume that $F$ is a non-negative function. %The formula for a general function $F$ can be easily obtained since one can decompose $F=F_{+}-F_{-}$ by two non-negative, bouned, and compactly supported functions $F_+:=\max\{F, 0\}$ and $F_-:=\max\{-F, 0\}$.
By Tonelli's theorem, and applying \Cref{thm: moment formulas} (2) to $F_t(\bf{v}_1,\bf{v}_2):=F(t^{1/2}\bf{v}_1, t^{1/2}\bf{v}_2)$,
it holds that
\[\begin{split}
\int_{\mathfrak C} t^2 \Siegel{F}{\sigma} (t^{1/2}g)d\nu_N dt
&=\int_0^1 t^2 \left[
\sum_{n\in N\ZZ-\{0\}} \frac {\varphi(n)}{\zeta_N(2)N^2\varphi(N)}\int_{\SL_2(\RR)} F_t(gJ_n) d\eta(g)\right.\\
&\left. \hspace{1in}+\frac 1 {\zeta_N(2)N^2} \int_{\RR^2} F_t(\bf{v}, \bf{v}) + F_t(\bf{v}, \bf{-v})d\bf{v}\right]dt.
\end{split}\]
By applying \eqref{eq:ch.v} to the functions in \eqref{eq:F.fun},
%It is not hard to show that 
the integral in the second line is equal to the integral in the second line above in \eqref{eq 1: Cone second moment}.
Hence let us concentrate on the integral in the first line of (R.H.S).

For $t\in (0,1]$ and $n\in N\ZZ-\{0\}$, consider the change of variables $g'=gh^{-1}_t$, where $h_t=\diag(t^{-1/2}, t^{1/2})$ so that 
\[
t^{1/2}gJ_n=g'\left(\begin{array}{cc}
1 & 0\\
0 & tn \end{array}\right).
\] 
Then putting $x=tn$, we deduce that the above first integral in (R.H.S) is equal to
\begin{equation}\label{eqn: 2nd moment first term}
\frac 1 {\zeta_N(2) N^2\varphi(N)} \sum_{n\in N\ZZ-\{0\}} \frac {\varphi(n)} { |n|^3}
\int_{n(0,1]} x^2 \int_{\SL_2(\RR)} F\left(g\left(\begin{array}{cc}
1 & 0 \\
0 & x\end{array}\right)\right) d\eta(g)dx.
\end{equation}
Here, $n(0,1]=(0,n]$ if $n>0$, and $[n,0)$ if $n<0$.

On the domain $n(0,1]\times \SL_2(\RR)$, we change variables
\[
g\left(\begin{array}{cc}
1 & 0 \\
0 & x \end{array}\right)=\left(\begin{array}{cc}
1 & 0 \\
c & 1 \end{array}\right)\left(\begin{array}{cc}
a & b \\
0 & a^{-1} \end{array}\right)\left(\begin{array}{cc}
1 & 0 \\
0 & x \end{array}\right)=(\bf{v}_1, \bf{v}_2)
\]
so that $$d\eta(g)dx=dadbdcdx=\frac 1 {|\det(\bf{v}_1, \bf{v}_2)|}d\bf{v}_1d\bf{v_2}.$$

Finally, let us switch two integrals.
Notice that
\[
(\bf{v}_1, \bf{v}_2)\in n(0,1]\times \SL_2(\RR)
\quad\text{if and only if}\quad
\left\{\begin{array}{cl}
x=\det(\bf{v}_1, \bf{v}_2) \ge n &\text{if}\; x>0\;(\text{hence}\; n>0);\\[0.05in]
x=\det(\bf{v}_1, \bf{v}_2) \le n &\text{if}\; x<0,
\end{array}\right.
\]
which explains the subscript of the summation in $\Phi_N(x)$.
Therefore the integral \eqref{eqn: 2nd moment first term} is reduced to
\[
\frac 1 {\zeta_N(2)N^3} \int_{\RR^2\times \RR^2} \Phi_N(\det(\bf{v}_1, \bf{v}_2)) F(\bf{v_1}, \bf{v_2}) d\bf{v}_1 d\bf{v}_2
\]
and we obtain the result.
\end{proof}

%{\color{violet} referring the result of [FH]
%\[
%\Phi_{S,m_0}(x):=|x| \hspace{-0.3in}\sum_{\scriptsize \begin{array}{c}
%n\in \NN\\
%n\equiv m_0 \mod N\end{array}} \frac {\varphi(n)}{n^3}
%\]
%with $\gcd(m_0, N)=1$.
%}


For the purpose of counting lattice points, it is necessary to obtain an estimate for $\Phi_N(x)$.

\begin{proposition}\label{Prop: asym formula of Phi_N} Let $\Phi_N(x)$ be defined as in \eqref{def: Phi_N} for each $N\in \NN$. It holds that
\[\Phi_N(x)=\dfrac 1 {\zeta_N(2)N} + O_N(|x|^{-1}\log |x|)\]
(as $|x|\rightarrow \infty$).
\end{proposition}

\begin{proof}
Since $\phi(N)=N\prod_{p|N} \left(1-\frac 1 p\right)$,
\[
\Phi_N(x)=\frac {N} {\varphi(N)} |x|\sum_{\scriptsize \begin{array}{c}
n\in N\NN\\
n\ge |x|\end{array}} \frac {\varphi(n)}{|n|^3}
=\prod_{p|N}\left(1-\frac 1 p\right)^{-1} |x|\sum_{\scriptsize \begin{array}{c}
n\in N\NN\\
n\ge |x|\end{array}} \frac {\varphi(n)}{|n|^3}.
\]
Hence it suffices to show that
\[
|x|\sum_{\scriptsize \begin{array}{c}
n\in N\NN\\
n\ge |x|\end{array}} \frac {\varphi(n)}{|n|^3}=\frac 1 {\zeta_N(2)N} \prod_{p|N} \left(1-\frac 1 p\right) + O(|x|^{-1}\log|x|).
\]
This is a direct consequence of Abel's summation theorem and Lemma~\ref{lem: estimation 1}.
\end{proof}

\begin{lemma}\label{lem: estimation 1} For any $K>1$,
\[
\sum_{\scriptsize \begin{array}{c}
1\le n \le K\\
n\in N\NN\end{array}} \varphi(m)=\left(\frac 1 {\zeta_N(2)N}\prod_{p|N} \left( 1- \frac 1 p\right)\right)\frac {K^2} 2 +O_N(K\log K).
\]
\end{lemma}
\begin{proof}
Let us focus on how one can reserve the leading term. The error term for each step is easily obtained in a similar way with the proof of \cite[Lemma 4.1]{FH}.

Using the fact that $\varphi(m)=m\sum_{d|m} \mu(d)/d$ for any $m\in \NN$, where $\mu$ is the M\"obius function,
\[
\sum_{\scriptsize \begin{array}{c}
1\le m \le K\\
m\in N\NN\end{array}} \varphi(m)
=\sum_{\scriptsize \begin{array}{c}
1\le m\le K\\
m\in N\NN\end{array}} m \sum_{d|m} \frac {\mu(d)} {d}
=\sum_{1\le d\le K} \mu(d) \sum_{\scriptsize \begin{array}{c}
1\le d'\le K/d\\
dd'\in N\NN\end{array}} d'.
\]
Since $d'd\in N\NN$ and $d'\in \NN$ implies $d'\in \frac N{\gcd(N,d)}\NN$, 
\[\begin{split}
\sum_{\scriptsize \begin{array}{c}
1\le d'\le K/d\\
dd'\in N\NN\end{array}} d'
&=\sum_{k'=1}^{\lfloor K\gcd(N,d)/(dN)\rfloor} \frac N {\gcd(N,d)} k'\\
&=\frac N {\gcd(N,d)} \frac 1 2 \left(\left\lfloor \frac {K\gcd(N,d)} {Nd} \right\rfloor^2+\left\lfloor \frac {K\gcd(N,d)} {Nd} \right\rfloor\right),
\end{split}\]
where $\lfloor x\rfloor$ is the largest integer less than or equal to $x\in \RR$. 
Putting $d_1=\gcd(N,d)$, we obtain
\[\begin{split}
\sum_{\scriptsize \begin{array}{c}
1\le m\le K\\
m\in N\NN\end{array}} \varphi(m)
&=\sum_{1\le d \le K} \mu(d) \frac {K^2\gcd(N,d)} {2d^2N} + O(K\log K)\\
&=\frac {K^2} {2N} \sum_{d_1|N} \sum_{\scriptsize \begin{array}{c}
1\le d\le K\\
\gcd(d,N)=d_1\end{array}} \frac {\mu(d)} {d^2} d_1 + O(K\log K).
\end{split}\]

Now we claim that
\[
\sum_{\scriptsize \begin{array}{c}
1\le d\le K\\
\gcd(N,d)=d_1\end{array}} \frac {\mu(d)}{d^2}\: d_1
=\sum_{\scriptsize \begin{array}{c}
1\le m \le K/d_1\\
\gcd(m,N/d_1)=1\end{array}} \frac {\mu(d_1m)} {(d_1m)^2} \:d_1
=\frac {\mu(d_1)}{d_1} \sum_{\scriptsize \begin{array}{c}
1\le m \le K/d_1\\
\gcd(m,N)=1\end{array}} \frac {\mu(m)} {m^2}.
\]
Indeed, $\mu(d_1m)\neq 0$ only if $\gcd(m,N)=1$.
In this case, $\gcd(m,N/d_1)=1$ if and only if $\gcd(m, N)=1$. Moreover, it holds that $\mu(d_1m)=\mu(d_1)\mu(m)$.

According to the proof of \cite[Lemma 4.1]{FH} (by taking $S=\{\infty\}\cup\{\text{primes dividing }N\}$), it follows that for any $d_1$,
\[
\sum_{\scriptsize \begin{array}{c}
1\le m\le K/d_1\\
\gcd(m,N)=1\end{array}} \frac {\mu(m)} {m^2}
=\sum_{\scriptsize \begin{array}{c}
m\in \NN\\
\gcd(m,N)=1\end{array}}\frac {\mu(m)} {m^2} + O(K\log K)
=\frac 1 {\zeta_N(2)} + O(K\log K).
\]
Therefore, we have
\[\begin{split}
\sum_{\scriptsize\begin{array}{c}
1\le m\le K\\
m\in N\NN\end{array}} \varphi(m)
&=\frac {K^2} {2N} \sum_{d_1|N} \frac {\mu(d_1)}{d_1}\left(\frac 1 {\zeta_N(2)} +O(K\log K)\right)\\
&=\frac 1 {\zeta_N(2)N} \prod_{p|N} \left(1-\frac 1 p\right)\cdot \frac {K^2} 2 + O(K\log K).
\end{split}\]
\end{proof}
