\section{Proofs of Counting Results}
As stated in the introduction, the main steps of the proof of Theorem~\ref{thm: Analog of Schmidt} are essentially parallel to those in Schmidt's original work \cite{Schmidt1960}, thus we do not reproduce the full argument here. We instead provide a sketch of the proof, focusing on the components that interact with the moment formulas presented earlier.

\begin{proof}[Sketch of the proof of Theorem~\ref{thm: Analog of Schmidt}.]
Let $\{A_T\}_{T>0}$ be an increasing family of Borel sets in $\RR^2$ with $V_T=\vol(A_T)\rightarrow \infty$ as $T\rightarrow \infty$. By re-indexing if necessary, we may further assume that $V_T=T$ for any $T>0$.

For each $m\in \NN$, define
\[
K_{m}=\left\{(M_1, M_2): 0\le M_1<M_2\le 2^m, \; M_1= u2^\ell,\; M_2=(u+1)2^{\ell}\;\text{for some}\; u,\ell\in \ZZ_{\ge 0} \right\}.
\]
We apply Borel--Cantelli lemma on the collection $\{\mathfrak B_m\}_{m\in \NN}$, where
\[
\mathfrak B_m=\left\{t^{1/2}g\in \mathfrak C: \left|t\widehat{\mathbbm 1}^{(\sigma)}_{A_M}(t^{1/2}g) - \frac {V_M}{\zeta_N(2)N^2}\right|\ge m^2 2^{m/2} \psi^{1/2}(m\log2 -1),\;\forall M\le 2^m \right\}.
\]

Indeed, one can show that
\begin{equation*}
\int_{\mathfrak B_m} 1 \:d \nu_N(g)dt\le \frac {c} {\psi(M\log2 -1)} 
\end{equation*}
for some $c>0$ (see \cite[Lemma 13]{Schmidt1960}), thus the summation of measures of $\mathfrak B_m$ converges under our assumption that $\int \psi^{-1}(x) dx<\infty$.
And one can obtain the above inequality directly from the following: there is a constant $c_1>0$ so that
\begin{equation}\label{eqn 1: sketch}
\sum_{(M_1, M_2)\in K_m} \int_{\mathfrak C} \left(t\widehat{\mathbbm 1}^{(\sigma)}_{A_{M_2}-A_{M_1}}(t^{1/2}g) - \frac {V_{M_2}-V_{M_1}} {\zeta_N(2)N^2}\right)^2 d\nu_N(g) dt< c_1m^3 2^m,
\end{equation}
together with observing that for any $M\le 2^m$, the interval $[0, M)$ can be expressed as the union of at most $2m$ intervals of the type $[M_1, M_2)$, where $(M_1, M_2)\in K_m$, and Cauchy--Schwarz inequality (\cite[Lemma12]{Schmidt1960}). Note that the function $\mathbbm 1_{A_M}$ can be written by a sum of at most $2M$ terms of the form $\mathbbm 1_{A_{M_2}-A_{M_1}}$, and likewise for $t\widehat{\mathbbm 1}^{(\sigma)}_{A_{M}}$ with terms $t\widehat{\mathbbm 1}^{(\sigma)}_{A_{M_2}-A_{M_1}}$.

Combining first moment formula (Theorem~\ref{thm: First moment on C}) and the second moment formula (Theorem~\ref{thm: Second moment on C}), it follows that for any $A\subseteq \RR^2$ (we will put $A=A_{M_2}-A_{M_1}$),
\[\begin{split}
\int_{\mathfrak C} \left(t\widehat{\mathbbm 1}^{(\sigma)}_A (t^{1/2}g) - \frac {\vol(A)}{\zeta_N(2)N^2}\right)^2 d\nu_N(g)dt
&\le
\frac 1 {2\zeta_N(2)N^2} \int_{\RR^2} \mathbbm 1_A(\bf{v})\left(\mathbbm 1_{A}(\bf{v})+\mathbbm 1_{A}(-\bf{v})\right) d\bf{v}\\
&\hspace{-1.4in}+\frac 1 {\zeta_N(2)N^3} \int_{\RR^2\times \RR^2} \left(\Phi_N(\det(\bf{v}_1, \bf{v}_2)) -\frac 1 {\zeta_N(2)N}\right)\mathbbm 1_{A}(\bf{v}_1) \mathbbm 1_{A}(\bf{v}_2) d\bf{v}_1 d\bf{v}_2.
\end{split}\]


Proposition~\ref{Prop: asym formula of Phi_N} yields that there are constants $c_2, \;c_3$ and $V_0>0$ such that if $V=\vol(A)>V_0$, one can take a non-negative and non-increasing function $\chi$ on $\RR_{>0}$ 
\[
\chi(x)=\left\{\begin{array}{cl}
c_2&{if}\; x<V_0/\log V_0;\\[0.05in]
c_3x^{-1}\log x&\text{if}\; V_0/\log V_0 \le x < V/\log V;\\[0.05in]
0&\text{if}\; x\ge V/\log V\\
\end{array}\right.\]
so that the following holds: $\int_{0}^\infty \chi(x)dx \le c_4 (\log V)^2$ for some $c_4>0$, thus there is $c_5>0$ such that 
\[
\frac 1 {\zeta_N(2)N^3} \int_{\RR^2\times \RR^2} \left(\Phi_N(\det(\bf{v}_1, \bf{v}_2)) -\frac 1 {\zeta_N(2)N}\right)\mathbbm 1_{A}(\bf{v}_1) \mathbbm 1_{A}(\bf{v}_2) d\bf{v}_1 d\bf{v}_2 \le c_5 V(\log V)^2
\]

(see the proof of \cite[Lemma 10 and Lemma 11]{Schmidt1960}).

Notice that the function $\chi$ depends on the Borel set $A$, specifically on the volume of $A$. 
Here, we use \cite[Theorem 3]{Schmidt1960} which states when $d=2$ that
\[
\int_{\RR^2\times \RR^2} \mathbbm 1_A (\bf{v}_1) \mathbbm 1_A(\bf{v}_2) \chi(|\det(\bf{v}_1, \bf{v}_2)|)
d\bf{v}_1 d\bf{v}_2 \le 8 \vol(A)\int_0^\infty \chi(x) dx.
\]

Hence, we obtain that
\[
\int_{\mathfrak C} \left(t\widehat{\mathbbm 1}^{(\sigma)}_A (t^{1/2}g) - \frac {\vol(A)}{\zeta_N(2)N^2}\right)^2 d\nu_N(g)dt \le c_6 V(\log V)^2.
\]
The upperbound \eqref{eqn 1: sketch} is deduced by summing all integrals for the sets $A=A_{M_2}-A_{M_1}$, where $(M_1, M_2)\in K_m$. Note that we use a decomposition of $K_m$, with possible repetitions, into the $m$-number of chains of pairs of $(M_1, M_2)$ as follows.
\[\begin{array}{c}
(0\cdot 2, 1\cdot 2), (1\cdot 2, 2\cdot 2), (2\cdot 2, 3\cdot 2), ..., ((2^{m-1}-1)\cdot 2, 2^{m-1}\cdot 2);\\
(0\cdot 2^2, 1\cdot 2^2), (1\cdot 2^2, 2\cdot 2^2), (2\cdot 2^2, 3\cdot 2^2), ..., ((2^{m-2}-1)\cdot 2^2, 2^{m-2}\cdot 2^2);\\
\vdots\\
(0\cdot 2^{m-1}, 1\cdot 2^{m-1}), (1\cdot 2^{m-1}, 2\cdot 2^{m-1}).
\end{array}\]
The partial sum over each chain in \eqref{eqn 1: sketch} is bounded by $c_6\vol(A_M)\log(\vol(A_M))^2\le c_6 2^{m} m^2$. 
\end{proof}


\begin{proof}[Proof of Theorem~\ref{thm: quantitative K}.] The key idea is to use Theorem~\ref{thm: Analog of Schmidt} with the family of Borel sets 
\[
\left\{A_T=\left\{(x,y)\in \RR^2: |x|\le \phi(|y|)\;\text{and}\; |y|<T\right\}\right\}_{T\in \RR_{>0}}.
\]
Moreover, we want to put $g=u_x=\left(\begin{array}{cc} 1 & x \\ 0 & 1\end{array}\right)$ for generic $x\in \RR$. For this reduction, we consider the small neighborhood of $\{u_x\in \SL_2(\RR): x\in \RR\}$ by thickening in direction 
\[\left\{\left(\begin{array}{cc} y & 0 \\ z & y^{-1}\end{array}\right): y\neq 0, \;z\in \RR \right\}.
\]

For the details, we refer the reader to \cite{AGY2021}. While their result is stated for $d\ge3$, due to the lack of moment formulas in dimension two, the proof of \cite[Theorem 1]{AGY2021} that we require here is not directly affected by this limitation.
\end{proof}

