\title[]{\Large{The Bilinear Hilbert--Carleson operator along curves}\\\normalsize{The purely non-zero curvature case}}
\author{\'Arp\'ad B\'enyi, Bingyang Hu and Victor Lie}

\address{\'Arp\'ad B\'enyi: Department of Mathematics, Western Washington University, 516 High Street, Bellingham, WA 98225,  U.S.A.}%
\email{benyia@wwu.edu}%%

\address{Bingyang Hu: Department of Mathematics, Auburn University, 221 Parker Hall, Auburn, AL 36849, U.S.A.}%
\email{bzh0108@auburn.edu}%%

\address{Victor D. Lie: Department of Mathematics, Purdue University, 150 N. University St, W. Lafayette, IN 47907, U.S.A.  and
The ``Simion Stoilow" Institute of Mathematics of the Romanian Academy, Bucharest, RO 70700, P.O. Box 1-764, Romania}%
\email{vlie@purdue.edu}%%




\begin{abstract} In this paper, we provide the maximal boundedness range (up to end-points) for the Bilinear Hilbert--Carleson operator along curves in the (purely) non-zero curvature setting. More precisely, we show that the operator 
$$  BHC_{[\vec{a},\vec{\a}]}(f_1,f_2)(x):=\sup_{\lambda\in\R}\left|\,\textnormal{p.v.}\int_{\R} f_1(x- a_1 t^{\a_1})\,f_2(x- a_2 t^{\a_2})\,e^{i\,\lambda\,a_3 \,t^{\a_3}}\,\frac{dt}{t}\right|$$
obeys the bounds  
$$\|BHC_{[\vec{a},\vec{\a}]}(f_1,f_2)\|_{L^r}\lesssim_{\vec{a}\,\vec{\a},r,p_1,p_2}\|f_1\|_{L^{p_1}}\,\|f_2\|_{L^{p_2}}$$ 
whenever  $\vec{a}=(a_1,a_2,a_3),\,\vec{\a}=(\a_1,\a_2,\a_3)\in (\R\setminus\{0\})^3$ with $\vec{\a}$ having pairwise distinct coordinates and 
for any H\"older range $\frac{1}{p_1}+\frac{1}{p_2}=\frac{1}{r}$ with $1<p_1,p_2<\infty$ and $\frac{1}{2}<r<\infty$.

This result is achieved via the Rank II LGC method introduced in \cite{HL23}.
\end{abstract}
\date{\today}

\keywords{Trilinear Hilbert transform, Bilinear Hilbert--Carleson operator, correlative time-frequency/wave-packet analysis, joint Fourier coefficients,  zero/non-zero curvature, LGC method, sparse-uniform decomposition, level set analysis, time-frequency correlation set.}

