\section{Introduction}

In this paper we focus on the study of singular integral operators that encompass the following features:
\begin{itemize}
\item a \textsf{multi(sub)linear} nature;

\item a \textsf{commutation} relation relative to the standard symmetries, \textit{i.e.},  translations and dilations;

\item a \textsf{Carleson-type} behavior, \textit{i.e.}, the defining object may be expressed as a supremum over a family of multilinear integral operators with (generalized) modulated singular kernel.
\end{itemize}

Indeed, our goal in this paper is to understand the behavior of the \emph{purely curved (non-resonant)} case of the generic \emph{Bilinear Hilbert--Carleson operator along $\vec{\g}$} defined as\footnote{Throughout the paper, all the singular integral expression are apriori only defined for Schwartz functions.}
\begin{equation}\label{BHCcurv}
        BHC_{[\vec{\g}]}(f_1,f_2)(x):=\sup_{\lambda\in\R}\left|\: \textrm{p.v.} \int_{\R} f_1(x-\g_1(t))\,f_2(x-\g_2(t))\,e^{i\,\lambda\,\g_3(t)}\,\frac{dt}{t}\right|\,,
\end{equation}
where here $\vec{\g}(t)=(\g_1(t), \g_2(t), \g_3(t))$ is a piecewise differentiable curve in $\R^3$.

While the deeper motivation behind the study of \eqref{BHCcurv} will be explained in detail in Section \ref{MotivHistory}, see in particular Remark \ref{ConIII2} therein, for the moment being, we summarize its key underlying justification as follows: the behavior of $BHC_{[\vec{\g}]}$ is \emph{connected in a fundamental, conceptual way} to the behavior of the \emph{trilinear Hilbert transform along $\vec{\g}$} given by 
\begin{equation}\label{ThTcurv}
        THT_{[\vec{\g}]}(f_1,f_2,f_3)(x):= \,\textrm{p.v.}\int_{\R} f_1(x-\g_1(t))\,f_2(x-\g_2(t))\,f_3(x-\g_3(t))\,\frac{dt}{t}\,,
\end{equation}
with the latter being a central object of interest whose general understanding constitutes an important open problem in harmonic analysis.


With these being said, we pass now to

\subsection{Statement of the main result}\label{Mainres}

\begin{mthm} \label{mainresult} \textit{Let \footnote{In the case $\a\notin\Z$ one has to properly define the meaning of $t^{\a}$ as either $|t|^{\a}$ or $\textrm{sgn}{t}\,|t|^{\a}$.} $\vec{\g}(t)=(a_1 t^{\a_1}, a_2 t^{\a_2}, a_3 t^{\a_3})$ with $\vec{a}=(a_1,a_2,a_3),\,\vec{\a}=(\a_1,\a_2,\a_3)\in (\R\setminus\{0\})^3$  and set
\begin{equation}\label{BHCcurval}
        BHC_{[\vec{a},\vec{\a}]}(f_1,f_2)(x):=\sup_{\lambda\in\R}\left|\,\emph{p.v.}\int_{\R} f_1(x- a_1 t^{\a_1})\,f_2(x- a_2 t^{\a_2})\,e^{i\,\lambda\,a_3 \,t^{\a_3}}\,\frac{dt}{t}\right|\,.
\end{equation}
If $\vec{\a}$ is a vector with \emph{pairwise distinct} coordinates then
the purely nonresonant\footnote{\textit{I.e.}, the operator under discussion has no modulation invariance structure.} Bilinear Hilbert--Carleson operator $BHC_{[\vec{a},\vec{\a}]}(f_1,f_2)$ obeys\footnote{Here and henceforth, for $a, b \in \R$, $a \lesssim b$ ($a \gtrsim b$, respectively) means there exists an absolute $C>0$, which is independent of $a$ and $b$, such that $a \le Cb$ ($a \ge Cb$, respectively). Moreover, if both $a\lesssim b$ and $a \gtrsim b$ hold, then we say $a \sim b$.}
\begin{equation}\label{BHCcurval1}
        \|BHC_{[\vec{a},\vec{\a}]}(f_1,f_2)\|_{L^r}\lesssim_{\vec{a}\,\vec{\a},r,p_1,p_2}\|f_1\|_{L^{p_1}}\,\|f_2\|_{L^{p_2}}
\end{equation}
for any H\"older range $\frac{1}{p_1}+\frac{1}{p_2}=\frac{1}{r}$ with $1<p_1,p_2<\infty$ and $\frac{1}{2}<r<\infty$.}
\end{mthm}

\begin{rem}\label{mainresultconse} As a confirmation of the natural companionship and already alluded deep interrelationship between \eqref{BHCcurv} and \eqref{ThTcurv}, we have that many elements in the proof of the above main theorem \emph{both rely and are relied upon}\footnote{For more on this please see Remark \ref{ConIII2}, Remark \ref{twoway} and, more generally, Section \ref{Planmainideas}.} when treating the trilinear counterpart \eqref{ThTcurv}, as witnessed by the work in \cite{HL23}:

 \textit{Under the same (purely) nonresonant hypothesis on $\vec{\a}$ as in Main Theorem \ref{mainresult}, we have that the curved trilinear Hilbert transform 
\begin{equation}\label{ThTcurval}
        THT_{[\vec{a},\vec{\a}]}(f_1,f_2,f_3)(x):= \,\emph{p.v.}\int_{\R} f_1(x- a_1 t^{\a_1})\,f_2(x- a_2 t^{\a_2})\,f_3(x-a_3 t^{\a_3})\,\frac{dt}{t}\,.
\end{equation}
obeys
\begin{equation}\label{ThTcurval1}
        \|THT_{[\vec{a},\vec{\a}]}(f_1,f_2,f_3)\|_{L^r}\lesssim_{\vec{a}\,\vec{\a},r,p_1,p_2,p_3}\|f_1\|_{L^{p_1}}\,\|f_2\|_{L^{p_2}}\,\|f_3\|_{L^{p_3}}
\end{equation}
for any Banach H\"older range $\frac{1}{p_1}+\frac{1}{p_2}+\frac{1}{p_3}=\frac{1}{r}$ with $1<p_1,p_2,p_3<\infty$ and $1\leq r<\infty$.}
\end{rem}


\begin{rem}\label{Gen1} Both proofs of the boundedness of \eqref{BHCcurval} and \eqref{ThTcurval} in the purely non-zero curvature setting as stated in Main Theorem \ref{mainresult} and Remark \ref{mainresultconse}, respectively, employ the Rank II LGC--method introduced in \cite{HL23}. Indeed, in contrast with the reasonings in \cite{Lie2024}, \cite{GL25} and \cite{HsL24} but similar with those in \cite{BBLV24} and \cite{HL23}, the linearized discrretized model of the operator in the present paper---obtained via the Rank I LGC--method---is \emph{not absolutely summable}. We stress here that the lack of absolute summability appearing in our context is a phenomenon \emph{within each single scale and not in-between scales}. The latter situation has been encountered before, see \emph{e.g.} \cite{Th02}, and, comparatively, is easier to address via partial integration, Plancherel and telescoping sum arguments. The former phenomenon however, is much more subtle as it captures hidden cancellations within the \emph{same-scale} local Fourier coefficients of the input functions: handling this type of challenge is the main strength and novelty as well as the very reason for designing the Rank II LGC--method.  Indeed, at the heart of this method lies a \emph{correlative} time-frequency discretized model that exploits the \emph{interaction} of the Fourier modes of the input functions and whose control is achieved via the following key ingredients:
\begin{enumerate} 
\item  a \emph{sparse-uniform decomposition} of the input functions adapted to a foliation of the phase-space;

\item  a structural analysis of some appropriate \emph{maximal joint Fourier coefficients};

\item  a level set analysis with respect to the \emph{time-frequency correlation set}.
\end{enumerate}
\end{rem}

\begin{rem}\label{Gen2A} The Bilinear Hilbert--Carleson operator defined by \eqref{BHCcurval1} and corresponding to the \emph{hybrid quadratic non-resonant} case  $\a_1=\a_2=1$ and $\a_3\notin\{1,2\}$ was introduced and studied in \cite{BBLV24}. Overall, this hybrid case is strictly harder than the purely non-resonant case studied in the present paper since in the former case one has to confront the presence of the modulation invariance structure expressed in \eqref{hybnresI}. However, a careful comparative analysis of the two proofs reveals the following deeper antithesis:
\begin{itemize}  
\item on the one hand, the \emph{single scale ($L^2$--base) smoothing inequality}\footnote{See the Main Proposition (informal version) in  Section \ref{Planmainideas} versus the corresponding Proposition 4.1. in \cite{BBLV24}.}  is significantly more difficult in the purely non-resonant case as opposed to the hybrid case. Indeed the crucial distinction is made by the un-isotropic (in the purely non-resonant case) versus isotropic (in the hybrid case) character of the $t-$argument corresponding to the input functions. This is turn requires for the  non-resonant case the introduction of a novel approach relying on the so-called constancy propagation of the linearizing function---see the discussion in Section \ref{Planmainideas};

\item on the other hand, the \emph{multi-scale analysis} is significantly more difficult in the hybrid case as opposed to the purely non-resonant case due to the extra modulation invariance structure of the former case which requires a BHT/Carleson type analysis involving tree selection algorithms based on the concepts of size, energy and mass---see Section 6 in \cite{BBLV24}.  
\end{itemize}
\end{rem}



\begin{rem}\label{Gen3}  Building on the context offered by Main Theorem \ref{mainresult}, Remark \ref{mainresultconse} and Remark \ref{Gen2A} it becomes apparent that the studies of the Bilinear Hilbert--Carleson operator $ BHC_{[\vec{a},\vec{\a}]} $ defined by \eqref{BHCcurval} and of the Trilinear Hilbert Transform $THT_{[\vec{a},\vec{\a}]}$ defined by \eqref{ThTcurval} are not only intimately connected to each-other but also on the specific choice of the vector $\vec{\a}=(\a_1,\a_2,\a_3)\in \R_{+}^3$. Consequently, we are naturally led to consider the following \emph{hierarchy}:
\begin{itemize}
\medskip
\item \textsf{The purely \underline{\emph{non-resonant}} case: $\{\a_j\}_{j=1}^3$ covers \underline{\emph{three}} distinct values}. In this situation neither $ BHC_{[\vec{a},\vec{\a}]} $ nor $THT_{[\vec{a},\vec{\a}]}$  have any modulation invariance symmetries. The full treatment of the former object is provided in the present paper while the treatment of the latter object is (essentially) covered in \cite{HL23}.
\medskip
\item \textsf{The \underline{\emph{hybrid}} case: $\{\a_j\}_{j=1}^3$ covers \underline{\emph{two}} distinct values}. In this situation both objects under consideration have suitable modulation invariance properties. However, their analysis splits in two major subcases:
\begin{itemize} 
 \item \textsf{\emph{hybrid quadratic non-resonant}} case: 
$$\qquad\qquad\exists\,i\not=k\in\{1,2,3\}\:\:\textrm{with}\:\:\a_i=\a_k=\min\{\a_j\}_{j=1}^3\notin \left\{\frac{1}{2}\max\{\a_j\}_{j=1}^3,\,\max\{\a_j\}_{j=1}^3\right\}\,.$$
\quad In this situation we further split our discussion according to the nature of our operator:
\begin{itemize}
\item for the Trilinear Hilbert Transform $THT_{[\vec{a},\vec{\a}]}$, due to the input symmetry and the presence of the dilation invariant Haar measure $\frac{dt}{t}$, we may assume wlog that $\a_1=\a_2=1$ and $\a_3\notin\{1,2\}$. As a consequence, we have the linear modulation\footnote{Throughout the paper, we denote the $j$-order modulation with parameter $a\in\R$ by $M_{j,a} f(x):=e^{i a x^j}\,f(x)$ with $j\in\N$.} invariance
    \begin{equation}\label{hybnres}
    \left| THT_{[\vec{a},\vec{\a}]} \left(M_{1,\frac{c}{a_1}}f_1, M_{1,-\frac{c}{a_2}}f_2, f_3\right)\right|=\left| THT_{[\vec{a},\vec{\a}]} \left(f_1, f_2, f_3\right)\right|\qquad \forall\:c\in\R\,.
    \end{equation}


\item for the Bilinear Hilbert--Carleson operator $ BHC_{[\vec{a},\vec{\a}]}$ we still have the dilation invariance of the measure but we lack the input symmetry and hence there is not a unique case to consider. Nevertheless, a natural prototype for the hybrid quadratic non-resonant case which is also the analogue of \eqref{hybnres}, is the situation $\a_1=\a_2=1$ and $\a_3\notin\{1,2\}$ given by
   \begin{equation}\label{hybnresI}
     BHC_{[\vec{a},\vec{\a}]} \left(M_{1,\frac{c}{a_1}}f_1, M_{1,-\frac{c}{a_2}}f_2\right)=BHC_{[\vec{a},\vec{\a}]} \left(f_1, f_2\right)\qquad \forall\:c\in\R\,.
    \end{equation}   
This last operator has been addressed in \cite{BBLV24}.
   \end{itemize}
\item  \textsf{\emph{hybrid quadratic resonant}} case:
$$\qquad\qquad\exists\,i\not=k\in\{1,2,3\}\:\:\textrm{with}\:\:\a_i=\a_k=\min\{\a_j\}_{j=1}^3=\frac{1}{2}\max\{\a_j\}_{j=1}^3\,.$$
\quad As before, we further split our discussion according to the nature of our operator:
\begin{itemize}
\item for the Trilinear Hilbert Transform $THT_{[\vec{a},\vec{\a}]}$, appealing to the input symmetry and dilation invariance, we may assume wlog that $\a_1=\a_2=1$ and $\a_3=2$. As a consequence, on top of \eqref{hybnres}, we now also have the quadratic modulation invariance
    \begin{equation}\label{hybres}
    \left| THT_{[\vec{a},\vec{\a}]} \left(M_{2,\frac{c}{a_1}}f_1, M_{2,-\frac{c}{a_2}}f_2, M_{1, \frac{c}{\a_3}(\a_1-\a_2)} f_3\right)\right|=\left| THT_{[\vec{a},\vec{\a}]} \left(f_1, f_2, f_3\right)\right|\qquad \forall\:c\in\R\,.
    \end{equation}

\item for the Bilinear Hilbert--Carleson operator $ BHC_{[\vec{a},\vec{\a}]}$, again, there are more options, with the natural analogue of \eqref{hybres} given by the case $\a_1=\a_2=1$ and $\a_3=2$. On top of \eqref{hybnresI} we now have 
   \begin{equation}\label{hybresI}
     BHC_{[\vec{a},\vec{\a}]} \left(M_{2,\frac{c}{a_1}}f_1, M_{2,-\frac{c}{a_2}}f_2\right)=BHC_{[\vec{a},\vec{\a}]} \left(f_1, f_2\right)\qquad \forall\:c\in\R\,.
    \end{equation}   
\end{itemize}
The hybrid quadratic resonant case is widely open. Any significant advancement would require some fundamental new ideas. 
\end{itemize}
\medskip
\item \textsf{The purely \underline{\emph{resonant}} case: $\{\a_j\}_{j=1}^3$ covers \underline{\emph{one}} single value}.  This is of course the most difficult case from all of the ones listed above. By applying a standard dilation invariance argument one can reduce matters to the situation $\a_1=\a_2=\a_3=1$. Also, for the simplicity of the exposition we set $\vec{a}=(a_1,a_2,a_3)=(1,2,3)$ and with these choices for $\vec{a},\vec{\a}$ we simply refer to  $THT_{[\vec{a},\vec{\a}]}$ as $\textsf{THT}$ and, with the obvious adaptations, to $BHC_{[\vec{a},\vec{\a}]}$ as $\textsf{BHC}$. With these, we have
\begin{itemize}   
 \item the (zero-curvature) Trilinear Hilbert Transform $\textsf{THT}$ obeys the modulation invariance relations
    \begin{equation}\label{thtpres}
    \left| \textsf{THT} \left(M_{1,3b_1}f_1, M_{1,3b_2}f_2, M_{1, -b_1-2b_2} f_3\right)\right|=\left| \textsf{THT}\left(f_1, f_2, f_3\right)\right|\qquad \forall\:b_1,\,b_2\in\R\,,
    \end{equation}
and
    \begin{equation}\label{thtpresquad}
    \left| \textsf{THT} \left(M_{2,3b}f_1, M_{2,-3b}f_2, M_{2,b} f_3\right)\right|=\left| \textsf{THT}\left(f_1, f_2, f_3\right)\right|\qquad \forall\:b\in\R\,.
    \end{equation}
 The infamous question addressing the boundedness of \textsf{THT} is widely open and represents one of the most difficult problems in harmonic analysis.\footnote{For more on this, the interested reader is invited to consult the introductory sections in \cite{Lie20} and \cite{HL23}.} 

\item the (zero-curvature) Bilinear Hilbert--Carleson operator $\textsf{BHC}$ obeys the modulation invariance relations
\begin{equation}\label{BHCpres1}
     \textsf{BHC} \left(M_{1,b_1}f_1, M_{1,b_2}f_2\right)=\textsf{BHC} \left(f_1, f_2\right)\qquad \forall\:b_1,\,b_2\in\R\,,
    \end{equation}   
and
 \begin{equation}\label{BHCpres2}
     \textsf{BHC}\left(M_{2,4b} f_1, M_{2,-b}f_2\right)=\textsf{BHC}\left(f_1, f_2\right)\qquad \forall\:b\in\R\,.
 \end{equation}   
 The question addressing the boundedness of \textsf{BHC} is also widely open and is directly related to another fundamental problem in classical Fourier analysis that of the pointwise convergence of the bilinear Fourier series.\footnote{For more on this one is invited to consult the Introduction in \cite{BBLV24}.}    
\end{itemize}    





\end{itemize}





\end{rem}

\subsection{Motivation and historical background}\label{MotivHistory}

The perspective and the overall structure of the presentation in this section is inspired by a survey paper \cite{Liesurv} in which the author therein discusses several deep connections between multilinear singular operators and maximal multi(sub)linear operators of Carleson type.
\medskip

Fix $n\in\N$. For expository reasons, in what follows, we introduce two generic classes of operators\footnote{The case of foremost importance for our present paper is $n=3$.}:
\begin{itemize}

\item \underline{$1^{st}$ class}: \textsf{the $(n-1)$-linear $\vec{\G}$-Carleson operator} $C_{n-1,\vec{\G}}$, defined as
\beq\label{nhilBHCarl}
C_{n-1,\vec{\G}}(f_1,\ldots,f_{n-1})(x):= \textrm{p.v.}\int_{\R}\prod_{j=1}^{n-1} f_j(x-\underline{\g}_j(t))\,\frac{e^{i\,\g(x,t)}}{t}\,dt\,,
\eeq
where here $\vec{\underline{\g}}:=(\underline{\g}_1 ,\ldots ,\underline{\g}_{n-1}):\mathbb R \rightarrow \mathbb R^{n-1}$ is an $(n-1)-$variable tuple with each $\underline{\g}_j$ a suitable piecewise smooth planar curve, $\g(x,t)$ is a piecewise smooth function in $t$ and only measurable in $x$, and, finally $\vec{\G}(x,t):=(\vec{\underline{\g}}(t), \g(x,t))$.
\medskip

 \item \underline{$2^{nd}$ class}: \textsf{the $n$-linear \emph{$\vec{\g}$-Hilbert transform}} $H_{n,\vec{\g}}$, defined as
\beq\label{nhilb}
H_{n,\vec{\g}}(f_1,\ldots,f_n)(x):= \textrm{p.v.}\int_{\R}\prod_{j=1}^n f_j(x-\g_j(t))\,\frac{dt}{t}\,,
\eeq
 where here $\vec{\g}:=(\g_1 ,\ldots ,\g_n):\mathbb R \rightarrow \mathbb R^n$ is an $n-$variable tuple with each $\g_j$ being a suitable piecewise smooth planar curve.
 \medskip
\end{itemize}

Next, in the increasing order of complexity, we build a hierarchical structure within which we elaborate on the deep and subtle interplay between the two classes introduced above. For now, in preparation for the discussion below, we mention that at the heuristic level this interplay involves a ``\emph{degree reduction}", by trading the $n^{th}$ input function in \eqref{nhilb} for a maximal ($x-$dependent) oscillatory exponential in \eqref{nhilBHCarl}, thus connecting
$H_{n,\vec{\g}}$ to $C_{n-1,\vec{\G}}$. We end these preparatives by stating that our antithetical discussion follows in parallel the above two sets of objects depending on 
\begin{itemize}
\item the value of $n$;

\item the curvature paradigm:  zero, non-zero and hybrid curvature regimes.
\end{itemize}

\noindent\underline{\textbf{I) The case $n=1$.}} $\quad$ In this context, using the convention $\prod_{j=1}^{0} f_j\equiv1$ one may represent \eqref{nhilBHCarl} as a maximal oscillatory singular integral. With this interpretation, one can portray the work of E. Stein and S. Wainger in \cite{swmul} as providing uniform in $x-$bounds to \eqref{nhilBHCarl} whenever $\g(x,t)=\sum_{j=1}^d a_j(x)\,t^{\a_j}$ with $d\in\N$, $\{\a_j(\cdot)\}_j$ real measurable functions and $\{\a_j\}_j\subset\R_{+}$.

Moving now our focus on \eqref{nhilb}, it becomes transparent that this expression corresponds to the classical Hilbert transform along curves $H_{1,\g}$ which is a central object within harmonic analysis, and which, among others, serves---in the zero curvature setting---as a main prototype for the seminal Calder\'on-Zygmund theory (see e.g. \cite{CZ1} and \cite{CZ2}). 

Along the way, we notice that the $L^2$-boundedness of \eqref{nhilb} is equivalent with the $L^{\infty}$-boundedness (as a function of $x$) of \eqref{nhilBHCarl} in the setting $\g(x,t):=x\,\g_1(t)$.
\smallskip

\noindent\underline{\textbf{II.1) The case $n=2$, zero curvature.}} $\quad$ We start our examination with the first class \eqref{nhilBHCarl}: the zero curvature case corresponds to the situation $\underline{\g}_1(t)=t$ and $\g(x,t)=a(x)\,t$ with $a$ measurable function, and the operator defined by \eqref{nhilBHCarl} represents the classical Carleson operator. Historically, the study of this operator was motivated by the central question---laying at the foundation of the harmonic analysis area---regarding the pointwise convergence of Fourier Series for square integrable functions. This problem offered the first study case of an operator that is invariant under linear modulation. In 1966, L. Carleson proved in \cite{Car66} his celebrated result on the $L^2$ boundedness of $C_{1,\G}$. Later, R. Hunt, \cite{hu}, extended this result to any $L^p$, $1<p<\infty$.


The second class \eqref{nhilb} corresponds to $\vec{\g}(t)=(a t, b t)$, $a\not=b\in\R\setminus\{0\}$  and was motivated by A. Calder\'on's study of the Cauchy transform on Lipschitz curves (\cite{Cal}, \cite{CMM}). After more than two decades, the first key insight into this problem was due to M. Lacey, who in \cite{la1} noticed that both the Carleson operator $C_{1,\G}$ and the bilinear Hilbert transform $H_{2,\vec{\g}}$ share a similar modulation invariance structure thus hinting that the approach of $H_{2,\vec{\g}}$ must rely on time-frequency techniques and in particular wave-packet analysis. This intuition was indeed confirmed in the breakthrough papers \cite{lt1}, \cite{lt2}, where, by introducing a novel time-frequency framework,  M. Lacey and C. Thiele proved the $L^{p_1}\times L^{p_2}\,\longrightarrow\,L^r$ boundedness of $H_{2,\vec{\g}}$ within the range $\frac{1}{p_1}+\frac{1}{p_2}=\frac{1}{r}$, $1<p,q\leq\infty$ and $\frac{2}{3}<r<\infty$.

\begin{rem}
We end the overview of case II.1 with two commentaries:
\begin{itemize}
 \item this zero-curvature case confirms the strong connection between the two classes of operators introduced in \eqref{nhilBHCarl} and \eqref{nhilb}: indeed, the methods pioneered by L. Carleson, \cite{Car66} and C. Fefferman, \cite{f} in relation to $C_{1,\G}$ served both as an inspiration and proved quintessential in the successful approach of $H_{2,\vec{\g}}$ via the concepts of mass, energy, tiles and tree organization/selection; 
 \item due to the lack of absolute summability of the Gabor coefficients within the discretized model operator representing $H_{2,\vec{\g}}$, the question regarding its maximal boundedness range -- i.e., whether or not one can cover the regime $\frac{1}{2}<r\leq\frac{2}{3}$ -- remains an important open problem in the time-frequency area. For more on the latter, we invite the reader to examine Section 3.3. in \cite{HL23} and in particular Observation 3.3. therein.
\end{itemize}     
\end{rem}





\noindent\underline{\textbf{II.2) The case $n=2$, non-zero curvature.}} $\quad$ For the first class \eqref{nhilBHCarl} this line of research was motivated both by the maximal singular oscillatory integral study revealed at Case $n=1$ and, more importantly, by the study of singular/maximal oscillatory integral operators on Heisenberg groups (where one has an unisotropic behavior). E. Stein, \cite{s2}, proved the $L^2$ boundedness of \eqref{nhilBHCarl} in the regime $\underline{\g}_1(t)=t$ and $\g(x,t)=a(x) t^2$ while E. Stein and S. Wainger (\cite{sw}) covered the full $L^p$, $1<p<\infty$ range (and also its higher dimensional analogue) for $\underline{\g}_1(t)=t$ and $\g(x,t)=\sum_{j=2}^d a_j(x) t^j$ with $d\geq 2$. Their approach relied on the $TT^{*}-$method and Van der Corput techniques.

For the second class \eqref{nhilb} the motivation is twofold: as a curved analogue of the classical (zero curvature) Bilinear Hilbert transform and as a continuous analogue of the ergodic theoretical problem regarding the norm and pointwise convergence of Furstenberg non-conventional bilinear averages.\footnote{For more on the connections and related bibliography we invite the interested reader to consult the Introduction in \cite{Lie2024}.} In this non-zero curvature realm, the complete boundedness range for $H_{2,\vec{\g}}$ is now fully settled depending on the nature of the curves $\vec{\g}$ considered: 1) in \cite{Li13}, \cite{LX16}, this was done for monomials and polynomials, respectively, with the method of proof relying on the $\sigma$-uniformity concept introduced in \cite{cltt} and inspired by  Gowers's work in \cite{Gow98}; 2)  In \cite{Lie15}, \cite{Lie18}, \cite{GL20}, the analysis was performed on a larger class of ``non-flat" curves that included any Laurent or even generalized polynomial with no monomial of degree one with the method of proof combining two types of discretization: a Taylor approximation of second order for the phase of the multiplier that decouples the frequency variables and a suitable (non-linear) wave-packet analysis applied to the input functions.

\smallskip
\begin{rem} Based on the Rank I LGC method introduced by the third author, in \cite{Lie2024} and \cite{GL25}, a unified approach to \eqref{nhilBHCarl} and \eqref{nhilb} in the non-zero case was offered thus creating the link between these two cases. Another result establishing an implicit relation between \eqref{nhilBHCarl} and \eqref{nhilb} in the particular setting $\g_1(t)=\underline{\g}_1(t)=t$, $\g_2(t)=t^2$ and $\g(x.t)=a(x) t^2$  was presented in \cite{DR22} relying on Gowers uniformity norms.
\end{rem}


\noindent\underline{\textbf{II.3) The case $n=2$, hybrid curvature.}} \quad For the first class \eqref{nhilBHCarl} this situation arises as a natural symbiosis between the zero curvature case covering the celebrated theorem of Carleson and the non-zero curvature situation encompassing the previously mentioned results in \cite{s2} and \cite{sw}. In the latter, E. Stein conjectures that the Polynomial Carleson operator $C_{1,\G}$ with $\g(x,t)=\sum_{j=1}^d a_j(x) t^j$ is of strong type $(p,p)$ for $1<p<\infty$. The relevance of this theme goes much beyond the synthesis character mentioned above: indeed, the Polynomial Carleson operator is the first example considered in the literature of a linear operator that is invariant under higher order modulations, thus requiring a higher-order wave-packet analysis. In \cite{lv1}, \cite{Lie20} the third author answered in the affirmative this conjecture by developing  a new time-frequency framework for higher-order wave packets, a tile selection algorithm that removed the presence of exceptional sets as well as novel local analysis adapted to the mass and tree selection algorithms. It is worth noticing that this result remains to date the only treatment of an operator obeying higher order modulation invariance. Finally, further elaboration on these ideas produced higher dimensional analogues, see \cite{zk1}, \cite{lv3n} and more recently \cite{BDJST}.

For the second class \eqref{nhilb}, the motivation for considering the hybrid curvature case resides on the desire of better understanding the subtle phenomenon that governs the transition from the zero to non-zero curvature. In order to understand this theme one is expected to combine both the approaches used at items II.1) and II.2) above. Indeed, in \cite{GL25}, the authors therein employed the Rank I LGC method in order to obtain the boundedness of $H_{2,\vec{\g}}$ in the hybrid setting $\g_1(t)=t$ and $\g_2(t)=at +b t^{\alpha}$ for $a\in\R\setminus\{1\}$, $b\in\R$ and $\alpha\in(0,\infty)\setminus\{1,2\}$.

\begin{rem} A noteworthy fact in the hybrid case context of \eqref{nhilb} is that the Rank I LGC method fails in the parabola case $\g_2(t)=at +b t^{2}$, hence the necessary restriction $\a\not=2$. This is a fundamental, conceptual obstruction transcending technical issues which is closely related to the similar phenomenon that happens in the case of the Polynomial Carleson operator where using a linear wave-packets analysis only works as long as the  polynomial phase does not contain quadratic monomials in $t$. This latter aspect corresponds precisely to the situation when the operator under analysis lacks quadratic/higher order modulation invariance structure. 
%However, in a very recent development, \cite{lv25}, the third author provides the resolution of $H_{2,\vec{\g}}$ in the parabola case by involving---for the first time in the multilinear setting---quadratic wave-packet analysis---in accordance with the \emph{quadratic quasi-resonance} character of this problem as revealed in \cite{GL25}. 
\end{rem}


\begin{rem} In the same \cite{GL25} the authors therein provide a unified approach to both \eqref{nhilBHCarl} and \eqref{nhilb} in the case of hybrid curves with no quadratic (quasi-)resonances thus re-confirming the intimate connection between the two classes of operators under discussion.
\end{rem}


\begin{obs} 
The jump from $n=2$ to $n\geq 3$ poses key difficulties in all the curvature regimes and until very recently no results existed even in the (purely) non-zero curvature case. Also, from now on, the reference to the hybrid curvature situation is adjusted (relaxed) to refer to a generic situation that covers both zero and non-zero curvature features without necessarily including the full zero-curvature realm.
\end{obs}

\noindent\underline{\textbf{III.1) The case $n=3$, (purely) zero curvature.}} \quad This addresses the case when in \eqref{nhilBHCarl} we take $\underline{\g}_1(t)=-t$,  $\underline{\g}_2(t)=t$ and $\g(x,t)=a(x) t$ with $a(\cdot)$ measurable. In this situation we refer to $C_{2,\G}$ as the purely resonant Bilinear Hilbert-Carleson operator since it naturally extends both the classical Bilinear Hilbert transform and the Carleson operator (with both these in the zero-curvature setting).

The motivation for considering this operator is multifaceted: 1) it is directly connected with the problem of the pointwise convergence of Fourier series in the bilinear setting; 2) it is related with the bilinear version of Rubio de Francia operator associated with arbitrary strips; 3) it belongs to the class of (multi-linear) operators that are both linear and quadratic modulation invariant and for which---as mentioned earlier---with the notable exception of the Polynomial Carleson operator discussed in II.3), we lack a good understanding. For more details on all these items the reader is invited to consult the extended Introduction in \cite{BBLV24}.

For the class represented by \eqref{nhilb}, this case corresponds to the situation when $\g_j(t)= a_j t$ and $\{a_j\}_{j=1}^3\subset\R\setminus\{0\}$ pairwise distinct; this way, $H_{3,\vec{\g}}$ represents the celebrated classical Trilinear Hilbert transform whose $L^p$-boundedness remains a major open question in harmonic analysis. In terms of motivation, this problem has deep ramifications in an array of mathematical areas: 1) on the analytic number theory/additive combinatorics side, $H_{3,\vec{\g}}$ is connected with the theme of counting additive patterns in subsets of $\Z$ in the spirit of Roth's and Szemer\'edi's theorems (\cite{Sze69}, \cite{Sze75}) and later Gowers, \cite{Gow98}; other connections between the study of $H_{3,\vec{\g}}$ and additive combinatorics appears in \cite{Chr01}; 2) on the ergodic theory side, the study of $H_{3,\vec{\g}}$  relates to the behavior of suitable Furstenberg non-conventional averages (see \emph{e.g.} \cite{FW96}, \cite{HK05}, \cite{Zieg07}, \cite{Leib05a}) as well as to the pointwise convergence of bilinear Birkhoff averages for two commuting measure-preserving transformations (\cite{DKST19}); 3) on the time-frequency/classical harmonic analysis side, $H_{3,\vec{\g}}$ exhibits linear and quadratic modulation invariance and is part of a natural hierarchy of objects extending the bilinear Hilbert transform and also further related to the triangular Hilbert transform (\cite{KTZ}).

\begin{rem} 
The problems of studying the $L^p-$boundedness properties for both operators \eqref{nhilBHCarl} and  \eqref{nhilb}  in the zero curvature setting and $n=3$ are widely open with no positive results known to date. A fundamental difficulty in approaching either of these problems is the---yet---poor understanding of the higher order modulation invariance feature.
\end{rem}


\noindent\underline{\textbf{III.2) The case $n=3$, (purely) non-zero curvature.}} \quad For the class in \eqref{nhilBHCarl} this case corresponds to the generic situation $\underline{\g}_1(t)=a_1 t^{\a_1}$, $\underline{\g}_2(t)=a_2 t^{\a_2}$ and $\g(x,t)=a(x) t^{\a_3}$ with $\{a_j\}_{j=1}^3\subset\R\setminus\{0\}$ and $\{\a_j\}_{j=1}^3\subset\R\setminus\{0\}$ pairwise distinct. In this situation we refer to $C_{2,\G}$ as the purely non-resonant Bilinear Hilbert-Carleson operator since this object has no modulation invariance structure. 

Moving to class \eqref{nhilb}, this covers the situation $\underline{\g}_j(t)=a_j t^{\a_j}$, $1\leq j\leq 3$, with $H_{3,\vec{\g}}$ representing now the curved trilinear Hilbert transform.

The motivation for considering the purely curved situation for both \eqref{nhilBHCarl} and \eqref{nhilb} arises from multiple directions\footnote{For more on these we invite the interested reader to consult the introduction in \cite{HL23}.}: 
\begin{enumerate}
\item these problems can be considered as natural models for the very difficult but fundamental open problems corresponding to the zero curvature setting and discussed at point III.1; 
\item they have connections with number theory/additive combinatorics, specifically with the question of identifying qualitative and/or quantitative conditions on a subset $S$ of $\R$ (or $\Z$) that guarantee the existence of  polynomial progressions patterns; 
\item they have connections with ergodic theory area: in particular, the purely curved case of \eqref{nhilb} may be regarded as a singular Euclidean extension of the ergodic theoretical problem regarding the norm and pointwise convergence behavior of the Furstenberg non-conventional polynomial averages.
\end{enumerate}     
\begin{rem} 
The non-zero curvature setting is the only one that is now completely settled in the $n=3$ case. Indeed we have the following:
\begin{itemize}
\item the maximal boundedness range---up to end-points---for the purely non-resonant Bilinear Hilbert-Carleson operator  $C_{2,\G}$ is the subject of the present paper;

\item the $L^{p_1}(\R)\times L^{p_2}(\R)\times L^{p_3}(\R)$ into $L^{r}(\R)$ boundedness of $H_{3,\vec{\g}}$ within the Banach H\"older range $\frac{1}{p_1}+\frac{1}{p_2}+\frac{1}{p_3}=\frac{1}{r}$ with $1<p_1,p_3<\infty$, $1<p_2\leq \infty$ and $1\leq r <\infty$ was solved recently by the second and third authors in \cite{HL23}. The extension to the quasi-Banach range corresponding to $r>\frac{1}{2}$ is dealt with in the follow up paper \cite{HL24}. Whether or not the latter constitutes the maximal boundedness range of $H_{3,\vec{\g}}$ seems to be a subtle open problem with additive combinatorics flavor.
\end{itemize}
\end{rem}

\begin{rem}\label{lgcIImeth} The resolution of both $C_{2,\G}$ and $H_{3,\vec{\g}}$ in this non-zero curvature setting relies in a crucial manner on the newly developed Rank II LGC method introduced in \cite{HL23}. Indeed, as already noticed in Remark \ref{Gen1}, a key difficulty in approaching both these problems was the lack of absolute summability for the associated linearized discretized models (and hence the failure of Rank I LGC method).  
\end{rem}


\begin{rem}\label{ConIII2} Reinforcing the philosophy stated at the beginning of our section and shaped throughout our previous remarks, the present case offers another instance of the deep connections between the two classes of operators \eqref{nhilBHCarl} and \eqref{nhilb}, respectively. Indeed, a crucial ingredient in the treatment of $H_{3,\vec{\g}}$ is a good understanding---though only within a partial range of the spatial and frequency parameters\footnote{\emph{I.e.} $k$ and $m$ respectively - see Remark \ref{twoway} and, more generally, Section \ref{Planmainideas}.}---of the main component of the maximal operator $C_{2,\G}$. The latter is achieved via a novel procedure that we refer to as ``\emph{constancy propagation}" of the linearizing function $a(x)$ which relies on a bootstrap argument resembling an induction on scale reasoning and involving the structure of the phase $a(x)$ in the definition of $\g(x,t)$ as part of $C_{2,\G}$. Thus, in a nutshell, our approach of $H_{3,\vec{\g}}$ \emph{requires} in first place a good understanding of $C_{2,\G}$, with the latter becoming a natural companion to the former object. The role of the present paper is to complete this companionship initiated with the study of $H_{3,\vec{\g}}$ in \cite{HL23} and provide the full understanding of the boundedness properties of $C_{2,\G}$, in particular covering all the possible range for the spatial and frequency parameters.
\end{rem}



\begin{rem}\label{Pel} The methods developed in \cite{HL23} and here have a great potential for further extensions and/or generalizations. Indeed, one such natural direction of investigation regards the key results involving local smoothing inequalities proved in \cite{KMPW2024a} and \cite{KMPW2024b}. These results rely on the so-called PET induction scheme developed by Bergelson and Leibman in \cite{BL96}, a powerful method  which---in the context described above---however, faces two key restrictions: 1) it only applies to curves described by suitable polynomials (corresponding in our case to the restriction $\{\a_j\}_{j=1}^3\subset\N$ pairwise distinct), and, 2) it only applies to large physical scales (corresponding in our case, in either \eqref{nhilBHCarl} or \eqref{nhilb}, to enforcing $|t|>>1$).  However, the flexibility of our methodology overcomes both these obstacles supporting thus our initial claim.  
\end{rem}


\noindent\underline{\textbf{III.3) The case $n=3$, hybrid curvature.}} \quad  A typical situation addressing this case is $\underline{\g}_1(t)=a_1 t$, $\underline{\g}_2(t)=a_2 t$ and $\g(x,t)=a(x) t^{\a_3}$ or $\underline{\g}_3(t)=a_3 t^{\a_3}$ depending on whether we refer to \eqref{nhilBHCarl} or  \eqref{nhilb}, respectively. Of course, as usual. we require $\{a_j\}_{j=1}^3\subset\R\setminus\{0\}$ with $a_1,\,a_2$ pairwise distinct and $\a_3\in\R\setminus\{0,1,2\}$. In this situation both $C_{2,\G}$ and $H_{3,\vec{\g}}$ are linear modulation invariant while they also exhibit non-zero curvature features---hence the \emph{hybrid} curvature character. The condition $\a_3\not=2$ is imposed in order for these operators to have \emph{only} linear but \emph{no} quadratic modulation invariance features, with the latter instance being a next level, critical step in the major enterprise of tackling the purely zero curvature case described at item III.1).

The motivation for studying these problems is shared with the one described at  III.2). Moreover this case is a natural link between Cases III.2) and III.1): indeed, approaching Case III.3 requires the knowledge accumulated from Case III.2) and is required in order to have a better understanding of the difficulties arising when dealing with Case III.1).


\begin{rem} While not completely settled, we believe that soon we will be able to fully understand the hybrid no-quadratic resonance case. Indeed, we have the following:
\begin{itemize}
\item the hybrid Bilinear Hilbert Carleson operator $C_{2,\G}$ in the above setting was studied in \cite{BBLV24}, where the authors therein proved that  $C_{2,\G}$ is bounded from $L^{p_1}(\R)\times L^{p_2}(\R)$ into $L^{r}(\R)$ for $\frac{1}{p_1}+\frac{1}{p_2}=\frac{1}{r}$ with $1<p_1,p_3\leq \infty$ and $\frac{2}{3} < r <\infty$ thus in particular extending the work of M. Lacey and C. Thiele, \cite{lt1}, \cite{lt2}, on the classical (zero-curvature) Bilinear Hilbert transform;

\item the hybrid trilinear Hilbert transform $H_{3,\vec{\g}}$ in a closely related setting with the one above is the subject of an ongoing study in \cite{BBL25}. 
\end{itemize}
Both these works are crucially relying on Rank II LGC (in particular their discretized linear wave-packet models fail to be absolutely summable) at which---in contrast with case III.2)---one now adds modulation invariance/multiresolution analysis techniques. 
\end{rem}


\begin{rem}\label{ConIII3}  Mirroring Remark \ref{ConIII2}, the hybrid case reconfirms once again the intimate link between \eqref{nhilBHCarl} and \eqref{nhilb}: the analysis of $H_{3,\vec{\g}}$ encapsulates as a prerequisite a good understanding of the maximal operator $C_{2,\G}$ that is further conditioned by the elements within the itemized list in Remark \ref{Gen1} and in particular by the local structure of the linearizing phase function $a(x)$ in the definition of $C_{2,\G}$.
\end{rem}


\noindent\underline{\textbf{IV) The general case $n\geq 4$.}} \quad Of course, as expected, this general case presents itself with multiple challenges that are yet to be understood. As before, one can create a natural hierarchy in an increasing order of difficulty from non-zero, hybrid to zero curvature. While the latter two cases are---in full generality---beyond reach as of now, for the former case substantial progress has been made. Indeed, the purely curved case addressing  $H_{n,\vec{\g}}$ in the general setting $\g_j(t)=a_j t^{\a_j}$ with  $\{a_j\}_{j=1}^n\subset\R\setminus\{0\}$ and $\{\a_j\}_{j=1}^n\subset\R\setminus\{0\}$ pairwise distinct as well as $C_{n-1,\vec{\G}}$ with the obvious modifications is the subject of an ongoing investigation in \cite{HL25} revealing yet again the intimate connection between \eqref{nhilb} and  \eqref{nhilBHCarl}. Moreover, the Hardy-Littlewood maximal analogue of \eqref{nhilb} has already been settled in the purely curved case and general $n$ in \cite{HL24}, 




















\subsection{Plan of the proof; main ideas}\label{Planmainideas}


In this section we provide
\begin{itemize}
\item (A) an outline of the structure of our paper;

\item (B) a brief description of some of the most relevant ideas.
\end{itemize}

We start our discussion with item (A): first the versatility\footnote{See also Remark \ref{Pel}.} of our methods allows us to treat with minimal effort any nonresonant choice of $\vec{\a}$ (see the hypothesis in Main Theorem \ref{mainresult}) once we have designed the strategy for a particular, representative choice. For this reason, it is enough to only focus on a special case of \eqref{BHCcurval1}, denoted by  
\begin{equation}\label{bhcdef}
BHC(f_1, f_2)(x):=\sup_{\lambda \in \R} \left|\, \textrm{p.v.} \int_\R f_1(x-t)f_2(x+t^2)e^{i\lambda t^3} \frac{dt}{t} \right|\,.
\end{equation}
In Section \ref{PrelDec}, we perform a preliminary discretization of $BHC$ depending on two type-parameters:
\begin{itemize}
\item a spatial parameter $k\in\Z$ accounting for the spatial scale of the kernel/multiplier;

\item a frequency parameter triple $(j,l,m)\in\Z^3$ accounting for the magnitude of the Fourier supports of the input functions $f_1$, $f_2$ and of the linearizing phase $\lambda(x)$, respectively. 
\end{itemize}
Next, depending on the suitable interdependencies between $k,j,l,m$ which govern the behaviour of the phase of the multiplier, and, in particular, the presence/absence of stationary points, we subdivide our operator into three key components:
$$BHC\leq BHC^{Lo}+BHC^{\not \Delta}+BHC^{\Delta}\,,$$
with the middle component further subdivided as
$$BHC^{\not \Delta}\leq BHC^{\not \Delta, S}+BHC^{\not \Delta, NS}\,,$$
where here $BHC^{Lo}$ stands for the low oscillatory component, the high oscillatory component corresponds to an on-diagonal ($BHC^{\Delta}$) and an
off-diagonal ($BHC^{\not \Delta}$) component, and finally, $BHC^{\not \Delta}$ encompasses a high frequency off-diagonal \emph{stationary} component $BHC^{\not \Delta, S}$ and a high frequency off-diagonal \emph{non-stationary} component $BHC^{\not \Delta, NS}$.

Withe these, our approach develops as follows\footnote{For convenience, all the analysis below---except for the one in the Appendix---is performed in the regime $k\geq0$.}:
\begin{itemize}
\item $BHC^{\not \Delta, NS}$ and $BHC^{Lo}$ are relatively easy to control, task which can be accomplished independent of the behavior of the other components: the former is treated in Section \ref{20250228sec01}---see Proposition \ref{20250317prop01}, while the latter is handled in Section \ref{20250228sec02}---see Theorem \ref{thmin};
\item as expected, the main difficulties and ideas reside in the local $L^2$ smoothing estimate for the diagonal component $BHC^{\Delta}$---see Section \ref{Mainsect} and in particular Theorem \ref{20241018mainthm01} therein; 
\item the local $L^2$ resolution of the high frequency off-diagonal \emph{stationary} component $BHC^{\not \Delta, S}$ relies on a skillful adaptation of the ideas employed for treating the main term $BHC^{\Delta}$; the required argumentation is presented in Section \ref{20250308sec01}---see Theorem \ref{generalizedmain};
\item finally, the maximal quasi-Banach boundednees range (up to end-points) of $BHC$ is completed in Section \ref{20250309sec01} while in the Appendix we provide a brief sketch of the modifications required in order to deal with the situation when $k<0$.         
\end{itemize}


We now move our focus on item (B): As expected, the crux of our entire work resides on obtaining the local $L^2$ smoothing control on the diagonal component $BHC^{\Delta}$ with the latter representing (essentially) the regime $j=l=m\in\N$ which corresponds to the main situation when the phase of the multiplier admits stationary points. The main result captured within Theorem \ref{20241018mainthm01} can be essentially included within the following:
$\newline$

\noindent\textbf{Main Proposition (informal).} [\textsf{$L^2$-smoothing control on the maximal joint Fourier coefficient}]\quad \emph{Let $r\in\Z$, $k,\,m\in\N$ and set 
$I_r^k=[r 2^{-k}, (r+1) 2^{-k}]$ and $I^k\equiv I_1^k$. Assume $f_1,\,f_2\in L^2(\R)$ such that $\textrm{supp}\, \widehat{f}_1\subseteq [2^{m+k}, 2^{m+k+1}]$ and  $\textrm{supp}\, \widehat{f}_2\subseteq [2^{m+2k}, 2^{m+2k+1}]$. Define now the $(m,k)$--\emph{maximal joint Fourier coefficient} of the pair $(f_1,f_2)$ along the moment curve $(t,t^2,t^3)$ as 
\begin{equation} \label{maxjointFourcoeff}
 \mathcal{J}_{m, k}(f_1, f_2)(x):=\sup_{\lambda\in\R}\,\frac{1}{|I^k|^{\frac{1}{2}}}\,\left|\int_{I^k} f_1(x-t)\,f_2(x+t^2)\,e^{i \lambda t^3} dt \right|\,.
\end{equation} 
Then, there exists $\ep>0$ absolute constant such that for any $r\in\Z$, one has
\begin{equation} \label{maxjointFourcoeffcontr}
\left\|\mathcal{J}_{m, k}(f_1, f_2)(\cdot)\right\|_{L^2(I_r^k)}\lesssim   2^{-\epsilon \min \{2 k, m\}}\,\|f_1\|_{L^2(3I_r^k)}\, \|f_2\|_{L^2(3 I_r^k)}\,.
\end{equation}}

\smallskip
We next elaborate on some of the main ideas involved in the proof of the above statement. The first simple observation based on some standard reasonings is that we only need to show \eqref{maxjointFourcoeffcontr} for $r=1$ and hence we may assume from now on that $x\in I^k$. Next, by exploiting the hypothesis in the Main Proposition, a linearization procedure reduce matters to the following situation: 
\smallskip

\begin{equation} \label{maxjointFourcoeff1}
 \mathcal{J}_{m, k}(f_1, f_2)(x)\approx \frac{1}{|I^k|^{\frac{1}{2}}}\,\left|\int_{I^k} f_1(x-t)\,f_2(x+t^2)\,e^{i 2^{\frac{m}{2}+3k} \widetilde{\lambda}(x) t^3} dt \right|\,,
\end{equation} 
with 
\begin{equation} \label{constlam}
\widetilde{\lambda}: I^k \to \left[2^{\frac{m}{2}}, 2^{\frac{m}{2}+1} \right]\quad\textsf{measurable, constant on intervals of length}\:\:2^{-m-2k}\,.
\end{equation} 
\smallskip

Building on the work in \cite{HL23}, the key contribution  of this paper is to unravel the subtle relationship between the \emph{structure} of the linearizing phase function $\widetilde{\lambda}$ and the \emph{nature} of the method employed in the resolution of \eqref{maxjointFourcoeffcontr}. More precisely, we have the following philosophical dichotomy:
\begin{itemize}
\item on the one hand, if $\widetilde{\lambda}$ is ``slowly" varying, \emph{e.g.} $\widetilde{\lambda}$ is constant on $ I^k$, then one can apply the Rank I LGC method having as a result a wave-packet discretizated model of \eqref{maxjointFourcoeff1} which can be controlled via absolute values in order to obtain the desired estimate in \eqref{maxjointFourcoeffcontr}.

\item on the other hand, if  $\widetilde{\lambda}$ is ``widely" varying within the context of \eqref{constlam}, then Rank I LGC method fails\footnote{\emph{I.e.}, the resulting discretized wave-packet model does not produce the required $ 2^{-\epsilon \min \{2 k, m\}}$-decay if the absolute values are applied over the local Fourier coefficients corresponding to $f_1$ and $f_2$.} and one has to appeal to the \emph{correlative} nature of the Rank II LGC method.
\end{itemize}

The main ingredient which reveals and allows us to exploit the above dichotomy is the \emph{constancy propagation} procedure introduced in \cite{HL23} and further refined here. As the name suggests, this procedure resembling an induction on scale mechanism allows us to move from a smaller constancy scale to a  larger one by exploiting different cancellation phenomena within the structure of our operator.

With these being said, we are ready to provide more content to our story: the constancy propagation procedure can not be performed \emph{pointwise}, directly on the expression \eqref{maxjointFourcoeff1}, but rather on a majorant of its $L^2$ $x$-average; more precisely, employing a spatial sparse-uniform dichotomy corresponding to the first stage of item (1) in Remark \ref{Gen1}, one reduces matters to the situation when both $f_1$ and $f_2$ are \emph{spatially} uniformly distributed. Once here, we apply a partition of the $t$-integration domain at the level of the \emph{linearizing} scale, \emph{i.e.} we write $I^k=\bigcup_{q\sim 2^{\frac{m}{2}}}I_q^{m, k} $  where here  $I_q^{m, k}:=\left[ \frac{q}{2^{\frac{m}{2}+k}}, \frac{q+1}{2^{\frac{m}{2}+k}}   \right]$ noticing that for $t\in I_q^{m, k}$ we have $2^{\frac{m}{2}+3k}\,\widetilde{\lambda}(x)\,t^3= -2 \cdot \frac{q^3 \lambda(x)}{2^{\frac{3m}{2}+3k}}\,+\,3 \cdot \frac{q^2 \lambda(x)}{2^{m+2k}}\,t\,+\,O(1)$, and, after some standard reasonings, we obtain 
\begin{eqnarray} \label{dom}
&& \:\:\:\:\:\: \qquad\qquad\qquad\qquad\qquad\left\|\mathcal{J}_{m, k}(f_1, f_2)(\cdot)\right\|_{L^2(I^k)}^2 \lesssim \nonumber  \\
&&\left[{\calL}_{m, k}(f_1, f_2) \right]^2 \ :=  2^{\frac{m}{2}+k} \cdot  \int_{I^k} \left( \sum_{q \sim 2^{\frac{m}{2}}} \left| \int_{I_q^{m, k}} f_1(x-t)f_2(x+t^2) e^{3i2^k \cdot \frac{q^2 \widetilde{\lambda}(x)}{2^{\frac{m}{2}}}t} dt\right|^2 \right)dx.
\end{eqnarray} 

It is on this latter expression that our constancy propagation applies.  Specifically, our analysis splits in two major cases:

\medskip 

\noindent \underline{\textsf{Case I: $k \ge \frac{m}{2}$.}} \quad In this case, the corner stone is represented by the proof of the following:
\smallskip

\begin{prop} (\cite[Theorem 4.3]{HL23}, \textsf{Informal statement})\label{maxjointctrl} If $k\geq \frac{m}{2}$, $f_1$, $f_2$  spatially uniformly distributed, and 
\begin{equation} \label{constlam1}
\widetilde{\lambda}: I^k \to \left[2^{\frac{m}{2}}, 2^{\frac{m}{2}+1} \right]\quad\textsf{measurable, constant on intervals of length}\:\:2^{-3k}\,,
\end{equation} 
then there exists $\ep>0$ absolute constant such that the expression ${\calL}_{m, k}(f_1, f_2)$ defined in \eqref{dom} obeys
\begin{equation} \label{maxjointFourcoeffcontr1}
{\calL}_{m, k}(f_1, f_2) \lesssim   2^{-\epsilon m}\,\|f_1\|_{L^2(3I^k)}\, \|f_2\|_{L^2(3 I^k)}\,.
\end{equation}
\end{prop}
\smallskip

\begin{rem}\label{twoway}  Proposition \ref{maxjointctrl} is a concrete embodiment of the deep connection between \eqref{BHCcurval} and \eqref{ThTcurval} claimed at the beginning of our Introduction. Indeed
\begin{itemize}
\item on the one hand,  Proposition \ref{maxjointctrl}---in the form of Theorem 4.3---is a key ingredient in \cite{HL23} for obtaining the $L^p$-boundedness of \eqref{ThTcurval1}; 

\item on the other hand, as revealed by \eqref{maxjointFourcoeffcontr}, \eqref{dom} and \eqref{maxjointFourcoeffcontr1},  Proposition \ref{maxjointctrl} captures exactly the desired smoothing estimate for the main component of \eqref{BHCcurval1} in the regime $k\geq m$.  
\end{itemize}
\end{rem}

Once here, our analysis further splits in two regimes:
\begin{enumerate}
    \item [$\bullet$]  \underline{\textsf{Case I.1: $k \ge m$.}} \quad In this situation, we simply notice that $2^{-m-2k}\geq 2^{-3k}$ and hence \eqref{constlam} implies \eqref{constlam1}. Consequently our Main Proposition is a direct corollary of Proposition \ref{maxjointctrl}.
\smallskip        

    \item [$\bullet$]  \underline{\textsf{Case I.2: $\frac{m}{2} \le k \le m$.}}\quad  In this situation, we follow a two-step approach: 
\medskip    
 \begin{itemize}   
    \item \underline{\textsf{Step I.2.1:}} We first implement the constancy propagation procedure in order to extend the constancy of $\widetilde{\lambda}$ from intervals of length $2^{-m-2k}$ to intervals of length $2^{-m-k}$ (see Section \ref{20241028subsec01}). 
\smallskip    
    \item \underline{\textsf{Step I.2.2:}} Once we reach the scale $2^{-m-k}$, we notice that in our regime $2^{-m-k} \ge 2^{-3k}$, and hence,  Proposition \ref{maxjointctrl} applies once again.
 \end{itemize}   
\end{enumerate}

\medskip

\noindent \underline{\textsf{Case II: $0 \le k \le \frac{m}{2}$.}} In this case there is no stratagem that allows us to reduce matters to  Proposition \ref{maxjointctrl}; in particular, we notice that in the present setting, in contrast with \eqref{maxjointFourcoeffcontr1},  the decaying factor in \eqref{maxjointFourcoeffcontr} takes the form $2^{-\epsilon k}$. Thus, our strategy develops now as follows:
\smallskip
\begin{itemize}
\item \underline{\textsf{Step II.1:}} As at the Step I.2.1, requiring though a slightly different point of view, we apply the constancy propagation procedure in order to extend the constancy of $\widetilde{\lambda}$ from intervals of length $2^{-m-2k}$ to intervals of length $2^{-m-k}$ (see Proposition \ref{20241018prop01}, Section \ref{20241217subsec01}).
\smallskip

\item \underline{\textsf{Step II.2:}} Once we reach the $2^{-m-k}-$constancy scale for  $\widetilde{\lambda}$, we return to the original form \eqref{maxjointFourcoeff1} and apply to it the Rank I LGC method in order to obtain \eqref{maxjointFourcoeffcontr} (see Section \ref{20250228sec03}). 
\end{itemize}
\smallskip

\noindent We end this section with the following 

\begin{rem}\label{twoway1} While the constancy propagation procedure is a key ingredient in the resolution of  
\begin{itemize}
\item \emph{i)} on the one hand, Proposition \ref{maxjointctrl}, and, 

\item \emph{ii)} on the other hand, Step I.2.1 and Step II.1, 
\end{itemize}
there are some relevant distinctions in the way in which this procedure is implemented: Indeed, in the former situation the analysis is performed at the level of each $x-$interval having the $x-$relevant scale $2^{-2k}$ (see Proposition 4.7 in \cite{HL23}) while in the latter situation a successful analysis requires a grouping/concatenation of $2^{m-k}$ $x-$intervals having the $x-$relevant scale $2^{-m-k}$ (see Sections \ref{20250228sec03} and \ref{20241028subsec01}).  
\end{rem}

