\section{Set-up for the problem: preliminaries}\label{PrelDec}

For notational simplicity and clarity of the exposition, throughout the reminder of the paper we set $\vec{a}=(1,-1,1)$, $\vec{\a}=(1,2,3)$ and focus only on the corresponding $BHC_{[\vec{a},\vec{\a}]}$ which for convenience will be referred from now on as $BHC$. With these, the goal of our paper is to analyze the boundedness behavior of the \emph{(purely) non-resonant bilinear Hilbert Carleson}:
$$
BHC(f_1, f_2)(x):=\sup_{\lambda \in \R} \left|\, \textrm{p.v.} \int_\R f_1(x-t)f_2(x+t^2)e^{i\lambda t^3} \frac{dt}{t} \right|, 
$$
whose multiplier form is given by
$$
BHC(f_1, f_2)(x)= \sup_{\lambda \in \R} \left| \int_{\R} \widehat{f_1}(\xi) \widehat{f_2}(\eta) \frakm_\lambda(\xi, \eta) e^{i\xi x} e^{i \eta x} d\xi d\eta \right|,
$$
with
$$
\frakm_{\lambda}(\xi, \eta):=\, \textrm{p.v.} \int_{\R} e^{-i\xi t} e^{i \eta t^2} e^{i \lambda t^3} \frac{dt}{t}. 
$$
\subsection{Discretization of the multiplier}
As usual in such circumstances, we proceed with a two-layer decomposition, as follows:

\subsubsection{A physical discretization} Let $\rho \in C_0^\infty(\R)$ be an odd function with $\textrm{supp}\,\rho \subseteq \left[-4, 4 \right] \backslash \left[-\frac{1}{4}, \frac{1}{4} \right]$ which, for $\rho_k(t):=2^k \rho(2^k t)$, satisfies 
$$
\frac{1}{t}=\sum_{k \in \Z} \rho_k(t)\,\qquad\textrm{for all}\:\:t\in\R\setminus\{0\}\,.
$$
This yields a first decomposition 
$$
BHC(f_1, f_2)(x)=\sup_{\lambda \in \R} \left| \sum_{k \in \Z} BHC_{\lambda}^k(f_1, f_2)(x) \right|, 
$$
where for each $\lambda \in \R$, 
$$
BHC_{\lambda}^k(f_1, f_2)(x):=\int_{\R^2} \widehat{f_1}(\xi) \widehat{f_2}(\eta) \frakm^k_{\lambda}(\xi, \eta) e^{i\xi x} e^{i \eta x} d\xi d\eta, 
$$
with
$$
\frakm_{\lambda}^k(\xi, \eta):=\int_{\R} e^{-i \frac{\xi}{2^k} t} e^{i \frac{\eta}{2^{2k}} t^2} e^{i \frac{\lambda}{2^{3k}}t^3} \rho(t)dt.  
$$



\subsubsection{A frequency discretization} 
Since the derivative of the phase function plays a fundamental role in the behavior of such integral operators, it is natural to start this section with a basic \emph{phase analysis}:
\begin{itemize}
\item for $k\in\Z$, we denote by
$$
\varphi_{\xi, \eta, \lambda}^k(t):=-\frac{\xi}{2^k}t+\frac{\eta}{2^{2k}}t^2+\frac{\lambda}{2^{3k}}t^3
$$ 
and notice that
\begin{equation} \label{20240407eq01}
\frac{d}{dt} \varphi_{\xi, \eta, \lambda}^k(t)=-\frac{\xi}{2^k}+\frac{2\eta}{2^{2k}}t+\frac{3\lambda}{2^{3k}}t^2, 
\end{equation} 
\begin{equation} \label{20240407eq02}
\frac{d^2}{dt^2} \varphi_{\xi, \eta, \lambda}^k(t)=\frac{2\eta}{2^{2k}}+\frac{6\lambda}{2^{3k}}t,
\end{equation} 
and
\begin{equation} \label{20240407eq03}
\frac{d^3}{dt^3} \varphi_{\xi, \eta, \lambda}^k(t)=\frac{6\lambda}{2^{3k}}\,;
\end{equation} 

\item next, setting $t_0$ the unique root of $\frac{d^2}{dt^2} \varphi_{\xi, \eta, \lambda}^k$, we have 
\begin{equation} \label{20240407eq05}
t_0:=-\frac{2^k \eta}{3 \lambda} \qquad \textrm{and} \qquad \frac{d^2}{dt^2} \varphi_{\xi, \eta, \lambda}^k (t_0)=0;
\end{equation} 

\item denting the discriminant associated with \eqref{20240407eq01} by 
\begin{equation} \label{20240407eq04}
\Delta:=\frac{\eta^2+3\lambda\xi}{2^{4k}}\,,
\end{equation} 
and using \eqref{20240407eq04} and \eqref{20240407eq05}, one can rewrite $\frac{d}{dt} \varphi_{\xi, \eta, \lambda}^k$ as
$$
\frac{d}{dt} \varphi_{\xi, \eta, \lambda}^k(t)=\frac{3 \lambda}{2^{3k}} \left[(t-t_0)^2-\left(\frac{2^{3k}}{3\lambda} \right)^2 \Delta \right], 
$$
and hence
$$
\frac{d}{dt} \varphi_{\xi, \eta, \lambda}^k(t_0)=-\frac{2^{3k}}{3\lambda} \Delta\,;
$$ 

\item finally, when $\Delta \ge 0$ we denote by $t_1, t_2$ the roots of the equations $\frac{d}{dt} \varphi_{\xi, \eta, \lambda}^k(t)=0$, and notice that
$$
t_{1, 2}=-\frac{2^k \eta}{3\lambda} \pm \frac{2^{3k} \sqrt{\Delta}}{3 \lambda}
$$
with
$$
\left|t_1-t_0 \right|= \left|t_2-t_0 \right|=\frac{2^{3k} \sqrt{\Delta}}{3 \left| \lambda \right|}. 
$$
\end{itemize}

With these done, having in mind the size of the $t-$coefficients in \eqref{20240407eq01}, we let $\phi_1$ and $\phi_2$ be some even and positive functions with $\supp \ \phi_{1, 2} \subseteq \left [-4, 4 \right] \backslash  \left[-\frac{1}{4}, \frac{1}{4} \right]$, which satisfy the partition of unity 
$$
1=\sum_{j, l \in \Z} \phi_1 \left(\frac{\xi}{2^{j+k}} \right) \phi_1 \left(\frac{\eta}{2^{l+2k}} \right) \qquad \textrm{and} \qquad 1=\sum_{m \in \Z} \phi_2 \left(\frac{\lambda}{2^{m+3k}} \right),
$$
respectively. Finally, for every $j, k, l, m \in \Z$, we let
$$
\frakm_{j, l, m, \lambda}^k \left(\xi, \eta \right):=\left(\int_{\R} e^{i\varphi_{\xi, \eta, \lambda}^k(t)} \rho(t) dt\right)  \phi_1 \left(\frac{\xi}{2^{j+k}} \right) \phi_1 \left(\frac{\eta}{2^{l+2k}} \right) \phi_2 \left(\frac{\lambda}{2^{m+3k}} \right),
$$
thus obtaining the decomposition 
$$
BHC(f_1, f_2)(x)=\sup_{\lambda \in \R} \left| \sum_{k \in \Z} \sum_{j, l, m \in \Z} BHC_{j, l, m, \lambda}^k(f_1, f_2)(x) \right|\,,
$$
where $BC_{j, l, m, \lambda}^k$ is the operator induced by the multiplier $m_{j, l, m, \lambda}^k$.

\subsection{Discretization of our $BHC$ operator and basic reductions}

In this section we provide:

\begin{enumerate}
\item  The road-map for the discretization of our operator $BHC$ into three main components:
\begin{itemize}
\item a \emph{low oscillatory} component denoted by $BHC^{Lo}$;

\item a \emph{high frequency diagonal} component denoted by $BHC^{\Delta}$;

\item a \emph{high frequency off-diagonal} component denoted by $BHC^{\not \Delta}$ and further subdivided into
\begin{itemize}
\item a high frequency off-diagonal \emph{stationary} component $BHC^{\not \Delta, S}$;

\item a high frequency off-diagonal \emph{non-stationary} component $BHC^{\not \Delta, NS}$.
\end{itemize}
\end{itemize}

\item A simple and concise treatment of the latter $BHC^{\not \Delta, NS}$ component.
\end{enumerate}


\subsubsection{A preliminary discretization}
We start our decomposition as follows:
\begin{eqnarray*}
BHC(f_1, f_2)%
&\le & BHC^{Hi}(f_1, f_2)\,+\,BHC^{Lo}(f_1, f_2)  \\
& \le &  BHC_{+}^{Hi}(f_1, f_2)\,+\,BHC_{-}^{Hi}(f_1, f_2)\,+\, BHC^{Lo}(f_1, f_2)\,, 
\end{eqnarray*}
where
\begin{enumerate}
    \item [$\bullet$] the \emph{low oscillatory} component is defined by
    $$
    BHC^{Lo}(f_1, f_2)(x):=\sup_{\lambda \in \R} \left|BHC_{ \lambda}^{Lo}(f_1, f_2)(x)\right|\qquad\textrm{with}\qquad BHC_{ \lambda}^{Lo}(f_1, f_2):=\sum_{k \in \Z} \sum_{(j, l, m) \in \Z^3 \backslash \N^3}BHC_{j, l, m, \lambda}^k(f_1, f_2);
    $$
    \item [$\bullet$] the \emph{high oscillatory} component is defined by 
    $$
    BHC^{Hi}(f_1, f_2)(x):=\sup_{\lambda \in \R} \left|BHC_{\lambda}^{Hi}(f_1, f_2)(x)\right|\qquad\textrm{with}\qquad BHC_{\lambda}^{Hi}(f_1, f_2):=\sum_{k \in \Z} \sum_{(j, l, m) \in \N^3} BHC^k_{j, l, m, \lambda}(f_1, f_2), 
    $$
    and 
    $$
       BHC_{\pm}^{Hi}(f_1, f_2)(x):=\sup_{\lambda \in \R} \left|BHC_{\pm,\lambda}^{Hi}(f_1, f_2)(x)\right|\qquad\textrm{with}\qquad BHC_{\pm,\lambda}^{Hi}(f_1, f_2):=\sum_{k \in \Z_{\pm}} \sum_{(j, l, m) \in \N^3} BHC^k_{j, l, m, \lambda}(f_1, f_2).
    $$
\end{enumerate}



\subsubsection{Decomposition of the high oscillatory term into a diagonal and an off-diagonal component}
We further divide our analysis of the high oscillatory component into two different cases:
\begin{equation}\label{hifreq}
BHC^{Hi}(f_1, f_2) \le BHC^{\Delta}(f_1, f_2)\,+\,BHC^{\not \Delta}(f_1, f_2) \qquad \textrm{with}
\end{equation}
\begin{enumerate}
    \item [$\bullet$] $BHC^{\Delta}(f_1, f_2)(x):=\sup_{\lambda \in \R} \left|BHC_\lambda^{\Delta}(f_1, f_2)(x) \right|$ the \emph{diagonal} component having the frequency index range
    $$
    \max\{j, l, m\}-\min\{j, l, m\} \le 300; 
    $$
    \item [$\bullet$] $BHC^{\not \Delta}(f_1, f_2)(x):=\sup_{\lambda \in \R} \left| BHC_{\lambda}^{\not \Delta}(f_1, f_2)(x) \right|$ the \emph{diagonal} component having the frequency index range
    $$
    \max\{j, l, m\}-\min\{j, l, m\}> 300. 
    $$
\end{enumerate}
One can also define $BHC_{\pm}^{\Delta}(f_1, f_2)$ and $BHC_{\pm}^{\not \Delta}(f_1, f_2)$ in an obvious way. Moreover, with the obvious correspondences, we further subdivide the off-diagonal term as 
\begin{equation}\label{offdiag}
BHC^{\not \Delta}(f_1, f_2)\le BHC^{\not \Delta, S}(f_1, f_2)\,+\,BHC^{\not \Delta, NS}(f_1, f_2) \qquad \textrm{where}
\end{equation}
\begin{enumerate}
    \item [$\bullet$] $BHC^{\not \Delta, S}(f_1, f_2)$ stands for the \emph{stationary} off-diagonal component corresponding to the stationary phase regime, \textit{i.e.} when at least one of the roots $\{t_1, t_2\}$ has the absolute value of size $\sim 1$, or equivalently, one of the following situations is satisfied\footnote{For any $j, l \in \Z$, $j \cong l$ means $|j-l|<20$.}
    \begin{enumerate}
        \item [(a)] $j \cong l$ and $j>m+100$;
        \item [(b)] $l \cong m$ and $l>j+100$;
        \item [(c)] $m \cong j$ and $m>l+100$. 
    \end{enumerate}
    \item [$\bullet$] $BHC^{\not \Delta,NS}(f_1, f_2)$ stands for the \emph{non-stationary} off-diagonal component corresponding to the non-stationary phase regime, \textit{i.e.}, when the first item above is not satisfied. 
\end{enumerate}

\vspace{-0.1in}

\subsection{Treatment of the non-stationary off-diagonal component $BHC^{\not \Delta,NS}$}  \label{20250228sec01}

This part is routine and follows a similar reasoning with the one in \cite[Section 2.4]{HL23}. To begin with, we let $\lambda: \R \to \R$ be a measurable function such that 
 $$
BHC^{\not \Delta, NS}(f_1, f_2)(x):= \sup\limits_{\lambda \in \R} \left| BHC^{\not \Delta, NS}_{\lambda} (f_1, f_2)(x)\right| \le 2 \left| BHC^{\not \Delta, NS}_{\lambda(x)} (f_1, f_2)(x)\right|. 
 $$
We then make use of the following two results.

\begin{prop}{\cite[Lemma 2.2]{HL23}} \label{20241113prop01}
For any $(j, l, m) \in \N^3$ within the non-stationary off-diagonal regime defined above, one has 
$$
\left| \frac{d}{dt} \varphi_{\xi, \eta, \lambda(x)}^k(t) \right| \gtrsim 2^j+2^l+2^m\,\qquad \textrm{for all}\:\:\:|t| \sim 1\,.
$$
\end{prop}



\begin{prop} \label{20250317prop01}
Let $j, l, m$ and $\lambda(\cdot)$ be defined as above. Then the following estimate holds:
$$
BHC^{\not \Delta, NS}(f_1, f_2)(x) \lesssim  \sum_{j, l \ge 0} \frac{1}{2^{\max\{j, l\}}} \cdot \int_{\frac{1}{4} \le |t| \le 4} \calS_{2^j t}^{\phi_1}(x) \calS_{-2^l t^2}^{\phi_1}(x) dt,
$$
where here $\calS_t^\phi f(x):= \left( \sum\limits_{k \in \Z} \left| \left(f* \left(2^k \check{\phi} \left(2^k \cdot \right) \right) \right) \left(x-\frac{t}{2^k} \right) \right|^2 \right)^{\frac{1}{2}}$ is the \emph{$t$-shifted square function}.

Consequently, we have that 
\begin{equation}\label{nonstathifoffdiag}
        \|BHC_{\lambda(\cdot)}^{\not \Delta, NS}(f_1, f_2)(\cdot)\|_{L^r}\lesssim_{r,p_1,p_2}\|f_1\|_{L^{p_1}}\,\|f_2\|_{L^{p_2}}
\end{equation}
for any H\"older range $\frac{1}{p_1}+\frac{1}{p_2}=\frac{1}{r}$ with $1<p_1,p_2\leq \infty$ and $\frac{1}{2}<r<\infty$.

\end{prop}

\begin{proof}
Fix $k \in \Z$ and $(j, l, m) \in \N^3$ in the non-stationary off-diagonal regime. We then see that using integration by parts, we have
$$
\frakm_{j, l, m, \lambda(x)}^k(\xi, \eta)=\frakA_{j, l, m, \lambda(x)}^k(\xi, \eta)+\frakB_{j, l, m, \lambda(x)}^k(\xi, \eta),
$$
where
$$
\frakA_{j, l, m, \lambda(x)}^k(\xi, \eta):=i \left( \int_{\R} e^{i \varphi_{\xi, \eta, \lambda(x)}^k(t)} \frac{\rho'(t)}{\frac{d}{dt} \varphi_{\xi, \eta, \lambda(x)}^k(t)}dt \right) \phi_1 \left(\frac{\xi}{2^{j+k}} \right) \phi_1 \left(\frac{\eta}{2^{l+2k}}\right) \phi_2 \left(\frac{\lambda(x)}{2^{{m+3k}}} \right)
$$
and
$$
\frakB_{j, l, m, \lambda(x)}^k(\xi, \eta):=-i \left( \int_{\R} e^{i \varphi_{\xi, \eta, \lambda(x)}^k(t)} \frac{\rho(t) \frac{d^2}{dt^2} \varphi_{\xi, \eta, \lambda(x)}^k(t)}{\left(\frac{d}{dt} \varphi_{\xi, \eta, \lambda(x)}^k(t) \right)^2}dt \right) \phi_1 \left(\frac{\xi}{2^{j+k}} \right) \phi_1 \left(\frac{\eta}{2^{l+2k}}\right) \phi_2 \left(\frac{\lambda(x)}{2^{{m+3k}}} \right)
$$
This further allows us to write. 
$$
BHC_{j, l, m, \lambda(x)}^k(f_1, f_2)=BHC_{j, l, m, \lambda(x)}^{k, \frakA}(f_1, f_2)+BHC_{j, l, m, \lambda(x)}^{k, \frakB}(f_1, f_2), 
$$
where $BHC_{j, l, m,\lambda(x)}^{k, \frakA}(f_1, f_2)$ and $ BHC_{j, l, m, \lambda(x)}^{k, \frakB}(f_1, f_2)$ have the multipliers $\frakA_{j, l, m, \lambda(x)}^k(\xi, \eta)$ and $\frakB_{j, l, m, \lambda(x)}^k(\xi, \eta)$, respectively. 

Denote $n:=\max\{j, l, m\}$. Observe that by Proposition \ref{20241113prop01}, for $|t| \sim 1$, 
$$
\left| \frac{d^2}{dt^2} \varphi_{\xi, \eta, \lambda(x)}^k(t) \right| =\left|\frac{6 \lambda(x)}{2^{3k}}\right| \cdot \left|t-t_0 \right| \lesssim 2^m \cdot \left\{2^{l-m}, 1\right\} \le 2^n \lesssim \left| \frac{d}{dt} \varphi_{\xi, \eta, \lambda(x)}^k(t) \right|, 
$$
which further gives
$$
\left| \frac{\rho'(t)}{\frac{d}{dt} \varphi_{\xi, \eta, \lambda(x)}^k(t)} \right|, \quad \left|  \frac{\rho(t) \frac{d^2}{dt^2} \varphi_{\xi, \eta, \lambda(x)}^k(t)}{\left(\frac{d}{dt} \varphi_{\xi, \eta, \lambda(x)}^k(t) \right)^2}\right| \lesssim \frac{1}{2^n}.
$$
Therefore, it suffices for us to analyze only one of the terms above, say $BHC_{j, l, m, \lambda(\cdot)}^{k, \frakA}(f_1, f_2)$. Next, via a Taylor series argument, we may consider, for the sake of analysis, that
\begin{eqnarray} \label{20241115eq02}
%
&& \left| BHC_{j, l, m, \lambda(x)}^{k, \frakA}(f_1, f_2)(x)\right|  \\
&& \lesssim \frac{1}{2^n} \int_{\frac{1}{4} \le |t| \le 4} \left| \left(\widehat{f_1}(\cdot) \phi_1 \left(\frac{\cdot}{2^{j+k}} \right) \right)^{\vee} \left(x-\frac{t}{2^k} \right) \right| \left| \left(\widehat{f_2}(\cdot) \phi_1 \left(\frac{\cdot}{2^{l+2k}} \right) \right)^{\vee} \left(x+\frac{t^2}{2^{2k}} \right) \right| \phi_2 \left(\frac{\lambda(x)}{2^{m+3k}} \right) dt. \nonumber 
\end{eqnarray}

With these, we then have 
\begin{eqnarray*}
%
&& \left| \sum_{k \in \Z} \sum_{j, l, m \ge 0} BHC_{j, l, m, \lambda(x)}^{k, \frakA}(f_1, f_2)(x) \right| \\
&& \lesssim \sum_{j, l \ge 0} \frac{1}{2^{\max\{j, l\}}} 
\Bigg [\int_{\frac{1}{4} \le |t| \le 4} \sum_{k \in \Z} \left| \left(\widehat{f_1}(\cdot) \phi_1 \left(\frac{\cdot}{2^{j+k}} \right) \right)^{\vee} \left(x-\frac{2^j t}{2^{j+k}} \right) \right| \\
&& \qquad \qquad \qquad  \cdot \left| \left(\widehat{f_2}(\cdot) \phi_1 \left(\frac{\cdot}{2^{l+2k}} \right) \right)^{\vee} \left(x+\frac{2^l t^2}{2^{l+2k}} \right) \right| \cdot  \left( \sum_{m \in \N} \phi_2 \left(\frac{\lambda(x)}{2^{m+3k}} \right) \right)  dt \Bigg ] \\
&& \lesssim \sum_{j, l \ge 0} \frac{1}{2^{\max\{j, l\}}} \cdot \int_{\frac{1}{4} \le |t| \le 4} \calS_{2^j t}^{\phi_1}(x) \calS_{-2^l t^2}^{\phi_1}(x) dt,
\end{eqnarray*}

 Finally, the desired $L^r$ bounds in \eqref{nonstathifoffdiag} follow from the above estimate and the corresponding $L^p$ bounds on $\calS_t^\phi f$ (see, e.g., \cite[Proposition 42]{Lie18} or \cite[Lemma 3.3]{GL20}). 
\end{proof}

\section{Treatment of the high-frequency diagonal component $BHC^{\Delta}$}\label{Mainsect}
Recall that 
$$
BHC^{\Delta}(f_1, f_2):=\sup\limits_{\lambda \in \R} \left|BHC_{\lambda}^{\Delta}(f_1, f_2) \right| \approx \sup_{\lambda \in \R} \left| \sum_{k \in \Z} \sum_{m \in \N} BHC_{m, \lambda}^k(f_1, f_2) \right|
$$
where $BHC_{m, \lambda}^k(f_1, f_2):=BHC_{m, m, m, \lambda}^k(f_1, f_2)$.  We start by splitting.
$$
BHC^{\Delta}(f_1, f_2)  \lesssim  BHC_{+}^{\Delta}(f_1, f_2)\,+\,BHC_{-}^{\Delta}(f_1, f_2), 
$$
with
$$
 BHC_{\pm}^{\Delta}(f_1, f_2):=\sup_{\lambda \in \R} |BHC_{\pm, \lambda}^{\Delta}(f_1, f_2)|:=\sup_{\lambda \in \R} \left|\sum_{k \in \Z_{\pm}} \sum_{m \in \N} BHC_{m, \lambda}^k(f_1, f_2)\right|.
$$
We shall first focus on the term $BHC_{+}^{\Delta}(f_1, f_2)$. 


\subsection{The case $k \ge 0$: Preparatives}
We first notice that
$$
 BHC_{+}^{\Delta}(f_1, f_2)=\sup\limits_{\lambda \in \R} \left|BHC_{+, \lambda}^{\Delta}(f_1, f_2)\right| \le \sum_{k \in \Z_{+}} \sum_{m \in \N} \sup_{\lambda} \left|BHC_{m, \lambda}^k(f_1, f_2) \right|. 
$$
From now on, we will fix the choice of $k, m \in \N$. Recall that in this case $|t| \sim 2^{-k}\leq 1$ and hence $|t|^3 \le t^2 \le |t|$. 

We now have that 
$$
BHC_{m, \lambda}^k(f_1, f_2)(x) \approx 2^k \phi_2 \left(\frac{\lambda}{2^{m+3k}} \right) \int_{\R} f_{1, m+k}(x-t) f_{2, m+2k}(x+t^2)e^{i \lambda t^3} \rho(2^k t) dt,
$$
and as a consequence we further divide our operator as 
$$
 \sup_{\lambda \in \R} \left|BHC_{m, \lambda}^k(f_1, f_2) \right| \le \sum_{n \in \Z} \sup_{\lambda \in \R} \left| BHC_{m, \lambda}^{k, I_n^{0, k}}(f_1, f_2)\right|,
$$
with
$$
BHC_{m, \lambda}^{k, I_n^{0, k}}(f_1, f_2)(x):=\one_{I_n^{0, k}}(x) \cdot 2^k \phi_2 \left(\frac{\lambda}{2^{m+3k}} \right) \int_{\R} f_{1, m+k}(x-t) f_{2, m+2k}(x+t^2)e^{i \lambda t^3} \rho(2^k t) dt,
$$
where, throughout the paper, $\one_{[a, b]}$ denotes the characteristic function of $[a, b]$, and for $m \in \N$, $j\in\{1,2\}$ and $k, q \in \Z$,   $f_{j, m}$ stands for $\calF^{-1} \left(\widehat{f}_j (\cdot) \phi_1 \left( \frac{\cdot}{2^{m}} \right) \right)$ and
$$
I_q^{m, k}:=\left[ \frac{q}{2^{\frac{m}{2}+k}}, \frac{q+1}{2^{\frac{m}{2}+k}}   \right].
$$

Notice that in order to recover the corresponding global estimates for $\sup\limits_{\lambda \in \R} \left|BC_{m, \lambda}^k\right|$, it suffices to prove local estimates for each of the terms $\sup\limits_{\lambda \in \R} \left| BC_{m, \lambda}^{k, I_n^{0, k}}\right|$, and then ``glue" them together by using the fact that $\left\{3I_n^{0,k} \right\}_{n \in \Z}$ has the finite intersection property. Therefore, from now on, we may assume without loss of generality that $n=1$. Moreover, for notational simplicity, in the sequel we will replace $I_1^{0, k}$ by $I^k$ and refer to 
$f_{j, m+j k}$ as simply $f_j$, $j\in\{1,2\}$. 

\bigskip 

\noindent \setword{\textbf{Key Heuristic 1.}}{KH1} \emph{Fix $k\geq 0$. Applying a standard linearization procedure we know that there exists a measurable function $\lambda (\cdot): \R \to \R$ such that 
$$
 \sup_{\lambda \in \R} \left| BHC_{m, \lambda}^{k, I^k}(f_1, f_2)(x) \right| \le 2 \left| BHC_{m, \lambda(x)}^{k, I^k}(f_1, f_2)(x) \right|. 
$$
Moreover, importantly, we claim that one can make this choice such that (essentially)}
\begin{center}
\texttt{$\lambda(x)$ takes constant values on intervals of length $2^{-m-2k}$}. 
\end{center}
\bigskip 


Indeed, to see this, we notice that 
\begin{eqnarray*}
%
&& \sup_{\lambda \in \R} \left| BHC_{m, \lambda}^{k, I^k}(f_1, f_2)(x) \right| \sim \sup_{\lambda \in \R} \left| \sum_{p' \sim 2^{m+k}} \one_{I_{p'}^{0, m+2k}} (x) \cdot2^k \phi_2 \left(\frac{\lambda}{2^{m+3k}} \right) \int_{I^k} f_1(x-t) f_2(x+t^2)e^{i \lambda t^3} dt \right|  \\
&& \quad \lesssim \sum_{p' \sim 2^{m+k}} \sup_{\lambda \in \R} \left| \one_{I_{p'}^{0, m+2k}}(x)\cdot2^k \phi_2 \left(\frac{\lambda}{2^{m+3k}} \right) \int_{I^k} f_1(x-t) f_2(x+t^2)e^{i \lambda t^3} dt \right|
\end{eqnarray*}
and, recalling our notational convention $f_j\equiv f_{j, m+jk}$, we immediately deduce that
\begin{enumerate}
\item [$\bullet$] $f_1$ is morally a constant on intervals of length $2^{-m-k}$;
\item [$\bullet$] $f_2$ is morally a constant on intervals of length $2^{-m-2k}$.
\end{enumerate}
Therefore, for each $\lambda \in \R$, one has 
$$
\one_{I_{p'}^{0, m+2k}}(x)  \int_{I^k} f_1(x-t) f_2(x+t^2)e^{i \lambda t^3} dt \approx \one_{I_{p'}^{0, m+2k}}(x)  \int_{I^k} f_1\left(\frac{p'}{2^{m+2k}}-t \right) f_2\left(\frac{p'}{2^{m+2k}}+t^2\right) e^{i \lambda t^3} dt
$$
which justifies our claim. \hfill \qedsymbol{}

\bigskip  

Our goal is to prove the following key result:
\medskip 

\begin{thm} \label{20241018mainthm01}
Let $k \ge 0$ and $m\in \N$. Let further, 
\begin{equation} \label{20240411eq01}
\Lambda_m^k(f_1, f_2, f_3):=2^k\int_{I^k} \int_{I^k} f_1(x-t)f_2(x+t^2)f_3(x)e^{i \lambda(x) t^3} dtdx,
\end{equation}
be the dual form of $BC_{m, \lambda(\cdot)}^{k, I^k}$ defined in {\bf Key Heuristic 1}, where $\lambda (\cdot): I^k \to [2^{m+3k}, 2^{m+3k+1}]$ is any measurable function taking constant values on intervals of length $2^{-m-2k}$. 

Then, there exists some $\epsilon>0$, such that the following estimate holds:
\begin{equation} \label{20240410eq02}
\left|\Lambda_m^k(f_1, f_2, f_3) \right| \lesssim  2^{-\epsilon \min \{2 k, m\}} \prod_{j=1}^3 \left\|f_j \right\|_{L^{p_j} \left(3I^k \right)}, 
\end{equation}
 whenever $(p_1, p_2, p_3)=(2, \infty, 2), (\infty, 2, 2)$ or $(2, 2, \infty)$
\end{thm}
\medskip 



We start our analysis of \eqref{20240411eq01} with a preliminary observation: applying Cauchy-Schwarz we have 
\begin{eqnarray*}
\left| \Lambda_m^k(f_1, f_2, f_3) \right|^2%
&\le&  2^{2k} \int_{I^k} \left| \sum_{q \sim 2^{\frac{m}{2}}} \int_{I_q^{m, k}} f_1(x-t)f_2(x+t^2)e^{i\lambda(x)t^3} dt \right|^2 dx \cdot \left\|f_3 \right\|_{L^2 \left(3I^k \right)}^2
\end{eqnarray*}
and using the information that for $t \in I_q^{m, k}$ one has
$$
\lambda(x) t^3=\frac{3q^2t\lambda(x)}{2^{m+2k}}-\frac{2q^3\lambda(x)}{2^{\frac{3m}{2}+3k}}+O(1),
$$
we conclude that
\begin{eqnarray}  \label{20240429eq01}
\left| \Lambda_m^k(f_1, f_2, f_3) \right|^2%
&\lesssim& 2^k \left\|f_3 \right\|_{L^2\left(3I^k \right)}^2 \left[ {\bf L}_{m, k}(f_1, f_2) \right]^2,   
\end{eqnarray}
where
\begin{equation} \label{20240426eq01}
\left[ {\bf L}_{m, k}(f_1, f_2) \right]^2:=2^{k} \int_{I^k} \left| \sum_{q \sim 2^{\frac{m}{2}}} \int_{I_q^{m, k}} f_1(x-t)f_2(x+t^2) e^{-2i \cdot \frac{q^3 \lambda(x)}{2^{\frac{3m}{2}+3k}}}  \cdot e^{3i \cdot \frac{q^2 \lambda(x)}{2^{m+2k}} t} dt \right|^2 dx\,.
\end{equation} 

Thus, we reduce matters to the analysis of ${\bf L}_{m, k}(f_1, f_2)$.

\subsection{A sparse-uniform dichotomy} \label{20241216subsec01}
We analyze the term \eqref{20240426eq01} via two different scenarios, namely, whether the $L^2$ information of the two input functions $f_1$ and $f_2$ are spatially concentrated or uniformly distributed. More precisely, let $\mu \in (0, 1)$ be sufficiently small and, for $i \in \{1, 2\}$ and $f_i$ define the \emph{sparse and uniform index sets} as follows: 
$$
\calS_\mu(f_i):=\left\{r \sim 2^{m+(i-1)k}: \frac{1}{\left|I_r^{ik+m} \right|} \int_{3I_r^{0, ik+m}}\left|Mf_i \right|^2 \gtrsim \frac{2^{\mu\min \left\{m, 2 k \right\}}}{|I^k|} \int_{3I^k} |f_i|^2 \right\}
$$
and
$$
\calU_\mu(f_i):=\left\{r \sim 2^{m+(i-1)k}: \frac{1}{\left|I_r^{ik+m} \right|} \int_{3I_r^{0, ik+m}}\left|Mf_i \right|^2 \lesssim \frac{2^{\mu\min \left\{m, 2 k \right\}}}{|I^k|} \int_{3I^k} |f_i|^2 \right\}\,,
$$
respectively, where $M$ is the Hardy-Littlewood maximal operator.

We shall now decompose our input functions accordingly:
$$
f_i=f_i^{\calS_\mu}+f_i^{\calU_\mu}, \qquad i \in \{1, 2\}, 
$$
where 
$$
f_i^{\calS_\mu}:=\sum_{r \in \calS_\mu(f_i)} \one_{I_r^{0, ik+m}} f_i, \quad \textrm{and} \quad f_i^{\calU_\mu}:=\sum_{r \in \calU_\mu(f_i)} \one_{I_r^{0, ik+m}} f_i, \qquad i \in \{1, 2\}. 
$$
Let us now decompose the term ${\bf L}_{m, k}(f_1, f_2)$ into two parts:
$$
{\bf L}_{m, k}(f_1, f_2) \le {\bf L}_{m, k}^{\calU_\mu}(f_1, f_2)+{\bf L}_{m, k}^{\calS_\mu}(f_1, f_2), 
$$
where 
\begin{enumerate}
    \item [$\bullet$] the \emph{uniform} component ${\bf L}_{m, k}^{\calU_\mu}(f_1, f_2)$ is given by $$
    {\bf L}_{m, k}^{\calU_\mu}(f_1, f_2):={\bf L}_{m, k}\left(f_1^{\calU_\mu}, f_2^{\calU_\mu}\right).
    $$
    \item [$\bullet$] the \emph{sparse} component ${\bf L}_{m, k}^{\calS_\mu}(f_1, f_2)$ is given by
    $$
    {\bf L}_{m, k}^{\calS_\mu}(f_1, f_2):={\bf L}_{m, k}\left(f_1^{\calS_\mu}, f_2^{\calU_\mu}\right)+{\bf L}_{m, k}\left(f_1^{\calU_\mu}, f_2^{\calS_\mu}\right)+{\bf L}_{m, k}\left(f_1^{\calS_\mu}, f_2^{\calS_\mu}\right).
    $$
\end{enumerate}
Note that the uniform/sparse parts enjoy the following properties:
\begin{enumerate}
\item [$\bullet$] For $f_i^{\calU_\mu}$, one has $f_i^{\calU_\mu} \in L^\infty(\R)$ with
\begin{equation} \label{uniformest} 
\left\|f_i^{\calU_\mu} \right\|_{L^\infty(3I^k)} \lesssim 2^{\frac{\mu \min \left\{m, 2k \right\}}{2}} 2^{\frac{k}{2}} \left\|f_i \right\|_{L^2(3I^k)};
\end{equation} 
\item [$\bullet$] For $f_i^{\calS_\mu}$, one has
\begin{equation} \label{20240429eq02}
\max_{i \in \{1, 2\}} \left| \supp \ f_i^{\calS_\mu} \right| \lesssim 2^{-\mu  \min\left\{m, 2k \right\}}|I^k|. 
\end{equation} 
\end{enumerate}

\subsection{Treatment of the sparse component ${\bf L}_{m, k}^{\calS_\mu}(f_1, f_2)$}
We consider two different cases.

\medskip 

\noindent\textsf{\underline{Case I: $f_1$ sparse.}} \quad In this situation we need to estimate a (generic) term of the form ${\bf L}_{m, k}\left(f_1^{\calS_\mu}, f_2\right)$. To begin with, for each $I \subseteq I^k$ interval, we set $\widetilde{\calS_\mu^{3I}}(f_1):=\bigcup\limits_{\substack{r \in \calS_\mu(f_1) \\ I_r^{0, k+m} \subseteq 3I}} I_r^{0, k+m}$. Therefore, by Cauchy-Schwarz and \eqref{20240429eq02}, we have 
\begin{eqnarray*}
\left[{\bf L}_{m, k}\left(f_1^{\calS_\mu}, f_2 \right) \right]^2%
&\le& 2^k \int_{I^k} \left( \int_{I^k} \left|f_1^{\calS_\mu}(x-t) \right| \left|f_2(x+t^2) \right| dt \right)^2 dx \\
&\le& 2^k \left| \widetilde{\calS_\mu^{3I^k}}(f_1) \right| \cdot \int_{I^k} \int_{I^k} \left|f^{\calS_\mu}_1(x-t) \right|^2 |f_2(x+t^2)|^2 dtdx \\
&\le& 2^k \cdot 2^{-\mu \min\{m, 2k\}} |I^k| \cdot \left\|f_1 \right\|^2_{L^2(3I^k)}\left\|f_2 \right\|^2_{L^2(3I^k)}.
\end{eqnarray*}
Therefore, combining the above estimate with \eqref{20240429eq01}, we have 
\begin{eqnarray*}
\left[\Lambda_m^k(f^{\calS^\mu}_1, f_2, f_3) \right]^2%
&\lesssim&  2^k \left\|f_3 \right\|_{L^2(3I^k)}^2 \cdot 2^k \cdot 2^{-\mu \min\{m, 2 k\}} |I^k| \cdot \left\|f_1 \right\|^2_{L^2(3I^k)}\left\|f_2 \right\|^2_{L^2(3I^k)} \\
&\lesssim& 2^{-\mu \min\{m, 2k\}}  \prod_{j=1}^3 \left\|f_j \right\|^2_{L^{p_j}\left(3I^k \right)}, 
\end{eqnarray*}
for $(p_1, p_2, p_3)=(2, \infty, 2), (\infty, 2, 2)$ and $(2, 2, \infty)$, which gives the desired estimate \eqref{20240410eq02}. 

\medskip 

\noindent\textsf{\underline{Case II: $f_2$ sparse.}} \quad In this case, we divide our analysis into two scenarios. We first prove the estimate \eqref{20240410eq02} with $(p_1, p_2, p_3)=(2, \infty, 2)$ or $(\infty, 2, 2)$. For this purpose, we focus our attention on the term ${\bf L}_{m, k} \left(f_1, f_2^{\calS_\mu} \right)$. As before, for any interval $I \subseteq I^k$, we set $\widetilde{\calS_{\mu}^{3I}} \left(f_2 \right):=\bigcup\limits_{\substack{r \in \calS_\mu(f_2) \\ I_r^{0, 2k+m} \subseteq 3I}} I_r^{0, 2k+m}$. With these, we have
\begin{eqnarray} \label{20240429eq10}
\left[{\bf L}_{m, k} \left(f_1, f_2^{\calS_\mu} \right) \right]^2 %
&\lesssim&  2^k \int_{I^k} \left( \int_{I^k} \left|f_1 (x-t) \right| \left|f_2^{\calS_\mu}(x+t^2) \right| dt \right)^2 dx \nonumber \\
&=& 2^k \sum_{\ell \sim 2^k} \int_{I_\ell^{0, 2k}} \left( \int_{I^k} \left|f_1 (x-t) \right| \left|f_2^{\calS_\mu}(x+t^2) \right| dt \right)^2 dx. 
\end{eqnarray}
Note that for each $\ ell\sim 2^k$, then by Cauchy-Schwarz and a change of variables, we have 
$$
\int_{I_\ell^{0, 2k}} \left( \int_{I^k} \left|f_1 (x-t) \right| \left|f_2^{\calS_\mu}(x+t^2) \right| dt \right)^2 dx \lesssim 2^k \cdot \left| \widetilde{\calS_\mu^{3I_\ell^{0, 2k}}} (f_2) \right|  \int_{I_\ell^{0, 2k}} \int_{I^k} \left|f_1 (x-t) \right|^2 \left|f_2^{\calS_\mu}(x+t^2) \right|^2 dt  dx.
$$
Thus, combining the above estimate with \eqref{20240429eq01} and \eqref{20240429eq10}, we have 
\begin{eqnarray*} 
\left[\Lambda_m^k(f_1, f^{\calS^\mu}_2, f_3) \right]^2%
&\lesssim& 2^{3k} \left\|f_3 \right\|_{L^2(3I^k)}^2 \cdot \sum_{\ell \sim 2^k}  \left| \widetilde{\calS_\mu^{3I_\ell^{0, 2k}}} (f_2)\right|  \int_{I_\ell^{0, 2k}} \int_{I^k} \left|f_1 (x-t) \right|^2 \left|f_2^{\calS_\mu}(x+t^2) \right|^2 dtdx \nonumber  \\
&\lesssim& 2^{3k} \left\|f_2 \right\|_{L^\infty(3I^k)}^2 \left\|f_3 \right\|_{L^2(3I^k)}^2 \cdot \sum_{\ell \sim 2^k} \left| \widetilde{\calS_\mu^{3I_\ell^{0, 2k}}} (f_2) \right| \int_{I_\ell^{0, 2k}} \int_{I^k} \left|f_1 (x-t) \right|^2  dtdx \\
&\lesssim& 2^k \left\|f_1 \right\|^2_{L^2(3I^k)}\left\|f_2 \right\|_{L^\infty(3I^k)}^2 \left\|f_3 \right\|_{L^2(3I^k)}^2 \cdot \sum_{\ell \sim 2^k} \left| \widetilde{\calS_\mu^{3I_\ell^{0, 2k}}}  (f_2) \right| \nonumber \\
&\lesssim& 2^{-\mu \min\{m, 2k\}} \left\|f_1 \right\|^2_{L^2 \left(3I^k \right)} \left\|f_2 \right\|^2_{L^\infty \left(3I^k \right)} \left\|f_3 \right\|^2_{L^2 \left(3I^k \right)}. \nonumber
\end{eqnarray*}
Similarly, one can also show that
$$
\left[\Lambda_m^k(f_1, f^{\calS^\mu}_2, f_3) \right]^2 \lesssim 2^{-\mu \min\{m, 2k\}} \left\|f_1 \right\|^2_{L^\infty \left(3I^k \right)} \left\|f_2 \right\|^2_{L^2 \left(3I^k \right)} \left\|f_3 \right\|^2_{L^2 \left(3I^k \right)}. 
$$
Next, we establish estimate \eqref{20240410eq02} for $(p_1, p_2, p_3)=(2, 2, \infty)$. For this, we first note that  
\begin{align*}
\left|\Lambda_m^k\left(f_1, f^{\calS_\mu}_2, f_3 \right) \right|^2 
& \le 2^{2k} \left( \int_{I^k} \int_{I^k} |f_1(x-t)|\left|f^{\calS_\mu}_2(x+t^2)\right||f_3(x)|dxdt \right)^2 \\
& \le 2^{2k} \left( \int_{I^k} \int_{2I^k} |f_3(x+t)|\left|f^{\calS_\mu}_2(x+t+t^2)\right||f_1(x)| dxdt \right)^2 \\
& \le 2^{2k} \int_{2I^k} \left(\int_{I^k} |f_3(x+t)| \left| f_2^{\calS_\mu}(x+t+t^2) \right| dt \right)^2 dx \cdot \left\|f_1 \right\|_{L^2(3I^k)}^2 \\
& \le 2^{2k} \left|\widetilde{\calS_{\mu}^{3I^k}} \left(f_2 \right) \right| \int_{2I^k} \int_{I^k}|f_3(x+t)|^2 \left| f_2^{\calS_\mu}(x+t+t^2) \right|^2 dtdx \cdot \left\|f_1 \right\|_{L^2(3I^k)}^2 \\
& \le 2^{2k} \cdot 2^{-\mu \min \left\{m, 2k\right\}} |I^k| \cdot  \int_{2I^k} \int_{I^k} |f_2(x+t+t^2)|^2dtdx \cdot \left\|f_1 \right\|_{L^2(3I^k)}^2 \left\|f_3 \right\|_{L^\infty(3I^k)}^2 \\
& \le 2^{-\mu \min \left\{m, 2k\right\}} \left\|f_1 \right\|_{L^2(3I^k)}^2 \left\|f_2 \right\|_{L^2(3I^k)}^2 \left\|f_3 \right\|_{L^\infty(3I^k)}^2,
\end{align*}
which gives the desired estimate.

\subsection{Treatment of the uniform component ${\bf L}_{m, k}^{\calU_\mu}(f_1, f_2)$: An overview} \label{20241023overview01}


In this section, for reader's convenience, we offer a very brief recap of the strategy employed for treating the uniform component  ${\bf L}_{m, k}^{\calU_\mu}(f_1, f_2)$ as displayed in the last part of the introductory Section \ref{Planmainideas}. 





To begin with, let us write 
$$
\widetilde{\lambda}(x):=\frac{\lambda (x)}{2^{\frac{m}{2}+3k}},
$$
and deduce that as a consequence of our assumptions we have $\widetilde{\lambda}: I^k \to \left[2^{\frac{m}{2}}, 2^{\frac{m}{2}+1} \right]$ is a measurable function which takes constant values on intervals of length $2^{-m-2k}$. Consequently, our main expression now becomes
\begin{eqnarray} \label{20241004eq01}
%
&& \:\:\:\:\:\:\left[ {\bf L}^{\calU_\mu}_{m, k}(f_1, f_2) \right]^2:= 2^{k} \int_{I^k} \left| \sum_{q \sim 2^{\frac{m}{2}}} \int_{I_q^{m, k}} f_1^{\calU_\mu}(x-t)f_2^{\calU_\mu}(x+t^2) e^{-2i \cdot \frac{q^3 \widetilde{\lambda}(x)}{2^m}}  \cdot e^{3i 2^k \cdot \frac{q^2 \widetilde{\lambda}(x)}{2^{\frac{m}{2}}} t} dt \right|^2 dx \nonumber  \\
&&\lesssim \left[{\calL}_{m, k}^{\calU_\mu}(f_1, f_2) \right]^2 \ :=  2^{\frac{m}{2}+k} \cdot  \int_{I^k} \left( \sum_{q \sim 2^{\frac{m}{2}}} \left| \int_{I_q^{m, k}} f^{\calU_\mu}_1(x-t)f^{\calU_\mu}_2(x+t^2) e^{3i2^k \cdot \frac{q^2 \widetilde{\lambda}(x)}{2^{\frac{m}{2}}}t} dt\right|^2 \right)dx.
\end{eqnarray} 
In the sequel, we will divide our proof into two cases: 
\medskip 

\noindent \underline{\textsf{Case I: $k \ge \frac{m}{2}$.}} \quad Recalling now Proposition \ref{maxjointctrl} (\cite[Theorem 4.3]{HL23}) we further consider
two regimes:
\smallskip

\begin{enumerate}
    \item [$\bullet$]  \underline{\textsf{Case I.1: $k \ge m$.}} \quad In this situation, since $2^{-m-2k}\geq 2^{-3k}$, our desired estimate follows directly from Proposition \ref{maxjointctrl}.
\smallskip        

    \item [$\bullet$]  \underline{\textsf{Case I.2: $\frac{m}{2} \le k \le m$.}}\quad  In this situation, we follow a two-step approach: 
\medskip    
 \begin{itemize}   
    \item \underline{\textsf{Step I.2.1:}} We first implement the constancy propagation procedure in order to extend the constancy of $\widetilde{\lambda}$ from intervals of length $2^{-m-2k}$ to intervals of length $2^{-m-k}$. 
\smallskip    
    \item \underline{\textsf{Step I.2.2:}} Once we reach the scale $2^{-m-k}$, we notice that we are in the regime $2^{-m-k} \ge 2^{-3k}$, and hence  Proposition \ref{maxjointctrl} applies once again.
 \end{itemize}   
\end{enumerate}

\medskip

\noindent \underline{\textsf{Case II: $0 \le k \le \frac{m}{2}$.}} In this case, we employ a two-step approach:
\smallskip
\begin{itemize}
\item \underline{\textsf{Step II.1:}} As at the Step I.2.1, we first apply the constancy propagation procedure in order to extend the constancy of $\widetilde{\lambda}$ from intervals of length $2^{-m-2k}$ to intervals of length $2^{-m-k}$.
\smallskip

\item \underline{\textsf{Step II.2:}} Once we reach the $2^{-m-k}-$constancy scale for  $\widetilde{\lambda}$, we apply to \eqref{20240411eq01} the Rank I LGC method in order to conclude our proof. 
\end{itemize}
\smallskip
\noindent We end this section with the following:

\begin{rem}
In the sequel, in order to illustrate the new ideas in the present paper, we focus our presentation on the second part $0 \le k \le \frac{m}{2}$, and only briefly mention the treatment required for the first part $k \ge \frac{m}{2}$ (for the latter, see \textsf{Step I} in the proof of Proposition \ref{20241018prop01}). 
\end{rem}


\subsection{Treatment of the uniform component ${\bf L}_{m, k}^{\calU_\mu}(f_1, f_2)$: Case II, Step II.1 in Overview} \label{20241217subsec01} 

Recall $\calL_{m, k}^{\calU_\mu}(f_1, f_2)$ defined in \eqref{20241004eq01}. Essentially, our goal in this first part is to show that 
\begin{equation} \label{20241005eq01} 
\textnormal{\texttt{the length of constancy of the measurable function $\widetilde{\lambda}$ can be extended to $2^{-m-k}$.}}  \tag{{\bf H1}}
\end{equation}
To make the above heuristic rigorously, for each $p \sim 2^m$, we define\footnote{For notational simplicity, throughout this section, we set $f_1=f_1^{\calU_\mu}$ and $f_2=f_2^{\calU_\mu}$.}
\begin{equation} \label{20241004eq21}
V_{m, k}^p(f_1, f_2):=2^{\frac{3m}{2}+k} \sum_{q \sim 2^{\frac{m}{2}}} \int_{I_p^{0, k+m}} \left| \int_{I_q^{m, k}} f_1(x-t)f_2(x+t^2) e^{3i 2^k \cdot \frac{q^2 \widetilde{\lambda}(x)}{2^{\frac{m}{2}}} t} dt \right|^2  dx\,,
\end{equation} 
and remark that
$$
\left[\calL_{m, k}^{\calU_\mu} (f_1, f_2) \right]^2=\frac{1}{2^m} \sum_{p \sim 2^m} V_{m, k}^p(f_1, f_2).
$$
Next, we claim that one can essentially replace the term $f_1(x-t)$ in \eqref{20241004eq21} by $f_1\left(\frac{p}{2^{k+m}}-t \right)$. Indeed, this is achieved by the following approximation argument, whose proof resembles the one in \cite[Proposition 4.5 and Corollary 4.6]{HL23}, and therefore, is omitted.

\begin{prop} \label{20241006prop01}
For $k, m \in \N$ with $0 \le k \le \frac{m}{2}$, $p \sim 2^m$, $q \sim 2^{\frac{m}{2}}$ and $\del>4\mu$ sufficiently small, one has
\begin{eqnarray*}
%
&& \int_{I_p^{0,k+m}} \left| \int_{I_q^{m, k}} f_1(x-t) f_2(x+t^2) e^{3i 2^k \frac{q^2 \widetilde{\lambda(x)}}{2^{\frac{m}{2}}} t} dt \right|^2 dx \\
&& \lesssim \frac{2^{\del k}}{\left|I_0^{0, k+m}\right|} \int_{3I_0^{0, k+m}} \int_{I_0^{0, k+m}} \left| \int_{I_q^{m, k}} f_1 \left(\alpha+\frac{p}{2^{k+m}}-t \right) f_2 \left(x+\frac{p}{2^{k+m}}+t^2 \right)  e^{3i 2^k \frac{q^2 \widetilde{\lambda}\left(x+\frac{p}{2^{k+m}} \right)}{2^{\frac{m}{2}}} t} dt \right|^2 dx d\alpha \\
&& \quad +O \left(2^{-(\del-2\mu)k} \cdot 2^{-2m-k} \left\| f_1 \right\|_{L^2 \left(3I^k \right)}^2 \left\| f_2 \right\|_{L^2 \left(3I^k \right)}^2 \right).
\end{eqnarray*}
\end{prop}

Once at this point, we group $2^{m-k}$ many consecutive $p$'s: specifically, we decompose 
$$
\left[ 2^m, 2^{m+1} \right]=\bigcup_{\widetilde{p} \sim 2^k} \left[\widetilde{p} 2^{m-k}, (\widetilde{p}+1)2^{m-k} \right]
$$
and define
\begin{equation} \label{20241217eq10}
V_{m, k}^{\widetilde{p}}(f_1, f_2):=\frac{1}{2^{m-k}} \sum_{p \in \left[\widetilde{p} 2^{m-k}, (\widetilde{p}+1)2^{m-k} \right]} V_{m, k}^p (f_1, f_2)\,.
\end{equation}
With these done we are ready to state the following
\medskip

\noindent \setword{\textbf{Key Heuristic 2}}{KH2}. One of the following statements is \emph{essentially true}: for each $\widetilde{p} \sim 2^k$, 
\begin{enumerate}
    \item [$\bullet$] \emph{either} $\lambda (\cdot)$ is morally constant on each interval $I_p^{0, k+m}$ with $p \in \left[ \widetilde{p} 2^{m-k}, (\widetilde{p}+1) 2^{m-k} \right]$;
    \item [$\bullet$] \emph{or} there exists some $\epsilon>0$, such that $\left| V_{m, k}^{\widetilde{p}} (f_1, f_2) \right| \lesssim 2^{-\epsilon k} \left\|f_1 \right\|_{L^2(3I^k)}^2 \left\|f_2 \right\|_{L^2(3I^k)}^2$.
\end{enumerate}
In order to make the above heuristic precise, we start by further decomposing the range of $\widetilde{\lambda}$ as follows: fix $\epsilon_0>0$ sufficiently small, and then write
$$
\textrm{Range of} \ \widetilde{\lambda}= \bigcup_{\ell \sim 2^{\frac{m}{2}-\epsilon_0 k}} \left[ \ell 2^{\epsilon_0 k}, (\ell+1) 2^{\epsilon_0 k} \right]. 
$$
Next, we partition each $I_p^{0, k+m}$ into the preimages corresponding to the above decomposition: for each $\ell \sim 2^{\frac{m}{2}-\epsilon_0 k}$, we set
$$
\frakM_\ell \left(I_p^{0, k+m} \right):=\left\{x \in I_p^{0, k+m}: \widetilde{\lambda}(x) \in \left[ \ell 2^{\epsilon_0 k}, (\ell+1)2^{\epsilon_0 k}  \right] \right\}, 
$$
define
\begin{enumerate}
    \item [$\bullet$] \emph{the heavy set of $\ell$-indices}:
    \begin{equation} \label{20241011eq32}
    \calH_p^k:=\left\{\ell \sim 2^{\frac{m}{2}-\epsilon_0 k}: \left| \frakM_\ell \left(I_p^{0, k+m} \right) \right| \gtrsim \left|I_p^{0, k+m} \right| 2^{-\epsilon_0 k} \right\}
    \end{equation} 
    \item [$\bullet$] \emph{the light set of $\ell$-indices}:
    \begin{equation} \label{20241011eq40}
      \calL_p^k:=\left\{\ell \sim 2^{\frac{m}{2}-\epsilon_0 k}: \left| \frakM_\ell \left(I_p^{0, k+m} \right) \right| \lesssim \left|I_p^{0, k+m} \right| 2^{-\epsilon_0 k} \right\},
    \end{equation}
\end{enumerate}
and set 
$$
\widetilde{\calH_p^k}:=\bigcup_{\ell \in \calH_p^k} \frakM_\ell \left(I_p^{0, k+m} \right) \quad \textrm{and} \quad \widetilde{\calL_p^k}:=\bigcup_{\ell \in \calL_p^k} \frakM_\ell \left(I_p^{0, k+m} \right).
$$
Observe now that
$$
I_p^{0, k+m}=\widetilde{\calH_p^k} \cup \widetilde{\calL_p^k} \quad \textrm{with} \quad \# \calH_p^k \lesssim 2^{\epsilon_0 k}. 
$$
Using the above decomposition, we further write $V_{m, k}^{\widetilde{p}}$ into two parts as follows: 
$$
V_{m, k}^{\widetilde{p}}(f_1, f_2)=V_{m, k}^{\widetilde{p}, \calH}(f_1, f_2)+V_{m, k}^{\widetilde{p}, \calL}(f_1, f_2), 
$$
where
$$
V_{m, k}^{\widetilde{p}, \calH}(f_1, f_2):=2^{\frac{m}{2}+2k} \sum_{p \in \left[\widetilde{p} 2^{m-k}, (\widetilde{p}+1)2^{m-k} \right]} \sum_{q \sim 2^{\frac{m}{2}}} \int_{\widetilde{\calH_p^k}} \left| \int_{I_q^{m, k}} f_1(x-t)f_2(x+t^2) e^{3i 2^k \cdot \frac{q^2 \widetilde{\lambda}(x)}{2^{\frac{m}{2}}} t} dt \right|^2  dx.
$$
and 
$$
V_{m, k}^{\widetilde{p}, \calL}(f_1, f_2):=2^{\frac{m}{2}+2k} \sum_{p \in \left[\widetilde{p} 2^{m-k}, (\widetilde{p}+1)2^{m-k} \right]} \sum_{q \sim 2^{\frac{m}{2}}} \int_{\widetilde{\calL_p^k}} \left| \int_{I_q^{m, k}} f_1(x-t)f_2(x+t^2) e^{3i 2^k \cdot \frac{q^2 \widetilde{\lambda}(x)}{2^{\frac{m}{2}}} t} dt \right|^2  dx.
$$
In what follows we first address the light component $V_{m, k}^{\widetilde{p}, \calL}$ whose treatment requires a completely different insight relative to the work performed in \cite{HL23}:

\begin{prop} \label{20241018prop01}
There exists some $\epsilon_1>0$, such that 
$$
\left|V_{m, k}^{\widetilde{p}, \calL}(f_1, f_2) \right| \lesssim 2^{-\epsilon_1 k} \left\|f_1 \right\|_{L^2(3I^k)}^2 \left\|f_2 \right\|^2_{L^2(3I^k)}. 
$$
\end{prop}

\begin{proof} \textsf{Step I: Initial reduction.} Without loss of generality, we may assume that $0 \le k \le \frac{m}{2}-\epsilon_2 m$ with $\epsilon_2>0$ being sufficiently small. This follows from the decay estimate for the case when $k=\frac{m}{2}$ (see, Subsection  \ref{20241028subsec01} below) and the continuity of the $\Lambda_{j, l, m}^k$ bounds (see, \cite[Appendix 13.3]{HL23}). 

Moreover, we may also assume that for each $p \in \left[(\widetilde{p}-20)2^{m-k}, (\widetilde{p}+20)2^{m-k}\right]$, $\widetilde{\calL_p^k}=I_p^{0, k+m}$. Otherwise, one can apply an extension argument as in the proof in \cite[\textsf{Step I}, Proposition 4.7]{HL23}.

Therefore, by the above observations and Proposition \ref{20241006prop01}, it suffices to consider the term
\begin{eqnarray*}
%
&& \frac{2^{\frac{m}{2}+2k+\del k}}{\left|I_0^{0, k+m} \right|} \sum_{p \in \left[\widetilde{p}2^{m-k}, (\widetilde{p}+1) 2^{m-k}  \right]} \sum_{q \sim 2^\frac{m}{2}} \int_{3I_0^{0, k+m}} \int_{I_0^{0, k+m}} \bigg| \int_{I_q^{m, k}} f_1 \left(\alpha+\frac{p}{2^{k+m}}-t \right) \\
&& \qquad \qquad \qquad \qquad  \cdot f_2 \left(x+\frac{p}{2^{k+m}}+t^2 \right)  e^{3i 2^k \frac{q^2 \widetilde{\lambda}\left(x+\frac{p}{2^{k+m}} \right)}{2^{\frac{m}{2}}} t} dt \bigg|^2 dx d\alpha, 
\end{eqnarray*}
which, by assuming wlog $\alpha=0$, further reduces to
\begin{eqnarray*}
%
&& {\bf V}_{m, k}^{\widetilde{p}, \calL}(f_1, f_2):=2^{\frac{m}{2}+2k+\del k} \sum_{p \in \left[\widetilde{p}2^{m-k}, (\widetilde{p}+1) 2^{m-k}  \right]} \sum_{q \sim 2^\frac{m}{2}}  \int_{I_0^{0, k+m}} \bigg| \int_{I_q^{m, k}} f_1 \left(\frac{p}{2^{k+m}}-t \right) \\
&& \qquad \qquad \qquad \qquad  \cdot f_2 \left(x+\frac{p}{2^{k+m}}+t^2 \right)  e^{3i 2^k \frac{q^2 \widetilde{\lambda}\left(x+\frac{p}{2^{k+m}} \right)}{2^{\frac{m}{2}}} t} dt \bigg|^2 dx, 
\end{eqnarray*}
We end our preparatives with the following

\begin{rem}\label{Simplif} Throughout the current proof we will simplify our reasonings by making use---in numerous instances---of the fact that
\begin{itemize}
\item $f_1$ is morally constant on intervals of length $2^{-m-k}$; 
\item  $f_2$ is morally a constant on intervals of length $2^{-m-2k}$.
\end{itemize}
These simplifications can be made rigorously by either subdividing the range of $q$ and then choosing representatives within each subdivision or by simply further subdividing the $t-$integration interval---see \emph{e.g.} Step I in the proof of Proposition 4.9. in \cite{HL23}. In order to remove excessive technicalities from our exposition and thus improve its readability we will skip detailing these elements here.
\end{rem}


\medskip 

\noindent \textsf{Step II: Further reductions via $TT^*$.} We begin by applying the change of variable $t \mapsto t+\frac{q}{2^{\frac{m}{2}+k}}$, which gives
\begin{eqnarray*}
%
&& {\bf V}_{m, k}^{\widetilde{p}, \calL}(f_1, f_2)\approx2^{\frac{m}{2}+2k+\del k} \sum_{p \in \left[\widetilde{p}2^{m-k}, (\widetilde{p}+1) 2^{m-k}  \right]} \sum_{q \sim 2^\frac{m}{2}}  \int_{I_0^{0, k+m}} \bigg| \int_{I_0^{m, k}} f_1 \left(\frac{p}{2^{k+m}}-\frac{q}{2^{\frac{m}{2}+k}}-t \right) \\
&& \qquad \qquad \qquad \qquad  \cdot f_2 \left(x+\frac{p}{2^{k+m}}+\frac{2tq}{2^{\frac{m}{2}+k}}+\frac{q^2}{2^{m+2k}} \right)  e^{3i 2^k \frac{q^2 \widetilde{\lambda}\left(x+\frac{p}{2^{k+m}} \right)}{2^{\frac{m}{2}}} t} dt \bigg|^2 dx\,,
\end{eqnarray*}
where above we have used the relation $\left(t+\frac{q}{2^{\frac{m}{2}+k}} \right)^2=\frac{2tq}{2^{\frac{m}{2}+k}}+\frac{q^2}{2^{m+2k}}+O \left(\frac{1}{2^{m+2k}} \right)$ together with the fact that\footnote{Recall Remark \ref{Simplif}.}  $f_2$ is morally a constant on intervals of length $2^{-m-2k}$.


Next, for each $p \in \left[\widetilde{p} 2^{m-k}, (\widetilde{p}+1) 2^{m-k} \right]$, we write
\begin{equation} \label{20241024eq01}
p=\widetilde{p}2^{m-k}+\beta 2^{\frac{m}{2}-k}+\gamma, 
\end{equation} 
for some $\beta \in \{0, 1, \dots 2^{\frac{m}{2}-1} \}$ and $\gamma \in \left\{0, 1, \dots, 2^{\frac{m}{2}-k}-1 \right\}$. With this, we have\footnote{Here, for notational convenience, we slightly abuse the notation and set $f_1 (\cdot)=f_1 \left(\cdot+\frac{\widetilde{p}}{2^{2k}} \right)$, $f_2 (\cdot)=f_2 \left(\cdot+\frac{\widetilde{p}}{2^{2k}} \right)$ and $\widetilde{\lambda} (\cdot)=\widetilde{\lambda} \left(\cdot+\frac{\widetilde{p}}{2^{2k}} \right)$.}
\begin{eqnarray*}
%
&& {\bf V}_{m, k}^{\widetilde{p}, \calL}(f_1, f_2)=2^{\frac{m}{2}+2k+\del k} \sum_{\beta=0}^{2^{\frac{m}{2}}-1} \sum_{\gamma=0}^{2^{\frac{m}{2}-k}-1}  \sum_{q \sim 2^{\frac{m}{2}}} \int_{I_0^{0, k+m}} \bigg | \int_{I_0^{m, k}} f_1 \left(\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}-\frac{q}{2^{\frac{m}{2}+k}}-t \right) \\
&& \qquad \cdot f_2 \left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}+\frac{2tq}{2^{\frac{m}{2}+k}}+\frac{q^2}{2^{m+2k}} \right)  e^{3i 2^k \frac{q^2 \widetilde{\lambda}\left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}\right)}{2^{\frac{m}{2}}} t} dt \bigg|^2 dx. 
\end{eqnarray*}
We next apply the following change of variables:
\begin{enumerate}
    \item [(1)] $\beta \mapsto \beta-\left\lfloor \frac{q^2}{2^{\frac{m}{2}}} \right\rfloor$;
    \item [(2)] $\gamma \mapsto \gamma-\left\lfloor \left\{\frac{q^2}{2^{\frac{m}{2}}} \right\} 2^{\frac{m}{2}-k} \right\rfloor$;
    \item [(3)] $x \mapsto x-\frac{\left\{\left\{\frac{q^2}{2^{\frac{m}{2}}} \right\} 2^{\frac{m}{2}-k} \right\}}{2^{m+k}}$.
\end{enumerate}
Using\footnote{Recall Remark \ref{Simplif}.} now that $f_1$ is morally constant on intervals of length $2^{-m-k}$ and Cauchy-Schwarz, we deduce
\begin{eqnarray} \label{20241006eq30}
%
&& {\bf V}_{m, k}^{\widetilde{p}, \calL}(f_1, f_2) \lesssim 2^{\frac{m}{2}+2k+\del k} \sum_{q \sim 2^{\frac{m}{2}}} \sum_{\beta=-2^{\frac{m}{2}}}^{2^{\frac{m}{2}}} \sum_{\gamma=-2^{-\frac{m}{2}-k}}^{2^{\frac{m}{2}-k}} \int_{3I_0^{0, k+m}} \nonumber \\
&& \qquad  \Bigg | \int_{I_0^{m, k}} f_1 \left(\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}-\frac{q}{2^{\frac{m}{2}+k}}-t-\frac{q^2}{2^{m+2k}} \right) f_2 \left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}+\frac{2tq}{2^{\frac{m}{2}+k}} \right)  \nonumber \\
&& \qquad \qquad \qquad  \cdot e^{3i 2^k \frac{q^2 \widetilde{\lambda}\left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}-\frac{q^2}{2^{m+2k}}\right)}{2^{\frac{m}{2}}} t} dt \Bigg|^2 dx \nonumber \\
&&\lesssim 2^{\frac{m}{2}+2k+\del k} \calA \calB,
\end{eqnarray}
where 
\begin{eqnarray*}
%
&& \calA^2:=\sum_{q \sim 2^{\frac{m}{2}}} \sum_{\beta=-2^{\frac{m}{2}}}^{2^{\frac{m}{2}}} \sum_{\gamma=-2^{\frac{m}{2}-k}}^{2^{\frac{m}{2}-k}} \iint_{\left(I_0^{m, k} \right)^2} \left| f_1 \left(\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}-\frac{q}{2^{\frac{m}{2}+k}}-t-\frac{q^2}{2^{m+2k}} \right) \right|^2 \\
&& \qquad \qquad \qquad \qquad  \qquad \cdot  \left| f_1 \left(\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}-\frac{q}{2^{\frac{m}{2}+k}}-s-\frac{q^2}{2^{m+2k}} \right) \right|^2 dtds,
\end{eqnarray*}
and
\begin{eqnarray*}
%
&& \calB^2:=\sum_{q \sim 2^{\frac{m}{2}}} \sum_{\beta=-2^{\frac{m}{2}}}^{2^{\frac{m}{2}}} \sum_{\gamma=-2^{\frac{m}{2}-k}}^{2^{\frac{m}{2}-k}} \iint_{\left(I_0^{m, k} \right)^2} \Bigg | \int_{3I_0^{0, k+m}}  f_2 \left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}+\frac{2tq}{2^{\frac{m}{2}+k}} \right) \\
&& \qquad \cdot  f_2 \left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}+\frac{2sq}{2^{\frac{m}{2}+k}} \right) e^{3i 2^k \frac{q^2 \widetilde{\lambda}\left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}-\frac{q^2}{2^{m+2k}}\right)}{2^{\frac{m}{2}}} (t-s)} dx \Bigg |^2 dtds. 
\end{eqnarray*}
We estimate $\calA$ first. Recall that since $f_1$ is uniform, we have $\left\|f_1 \right\|_{L^\infty(3I^k)} \lesssim 2^{\mu k}2^{\frac{k}{2}} \left\|f_1 \right\|_{L^2(3I^k)}$, and hence 
$$
\calA^2 \lesssim 2^{\frac{m}{2}} \cdot 2^{m-k} \cdot 2^{-m-2k} \cdot 2^{4\mu k} \cdot 2^{2k} \cdot \left\|f_1 \right\|^4_{L^2(3I^k)}=2^{\frac{m}{2}-k} \cdot 2^{4\mu k} \left\|f_1 \right\|_{L^2(3I^k)}^4.
$$
Thus, by \eqref{20241006eq30}, one has
\begin{equation} \label{20241008eq43}
{\bf V}_{m, k}^{\widetilde{p}, \calL}(f_1, f_2)\lesssim 2^{\frac{3m}{4}+\frac{3k}{2}+(\del+2\mu)k} \left\|f_1 \right\|_{L^2(3I^k)}^2 \calB.
\end{equation}

\medskip 

\noindent\textsf{Step III: Estimate of $\calB$.} We start by applying the change of variables $t \to \frac{2^{\frac{m}{2}}}{q}t$ and $s \to \frac{2^{\frac{m}{2}}}{q}s$ and then open the square in order to deduce that (with shifting $f_1, f_2$, and $\widetilde{\lambda}$ properly)
\begin{eqnarray*}
%
&& \calB^2 \lesssim \sum_{q \sim 2^{\frac{m}{2}}} \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{\gamma \sim 2^{\frac{m}{2}-k}} \iint_{\left(2I_0^{m, k} \right)^2} \iint_{\left(3I_0^{0, k+m} \right)^2} \\
&& \qquad f_2 \left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}+\frac{2t}{2^k} \right) f_2 \left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}+\frac{2s}{2^k} \right) \\
&& \qquad \cdot  f_2 \left(y+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}+\frac{2t}{2^k} \right)  f_2 \left(y+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}+\frac{2t}{2^k} \right) \\
&& \qquad \cdot e^{3i 2^k q \left[\widetilde{\lambda}\left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}-\frac{q^2}{2^{m+2k}}\right)-\widetilde{\lambda}\left(y+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\gamma}{2^{k+m}}-\frac{q^2}{2^{m+2k}}\right)  \right](t-s)} dxdydtds. 
\end{eqnarray*}

For technical reasoning, taking $\epsilon_3>0$ sufficiently small, we decompose the regime of $\gamma$ as follows:
$$
\left[2^{\frac{m}{2}-k}, 2^{\frac{m}{2}-k+1} \right]=\bigcup_{\widetilde{\gamma} \sim 2^{\epsilon_3 k}} \left[2^{\frac{m}{2}-k-\epsilon_3 k} \widetilde{\gamma}, 2^{\frac{m}{2}-k-\epsilon_3 k}(\widetilde{\gamma}+1) \right].
$$
Using this (by properly shifting the functions again), we have 
\begin{eqnarray*}
%
&& \calB^2 \lesssim \sum_{q \sim 2^{\frac{m}{2}}} \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{\widetilde{\gamma} \sim 2^{\epsilon_3 k} } \sum_{\gamma' \sim 2^{\frac{m}{2}-k-\epsilon_3 k}} \iint_{\left(2I_0^{m, k} \right)^2} \iint_{\left(3I_0^{0, k+m} \right)^2} \\
&& \quad f_2 \left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}+\frac{2t}{2^k} \right) f_2 \left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}+\frac{2s}{2^k} \right)\\
&& \quad \cdot f_2 \left(y+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}+\frac{2t}{2^k} \right)  f_2 \left(y+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}+\frac{2s}{2^k} \right) \\
&& \quad \cdot e^{3i 2^k q \left[\widetilde{\lambda}\left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right)-\widetilde{\lambda}\left(y+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right)  \right](t-s)} dxdydtds. 
\end{eqnarray*}
Next, by applying change variables $t \to t-\frac{\gamma'}{2 \cdot 2^m}-\frac{2^k y}{2}$ and $s \to s-\frac{\gamma'}{2 \cdot 2^m}-\frac{2^k y}{2}$, then up to an admissible error of the form (recall that $0 \le k \le \frac{m}{2}-\epsilon_2 m$)
$$
O\left(2^{\delta k}\,(2^{-\frac{\epsilon_3 k}{2}}+2^{-\frac{\epsilon_2 m}{2}})\left\|f_1 \right\|_{L^2(3I^k)}^2 \left\|f_2 \right\|^2_{L^2(3I^k)} \right), 
$$
one deduces that
\begin{eqnarray*}
%
&& \calB^2 \lesssim \sum_{q \sim 2^{\frac{m}{2}}} \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{\widetilde{\gamma} \sim 2^{\epsilon_3 k} } \sum_{\gamma' \sim 2^{\frac{m}{2}-k-\epsilon_3 k}} \iint_{\left(2I_0^{m, k} \right)^2} \iint_{\left(3I_0^{0, k+m} \right)^2} dxdydtds\\
&&  \quad f_2 \left(x-y+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{2t}{2^k} \right) f_2 \left(x-y+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{2s}{2^k} \right)\\
&& \quad \cdot f_2 \left(\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{2t}{2^k} \right)  f_2 \left(\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{2s}{2^k} \right) \\
&& \quad \cdot e^{3i 2^k q \left[\widetilde{\lambda}\left(x+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right)-\widetilde{\lambda}\left(y+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right)  \right](t-s)}.
\end{eqnarray*}
For technical reasoning again, we need to further decompose the range of $y$ into smaller intervals: let $\epsilon_4>0$ be sufficiently small and write
$$
3I_0^{0, k+m}=\left[0, \frac{3}{2^{k+m}}\right]=\bigcup_{\iota=0}^{3 2^{\epsilon_4 k}-1} \left[\frac{\iota}{2^{k+m+\epsilon_4 k}}, \frac{\iota+1}{2^{k+m+\epsilon_4 k}} \right].
$$
Using the above decomposition (by properly shifting the functions again) followed by the change variable $x \to x+y$, one deduces that 
\begin{eqnarray*}
%
&& \calB^2 \lesssim  \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{\widetilde{\gamma} \sim 2^{\epsilon_3 k} } \sum_{\iota \sim 2^{\epsilon_4 k}} \iint_{2I_0^{m, k} \times 2I_0^{m, k}}  \int_{5I_0^{0, k+m}}    \\
&& \Bigg | f_2 \left(x-\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{2t}{2^k} \right) f_2 \left(\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{2t}{2^k} \right)   \\
&&  \cdot   f_2 \left(x-\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{2s}{2^k} \right) f_2 \left(\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{2s}{2^k} \right) \Bigg | \\
&& \cdot \left| \sum_{q \sim 2^{\frac{m}{2}}} \sum_{\gamma' \sim 2^{\frac{m}{2}-k-\epsilon_3k }} \int_{I_0^{0, k+m+\epsilon_4 k}} e^{3i 2^k q \Bigg[ \substack{\widetilde{\lambda}\left(x+y+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right) \qquad \qquad \quad     \\
\qquad -\widetilde{\lambda}\left(y+\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right)} \Bigg](t-s)} dy \right|  dxdtds 
\end{eqnarray*}
Now, by another change of variable $t \to t+s$ and an application of Cauchy-Schwarz, we derive that
\begin{equation} \label{20241008eq01}
\calB^2 \lesssim \calC \calD, 
\end{equation}
where
\begin{eqnarray*}
%
&& \calC^2:=\sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{\widetilde{\gamma} \sim 2^{\epsilon_3 k} } \sum_{\iota \sim 2^{\epsilon_4 k}} \iint_{4I_0^{m, k} \times 2I_0^{m, k}}  \int_{5I_0^{0, k+m}} \\
&& \Bigg | f_2 \left(x-\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{2(t+s)}{2^k} \right) f_2 \left(\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{2(t+s)}{2^k} \right)   \\
&&  \cdot   f_2 \left(x-\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{2s}{2^k} \right) f_2 \left(\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{2s}{2^k} \right) \Bigg |^2 dx dtds
\end{eqnarray*}
and
\begin{eqnarray*}
%
&& \calD^2:=|I_0^{m, k}|\sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{\widetilde{\gamma} \sim 2^{\epsilon_3 k} } \sum_{\iota \sim 2^{\epsilon_4 k}} \int_{4I_0^{m, k} }  \int_{5I_0^{0, k+m}} \\
&&  \left| \sum_{q \sim 2^{\frac{m}{2}}} \sum_{\gamma' \sim 2^{\frac{m}{2}-k-\epsilon_3k }} \int_{I_0^{0, k+m+\epsilon_4 k}} e^{3i 2^k q \left[ \substack{\widetilde{\lambda}\left(x+y+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right) \qquad \qquad \quad     \\
\qquad -\widetilde{\lambda}\left(y+\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right)} \right]t} dy \right|^2  dxdt. 
\end{eqnarray*}
To this end, we first estimate $\calC$, which is routine since $f_2$ is uniform. More precisely, from \eqref{uniformest}, we have 
\begin{eqnarray*}
\calC^2%
& \lesssim & 2^{\frac{m}{2}} \cdot 2^{\epsilon_3 k} \cdot 2^{\epsilon_4 k} 2^{-m-2k} \cdot 2^{-m-k} \cdot 2^{8\mu k} \cdot 2^{4k} \left\|f_2 \right\|_{L^2(3I^k)}^8 \\
&=& 2^{-\frac{3m}{2}} \cdot 2^k \cdot 2^{\left(8\mu+\epsilon_3+\epsilon_4 \right)k} \left\|f_2 \right\|_{L^2(3I^k)}^8.
\end{eqnarray*}
Thus, using the above with \eqref{20241008eq43} and \eqref{20241008eq01}, we have 
\begin{eqnarray} \label{20241009eq01}
{\bf V}_{m, k}^{\widetilde{p}, \calL}(f_1, f_2)%
&\lesssim& 2^{\frac{3m}{4}+\frac{3k}{2}+(\del+2\mu)k} \left\|f_1 \right\|_{L^2(3I^k)}^2 \cdot 2^{-\frac{3m}{8}} \cdot 2^{\frac{k}{4}} \cdot 2^{\left(2\mu+\frac{\epsilon_3}{4}+\frac{\epsilon_4}{4}\right)k} \left\|f_2 \right\|_{L^2(3I^k)}^2 \calD^{\frac{1}{2}} \nonumber \\
&\lesssim& 2^{\frac{3m}{8}} \cdot 2^{\frac{7k}{4}} \cdot 2^{\left(4\mu+\del+\frac{\epsilon_3+\epsilon_4}{4} \right)k} \left\|f_1\right\|_{L^2(3I^k)}^2 \left\|f_2\right\|_{L^2(3I^k)}^2 \calD^{\frac{1}{2}}.  
\end{eqnarray}

\medskip 

\noindent\textsf{Step IV: The estimate of $\calD$.} We start by opening the square, Fubini, and integrating the $t$-integral, to deduce 
$$
\calD^2 \lesssim \left|I_0^{m, k} \right|^2 \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{\substack{\widetilde{\gamma} \sim 2^{\epsilon_3 k} \\ \iota \sim 2^{\epsilon_4 k}}} \sum_{q, q_1 \sim 2^{\frac{m}{2}}} \sum_{\gamma', \gamma_1' \sim 2^{\frac{m}{2}-k-\epsilon_3 k}} \int_{5I_0^{0, k+m}} \iint_{\left(I_0^{0, k+m+\epsilon_4 k} \right)^2} \Xi_{x, y, y_1, \beta, \iota}^{\widetilde{\gamma}, \gamma', \gamma'_1, 1}(q, q_1) dydy_1dx,
$$
where\footnote{Recall our notation $\llbracket x \rrbracket:=\frac{1}{1+|x|}$.} 
\begin{eqnarray*}
%
&& \Xi_{x, y, y_1, \beta, \iota}^{\widetilde{\gamma}, \gamma', \gamma'_1, 1}(q, q_1):=\vast \llbracket \left[\substack{\widetilde{\lambda}\left(x+y+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right) \qquad \qquad \quad     \\
\qquad -\widetilde{\lambda}\left(y+\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right)} \right] \\
&& \qquad \qquad \qquad \qquad \qquad \qquad \qquad -\frac{q_1}{q} \left[\substack{\widetilde{\lambda}\left(x+y_1+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma_1'}{2^{m+k}}-\frac{q_1^2}{2^{m+2k}}\right) \qquad \qquad \quad     \\
\qquad -\widetilde{\lambda}\left(y_1+\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma_1'}{2^{m+k}}-\frac{q_1^2}{2^{m+2k}}\right)} \right] \vast \rrbracket.
\end{eqnarray*}
Next,  we will glue the $y$-intervals with smaller length $2^{-m-k-\epsilon_3 k}$ in order to form intervals of length $2^{-\frac{m}{2}-2k}$. In order to do so we make use of $\Xi_{x, y, y_1, \beta, \iota}^{\widetilde{\gamma}, \gamma', \gamma'_1, 1}(q, q_1)>0$. With this we apply the change of variable $x \to x+\frac{\iota}{2^{k+m+\epsilon_4 k}}$ and notice that 
\begin{equation} \label{20241010eq01}
\calD^2 \lesssim \left|I_0^{m, k} \right|^2 \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{\substack{\widetilde{\gamma} \sim 2^{\epsilon_3 k} \\ \iota \sim 2^{\epsilon_4 k}}} \sum_{q, q_1 \sim 2^{\frac{m}{2}}} \sum_{\gamma', \gamma_1' \sim 2^{\frac{m}{2}-k-\epsilon_3 k}} \int_{10 I_0^{0, k+m}} \iint_{\left(I_0^{0, k+m+\epsilon_4 k} \right)^2} \Xi_{x, y, y_1, \beta, \iota}^{\widetilde{\gamma}, \gamma', \gamma'_1, 2}(q, q_1) dydy_1dx,
\end{equation} 
where 
\begin{eqnarray*}
%
&& \Xi_{x, y, y_1, \beta, \iota}^{\widetilde{\gamma}, \gamma', \gamma'_1, 2}(q, q_1):=\vast \llbracket \left[\substack{\widetilde{\lambda}\left(x+y+\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right) \qquad \\
\qquad -\widetilde{\lambda}\left(y+\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right)} \right] \\
&& \qquad \qquad \qquad \qquad \qquad \qquad -\frac{q_1}{q} \left[\substack{\widetilde{\lambda}\left(x+y_1+\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma_1'}{2^{m+k}}-\frac{q_1^2}{2^{m+2k}}\right) \qquad \\
\qquad -\widetilde{\lambda}\left(y_1+\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma_1'}{2^{m+k}}-\frac{q_1^2}{2^{m+2k}}\right)} \right] \vast \rrbracket.
\end{eqnarray*}
Now the summation in \eqref{20241010eq01} can be treated as a diagonal sum with respect to the variables $\widetilde{\gamma}$ and $\iota$. Using again the fact that $\Xi_{x, y, y_1, \beta, \iota}^{\widetilde{\gamma}, \gamma', \gamma'_1, 2}(q, q_1)>0$, we derive that
\begin{equation} \label{20241010eq02}
\calD^2 \lesssim \left|I_0^{m, k} \right|^2 \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{\substack{\widetilde{\gamma}, \widetilde{\gamma}_1 \sim 2^{\epsilon_3 k} \\ \iota, \iota_1 \sim 2^{\epsilon_4 k}}} \sum_{q, q_1 \sim 2^{\frac{m}{2}}} \sum_{\gamma', \gamma_1' \sim 2^{\frac{m}{2}-k-\epsilon_3 k}} \int_{10 I_0^{0, k+m}} \iint_{\left(I_0^{0, k+m+\epsilon_4 k} \right)^2} \Xi_{x, y, y_1, \beta, \iota, \iota_1}^{\widetilde{\gamma}, \widetilde{\gamma}_1, \gamma', \gamma'_1}(q, q_1) dydy_1dx,
\end{equation} 
where 
\begin{eqnarray*}
%
&& \Xi_{x, y, y_1, \beta, \iota, \iota_1}^{\widetilde{\gamma}, \widetilde{\gamma}_1, \gamma', \gamma'_1}(q, q_1):=\vast \llbracket \left[\substack{\widetilde{\lambda}\left(x+y+\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right) \qquad \\
\qquad -\widetilde{\lambda}\left(y+\frac{\iota}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma'}{2^{m+k}}-\frac{q^2}{2^{m+2k}}\right]} \right) \\
&& \qquad \qquad \qquad \qquad \qquad \qquad -\frac{q_1}{q} \left[\substack{\widetilde{\lambda}\left(x+y_1+\frac{\iota_1}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}_1}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma_1'}{2^{m+k}}-\frac{q_1^2}{2^{m+2k}}\right) \qquad \\
\qquad -\widetilde{\lambda}\left(y_1+\frac{\iota_1}{2^{k+m+\epsilon_4 k}}+\frac{\beta}{2^{\frac{m}{2}+2k}}+\frac{\widetilde{\gamma}_1}{2^{\frac{m}{2}+2k+\epsilon_3 k}}+\frac{\gamma_1'}{2^{m+k}}-\frac{q_1^2}{2^{m+2k}}\right)} \right] \vast \rrbracket.
\end{eqnarray*}
Summing up the $y, \iota, \gamma'$, and $\widetilde{\gamma}$ variables, as well as the $y_1, \iota_1, \gamma'_1$, and $\widetilde{\gamma}_1$ variables, respectively, we have
\begin{equation} \label{20241010eq20}
\calD^2 \lesssim \left|I_0^{m, k} \right|^2 \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{q, q_1 \sim 2^{\frac{m}{2}}} \int_{10 I_0^{0, k+m}} \iint_{(I_0^{m, 2k})^2} \Xi_{x, y, y_1,  \beta}(q, q_1) dydy_1dx, 
\end{equation} 
where 
\begin{eqnarray*}
%
&& \Xi_{x, y, y_1, \beta}(q, q_1):=\Bigg \llbracket  \left[ \widetilde{\lambda}\left(x+y+\frac{\beta}{2^{\frac{m}{2}+2k}}-\frac{q^2}{2^{m+2k}} \right)-\widetilde{\lambda}\left(y+\frac{\beta}{2^{\frac{m}{2}+2k}}-\frac{q^2}{2^{m+2k}} \right) \right] \\
&& \qquad \qquad \qquad \qquad \qquad \qquad-\frac{q_1}{q} \left[ \widetilde{\lambda}\left(x+y_1+\frac{\beta}{2^{\frac{m}{2}+2k}}-\frac{q_1^2}{2^{m+2k}} \right)-\widetilde{\lambda}\left(y_1+\frac{\beta}{2^{\frac{m}{2}+2k}}-\frac{q_1^2}{2^{m+2k}} \right) \right] \Bigg \rrbracket.
\end{eqnarray*} 
Now, in order to handle \eqref{20241010eq20}, we apply the change of variables $\beta \to \beta+\left\lfloor \frac{q^2}{2^{\frac{m}{2}}} \right \rfloor$ and then $y \to y+\frac{\left\{ \frac{q^2}{2^{\frac{m}{2}}} \right\}}{2^{\frac{m}{2}+2k}}$ and $y_1 \to y_1+\frac{\left\{ \frac{q^2}{2^{\frac{m}{2}}} \right\}}{2^{\frac{m}{2}+2k}}$ to deduce that 
\begin{eqnarray} \label{20240110eq21}
%
&&\calD^2 \lesssim \left|I_0^{m, k} \right|^2 \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{q, q_1 \sim 2^{\frac{m}{2}}} \int_{10 I_0^{0, m+k}} \iint_{(2I_0^{m, 2k})^2} \bigg \llbracket \left[\widetilde{\lambda} \left(x+y+\frac{\beta}{2^{\frac{m}{2}+2k}} \right)-\widetilde{\lambda} \left(y+\frac{\beta}{2^{\frac{m}{2}+2k}} \right) \right] \nonumber \\
&& \quad -\frac{q_1}{q} \left[ \widetilde{\lambda} \left(x+y_1+\frac{\beta}{2^{\frac{m}{2}+2k}}-\frac{q_1^2-q^2}{2^{m+2k}} \right)- \widetilde{\lambda} \left(y_1+\frac{\beta}{2^{\frac{m}{2}+2k}}-\frac{q_1^2-q^2}{2^{m+2k}} \right) \right] \bigg \rrbracket dydy_1 dx.
\end{eqnarray}
Then, letting $u=\left\lfloor \frac{q_1^2-q^2}{2^{\frac{m}{2}}} \right \rfloor$, $y_1 \to y_1+\frac{\left\{\frac{q_1^2-q^2}{2^{\frac{m}{2}}} \right\}}{2^{\frac{m}{2}+2k}}$, and using that $\frac{q_1}{q}=\sqrt{1+\frac{2^{\frac{m}{2}}u}{q^2}+O \left(\frac{1}{2^{\frac{m}{2}}} \right)}$, we reduce \eqref{20240110eq21} to the following estimate:
\begin{eqnarray} \label{20241011eq01}
%
&&\calD^2 \lesssim  \left|I_0^{m, k} \right|^2 \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{q, u \sim 2^{\frac{m}{2}}} \int_{10 I_0^{0, m+k}} \iint_{4I_0^{m , 2k} \times 2I_0^{m, 2k}} \bigg \llbracket \left[\widetilde{\lambda} \left(x+y+\frac{\beta}{2^{\frac{m}{2}+2k}} \right)-\widetilde{\lambda} \left(y+\frac{\beta}{2^{\frac{m}{2}+2k}} \right) \right] \nonumber \\
&& \quad  - \frac{\sqrt{2^{\frac{m}{2}}u+q^2}}{q} \left[ \widetilde{\lambda}\left(x+y_1+\frac{\beta}{2^{\frac{m}{2}+2k}}-\frac{u}{2^{\frac{m}{2}+2k}} \right)-\widetilde{\lambda}\left(y_1+\frac{\beta}{2^{\frac{m}{2}+2k}}-\frac{u}{2^{\frac{m}{2}+2k}} \right) \right] \Bigg \rrbracket dydy_1dx. 
\end{eqnarray}
The treatment of \eqref{20241011eq01} follows now the same reasonings as in \cite[\textsf{Steps IV} and \textsf{V}, Proposition 4.7]{HL23}. For reader's convenience we include below a sketch of the argument: firstly, for notational convenience we set $\widetilde{\lambda}_{\beta}(\cdot)=\widetilde{\lambda} \left(\cdot+\frac{\beta}{2^{\frac{m}{2}+2k}} \right)$ and reduce \eqref{20241011eq01} to
\begin{eqnarray*} 
%
&&\calD^2 \lesssim  \left|I_0^{m, k} \right|^2 \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{q, u \sim 2^{\frac{m}{2}}} \int_{10 I_0^{0, m+k}} \iint_{\left(4I_0^{m , 2k} \right)^2} \bigg \llbracket \left[\widetilde{\lambda}_{\beta} \left(x+y\right)-\widetilde{\lambda}_{\beta} (y) \right] \nonumber \\
&& \qquad \qquad \qquad   - \frac{\sqrt{2^{\frac{m}{2}}u+q^2}}{q} \left[ \widetilde{\lambda}_{\beta}\left(x+y_1-\frac{u}{2^{\frac{m}{2}+2k}} \right)-\widetilde{\lambda}_{\beta}\left(y_1-\frac{u}{2^{\frac{m}{2}+2k}} \right) \right] \Bigg \rrbracket dydy_1dx. 
\end{eqnarray*}
Secondly, we further decompose the $y$ and $y_1$ intervals to smaller intervals of length $2^{-k-m}$, which gives
\begin{eqnarray} \label{20241011eq30}
%
&&\calD^2 \lesssim \left|I_0^{m, k} \right|^2 \sum_{\beta \sim 2^{\frac{m}{2}}}  \sum_{q, u \sim 2^{\frac{m}{2}}} \sum_{\gamma, \gamma_1 \sim 2^{\frac{m}{2}-k}} \int_{10 I_0^{0, m+k}} \iint_{\left(I_0^{0 , m+k} \right)^2} \bigg \llbracket \left[\widetilde{\lambda}_{\beta,\gamma} \left(x+y\right)-\widetilde{\lambda}_{\beta,\gamma} (y) \right] \nonumber \\
&& \qquad \qquad \qquad   - \frac{\sqrt{2^{\frac{m}{2}}u+q^2}}{q} \left[ \widetilde{\lambda}_{\beta,\gamma_1}\left(x+y_1-\frac{u}{2^{\frac{m}{2}+2k}} \right)-\widetilde{\lambda}_{\beta,\gamma_1}\left(y_1-\frac{u}{2^{\frac{m}{2}+2k}} \right) \right] \Bigg \rrbracket dydy_1dx, 
\end{eqnarray}
where $\widetilde{\lambda}_{\beta,\gamma}(\cdot)=\widetilde{\lambda}_{\beta} \left(\cdot+\frac{\gamma}{2^{m+k}} \right)$. Next, we apply the change of variables $y_1 \to y_1+y$, $x \to x-y$ to derive 
\begin{eqnarray} \label{20241011eq10}
%
&&\calD^2 \lesssim  \left|I_0^{m, k} \right|^2 \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{q, u \sim 2^{\frac{m}{2}}} \sum_{\gamma, \gamma_1 \sim 2^{\frac{m}{2}-k}} \iint_{\left(20 I_0^{0, m+k}\right)^2} \bigg\{ \int_{2I_0^{0 , m+k}} \bigg \llbracket \left[\widetilde{\lambda}_{\beta,\gamma} \left(x\right)-\widetilde{\lambda}_{\beta,\gamma} (y) \right] \nonumber \\
&& \qquad \qquad  - \frac{\sqrt{2^{\frac{m}{2}}u+q^2}}{q} \left[ \widetilde{\lambda}_{\beta,\gamma_1}\left(x+y_1-\frac{u}{2^{\frac{m}{2}+2k}} \right)-\widetilde{\lambda}_{\beta,\gamma_1}\left(y+y_1-\frac{u}{2^{\frac{m}{2}+2k}} \right) \right] \Bigg \rrbracket dy_1 \bigg\} dydx. 
\end{eqnarray}
Fix momentarily $\beta$, $\gamma$ and recall that $\widetilde{\lambda}_{\beta,\gamma}  (\cdot)$ is \emph{light} on each interval of the length $2^{-m-k}$ due to our assumptions - see \eqref{20241011eq40}). Next, we decompose both $x$ and $y$ intervals in the above estimate as follows
$$
20I_0^{0, k+m}=\bigcup_{l \in \widetilde{\calL}_{\beta,\gamma}} \widetilde{\frakM_{l, \beta, \gamma}} \left(20I_0^{0, k+m} \right),
$$
where 
$$
\widetilde{\frakM_{l,\beta, \gamma}} \left(20I_0^{0, k+m} \right):=\left\{x \in 20I_0^{0, k+m}: \widetilde{\lambda}_{\beta,\gamma}(x) \in \left[l2^{\epsilon_0 k}, (l+1)2^{\epsilon_0 k} \right] \right\},
$$
and 
$$
\widetilde{\calL}_{\beta,\gamma}:=\left\{l \sim 2^{\frac{m}{2}-\epsilon_0 k}: \left| \widetilde{\frakM_{l,\beta, \gamma}} \left(20I_0^{0, k+m} \right) \right| \lesssim \left|I_0^{0, k+m} \right| 2^{-\epsilon_0 k} \right\}.
$$
With these, one can write \eqref{20241011eq10} as 
$$
\calD^2 \lesssim \calD_{\textnormal{diag}}^2+\calD_{\textnormal{off}}^2, 
$$
where 
\begin{eqnarray*}
%
&&\calD_{\textnormal{diag}}^2:= \left|I_0^{m, k} \right|^2 \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{q, u \sim 2^{\frac{m}{2}}} \sum_{\gamma, \gamma_1 \sim 2^{\frac{m}{2}-k}} \sum_{\substack{l, l_1 \in \widetilde{\calL}_{\beta,\gamma} \\ |l-l_1| \le 10}} \iint_{\widetilde{\frakM_{l,\beta,\gamma}} \left(20I_0^{0, k+m} \right) \times \widetilde{\frakM_{l_1,\beta,\gamma}} \left(20I_0^{0, k+m} \right)} \nonumber \\
&& \quad \left\{ \int_{2I_0^{0 , m+k}} \bigg \llbracket \left[\widetilde{\lambda}_{\beta,\gamma} \left(x\right)-\widetilde{\lambda}_{\beta,\gamma} (y) \right] - \frac{\sqrt{2^{\frac{m}{2}}u+q^2}}{q} \left[ \widetilde{\lambda}_{\beta,\gamma_1}\left(x+y_1-\frac{u}{2^{\frac{m}{2}+2k}} \right)-\widetilde{\lambda}_{\beta,\gamma_1}\left(y+y_1-\frac{u}{2^{\frac{m}{2}+2k}} \right) \right] \Bigg \rrbracket dy_1 \right\} dydx. 
\end{eqnarray*}
and
\begin{eqnarray*}
%
&&\quad\calD_{\textnormal{off}}^2:=  \left|I_0^{m, k} \right|^2 \sum_{\beta \sim 2^{\frac{m}{2}}} \sum_{q, u \sim 2^{\frac{m}{2}}} \sum_{\gamma, \gamma_1 \sim 2^{\frac{m}{2}-k}} \sum_{\substack{l, l_1 \in \widetilde{\calL}_{\beta,\gamma} \\ |l-l_1|>10}} \iint_{\widetilde{\frakM_{l,\beta, \gamma}} \left(20I_0^{0, k+m} \right) \times \widetilde{\frakM_{l_1, \beta, \gamma}} \left(20I_0^{0, k+m} \right)} \nonumber \\
&&\left\{ \int_{2I_0^{0 , m+k}} \bigg \llbracket \left[\widetilde{\lambda}_{\beta,\gamma} \left(x\right)-\widetilde{\lambda}_{\beta,\gamma} (y) \right] - \frac{\sqrt{2^{\frac{m}{2}}u+q^2}}{q} \left[ \widetilde{\lambda}_{\beta,\gamma_1}\left(x+y_1-\frac{u}{2^{\frac{m}{2}+2k}} \right)-\widetilde{\lambda}_{\beta,\gamma_1}\left(y+y_1-\frac{u}{2^{\frac{m}{2}+2k}} \right) \right] \Bigg \rrbracket dy_1 \right\} dydx. 
\end{eqnarray*}
The analysis now reduces to the estimates of the terms $\calD_{\textnormal{diag}}^2$ and $\calD_{\textnormal{off}}^2$: the estimate of $\calD_{\textnormal{diag}}^2$ yields a decay of the form $2^{\left(\del+4\mu-\frac{\epsilon_0}{4} \right)k} \left\|f_1 \right\|_{L^2(3I^k)}^2 \left\|f_2 \right\|_{L^2(3I^k)}^2$, while in estimating the second term $\calD_{\textnormal{off}}^2$ the key ingredient is the usage of the curvature within the mapping 
$$
\left[2^{\frac{m}{2}}, 2^{\frac{m}{2}+1} \right] \ni q \mapsto  \frac{\sqrt{2^{\frac{m}{2}}u+q^2}}{q} \in \left [\frac{1}{10}, 10 \right]. 
$$
(see, the argument in \cite[(4.60)-(4.66)]{HL23}). We leave the further details to the interested reader. 
\end{proof}

\subsection{Treatment of the uniform component ${\bf L}_{m, k}^{\calU_\mu}(f_1, f_2)$: Case II, Step II.2 in Overview} \label{20250228sec03}

In the previous section, we have employed the constancy propagation method -- a key idea originating in the work \cite{HL23}; specifically, we were able to extend the length of constancy for the measurable function $\widetilde{\lambda}$ from the original scale $2^{-m-2k}$ to the larger scale $2^{-m-k}$. As a consequence, with the language provided by \eqref{20241011eq32}, we are now left with treating the case when all intervals $I_p^{0, m+k}$ are \emph{heavy}. Thus, up to an admissible $2^{2\epsilon_0 k}$--loss (involving some standard extension arguments) we may assume from now on that 
\begin{equation} \label{20241012eq01}
\textnormal{\texttt{$\widetilde{\lambda} (\cdot)$ takes constant values on intervals $\left\{I_\ell^{0, m+k}\right\}_{\ell \sim 2^m}$.}} \tag{{\bf H2}}
\end{equation}
The result below represents the rigorous embodiment of the first part of \ref{KH2}:

\begin{prop}
Let $k, m \in \N$, with $0 \le k \le \frac{m}{2}$, and 
\begin{equation} \label{20241012eq19}
\Lambda_m^k(f_1, f_2, f_3):=2^k\int_{I^k} \int_{I^k} f_1(x-t)f_2(x+t^2)f_3(x)e^{i 2^{\frac{m}{2}+3k} \widetilde{\lambda}(x) t^3} dtdx, 
\end{equation} 
with $\widetilde{\lambda}$ satisfying the assumption \eqref{20241012eq01}. Then there exists an $\epsilon_5>0$, such that 
\begin{equation} \label{20241012eq20}
\left|\Lambda_m^k(f_1, f_2, f_3) \right| \lesssim 2^{-\epsilon_5 k}  \prod_{j=1}^3 \left\|f_j \right\|_{L^{p_j}(3I^k)},
\end{equation} 
whenever $(p_1, p_2, p_3)=(2, 2, \infty), (2, \infty, 2)$ or $(\infty, 2, 2)$. 
\end{prop}

We divide the proof of \eqref{20241012eq20} into four stages. 

\subsubsection{Discretization} We begin by discretizing the model \eqref{20241012eq19} via the Rank-I LGC methodology:

\medskip 

\noindent \textsf{Step I: Linearization.}
\begin{enumerate}
    \item [$\bullet$] for $f_1(x-t)$, we use discretization in spatial intervals of length $2^{-\frac{m}{2}-k}$;
    \item  [$\bullet$] for $f_2(x+t^2)$, we use discretization in spatial intervals of length $2^{-\frac{m}{2}-2k}$. 
\end{enumerate}

\medskip 

\noindent \textsf{Step II: Gabor frame decomposition.}
Guided by the spatial decomposition in \textsf{Step I}, we write
\begin{equation} \label{20240726eq03}
f_j=\sum_{\substack{p_j \sim 2^{\frac{m}{2}+(j-1)k} \\ n_j  \sim 2^{\frac{m}{2}}}} \left \langle f_j, \phi_{p_j, n_j}^{jk} \right \rangle \phi_{p_j, n_j}^{jk}, \quad j=1, 2, 
\end{equation} 
where $\phi_{r, n}^{jk}(x):=2^{\frac{m}{4}+\frac{jk}{2}} \phi \left(2^{\frac{m}{2}+jk}x-r \right) e^{i2^{\frac{m}{2}+jk}xn}$, with $\phi$ being a smooth cut-off function supported away from the origin. 

Plugging \eqref{20240726eq03} to \eqref{20241012eq19}, we see that
\begin{eqnarray*}
%
&& \Lambda_m^k(f_1, f_2, f_3)=2^k \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{\substack{p_1 \sim 2^{\frac{m}{2}} \\ n_1 \sim 2^{\frac{m}{2}}}} \sum_{\substack{p_2 \sim 2^{\frac{m}{2}+k} \\ n_2 \sim 2^{\frac{m}{2}}}} \left \langle f_1, \phi_{p_1, n_1}^{k} \right \rangle \left \langle f_2, \phi_{p_2, n_2}^{2k} \right \rangle \\
&& \qquad \qquad \cdot \int_{I_p^{m, 2k}} \int_{I_q^{m, k}} \phi_{p_1, n_1}^k(x-t)\phi_{p_2, n_2}^{2k}(x+t^2) f_3(x) e^{i 2^{\frac{m}{2}+3k} \widetilde{\lambda}(x)t^3}dtdx.
\end{eqnarray*}
Note that for $t \in I_q^{m, k}$, one has $2^{\frac{m}{2}+3k}\widetilde{\lambda}(x) t^3=\frac{3q^2t\widetilde{\lambda}(x)}{2^{\frac{m}{2}-k}}-\frac{2q^3\widetilde{\lambda}(x)}{2^m}+O(1)$. With this, we have
\begin{eqnarray*}
%
&& \Lambda_m^k(f_1, f_2, f_3)=2^k \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{\substack{p_1 \sim 2^{\frac{m}{2}} \\ n_1 \sim 2^{\frac{m}{2}}}} \sum_{\substack{p_2 \sim 2^{\frac{m}{2}+k} \\ n_2 \sim 2^{\frac{m}{2}}}} \left \langle f_1, \phi_{p_1, n_1}^{k} \right \rangle \left \langle f_2, \phi_{p_2, n_2}^{2k} \right \rangle \\
&& \qquad \quad \cdot \int_{I_p^{m, 2k}} \int_{I_q^{m, k}} \phi_{p_1, n_1}^k(x-t)\phi_{p_2, n_2}^{2k}(x+t^2) f_3(x)  e^{-2i \cdot \frac{q^3 \widetilde{\lambda}(x)}{2^m}}  \cdot e^{3i \cdot \frac{q^2 \widetilde{\lambda}(x)}{2^{\frac{m}{2}-k}} t} dtdx.
\end{eqnarray*}
Since $0 \le k \le \frac{m}{2}$, one has $\left| I_p^{m, 2k} \right|=\frac{1}{2^{\frac{m}{2}+2k}} \ge \frac{1}{2^{m+k}}$.
This yields the following decomposition: 
\begin{eqnarray} \label{20250228eq01}
I_p^{m, 2k}%
&=& \left[\frac{p}{2^{\frac{m}{2}+2k}}, \frac{p+1}{2^{\frac{m}{2}+2k}} \right]=\left[\frac{2^{\frac{m}{2}-k}p}{2^{m+k}},  \frac{2^{\frac{m}{2}-k}(p+1)}{2^{m+k}}\right] \nonumber \\
&=& \bigcup_{\widetilde{p}=0}^{2^{\frac{m}{2}-k}-1} \left[ \frac{2^{\frac{m}{2}-k}p+\widetilde{p}}{2^{m+k}}, \frac{2^{\frac{m}{2}-k}p+\widetilde{p}+1}{2^{m+k}} \right]=\bigcup_{\widetilde{p}=0}^{2^{\frac{m}{2}-k}-1} I_{2^{\frac{m}{2}-k}p+\widetilde{p}}^{0, m+k}. 
\end{eqnarray} 
Furthermore, by denoting $\psi_{r, n}^k(x):=2^{\frac{m+k}{2}} \phi\left(2^{m+k}x-r\right) e^{i2^{m+k}xn}$, we have 
\begin{eqnarray*}
%
&& \Lambda_m^k(f_1, f_2, f_3)=2^k \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{\substack{p_1 \sim 2^{\frac{m}{2}} \\ n_1 \sim 2^{\frac{m}{2}}}} \sum_{\substack{p_2 \sim 2^{\frac{m}{2}+k} \\ n_2 \sim 2^{\frac{m}{2}}}} \left \langle f_1, \phi_{p_1, n_1}^{k} \right \rangle \left \langle f_2, \phi_{p_2, n_2}^{2k} \right \rangle \\
&& \qquad  \cdot \sum_{\widetilde{p}=0}^{2^{\frac{m}{2}-k}-1} \int_{I_{2^{\frac{m}{2}-k}p+\widetilde{p}}^{0, m+k}} \int_{I_q^{m, k}} \phi_{p_1, n_1}^k(x-t)\phi_{p_2, n_2}^{2k}(x+t^2) f_3(x) e^{-2i \cdot \frac{q^3 \widetilde{\lambda}(x)}{2^m}}  \cdot e^{3i \cdot \frac{q^2 \widetilde{\lambda}(x)}{2^{\frac{m}{2}-k}} t} dtdx.
\end{eqnarray*}
With a slight notational abuse, we now write 
$$
\widetilde{\lambda}: \left[2^m, 2^{m+1} \right] \cap \Z \mapsto \left[2^\frac{m}{2}, 2^{\frac{m}{2}+1} \right] \cap \Z , \qquad \textnormal{with} \quad \widetilde{\lambda}(p'):=\widetilde{\lambda} \left(\frac{p'}{2^{m+k}} \right).
$$
Making now use of \eqref{20241012eq01}, we deduce  
\begin{eqnarray*}
%
&& \Lambda_m^k(f_1, f_2, f_3) \simeq 2^k \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{\substack{p_1 \sim 2^{\frac{m}{2}} \\ n_1 \sim 2^{\frac{m}{2}}}} \sum_{\substack{p_2 \sim 2^{\frac{m}{2}+k} \\ n_2 \sim 2^{\frac{m}{2}}}} \left \langle f_1, \phi_{p_1, n_1}^{k} \right \rangle \left \langle f_2, \phi_{p_2, n_2}^{2k} \right \rangle  \sum_{\widetilde{p}=0}^{2^{\frac{m}{2}-k}-1} e^{-2i \cdot \frac{q^3 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{m}}}  \\
&&\qquad \qquad \qquad \qquad \cdot \int_{I_{2^{\frac{m}{2}-k}p+\widetilde{p}}^{0, m+k}} \int_{I_q^{m, k}} \phi_{p_1, n_1}^k(x-t)\phi_{p_2, n_2}^{2k}(x+t^2) f_3(x)  e^{3i \cdot \frac{q^2 \widetilde{\lambda}\left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}} t} dtdx \\
&&  \quad  \simeq 2^{2k} \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{\substack{p_1 \sim 2^{\frac{m}{2}} \\ n_1 \sim 2^{\frac{m}{2}}}} \sum_{\substack{p_2 \sim 2^{\frac{m}{2}+k} \\ n_2 \sim 2^{\frac{m}{2}}}} \left \langle f_1, \phi_{p_1, n_1}^{k} \right \rangle \left \langle f_2, \phi_{p_2, n_2}^{2k} \right \rangle\sum_{\widetilde{p}=0}^{2^{\frac{m}{2}-k}-1}e^{-2i \cdot \frac{q^3 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{m}}}  \\
&&\qquad \qquad \cdot \int_{I_{2^{\frac{m}{2}-k}p+\widetilde{p}}^{0, m+k}} \int_{I_q^{m, k}} 2^{\frac{m+k}{2}} \phi \left(2^{\frac{m}{2}+k}(x-t)-p_1 \right) \phi \left(2^{\frac{m}{2}+2k} \left(x+t^2 \right)-p_2 \right) \\
&& \qquad \qquad \qquad \qquad  \qquad \qquad   \cdot e^{i 2^{\frac{m}{2}+k}(x-t)n_1} e^{i2^{\frac{m}{2}+2k}(x+t^2)n_2} f_3(x)  e^{3i \cdot \frac{q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}} t} dtdx.
\end{eqnarray*}
Since $x \in I_{2^{\frac{m}{2}-k}p+\widetilde{p}}^{0, m+k} \subseteq I_p^{m, 2k}$ and $t \in I_q^{m, k}$, we have 
\begin{equation} 
p_1 \cong \frac{p}{2^k}-q \quad \textrm{and} \quad p_2 \cong p+\frac{q^2}{2^{\frac{m}{2}}}. \tag{\textnormal{\textbf{Time Correlation}}}
\end{equation} 
Hence, 
\begin{eqnarray*}
%
&& \Lambda_m^k(f_1, f_2, f_3)  \simeq 2^{2k}  \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{n_1, n_2 \sim 2^{\frac{m}{2}}} \left \langle f_1, \phi_{\frac{p}{2^k}-q, n_1}^{k} \right \rangle \left \langle f_2, \phi_{p+\frac{q^2}{2^{\frac{m}{2}}}, n_2}^{2k} \right \rangle \sum_{\widetilde{p}=0}^{2^{\frac{m}{2}-k}-1}  e^{-2i \cdot \frac{q^3 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{m}}}  \\
&& \qquad \quad \cdot \int_{I_{2^{\frac{m}{2}-k}p+\widetilde{p}}^{0, m+k}} 2^{\frac{m+k}{2}}  e^{i\left(2^{\frac{m}{2}+k}n_1+2^{\frac{m}{2}+2k} n_2 \right)x} f_3(x) \cdot \left[ \int_{I_q^{m, k}} e^{it \left(-2^{\frac{m}{2}+k}n_1+ \frac{3q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}} \right)+i2^{\frac{m}{2}+2k}n_2t^2} dt \right] dx
\end{eqnarray*}
Note that for $t \in I_q^{m, k}$, $2^{\frac{m}{2}+2k}n_2t^2 \simeq 2^{\frac{m}{2}+2k} n_2 \left(\frac{2tq}{2^{\frac{m}{2}+k}}-\frac{q^2}{2^{m+2k}} \right)+O(1)$, and therefore,
\begin{eqnarray*}
%
&& \Lambda_m^k(f_1, f_2, f_3) \simeq 2^{2k}  \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{n_1, n_2 \sim 2^{\frac{m}{2}}} \left \langle f_1, \phi_{\frac{p}{2^k}-q, n_1}^{k} \right \rangle \left \langle f_2, \phi_{p+\frac{q^2}{2^{\frac{m}{2}}}, n_2}^{2k} \right \rangle \sum_{\widetilde{p}=0}^{2^{\frac{m}{2}-k}-1}  e^{-2i \cdot \frac{q^3 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{m}}} \\
&& \quad \cdot e^{-i2^{\frac{m}{2}}n_2 \cdot \frac{q^2}{2^m}} \int_{I_{2^{\frac{m}{2}-k}p+\widetilde{p}}^{0, m+k}} 2^{\frac{m+k}{2}} e^{i 2^{m+k} \left(\frac{n_1}{2^{\frac{m}{2}}}+\frac{2^kn_2}{2^{\frac{m}{2}}} \right)} f_3(x) \cdot \left[\int_{I_q^{m, k}} e^{it \left(-2^{\frac{m}{2}+k}n_1+2^{\frac{m}{2}+k} \cdot \frac{2q}{2^{\frac{m}{2}}}n_2+ \frac{3q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}}  \right)} dt \right] dx \\
&& \quad \simeq 2^{2k}  \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{n_1, n_2 \sim 2^{\frac{m}{2}}} \left \langle f_1, \phi_{\frac{p}{2^k}-q, n_1}^{k} \right \rangle \left \langle f_2, \phi_{p+\frac{q^2}{2^{\frac{m}{2}}}, n_2}^{2k} \right \rangle \cdot \sum_{\widetilde{p}=0}^{2^{\frac{m}{2}-k}-1}  e^{-2i \cdot \frac{q^3 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{m}}} e^{-i2^{\frac{m}{2}}n_2 \cdot \frac{q^2}{2^m}} \\
&& \qquad \qquad \cdot \left\langle f_3, \psi_{2^{\frac{m}{2}-k}p+\widetilde{p}, \frac{n_1}{2^{\frac{m}{2}}}+\frac{2^kn_2}{2^{\frac{m}{2}}}}^k \right \rangle  \int_{I_q^{m, k}} e^{it \left(-2^{\frac{m}{2}+k}n_1+2^{\frac{m}{2}+k} \cdot \frac{2q}{2^{\frac{m}{2}}}n_2+ \frac{3q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}}  \right)} dt.
\end{eqnarray*}
Observe that the above equation gives the following:
\begin{enumerate}
    \item \underline{frequency information of $f_3$}: this follows from the Gabor frame corresponding to $f_3$, which implies
    \begin{equation}
        n_3 \cong \frac{n_1}{2^{\frac{m}{2}}}+\frac{2^k n_2}{2^{\frac{m}{2}}} \cong  \frac{2^k n_2}{2^{\frac{m}{2}}}  \tag{{\bf Frequency Correlation}}
    \end{equation}
    \item \underline{time-frequency correlation between $p, q, n_1$ and $n_2$}: this follows from maximizing the $t$-integral. More precisely, we have 
    \begin{eqnarray*}
    %
    && \int_{I_q^{m, k}} e^{it \left(-2^{\frac{m}{2}+k}n_1+2^{\frac{m}{2}+k} \cdot \frac{2q}{2^{\frac{m}{2}}}n_2+\frac{3q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}} \right)} dt \\
    && \quad =\int_{I_0^{m, k}} e^{i \left(t+\frac{q}{2^{\frac{m}{2}+k}} \right) \left(-2^{\frac{m}{2}+k}n_1+2^{\frac{m}{2}+k} \cdot \frac{2q}{2^{\frac{m}{2}}}n_2+\frac{3q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}} \right)} dt \\
    && \quad  =C_{p, \widetilde{p}, q, n_1, n_2} \cdot \int_{I_0^{m, k}} e^{i t \left(-2^{\frac{m}{2}+k}n_1+2^{\frac{m}{2}+k} \cdot \frac{2q}{2^{\frac{m}{2}}}n_2+\frac{3q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}} \right)} dt \\
    && \quad =\frac{C_{p, \widetilde{p}, q, n_1, n_2}}{2^{\frac{m}{2}+k}} \int_0^1 e^{it \left(-n_1+\frac{2qn_2}{2^{\frac{m}{2}}}+\frac{3q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^m} \right)}dt,
    \end{eqnarray*}
    where $C_{p, \widetilde{p}, q, n_1, n_2}:=e^{i\frac{q}{2^{\frac{m}{2}+k}} \left(-2^{\frac{m}{2}+k}n_1+2^{\frac{m}{2}+k} \cdot \frac{2q}{2^{\frac{m}{2}}}n_2+\frac{3q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}} \right) }$. As a consequence, we see that, for fixed $p \sim 2^{\frac{m}{2}+k}$, $\widetilde{p} \sim 2^{\frac{m}{2}-k}$,  and $q \sim 2^{\frac{m}{2}}$, the main contribution of the $t$-integral arises when the pair $(n_1, n_2)$ belongs to the \emph{time-frequency correlation set}
    \begin{equation}
        {\textnormal{\textbf{TFC}}}_{p, \widetilde{p}, q}:=\left\{\substack{(n_1, n_2) \\ n_1, n_2 \sim 2^{\frac{m}{2}}}: n_1-\frac{2qn_2}{2^{\frac{m}{2}}}-\frac{3q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^m} \cong 0 \right\}. \tag{\bf{Time Frequency Correlation set}}
    \end{equation}
\end{enumerate}
Utilizing all the time-frequency correlations, we see that
\begin{eqnarray*}
%
&& \Lambda_m^k(f_1, f_2, f_3) \simeq  2^{k-\frac{m}{2}}  \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{\widetilde{p}=0}^{2^{\frac{m}{2}-k}-1} \sum_{(n_1, n_2) \in {\textnormal{\textbf{TFC}}}_{p, \widetilde{p}, q} }  C_{\phi, p, \widetilde{p}, q, n_1, n_2} \nonumber \\
&& \qquad \qquad \qquad  \cdot \left \langle f_1, \phi_{\frac{p}{2^k}-q, n_1}^{k} \right \rangle \left \langle f_2, \phi_{p+\frac{q^2}{2^{\frac{m}{2}}}, n_2}^{2k} \right \rangle \left\langle f_3, \psi_{2^{\frac{m}{2}-k}p+\widetilde{p}, \frac{2^kn_2}{2^{\frac{m}{2}}}}^k \right \rangle , 
\end{eqnarray*}
where $C_{\phi, p, q, n_1, n_2}= e^{-2i \cdot \frac{q^3 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^m}}\cdot e^{i2^{\frac{m}{2}}n_2 \cdot \frac{q^2}{2^{m}}} \cdot C_{p, \widetilde{p}, q, n_1, n_2}$. 

This way we obtain the \emph{wave packet discretized (absolute summable) model} of the form $\Lambda_m^k(f_1, f_2, f_3)$ as 
\begin{eqnarray}  \label{20241013eq21}
&& \left(\Lambda_m^k \right)^*(f_1, f_2, f_3):=2^{k-\frac{m}{2}}  \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{\widetilde{p} \sim 2^{\frac{m}{2}-k}} \sum_{n_2 \sim 2^{\frac{m}{2}}}  \left| \left \langle f_1, \phi_{\frac{p}{2^k}-q, \frac{2qn_2}{2^{\frac{m}{2}}}+\frac{3q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^m}}^{k} \right \rangle \right| \nonumber \\
&& \qquad \qquad \qquad \qquad \qquad \qquad  \cdot \left| \left \langle f_2, \phi_{p+\frac{q^2}{2^{\frac{m}{2}}}, n_2}^{2k} \right \rangle \right| \left| \left\langle f_3, \psi_{2^{\frac{m}{2}-k}p+\widetilde{p}, \frac{2^kn_2}{2^{\frac{m}{2}}}}^k \right \rangle \right|.
\end{eqnarray}

\subsubsection{A time-frequency sparse-uniform dichotomy.} 
We move now our focus on the term \eqref{20241013eq21}. First, we decompose the regime of $n_2$ into intervals of length $2^{\frac{m}{2}-k}$:
$$
\left\{n_2 \sim 2^{\frac{m}{2}} \right\}=\bigcup_{\widetilde{n_2} \sim 2^k} \left[\widetilde{n_2}2^{\frac{m}{2}-k}, \left(\widetilde{n_2}+1 \right)2^{\frac{m}{2}-k} \right], 
$$
which yields 
\begin{eqnarray} \label{20241013eq50}
&& \left(\Lambda_m^k \right)^*(f_1, f_2, f_3)=2^{k-\frac{m}{2}}  \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{\widetilde{p} \sim 2^{\frac{m}{2}-k}} \sum_{\substack{\widetilde{n_2} \sim 2^k \\ r \sim 2^{\frac{m}{2}-k}}}  \left| \left \langle f_1, \phi_{\frac{p}{2^k}-q, \frac{2q\left(2^{\frac{m}{2}-k}\widetilde{n_2}+r \right)}{2^{\frac{m}{2}}}+\frac{3q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^m}}^{k} \right \rangle \right| \nonumber \\
&& \qquad \qquad \qquad \qquad \qquad \qquad  \cdot \left| \left \langle f_2, \phi_{p+\frac{q^2}{2^{\frac{m}{2}}}, 2^{\frac{m}{2}-k}\widetilde{n_2}+r}^{2k} \right \rangle \right| \left| \left\langle f_3, \psi_{2^{\frac{m}{2}-k}p+\widetilde{p}, \widetilde{n_2}}^k \right \rangle \right| \nonumber  \\
&& \quad \lesssim 2^{k-\frac{m}{2}}  \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{\substack{\widetilde{p} \sim 2^{\frac{m}{2}-k} \\ \widetilde{n_2} \sim 2^k}} \left| \left\langle f_3, \psi_{2^{\frac{m}{2}-k}p+\widetilde{p}, \widetilde{n_2}}^k \right \rangle \right| \cdot \left(\sum_{r \sim 2^{\frac{m}{2}-k}} \left| \left \langle f_2, \phi_{p+\frac{q^2}{2^{\frac{m}{2}}}, 2^{\frac{m}{2}-k}\widetilde{n_2}+r}^{2k} \right \rangle \right|^2 \right)^{\frac{1}{2}} \nonumber \\
&& \qquad \qquad \qquad \qquad \qquad \qquad  \cdot \left( \sum_{r \sim 2^{\frac{m}{2}-k}}  \left| \left \langle f_1, \phi_{\frac{p}{2^k}-q, \frac{2q\left(2^{\frac{m}{2}-k}\widetilde{n_2}+r \right)}{2^{\frac{m}{2}}}+\frac{3q^2 \widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^m}}^{k} \right \rangle \right|^2 \right)^{\frac{1}{2}}. 
\end{eqnarray}
For $L_1, L_2 \sim 2^k$, denote 
$$
\Omega_1^{L_1}:=\left[L_1 2^m, (L_1+1)2^m \right] \quad \textrm{and} \quad \Omega_2^{L_2}:=\left[L_2 2^{m+k}, (L_2+1)2^{m+k} \right], 
$$
and also let $f^{\Omega_j^{L_j}}$ be the frequency projection onto $\Omega_j^{L_j}$:
$$
f^{\Omega_j^{L_j}}(x):=\int_\R \widehat{f}(\xi) \chi \left( \frac{\xi-L_j2^{m+(j-1)k}}{|\Omega_j^{L_j}|} \right)e^{i\xi x}d\xi, \quad j=1, 2,
$$
for $\chi$ being a smooth cut-off with $\supp \chi \subset \left[\frac{1}{2}, 2 \right]$. 

Applying Parseval, we further estimate \eqref{20241013eq50} by 
\begin{eqnarray} \label{20241014eq01}
&& \left(\Lambda_m^k \right)^*(f_1, f_2, f_3) \lesssim 2^{k-\frac{m}{2}}  \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ q \sim 2^{\frac{m}{2}}}} \sum_{\substack{\widetilde{p} \sim 2^{\frac{m}{2}-k} \\ \widetilde{n_2} \sim 2^k}} \left| \left\langle f_3, \psi_{2^{\frac{m}{2}-k}p+\widetilde{p}, \widetilde{n_2}}^k \right \rangle \right| \left\|f_2^{\Omega_2^{\widetilde{n_2}}} \right\|_{L^2 \left(I^{m, 2k}_{p+\frac{q^2}{2^{\frac{m}{2}}}} \right)} \nonumber \\
&& \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \cdot \left\| f_1^{\Omega_1^{\frac{2q\widetilde{n_2}}{2^{\frac{m}{2}}}+\frac{3q^2}{2^m} \cdot \frac{\widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}}}} \right\|_{L^2 \left(I^{m, k}_{\frac{p}{2^k}-q} \right)}.
\end{eqnarray}
Next, we decompose the regime of $q$ into intervals of length $2^{\frac{m}{2}-k}$
$$
\left\{q \sim 2^{\frac{m}{2}} \right\}=\bigcup_{\widetilde{q} \sim 2^k} \left[ \widetilde{q} 2^{\frac{m}{2}-k}, \left(\widetilde{q}+1 \right)2^{\frac{m}{2}-k} \right], 
$$
and notice that via Cauchy-Schwarz, \eqref{20241014eq01} becomes 
\begin{eqnarray} \label{20241014eq56}
&& \left(\Lambda_m^k \right)^*(f_1, f_2, f_3) \lesssim 2^{k-\frac{m}{2}}  \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ \widetilde{q} \sim 2^k}} \sum_{\substack{\widetilde{p} \sim 2^{\frac{m}{2}-k} \\ \widetilde{n_2} \sim 2^k}} \sum_{s \sim 2^{\frac{m}{2}-k}}  \left| \left\langle f_3, \psi_{2^{\frac{m}{2}-k}p+\widetilde{p}, \widetilde{n_2}}^k \right \rangle \right| \left\|f_2^{\Omega_2^{\widetilde{n_2}}} \right\|_{L^2 \left(I^{m, 2k}_{p+\frac{2^{\frac{m}{2}}\widetilde{q}^2}{2^{2k}}+\frac{2\widetilde{q}s}{2^{k}}+\frac{s^2}{2^{\frac{m}{2}}}} \right)} \nonumber \\
&& \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \cdot \left\| f_1^{\Omega_1^{\frac{2\widetilde{q}}{2^k}\widetilde{n_2}+\frac{3\widetilde{q}^2}{2^{2k}} \cdot \frac{\widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}}}} \right\|_{L^2 \left(I^{m, k}_{\frac{p}{2^k}-2^{\frac{m}{2}-k}\widetilde{q}-s} \right)} \nonumber \\
&& \lesssim 2^{k-\frac{m}{2}}  \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ \widetilde{p} \sim 2^{\frac{m}{2}-k}}} \sum_{\substack{\widetilde{q} \sim 2^k \\ \widetilde{n_2} \sim 2^k}}  \left| \left\langle f_3, \psi_{2^{\frac{m}{2}-k}p+\widetilde{p}, \widetilde{n_2}}^k \right \rangle \right|  \left( \sum_{s \sim 2^{\frac{m}{2}-k}} \left\|f_2^{\Omega_2^{\widetilde{n_2}}} \right\|_{L^2 \left(I^{m, 2k}_{p+\frac{2^{\frac{m}{2}}\widetilde{q}^2}{2^{2k}}+\frac{2\widetilde{q}s}{2^{k}}+\frac{s^2}{2^{\frac{m}{2}}}} \right)}^2 \right)^{\frac{1}{2}} \nonumber \\
&& \qquad \qquad \qquad \qquad \qquad \qquad \qquad  \cdot \left( \sum_{s \sim 2^{\frac{m}{2}-k}} \left\| f_1^{\Omega_1^{\frac{2\widetilde{q}}{2^k}\widetilde{n_2}+\frac{3\widetilde{q}^2}{2^{2k}} \cdot \frac{\widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}}}} \right\|_{L^2 \left(I^{m, k}_{\frac{p}{2^k}-2^{\frac{m}{2}-k}\widetilde{q}-s} \right)}^2 \right)^{\frac{1}{2}} \nonumber \\
&& \lesssim  2^{k-\frac{m}{2}}   \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ \widetilde{p} \sim 2^{\frac{m}{2}-k}}} \sum_{\substack{\widetilde{q} \sim 2^k \\ \widetilde{n_2} \sim 2^k}}  \left\|f_3^{\Omega_2^{\widetilde{n_2}}} \right\|_{L^2 \left(I^{0, m+k}_{2^{\frac{m}{2}-k}p+\widetilde{p}} \right)} \left\|f_2^{\Omega_2^{\widetilde{n_2}}} \right\|_{L^2 \left(I_{\frac{p}{2^{\frac{m}{2}-k}}+\frac{\widetilde{q}^2}{2^k}}^{0, 3k} \right)} \left\| f_1^{\Omega_1^{\frac{2\widetilde{q}}{2^k}\widetilde{n_2}+\frac{3\widetilde{q}^2}{2^{2k}} \cdot \frac{\widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}}}} \right\|_{L^2 \left(I^{0, 2k}_{\frac{p}{2^{\frac{m}{2}}}-\widetilde{q}} \right)}.
\end{eqnarray}
Guided by \eqref{20241014eq56}, we define the \emph{time-frequency sparse sets of indices} by
$$
\calS_\nu(f_j):=\left\{ \substack{(Q_j, L_j) \\ Q_j \sim 2^k, L_j \sim 2^k}: \int_{I_{Q_j}^{0, (j+1)k}} \left|f_j^{\Omega_j^{L_j}} \right|^2 \gtrsim 2^{-\nu k} \int_{I_{Q_j}^{0, (j+1)k}}|f_j|^2 \right\}, \quad j\in\{1, 2\}\,,
$$
and
$$
\calS_\nu(f_3):=\left\{ \substack{(Q_3, L_3) \\ Q_3 \sim 2^m, L_3 \sim 2^k}: \int_{I_{Q_3}^{0, m+k}} \left|f_3^{\Omega_2^{L_3}} \right|^2 \gtrsim 2^{-\nu k} \int_{I_{Q_3}^{0, m+k}}|f_3|^2 \right\}\,,
$$
where here $\nu>0$ is a small parameter to be chosen later.

We also define the \emph{time-frequency uniform sets of indices} $\calU_\mu(f_1), \calU_\mu(f_2)$ and $\calU_\mu(f_3)$ as the complements of the corresponding sparse sets. 

Now, we decompose our functions into sparse and uniform components as follows:
\begin{enumerate}
    \item [$\bullet$] for $f_j$ with $j=1, 2$, the \emph{uniform} and \emph{sparse} component are defined as
    $$
    f_j^{\calU_\nu}:=\sum_{(Q_j, L_j) \in \calU_\nu(f_j)} \one_{I_{Q_j}^{0, (j+1)k}} f_j^{\Omega_j^{L_j}} \quad \textrm{and} \quad f_j^{\calS_\nu}:=\sum_{(Q_j, L_j) \in \calS_\nu(f_j)} \one_{I_{Q_j}^{0, (j+1)k}} f_j^{\Omega_j^{L_j}} \quad \textrm{respectively}; 
    $$
    \item [$\bullet$] for $f_3$, the \emph{uniform} and \emph{sparse} component are defined as
    \begin{equation} \label{20241015eq01}
    f_3^{\calU_\nu}:=\sum_{(Q_3, L_3) \in \calU_\nu(f_3)} \one_{I_{Q_3}^{0, m+k}} f_3^{\Omega_2^{L_3}} \quad \textrm{and} \quad f_3^{\calS_\nu}:=\sum_{(Q_3, L_3) \in \calS_\nu(f_3)} \one_{I_{Q_3}^{0, m+k}} f_3^{\Omega_2^{L_3}} \quad \textrm{respectively}.
    \end{equation} 
    \end{enumerate}
With these done, we decompose 
$$
\left(\Lambda_m^k \right)^*(f_1, f_2, f_3):=\left(\Lambda_m^k \right)^{*}_{\calU_\nu}(f_1, f_2, f_3)+\left(\Lambda_m^k \right)^{*}_{\calS_\nu}(f_1, f_2, f_3),
$$
with $\left(\Lambda_m^k \right)^{*}_{\calS_\nu}(f_1, f_2, f_3):=\left(\Lambda_m^k \right)^{*}\left(f^{\calS_\nu}_1, f^{\calS_\nu}_2, f^{\calS_\nu}_3 \right)$. 

\subsubsection{Treatment of $\left(\Lambda_m^k \right)^{*}_{\calU_\nu}(f_1, f_2, f_3)$.} \label{20241126subsubsec01} In this case, at least one of the input functions is uniform. Without loss of generality, we assume that $f_3$ is uniform. All the other cases can be treated in a similar way, and hence we will omit their proofs here. 

To begin with, from \eqref{20241014eq56}, we have 
\begin{eqnarray*}
%
&& \left(\Lambda_m^k \right)^* \left(f_1, f_3, f_3^{\calU_\nu} \right) \lesssim 2^{k-\frac{m}{2}}   \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ \widetilde{p} \sim 2^{\frac{m}{2}-k}}} \sum_{\substack{\widetilde{q} \sim 2^k \\ \widetilde{n_2} \sim 2^k}}  \left\|\left(f^{\calU_\nu}_3 \right)^{\Omega_2^{\widetilde{n_2}}} \right\|_{L^2 \left(I^{0, m+k}_{2^{\frac{m}{2}-k}p+\widetilde{p}} \right)} \\
&& \qquad \qquad \qquad \qquad \qquad \qquad \qquad  
 \cdot \left\|f_2^{\Omega_2^{\widetilde{n_2}}} \right\|_{L^2 \left(I_{\frac{p}{2^{\frac{m}{2}-k}}+\frac{\widetilde{q}^2}{2^k}}^{0, 3k} \right)} \left\| f_1^{\Omega_1^{\frac{2\widetilde{q}}{2^k}\widetilde{n_2}+\frac{3\widetilde{q}^2}{2^{2k}} \cdot \frac{\widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}}}} \right\|_{L^2 \left(I^{0, 2k}_{\frac{p}{2^{\frac{m}{2}}}-\widetilde{q}} \right)}.
 \end{eqnarray*}
Using the assumption that $f_3$ is uniform (in the sense of \eqref{20241015eq01}), the above expression is bounded above by
\begin{eqnarray*}
%
&& 2^{k-\frac{m}{2}} \cdot 2^{-\frac{\nu k}{2}}  \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ \widetilde{p} \sim 2^{\frac{m}{2}-k}}} \sum_{\substack{\widetilde{q} \sim 2^k \\ \widetilde{n_2} \sim 2^k}}  \left\|f_3 \right\|_{L^2 \left(I^{0, m+k}_{2^{\frac{m}{2}-k}p+\widetilde{p}} \right)} \\
&& \qquad \qquad \qquad \qquad \qquad \qquad \qquad  
 \cdot \left\|f_2^{\Omega_2^{\widetilde{n_2}}} \right\|_{L^2 \left(I_{\frac{p}{2^{\frac{m}{2}-k}}+\frac{\widetilde{q}^2}{2^k}}^{0, 3k} \right)} \left\| f_1^{\Omega_1^{\frac{2\widetilde{q}}{2^k}\widetilde{n_2}+\frac{3\widetilde{q}^2}{2^{2k}} \cdot \frac{\widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}}}} \right\|_{L^2 \left(I^{0, 2k}_{\frac{p}{2^{\frac{m}{2}}}-\widetilde{q}} \right)}.
 \end{eqnarray*}
 Applying Cauchy-Schwarz in the following order: first in $n_2$, then in $\widetilde{q}$, then in $\tilde{p}$ and finally in $p$, we see that the above expression is bounded above by 
 \begin{eqnarray*}
 %
 && 2^{k-\frac{m}{2}} \cdot 2^{-\frac{\nu k}{2}}  \sum_{\tilde{p} \sim 2^{\frac{m}{2}-k}} \sum_{\substack{p \sim 2^{\frac{m}{2}+k} \\ \widetilde{q} \sim 2^k}} \left\|f_3 \right\|_{L^2 \left(I^{0, m+k}_{2^{\frac{m}{2}-k}p+\widetilde{p}} \right)} \left\|f_2 \right\|_{L^2 \left(I_{\frac{p}{2^{\frac{m}{2}-k}}+\frac{\widetilde{q}^2}{2^k}}^{0, 3k} \right)} \left\| f_1 \right\|_{L^2 \left(I^{0, 2k}_{\frac{p}{2^{\frac{m}{2}}}-\widetilde{q}} \right)} \\
 && \lesssim 2^{k-\frac{m}{2}} \cdot 2^{-\frac{\nu k}{2}}  \sum_{\tilde{p} \sim 2^{\frac{m}{2}-k}} \sum_{p \sim 2^{\frac{m}{2}+k}} \left\|f_3 \right\|_{L^2 \left(I^{0, m+k}_{2^{\frac{m}{2}-k}p+\widetilde{p}} \right)}\left( \sum_{\widetilde{q} \sim 2^k}\left\|f_2 \right\|^2_{L^2 \left(I_{\frac{p}{2^{\frac{m}{2}-k}}+\frac{\widetilde{q}^2}{2^k}}^{0, 3k} \right)} \right)^{\frac{1}{2}} \left( \sum_{\widetilde{q} \sim 2^k} \left\| f_1 \right\|^2_{L^2 \left(I^{0, 2k}_{\frac{p}{2^{\frac{m}{2}}}-\widetilde{q}} \right)} \right)^{\frac{1}{2}} \\
 && \lesssim 2^{\frac{k}{2}-\frac{m}{4}} \cdot 2^{-\frac{\nu k}{2}} \left\|f_1 \right\|_{L^2(3I^k)} \sum_{p \sim 2^{\frac{m}{2}+k}} \left\|f_2 \right\|_{L^2 \left(I^{0, 2k}_{\frac{p}{2^{\frac{m}{2}}}} \right)} \left\|f_3 \right\|_{L^2 \left(I^{0, \frac{m}{2}+2k}_{p} \right)} \\
 && \lesssim 2^{\frac{k}{2}} \cdot  2^{-\frac{\nu k}{2}} \left\|f_1 \right\|_{L^2(3I^k)} \sum_{p \sim 2^{k}} \left\|f_2 \right\|_{L^2 \left(I^{0, 2k}_{p} \right)} \left\|f_3 \right\|_{L^2 \left(I^{0, 2k}_{p} \right)}\\
 && \lesssim 2^{\frac{k}{2}} \cdot  2^{-\frac{\nu k}{2}} \left\|f_1 \right\|_{L^2(3I^k)}\left\|f_2 \right\|_{L^2(3I^k)}\left\|f_3 \right\|_{L^2(3I^k)}, 
\end{eqnarray*}
which gives the desired estimate. 

\subsubsection{Treatment of $\left(\Lambda_m^k \right)^{*}_{\calS_\nu}(f_1, f_2, f_3)$.} \label{20241126subsubsec02} In this case, we have 
\begin{enumerate}
    \item [$\bullet$] if $j \in \{1, 2\}$ then up to a $2^{\nu k}$ factor there is a unique measurable function $L_j: [2^{jk}, 2^{jk+1}] \cap \Z \mapsto \left[2^k, 2^{k+1} \right] \cap \Z$ such that for each $Q_j \sim 2^{jk}$ one has
    \begin{equation} \label{20241015eq10}
    2^{-\nu k} \int_{I_{Q_j}^{0, (j+1)k}} |f_j|^2 \lesssim  \int_{I_{Q_j}^{0, (j+1)k}} \left| f_j^{\Omega_j^{L_j(Q_j)}} \right|^2 \lesssim  \int_{I_{Q_j}^{0, (j+1)k}} |f_j|^2, \quad j \in \{1, 2\};
    \end{equation} 
    \item [$\bullet$] up to a $2^{\nu k}$ factor there is a unique measurable function $L_3: [2^m, 2^{m+1}] \cap \Z \mapsto \left[2^k, 2^{k+1} \right] \cap \Z$ such that for each $Q_3 \sim 2^m$ one has
    \begin{equation} \label{20241015eq10}
    2^{-\nu k} \int_{I_{Q_3}^{0, m+k}} |f_3|^2 \lesssim  \int_{I_{Q_3}^{0, m+k}} \left| f_3^{\Omega_3^{L_3(Q_3)}} \right|^2 \lesssim  \int_{I_{Q_3}^{0, m+k}} |f_3|^2.
    \end{equation} 
\end{enumerate}
Combing this with \eqref{20241014eq56}, we see that
\begin{eqnarray*}
%
&& \left(\Lambda_m^k \right)^{*}_{\calS_\nu}(f_1, f_2, f_3) \lesssim  2^{k-\frac{m}{2}} \cdot 2^{3\nu k} \sum_{\widetilde{p} \sim 2^{\frac{m}{2}-k}} \sum_{(p, \widetilde{q}) \in \TFC_{\widetilde{p}}}  \left\|f_3 \right\|_{L^2 \left(I^{0, m+k}_{2^{\frac{m}{2}-k}p+\widetilde{p}} \right)} \left\|f_2 \right\|_{L^2 \left(I_{\frac{p}{2^{\frac{m}{2}-k}}+\frac{\widetilde{q}^2}{2^k}}^{0, 3k} \right)} \left\| f_1 \right\|_{L^2 \left(I^{0, 2k}_{\frac{p}{2^{\frac{m}{2}}}-\widetilde{q}} \right)} \\
&& \lesssim 2^{k-\frac{m}{2}} \cdot 2^{3\nu k} \left( \sum_{\widetilde{p} \sim 2^{\frac{m}{2}-k}} \left(\# \TFC_{\widetilde{p}} \right) \right)^{\frac{1}{2}} \left(\sum_{\substack{\widetilde{p} \sim 2^{\frac{m}{2}-k} \\ p \sim 2^{\frac{m}{2}+k} \\ \widetilde{q} \sim 2^k}}  \left\|f_3 \right\|^2_{L^2 \left(I^{0, m+k}_{2^{\frac{m}{2}-k}p+\widetilde{p}} \right)} \left\|f_2 \right\|^2_{L^2 \left(I_{\frac{p}{2^{\frac{m}{2}-k}}+\frac{\widetilde{q}^2}{2^k}}^{0, 3k} \right)} \left\| f_1 \right\|^2_{L^2 \left(I^{0, 2k}_{\frac{p}{2^{\frac{m}{2}}}-\widetilde{q}} \right)}  \right)^{\frac{1}{2}},
\end{eqnarray*}
where for each $\widetilde{p} \sim 2^{\frac{m}{2}-k}$, 
$$
\TFC_{\widetilde{p}}:=\left\{\substack{(p, \widetilde{q}) \\ p \sim 2^{\frac{m}{2}+k}, \widetilde{q} \sim 2^k}: L_1\left( \frac{p}{2^{\frac{m}{2}}}-\widetilde{q} \right) \cong \frac{2 \widetilde{q}}{2^k}L_2 \left(\frac{p}{2^{\frac{m}{2}-k}}+\frac{\widetilde{q}^2}{2^k} \right)+ \frac{3\widetilde{q}^2}{2^{2k}} \cdot \frac{\widetilde{\lambda} \left(2^{\frac{m}{2}-k}p+\widetilde{p} \right)}{2^{\frac{m}{2}-k}}  \right\}.
$$
The desired decay comes now from the claim that there exists a suitable $\epsilon_5'>0$ such that for each $\widetilde{p} \sim 2^{\frac{m}{2}-k}$, 
\begin{equation} \label{20241015eq23}
\#\TFC_{\widetilde{p}} \lesssim 2^{\frac{m}{2}+2k-\epsilon_5'k}. 
\end{equation} 
We claim that in this case, one can reduce the estimate \eqref{20241015eq23} to the situation that was treated in \cite[Section 5.3.2]{HL23}. To see this, we further decompose the regime of $p$ as 
$$
\left\{p \sim 2^{\frac{m}{2}+k} \right\}=\bigcup_{p' \sim 2^{2k}} \left[2^{\frac{m}{2}-k}p', 2^{\frac{m}{2}-k}(p'+1)\right].
$$
Using the above, we further decompose the set $\TFC_{\widetilde{p}}$ as 
$$
\TFC_{\widetilde{p}}=\bigcup_{l \sim 2^{\frac{m}{2}-k}} \TFC_{\widetilde{p}, l}, 
$$
where for each $\widetilde{p}, l \sim 2^{\frac{m}{2}-k}$,
$$
\TFC_{\widetilde{p}, l}:=\left\{ \substack{\left(p', \widetilde{q}\right) \\ p' \sim 2^{2k}, \widetilde{q} \sim 2^k}: L_1\left( \frac{p'}{2^k}-\widetilde{q} \right) \cong \frac{2 \widetilde{q}}{2^k}L_2 \left(p'+\frac{\widetilde{q}^2}{2^k} \right)+ \frac{3\widetilde{q}^2}{2^{2k}} \cdot \frac{\widetilde{\lambda} \left(2^{m-2k}p'+2^{\frac{m}{2}-k}l+\widetilde{p} \right)}{2^{\frac{m}{2}-k}}  \right\}.
$$
Since in this case $\widetilde{p}$ and $l$ are fixed, by denoting
$$
L_{3, \widetilde{p}, l}(p'):=\frac{\widetilde{\lambda} \left(2^{m-2k}p'+2^{\frac{m}{2}-k}l+\widetilde{p} \right)}{2^{\frac{m}{2}-k}},
$$
we notice that the estimate for the size of the set $\TFC_{\widetilde{p}, l}$ reduces to the situation treated in \cite[Page 58]{HL23}. 
Thus, it follows that $\#\TFC_{\widetilde{p}, l} \lesssim 2^{(3-\epsilon_5')k}$ and hence our proof is now complete. 

\medskip 

\subsection{Treatment of the uniform component ${\bf L}_{m, k}^{\calU_\mu}(f_1, f_2)$: Case I in Overview} \label{20241028subsec01}

Following the discussion in Section \ref{20241023overview01}, here we only consider \underline{\textsf{Step I.2.1}}, that is, the situation when $\frac{m}{2} \le k \le m$. At the core of our reasoning lies in the \emph{constancy propagation} of $\widetilde{\lambda}$ from intervals of length  $2^{-m-2k}$ to intervals of length $2^{-m-k}$. This strategy resembles the one presented in the proof of Proposition \ref{20241018prop01}, and hence, in this section, we will only focus on the key modifications required for treating our present case.

With these in mind, we follow the reasoning presented in \eqref{20241004eq21}--\eqref{20241011eq40}, and, with the obvious adaptations, as well as notations---see in particular \ref{KH2}---we reduce matters to the following estimate: for each $\widetilde{p} \sim 2^k$, there exists some $\widetilde{\epsilon_1}>0$, such that 
\begin{equation} \label{20241023eq01}
\left|\widetilde{V}_{m, k}^{\widetilde{p}, \frakL}(f_1, f_2) \right| \lesssim 2^{-\widetilde{\epsilon_1} m} \left\|f_1 \right\|_{L^2(3I^k)}^2 \left\|f_2 \right\|^2_{L^2(3I^k)}, 
\end{equation} 
where
$$
\widetilde{V}_{m, k}^{\widetilde{p}, \frakL}(f_1, f_2):=2^{\frac{m}{2}+2k} \sum_{p \in \left[\widetilde{p} 2^{m-k}, (\widetilde{p}+1)2^{m-k} \right]} \sum_{q \sim 2^{\frac{m}{2}}} \int_{\widetilde{\frakL_p^k}} \left| \int_{I_q^{m, k}} f_1(x-t)f_2(x+t^2) e^{3i 2^k \cdot \frac{q^2 \widetilde{\lambda}(x)}{2^{\frac{m}{2}}} t} dt \right|^2  dx.
$$
Here, for $\widetilde{\epsilon}_0>0$ and $p \sim 2^m$, the \emph{light set of $\ell$-indices} associated to the interval $I_p^{0, k+m}$ is defined as
$$
\widetilde{\frakL_p^k}:=\bigcup_{\ell \in \frakL_p^k} \frakM^\ell \left(I_p^{0, k+m} \right) \quad \textrm{with} \quad 
\frakL_p^k:=\left\{\ell \sim 2^{\frac{m}{2}-\widetilde{\epsilon_0} m}: \left| \frakM^\ell \left(I_p^{0, k+m} \right) \right| \lesssim \left|I_p^{0, k+m} \right| 2^{-\widetilde{\epsilon_0} m} \right\}
$$
and
$$
\frakM^\ell \left(I_p^{0, k+m} \right):=\left\{x \in I_p^{0, k+m}: \widetilde{\lambda}(x) \in \left[ \ell 2^{\widetilde{\epsilon_0} m}, (\ell+1)2^{\widetilde{\epsilon_0} m}  \right] \right\}.
$$
Next, following the argument in \textsf{Step I} in Proposition \ref{20241018prop01}, we may assume $\widetilde{\frakL_p^k}=I_p^{0, m+k}$ for each $p \sim 2^m$. Moreover, another application of Proposition \ref{20241006prop01} (with $2^{\del k}$ and $2^{-(\del-2\mu)k}$ replaced by $2^{\del m}$ and $2^{-(\del-2\mu)m}$, respectively) followed by the change of variable\footnote{Here we make again use of Remark \ref{Simplif}.} $t \to t+\frac{q}{2^{\frac{m}{2}+k}}$ reduces our analysis to 
\begin{eqnarray*}
%
&& {\bf \widetilde{V}}_{m, k}^{\widetilde{p}, \frakL}(f_1, f_2):=2^{\frac{m}{2}+2k+\del m} \sum_{p \in \left[\widetilde{p}2^{m-k}, (\widetilde{p}+1) 2^{m-k}  \right]} \sum_{q \sim 2^\frac{m}{2}}  \int_{I_0^{0, k+m}} \bigg| \int_{I_0^{m, k}} f_1 \left(\frac{p}{2^{k+m}}-\frac{q}{2^{\frac{m}{2}+k}}-t \right) \\
&& \qquad \qquad \qquad \qquad  \cdot f_2 \left(x+\frac{p}{2^{k+m}}+\frac{2tq}{2^{\frac{m}{2}+k}}+\frac{q^2}{2^{m+2k}} \right)  e^{3i 2^k \frac{q^2 \widetilde{\lambda}\left(x+\frac{p}{2^{k+m}} \right)}{2^{\frac{m}{2}}} t} dt \bigg|^2 dx. 
\end{eqnarray*}
In this case, instead of further subdividing the range of $p$ (see, \eqref{20241024eq01}), we decompose the range of $q$:
$$
\left\{q \sim 2^{\frac{m}{2}} \right\}=\bigcup_{q' \sim 2^{m-k}} \left[q'2^{k-\frac{m}{2}}, (q'+1)2^{k-\frac{m}{2}} \right].
$$
Thus, we have
\begin{eqnarray*}
%
&& {\bf \widetilde{V}}_{m, k}^{\widetilde{p}, \frakL}(f_1, f_2) \lesssim 2^{\frac{m}{2}+2k+\del m} \sum_{p \in \left[\widetilde{p}2^{m-k}, (\widetilde{p}+1) 2^{m-k}  \right]} \sum_{q' \sim 2^{m-k}} \sum_{\ell \sim 2^{k-\frac{m}{2}}} \int_{I_0^{0, k+m}} \bigg| \int_{I_0^{m, k}} f_1 \left(\frac{p}{2^{k+m}}-\frac{q'}{2^m}-\frac{l}{2^{\frac{m}{2}+k}}-t \right) \\
&& \qquad \cdot f_2 \left(x+\frac{p}{2^{k+m}}+\frac{2tq'}{2^m}+\frac{2t\ell}{2^{\frac{m}{2}+k}}+\frac{(q')^2}{2^{2m}}+\frac{2q'\ell}{2^{\frac{3m}{2}+k}}+\frac{\ell^2}{2^{m+2k}} \right)  e^{3i 2^k \frac{\left(q'2^{k-\frac{m}{2}}+\ell \right)^2 \widetilde{\lambda}\left(x+\frac{p}{2^{k+m}} \right)}{2^{\frac{m}{2}}} t} dt \bigg|^2 dx. 
\end{eqnarray*}
Applying the change of variables $p \to p-\left\lfloor \frac{(q')^2}{2^{m-k}} \right \rfloor$ and $x \to x-\frac{2q'\ell}{2^{\frac{3m}{2}+k}}-\frac{\ell^2}{2^{m+2k}}-\frac{\left\{ \frac{\left(q' \right)^2}{2^{m-k}} \right\}}{2^{m+k}}$, we have
\begin{eqnarray*}
%
&& {\bf \widetilde{V}}_{m, k}^{\widetilde{p}, \frakL}(f_1, f_2) \\
&& \lesssim 2^{\frac{m}{2}+2k+\del m} \sum_{p \in \left[\widetilde{p}2^{m-k}, (\widetilde{p}+2) 2^{m-k}  \right]} \sum_{q' \sim 2^{m-k}} \sum_{\ell \sim 2^{k-\frac{m}{2}}} \int_{9I_0^{0, k+m}} \bigg| \int_{I_0^{m, k}} f_1 \left(\frac{p}{2^{k+m}}-\frac{q'}{2^m}-\frac{(q')^2}{2^{2m}}-\frac{l}{2^{\frac{m}{2}+k}}-t \right) \\
&& \qquad \cdot f_2 \left(x+\frac{p}{2^{k+m}}+\frac{2tq'}{2^m}+\frac{2t\ell}{2^{\frac{m}{2}+k}}\right)  e^{3i 2^k \frac{\left(q'2^{k-\frac{m}{2}}+\ell \right)^2 \widetilde{\lambda}\left(x+\frac{p}{2^{k+m}}-\frac{(q')^2}{2^{2m}}-\frac{2q'\ell}{2^{\frac{3m}{2}+k}}-\frac{\ell^2}{2^{m+2k}}\right)}{2^{\frac{m}{2}}} t} dt \bigg|^2 dx. 
\end{eqnarray*}
Opening the square and then applying Cauchy-Schwarz, we have
$$
{\bf \widetilde{V}}_{m, k}^{\widetilde{p}, \frakL}(f_1, f_2) \lesssim 2^{\frac{m}{2}+2k+\del m} \widetilde{\calA} \,\widetilde{\calB}, 
$$
where 
\begin{eqnarray*}
%
&& \widetilde{\calA}^2:= \iint_{\left(I_0^{m, k} \right)^2} \sum_{p \in \left[\widetilde{p}2^{m-k}, (\widetilde{p}+2) 2^{m-k}  \right]} \sum_{q' \sim 2^{m-k}} \sum_{\ell \sim 2^{k-\frac{m}{2}}} \left|f_1 \left(\frac{p}{2^{k+m}}-\frac{q'}{2^m}-\frac{(q')^2}{2^{2m}}-\frac{l}{2^{\frac{m}{2}+k}}-t \right) \right|^2\\
&& \qquad \qquad \qquad \qquad  \cdot \left| f_1 \left(\frac{p}{2^{k+m}}-\frac{q'}{2^m}-\frac{(q')^2}{2^{2m}}-\frac{l}{2^{\frac{m}{2}+k}}-s \right) \right|^2 dtds
\end{eqnarray*}
and
\begin{eqnarray*}
%
&& \widetilde{\calB}^2:= \iint_{\left(I_0^{m, k} \right)^2} \sum_{p \in \left[\widetilde{p}2^{m-k}, (\widetilde{p}+2) 2^{m-k}  \right]} \sum_{q' \sim 2^{m-k}} \sum_{\ell \sim 2^{k-\frac{m}{2}}} \\
&& \qquad \quad \Bigg | \int_{9I_0^{0, k+m}}  f_2 \left(x+\frac{p}{2^{k+m}}+\frac{2tq'}{2^m}+\frac{2t\ell}{2^{\frac{m}{2}+k}}\right) f_2 \left(x+\frac{p}{2^{k+m}}+\frac{2sq'}{2^m}+\frac{2s\ell}{2^{\frac{m}{2}+k}}\right) \\
&& \qquad \qquad \cdot e^{3i \cdot 2^k \frac{\left(q'2^{k-\frac{m}{2}}+\ell \right)^2 \widetilde{\lambda}\left(x+\frac{p}{2^{k+m}}-\frac{(q')^2}{2^{2m}}-\frac{2q'\ell}{2^{\frac{3m}{2}+k}}-\frac{\ell^2}{2^{m+2k}}\right)}{2^{\frac{m}{2}}} (t-s)} dx \Bigg |^2 dtds. 
\end{eqnarray*}
The analysis of the term $\widetilde{\calA}^2$ follows as usual by the assumption that $f_1$ is uniform (see \eqref{uniformest}), and hence we omit it here. We thus move our focus on $\widetilde{\calB}^2$. We first apply the change of variable back $q=q'2^{k-\frac{m}{2}}+\ell$ followed by the change of variables $t \to \frac{2^{\frac{m}{2}}}{q} t$, $s \to \frac{2^{\frac{m}{2}}}{q}s$, and $s \to t-v$ in order to deduce 
\begin{eqnarray*}
%
&& \widetilde{\calB}^2 \lesssim \iint_{3I_0^{m, k} \times 7I_0^{m, k}} \sum_{p \in \left[ \widetilde{p}2^{m-k}, (\widetilde{p}+2)2^{m-k} \right]} \sum_{q \sim 2^{\frac{m}{2}}} \bigg | \int_{9I_0^{0, k+m}} f_2 \left(x+\frac{p}{2^{k+m}}+\frac{2t}{2^k} \right) \\
&&\qquad \qquad \qquad  \cdot f_2 \left(x+\frac{p}{2^{k+m}}+\frac{2(t-v)}{2^k} \right) e^{3i \cdot 2^k q \widetilde{\lambda} \left(x+\frac{p}{2^{k+m}}-\frac{q^2}{2^{m+2k}} \right)v} dx \bigg|^2 dtdv.
\end{eqnarray*}
For technical reasoning, letting $\widetilde{\epsilon}_2>0$ being sufficiently small, we divide the $t$-interval as follows: 
$$
7I_0^{m, k}:=\left[0, \frac{7}{2^{\frac{m}{2}+k}} \right]=\bigcup_{\iota=0}^{ 7 \cdot 2^{\widetilde{\epsilon}_2 m}-1}  \left[ \frac{\iota}{2^{\frac{m}{2}+k+\widetilde{\epsilon}_2m }}, \frac{\iota+1}{2^{\frac{m}{2}+k+\widetilde{\epsilon}_2m }} \right]=\bigcup_{\iota=0}^{ 7 \cdot 2^{\widetilde{\epsilon}_2 m}-1} I_{\iota}^{m, k+\widetilde{\epsilon_2}m}, 
$$
which gives (after a change of variable)
\begin{eqnarray*}
%
&& \widetilde{\calB}^2 \lesssim \sum_{\iota \sim 2^{\widetilde{\epsilon_2} m}}  \iint_{3I_0^{m, k} \times I_0^{m, k+\widetilde{\epsilon}_2m }} \sum_{p \in \left[ \widetilde{p}2^{m-k}, (\widetilde{p}+2)2^{m-k} \right]} \sum_{q \sim 2^{\frac{m}{2}}} \bigg | \int_{9I_0^{0, k+m}} f_2 \left(x+\frac{p}{2^{k+m}}+\frac{2\iota}{2^{\frac{m}{2}+2k+\widetilde{\epsilon_2}m}}+\frac{2t}{2^k} \right) \\
&&\qquad \qquad \cdot f_2 \left(x+\frac{p}{2^{k+m}}+\frac{2\iota}{2^{\frac{m}{2}+2k+\widetilde{\epsilon_2}m}}+\frac{2(t-v)}{2^k} \right) e^{3i \cdot 2^k q \widetilde{\lambda} \left(x+\frac{p}{2^{k+m}}-\frac{q^2}{2^{m+2k}} \right)v} dx \bigg|^2 dtdv.
\end{eqnarray*}
Applying now the change of variable $x \to x-\frac{2t}{2^k}$, then, up to an admissible error $O\left(2^{-(\widetilde{\epsilon_2}-\delta)m} \left\|f_1 \right\|^2_{L^2(3I^k)} \left\|f_2 \right\|^2_{L^2(3I^k)}\right)$ in \eqref{20241023eq01}, we further have
\begin{eqnarray*}
%
&& \widetilde{\calB}^2 \lesssim \sum_{\iota \sim 2^{\widetilde{\epsilon_2} m}} \iint_{3I_0^{m, k} \times I_0^{m, k+\widetilde{\epsilon_2}m}} \sum_{p \in \left[ \widetilde{p}2^{m-k}, (\widetilde{p}+2)2^{m-k} \right]} \sum_{q \sim 2^{\frac{m}{2}}} \bigg | \int_{9I_0^{0, k+m}} f_2 \left(x+\frac{p}{2^{k+m}}+\frac{2\iota}{2^{\frac{m}{2}+2k+\widetilde{\epsilon_2}m}}\right) \\
&&\qquad \qquad \qquad  \cdot f_2 \left(x+\frac{p}{2^{k+m}}+\frac{2\iota}{2^{\frac{m}{2}+2k+\widetilde{\epsilon_2}m}}-\frac{2v}{2^k} \right) e^{3i \cdot 2^k q \widetilde{\lambda} \left(x-\frac{2t}{2^k}+\frac{p}{2^{k+m}}-\frac{q^2}{2^{m+2k}} \right)v} dx \bigg|^2 dtdv.
\end{eqnarray*}
Fix a choice of $\iota \sim 2^{\widetilde{\epsilon_2} m}$ that maximizes the right-hand side of the above estimate and denote $f_2(\cdot):=f_2 \left(\cdot+\frac{2\iota}{2^{\frac{m}{2}+2k+\widetilde{\epsilon_2}m}} \right)$; with these, we see that  
\begin{eqnarray*}
&& \widetilde{\calB}^2 \lesssim 2^{\widetilde{\epsilon_2}m} \sum_{p \in \left[ \widetilde{p} 2^{m-k}, (\widetilde{p}+2)2^{m-k} \right]} \iint_{\left(9I_0^{0, k+m} \right)^2} \vast | \int_{3 I_0^{m, k}} f_2 \left(x+\frac{p}{2^{k+m}} \right) f_2 \left(y+\frac{p}{2^{k+m}} \right) f_2 \left(x+\frac{p}{2^{k+m}}-\frac{2v}{2^k} \right) \\
&& \quad \cdot f_2 \left(y+\frac{p}{2^{k+m}}-\frac{2v}{2^k} \right) \left[\int_{I_0^{m, k}} \left( \sum_{q \sim 2^{\frac{m}{2}}} e^{3i \cdot 2^k v \left[\widetilde{\lambda} \left(x-\frac{2t}{2^k}+\frac{p}{2^{k+m}}-\frac{q^2}{2^{m+2k}} \right)-\widetilde{\lambda} \left(y-\frac{2t}{2^k}+\frac{p}{2^{k+m}}-\frac{q^2}{2^{m+2k}} \right) \right]}\right) dt \right] dv \vast | dxdy \\
&&\lesssim 2^{\widetilde{\epsilon_2}m}  \cdot 
 \widetilde{\calC}\,\widetilde{\calD}, 
\end{eqnarray*}
where 
\begin{eqnarray*}
%
&& \widetilde{\calC}^2:=\sum_{p \in \left[ \widetilde{p} 2^{m-k}, (\widetilde{p}+2)2^{m-k} \right]} \iiint_{\left(9I_0^{0, k+m} \right)^2 \times 3 I_0^{m, k}}  \Bigg | f_2 \left(x+\frac{p}{2^{k+m}} \right) f_2 \left(y+\frac{p}{2^{k+m}} \right) \\
&& \qquad \quad \cdot  f_2 \left(x+\frac{p}{2^{k+m}}-\frac{2v}{2^k} \right) f_2 \left(x+\frac{p}{2^{k+m}}-\frac{2v}{2^k} \right) f_2 \left(y+\frac{p}{2^{k+m}}-\frac{2v}{2^k} \right) \Bigg|^2 dxdydv
\end{eqnarray*}
and 
\begin{eqnarray*}
%
&& \widetilde{\calD}^2:=\sum_{p \in \left[ \widetilde{p} 2^{m-k}, (\widetilde{p}+2)2^{m-k} \right]} \iiint_{\left(9I_0^{0, k+m} \right)^2 \times 3I_0^{m, k}} \\
&& \qquad \left|\int_{I_0^{m,k}} \left( \sum_{q \sim 2^{\frac{m}{2}}} e^{3i \cdot 2^k q v \left[\widetilde{\lambda} \left(x-\frac{2t}{2^k}+\frac{p}{2^{k+m}}-\frac{q^2}{2^{m+2k}} \right)-\widetilde{\lambda} \left(y-\frac{2t}{2^k}+\frac{p}{2^{k+m}}-\frac{q^2}{2^{m+2k}} \right) \right]} \right) dt \right|^2 dvdxdy
\end{eqnarray*}
The estimate of $\widetilde{\calC}^2$ follows again easily from the assumption that $f_2$ is uniform. Turning our attention to $\widetilde{D}^2$, we open the square first and then write $q=q'2^{k-\frac{m}{2}}+\ell$ and $q_1=q_1'2^{k-\frac{m}{2}}+\ell_1$:
{\footnotesize \begin{eqnarray*}
%
&& \widetilde{\calD}^2 \lesssim \sum_{p \in \left[\widetilde{p}2^{m-k}, (\widetilde{p}+2)2^{m-k} \right]} \sum_{q', q_1' \sim 2^{m-k}}  \sum_{\ell, \ell_1 \sim 2^{k-\frac{m}{2}}} \iint_{\left(9I_0^{0, k+m} \right)^2} \iint_{\left(I_0^{m, k} \right)^2} dtdt_1dxdy \\
&& \quad  \left | \int_{3 I_0^{m, k}} e^{3i \cdot 2^k v\left( \substack{(q'2^{k-\frac{m}{2}}+\ell) \left[ \widetilde{\lambda} \left(x-\frac{2t}{2^k}+\frac{p}{2^{k+m}}-\frac{(q')^2}{2^{2m}}-\frac{2q'\ell}{2^{\frac{3m}{2}+k}}-\frac{\ell^2}{2^{m+2k}} \right)-\widetilde{\lambda} \left(y-\frac{2t}{2^k}+\frac{p}{2^{k+m}}-\frac{(q')^2}{2^{2m}}-\frac{2q'\ell}{2^{\frac{3m}{2}+k}}-\frac{\ell^2}{2^{m+2k}} \right)  \right] \qquad \\ \qquad   -(q_1'2^{k-\frac{m}{2}}+\ell_1) \left[ \widetilde{\lambda} \left(x-\frac{2t_1}{2^k}+\frac{p}{2^{k+m}}-\frac{(q_1')^2}{2^{2m}}-\frac{2q_1'\ell_1}{2^{\frac{3m}{2}+k}}-\frac{\ell_1^2}{2^{m+2k}} \right)-\widetilde{\lambda} \left(y-\frac{2t_1}{2^k}+\frac{p}{2^{k+m}}-\frac{(q_1')^2}{2^{2m}}-\frac{2q_1'\ell_1}{2^{\frac{3m}{2}+k}}-\frac{\ell_1^2}{2^{m+2k}} \right) \right] } \right)} dv \right|. 
\end{eqnarray*}} \\
Applying further the change of variables $x \to x+\frac{2q'\ell}{2^{\frac{3m}{2}+k}}+\frac{\ell^2}{2^{m+2k}}+\frac{2t}{2^k}+\frac{\left\{\frac{(q')^2}{2^{m+k}}\right\}}{2^{m+k}}$, $y \to y+\frac{2q'\ell}{2^{\frac{3m}{2}+k}}+\frac{\ell^2}{2^{m+2k}}+\frac{2t}{2^k}+\frac{\left\{\frac{(q')^2}{2^{m+k}}\right\}}{2^{m+k}}$, and $p \to p+\left\lfloor \frac{(q')^2}{2^{m-k}} \right\rfloor$, we see that
{\footnotesize\begin{eqnarray*}
%
&& \widetilde{\calD}^2 \lesssim \sum_{p \in \left[\widetilde{p} 2^{m-k}, (\widetilde{p}+3)2^{m-k} \right]} \sum_{q', q_1' \sim 2^{m-k}} \sum_{\ell, \ell' \sim 2^{k-\frac{m}{2}}} \iint_{\left(15I_0^{0, k+m} \right)^2} \iint_{\left(I_0^{m, k} \right)^2} dtdt_1dxdy \\
&& \quad \left| \int_{3 I_0^{m, k}} e^{3i \cdot 2^k v \left( \left(q'2^{k-\frac{m}{2}}+\ell \right)\left[\substack{\widetilde{\lambda} \left(x+\frac{p}{2^{k+m}} \right) \quad \\ \quad -\widetilde{\lambda} \left(y+\frac{p}{2^{k+m}} \right)}\right]-\left(q_1'2^{k-\frac{m}{2}}+\ell_1 \right) \left[\substack{\widetilde{\lambda} \left(x+\frac{2(t-t_1)}{2^k}+\frac{p}{2^{k+m}}+\frac{(q')^2-(q_1')^2}{2^{2m}}+\frac{2(q'\ell-q_1'\ell_1)}{2^{\frac{3m}{2}+k}}+\frac{\ell^2-\ell_1^2}{2^{m+2k}} \right) \qquad \\ \qquad - \widetilde{\lambda} \left(y+\frac{2(t-t_1)}{2^k}+\frac{p}{2^{k+m}}+\frac{(q')^2-(q_1')^2}{2^{2m}}+\frac{2(q'\ell-q_1'\ell_1)}{2^{\frac{3m}{2}+k}}+\frac{\ell^2-\ell_1^2}{2^{m+2k}} \right)} \right]   \right)} dv \right|.
\end{eqnarray*}} \\ 
Finally, we apply the change of variable $t \to t_1+s$ and also change back the variables $q=q'2^{k-\frac{m}{2}}+\ell$ and $q_1=q_1'2^{k-\frac{m}{2}}+\ell'$ in order to deduce
\begin{eqnarray} \label{20241031eq01}
%
&& \widetilde{\calD}^2 \lesssim |I_0^{m, k}|  \sum_{p \in \left[\widetilde{p} 2^{m-k}, (\widetilde{p}+3)2^{m-k} \right]} \sum_{q, q_1 \sim 2^{\frac{m}{2}}}  \iint_{\left(15I_0^{0, k+m} \right)^2} \int_{3I_0^{m, k}} \nonumber  \\
&& \quad \left|\int_{ 3 I_0^{m, k}} e^{3i \cdot 2^{\frac{m}{2}+k} v \left( \frac{q}{2^{\frac{m}{2}}} \left[\substack{\widetilde{\lambda} \left(x+\frac{p}{2^{k+m}} \right) \quad \\ \quad -\widetilde{\lambda} \left(y+\frac{p}{2^{k+m}} \right)}\right]-\frac{q_1}{2^{\frac{m}{2}}} \left[ \substack{ \widetilde{\lambda} \left(x+\frac{2s}{2^k}+\frac{p}{2^{k+m}}-\frac{q_1^2-q^2}{2^{m+2k}} \right) \qquad \\ \qquad - \widetilde{\lambda} \left(y+\frac{2s}{2^k}+\frac{p}{2^{k+m}}-\frac{q_1^2-q^2}{2^{m+2k}} \right) } \right] \right)} dv \right| dsdxdy \nonumber\\
&&\lesssim  |I_0^{m, k}|^2 \sum_{p \in \left[\widetilde{p} 2^{m-k}, (\widetilde{p}+3)2^{m-k} \right]} \sum_{q, q_1 \sim 2^{\frac{m}{2}}}  \iint_{\left(15I_0^{0, k+m} \right)^2} \int_{3I_0^{m, k}} \left\lfloor \widetilde{\Xi}_{x, y, s, p}(q, q_1) \right\rfloor dsdxdy, 
\end{eqnarray}
where 
$$
\widetilde{\Xi}_{x, y, s, p}(q, q_1):=\left[\substack{\widetilde{\lambda} \left(x+\frac{p}{2^{k+m}} \right) \qquad \\ \qquad  -\widetilde{\lambda} \left(y+\frac{p}{2^{k+m}} \right)}\right]-\frac{q_1}{q} \left[ \substack{ \widetilde{\lambda} \left(x+\frac{2s}{2^k}+\frac{p}{2^{k+m}}-\frac{q_1^2-q^2}{2^{m+2k}} \right) \qquad \quad \\ \qquad \quad - \widetilde{\lambda} \left(y+\frac{2s}{2^k}+\frac{p}{2^{k+m}}-\frac{q_1^2-q^2}{2^{m+2k}} \right) } \right]. 
$$
Once here, we notice that the desired control on the term \eqref{20241031eq01} follows using similar reasonings to the ones employed for treating \eqref{20240110eq21} thus concluding our proof.
