\section{Treatment of the stationary off-diagonal component $BHC^{\not \Delta, S}$} \label{20250308sec01}

In this section we focus our attention on the behavior of the stationary off-diagonal component  $BHC^{\not \Delta, S}$. Recall--see \eqref{offdiag}--that $BHC^{\not \Delta, S}$ addresses the regime where one of the following situations is satisfied:
\begin{enumerate}
    \item [(a)] $j \cong l$ and $j>m+100$;
    \item [(b)] $l \cong m$ and $l>j+100$;
    \item [(c)] $m \cong j$ and $m>l+100$.
\end{enumerate}

As before, we only focus on the case $k \ge 0$. We divide our approach into two major cases:
\begin{enumerate}
    \item [({\bf O1})] $j \simeq l, k \ge 0$, and $0 \le m \le \frac{j}{2}$;
    \item [({\bf O2})] all other stationary off-diagonal cases except ({\bf O1}). 
\end{enumerate}
As a brief preview of our strategy in this section we have: 
\begin{itemize}
\item for the Case ({\bf O1}), the phase function $\lambda(x)$ oscillates at the scale $2^{m+3k}$, which implies that the term $\lambda(x)t^3$ is essentially constant on $t$-intervals of length $2^{-m-k}$, which is larger than $2^{-\frac{j}{2}-k}$ -- the linearization scale for the $t$-variable; as a consequence  Rank-I LGC will be effective in the first case;
\item for the Case ({\bf O2}), the phase $\lambda(x) t^3$ oscillates faster, and thus in this situation we will apply Rank-II LGC by extending the earlier argument that we used to treat the main diagonal term.
\end{itemize}    

\subsection{Treatment of the Case ({\bf O1}): $j \simeq l, k \ge 0$, and $0 \le m \le \frac{j}{2}$}

In this context, without loss of generality, we may assume that $j=l$ and hence our main term becomes
\begin{equation} \label{20241124eq01}
\sup_{\lambda \in \R} \left|BHC_{j, j, m, \lambda(x)}^k (f_1, f_2)(x) \right|=\sup_{\lambda \in \R} \left| \one_{I^k}(x) 2^k \phi \left(\frac{\lambda}{2^{m+3k}} \right) \int_{I^k} f_{1, j+k}(x-t) f_{2, j+2k}(x+t^2)e^{i\lambda t^3} dt \right|, 
\end{equation} 
where we recall here that $f_{i, j+ik}$ is the Fourier projection of the function $f_i$ within the frequency interval $[2^{j+ik},\,2^{j+ik+1}]$,  $i \in \{1, 2\}$. Taking again $\lambda(\cdot)$ the measurable function that maximizes the right-hand side of \eqref{20241124eq01} we consider the dual form
\begin{eqnarray} \label{20250308eq03}
%
&& \Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3):=\left \langle BHC_{j, j, m, \lambda(x)}^k(f_1, f_2), f_3 \right \rangle  \nonumber \\
&& =2^k\int_{I^k} \int_{I^k} f_{1, j+k}(x-t)f_{2, j+2k}(x+t^2)f_3(x)e^{i \lambda(x) t^3} dtdx \\
&&=2^k \sum_{\widetilde{q} \sim 2^m} \int_{I^k} \int_{I_{\widetilde{q}}^{0, m+k}} f_{1, j+k}(x-t)f_{2, j+2k}(x+t^2)f_3(x)e^{i\lambda(x)t^3} dtdx. \nonumber 
\end{eqnarray}
Preparing the ground for the Rank-I LGC method, we first observe that for $t \in I_{\widetilde{q}}^{0, m+k}$, one has
\begin{equation}\nonumber
\lambda(x)t^3=\frac{3\lambda(x)\,t\,\widetilde{q}^2}{2^{2m+2k}} - \frac{2\lambda(x) \widetilde{q}^3}{2^{3m+3k}}+O(2^{-m})=\frac{\lambda(x) \widetilde{q}^3}{2^{3m+3k}}+O(1). 
\end{equation}
Thus,
$$
\Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3)\approx 2^k \sum_{\widetilde{q} \sim 2^m} \int_{I^k} e^{\frac{i\lambda(x) \widetilde{q}^3}{2^{3m+3k}}} \left( \int_{I_{\widetilde{q}}^{0, m+k}} f_{1, j+k}(x-t)f_{2, j+2k}(x+t^2)f_3(x) dt \right) dx. 
$$
We further split of the interval $I_{\widetilde{q}}^{0, m+k}$ into intervals of length $2^{-\frac{j}{2}-k}$:
$$
\left[\frac{\widetilde{q}}{2^{m+k}}, \frac{\widetilde{q}+1}{2^{m+k}} \right]=\left[\frac{2^{\frac{j}{2}-m} \widetilde{q}}{2^{\frac{j}{2}+k}}, \frac{2^{\frac{j}{2}-m}(\widetilde{q}+1)}{2^{\frac{j}{2}+k}} \right]=\bigcup_{\ell=0}^{2^{\frac{j}{2}-m}-1} \left[\frac{2^{\frac{j}{2}-m} \widetilde{q}+\ell}{2^{\frac{j}{2}+k}}, \frac{2^{\frac{j}{2}-m} \widetilde{q}+\ell+1}{2^{\frac{j}{2}+k}} \right].
$$
With these one further has
\begin{equation}\nonumber
\Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3)\approx2^k \sum_{\widetilde{q} \sim 2^m} \sum_{\substack{p \sim 2^{\frac{j}{2}+k} \\ \ell \sim 2^{\frac{j}{2}-m}}} \int_{I_p^{j, 2k}} e^{\frac{i\lambda(x) \widetilde{q}^3}{2^{3m+3k}}} \left( \int_{I_{2^{\frac{j}{2}-m} \widetilde{q}+\ell}^{j, k}} f_{1, j+k}(x-t)f_{2, j+2k}(x+t^2)f_3(x) dt \right) dx. 
\end{equation}
We are now ready to apply Rank-I LGC: at \textsf{Step 1}, for $f_1(x-t)$ we will use spatial intervals of lengths $2^{-\frac{j}{2}-k}$ while for $f_2(x+t^2)$ we will involve spatial intervals of lengths $2^{-\frac{j}{2}-2k}$, respectively. In accordance with this, at \textsf{Step 2}, we apply a \emph{Gabor frame decomposition} as follows:
$$
f_r=\sum_{\substack{p_r \sim 2^{\frac{j}{2}+(r-1)k} \\ n_r \sim 2^{\frac{j}{2}}}} \left \langle f_r, \phi_{p_r, n_r}^{j, rk} \right \rangle \phi_{p_r, n_r}^{j, rk}, \quad r \in \{1, 2\}, 
$$ 
where $\phi_{p_r, n_r}^{j, rk}(x)=2^{\frac{j}{4}+\frac{rk}{2}} \phi \left(2^{\frac{j}{2}+rk}x-p_r \right) e^{i2^{\frac{j}{2}+rk}xn_r}$. This allows one to write 
\begin{eqnarray*}
%
\Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3) &\approx & 2^k \sum_{\widetilde{q} \sim 2^m} \sum_{\substack{p \sim 2^{\frac{j}{2}+k} \\ \ell \sim 2^{\frac{j}{2}-m}}} \sum_{\substack{p_1 \sim 2^{\frac{j}{2}} \\ n_1 \sim 2^{\frac{j}{2}}}} \sum_{\substack{p_2 \sim 2^{\frac{j}{2}+k} \\ n_2 \sim 2^{\frac{j}{2}}}} \left \langle f_1, \phi_{p_1, n_1}^{j, k} \right \rangle \left \langle f_2, \phi_{p_2, n_2}^{j, 2k} \right \rangle \\
&& \quad \cdot \int_{I_p^{j, 2k}} f_3(x) e^{\frac{i\lambda(x) \widetilde{q}^3}{2^{3m+3k}}} \left[\int_{I_{2^{\frac{j}{2}-m} \widetilde{q}+\ell}^{j, k}} \phi_{p_1, n_1}^{j, k}(x-t) \phi_{p_2, n_2}^{j, 2k}(x+t^2) dt \right] dx. 
\end{eqnarray*} 
Since $x \in I_p^{j, 2k}$ and $t \in I_{2^{\frac{j}{2}-m} \widetilde{q}+\ell}^{j, k}$, we see that $p_1 \cong \frac{p}{2^k}-\left(2^{\frac{j}{2}-m}\widetilde{q}+\ell \right)$ and $p_2 \cong p+\frac{\left(2^{\frac{j}{2}-m} \widetilde{q}+\ell \right)^2}{2^{\frac{j}{2}}}$. Therefore,  
\begin{eqnarray*}
\Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3) 
&\approx & 2^{\frac{j}{4}+\frac{3k}{2}} \sum_{\widetilde{q} \sim 2^m} \sum_{\substack{p \sim 2^{\frac{j}{2}+k} \\ \ell \sim 2^{\frac{j}{2}-m}}} \sum_{\substack{n_1 \sim 2^{\frac{j}{2}} \\ n_2 \sim 2^{\frac{j}{2}}}} \left \langle f_1, \phi_{\frac{p}{2^k}-\left(2^{\frac{j}{2}-m}\widetilde{q}+\ell \right), n_1}^{j, k} \right \rangle \left \langle f_2, \phi_{ p+\frac{\left(2^{\frac{j}{2}-m} \widetilde{q}+\ell \right)^2}{2^{\frac{j}{2}}}, n_2}^{j, 2k} \right \rangle \\
&& \quad \cdot \int_{I_p^{j, 2k}} 2^{\frac{j}{4}+k} f_3(x)  e^{\frac{i\lambda(x) \widetilde{q}^3}{2^{3m+3k}}} \cdot e^{i2^{\frac{j}{2}+2k} \left(n_2+\frac{n_1}{2^k} \right)x} \left[ \int_{I_{2^{\frac{j}{2}-m}\widetilde{q}+\ell}^{j, k}} e^{i \left(-2^{\frac{j}{2}+k} n_1 t+2^{\frac{j}{2}+2k}n_2t^2 \right)}dt \right]dx.
\end{eqnarray*}
Observe that on the $t$-interval $I_{2^{\frac{j}{2}-m} \widetilde{q}+\ell}^{j, k}$, one has 
$$
2^{\frac{j}{2}+2k}n_2t^2 \simeq 2^{\frac{j}{2}+2k} n_2\left(\frac{2t \left(2^{\frac{j}{2}-m} \widetilde{q}+\ell \right)}{2^{\frac{j}{2}+k}}-\frac{\left(2^{\frac{j}{2}-m} \widetilde{q}+\ell \right)^2}{2^{j+2k}}\right)+O(1),
$$
which, together with a change of variables, yields that
\begin{eqnarray*} 
\Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3) & \approx & 2^{\frac{j}{4}+\frac{3k}{2}} \sum_{\widetilde{q} \sim 2^m} \sum_{\substack{p \sim 2^{\frac{j}{2}+k} \\ \ell \sim 2^{\frac{j}{2}-m}}} \sum_{\substack{n_1 \sim 2^{\frac{j}{2}} \\ n_2 \sim 2^{\frac{j}{2}}}} \left \langle f_1, \phi_{\frac{p}{2^k}-\left(2^{\frac{j}{2}-m}\widetilde{q}+\ell \right), n_1}^{j, k} \right \rangle \left \langle f_2, \phi_{ p+\frac{\left(2^{\frac{j}{2}-m} \widetilde{q}+\ell \right)^2}{2^{\frac{j}{2}}}, n_2}^{j, 2k} \right \rangle \nonumber \\
&& \cdot \int_{I_p^{j, 2k}} 2^{\frac{j}{4}+k} f_3(x)  e^{\frac{i\lambda(x) \widetilde{q}^3}{2^{3m+3k}}} \cdot e^{i2^{\frac{j}{2}+2k} \left(n_2+\frac{n_1}{2^k} \right)x} \cdot \frac{C_{\widetilde{q}, \ell, n_2, j}}{2^{\frac{j}{2}+k}} \left[ \int_0^1  e^{i \left(-n_1+n_2 \cdot \frac{2 \left(2^{\frac{j}{2}-m}\widetilde{q}+\ell \right)}{2^{\frac{j}{2}}} \right)t} dt \right] dx.
\end{eqnarray*}
Now, as usual, we maximize the contribution from the $t$-integral, which further leads to 
\begin{eqnarray} \label{20250209eq01}
\left| \Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3)\right| &\lesssim& 2^{-\frac{j}{4}+\frac{k}{2}} \sum_{\substack{ \widetilde{q} \sim 2^m \\ p \sim 2^{\frac{j}{2}+k}}} \sum_{\substack{\ell \sim 2^{\frac{j}{2}-m} \\ n_2 \sim 2^{\frac{j}{2}}}} \left| \left \langle f_1, \phi_{\frac{p}{2^k}-\left(2^{\frac{j}{2}-m}\widetilde{q}+\ell \right), 2n_2 \left(\frac{\widetilde{q}}{2^m}+\frac{\ell}{2^{\frac{j}{2}}} \right)}^{j, k} \right \rangle \right| \left|  \left \langle f_2, \phi_{ p+\frac{\left(2^{\frac{j}{2}-m} \widetilde{q}+\ell \right)^2}{2^{\frac{j}{2}}}, n_2}^{j, 2k} \right \rangle \right| \nonumber \\
&&\cdot \left| \left \langle f_3^{\widetilde{q}}, \phi_{p, n_2 \left(1+\frac{2\widetilde{q}}{2^{m+k}}+\frac{2\ell}{2^{\frac{j}{2}+k}} \right)}^{j, 2k} \right \rangle \right|\,,
\end{eqnarray}
where here for each $\widetilde{q} \sim 2^m$ we set $f_3^{\widetilde{q}}(x):=f_3(x)e^{\frac{i\lambda(x) \widetilde{q}^3}{2^{3m+3k}}}$.

Once at this point, we define the \emph{sparse index set} as follows: for $\mu>0$ sufficiently small, 
$$
\textsf{S}_\mu(f_i):=\left\{(p_i, n_i): \left|\left \langle f_i, \phi_{p_i, n_i}^{j, ik} \right \rangle \right|^2 \gtrsim 2^{-\mu j} \int_{I_{p_i}^{j, ik}} |f_i|^2,  \quad  p_i \sim 2^{\frac{j}{2}+(i-1)k}, \; n_i \sim 2^{\frac{j}{2}} \right\}, \quad i \in \{1, 2\}.
$$
Define also the \emph{uniform index set} $\textsf{U}_\mu(f_i)$ to be the complement of the set $\textsf{S}_\mu(f_i), i\in\{1, 2\}$. We now decompose the input functions $f_1$ and $f_2$, as usual, into their \emph{uniform} and \emph{sparse} components:  
$$
f_i^{\textsf{U}_\mu}:=\sum_{(p_i, n_i) \in \textsf{U}_\mu(f_i)} \one_{I_{p_i}^{i, ik}} f_i^{\omega_i^{n_i}} \quad \textrm{and} \quad f_i^{\textsf{S}_\mu}:=\sum_{(p_i, n_i) \in \textsf{S}_\mu(f_i)} \one_{I_{p_i}^{i, ik}} f_i^{\omega_i^{n_i}}, \qquad i\in\{1, 2\}, 
$$
where $\omega_i^{n_i}:=\left[n_i 2^{\frac{j}{2}+ik}, (n_i+1)2^{\frac{j}{2}+ik} \right]$.

With these done, we split $ \Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3)$ into its uniform and sparse components as follows:
$$
\Lambda_{j, j, m, \lambda(\cdot)}^{k, \textsf{S}_\mu}(f_1, f_2, f_3):=\Lambda_{j, j, m, \lambda(\cdot)}^k (f_1^{\textsf{S}_\mu}, f_2^{\textsf{S}_\mu}, f_3) 
$$
and
$$
\Lambda_{j, j, m, \lambda(\cdot)}^{k, \textsf{U}_\mu}(f_1, f_2, f_3):=\Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3)-\Lambda_{j, j, m, \lambda(\cdot)}^{k, \textsf{S}_\mu}(f_1, f_2, f_3).
$$
In the uniform case -- \emph{i.e.}, if one of the functions $f_1$ or $f_2$ is uniform--assume without loss of generality that, $f_1=f_1^{\textsf{U}_\mu}$. Departing from \eqref{20250209eq01}, we first apply Cauchy-Schwarz in $n_2$, followed by a (backward) change of variable $q=2^{\frac{j}{2}-m}\widetilde{q}+\ell$, and finally by an application of Cauchy-Schwarz first in $q$ and then in $p$:
\begin{eqnarray*}
%
&& \left| \Lambda_{j, j, m, \lambda(\cdot)}^k(f^{\textsf{U}_\mu}_1, f_2, f_3)\right| \lesssim 2^{-\frac{j}{4}+\frac{k}{2}-\frac{\mu j}{2}} \sum_{\substack{ \widetilde{q} \sim 2^m \\ p \sim 2^{\frac{j}{2}+k}}} \sum_{\substack{\ell \sim 2^{\frac{j}{2}-m} \\ n_2 \sim 2^{\frac{j}{2}}}} \left\|f_1 \right\|_{L^2 \left(I^{j, k}_{\frac{p}{2^k}-\left(2^{\frac{j}{2}-m}\widetilde{q}+\ell \right)} \right)} \\
&& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \cdot \left|  \left \langle f_2, \phi_{ p+\frac{\left(2^{\frac{j}{2}-m} \widetilde{q}+\ell \right)^2}{2^{\frac{j}{2}}}, n_2}^{j, 2k} \right \rangle \right| \left| \left \langle f_3^{\widetilde{q}}, \phi_{p, n_2 \left(1+\frac{2\widetilde{q}}{2^{m+k}}+\frac{2\ell}{2^{\frac{j}{2}+k}} \right)}^{j, 2k} \right \rangle \right| \\
&& \quad \lesssim 2^{-\frac{j}{4}+\frac{k}{2}-\frac{\mu j}{2}} \sum_{\substack{ \widetilde{q} \sim 2^m \\ p \sim 2^{\frac{j}{2}+k} \\ \ell \sim 2^{\frac{j}{2}-m}}} \left\|f_1 \right\|_{L^2 \left(I^{j, k}_{\frac{p}{2^k}-\left(2^{\frac{j}{2}-m}\widetilde{q}+\ell \right)} \right)} \left\|f_2 \right\|_{L^2 \left(I_{ p+\frac{\left(2^{\frac{j}{2}-m} \widetilde{q}+\ell \right)^2}{2^{\frac{j}{2}}}}^{j, 2k} \right)} \left\| f_3^{\widetilde{q}} \right\|_{L^2 \left(I_p^{j, 2k} \right)} \\
&& \quad \lesssim 2^{-\frac{j}{4}+\frac{k}{2}-\frac{\mu j}{2}} \sum_{\substack{p \sim 2^{\frac{j}{2}+k} \\ q \sim 2^{\frac{j}{2}}}}  \left\|f_1 \right\|_{L^2 \left(I^{j, k}_{\frac{p}{2^k}-q} \right)} \left\|f_2 \right\|_{L^2 \left(I_{ p+\frac{q^2}{2^{\frac{j}{2}}}}^{j, 2k} \right)} \left\| f_3 \right\|_{L^2 \left(I_p^{j, 2k} \right)} \\
&& \quad \lesssim 2^{\frac{k}{2}-\frac{\mu j}{2}} \left\|f_1 \right\|_{L^2(I^k)}\left\|f_2 \right\|_{L^2(I^k)}\left\|f_3 \right\|_{L^2(I^k)}.
\end{eqnarray*}
In the sparse case--\emph{i.e.} if both $f_1$ and $f_2$ are sparse--from \eqref{20250209eq01} we have
\begin{align*} 
& \left| \Lambda_{j, j, m, \lambda(\cdot)}^k(f^{\textsf{S}_\mu}_1, f^{\textsf{S}_\mu}_2, f_3)\right| \lesssim 2^{-\frac{j}{4}+\frac{k}{2}} \cdot 2^{2\mu j} \cdot \left(\# \sTFC \right)^{\frac{1}{2}} \\
& \quad \cdot \left[ \sum_{\substack{ \widetilde{q} \sim 2^m \\ p \sim 2^{\frac{j}{2}+k}}} \sum_{\substack{\ell \sim 2^{\frac{j}{2}-m} \\ n_2 \sim 2^{\frac{j}{2}}}}   \left\|f_1 \right\|^2_{L^2 \left(I^{j, k}_{\frac{p}{2^k}-\left(2^{\frac{j}{2}-m}\widetilde{q}+\ell \right)} \right)} \left\|f_2 \right\|^2_{L^2 \left(I_{ p+\frac{\left(2^{\frac{j}{2}-m} \widetilde{q}+\ell \right)^2}{2^{\frac{j}{2}}}}^{j, 2k} \right)} \left| \left \langle f_3^{\widetilde{q}}, \phi_{p, n_2 \left(1+\frac{2\widetilde{q}}{2^{m+k}}+\frac{2\ell}{2^{\frac{j}{2}+k}} \right)}^{j, 2k} \right \rangle \right|^2 \right]^{\frac{1}{2}} \nonumber \\
& \lesssim 2^{-\frac{j}{4}+\frac{k}{2}} \cdot 2^{2\mu j} \cdot \left(\# \sTFC \right)^{\frac{1}{2}} \nonumber \\
& \quad \cdot \left[ \sum_{\substack{ \widetilde{q} \sim 2^m \\ p \sim 2^{\frac{j}{2}+k} \\ \ell \sim 2^{\frac{j}{2}-m}}}  \left\|f_1 \right\|^2_{L^2 \left(I^{j, k}_{\frac{p}{2^k}-\left(2^{\frac{j}{2}-m}\widetilde{q}+\ell \right)} \right)} \left\|f_2 \right\|^2_{L^2 \left(I_{ p+\frac{\left(2^{\frac{j}{2}-m} \widetilde{q}+\ell \right)^2}{2^{\frac{j}{2}}}}^{j, 2k} \right)} \left\| f_3 \right\|_{L^2 \left(I_p^{j, 2k} \right)}^2 \right]^{\frac{1}{2}} 
\end{align*}
where 
$$
\sTFC:=\left\{ \substack{(p, \widetilde{q}, l) \in \Z \times \Z \times \Z  \\ \\ p \sim 2^{\frac{j}{2}+k}, \; \widetilde{q} \sim 2^m \; \ell \sim 2^{\frac{j}{2}-m}}:  L_1 \left(\frac{p}{2^k}-l-2^{\frac{j}{2}-m}\widetilde{q} \right) \cong 2\left( \frac{\widetilde{q}}{2^m}+\frac{\ell}{2^{\frac{j}{2}}} \right)L_2 \left(p+\frac{\left(2^{\frac{j}{2}-m} \widetilde{q}+\ell \right)^2}{2^{\frac{j}{2}}} \right)   \right\},
$$
with $L_i: \left[2^{\frac{j}{2}+(i-1)k}, 2^{\frac{j}{2}+(i-1)k+1} \right] \cap \Z \mapsto \left[2^{\frac{j}{2}}, 2^{\frac{j}{2}+1} \right] \cap \Z, i \in \{1, 2\}$ being some measurable functions. 

Our desired decay bound follows from the control over the size of $\sTFC$; indeed, one can verify that there exists some $\widetilde{\epsilon}>0$ such that 
$$
\# \sTFC \lesssim 2^{j+k-\widetilde{\epsilon} j}. 
$$
Consequently, the estimates for both uniform and sparse components can be summarized as follows: there exists $\widetilde{\epsilon}>0$, such that
$$
\left| \Lambda_{j, j, m, \lambda(\cdot)}^{k, \textsf{U}_\mu}(f_1, f_2, f_3)\right| \lesssim 2^{-\frac{\mu}{2} j} \prod_{r=1}^3 \left\|f_r \right\|_{L^{p_j} \left(3I^k \right)} \quad \textrm{and} \quad \left| \Lambda_{j, j, m, \lambda(\cdot)}^{k, \textsf{S}_\mu}(f_1, f_2, f_3)\right| \lesssim 2^{(2\mu-\widetilde{\epsilon}) j} \prod_{r=1}^3 \left\|f_r \right\|_{L^{p_j} \left(3I^k \right)},
$$
and therefore, we conclude that
\begin{equation} \label{20250210eq01}
\left|\Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3) \right| \lesssim 2^{-\frac{\widetilde{\epsilon}}{5} j} \prod_{r=1}^3 \left\|f_r \right\|_{L^{p_j} \left(3I^k \right)},
\end{equation} 
whenever $(p_1, p_2, p_3)=(2, 2, \infty), (2, \infty, 2)$ or $(\infty, 2, 2)$. 

\medskip

\subsection{Treatment of Case ({\bf O2}): Other stationary off-diagonal cases}

Our goal in this section is to extend Theorem \ref{20241018mainthm01} to a slightly more general set-up that also covers the other stationary off-diagonal cases described in Case ({\bf O2}). Indeed, the main result of our section is

\begin{thm} \label{generalizedmain}
For any $k, m \in \N$, consider
$$
\widetilde{\Lambda}^k_m(f_1, f_2, f_3):=2^k \int_{I^k} \int_{I^k} f_1(x-t)f_2(x+t^2)f_3(x)e^{i\lambda(x) t^3} dtdx, 
$$
where
\begin{enumerate}
    \item [$\bullet$] $\lambda(x) \in \left[2^{\frac{m}{2}+\kappa m+3k}, 2^{m+3k+1}\right]$ for some $\kappa>0$;
    \item [$\bullet$] one of the following situations holds:
    \begin{enumerate}
        \item [(1)] $\supp \ \widehat{f_1} \subseteq \left[2^k, 2^{m+k+1} \right]$ and $\supp \ \widehat{f_2} \subseteq \left[2^{m+2k}, 2^{m+2k+1} \right]$;
        \item [(2)] $\supp \ \widehat{f_1} \subseteq \left[2^{m+k}, 2^{m+k+1} \right]$ and $\supp \ \widehat{f_2} \subseteq \left[2^{2k}, 2^{m+2k+1} \right]$.
    \end{enumerate}
\end{enumerate}
Moreover, if either $\supp \ \widehat{f_1}$ is away from $[2^{-100} \cdot 2^{m+k}, 2^{m+k+1}]$ or $\supp \ \widehat{f_2}$ is away from $[2^{-100} \cdot 2^{m+2k}, 2^{m+2k+1}]$, then one may further impose $\lambda \in [2^{m+3k}, 2^{m+3k+1}]$.  

Under the above assumptions, there exists some $\epsilon>0$, such that 
$$
\left| \widetilde{\Lambda}^k_m(f_1, f_2, f_3) \right| \lesssim 2^{-\epsilon \min \{2k, m\}} \prod_{j=1}^3 \left\|f_j \right\|_{L^{p_j}(3I^k)}, 
$$
whenever $(p_1, p_2, p_3)=(2, \infty, 2)$, $(\infty, 2, 2)$ or $(2, 2, \infty)$. 
\end{thm}

\subsubsection{Deducing Case ({\bf O2}) from Theorem \ref{generalizedmain}.} In this brief subsection we provide the proof sketch for how to obtain Case ({\bf O2}) if one assumes the veridicity of Theorem \ref{generalizedmain}.

\medskip

\noindent \underline{\textsf{Case 1: $j \cong \ell, k \ge 0$, and $\frac{j}{2} \le m \le j-100$.}} We start by noticing that without loss of generality, we may assume $j=l$ and also that in this situation, the role of the parameter $m$ in Theorem \ref{generalizedmain} is now replaced by $j$. Moreover, using estimate \eqref{20250210eq01} derived from the Case ({\bf O1}) and a standard continuity argument  (see, again \cite[Appendix 13.3]{HL23}), we may also assume that 
$$
\frac{j}{2}+\kappa j \le m \le j-100
$$
for some $\kappa>0$ sufficiently small (note that estimate \eqref{20250210eq01} is independent of $k$). Therefore, the main term we have to control in this case is given by
$$
\Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3)=2^k \int_{I^k} \int_{I^k} f_{1, j+k}(x-t)f_{2, j+2k}(x+t^2)f_3(x)e^{i \lambda(x) t^3} \phi \left(\frac{\lambda(x)}{2^{m+3k}} \right) dtdx. 
$$
Taking now
$$
\widetilde{\Lambda}_j^{k, 1}(f_1, f_2, f_3):=\sum_{\frac{j}{2}+\kappa j \le m \le j-100} \Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3),
$$
it is easy to notice that Theorem \ref{generalizedmain} applies. 

\medskip 

\noindent \underline{\textsf{Case 2: $l \cong m, k \ge 0$, and $m>j+100$.}} Without loss of generality, we may assume $l=m$, and hence the main term to understand is given by
$$
\Lambda_{j, m, m, \lambda(\cdot)}^k(f_1, f_2, f_3)=2^k \int_{I^k} \int_{I^k} f_{1, j+k}(x-t)f_{2, m+2k}(x+t^2)f_3(x)e^{i \lambda(x) t^3} \phi \left(\frac{\lambda(x)}{2^{m+3k}} \right) dtdx. 
$$
Note that to apply Theorem \ref{generalizedmain}, it suffices to consider
\begin{eqnarray*}
\widetilde{\Lambda}_m^{k, 2}(f_1, f_2, f_3)%
&:=& \sum_{0 \le j \le m-100} \Lambda_{j, m, m, \lambda(\cdot)}^k(f_1, f_2, f_3) \\
&=& 2^k \int_{I^k} \int_{I^k} f_{1, j, k}(x-t)f_{2, m+2k}(x+t^2)f_3(x)e^{i \lambda(x) t^3} \phi \left(\frac{\lambda(x)}{2^{m+3k}} \right) dtdx,
\end{eqnarray*}
where
$$
f_{1, j, k}:= \calF^{-1}\left( \sum_{0 \le j \le m-100} \widehat{f_{1, j+k}} \right).
$$

\medskip 

\noindent \underline{\textsf{Case 3: $m \cong j, k \ge 0$, and $m>l+100$.}} The treatment of this case resembles \textsf{Case 2} above. In this situation, without loss of generality, one considers
\begin{eqnarray} \label{20250210eq20}
\widetilde{\Lambda}_m^{k, 3}(f_1, f_2, f_3)%
&:=& \sum_{0 \le l \le m-100} \Lambda_{m, l, m, \lambda(\cdot)}^k(f_1, f_2, f_3) \nonumber \\
&=& \sum_{0 \le l \le m-100} 2^k \int_{I^k} \int_{I^k} f_{1, m+k}(x-t)f_{2, l+2k}(x+t^2)f_3(x)e^{i \lambda(x) t^3} \phi \left(\frac{\lambda(x)}{2^{m+3k}} \right) dtdx \nonumber \\
&=& 2^k \int_{I^k} \int_{I^k} f_{1, m+k}(x-t)f_{2, m, 2k}(x+t^2)f_3(x)e^{i \lambda(x) t^3} \phi \left(\frac{\lambda(x)}{2^{m+3k}} \right) dtdx,
\end{eqnarray}
where
$$
f_{2, m, 2k}:= \calF^{-1} \left( \sum_{0 \le l \le m-100} \widehat{f_{2, l+2k}} \right).
$$
It is clear that \eqref{20250210eq20} satisfies all the assumptions of Theorem \ref{generalizedmain}.

\subsubsection{Proof of Theorem \ref{generalizedmain}} To this end, we notice that the proof of Theorem \ref{generalizedmain} follows by a straightforward modification of the argument used in the proof of Theorem \ref{20241018mainthm01}. Indeed, carefully  examining the proof of Theorem \ref{20241018mainthm01}, one employs the following three \emph{key} ingredients:
\begin{enumerate}
    \item [(1)] the essential spatial length of constancy for $f_1$ is $2^{-m-k}$;
    \item [(2)] the essential spatial length of constancy of $f_2$ is $2^{-m-2k}$;
    \item [(3)] the height of the re-normalized phase $\widetilde{\lambda}(x):=\frac{\lambda(x)}{2^{\frac{m}{2}+3k}}$ lies in the range $\left[2^{\kappa m}, 2^{\frac{m}{2}} \right]$. 
\end{enumerate}
With these in mind, one can follow the same strategy outlined in Section \ref{20241023overview01}: first, apply the Rank-II LGC to propagate the length of constancy of $\lambda$ to a larger scale; then, use the argument presented in \cite[Theorem 4.3]{HL23} (when $k \ge \frac{m}{2})$) or Rank-I LGC (when $0 \le k \le \frac{m}{2}$) to complete the proof. We leave further details to the interested reader. 


\section{Treatment of the low oscillatory component $BHC^{Lo}$} \label{20250228sec02}

In this section, we treat the low oscillatory component $BHC^{Lo}(f_1, f_2):=\sup\limits_{\lambda \in \R} \left| BHC_\lambda^{Lo}(f_1, f_2) \right|$, where we recall that 
 $$
BHC_{\lambda}^{Lo}(f_1, f_2):=\sum_{k \in \Z} \sum_{(j, l, m) \in \Z^3 \backslash \N^3}BHC_{j, l, m, \lambda}^k(f_1, f_2).
$$
We start with the routine linearization procedure by letting $\lambda(\cdot)$ be the measurable function that maximizes the supremum $\sup\limits_{\lambda \in \R} \left| BHC_\lambda^{Lo}(f_1, f_2) \right|$, and therefore, it suffices to bound the operator 
\begin{equation} \label{multdec}
BHC_{\lambda(\cdot)}^{Lo}(f_1, f_2):=\sum_{k \in \Z} \sum_{(j, l, m) \in \Z^3 \backslash \N^3}BHC_{j, l, m, \lambda(\cdot)}^k(f_1, f_2),
\end{equation} 
where we recall that 
\begin{equation} \label{20241104eq01}
BHC_{j, l, m, \lambda(x)}^k(f_1, f_2)(x):=2^k\phi \left(\frac{\lambda(x)}{2^{m+3k}} \right) \int_{\R} f_{1, j+k}(x-t)f_{2, l+2k}(x+t^2)e^{i\lambda(x)t^3} \rho(2^k t) dt.
\end{equation}
Here, $\rho$ is an odd smooth cut-off and $\phi$ is an even and positive smooth cut-off both supported in $\left[-4, 4 \right] \backslash \left[-\frac{1}{4}, \frac{1}{4} \right]$, $f_{1, j+k}=\calF^{-1} \left( \widehat{f_1} \phi \left(\frac{\cdot}{2^{j+k}} \right)\right)$ and $f_{2, l+2k}=\calF^{-1} \left(\widehat{f_2} \phi \left(\frac{\cdot}{2^{l+2k}} \right) \right)$. The main result of this section is given by
\begin{thm}\label{thmin} 
For any $1<p,\,q<\infty$ and $\frac{1}{2}< r<\infty$ with $\frac{1}{p}+\frac{1}{q}=\frac{1}{r}$ the following holds:
\begin{equation}\label{20241106thm01}
\left\|BHC^{Lo}(f_1, f_2)\right\|_r\lesssim_{p,q} \|f_1\|_p\,\|f_2\|_q\,.
\end{equation}
\end{thm}
Our analysis will be split into seven distinct cases depending on the sign of each of the parameters $j,\,l,\,m\in\Z$ appearing in \eqref{multdec}. Indeed, for $*_1,\,*_2,\,*_3\in\{-,\,+\}$, we set
\begin{equation}\label{decompnegat}
BHC_{*_1,\,*_2,\,*_3, \lambda(\cdot)}(f_1, f_2):=\sum_{k\in\Z}\sum_{j\in \Z_{*_1}}\sum_{l\in \Z_{*_2}}\sum_{m\in \Z_{*_3}} BHC_{j, l, m, \lambda(\cdot)}^k(f_1, f_2),
\end{equation}
where $\Omega:=\left\{\left(*_1,\,*_2,\,*_3\right)\,|\, \left(*_1,\,*_2,\,*_3 \right)^3 \in \{-,\,+\}^3\setminus\{\left(+,+,+\right)\right\}$ and list below the seven cases that are of interest for us: 
\begin{itemize}
\item \textbf{Case A}: \textsf{$j<0$, $l<0$, and $m \le 0$;}
\item \textbf{Case B}: \textsf{$j<0$, $l<0$, and $m>0$;}
\item \textbf{Case C}: \textsf{$j<0$, $l\geq 0$, and $m \le 0$;}
\item \textbf{Case D}: \textsf{$j< 0$, $l\geq 0$, and $m> 0$;}
\item \textbf{Case E}: \textsf{$j\geq 0$, $l<0$, and $m \le 0$;}
\item \textbf{Case F}: \textsf{$j\geq 0$, $l<0$, and $m>0$;}
\item \textbf{Case G}: \textsf{$j \geq 0, l \ge 0$, and $m \le 0$.}
\end{itemize}
To this end, we introduce the notation $\psi(x):=\sum\limits_{\ell \in \Z \backslash \N} \phi \left(\frac{x}{2^{\ell}} \right)$, and $\check{\psi}_k(x):=2^k \check{\psi}(2^k x)$. 

\subsection{Treatment of the Cases A, C, E, and G: $m \le 0$}  We notice that in all of these cases $m \le 0$ which together with the support conditions on $\phi$ and $\rho$ yields $\lambda(x) t^3 \lesssim 1$. Therefore, one can put together all the cases {\bf A, C, E}, and {\bf G} and encapsulate them into the study of the following operator:
$$
BHC^{Lo, \le}_{\lambda (\cdot)}(f_1, f_2)(x):=\int_{\R} f_1(x-t)f_2(x+t^2)e^{i\lambda(x)t^3} \chi(\lambda(x), t) \frac{dt}{t},
$$
where 
$$
\chi(\lambda, t):=\sum_{\substack{\ell, k \in \Z \\ \ell+k \ge 0}} \rho(2^{3\ell} \lambda) \rho(2^k t).
$$
Note that $\chi$ enjoys the following properties: 1) $\chi(\lambda, t) \lesssim 1$ for al $\lambda, t \neq 0$, and 2) if $\chi(\lambda, t) \neq 0$, then $|\lambda t^3| \lesssim 1$. Our goal is to show that $BHC^{Lo, \le}_{\lambda (\cdot)}(f_1, f_2)$ satisfies estimate \eqref{20241106thm01}, which is a direct consequence of 
\begin{equation} \label{20250216eq21}
\left|BHC^{Lo, \le}_{\lambda (\cdot)}(f_1, f_2) \right| \lesssim \calH^*_{\calC}(f_1, f_2)+\calM_{\calC}(f_1, f_2)\,,
\end{equation}
where
\begin{enumerate}
    \item [$\bullet$] $\calH^*_{\calC}(f_1, f_2)$ is the \emph{maximal (smooth) truncation of the bilinear Hilbert transform along the curve $(-t, t^2)$}
    $$
    \calH^*_{\calC}(f_1, f_2)(x):=\sup_{r>0} \left| \int_\R f_1(x-t)f_2(x+t^2) \theta \left(\frac{t}{r} \right) \frac{dt}{t} \right|,
    $$
    with $\theta$ being a suitable smooth bump function supported near the origin, and
    \item [$\bullet$] $\calM_{\calC}(f_1, f_2)$ is the \emph{bilinear maximal function along the curve $(t, t^2)$}
    \begin{equation} \label{bilinearmax}
    \calM_{\calC}(f_1, f_2)(x):=\sup_{r>0} \frac{1}{2r} \int_{-r}^r \left|f_1(x-t) \right| \left|f_2(x+t^2) \right|dt.
    \end{equation}
\end{enumerate}
Indeed, notice that if \eqref{20250216eq21} holds, then the desired estimate \eqref{20241106thm01} follows from the existing estimates for these operators (see, e.g., \cite{{GL20}}). Now, to see that \eqref{20250216eq21} holds, we split $BHC^{Lo, \le}_{\lambda (\cdot)}(f_1, f_2)(x)$ as follows:
\begin{align*}
BHC^{Lo, \le}_{\lambda (\cdot)}(f_1, f_2)(x) 
&= \int_{\R} f_1(x-t)f_2(x+t^2)\chi(\lambda(x), t) \frac{dt}{t} \\
& \quad +\int_{\R} f_1(x-t)f_2(x+t^2) \left(e^{i\lambda(x)t^3}-1 \right) \chi(\lambda(x), t) \frac{dt}{t} \\
&:= I+II.
\end{align*}
For the first term $I$, we have 
\begin{align*}
|I| 
&= \left| \int_{\R} f_1(x-t)f_2(x+t^2)\chi(\lambda(x), t) \frac{dt}{t} \right| \\
&=\left| \sum_{\ell \in \Z} \rho (2^{3\ell} \lambda(x)) \int_\R f_1(x-t)f_2(x+t^2)  \theta\left(\frac{t}{2^\ell} \right) \frac{dt}{t} \right| \\
& \le \left( \sum_{\ell \in \Z} \rho \left(2^{3\ell} \lambda(x) \right) \right) \calH_{\calC}^*(f_1, f_2)(x) \lesssim \calH_{\calC}^*(f_1, f_2)(x),
\end{align*}
where here we denote $\theta(t):=\sum_{k \ge 0} \rho(2^k t)$ (a smooth bump function supported near the origin). 

For the second term, we use the basic relations $|e^{is}-1| \le |s|$ and $\chi(\lambda, t)\lesssim \one_{[-C, C]} (\lambda t^3)$ in order to deduce 
\begin{align*}
|II|
& \lesssim \int_{t: |\lambda(x)t^3| \lesssim 1} |f_1(x-t)||f_2(x+t^2)||\lambda(x)t^3| \frac{dt}{|t|} \\
& \lesssim  \sum_{\ell \in \N} 2^{-\ell} \cdot \frac{1}{2^{-\frac{\ell}{3}} |\lambda(x)|^{-\frac{1}{3}}} \int_{\{t: |t| \lesssim 2^{-\frac{\ell}{3}}|\lambda(x)|^{-\frac{1}{3}}\}   } |f_1(x+t)||f_2(x+t^2)|dt \\
& \lesssim \calM_{\calC}(f_1, f_2)(x). 
\end{align*}
This concludes the proof of \eqref{20250216eq21}. 

\subsection{Treatment of Cases B:  $j<0$, $l<0$, and $m>0$}

In this situation, for a given $k\in\Z$, the multiplier associated to $BHC_{-,-,+, \lambda(\cdot)}^k$ is given by
$$
\mathfrak{m}_{-, -, +, \lambda(x)}^k(\xi,\eta)=\sum_{m\in\N} \mathfrak{m}_{-, -, m, \lambda(x)}^k(\xi,\eta), 
$$
where 
$$
\mathfrak{m}_{-, -, m, \lambda(x)}^k(\xi,\eta):=\left[\int_\R e^{i \left(-\frac{\xi}{2^k}t+\frac{\eta}{2^{2k}}t^2+\frac{\lambda(x)}{2^{3k}} t^3 \right)}\rho(t)\,dt\right]\,\psi\left(\frac{\xi}{2^{k}}\right)\,
\psi\left(\frac{\eta}{2^{2k}}\right)\,\phi\left(\frac{\lambda(x)}{2^{m+3k}}\right)\,,
$$
Applying a Taylor series argument followed by an integration by parts, we further have
\begin{eqnarray*}\label{multdecB1}
%
&&\mathfrak{m}_{-, -, m, \lambda(x)}^k(\xi,\eta) \\
&&=\sum_{\ell_1, \ell_2 \ge 0} \frac{C_{\ell_1, \ell_2}}{\ell_1! \ell_2!} \left(\frac{\xi}{2^k} \right)^{\ell_1} \psi \left(\frac{\xi}{2^k} \right) \left(\frac{\eta}{2^{2k}} \right)^{\ell_2} \psi \left(\frac{\eta}{2^{2k}} \right) \phi \left(\frac{\lambda(x)}{2^{m+3k}} \right) \int_{\R} e^{i \frac{\lambda(x)}{2^{3k}}t^3} t^{\ell_1+2\ell_2} \rho(t)dt \nonumber \\
&& \approx \frac{1}{2^m} \sum_{\ell_1, \ell_2 \ge 0} \frac{\tilde{C}_{\ell_1, \ell_2}}{\ell_1! \ell_2!}\,\left(\frac{\xi}{2^k} \right)^{\ell_1} \psi \left(\frac{\xi}{2^k} \right) \left(\frac{\eta}{2^{2k}} \right)^{\ell_2} \psi \left(\frac{\eta}{2^{2k}} \right) \tilde{\phi} \left(\frac{\lambda(x)}{2^{m+3k}} \right)    \int_{\R} e^{i \frac{\lambda(x)}{2^{3k}}t^3} \left(t^{\ell_1+2\ell_2-2} \rho(t)\right)' dt\,,
\end{eqnarray*}
where $\tilde{C}_{\ell_1, \ell_2}$ and $\tilde{\phi}$ are some objects with features similar to the original $C_{\ell_1, \ell_2}$ and $\phi$, respectively. 

This implies
$$
\left| \sum_{k \in \Z} BHC_{-, -, +, \lambda(\cdot)}^k(f_1, f_2) (x)\right| \lesssim Mf_1(x)Mf_2(x),
$$
which gives the desired estimate \eqref{20241106thm01}. Here $Mf$ refers to the standard Hardy-Littlewood maximal operator. 


\subsection{Treatment of Case D: $j< 0$, $l\ge 0$, and $m>0$}  
As before, we start with a Taylor series development for the multiplier: 
\begin{equation} \label{multdecE}
\frakm_{-, l, m, \lambda(x)}^k(\xi, \eta)=\sum_{\ell_1 \ge 0} \frac{C_{\ell_1}}{\ell_1!} \left(\frac{\xi}{2^k} \right)^{\ell_1} \psi \left(\frac{\xi}{2^k} \right) \phi \left(\frac{\eta}{2^{2k+l}} \right) \phi \left(\frac{\lambda(x)}{2^{3k+m}} \right) \int_{\R} e^{i \left(\frac{\eta}{2^{2k}}t^2+\frac{\lambda(x)}{2^{3k}}t^3 \right)} t^{\ell_1}\rho(t)dt
\end{equation} 
Due to the fast decay in the parameters $\ell_1$ it suffices to consider $\ell_1=0$.
\medskip

\noindent \textsf{Subcase E.1: $l\ncong m$.} \quad  In this situation the phase in the integral term of \eqref{multdecE} has no stationary points. Thus, applying an integration by parts argument, we have
\begin{equation}\label{multdecE1}
\frakm_{-, l, m, \lambda(x)}^k(\xi, \eta) \approx  \frac{1}{2^{\max\{l, m\}}} \Big(\int_\R e^{i\,\frac{\eta}{2^{2k}}t^2}\, e^{i\,\frac{\lambda(x)}{2^{3k}}t^3}\,\rho(t)\,dt\Big)\, \psi\Big(\frac{\xi}{2^{k}}\Big) \phi\Big(\frac{\eta}{2^{2k+l}}\Big) \phi\Big(\frac{\lambda(x)}{2^{3k+m}}\Big)\,.
\end{equation}
As a consequence by Cauchy-Schwarz, 
\begin{eqnarray*}
%
&& \left|BHC_{-,\,+,\,+, \lambda(x)}(f_1,f_2)(x)\right|_{\textnormal{\textsf{E.1}}} \\
&& \approx \left|\sum_{k\in\Z}\sum_{{l,m\in\N}\atop{|l-m|\gtrsim 1}}\,
\frac{1}{2^{\max\{l, m\}}}\,(f_1*\check{\psi}_k)(x)\,
\left(\int_{\R} (f_2*\check{\phi}_{2k+l})\left(x+\frac{t^2}{2^{2k}}\right)\,e^{i\,\frac{\lambda(x)}{2^{3k}}t^3}\,\rho(t)\,dt\right)\,
\phi\Big(\frac{\lambda(x)}{2^{3k+m}}\Big)\right| \\
&&\lesssim\sum_{k\in\Z}\sum_{{l,m\in\N}\atop{|l-m|\gtrsim 1}}\,
\frac{1}{2^{\max\{l, m\}}}\,|f_1*\check{\psi}_k|(x)\,
\left(\int_{\R} \left|(f_2*\check{\phi}_{2k+l})\left(x+\frac{t^2}{2^{2k}}\right)\,\rho(t)\right|\,dt\right)\,
\phi\Big(\frac{\lambda(x)}{2^{3k+m}}\Big)\\
&&\lesssim \sum_{{l,m\in\N}\atop{|l-m|\gtrsim 1}}\,
\frac{1}{2^{\max \{l, m\}}}\,Mf_1(x)\,\left(\int_{\R} \calS^{\phi}_{2, 2^{\frac{l}{2}} t} f_2(x)\,|\rho(t)|\,dt\right), 
\end{eqnarray*}
where $\calS_{\iota, t}^{\phi}f$ is the $t$-shifted square maximal operator defined as 
$$
\calS_{\iota, t}^\phi f(x):=\left( \sum_{k \in \Z} \left| \left(f*\check{\phi}_{\iota k} \right) \left(x+\frac{t^{\iota}}{2^{\iota k}} \right) \right|^2 \right)^{\frac{1}{2}}. 
$$
The desired estimate \eqref{20241106thm01} is then a consequence of the following estimate: 
$$
\left\|\calS_{2, 2^{\frac{l}{2}}t}^{\phi}f \right\|_p \lesssim_{\phi, p} (1+l)^{\frac{2}{p^*}-1} \left\|f\right\|_p,
$$ 
where $p^*=\min\{p, p'\}$ (see, \cite[Proposition 42]{Lie18} or \cite[Lemma 3.3]{GL20}).
\medskip

\noindent \textsf{Subcase E.2: $l\cong m$.} \quad In this situation, for each given $k\in\Z$ and $m\in\N$, the phase in the integral term of \eqref{multdecE} may have a stationary point of magnitude $\simeq 1$. This is the context that naturally connects with the topic of the curved $\gamma$-Carleson operators as discussed in \cite{Lie2024}. More precisely, we have 
\begin{eqnarray*} 
%
&& |BHC_{-,\,+,\,+, \lambda(x)}(f_1,f_2)(x)|_{\textnormal{\textsf{E.2}}} \nonumber \\
&& \approx \left|\sum_{k\in\Z}\sum_{m\in\N}\,
(f_1*\check{\psi}_k)(x)\,
\left(\int_{\R} (f_2*\check{\phi}_{2k+m}) \left(x+\frac{t^2}{2^{2k}} \right)\,e^{i\,\frac{\lambda(x)}{2^{3k}}t^3}\,\rho(t)\,dt\right)\,
\phi\Big(\frac{\lambda(x)}{2^{3k+m}}\Big)\right|  \nonumber \\
&& \approx \left|\sum_{k\in\Z}\sum_{m\in\N}\,
(f_1*\check{\psi}_k)(x)\,
\left(\int_{\R} (f_2*\check{\phi}_{2k+m})(x+t)\,e^{i\,\lambda(x)\,t^{\frac{3}{2}}}\,2^{2k}\,\tilde{\rho}(2^{2k}\,t)\,dt\right)\,
\phi\Big(\frac{\lambda(x)}{2^{3k+m}}\Big)\right|  \nonumber \\
&& \lesssim \sum_{m\in\N} \left(\sum_{k\in\Z} \left|(f_1*\check{\psi}_k)(x)\,\phi\Big(\frac{\lambda(x)}{2^{3k+m}}\Big)\right|^2\right)^{\frac{1}{2}}
\,\left(\sum_{k\in\Z} \left|\calC_{\gamma, 2k, m}f_2(x) \right|^2\right)^{\frac{1}{2}}  \nonumber \\
&& \lesssim Mf_1(x) \cdot \sum_{m\in\N}  \left(\sum_{k\in\Z} \left|\calC_{\gamma, 2k, m}f_2(x) \right|^2\right)^{\frac{1}{2}}\:,
\end{eqnarray*}
where $\widetilde{\rho}(t):=t^{-1/2}\rho\left(t^{1/2}\right)$, and $\calC_{\gamma, 2k, m} f$ is the $\gamma$-Carleson operator for $\gamma(x, t):=\lambda(x) t^{\frac{3}{2}}$: 
\begin{align} \label{20250218eq01}
\calC_{2k,m}f(x) 
&=\left( \int_{\R} (f*\check{\phi}_{2k+m}) \left(x+\frac{t}{2^{2k}} \right) e^{i \gamma\left(x, \frac{t}{2^{2k}} \right)} \tilde{\rho}(t)\,dt \right) \phi \left(\frac{\lambda(x)}{2^{m+3k}}\right) \nonumber \\
&:=\left( \int_{\R} (f*\check{\phi}_{2k+m}) \left(x+\frac{t}{2^{2k}} \right) e^{i \frac{\lambda(x) t^{\frac{3}{2}}}{2^{3k}}} \tilde{\rho}(t)\,dt \right) \phi \left(\frac{\lambda(x)}{2^{m+3k}}\right).
\end{align} 
Finally, estimate \eqref{20241106thm01} can be now achieved by combining  Minkowski, Fefferman-Stein maximal inequality, interpolation and the following features of the operator \eqref{20250218eq01}: 
\begin{enumerate}
    \item [$\bullet$] (\emph{$L^2$--estimate}) Appealing to \cite[Proposition 48]{Lie2024}, there exists some $\epsilon>0$, such that
$$
\|\calC_{2k,m} f\|_2 \lesssim 2^{-\epsilon m}\,\|f*\check{\phi}_{2k+m}\|_2;
$$
\item [$\bullet$] (\emph{$L^p$--estimate}) For fixed $m \in \N$, one has the trivial bound
$$
\left| \calC_{\gamma, 2k, m} f(x) \right| \lesssim \left(\int_{\R} \calM^{(-2^m t)} f(x) \rho(t) dt\right) \cdot \phi \left(\frac{\lambda(x)}{2^{m+3k}} \right),
$$
where 
$$
\calM^{(2^m t)}f(x)=\sup_{k \in \Z} \left|\left(f*\check{\phi}_k \right) \left(x-\frac{2^m t}{2^k} \right) \right|
$$
enjoys---see, e.g., \cite[Lemma 3.4]{GL20}---the $L^p$ estimate
$$
\left\|\calM^{(2^m t)}f \right\|_p \lesssim (1+m)^{\frac{1}{p}} \left\|f\right\|_p\qquad \textrm{for any}\:\:|t| \sim 1\,. 
$$
\end{enumerate}

We leave further details to the interested reader.


\subsection{Treatment of Case F: $j\geq 0$, $l<0$, and $m>0$}  
The approach in this case is similar to the one in Case D above with just some straightforward changes: the roles of $f_1$ and $f_2$ are interchanged, the term $\frac{t^2}{2^{2k}}$ is replaced in the new context by $\frac{t}{2^{k}}$ and one appeals to the $\gamma$-Carleson operator for $\gamma(x,t)=\lambda(x)\,t^{3}$. Thus, one can immediately verify that \eqref{20241106thm01} holds.
\bigskip 

\section{The maximal quasi-Banach boundedness range of $BHC$} \label{20250309sec01}

In this last section we provide the desired maximal\footnote{Up to end-points.} quasi-Banach range for our main operator $BHC$ as stated in {\bf Main Theorem} \ref{mainresult}.

We start by recalling the main decomposition of our operator: 
\begin{eqnarray*}
%
BHC(f_1, f_2) &\le&  BHC^{Hi}(f_1, f_2)\,+\,BHC^{Lo}(f_1, f_2) \\
&\le&  \begin{matrix} \underbrace{BHC^{\Delta}(f_1, f_2)} \\ \textnormal{{\bf main diagonal}} \end{matrix}\quad+\quad\begin{matrix} \underbrace{BHC^{\not\Delta, S}(f_1, f_2)} \\ \textnormal{{\bf stationary off-diagonal}}  \end{matrix}\\
&+&\begin{matrix} \underbrace{BHC^{\not\Delta, NS}(f_1, f_2)} \\ \textnormal{{\bf non-stationary off-diagonal}} \end{matrix}\quad + \quad \begin{matrix} \underbrace{BHC^{Lo}(f_1, f_2)} \\  \textnormal{{\bf low oscillatory}} \end{matrix}.
\end{eqnarray*}
Since in Section \ref{20250228sec01} and Section \ref{20250228sec02}, we have established the full quasi-Banach range for both the non-stationary off-diagonal and the low-oscillatory components our main focus in this section will be on the other two remaining components.\footnote{Throughout this whole section, we assume that $k \ge 0$. A sketch of the case $k\le 0$ can be found in the Appendix.}

\subsection{Treatment of the main diagonal component $BHC^{\Delta}$: Tame bounds}\label{20250308sec10}

In this first subsection, we provide slowly growing\footnote{\emph{I.e}, at most polynomially in the parameters $k,\,m\in\N$.} restricted weak type bounds for the sub-components of $BHC^{\Delta}$. We start by recalling that in this case, the main term we have to understand takes the form
\begin{equation}\nonumber
\Lambda_m^k(f_1, f_2, f_3)= \int_{\R^2} (f_1*\check{\phi}_{m+k}) \left(x-\frac{t}{2^k} \right) (f_2* \check{\phi}_{m+2k}) \left(x+\frac{t^2}{2^{2k}} \right) f_3(x) e^{i \lambda(x) \frac{t^3}{2^{3k}}} \rho(t) \phi \left(\frac{\lambda(x)}{2^{m+3k}} \right) dtdx,  
\end{equation}
where here  $f_i* \check{\phi}_{m+ik}$ refers to the Fourier projection of $f_i$ on the frequency interval $[2^{m+ik},\,2^{m+ik+1}]$, $\lambda (\cdot)$ is some real measurable function taking values of the size $\sim 2^{m+3k}$ and $\rho$ is an odd function with $\supp \ \rho \subseteq \left[-4, 4 \right] \backslash \left[-\frac{1}{4}, \frac{1}{4} \right]$. Throughout this section we let $|f_i| \le \one_{F_i}$, $i\in\{1,2,3\}$, where $F_1$ and $F_2$ are some arbitrary measurable sets, and $F_3$ is any measurable set with positive finite measure. 

One technical subtlety in providing restricted weak type estimates for the above expression is that this task needs to be treated differently based on both the spatial and frequency information of the input functions. This becomes especially important\footnote{See the proof of Theorem \ref{refinedrefined}.}  when dealing with the stationary off-diagonal component $BHC^{\not\Delta, S}$ in Section \ref{20250309sec02}.

\subsubsection{The cases $0 \le k \le 2m$ ($m$ fixed) and $0 \le m \le 2k$ ($k$ fixed): a single-scale argument} \label{20250415subsec01}  In this situation, we prove restricted weak-type estimate directly for the single term $\Lambda_m^k(f_1, f_2, f_3)$ appealing \emph{only} to the spatial information of the input functions $f_1, f_2$, and $f_3$. Indeed, it is enough to notice that
\begin{align} \label{20250430eq02}
\left| \Lambda_m^k(f_1, f_2, f_3) \right|
& \lesssim \int_{\R} \left(\int_{\R} Mf_1 \left(x-\frac{t}{2^k} \right) Mf_2 \left(x+\frac{t^2}{2^{2k}} \right) |\rho(t)|dt \right) |f_3(x)|dx 
\nonumber \\
& \lesssim \int_{\R} \calM_{\calC} (Mf_1, Mf_2)(x) |f_3(x)|dx, 
\end{align}
where we recall that $\calM_{\calC}(f_1, f_2)$ is the \emph{bilinear maximal function along the curve} $(t, t^2)$ (see \eqref{bilinearmax}). Since $\calM_{\calC}(f_1, f_2)$ maps $L^{p_1} \times L^{p_2} \to L^r$ with $\frac{1}{r}=\frac{1}{p_1}+\frac{1}{p_2}$ satisfying $1 \le p_1, p_2 \le \infty$ and $\frac{1}{2}<r \le \infty$, one further has that for any $\theta>0$, there exists some $F_3' \subseteq F_3$ with $|F_3'| \ge \frac{|F_3|}{2}$ such that for $|f_3| \le \one_{F_3'}$, 
\begin{align} \label{20250415eq30Z}
\left| \Lambda_m^k(f_1, f_2, f_3) \right | 
& \lesssim_{\theta} \left\|\calM_{\calC}(Mf_1, M f_2) \right\|_{L^{\frac{1}{2}+\theta}} |F_3|^{\frac{2\theta-1}{2\theta+1}} \lesssim \left\|Mf_1 \right\|_{L^{1+2\theta}} \left\|M f_2 \right\|_{L^{1+2\theta}} |F_3|^{\frac{2\theta-1}{2\theta+1}}  \nonumber \\
& \lesssim_{\theta} \left\|f_1 \right\|_{L^{1+2\theta}} \left\| f_2 \right\|_{L^{1+2\theta}} |F_3|^{\frac{2\theta-1}{2\theta+1}} \le |F_1|^{\frac{1}{1+2\theta}}|F_2|^{\frac{1}{1+2\theta}}|F_3|^{\frac{2\theta-1}{2\theta+1}},
\end{align}
which proves the desired restricted weak-type estimate in this case. 


\subsubsection{The case $ k \ge 2m$ ($m$ fixed): a multi-scale argument} \label{20250415subsec02}  In this situation we provide restricted weak-type estimates for the term
    $$
    \Lambda_m^{\ge}(f_1, f_2, f_3):=\sum_{k \ge 2m} \Lambda_m^k(f_1, f_2, f_3)\,,
    $$
by allowing the implicit bounds to depend polynomially on $m$. First of all, via some standard Fourier analytic arguments (see for example the by-product of Rank I LGC in Section \ref{20250228sec03} and also \cite[Section 4.3]{GL25}), we may, without loss of generality, assume that
\begin{align*}
\Lambda_m^{\ge} (f_1, f_2, f_3)
&=\sum_{k \ge 2m} \int_{\R^2} \left(f_1*\check{\phi}_{m+k} \right) \left(x-\frac{t}{2^k}\right)\left(f_2*\check{\phi}_{m+2k}\right)\left(x+\frac{t^2}{2^{2k}}\right) \\
& \qquad \qquad \qquad \qquad  \cdot \left(f_3*\check{\phi}_{m+2k} \right)(x) e^{i\lambda(x)\frac{t^3}{2^{3k}}} \rho(t) \phi \left(\frac{\lambda(x)}{2^{m+3k}} \right)dtdx. 
\end{align*}
Discretizing the form above first for the $x$ variable and then for the $t$ variable, we have 
\begin{eqnarray} \label{20250301eq01}
%
&& \left|\Lambda_m^{\ge}(f_1, f_2, f_3) \right| \lesssim \sum_{\substack{ k \ge 2m \\ z \in \Z}}  \frac{1}{2^{m+2k}} \int_{\frac{1}{4}}^4 \left| \left(f_1*\check{\phi}_{m+k} \right) \left(\frac{z}{2^{m+2k}}-\frac{t}{2^k} \right) \right| \left| \left(f_2*\check{\phi}_{m+2k} \right) \left(\frac{z}{2^{m+2k}}+\frac{t^2}{2^{2k}} \right) \right| \nonumber \\
&& \qquad \quad \qquad \qquad \quad \qquad \cdot \left| \left(f_3*\check{\phi}_{m+2k} \right) \left(\frac{z}{2^{m+2k}}  \right) \right|dt \nonumber  \\
&&\simeq \frac{1}{2^m} \sum_{k \ge 2m} \sum_{\substack{r \in \Z \\ p \sim 2^m}} \frac{1}{\left|I_r^{m+k} \right|^{\frac{1}{2}}} \left| \left \langle f_1, \Phi_{P_{m+k}(r-p)} \right \rangle \right| \left[ \sum_{I_u^{m+2k} \subseteq I_r^{m+k}} \left| \left \langle f_2, \Phi_{P_{m+2k}\left(u+\frac{p^2}{2^m} \right)} \right \rangle \right| \left| \left \langle f_3, \Phi_{P_{m+2k}(u)} \right \rangle \right| \right] \nonumber \\
&&\simeq \frac{1}{2^m} \sum_{k \ge 2m} \sum_{\substack{r \in \Z \\ p \sim 2^m}} \frac{1}{\left|I_r^{m+k} \right|^{\frac{1}{2}}} \left| \left \langle f_1, \Phi_{P_{m+k}(r-p)} \right \rangle \right| \left[ \sum_{I_u^{m+2k} \subseteq I_r^{m+k}} \left| \left \langle f_2, \Phi_{P_{m+2k}(u)} \right \rangle \right| \left| \left \langle f_3, \Phi_{P_{m+2k}\left(u-\frac{p^2}{2^m}\right)} \right \rangle \right| \right] \nonumber \\
&&\simeq \frac{1}{2^m} \sum_{k \ge 2m} \sum_{\substack{r \in \Z \\ p \sim 2^m}} \frac{1}{\left|I_r^{m+k} \right|^{\frac{1}{2}}} \left| \left \langle f_1, \Phi_{P_{m+k} \left(r-2^{\frac{m}{2}}p^{\frac{1}{2}} \right)} \right \rangle \right| \nonumber   \\
&& \qquad \quad \qquad \qquad \quad \qquad \cdot \left[ \sum_{I_u^{m+2k} \subseteq I_r^{m+k}} \left| \left \langle f_2, \Phi_{P_{m+2k}(u)} \right \rangle \right| \left| \left \langle f_3, \Phi_{P_{m+2k}\left(u-p\right)} \right \rangle \right| \right], 
\end{eqnarray}
where $I_r^{m+k}:=\left[\frac{r}{2^{m+k}}, \frac{r+1}{2^{m+k}} \right]$, $P_{m+k}(v)$ is the time-frequency tile adapted to $\left[\frac{v}{2^{m+k}}, \frac{v+1}{2^{m+k}} \right] \times \left[2^{m+k}, 2^{m+k+1} \right]$, and $\Phi_{P_{m+k}(v)}$ is the $L^2$-normalized Gabor wave packet adapted to it. Moreover, in the last step of the above estimate, we have used the change of variable $p \to 2^{\frac{m}{2}}p^{\frac{1}{2}}$. 

Now by an $\ell^1$--$\ell^\infty$   H\"older in the $p$ parameter, we further have
\begin{eqnarray*}
%
&& \left| \Lambda_m^{\ge}(f_1, f_2, f_3) \right| \lesssim \sum_{\substack{r \in \Z \\ k \ge 2m}} \frac{1}{\left|I_r^{m+k}\right|^{\frac{1}{2}}} \left(\frac{1}{2^m} \sum_{p \sim 2^m} \left| \left \langle f_1, \Phi_{P_{m+k} \left(r-2^{\frac{m}{2}}p^{\frac{1}{2}} \right)} \right\rangle \right| \right) \\
&& \qquad \quad \qquad \qquad \quad \qquad \cdot \left[ \sum_{I_u^{m+2k} \subseteq I_r^{m+k}} \left| \left \langle f_2, \Phi_{P_{m+2k}(u)} \right \rangle \right| \left| \left \langle f_3, \Phi_{P_{m+2k}\left(u-p \left(I_r^{m+k} \right)\right)} \right \rangle \right| \right], 
\end{eqnarray*}
where 
$$
p(\cdot): \left\{I_r^{m+k} \right\}_{r \in \Z, \; k \ge 2m} \mapsto [2^m, 2^{m+1}] \cap \N \quad \textrm{is any measurable function}.
$$
Assume now $f_1, f_2$, and $f_3$ verify the standard assumptions involved in a restricted weak-type estimate: 
$$
|f_1| \le \one_{F_1}, \quad |f_2| \le \one_{F_2}, \quad \textrm{and} \quad |f_3| \le \one_{F_3'}, 
$$
where
\begin{equation} \label{20250626eq10}
F_3':=F_3 \backslash \Omega\qquad \textrm{with}\qquad\Omega:=\left\{M\one_{F_1} \ge C \frac{|F_1|}{|F_3|}  \right\}\cup \left\{M\one_{F_3} \ge C\right\}
\end{equation}
for some $C>0$ sufficiently large such that $|F_3'| \ge \frac{|F_3|}{2}$. Note here that $\Omega$ is \emph{independent} of the choice of both $m$ and the measurable function $p(\cdot)$. 

Next, for $\beta \in \N$, set 
\begin{equation} \label{20250626eq01}
\calI_\beta:=\left\{I_{\widetilde{r}}^k: 1+\frac{\dist(I_{\widetilde{r}}^k, \; \Omega^c)}{\left|I_{\widetilde{r}}^k\right|} \simeq 2^\beta, \; \widetilde{r} \in \Z \right\}. 
\end{equation} 
This allows us to write 
\begin{equation} \label{20250626eq02}
\left| \Lambda_m^{\ge} (f_1, f_2, f_3) \right| \lesssim \sum_{\beta \in \N} \Lambda_m^{\ge, \beta} (f_1, f_2, f_3), 
\end{equation} 
where
$$
\Lambda_m^{\ge, \beta} (f_1, f_2, f_3):=\sum_{k \ge 2m}  \sum_{I_{\widetilde{r}}^k \in \calI_\beta} \left(\frac{1}{\left| I_{\widetilde{r}}^k \right|} \int_{I_{\widetilde{r}}^k}|f_1| \right) \left[ \sum_{\substack{I_u^{m+2k} \subseteq I_r^{m+k} \\ I_r^{m+k} \subseteq I_{\widetilde{r}}^k}} \left| \left \langle f_2, \Phi_{P_{m+2k}(u)} \right \rangle \right| \left| \left \langle f_3, \Phi_{P_{m+2k}\left(u-p \left(I_r^{m+k} \right)\right)} \right \rangle \right| \right]. 
$$
Using now \eqref{20250626eq01} and Cauchy-Schwarz, we have for each $\beta \in \N$, 
\begin{align} \label{20250626eq03} 
\Lambda_m^{\ge , \beta}(f_1, f_2, f_3) 
& \lesssim  \frac{2^\beta |F_1|}{|F_3|} \cdot \sum_{k \ge 2m}  \sum_{I_{\widetilde{r}}^k \in \calI_\beta} \sum_{\substack{I_u^{m+2k} \subseteq I_r^{m+k} \\ I_r^{m+k} \subseteq I_{\widetilde{r}}^k}} \left| \left \langle f_2, \Phi_{P_{m+2k}(u)} \right \rangle \right| \left| \left \langle f_3, \Phi_{P_{m+2k}\left(u-p \left(I_r^{m+k} \right)\right)} \right \rangle \right| \nonumber \\
& \lesssim  \frac{2^\beta |F_1|}{|F_3|} \cdot  \int_{\R} \sum_{k \ge 2m} \sum_{\substack{I_u^{m+2k} \subseteq I_r^{m+k} \\ I_r^{m+k} \subseteq I_{\widetilde{r}}^k \\ I_{\widetilde{r}}^k \in \calI_\beta}} \frac{ \left| \left \langle f_2, \Phi_{P_{m+2k}(u)} \right \rangle \right|}{\left|I_u^{m+2k} \right|^{\frac{1}{2}}} \cdot \frac{ \left| \left \langle f_3, \Phi_{P_{m+2k}\left(u-p \left(I_r^{m+k} \right)\right)} \right \rangle \right|}{\left|I_u^{m+2k} \right|^{\frac{1}{2}}} \one_{I_u^{m+2k}}(x)dx \nonumber \\
& \lesssim  \frac{2^\beta |F_1|}{|F_3|} \cdot \int_{\R} \calS f_2(x) \calS_{\calI_\beta, p(\cdot)}^{\max} f_3(x) dx, 
\end{align}
where 
$$
\calS_{\calI_\beta, p(\cdot)}^{\max} f_3(x):=\left( \sum_{k \ge 2m} \sum_{\substack{I_u^{m+2k} \subseteq I_r^{m+k} \\ I_r^{m+k} \subseteq I_{\widetilde{r}}^k \\ I_{\widetilde{r}}^k \in \calI_\beta}} \frac{ \left| \left \langle f_3, \Phi_{P_{m+2k}\left(u-p \left(I_r^{m+k} \right)\right)} \right \rangle \right|^2}{\left|I_u^{m+2k} \right|}  \one_{I_u^{m+2k}}(x) \right)^{\frac{1}{2}}.
$$
is the \emph{maximal $m$-shifted square function} relative to the pair $(\calI_\beta, p(\cdot))$. By \cite[(4.166)]{GL25}, 
\begin{equation} \label{20250626eq04}
\left\| \calS_{\calI_\beta, p(\cdot)}^{\max} f_3 \right\|_{L^p(\R)} \lesssim_n m2^{-n\beta} |F_3|^{\frac{1}{p}} 
\end{equation} 
for any $n \in \N$ and $1 < p<+\infty$. Putting \eqref{20250626eq02} -- \eqref{20250626eq04} together, we deduce that for any $\mu \in (0, 1)$,  
$$
\left|\Lambda_m^{\ge}(f_1, f_2, f_3) \right | \lesssim m|F_1||F_2|^\mu |F_3|^{-\mu}, 
$$
which concludes the desired restricted weak-type estimate in this case. 

\subsubsection{The case $ m \ge 2k$ ($k$ fixed): a multi-scale argument}\label{20250430sec01}  In this situation we provide restricted weak-type estimates for the term
$$
\Lambda_{\ge}^k(f_1, f_2, f_3):=\sum_{m \ge 2k} \Lambda_m^k(f_1, f_2, f_3)\,,
$$
by allowing (again) the implicit bounds to depend polynomially on $k$. Since we want to make use of this argumentation for the treatment of the stationary off-diagonal component we employ a three-case treatment depending on the spatial and frequency localization of each of the input functions.

We start by stating the form of the expression that is of interest for us
\begin{equation} \label{20250415eq01}
\Lambda_{\ge}^k (f_1, f_2, f_3)= \sum_{m \ge 2k} \int_{\R^2} \left(f_1*\check{\phi}_{m+k} \right) \left(x-\frac{t}{2^k}\right)\left(f_2*\check{\phi}_{m+2k}\right)\left(x+\frac{t^2}{2^{2k}}\right) f_3(x) e^{i\lambda(x)\frac{t^3}{2^{3k}}} \rho(t) \phi \left(\frac{\lambda(x)}{2^{m+3k}} \right) dtdx.
\end{equation}

\noindent \underline{{\textsf A. Treatment of $\Lambda_{\ge}^k(f_1, f_2, f_3)$ involving only the spatial information of $f_1$ and $f_3$.}}

\vspace{0.2cm}

 By Cauchy-Schwarz, we estimate \eqref{20250415eq01} by 
\begin{align*}
\left|\Lambda_{\ge}^k(f_1, f_2, f_3) \right| 
& \lesssim  \int_{\R} \int_{\R} M f_1 \left(x-\frac{t}{2^k} \right) \calS f_2 \left(x+\frac{t^2}{2^{2k}} \right) |f_3(x)| \left( \sum_{m \ge 2k} \phi^2 \left(\frac{\lambda(x)}{2^{m+3k}} \right) \right)^{\frac{1}{2}} |\rho(t)| dtdx \\
& \lesssim \int_{\R} \left(\int_{\R} Mf_1 \left(x-\frac{t}{2^k} \right) \calS f_2 \left(x+\frac{t^2}{2^{2k}} \right) |\rho(t)| dt \right) |f_3(x)| dx \\
& \lesssim \int_{\R} \calM_{\calC} \left(Mf_1, \calS f_2 \right)(x) |f_3(x)|dx.
\end{align*}
It now suffices to follow the same argument from Section \ref{20250415subsec01} in order to deduce that for any $\theta>0$
\begin{equation} \label{20250430eq01}
\left| \Lambda_{\ge}^k(f_1, f_2, f_3) \right | \lesssim |F_1|^{\frac{1}{1+2\theta}}|F_2|^{\frac{1}{1+2\theta}}|F_3|^{\frac{2\theta-1}{2\theta+1}}. 
\end{equation} 


\vspace{0.2cm}

\noindent \underline{\textsf{B. Treatment of $\Lambda_{\ge}^k(f_1, f_2, f_3)$ involving only the spatial information of $f_2$ and $f_3$.}}

\vspace{0.2cm}

The proof of this case follows from a straightforward modification of the previous case, by interchanging the role of $f_1$ and $f_2$. This yields
$$
\left| \Lambda_{\ge}^k(f_1, f_2, f_3) \right| \lesssim \int_{\R} \calM_{\calC}(\calS f_1, Mf_2)(x) |f_3(x)|dx, 
$$
which further gives the same restricted weak-type estimate \eqref{20250430eq01}. 

\vspace{0.2cm}

\noindent  \underline{\textsf{C. Treatment of $\Lambda_{\ge}^k(f_1, f_2, f_3)$ involving only the spatial information of $f_3$.}}

\vspace{0.2cm}
In this case, we apply Cauchy-Schwarz in \eqref{20250415eq01} to the terms involving $f_1$ and $f_2$ to deduce that 
\begin{align*}
\left| \Lambda_{\ge}^k (f_1, f_2, f_3) \right| %
& \lesssim \int_{\R} \int_{\R} \calS f_1 \left(x-\frac{t}{2^k} \right) \calS f_2 \left(x+\frac{t^2}{2^{2k}} \right) |f_3(x)| |\rho(t)| dtdx \\
& \lesssim \int_{\R} \left(\int_{\R} \calS f_1 \left(x-\frac{t}{2^k} \right) \calS f_2 \left(x+\frac{t^2}{2^{2k}} \right) |\rho(t)| dt \right) |f_3(x)| dx \\
& \lesssim \int_{\R} \calM_{\calC} (\calS f_1, \calS f_2)(x) |f_3(x)| dx. 
\end{align*}
The rest of the argument is similar to the previous cases, so we omit further details here. 




\subsection{Treatment of the stationary off-diagonal component $BHC^{\not\Delta, S}$: Tame bounds}\label{20250309sec02}


In this second (sub)section, we provide slowly growing restricted weak-type bounds for the sub-components of $BHC^{\not\Delta, S}$ by properly adapting the approach described in the previous section.

We start by recalling the discretization used in Section \ref{20250308sec01} which reduces the analysis of the stationary off-diagonal component to two main cases: 
\begin{enumerate}
    \item [({\bf O1})] $j \cong l, k \ge 0$ and $0 \le m \le \frac{j}{2}$;
    \item [({\bf O2})] all other remaining stationary off-diagonal cases. 
\end{enumerate}

\vspace{0.1cm}

Assume now that $f_1, f_2$, and $f_3$ obey the standard restricted-weak type assumptions---see the introductory paragraph in Section \ref{20250308sec10}. For the case ({\bf O1}), it is not hard to see that the arguments in Sections \ref {20250415subsec01} and \ref{20250415subsec02} still apply, and hence we have
\begin{enumerate}
    \item [$\bullet$] \textsf{multi-scale estimate---summation in $k$:}
    \begin{equation} \label{20250310eq00}
    \sum_{k \ge 2j} \left| \Lambda_{j, l, m, \lambda(\cdot)}^k (f_1, f_2, f_3) \right| \lesssim (j+1) |F_1||F_2|^{\mu}|F_3|^{-\mu}  \quad \textnormal{for any} \ \mu \in (0, 1);
    \end{equation}
\item [$\bullet$] \textsf{single-scale estimate} for any $k \ge 0$ and $j, l, m$ satisfying assumption ({\bf O1}), we have
\begin{equation} \label{20250310eq01}
\left|\Lambda_{j, l, m, \lambda(\cdot)}^k (f_1, f_2, f_3) \right| \lesssim |F_1|^{\frac{1}{1+2\theta}}|F_2|^{\frac{1}{1+2\theta}}|F_3|^{\frac{2\theta-1}{2\theta+1}},  \quad \textnormal{for any} \ \theta>0,
\end{equation}
\end{enumerate}
where $\Lambda_{j, j, m, \lambda(\cdot)}^k (f_1, f_2, f_3)$ is the \emph{dual form} corresponding to the case ({\bf O1}) (see \emph{e.g.} \eqref{20250308eq03}).  

\vspace{0.1cm}

Next, for the case ({\bf O2}), it is sufficient to prove the desired restricted weak-type estimate for the term\footnote{Here, we may slightly relax the assumption of $\lambda$ in Theorem \ref{generalizedmain} by allowing $\lambda(x) \in \left[2^{\frac{m}{2}+3k}, 2^{m+3k} \right]$.} $\widetilde{\Lambda}_m^k(f_1, f_2, f_3)$ defined as in Theorem \ref{generalizedmain}. More precisely, we have
\begin{enumerate}
    \item [$\bullet$] \textsf{multi-scale estimate---summation in $k$}:
    \begin{equation} \label{20250310eq02}
    \left| \sum_{k \ge 2m} \widetilde{\Lambda}_m^k(f_1, f_2, f_3)\right| \lesssim (m+1)^3 |F_1||F_2|^{\mu}|F_3|^{-\mu}  \quad \textnormal{for any} \ \mu \in (0, 1); 
    \end{equation} 
    \item [$\bullet$] \textsf{multi-scale estimate---summation in $m$}:
    \begin{equation} \label{20250415eq40}
    \left| \sum_{m \ge 2k} \widetilde{\Lambda}_m^k(f_1, f_2, f_3)\right| \lesssim (|k|+1)^3 |F_1|^{\frac{1}{1+2\theta}}|F_2|^{\frac{1}{1+2\theta}}|F_3|^{\frac{2\theta-1}{2\theta+1}}, \quad \textnormal{for any} \ \theta>0, 
    \end{equation}
    \item [$\bullet$] \textsf{single scale estimate}: for any $m, k \ge 0$, one has
    \begin{equation} \label{20250310eq03}
    \left| \widetilde{\Lambda}_m^k(f_1, f_2, f_3) \right| \lesssim |F_1|^{\frac{1}{1+2\theta}}|F_2|^{\frac{1}{1+2\theta}}|F_3|^{\frac{2\theta-1}{2\theta+1}}, \quad \textnormal{for any} \ \theta>0. 
    \end{equation} 
\end{enumerate}

\noindent \textit{Sketch of the proof.} We first note that the argument in Section \ref{20250415subsec01} works for both single-scale estimates \eqref{20250310eq01} and \eqref{20250310eq03}. For the estimate \eqref{20250310eq00}, it is enough to observe that the argument in Section \ref{20250415subsec02} still applies if we switch the roles of $j$ and $m$. So, it remains to handle the two multi-scale estimates in case ({\bf O2}).

For the estimate \eqref{20250310eq02}, recall that $m$ is fixed and the sum is taken over all $k \ge 2m$. We consider two sub-cases: \begin{enumerate} \item[\textit{(a-1)}.] $\supp \ \widehat{f_1} \subseteq [2^k, 2^{m+k+1}]$ and $\supp \ \widehat{f_2} \subseteq [2^{m+2k}, 2^{m+2k+1}]$; \item[\textit{(a-2)}.] $\supp \ \widehat{f_1} \subseteq [2^{m+k}, 2^{m+k+1}]$ and $\supp \ \widehat{f_2} \subseteq [2^{2k}, 2^{m+2k+1}]$. \end{enumerate} In both of these sub-cases, the argument from Section \ref{20250415subsec02} still works. More precisely, in case \textit{(a-1)}, the only change to make is to observe that the input function $f_1$ is supported on about $m$ dyadic frequency intervals, and hence in the case the magnitude of the constant in \eqref{20250310eq02} is $ \lesssim (m+1)^2$. Next, in the case \textit{(a-2)}, since $k \ge 2m$, we observe that $\supp \ \widehat{f_2} \subseteq [2^{2k}, 2^{m+2k+1}]$, and hence both $f_2$ and $f_3$ are supported on about $m$ dyadic frequency intervals, and hence the magnitude of the constant of $ \lesssim (m+1)^3$. 

Next, for the estimate \eqref{20250415eq40}, note that $k$ is fixed and the sum is taken over $m \ge 2k$. Let us break the analysis into four sub-cases: \begin{enumerate} \item[\textit{(b-1)}.] $\supp \ \widehat{f_1} \subseteq [2^k, 2^{-100} \cdot 2^{m+k}]$ and $\supp \ \widehat{f_2} \subseteq [2^{m+2k}, 2^{m+2k+1}]$; \item[\textit{(b-2)}.] $\supp \ \widehat{f_1} \subseteq [2^{m+k}, 2^{m+k+1}]$ and $\supp \ \widehat{f_2} \subseteq [2^{2k}, 2^{-100} \cdot 2^{m+2k}]$; \item[\textit{(b-3)}.] $\supp \ \widehat{f_1} \subseteq [2^{-100} \cdot 2^{m+k}, 2^{m+k+1}]$ and $\supp \ \widehat{f_2} \subseteq [2^{m+2k}, 2^{m+2k+1}]$; \item[\textit{(b-4)}.] $\supp \ \widehat{f_1} \subseteq [2^{m+k}, 2^{m+k+1}]$ and $\supp \ \widehat{f_2} \subseteq [2^{-100} \cdot 2^{m+2k}, 2^{m+2k+1}]$. \end{enumerate}

In case \textit{(b-1)}, the assumption ({\bf O2}) allows us to assume that $\textnormal{range}(\lambda) \subseteq [2^{m+3k}, 2^{m+3k}]$, so the argument from Case \textsf{A} in Section \ref{20250430sec01} applies. For case \textit{(b-2)}, the reasoning in Case \textsf{B} from Section \ref{20250430sec01} is valid. Finally, in cases \textit{(b-3)} and \textit{(b-4)}, we can use the argument from Case \textsf{C} in the same section. \hfill $\square$



\subsection{Putting together all the estimates: A unified treatment of $BHC^{\Delta}$ and $BHC^{\not\Delta, S}$} 


In this section, our goal is to prove the full desired quasi-Banach range for both $BHC^{\Delta}$ and $BHC^{\not\Delta, S}$. These bounds will follow from an interpolation argument between the $L^2$ estimates established in Theorem \ref{generalizedmain} and the restricted weak-type estimates proved in Sections
\ref{20250308sec10} and \ref{20250309sec02}.


\subsubsection{Preliminaries} With these settled, we start by noticing that based on the above and with the previous notations the dual forms that correspond to the two major cases to treat are given by 
$$
\Lambda_{\textnormal{(\bf O-1})}(f_1, f_2, f_3):=\left \langle BHC_{\lambda(\cdot)}^{\textnormal{({\bf O1})}}(f_1, f_2), f_3 \right \rangle:=\sum_{j, k \ge 0} \sum_{\substack{l \cong j \\ 0 \le m \le \frac{j}{2}}} \Lambda_{j, l, m, \lambda(\cdot)}^k(f_1, f_2, f_3),
$$
where $\Lambda_{j, l, m, \lambda(\cdot)}^k(f_1, f_2, f_3)$ is a single piece of the dual form with $j, l, m$ and $k$ fixed (see \eqref{20250308eq03}) and
$$
\Lambda_{\textnormal{(\bf O-2})}(f_1, f_2, f_3):=\left \langle BHC_{\lambda(\cdot)}^{\textnormal{({\bf O2})}}(f_1, f_2), f_3 \right \rangle :=\sum_{m, k \ge 0}  \widetilde{\Lambda}_m^k(f_1, f_2, f_3),
$$
where $ \widetilde{\Lambda}_m^k(f_1, f_2, f_3)$ is a single piece of the ``extended" diagonal component  defined in Theorem \ref{generalizedmain}. 

Our final \emph{goal} is to establish the full quasi-Banach range bounds for both these forms. In order to do so, we first collect all the key estimates we have already obtained: 
\begin{enumerate}
    \item [(1)] {\bf $L^2$-estimates}: there exists some absolute $\epsilon>0$ sufficiently small, such that for any $(p_1, p_2, p_3)=(2, \infty, 2), (\infty, 2, 2)$, and $(2, 2, \infty)$, one has
    \begin{enumerate}
        \item [(a)] under assumption ({\bf O1})---see \eqref{20250210eq01}:
        $$
        \left|\Lambda_{j, l, m, \lambda(\cdot)}^k(f_1, f_2, f_3) \right| \lesssim 2^{-\epsilon j} \prod_{i=1}^3 \left\|f_i \right\|_{L^{p_j} \left(3I^k \right)}\,;
        $$

        \item [(b)] under assumption ({\bf O2})---see Theorem \ref{generalizedmain}: 
        \begin{equation} \label{20250312eq01}
        \left| \widetilde{\Lambda}_m^k(f_1, f_2, f_3) \right| \lesssim 2^{-\epsilon \min\{2k, m\}} \prod_{i=1}^3 \left\|f_i \right\|_{L^{p_j} \left(3I^k \right)}\,;
        \end{equation} 

    \end{enumerate}
    \item [(2)] {\bf Restricted weak-type estimates}: for $F_1, F_2$, and $F_3$ measurable sets with finite (non-zero) Lebesgue measure, there exists some 
    $$
    F_3' \subseteq F_3 \quad \textnormal{measurable with} \quad |F_3'| \ge \frac{|F_3|}{2}\,,
    $$
    such that for any functions $f_1, f_2$, and $f_3$ obeying
    \begin{equation} \label{20250314eq01}
    |f_1| \le \one_{F_1}, \quad |f_2| \le \one_{F_2}, \quad \textrm{and} \quad |f_3| \le \one_{F_3'}, 
    \end{equation} 
    one has 
    \begin{enumerate}
        \item [(c)] under assumption ({\bf O1})

            \noindent $\bullet$ \textsf{multi-scale estimate---summation in $k$}, see \eqref{20250310eq00}): 
            \begin{equation} \label{summary001}
            \sum_{k \ge 2j} \left| \Lambda_{j, l, m, \lambda(\cdot)}^k(f_1, f_2, f_3) \right| \lesssim (j+1)^2|F_1||F_2|^{\mu}|F_3|^{-\mu}\, \quad \textrm{for any} \ \mu \in(0,1 )\, ; 
            \end{equation}


            \noindent $\bullet$ \textsf{single-scale estimate}---for any $k \ge 0$, see \eqref{20250310eq01}:
              \begin{equation} \label{summary002}
        \left| \Lambda_{j, l, m, \lambda(\cdot)}^k(f_1, f_2, f_3) \right| \lesssim |F_1|^{\frac{1}{1+2\theta}}|F_2|^{\frac{1}{1+2\theta}}|F_3|^{\frac{2\theta-1}{2\theta+1}},  \quad \textnormal{for any} \ \theta>0\,;
        \end{equation}

       \item [(d)] under assumption ({\bf O2}): 

         \noindent $\bullet$ \textsf{multi-scale estimate---summation in $k$},  see \eqref{20250310eq02}:
            \begin{equation} \label{summary003}
           \sum_{k \ge 2m}  \left| \widetilde{\Lambda}_m^k(f_1, f_2, f_3) \right| \lesssim (m+1)^3|F_1||F_2|^{\mu}|F_3|^{-\mu}\, \quad \textrm{for any} \ \mu \in (0, 1);
            \end{equation} 


             \noindent $\bullet$ \textsf{multi-scale estimate---summation in $m$}, see \eqref{20250415eq40}:
            \begin{equation} \label{summary004}
             \sum_{m \ge 2k} \left|\widetilde{\Lambda}_m^k(f_1, f_2, f_3) \right| \lesssim (|k|+1)^3 |F_1|^{\frac{1}{1+2\theta}}|F_2|^{\frac{1}{1+2\theta}}|F_3|^{\frac{2\theta-1}{2\theta+1}},  \qquad \textnormal{for any} \ \theta>0\,; 
            \end{equation}

             \noindent $\bullet$ \textsf{single-scale estimate}---for any $k \ge 0$, see \eqref{20250310eq03}:
            \begin{equation} \label{summary005}
            \left|  \widetilde{\Lambda}_m^k(f_1, f_2, f_3) \right|   \lesssim |F_1|^{\frac{1}{1+2\theta}}|F_2|^{\frac{1}{1+2\theta}}|F_3|^{\frac{2\theta-1}{2\theta+1}},  \quad \textnormal{for any} \ \theta>0\,.
            \end{equation}
           \end{enumerate}
\end{enumerate}



\subsubsection{A refinement of \eqref{20250312eq01}} In this brief section we solve the following issue: estimate \eqref{20250312eq01} is \emph{not} sufficient for summing in both the $k$ and $m$ parameters. The main reason is that Theorem \ref{generalizedmain}, as stated, lacks frequency localization in $f_3$. This inconvenience is addressed in the following refinement of Theorem \ref{generalizedmain}:

\begin{thm} \label{refinedrefined}
For any $k, m \in \N$, let
$$
BHC_{m, \lambda, \textnormal{ref}}^k(f_1, f_2)(x):=\sup_{\lambda \in \left[2^{\frac{m}{2}+\kappa m+3k}, 2^{m+3k} \right]} \left|  \int_{\R} f_1(x-t)f_2(x+t^2)e^{i\lambda t^3} 2^k \rho(2^k t) dt \right|
$$
where $\kappa>0$ is the same constant that we picked in Theorem \ref{generalizedmain}, and further denote its dual form by
$$
\widetilde{\Lambda}_{m, \lambda, \textnormal{ref}}^k(f_1, f_2, f_3):= \left\langle BHC_{m, \lambda, \textnormal{ref}}^k(f_1, f_2), f_3 \right \rangle. 
$$
Assume one of the following situations holds:
    \begin{enumerate}
        \item [(1)] $\supp \ \widehat{f_1} \subseteq \left[2^k, 2^{m+k+1} \right]$ and $\supp \ \widehat{f_2} \subseteq \left[2^{m+2k}, 2^{m+2k+1} \right]$;
        \item [(2)] or $\supp \ \widehat{f_1} \subseteq \left[2^{m+k}, 2^{m+k+1} \right]$ and $\supp \ \widehat{f_2} \subseteq \left[2^{2k}, 2^{m+2k+1} \right]$.
    \end{enumerate}
Moreover, if either $\widehat{f_1}$ is supported away from $[2^{m+k-3}, 2^{m+k+1}]$ or $\widehat{f_2}$ is supported away from $[2^{m+2k-3}, 2^{m+2k+1}]$ then one may further assume that the linearizing supremum phase function obeys $\lambda (x) \in [2^{m+3k}, 2^{m+3k+1}]$.  


Under the above assumptions, the following hold:
\begin{enumerate}
\item [(a)] assuming $m \le k+20$, then
\begin{enumerate}
   \item [(a-1)] if $\supp \ \widehat{f_1} \subseteq 
[2^k, 2^{m+k+1} ]$ and $\supp \ \widehat{f_2} \subseteq [2^{m+2k}, 2^{m+2k+1}]$ then one may assume the frequency localization $\supp \ \widehat{f_3} \subseteq [2^{m+2k}, 2^{m+2k+1}]$;
\item [(a-2)] if $\supp \ \widehat{f_1} \subseteq [2^{m+k}, 2^{m+k+1}]$ and $\supp \ \widehat{f_2} \subseteq \left[2^{2k}, 2^{m+2k+1} \right]$ then one may assume the frequency localization $\supp \ \widehat{f_3} \subseteq [0, 2^{m+2k+1}]$;
\end{enumerate}
\item [(b)] assuming $m \ge k+20$, then  
\begin{enumerate}
    \item [(b-1)] if $\supp \ \widehat{f_1} \subseteq 
[2^k, 2^{m+k+1} ]$ and $\supp \ \widehat{f_2} \subseteq [2^{m+2k}, 2^{m+2k+1}]$ then one may assume the frequency localization $\supp \ \widehat{f_3} \subseteq [2^{m+2k}, 2^{m+2k+1}]$;
\item [(b-2)] if $\supp \ \widehat{f_1} \subseteq [2^{m+k}, 2^{m+k+1}]$ and $\supp \ \widehat{f_2} \subseteq \left[2^{2k}, 2^{m+k-10} \right]$ then one may assume the frequency localization $\supp \ \widehat{f_3} \subseteq [2^{m+k-1}, 2^{m+k+1}]$;
\item [(b-3)] if $\supp \ \widehat{f_1} \subseteq [2^{m+k}, 2^{m+k+1}]$ and $\supp \ \widehat{f_2} \subseteq [2^{m+k-10}, 2^{m+2k+1}]$ then one may assume the frequency localization\footnote{The frequency localization of $f_3$ will \emph{not} be relevant here, as we will prove the $L^2$ estimates for $(p_1, p_2, p_3)=(2, 2, \infty)$ in this case.} $\supp \ \widehat{f_3} \subseteq [0, 2^{m+2k+1}]$. 
\end{enumerate}
\end{enumerate}
Moreover, \eqref{20250312eq01} remains valid for $\widetilde{\Lambda}_{m, \lambda, \textnormal{ref}}^k(f_1, f_2, f_3)$ in all the above cases. 
\end{thm}


\begin{proof}
The fact that \eqref{20250312eq01} holds in all of the aforementioned cases follows from a careful inspection of the proof of Theorem \ref{generalizedmain}. Regarding the claims on the frequency localization of $f_3$ we notice that these can be verified using a standard Rank-I LGC argument as outlined in Section \ref{20250228sec03}. We leave the further details to the interested reader.
\end{proof}


\subsubsection{$L^r$ estimates for $\Lambda_{\textnormal{(\bf O-1})}$ and $\Lambda_{\textnormal{(\bf O-2)}}$ within the quasi-Banach range}

In the first part of this section we address the Hilbert case, \emph{i.e.}, we establish $L^p$ bounds for $\Lambda_{\textnormal{(\bf O-1)}}(f_1, f_2, f_3)$ and $\Lambda_{\textnormal{(\bf O-2)}}(f_1, f_2, f_3)$ when $(p_1, p_2, p_3)$ is restricted to the triples $(2, \infty, 2), (\infty, 2, 2)$, and $(2, 2, \infty)$. 

First, for case ({\bf O1}), it suffices to consider 
$$
\Lambda_{\textnormal{(\bf O-1)}}(f_1, f_2, f_3) \simeq \sum_{j\geq 0} \Lambda_{\textnormal{(\bf O-1)}}^{j}(f_1, f_2, f_3):=\sum_{j\geq 0} \sum_{k\ge 0} \sum_{0 \le m \le \frac{j}{2}} \Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3), 
$$
and then, using \eqref{20250210eq01} and Cauchy-Schwarz, we have 
\begin{align} \label{20250415eq50}
\left| \Lambda_{\textnormal{(\bf O-1)}}^{j}(f_1, f_2, f_3) \right| 
& \le\sum_{0 \le m \le \frac{j}{2}} \left| \sum_{k \ge 0} \Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3) \right| \lesssim j\,2^{-\epsilon j} \prod_{i=1}^3 \left\|f_i \right\|_{L^{p_i}(\R)}, 
\end{align}
where $(p_1, p_2, p_3)=(2, 2, \infty), (2, \infty, 2)$, and $(\infty, 2, 2)$. 

Next, for case ({\bf O2}), guided by the refined Theorem \ref{refinedrefined}, we write
\begin{align} \label{20250503eq43}
\Lambda_{\textnormal{(\bf O-2)}}(f_1, f_2, f_3) 
& = \Lambda_{\textnormal{(\bf O-2-a-1)}}(f_1, f_2, f_3)+\Lambda_{\textnormal{(\bf O-2-a-2)}}(f_1, f_2, f_3)+\Lambda_{\textnormal{(\bf O-2-b-1)}}(f_1, f_2, f_3) \nonumber  \\
& \quad +\Lambda_{\textnormal{(\bf O-2-b-2)}}(f_1, f_2, f_3)+\Lambda_{\textnormal{(\bf O-2-b-3)}}(f_1, f_2, f_3),
\end{align}
where
$$
\Lambda_{\textnormal{(\bf O-2-a-1)}}(f_1, f_2, f_3):=\sum_{m \ge 0} \Lambda^{m}_{\textnormal{(\bf O-2-a-1)}}(f_1, f_2, f_3):= \sum_{m \ge 0} 
\sum_{k \ge m-20} \widetilde{\Lambda}_{m, \lambda, \textnormal{ref}}^k \left( f_1^{[2^k, 2^{m+k+1}]}, f_2^{[2^{m+2k}, 2^{m+2k+1}]}, f_3 \right),
$$
$$
\Lambda_{\textnormal{(\bf O-2-a-2)}}(f_1, f_2, f_3):=\sum_{m \ge 0} \Lambda^{m}_{\textnormal{(\bf O-2-a-2)}}(f_1, f_2, f_3):=\sum_{m\geq 0}\sum_{k \ge m-20} \widetilde{\Lambda}_{m, \lambda, \textnormal{ref}}^k \left( f_1^{[2^{m+k}, 2^{m+k+1}]}, f_2^{[2^{2k}, 2^{m+2k-10}]}, f_3 \right),
$$
$$
    \Lambda_{\textnormal{(\bf O-2-b-1)}}(f_1, f_2, f_3):=\sum_{k \ge 0}  \Lambda_{\textnormal{(\bf O-2-b-1)}}^{k}(f_1, f_2, f_3):=\sum_{k\geq 0}\sum_{m \ge k+20} \widetilde{\Lambda}_{m, \lambda, \textnormal{ref}}^k \left( f_1^{[2^k, 2^{m+k+1}]}, f_2^{[2^{m+2k}, 2^{m+2k+1}]}, f_3 \right),
    $$
$$
    \Lambda_{\textnormal{(\bf O-2-b-2)}}(f_1, f_2, f_3):=\sum_{k \ge 0}  \Lambda_{\textnormal{(\bf O-2-b-2)}}^{k}(f_1, f_2, f_3):=\sum_{k\geq 0}\sum_{m \ge k+20} \widetilde{\Lambda}_{m, \lambda, \textnormal{ref}}^k \left( f_1^{[2^{m+k}, 2^{m+k+1}]}, f_2^{[2^{2k}, 2^{m+k-10}]}, f_3 \right),
    $$
and
$$
\Lambda_{\textnormal{(\bf O-2-b-3)}}(f_1, f_2, f_3):=\sum_{k \ge 0}\Lambda_{\textnormal{(\bf O-2-b-3)}}^{k}(f_1, f_2, f_3):=\sum_{k\geq 0} \sum_{m \ge k+20} \widetilde{\Lambda}_{m, \lambda, \textnormal{ref}}^k \left( f_1^{[2^{m+k}, 2^{m+k+1}]}, f_2^{[2^{m+k-10}, 2^{m+2k+1}]}, f_3 \right).
$$
Here, we recall that $f^{I}$ refers to the Fourier projection of $f$ on the frequency interval $I$. 

For the case ({\bf O-2-a-1}), we have
\begin{equation*}
\left| \Lambda^{m}_{\textnormal{(\bf O-2-a-1)}}(f_1, f_2, f_3)\right| 
\lesssim \sum_{k \ge m-20} \left| \widetilde{\Lambda}_{m, \lambda, \textnormal{ref}}^k \left( f_1^{[2^k, 2^{m+k+1}]}, f_2^{[2^{m+2k}, 2^{m+2k+1}]}, f_3 \right) \right| \lesssim  2^{-\epsilon m}\,\prod_{i=1}^3 \left\|f_i \right\|_{L^{p_i}(\R)}\,,  
\end{equation*} 
where $(p_1, p_2, p_3)=(2, 2, \infty), (2, \infty, 2)$, and $(\infty, 2, 2)$. Note that the same argument applied to the term $\Lambda^{m}_{\textnormal{(\bf O-2-a-2)}}(f_1, f_2, f_3)$, yields the same smoothing estimate. Next, for $\Lambda_{\textnormal{(\bf O-2-b-1)}}^{k}(f_1, f_2, f_3)$, from case (b-1) in Theorem \ref{refinedrefined}, we have 
\begin{align} \label{20250415eq34}
& \left| \Lambda_{\textnormal{(\bf O-2-b-1)}}^{k}(f_1, f_2, f_3) \right|  \le  \sum_{m \ge k+20} \left| \widetilde{\Lambda}_{m, \lambda, \textnormal{ref}}^k \left( f_1^{[2^k, 2^{m+k+1}]}, f_2^{[2^{m+2k}, 2^{m+2k+1}]}, f_3 \right) \right| \nonumber \\
& \lesssim 2^{-2 \epsilon k}  \left(\sum_{m>k+20} \left\|f_1^{[2^k, 2^{m+k+1}]} \right\|_{L^\infty(\R)} \left\|f_2^{[2^{m+2k}, 2^{m+2k+1}]} \right\|_{L^2(\R)} \left\|f^{[2^{m+2k}, 2^{m+2k+1}]}_3 \right\|_{L^2(\R)} \right)  \nonumber \\
& \lesssim  2^{-2\epsilon k} \left\|f_1 \right\|_{L^\infty} \left\|f_2 \right\|_{L^2(\R)} \left\|f_3 \right\|_{L^2(\R)}\,.
\end{align}
Note that in this case, the $L^2$ estimate is \emph{only} valid for $(p_1, p_2, p_3)=(\infty, 2, 2)$. Finally, for the terms $\Lambda_{\textnormal{(\bf O-2-b-2)}}^{k}(f_1, f_2, f_3)$ and $\Lambda_{\textnormal{(\bf O-2-b-3)}}^{k}(f_1, f_2, f_3)$, one can apply a similar argument as in \eqref{20250415eq34}, now utilizing the frequency localizations specified in cases (b-2) and (b-3), respectively, of Theorem~\ref{refinedrefined}.  The corresponding $L^p$ smoothing estimate indices in these cases are $(p_1, p_2, p_3)=(2, \infty, 2)$, and $(2, 2, \infty)$, respectively. 

These conclude the $L^2$-base decay estimates that now can be uses as a base-point for multilinear interpolation with the tamer bounds described below (the proof of the latter require only standard adaptations of the reasonings involved for proving \eqref{summary001}---\eqref{summary005}):

\begin{lem} \label{20250317lem01}
Let $f_1$, $f_2$, $f_3$ satisfy the assumptions \eqref{20250314eq01} with the major set $F_3'$ defined by \eqref{20250626eq10}. Then, for any 
$(p_1, p_2, p_3)$ satisfying $\frac{1}{p_1}+\frac{1}{p_2}=\frac{1}{p_3'}$ with $1 < p_1, p_2< +\infty$ and $\frac{1}{2}<p_3'<\infty$
the following estimates hold:
$$
 \sum_{k \ge 0}  \left|\Lambda_{j, j, m, \lambda(\cdot)}^k(f_1, f_2, f_3) \right| \lesssim (j+1)^2 \prod_{i=1}^3 \left\|f_i \right\|_{L^{p_i}(\R)}, \quad \sum_{k \ge 0}\left| \widetilde{\Lambda}_m^k(f_1, f_2, f_3) \right| \lesssim (m+1)^3 \prod_{i=1}^3 \left\|f_i \right\|_{L^{p_i}(\R)}, 
$$
and
$$
\sum_{m \ge 0} \left| \widetilde{\Lambda}_m^k(f_1, f_2, f_3) \right| \lesssim (|k|+1)^3 \prod_{i=1}^3 \left\|f_i \right\|_{L^{p_i}(\R)}.
$$
\end{lem}

Combining now the main $L^2$ decay estimates with Lemma \ref{20250317lem01} and using multi-linear interpolation, we conclude the desired (maximal) quasi Banach range estimates: 
$$
\left|\Lambda_{\textnormal{(\bf O-1})}(f_1, f_2, f_3) \right|, \; \left| \Lambda_{\textnormal{(\bf O-2})}(f_1, f_2, f_3) \right| \lesssim \prod_{i=1}^3 \left\|f_i \right\|_{L^{p_i}(\R)}\,
$$
for any triple $(p_1, p_2, p_3)$ satisfying the hypothesis in the statement of Lemma \ref{20250317lem01}.



\section{Appendix: Treatment of the case $k<0$: an outline}

In this section, we provide a brief outline for the treatment of the main diagonal term $BHC_{-}^{\Delta}$ representing, of course, the crux of the entire $k<0$ analysis and which further crucially relies on the Rank-II LGC methodology. To begin with, we recall that the operator we wish to understand is given by 
$$
 BHC_{-}^{\Delta}(f_1, f_2)\approx\sum_{k \in \Z_{-}} \sum_{m \in \N} \sup_{\lambda} \left|BHC_{m, \lambda}^k(f_1, f_2)(x) \right|,
$$
with
\begin{equation} \label{20241215eq10}
BHC_{m, \lambda}^k(f_1, f_2)(x) \approx 2^k \phi \left(\frac{\lambda}{2^{m+3k}} \right) \int_{\R} f_{1, m+k}(x-t) f_{2, m+2k}(x+t^2)e^{i\lambda t^3} \rho(2^k t) dt,
\end{equation} 
where $\phi$ is a smooth even function supported in $[-4, 4] \backslash \left[-\frac{1}{4}, \frac{1}{4} \right]$, and, wlog $\rho\in C_0^{\infty}(\R)$ with $\textrm{supp}\,\rho\subset[\frac{1}{10},10]$. 

In what follows, we focus entirely only on the key differences relative to the case $k \ge 0$:
\begin{enumerate}
    \item [$\bullet$] the dominant frequency regime corresponds to $f_1$, having the magnitude $2^{m+k}$;
    \item [$\bullet$] the dominant spatial interval in the $x$-variable becomes $I^{2k}:=I_0^{0, 2k}$ versus $I^k$ in the $k>0$ regime;
    \item [$\bullet$] the roles of $f_1$ and $f_2$ are interchanged. 
\end{enumerate}

With these being said, we first apply the change of variable $t^2 \to t$ in order to rewrite \eqref{20241215eq10} as
$$
BHC_{m, \lambda}^k(f_1, f_2)(x) \approx 2^{2k} \phi \left(\frac{\lambda}{2^{m+3k}} \right) \int_{\R} f_{2, m+2k}(x+t) f_{1, m+k}\left(x-t^{\frac{1}{2}} \right) e^{i\lambda t^{\frac{3}{2}}} \widetilde{\rho} \left(2^{2k} t \right)dt,
$$
where $\widetilde{\rho}(t):=\frac{t^{-1/2}}{2} \rho(t^{1/2})$. Observe that the above operator is concentrated locally on intervals of length $2^{-2k}$, and hence it suffices to consider 
$$
BHC_{m, \lambda}^{k, I^{2k}}(f_1, f_2)(x) \approx 2^{2k} \one_{I^{2k}}(x) \phi_2 \left(\frac{\lambda}{2^{m+3k}} \right) \int_{\R} f_{2, m+2k}(x+t) f_{1, m+k}\left(x-t^{\frac{1}{2}} \right) e^{i\lambda t^{\frac{3}{2}}} \widetilde{\rho} \left(2^{2k} t \right)dt.
$$
Let again $\lambda (\cdot): I^{2k} \to \left[2^{m+3k}, 2^{m+3k+1} \right]$ be a measurable function such that 
$$
\sup_{\lambda \in \R} \left| BHC_{m, \lambda}^{k, I^{2k}}(f_1, f_2)(x)\right| \le 2 \left|BHC_{m, \lambda(x)}^{k, I^{2k}}(f_1, f_2)(x) \right|.
$$
Next, by using Heisenberg's uncertainty principle, the analogue of {\bf Key Heuristic 1} becomes the following: 

\bigskip 

\noindent\textbf{Key Heuristic 1$^\prime$.}

\begin{center}
\texttt{$\lambda(\cdot)$ takes constant values on intervals of length $2^{-m-k}$ when $k<0$}. 
\end{center}

\bigskip 

It now becomes transparent that the natural analogue of Theorem \ref{20241018mainthm01} becomes:
\bigskip 

\begin{thm} \label{20241217thm01A}
Let $k \in \Z_{<0}$ and $m \in \N$. Let further, 
\begin{equation} \label{20241215eq02}
\underline{\Lambda}_m^k(f_1, f_2, f_3):=2^{2k} \int_{I^{2k}} \int_{I^{2k}} f_2(x+t)f_1(x-t^{\frac{1}{2}}) f_3(x) e^{i\lambda(x) t^{\frac{3}{2}}} \widetilde{\rho} \left(2^{2k} t \right) dt, 
\end{equation}
be the dual form of $BHC_{m, \lambda(\cdot)}^{k, I^{2k}}(f_1, f_2)$, where $\lambda(\cdot)$ takes constant value on intervals of length $2^{-m-k}$.

Then, there exists some $\underline{\epsilon}>0$, such that 
$$
\left |\underline{\Lambda}_m^k(f_1, f_2, f_3) \right| \lesssim 2^{-\underline{\epsilon} \min\{-2k, m\}} \prod_{j=1}^3 \left\|f_j \right\|_{L^{p_j}(3I^{2k})},
$$
where $(p_1, p_2, p_3)=(2, 2, \infty), (2, \infty, 2)$ or $(\infty, 2, 2)$. 
\end{thm}
\bigskip 

Below we only provide a sketch of the proof for the above statement and leave further details to the interested reader. 
\medskip 

Consider now the dual form of $BHC_{m, \lambda(x)}^{k, I^{2k}}(f_1, f_2)(x)$, that is, 
\begin{equation} \label{20241215eq02A}
\underline{\Lambda}_m^k(f_1, f_2, f_3):=2^{2k} \int_{I^{2k}} \int_{I^{2k}} f_2(x+t)f_1(x-t^{\frac{1}{2}}) f_3(x) e^{i\lambda(x) t^{\frac{3}{2}}} \widetilde{\rho} \left(2^{2k} t \right) dt, 
\end{equation}
 By Cauchy-Schwarz and a Taylor series argument, we see that 
\begin{equation} 
\left| \underline{\Lambda}_m^k(f_1, f_2, f_3) \right|^2 \lesssim 2^{2k} \left\|f_3 \right\|_{L^2(3I^{2k})}^2 \left[ \underline{\bf L}_{m, 2k}(f_1, f_2) \right]^2,  \label{20240429eq01A}
\end{equation} 
where 
\begin{equation} \label{20241216eq01A}
\left[ \underline{\bf L}_{m, 2k}(f_1, f_2) \right]^2:=2^{2k} \int_{I^{2k}}\left|\sum_{q \sim 2^{\frac{m}{2}}} \int_{I_q^{m, 2k}} f_2(x+t)f_1(x-t^{\frac{1}{2}})e^{\frac{3i \lambda(x)}{2} \cdot \frac{q^{\frac{1}{2}}}{2^{\frac{m}{4}+k}}t} dt \right|^2 dx. 
\end{equation} 
Following the strategy outlined in Section \ref{20241216subsec01}, one employs a sparse-uniform dichotomy procedure that reduces the analysis of \eqref{20241004eq01} to the following expression
\begin{eqnarray} \label{20241216eq02}
\left[\underline{\calL}_{m, 2k}(f_1, f_2) \right]^2%
&=& 2^{\frac{m}{2}+2k} \int_{I^{2k}} \sum_{q \sim 2^{\frac{m}{2}}} \left| \int_{I_q^{m, 2k}} f_2(x+t)f_1(x-t^{\frac{1}{2}})e^{\frac{3i \cdot 2^{\frac{m}{2}+2k}}{2} \cdot \left(\frac{q}{2^{\frac{m}{2}}}\right)^{\frac{1}{2}} \widetilde{\lambda}(x) t} dt \right|^2 dx
\end{eqnarray}
where both $f_1$ and $f_2$ in \eqref{20241216eq02} are uniform, in the sense that
$$
\left\|f_i \right\|_{L^\infty(3I^{2k})} \lesssim 2^{\frac{\mu \min\{m, 2|k|\}}{2}} \cdot 2^k \left\|f_i \right\|_{L^2(3I^{2k})}, \quad i\in\{1, 2\}, 
$$
for some $\mu>0$ sufficiently small and $\widetilde{\lambda}(x):=\frac{\lambda(x)}{2^{\frac{m}{2}+3k}}$. Note that $\widetilde{\lambda}(\cdot): I^{2k} \mapsto \left[2^{\frac{m}{2}}, 2^{\frac{m}{2}+1} \right]$ takes constant value on intervals of length $2^{-m-k}$. The analysis of \eqref{20241216eq02} is similar to the treatment of the term \eqref{20241004eq01}. More precisely, we again divide the proof into two parts:

\medskip 

 \noindent   \underline{\textsf{Part I: $k \le -\frac{m}{2}$.}} In this case, following the strategy presented in \cite[Theorem 4.3]{HL23}:  

\vspace{0.1cm}

\begin{enumerate}

\item [$\bullet$] If $k \le -m$, then the proof of the uniform component follows from the same argument in \cite[Theorem 11.1]{HL23}. 

\item [$\bullet$] If $-m \le k \le -\frac{m}{2}$, then the whole argument can be divided into two steps.

\noindent \underline{\textsf{Step I.1}:} we apply a bootstrap argument (see, \cite[Proposition 4.7]{HL23}) in order to extend the length of constancy of $\widetilde{\lambda}$ to the level $2^{-m-2k}$.

\vspace{0.1cm}

\noindent \underline{\textsf{Step I.2}:} once we reach the scale $2^{-m-2k}$, note that in this case $2^{-m-2k} \ge 2^{-\frac{m}{2}-k}$, and hence we apply another bootstrap argument to extend the length of constancy of $\widetilde{\lambda}$ to the level $2^{-\frac{m}{2}-2k}$, which matches the scale of $t$-intervals (that is, the maximal scale that $t^{\frac{1}{2}}$ behaves like a linearized function), and hence the argument in \cite[Proposition 4.9]{HL23} applies. 

\end{enumerate}

\vspace{0.1cm}

\noindent $\bullet$ \textit{Part II: $-\frac{m}{2} \le k \le 0$.} Again, this is the case that is not covered by \cite[Theorem 4.3]{HL23} and hence one has to apply a new idea in the spirit of the proof developed in Sections \ref{20241217subsec01} and \ref{20250228sec03}. 

\vspace{0.1cm}

\noindent \underline{\textsf{Step II.1}:} mirroring \underline{\textsf{Step I.1}} above, we need to apply a bootstrap argument in the spirit of Proposition \ref{20241018prop01} in otder to extend the length of constancy of $\widetilde{\lambda}$ to the level $2^{-m-2k}$.

\vspace{0.1cm}

\noindent \underline{\textsf{Step II.2}:} once we reach the scale $2^{-m-2k}$, instead of applying another bootstrap argument, we implement Rank-I LGC methodology to \eqref{20241215eq02}.  

\medskip 

We end our brief outlook with the following remark: in the case $-m \le k \le 0$ in order to fully make use of the hidden cancellation encoded in the curvature, one needs to subdivide the integral expression in $2^{m}$ many $x$-intervals of the length $2^{-m-2k}$ and then group together $2^{m+k}$ such consecutive intervals. More precisely, the bootstrap argument is applied to the operator
\begin{equation} 
\calV_{m, k}^{\widetilde{p}}(f_1, f_2):=2^{-k} \sum_{p \in \left[\widetilde{p} 2^{m+k}, (\widetilde{p}+1)2^{m+k} \right]} \left[ \frac{1}{2^m} \calV_{m, k}^p (f_1, f_2) \right] \label{20241217eq10A},
\end{equation} 
where here $\widetilde{p} \sim 2^{-k}$ and for each $p \sim 2^m$ one has
\begin{equation}
\calV_{m, k}^p (f_1, f_2):=2^{\frac{3m}{2}+2k} \sum_{q \sim 2^{\frac{m}{2}}} \int_{I_p^{0, m+2k}} \left| \int_{I_q^{m, 2k}} f_2(x+t)f_1(x-t^{\frac{1}{2}})e^{\frac{3i \cdot 2^{\frac{m}{2}+2k}}{2} \cdot \left(\frac{q}{2^{\frac{m}{2}}}\right)^{\frac{1}{2}} \widetilde{\lambda}(x) t} dt \right|^2 dx. \label{20241004eq21A}
\end{equation}

