\section{Results}
To obtain our result, we use versions of the lemmas from \cite{aczel1984} that are adapted to our setting. The proofs of the lemmas can be found in the appendix.

\vspace{0.3cm}

\nd\tb{Lemma 1.} If $\psi\colon [-\epsilon, \epsilon]^{[0,1]}=\{f\colon [0,1]\to[-\epsilon,\epsilon]\}\to\mb R$ is continuous with respect to the metric induced by the $L^2$ norm, and satisfying the Cauchy equation \[ \psi\left(f+g\right)=\psi\left(f\right)+\psi\left(g\right)\,\forall f,g,f+g\in[-\epsilon,\epsilon]^{[0,1]},\] then there exists a continuous continuation $\overline\psi\colon C(I)\to\mb R$ of $\psi$ (i.e. such that $\overline\psi\vert_{[-\epsilon,\epsilon]^{[0,1]}}=\psi$) satisfying the Cauchy equation on $C(I)$: \[\overline\psi\left(f+g\right)=\overline\psi\left(f\right)+\overline\psi\left(g\right)\,\forall f,g\in C(I).\]

\vspace{0.3cm}

\nd\tb{Lemma 2.} Fix $m\ge 3$, a family of continuous maps $\{\alpha_j\colon I^I\to I\}_{j=1}^m$ satisfies the following two conditions \begin{align*}&\forall f\in I^I, f=0\text{ for }\lambda\text{-a.e. }i\in I\implies\alpha_1(f)=\dots=\alpha_m(f)=0;\\&\forall f_1,\dots,f_m\in I^I, \sum\limits_{j=1}^mf_j=1\implies\sum\limits_{j=1}^m\alpha_j\left(f_j\right)=1\end{align*} iff there exists a probability measure $\mu$ on $I$ such that $\alpha_j(f)=\int_Ifd\mu$ for any $1\le j\le m$.

\vspace{0.3cm}

\nd\tb{Theorem 1.} Let $m\ge 3$. An FCAF $\alpha$ satisfies optimality, independence and zero unanimity iff it is a weighted arithmetic mean.

\vspace{0.3cm}

\nd The proof is similar to \cite{f2025} except for the part showing that the weight is the same for any individual in different types.

\vspace{0.3cm}

\nd\tl{Proof.} The if part is obvious. For the only if part, notice that by independence we can decompose $\alpha$ into a set \[\{\alpha_{x_j}\colon\mathcal C^I\vert_{x_j}\to\mathcal C\vert_{x_j}\}_{j=1}^m\] of $m$ maps, each of which restricted on a single object $x_j\in X$. By optimality and zero unanimity,  $\{\alpha_{x_j}\}$ satisfies the conditions of \tb{Lemma 2}, so applying the lemma, it follows that, for each $1\le t\le p$, there is a probability measure $\mu^t$ on $I$ such that \[\alpha_{x_j}\vert_t(c(x_j)_t)=\int_Ic_i(x_j)_t\mu^t(di).\] Now, it suffices to show that the measures $\mu^t$ are consistent between types $1\le t\le p$. Indeed, for any $1\le t\le p$, $\lambda$-measurable $J\subseteq I$, consider \[c_j^t\left(x_1\right)=\left(\underbrace{0,\dots, 0}_{t-1},1,0,\dots,0\right)\,\forall j\in J,\] and \[c_i^t\left(x_1\right)=\left(1,0,\dots,0\right)\,\forall i\in I\setminus J.\] Then, \begin{align*}\alpha (c^t)(x_1)&=\left(\int_{I\setminus J}c_i^t(x_1)_1\mu^1(di),\underbrace{0,\dots, 0}_{t-2},\int_Jc_j^t(x_1)_t\mu^t(dj),0,\dots,0\right)\\&=\left(\int_{I\setminus J}\mu^1(di),\underbrace{0,\dots, 0}_{t-2},\int_J\mu^t(dj),0,\dots,0\right),\end{align*} so \[1=\int_{I\setminus J}\mu^1(di)+\int_J\mu^t(dj).\] For any $1\le t'\le p$, comparing the last equation and the corresponding equation \[1=\int_{I\setminus J}\mu^1(di)+\int_J\mu^{t'}(dj),\] we obtain \[\int_J\mu^t(dj)=\int_J\mu^{t'}(dj).\] Since this equation is true for any $\lambda$-measurable set $J\subseteq I$, it follows that $\mu^t=\mu^{t'}$, establishing the consistency. 

\vspace{0.3cm}

\nd With the previous theorem, we can immediately obtain the following corollaries:

\vspace{0.3cm}

\nd\tb{Corollary 1.} Let $m\ge 3$. An FCAF $\alpha$ satisfies optimality, independence, zero unanimity and anonymity iff it is a arithmetic mean.

\vspace{0.3cm}

\nd\tb{Corollary 2.} Let $m\ge 3$, $\alpha$ be an FCAF. Then the following statements are equivalent:
\begin{itemize}
    \item $\alpha$ is a non-degenerate weighted arithmetic mean;
    \item $\alpha$ satisfies optimality, independence, zero unanimity and non-dictatorship;
    \item $\alpha$ satisfies optimality, independence, unanimity and non-dictatorship;
    \item $\alpha$ satisfies optimality, independence, coherence and non-dictatorship;
    \item $\alpha$ satisfies optimality, symmetry, zero unanimity and non-dictatorship;
    \item $\alpha$ satisfies optimality, symmetry, unanimity and non-dictatorship;
    \item $\alpha$ satisfies optimality, symmetry, coherence and non-dictatorship.
\end{itemize}

\appendix
\section{Proofs}
We mimic the proofs from \cite{aczel1984}.

\vspace{0.3cm}

\nd\tl{Proof of Lemma 1.} Note that for any $kf\in [-\epsilon,\epsilon]^{[0,1]}, k\in\mb Z$, we have \[\psi\left(kf\right)=k\psi\left(f\right),\] so, for any $g\in[-\epsilon,\epsilon]^{[0,1]}, k\in\mb Z$, we have \[\psi\left(g\right)=k\psi\left(\frac gk\right).\] Now, note that any $f\in C(I)$ is bounded, so there exists $k\in\mb Z$ such that $\frac fk\in[-\epsilon,\epsilon]^{[0,1]}$, define $\overline\psi\left(f\right)=k\psi\left(\frac fk\right)$. (From the above equality, this does not depend on the choice of $k$.) Substituting $k=1$ gives $\overline\psi\vert_{[-\epsilon,\epsilon]^{[0,1]}}=\psi$. Also, we have, for any $f,g\in C(I)$, \[\overline\psi\left(f+g\right)=k\psi\left(\frac{f+g}k\right)=k\left(\psi\left(\frac fk\right)+\psi\left(\frac gk\right)\right)=\overline\psi\left(f\right)+\overline\psi\left(g\right).\]

\vspace{0.3cm}

\nd\tl{Proof of Lemma 2.} The if part is obvious. For the only if part, define \[\tilde I=\left[-\frac1m,1-\frac1m\right],\, \tilde f_j=f_j-\frac1m,\, \tilde\alpha_j(\tilde f_j)=\alpha_j\left(\tilde f_j+\frac1m\right)=\alpha_j\left(f_j\right).\] Now we have \[\left(\tilde f_j\in\tilde I^I\,\forall j, \sum\limits_{j=1}^m\tilde f_j=0\right)\implies\sum\limits_{j=1}^m\tilde\alpha_j(\tilde f_j)=1.\] In particular, \[\sum\limits_{j=1}^m\tilde\alpha_j\left(0\right)=1.\] Define $\psi_j(\tilde f)=\tilde\alpha_j(\tilde f)-\tilde\alpha_j\left(0\right)$. Then \[\left(\tilde f_j\in\tilde I^I\,\forall j,\sum\limits_{j=1}^m\tilde f_j=0\right)\implies\sum\limits_{j=1}^m\psi_j(\tilde f_j)=0,\psi_j\left(0\right)=0\,\forall j.\] In particular, \[\left(\tilde f_j\in[-\epsilon,\epsilon]^I\,\forall j,\sum\limits_{j=1}^m\tilde f_j=0\right)\implies\sum\limits_{j=1}^m\psi_j(\tilde f_j)=0,\psi_j\left(0\right)=0\,\forall j.\] For any $1\le j<k\le m$, $g\in[-\epsilon,\epsilon]^I$, substituting $\tilde f_j=g, \tilde f_k=-g$ and $\tilde f_\ell=0$ for all $j\ne\ell\ne k$, we get \[\psi_j\left(g\right)+\psi_k\left(-g\right)=0.\] Thus, for any pairwise distinct $j$, $k$, $\ell$, \[\psi_j\left(g\right)=-\psi_k\left(-g\right)=-\left(-\psi_\ell\left(-\left(-g\right)\right)\right)=\psi_\ell\left(g\right)\] Let $\psi=\psi_j\vert_{[-\epsilon,\epsilon]^I}\,\forall j$, then $\psi\left(g\right)+\psi\left(-g\right)=0$. Now, substituting $\tilde f_1=f, \tilde f_2=g, \tilde f_3=-f-g, \tilde f_4=\dots=\tilde f_m=0$, we know that $\psi$ satisfies the Cauchy functional equation for all $f,g,f+g\in[-\epsilon,\epsilon]^I$. By \tb{Lemma 1}, we can uniquely extend $\psi$ to $\overline\psi\colon C(I)\to\mb R$ satisfying the Cauchy functional equation for all $f,g\in C(I)$. Now, define $\varphi_j(\tilde f)=\psi_j(\tilde f)-\overline\psi(\tilde f)$ for all $\tilde f\in\tilde I^I$, we show that $\varphi_j=0$ on $\tilde I^I$ for any $j$. Indeed, we know that $\varphi_j=0$ on $[-\epsilon, \epsilon]^I$. From the above, we get \[\left(\tilde f_j\in\tilde I^I\,\forall j,\sum\limits_{j=1}^m\tilde f_j=0\right)\implies\sum\limits_{j=1}^m\psi_j(\tilde f_j)=0\implies\sum\limits_{j=1}^m\varphi_j(\tilde f_j)=-\sum\limits_{j=1}^m\overline\psi(\tilde f_j)=-\overline\psi\left(\sum\limits_{j=1}^m\tilde f_j\right)=-\overline\psi\left(0\right)=0.\] For any $f\in\tilde I^I$, since $-f\in\left[-\frac{m-1}m,\frac1m\right]^I$, there exist $f_2,\dots, f_m\in\left[-\frac1m,1-\frac1m\right]^I=\tilde I^I$ such that $f+\sum\limits_{j=2}^mf_j=0$, and note that $\frac1{m-1}\sum\limits_{j=2}^mf_j\in\tilde I^I$. The above implication gives \[\varphi_1\left(f\right)+\varphi_2\left(\frac{-1}{m-1}f\right)+\dots+\varphi_m\left(\frac{-1}{m-1}f\right)=0.\] For any $\ell\ge 1$, replacing $f$ by $\left(\frac{-1}{m-1}\right)^\ell f$, we obtain \[\varphi_1\left(\left(\frac{-1}{m-1}\right)^\ell f\right)+\varphi_2\left(\left(\frac{-1}{m-1}\right)^{\ell+1}f\right)+\dots+\varphi_m\left(\left(\frac{-1}{m-1}\right)^{\ell+1}f\right)=0.\] We know that for sufficiently large $\ell+1$, $\varphi_2, \dots, \varphi_m$ vanish, so the equality implies that $\varphi_1\left(\left(\frac{-1}{m-1}\right)^\ell f\right)=0$ as well, so by symmetry $\varphi_j\left(\left(\frac{-1}{m-1}\right)^\ell f\right)=0$ for any $j$. Recursively, we show that $\varphi_j\left(f\right)=0$ for any $j$, so $\psi_j=\overline\psi$ on $\tilde I^I$ for any $j$. Now note that $I$ is a locally compact Hausdorff space. Hence, due to the continuities of the $\alpha_j$'s, $\overline\psi$ is continuous as well. Since $\overline\psi$ satisfies the Cauchy functional equation, it follows that $\overline\psi\in(C(I))^*$, thus we can apply a version of Riesz representation theorem (see, for example, theorem 2.14 of \cite{r1987}) and conclude that \[\overline\psi(f)=\int_Ifd\mu\] for some positive measure $\mu$ on I. It is easy to see that our conditions require $\mu$ to be a probability measure. Reverting, we obtain \begin{align*}\alpha_j\left(f\right)&=\alpha_j\left(f\right)-\alpha_j\left(0\right)=\tilde\alpha_j\left(f-\frac1m\right)-\tilde\alpha_j\left(-\frac1m\right)=\psi_j\left(f-\frac1m\right)-\psi_j\left(-\frac1m\right)\\&=\overline\psi\left(f-\frac1m\right)-\overline\psi\left(-\frac1m\right)=\overline\psi\left(f\right)=\int_Ifd\mu,\end{align*} concluding the proof.

