\section{Some Theoretical Results}\label{sec:4}
 In the Bayesian context, parameters of the log-logistic distribution such as the scale and shape are treated as random variables, and posterior distributions are derived using techniques like MCMC \cite{robert2004monte}. These methods enhance inference by allowing the incorporation of expert knowledge and yielding full probability distributions over parameters rather than point estimates. We discuss some theorems below to justify our claim in this context. In the following section, we discuss all the possible theorems and lemmas and showed the proof in the Appendix section. In case of LTLL, researchers introduced  method to estimate parameters \cite{kreer2024maximum}, it is particularly advantageous in situations where data availability is limited.

\begin{theorem}\label{thm1}
    Let us consider the i.i.d. left-truncated sampl\( X_1, \dots, X_N \) be i.i.d. with \( X_i > 1 \) and at least two distinct values. Define the objective function
\[
\varphi(\lambda, \beta) = N \ln \left(1 + \frac{1}{\lambda} \right) + N \ln \beta - N \ln \lambda + \beta S - 2 \sum_{i=1}^N \ln \left[1 + \frac{X_i^\beta}{\lambda} \right].
\]

Define \( \beta_C > 0 \) by
\[
\frac{1}{2} = \frac{1}{N} \sum_{i=1}^N \frac{1}{X_i^{\beta_C}}, 
\quad \text{and} \quad 
\frac{1}{\beta_0} = \frac{1}{N} \sum_{i=1}^N \ln X_i.
\]

Then:
\begin{itemize}
    \item[(1)] If \( \beta_0 > \beta_C \), then \( \varphi \) has a global maximum \( (\hat{\lambda}, \hat{\beta}) \in \mathbb{R}^+ \times \mathbb{R}^+ \).
    \item[(2)] If \( \beta_0 \leq \beta_C \), then \( \varphi \) attains a (local) maximum at the boundary \( (\hat{\lambda}, \hat{\beta}) = (0, \beta_0) \).
\end{itemize}

\end{theorem}
Theorem \ref{thm1} establishes the existence of a maximum for the objective function $\varphi(\lambda, \beta)$ derived from a left-truncated sample, a common scenario in survival analysis and reliability theory. It shows the existence of LTLL from the study of Kreer et al.\cite{kreer2024maximum}. The condition involving $\beta_0$ and $\beta_C$ provides a threshold behavior that determines whether the maximum lies in the interior or on the boundary of the parameter space. Recent works have extended such analysis in several directions. For instance, Poudyal, C., \& Brazauskas \cite{poudyal2023finite} discussed the Pareto tail index under data truncation and censoring, demonstrating how tail behavior influences parameter estimates. Moreover, Cope EW \cite{cope2011penalized} proposed penalized likelihood-based techniques that maintain consistency and efficiency under heavy truncation and contamination, echoing the sensitivity of $\varphi$ to the tail index $\beta$ as seen in Theorem \ref{thm1}. Therefore, the consistency of the Bayes estimator refers to its convergence to the true parameter value as the sample size increases (see e.g. \cite{diaconis1986consistency}). Under regularity conditions, such as identifiability of the model, a well-specified prior that assigns positive mass around the true parameter, and increasing sample size, the posterior distribution concentrates around the true value \cite{pati2013posterior}. 
\begin{theorem}\label{thm2}(Posterior Consistency of Bayesian Estimators)
Let $(\alpha_N, \beta_N)$ be the sequence of Bayesian estimators based on the LTLL sample $X_1, ..., X_N$. If the prior distributions are {proper and non-informative}, then the Bayesian estimators are {strongly consistent}, meaning:
\[
(\alpha_N, \beta_N) \xrightarrow{P} (\alpha_0, \beta_0),
\]
where $(\alpha_0, \beta_0)$ are the true parameters.    
\end{theorem}


%\subsection{Lemma 2: Closed-Form Expression for the Marginal Posterior of $\beta$}
\begin{lemma}(Closed-Form Expression for the Marginal Posterior of $\beta$)
Closed-Form Expression for the Marginal Posterior of $\beta$: Integrating out $\alpha$ in the joint posterior leads to:
\[
\pi(\beta | X) \propto \beta^{N+c-1} \exp\left[ -d\beta - \sum_{i=1}^{N} \ln (1 + X_i^\beta) \right].
\]
This function can be approximated by a gamma distribution in large samples.    
\end{lemma}


\begin{proof}
The joint posterior distribution of $(\alpha, \beta)$, given data $X = \{X_1, \dots, X_N\}$, is given by Bayes' theorem:
\begin{equation}
    \pi(\alpha, \beta | X) \propto \pi(X | \alpha, \beta) \pi(\alpha, \beta).
\end{equation}
Assuming a prior of the form $\pi(\alpha, \beta) = \pi(\alpha) \pi(\beta)$ and integrating out $\alpha$, we obtain the marginal posterior for $\beta$:
\begin{equation}
    \pi(\beta | X) = \int \pi(\alpha, \beta | X) d\alpha.
\end{equation}

Under a conjugate prior assumption, integrating out $\alpha$ leads to a closed-form expression:
\begin{equation}
    \pi(\beta | X) \propto \beta^{N+c-1} \exp\left[ -d\beta - \sum_{i=1}^{N} \ln (1 + X_i^\beta) \right],
\end{equation}
where $c$ and $d$ are hyperparameters from the prior distribution. For large $N$, the likelihood function dominates, and the posterior distribution of $\beta$ can be approximated using a gamma distribution due to the shape of the exponent and power-law behavior (see e.g. \cite{malevergne2005empirical}). Thus, we conclude that for large samples, $\pi(\beta | X)$ is well-approximated by a gamma distribution.

\end{proof}

\begin{theorem} (Credible Interval for Truncated Log-Logistic Parameters) Let $X_1, \dots, X_N$ be an i.i.d. sample from a left-truncated log-logistic distribution $LL(\alpha, \beta; x_L)$ with truncation point $x_L > 0$, and suppose that at least two observations differ. Let $(\hat{\alpha}_N, \hat{\beta}_N)$ denote the  of the scale and shape parameters. Assume the regularity conditions stated in Newey and McFadden \cite{newey1994chapter} hold, and the consistency criterion from the paper is satisfied:
\[
\frac{1}{\beta_0} = \frac{1}{N} \sum_{i=1}^{N} \ln X_i > \beta_C \quad \text{with} \quad \frac{1}{2} = \frac{1}{N} \sum_{i=1}^{N} X_i^{-\beta_C}.
\]

Then, as $N \to \infty$, the posterior distribution of $(\alpha, \beta)$, centered at $(\hat{\alpha}_N, \hat{\beta}_N)$ and scaled by $\sqrt{N}$, converges in distribution to a bivariate normal:
\[
\sqrt{N} \begin{pmatrix}
\hat{\alpha}_N - \alpha \\
\hat{\beta}_N - \beta
\end{pmatrix}
\overset{d}{\to} \mathcal{N}\left( \mathbf{0}, \, I^{-1}(\alpha, \beta) \right),
\]
where $I^{-1}(\alpha, \beta)$ is the inverse Fisher information matrix evaluated at the true parameters.

Consequently, for large $N$, the $(1 - \xi)$ credible region for $(\alpha, \beta)$ is asymptotically equivalent to the Wald-type confidence ellipse:
\[
(\theta - \hat{\theta}_N)^\top I(\hat{\theta}_N) (\theta - \hat{\theta}_N) \leq \chi^2_{2}(1 - \xi),
\]
where $\theta = (\alpha, \beta)^\top$, $\hat{\theta}_N = (\hat{\alpha}_N, \hat{\beta}_N)^\top$, and $\chi^2_{2}(1 - \xi)$ is the $(1 - \xi)$ quantile of the chi-squared distribution with 2 degrees of freedom.

\end{theorem}



\begin{theorem} \label{thm6}(Credible Region for Parameters)
    Show that an approximate $100(1-\gamma)\%$ joint credible region for $(\alpha,\beta)$ for large $N$ is given by the ellipse

\begin{equation}
    \left\{ (\alpha, \beta) : (\theta - \hat{\theta})^\top I(\hat{\theta}) (\theta - \hat{\theta}) \leq \frac{\chi^2_{2, 1-\gamma}}{N} \right\},
\end{equation}

where we write $\theta = (\alpha, \beta)$ and $\hat{\theta} = (\hat{\alpha}, \hat{\beta})$, and $\chi^2_{2,1-\gamma}$ is the $(1-\gamma)$ quantile of the $\chi^2$ distribution with 2 degrees of freedom. 
%This elliptical region is the asymptotic highest-posterior-density credible set for $(\alpha, \beta)$ and coincides (to first order in $1/N$) with the classical $1-\gamma$ confidence ellipse based on the Fisher information.
\end{theorem}

In the estimation of parameters for the LTLL distribution, the standard maximum likelihood method encounters unique challenges due to truncation. The paper by Kreer et al. (2024) \cite{kreer2024maximum} provides a comprehensive analysis of the  framework when the truncation point is fixed, often normalized to \( x_L = 1 \). A key contribution is the identification of a simple and effective existence criterion: the  equations admit a non-trivial solution if and only if the statistic $\beta_0 = \left( \frac{1}{N} \sum_{i=1}^N \ln X_i \right)^{-1}$
exceeds a critical threshold \( \beta_C \), defined by the equation $\frac{1}{N} \sum_{i=1}^N X_i^{-\beta_C} = \frac{1}{2}.$
When this criterion is satisfied, a profile likelihood approach reduces the problem to one dimension, improving numerical stability. The authors further show that in cases where the  does not exist, the LTLL model degenerates to a Pareto distribution, providing a boundary solution that is well-defined in \( L^1(\mathbb{R}^+) \). This rigorous framework not only ensures consistent estimation but also extends applicability to real-world data such as cancer remission times and precipitation measurements (see in section \ref{sec:6}) In the next section, we introduce Bayesian estimation by providing the theoretical establishment above and the algorithm in section \ref{sec:5} below. We discuss some of the proofs of the above theorem in the appendix. 

\section{Algorithm for the Bayesian Estimation of Parameters}\label{sec:5}

For any \( X = \{x_1, x_2, \dots, x_n\} \) be a random sample from a left-truncated log-logistic distribution with parameters \( \alpha > 0 \), \( \beta > 0 \), and fixed truncation point \( x_L > 0 \). The probability density function of the LTLL distribution is given by:

\[
f_T(x \mid \alpha, \beta, x_L) = 
\frac{f(x \mid \alpha, \beta)}{1 - F(x_L \mid \alpha, \beta)}, \quad x > x_L,
\]
where \( f(x \mid \alpha, \beta) \) and \( F(x \mid \alpha, \beta) \) are the standard log-logistic PDF and CDF respectively:

\[
f(x \mid \alpha, \beta) = \frac{(\alpha/\beta)(x/\beta)^{\alpha - 1}}{\left[1 + (x/\beta)^{\alpha}\right]^2}, \quad
F(x \mid \alpha, \beta) = \frac{1}{1 + (x/\beta)^{-\alpha}}.
\]

The steps for Bayesian estimation using Metropolis-Hastings are:

\begin{enumerate}
    \item \textbf{Specify prior distributions:}
    \[
    \alpha \sim \text{Gamma}(a_1, b_1), \quad \beta \sim \text{Gamma}(a_2, b_2).
    \]

    \item \textbf{Define the truncated likelihood:}
    \[
    L_T(\alpha, \beta \mid X) = \prod_{i=1}^{n} \frac{f(x_i \mid \alpha, \beta)}{1 - F(x_L \mid \alpha, \beta)}.
    \]

    \item \textbf{Compute the posterior distribution:}
    \[
    p(\alpha, \beta \mid X) \propto L_T(\alpha, \beta \mid X) \cdot p(\alpha) \cdot p(\beta).
    \]

    \item \textbf{Metropolis-Hastings Sampling Algorithm:}
    \begin{enumerate}
        \item Initialize parameters \( (\alpha^{(0)}, \beta^{(0)}) \).
        \item For \( t = 1, 2, \dots, T \), do:
        \begin{itemize}
            \item Propose new values:
            \[
            \alpha^* \sim q(\alpha \mid \alpha^{(t-1)}), \quad \beta^* \sim q(\beta \mid \beta^{(t-1)}).
            \]
            \item Compute the acceptance ratio:
            \[
            r = \frac{L_T(\alpha^*, \beta^* \mid X) \cdot p(\alpha^*) \cdot p(\beta^*)}
                     {L_T(\alpha^{(t-1)}, \beta^{(t-1)} \mid X) \cdot p(\alpha^{(t-1)}) \cdot p(\beta^{(t-1)})}
              \cdot \frac{q(\alpha^{(t-1)} \mid \alpha^*) q(\beta^{(t-1)} \mid \beta^*)}
                     {q(\alpha^* \mid \alpha^{(t-1)}) q(\beta^* \mid \beta^{(t-1)})}.
            \]
            \item Accept \( (\alpha^*, \beta^*) \) with probability \( \min(1, r) \); otherwise retain \( (\alpha^{(t)}, \beta^{(t)}) = (\alpha^{(t-1)}, \beta^{(t-1)}) \).
        \end{itemize}
    \end{enumerate}

    \item \textbf{Posterior summaries:} After burn-in and thinning,
    \[
    \hat{\alpha} = \frac{1}{T'} \sum_{t=1}^{T'} \alpha^{(t)}, \quad
    \hat{\beta} = \frac{1}{T'} \sum_{t=1}^{T'} \beta^{(t)}.
    \]

    \item \textbf{Credible intervals:} Compute \(95\%\) credible intervals using posterior quantiles:
    \[
    \text{CI}_{\alpha}^{95\%} = (\alpha_{2.5\%}, \alpha_{97.5\%}), \quad
    \text{CI}_{\beta}^{95\%} = (\beta_{2.5\%}, \beta_{97.5\%}).
    \]
\end{enumerate}

Therefore, the Bayesian framework for estimating the parameters of the LTLL distribution with a fixed truncation point \( x_L > 0 \), the unknown shape and scale parameters \( \alpha \) and \( \beta \) are treated as random variables with prior distributions, typically chosen as independent Gamma distributions. The likelihood function is adjusted to account for left truncation by normalizing the standard log-logistic density over the interval \( (x_L, \infty) \), and the posterior distribution is obtained by applying Bayes' theorem to combine this likelihood with the priors. Mathematically, the posterior is proportional to the product of the truncated likelihood and the priors. Inference is then based on posterior summaries such as the mean or median (e.g., \( \hat{\alpha} = \mathbb{E}[\alpha \mid X] \)), and uncertainty is quantified using credible intervals derived from the posterior.


\section{Simulation Study}\label{sec:6}

