\begin{tikzcd}
&& \textnormal{QS} \arrow[d, shift left=-1ex, "\diamondsuit" swap] & &\\
&& \HKQS \arrow[u, dashed, shift right=1ex, "\spadesuit" swap] & & \\
{\mathcal{GL}_m(e,f)\neq 0} \arrow[r, dashed, shift left=-1ex, "\blacklozenge" swap]  & \GLQS \arrow[l, dashed, shift right=1ex, "\blacksquare" swap] \arrow[ruu, "\clubsuit", dashed, bend left] \arrow[ru, "\heartsuit"] && \SLQS  \arrow[r, dashed, shift left=-1ex, "\blacktriangle"] \arrow[ll, "\bigstar", dashed] \arrow[ul, "\triangle" swap]& {\mathcal{SL}_m(e,f)\neq 0} \arrow[l, dashed, shift left=-1ex]
\end{tikzcd}
\end{center}
where 
\begin{itemize}[label={}]
\item $\diamondsuit$: when $H=\underline{\rm aut}^r(A)$ and $K=\underline{\rm aut}^r(B)$ are Manin's universal quantum groups (cf.~\cite[Definition 2.1.1]{HNUVVW2024-2}) associated to $A,B$ respectively;
\smallskip

\item $\heartsuit$: when $A=A(e, N)$ and $B=A(f, N)$ are superpotential algebras correspond to nondegenerate twisted superpotentials $e,f$ respectively (cf.~\Cref{defn:superpotential}); $H=\mathcal{GL}_m(e)$ and $K=\mathcal{GL}_m(f)$ are Hopf algebras defined in \Cref{cogp} for any integers $2 \leq N \leq m$;
\smallskip

\item $\triangle$: when $A=A(e, N)$ and $B=A(f, N)$; $H=\mathcal{SL}_m(e)$ and $K=\mathcal{SL}_m(f)$ are defined in \Cref{cogp};
\smallskip

\item $\spadesuit$: by \Cref{RQS}, when $A, B$ are locally finite;
\smallskip

\item $\clubsuit$: by \Cref{SQSAS}, when $A=A(e,N)$ and $B=A(f,N)$ for $L$-traceable $e,f$ (cf.~\Cref{defn:traceable}) with $2 \leq L \leq N \leq m$; $H=\mathcal{GL}_m(e)\cong \underline{\rm aut}^r(A(e, N))$ and $K=\mathcal{GL}_m(f)\cong \underline{\rm aut}^r(A(f,N))$;
\smallskip

\item $\blacklozenge$: by \Cref{SQSMTE}, when $A=A(e, N)$ and $B=A(f, N)$ and $\mathcal{GL}_m(e,f)$ is defined in \eqref{eq:alg};
\smallskip

\item $\blacksquare$: by \Cref{SQSBG}, when $A=A(e, N)$ and $B=A(f, N)$ for $L$-traceable $e,f$ with $2 \leq L \leq N \leq m$;\smallskip

\item $\bigstar$: by \Cref{thm:SLQS} and \Cref{SQSMTE}, due to the fact that $\mathcal{SL}_m(e)$ and $\mathcal{SL}_m(f)$ are respective quotients of $\mathcal{GL}_m(e)$ and $\mathcal{GL}_m(f)$;
\smallskip

\item $\blacktriangle$: by \Cref{thm:SLQS}, when $A=A(e, N)$ and $B=A(f, N)$. For the direction $\SLQS$ implies $\mathcal{SL}_m(e,f)\neq 0$, we need to assume $e,f$ are $L$-traceable for some $2 \leq L \leq N \leq m$.
\end{itemize}



