\subsection{Nondegenerate twisted superpotentials} 
\label{subsect:nondegentwistsuppot}

\begin{defn}
\label{defn:superpotential}
Let $2 \leq N \leq m$ be integers and $V$ be an $q$-dimensional $\kk$-vector space. Let $\phi: V^{\otimes m} \rightarrow V^{\otimes m}$ be the linear map defined by 
\[\phi\left( v_1 \otimes \cdots \otimes v_m \right) \coloneqq  v_m \otimes v_1 \otimes \cdots \otimes v_{m-1}, \quad \text{for any $v_i \in V$}.\]
\begin{enumerate}
\item[(1)]  Take an element $s \in V^{\otimes m}$. 
\begin{itemize}
\item[(i)] We say $s$ is a \emph{twisted superpotential} if there is $\mathbb{P} \in \GL(V)$ so that \[\left( \mathbb{P} \otimes \id^{\otimes(m-1)} \right) \phi(s) = s.\]
\item[(ii)] A twisted superpotential $s$ is said to be 
\emph{nondegenerate} if for $\nu_1\in V^*$, $(\nu _1\otimes \nu _2\otimes \cdots \otimes \nu _m)(s)=0$ for all $\nu_2,\ldots,\nu_m\in V^*$ implies that $\nu _1=0$. 
\end{itemize}
\item[(2)] Given a twisted superpotential $s \in V^{\otimes m}$, the \emph{superpotential algebra} associated to $s$ is defined as
\[A(s,N) \coloneqq  TV / \partial^{m-N} (\Bbbk s),\]
where $TV$ is the tensor algebra on $V$,
\begin{align*} 
\partial  (\Bbbk s) &= \left\{ \left( \nu \otimes \id^{\otimes (m-1)}\right) (\alpha s) \mid \nu \in V^*, \alpha \in \Bbbk \right\}, 
\text{ and } \\
\partial^{i+1} (\Bbbk s) &= \partial \left( \partial^i ( \Bbbk s)\right), \quad \text{for all }i \geq 0. \end{align*} 
    \end{enumerate}
\end{defn} 

In the above definition, $s\in V^{\otimes m}$ is called a \emph{superpotential} if $\phi(s)=s$, that is, $\mathbb P=\mathbb I$ the identity matrix. Without loss of generality, we may consider a (nondegenerate) twisted superpotential as a (nondegenerate) linear map $s: \kk \to V^{\otimes m}$. We use this identification interchangeably throughout the paper. Moreover, nondegenerate twisted superpotentials are closely related to preregular forms (see e.g., \cite{Dubois-Violette2007}). 



The combined result due to Dubois-Violette and Mori--Smith demonstrates that every $N$-Koszul AS-regular algebra arises from superpotential algebras, and it identifies which superpotential algebras yield CY algebras. 

\begin{thm}[{\cite[Theorem 11]{Dubois-Violette2007}, \cite[Corollary 4.5]{MS2016}}]
\label{NKAS}
Let $A$ be an $N$-Koszul, Artin--Schelter regular algebra of global dimension $d$. There is a unique nondegenerate twisted superpotential $s\in A_1^{\otimes m}$ up to nonzero scalar multiples with $2 \leq N \leq m$ such that $A=A(s,N)$. Moreover, we get 
\begin{itemize}
    \item[(1)] $m$ is the AS index for $A$. When $N=2$, $m=d$. When $N\ge 3$, $d$ is odd and $m=\frac{1}{2}N(d-1)+1$.
    \item[(2)] The Nakayama automorphism $\mu$ of $A(s,N)$ is determined by $\mu|_{A_1}=(-1)^{d+1}(\mathbb P^T)^{-1}$, where $(s,\mathbb P)$ is the corresponding nondegenerate twisted superpotential in $A_1^{\otimes m}$.
    \item[(3)] $A(s,N)$ is CY if and only if $\mathbb P=(-1)^{d+1}\mathbb I$ if and only if $\phi(s)=(-1)^{d+1}s$ where $\phi: A_1^{\otimes m}\to A_1^{\otimes m}$ is the cyclic permutation. 
\end{itemize}
\end{thm}



Let $2\leq N\leq m$ be integers, and $V$ be any $q$-dimensional vector space. We identify $V^{\otimes m}$ as an $mq$-dimensional vector space and define ${\rm Gr}(1,mq)$ to be the Grassmannian parameterizing the set of all one-dimensional subspaces of $V^{\otimes m}$. Let $f\in V^{\otimes m}$ be a nondegenerate twisted superpotential, then $\kk f$ can be identified as an element in ${\rm Gr}(1,mq)$. Now, we define a subset of the Grassmannian ${\rm Gr}(1,mq)$ as 
\begin{equation}
\label{ASclass}
   {\rm AS}(m,N,q) \coloneqq \{\kk f\in {\rm Gr}(1,mq)\,|\, \text{$A(f,N)$ is $N$-Koszul AS-regular}\}\subseteq {\rm Gr}(1,mq). 
\end{equation}
It is clear that ${\rm Gr}(1,mq)$ has a natural $\PGL_q(\kk)$ action by acting on $V$ diagonally in $V^{\otimes m}$, which makes ${\rm AS}(m,N,q)$ a $\PGL_q(\kk)$-invariant subset.  There is a subset of ${\rm AS}(m,N,q)$ corresponding to those $N$-Koszul AS-regulars that are Calabi--Yau algebras of dimension $d=2(m-1)/N+1$, which we denote by 
\begin{equation}
\label{CYclass}
    {\rm CY}(m,N,q) \coloneqq \{\kk f\in {\rm AS}(m,N,q)\,|\, \phi(f)=(-1)^{d+1}f\}\subseteq {\rm AS}(m,N,q),
\end{equation}
where $\phi: V^{\otimes m}\to V^{\otimes m}$ is the cyclic permutation. For short, we refer to any $\kk f \in {\rm AS}(m,N,q)$ or ${\rm CY}(m,N,q)$ as an $N$-Koszul AS-regular superpotential or a Calabi--Yau superpotential, respectively.

