\subsection{Cogroupoids}
We now discuss the technical machinery necessary for investigating quantum symmetries related to superpotential algebras. This involves analyzing the Morita--Takeuchi equivalence between universal quantum groups associated to superpotential algebras, utilizing the concept of cogroupoids as introduced by Bichon \cite{Bichon2014}. 

\begin{defn}
\label{defn:cocategory}
A \emph{$\kk$-cocategory} $\mc{C}$ consists of:
\begin{enumerate}
\item A set of objects $\ob(\mc{C})$;
\item For any $X,Y\in \ob(\mc{C})$, a $\kk$-algebra $\mc{C}(X,Y)$;
\item For any $X,Y,Z\in \ob(\mc{C})$, $\kk$-algebra homomorphisms
\[ \bdt^Z_{XY}:\mc{C}(X,Y)\ra \mc{C}(X,Z)\ot \mc{C}(Z,Y) \qquad \t{and} \qquad \vps_X:\mc{C}(X,X)\ra \kk \]
such that for any $X,Y,Z,T\in \ob(\mc{C})$, the following diagrams commute
\[
\xymatrix{
\mc{C}(X,Y)\ar^-{\bdt^Z_{X,Y}}[rr]\ar_{\bdt^T_{X,Y}}[d] && \mc{C}(X,Z)\ot \mc{C}(Z,Y)\ar^-{\bdt^T_{X,Z}}[d]\\
\mc{C}(X,T)\ot \mc{C}(T,Y)\ar^-{\id\ot \bdt^Z_{T,Y}}[rr]&&\mc{C}(X,T)\ot \mc{C}(T,Z)\ot \mc{C}(Z,Y), } 
\]
\[\xymatrix
{\mc{C}(X,Y)\ar@{=}[rd]\ar_{\bdt^Y_{X,Y}}[d]&\\
\mc{C}(X,Y)\ot\mc{C}(Y,Y)\ar^-{\id \ot \vps_Y}[r]&\mc{C}(X,Y),} \qquad 
\xymatrix
{\mc{C}(X,Y)\ar@{=}[rd]\ar_{\bdt^X_{X,Y}}[d]&\\
\mc{C}(X,X)\ot\mc{C}(X,Y)\ar^-{\vps_X \ot \id }[r]&\mc{C}(X,Y).}
\]
\end{enumerate}
\end{defn}

For $a^{X,Y}\in \mc{C}(X,Y)$, we use Sweedler's notation to write 
\[ \bdt^Z_{X,Y}(a^{X,Y})=\sum a^{X,Z}_1\ot a^{Z,Y}_2. \]
From its definition, a cocategory with one object is just a bialgebra. In particular, $\mc{C}(X, X)$ is a bialgebra for any $X \in \ob(\mc{C})$. A cocategory $\mc{C}$ is said to be \emph{connected} if $\mc{C}(X,Y)$ is a nonzero algebra for any $X,Y\in \ob(\mc{C})$ \cite[Definition 2.4]{Bichon2014}.

\begin{defn}
\label{defn:cogroupoid}
A \emph{$\kk$-cogroupoid} $\mc{C}$ consists of a $\kk$-cocategory $\mc{C}$ together with linear maps
\[ S_{X,Y}:\mc{C}(X,Y)\longrightarrow \mc{C}(Y,X), \]
for any $X,Y\in \ob(\mc{C})$, such that the following diagram commutes
{\small \[\xymatrix{\mc{C}(Y,X) & \kk \ar[l]_-u & \mc{C}(X,X)\ar[d]_{\bdt_{X,X}^Y}\ar[r]^-{\vps_X}\ar[l]_-{\varepsilon_X} &\kk\ar[r]^-u&\mc{C}(X,Y)\\
\mc{C}(Y,X)\ot\mc{C}(Y,X) \ar[u]^m &&\mc{C}(X,Y)\ot\mc{C}(Y,X)\ar[rr]^{\id\ot S_{Y,X}} \ar[ll]_-{S_{X,Y} \otimes \id} &&\mc{C}(X,Y) \ot\mc{C}(X,Y). \ar[u]^m} \]} 
\end{defn}


In a cogroupoid $\mc{C}$, the bialgebra $\mc{C}(X,X)$ is a Hopf algebra for any $X\in \ob(\mc{C})$, with the antipode map given by $S_{X,X}$, and if $\mc{C}(X,Y)$ is nonzero then it is a $\mc{C}(X,X)$-$\mc{C}(Y,Y)$-bi-Galois object \cite[Proposition 2.8]{Bichon2014}. For other properties of cogroupoids, we refer the reader to \cite{Bichon2014}.

The following is Bichon's reformulation of Schauenburg's result \cite{Sch1996} about bi-Galois objects for Morita--Takeuchi equivalences in terms of cogroupoids. 
\begin{thm}[{\cite[Theorem 2.10]{Bichon2014}}]
Let $H$ and $K$ be Hopf algebras. Then the following conditions are equivalent.
 \begin{enumerate}
     \item There exists a $\kk$-linear equivalence of monoidal categories ${\rm comod}(H)\stackrel{\otimes }{\cong} {\rm comod}(K)$;
     \item There exists a connected cogroupoid $\mathcal C$ and two objects $X,Y \in \ob(\mc{C})$ such that $H \cong\mathcal C(X, X)$ and $K \cong\mathcal C(Y, Y )$.
 \end{enumerate}
\end{thm}

Moreover, according to \cite[Theorem 2.12]{Bichon2001}, in a cogroupoid $\mathcal C$, suppose $\mathcal C(X,Y)\neq 0$, then $\mathcal C(Y,X)\neq 0$ and we have $\kk$-linear equivalences of monoidal categories that are inverse of each other: 
\begin{align*}
\comod(\mathcal C(X,X))&\overset{\otimes}{\cong} \comod(\mathcal C(Y,Y)) & \comod(\mathcal C(Y,Y))&\overset{\otimes}{\cong} \comod(\mathcal C(X,X))\\
W&\mapsto W\sq_{\mathcal C(X,X)}\mathcal{C}(X,Y) & M&\mapsto M\sq_{\mathcal C(Y,Y)} \mathcal{C}(Y,X).
\end{align*}

\begin{defn}[{\cite[Definition 4.2.1]{HNUVVW2024-3}}]
A cogroupoid $\mathcal C$ is called \emph{copivotal}  
if for any $X\in \mathrm{ ob}(\mathcal C)$, there exists some  
character $\Phi_X: \mathcal C(X,X)\to \kk$ such that for any $X,Y\in \mathrm{ ob}(\mathcal C)$, 
\[
S_{Y,X}\circ S_{X,Y}=\Phi_X^{-1}*\id*\Phi_Y,
\]
where the right hand is defined as 
\begin{align*}
\Phi_X^{-1}*\id*\Phi_Y &:=\left(\mathcal C(X,Y)\xrightarrow{\Delta_{X,Y}^X} \mathcal C(X,X)\otimes \mathcal C(X,Y)\right.\\
&\quad \left.\xrightarrow{\id \otimes \Delta_{X,Y}^Y} \mathcal C(X,X)\otimes\mathcal C(X,Y)\otimes  C(Y,Y)\xrightarrow{\Phi_X^{-1}\otimes \id \otimes \Phi_Y} \mathcal C(X,Y)\right),
\end{align*}
and $\Phi_X^{-1} = \Phi_X \circ S_{X,X}$ is the convolution inverse of $\Phi_X$.
\end{defn}


