\subsection{$\mathcal{GL}$-type and $\mathcal{SL}$-type quantum-symmetric equivalences}

For any integer $m \ge 2$, we investigate the cogroupoid $\mathcal{GL}_m$ constructed in \Cref{cogp}. Let $e\in U^{\otimes m},f\in V^{\otimes m}$ be two nondegenerate twisted superpotentials where $U, V$ are two $\kk$-vector spaces with fixed bases $\{u_1, \ldots, u_p\}$ and $\{v_1, \ldots, v_q\}$, respectively. We also write $\{u^1, \ldots, u^p\}$ and $\{v^1, \ldots, v^q\}$ for the corresponding dual bases of $U^*$ and $V^*$. Suppose the bi-Galois object $\mathcal{GL}_m(e,f)\neq 0$. Then, a monoidal equivalence between two right comodule categories:
\begin{align}
\label{Fcogroupoid}
(F,\xi): \comod(\mathcal{GL}_m(e))~&\overset{\otimes}{\cong}~ \comod(\mathcal{GL}_m(f)) \\
W~&\mapsto~ F(W)\coloneqq  W\,\square_{\mathcal{GL}_m(e)}\,\mathcal{GL}_m(e,f), \notag
\end{align}
can be given by the cotensor product with the bi-Galois object $\mathcal{GL}_m(e,f)$, and $\xi$ is a natural isomorphism (as in \cite[Proposition 1.4]{Ulbrich1987} for left comodules) 
\begin{align*}
\xi_{W,M}: (W\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f))\otimes (M\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f))~&\cong~ (W\otimes M)\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f)\\
\left(\sum w_i\otimes a_i\right)\otimes \left(\sum m_j\otimes b_j\right)~&\mapsto~ \sum w_i\otimes m_j\otimes a_ib_j
\end{align*}
satisfying certain compatible conditions (cf. \cite[\S 2.4]{EGNO2015}) for $w_i \in W, m_j \in M$ and $a_i,b_j \in \mathcal{GL}_m(e,f)$. In our context, the cotensor product is explicitly given by 
\begin{align}\label{coten}
W\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f) \coloneqq \left\{x\in W\otimes \mathcal{GL}_m(e,f)\,|\, (\rho_W\otimes \id_{\mathcal{GL}_m(e,f)})(x)=(\id_W \otimes \Delta_{e,f}^e)(x)\right\},
\end{align}
where $\rho_W: W\to W\otimes \mathcal{GL}_m(e)$ is the right $\mathcal{GL}_m(e)$-comodule structure map on $W$. Moreover, the right $\mathcal{GL}_m(f)$-comodule structure on $F(W)= W\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f)$ comes from that of $\mathcal{GL}_m(f)$ on $\mathcal{GL}_m(e,f)$ via $\Delta_{e,f}^f$. 


We denote by $U_e\coloneqq U$ the right comodule over $\mathcal{GL}_m(e)$ given via the $\mathcal{GL}_m(e)$-coaction $u_i\mapsto \sum_{1\leq j\leq p} u_j\otimes a_{ji}^{e,e} \in U_e \otimes \mathcal{GL}_m(e)$. Similarly, we denote by $V_f\coloneqq V$ the analogous right comodule over $\mathcal{GL}_m(f)$. Using \eqref{eq:alg}, it is straightforward to check that 
\begin{align*}
  e: \kk(D^{e,e})^{-1} &\to U_e^{\otimes m}\\
 (D^{e,e})^{-1} &\mapsto \sum_{1\leq i_1,\ldots,i_m\leq p}e_{i_1\cdots i_m}u_{i_1}\otimes \cdots \otimes u_{i_m}
\end{align*}
is a right $\mathcal{GL}_m(e)$-comodule map, where $\kk(D^{e,e})^{-1}$ is the one-dimensional right $\mathcal{GL}_m(e)$-comodule given by the group-like element $(D^{e,e})^{-1}$. The $\kk$-vector space dual $U_e^*$ equipped with the right $\mathcal{GL}_m(e)$-comodule structure given by $u^i\mapsto \sum_{1\leq j\leq p}u^j\otimes b_{ij}$ is the left dual of $U_e$ in the category $\comod(\mathcal{GL}_m(e))$. Moreover, the dual map 
\[
e^*~=~\left((U_e^*)^{\otimes m}\xrightarrow{\id \otimes {\rm coev} } (U_e^*)^{\otimes m} \otimes \kk (D^{e,e})^{-1} \otimes \kk (D^{e,e})\xrightarrow{\id \otimes e \otimes \id } (U_e^*)^{\otimes m} \otimes U_e^{\otimes m} \otimes \kk (D^{e,e})\xrightarrow{{\rm coev}\otimes \id }\kk D^{e,e}\right)
\]
is again $\mathcal{GL}_m(e)$-colinear and is given by
\begin{align*}
    e^*(u^{i_1}\otimes u^{i_m})&\,=\left\langle u^{i_1}\otimes \cdots \otimes u^{i_m}, \sum\limits_{1\leq j_1,\ldots,j_m\leq p} e_{j_1\cdots j_m}u_{j_1}\otimes \cdots \otimes u_{j_m}\right \rangle\, D^{e,e}\\
    &\,= \sum\limits_{1\leq j_1,\ldots,j_m\leq p}\langle u^{i_1},u_{j_m}\rangle\cdots \langle u^{i_m},u_{j_1}\rangle\,e_{j_1\cdots j_m}\, D^{e,e}\\
    &\,= e_{i_m\cdots i_1}\, D^{e,e}.
\end{align*}
Similar formulas hold for  the $\mathcal{GL}_m(f)$-colinar maps $f: \kk(D^{f,f})^{-1}\to V_f^{\otimes m}$ and $f^*: (V_f^*)^{\otimes m}\to \kk D^{f,f}$.

In what follows, when we say that the morphism $ e: \kk(D^{e,e})^{-1} \to U_e^{\otimes m}$ is nondegenerate, we are viewing $\Imm(e)$ as a nondegenerate twisted superpotential as in \Cref{defn:superpotential}(1)(ii). 


\begin{lemma}
\label{lem:comoduleGL}
Let $2\leq N\leq m$ be integers,  $e\in U^{\otimes m}$ a nondegenerate twisted superpotential, and retain the above notation. Then the corresponding superpotential algebra $A(e,N)=TU_e/\partial^{m-N}(\kk e)$ is a right comodule algebra over $\mathcal{GL}_m(e)$ and over $\mathcal{SL}_m(e)$.
\end{lemma}
\begin{proof}
  Since $U_e$ is a right $\mathcal{GL}_m(e)$-comodule, it suffices to show that $\partial^{m-N}(\kk e)\subset U_e^{\otimes N}$ is a subcomodule over $\mathcal{GL}_m(e)$.
  For any $\mathcal{GL}_m(e)$-subcomodule $\iota: W\subset U_e^{\otimes n}$, it is straightforward to check that the subspace $\partial(W)\subset  U_e^{\otimes (n-1)}$ can be given by  
  \[
  \partial(W)={\rm Image}\left(U_e^*\otimes W\xrightarrow{\id \otimes \iota} U_e^*\otimes U_e^{\otimes n}\xrightarrow{\cong } (U_e^*\otimes U_e)\otimes U_e^{\otimes (n-1)}\xrightarrow{{\rm ev}\otimes \id} U_e^{\otimes (n-1)}\right).
  \]
  Since $\partial(W)$ is the image of the composition of all right $\mathcal{GL}_m(e)$-comodule maps, we have $\partial(W)$ is a $\mathcal{GL}_m(e)$-subcomodule of $U_e^{\otimes (n-1)}$. Iteratively, $\partial^i(W)=\partial(\partial^{i-1}(W))\subset U_e^{\otimes (n-i)}$ are subcomodules for all $2\leq i\leq n$. Applying it to the $\mathcal{GL}_m(e)$-comodule embedding $e: \kk(D^{e,e})^{-1} \to U_e^{\otimes m}$, it implies that $\partial^{m-N}(\kk e)=\partial^{m-N}(\kk (D^{e,e})^{-1})$ is a $\mathcal{GL}_m(e)$-subcomodule of $U_e^{\otimes N}$. Finally, the $\mathcal{SL}_m(e)$-coaction on $A(e,N)$ is induced from the Hopf quotient map $\pi:\mathcal{GL}_m(e)\to \mathcal{SL}_m(e)=\mathcal{GL}_m(e)/(D^{e,e}-1)$.
\end{proof}


In light of \Cref{def:HKQS}, we propose the following notation for the two types of quantum-symmetric equivalence for superpotential algebras regarding Hopf coactions associated with $\mathcal{GL}_m$ and $\mathcal{SL}_m$.

\begin{notation}
\label{GLQSandSLQS}
Let $2\leq N\leq m$ be integers. Suppose $A(e,N)$ and $A(f,N)$ are two superpotential algebras given by nondegenerate twisted superpotentials $e\in U^{\otimes m}$ and $f\in V^{\otimes m}$, respectively. 
\begin{itemize}
      \item[(a)] We say $A(e,N)$ and $A(f,N)$ are \emph{$\mathcal{GL}$ quantum-symmetrically equivalent} (denote $\GLQS$ equivalent) if they are $(\mathcal{GL}_m(e),\mathcal{GL}_m(f))$-QS equivalent.
       \item[(b)] We say $A(e,N)$ and $A(f,N)$ are \emph{$\mathcal{SL}$ quantum-symmetrically equivalent} (denote $\SLQS$ equivalent) if they are $(\mathcal{SL}_m(e),\mathcal{SL}_m(f))$-QS equivalent.
\end{itemize}
\end{notation}


\begin{lemma}
\label{SQSMTE}
Let $e\in U^{\otimes m}$ and $f\in V^{\otimes m}$ be two nondegenerate twisted superpotentials. If $\mathcal{GL}_m(e,f)\neq 0$, then the corresponding superpotential algebras $A(e,N)$ and $A(f,N)$ are $\GLQS$ equivalent. 
\end{lemma}

\begin{proof}
Retain the above notation, with $\{u_1, \ldots, u_p\}$ and $\{v_1, \ldots, v_q\}$ are bases for the $\kk$-vector spaces $U$ and $V$, respectively. To show that $A(e,N)$ and $A(f,N)$ are $\GLQS$ equivalent, it is enough to show that $F(A(e,N))=A(f,N)$, where $F$ is the cotensor product given in \eqref{Fcogroupoid}. By the construction of the superpotential algebras, it is equivalent to show that  $F(U_e)=V_f$, and the morphism $e: \kk (D^{e,e})^{-1}\to U_e^{\otimes m}$ is sent to the morphism $f: \kk (D^{f,f})^{-1}\to V_f^{\otimes m}$. 

We first follow the argument in the proof of \cite[Corollary 3.5]{Bichon2001} to show that $F(U_e)=V_f$. As a consequence of \cite[Theorem 2.12]{Bichon2001}, $\mathcal{GL}_m(f,e)\neq 0$ and we have the inverse monoidal equivalence 
\begin{align*}
(G,\zeta): \comod(\mathcal{GL}_m(f))~&\overset{\otimes}{\cong}~ \comod(\mathcal{GL}_m(e)) \\
M~&\mapsto~ G(M)\coloneqq  M\,\square_{\mathcal{GL}_m(f)}\,\mathcal{GL}_m(f,e).
\end{align*}
It is straightforward to check that the linear map
\begin{align*}
  \nu_f: V_f\to&\, F(U_e)=U_e\square_{\mathcal{GL}_m(e))}\mathcal{GL}(e,f)\\
  v_j\mapsto&\,  \sum_{1\leq i\leq p} u_i\otimes a_{ij}^{e,f}, \quad \text{for all $1 \leq j \leq q$,}
\end{align*}
is $\mathcal{GL}_m(f)$-colinear. Similarly, we have a $\mathcal{GL}_m(e)$-colinear map $\nu_e: U_e\to G(V_f)$. We then obtain a sequence of colinear maps
\[
V_f\xrightarrow{\nu_f} F(U_e)\xrightarrow{F(\nu_e)} FG(V_f)\xrightarrow{\cong }V_f
\]
whose composition is the identity map, as shown by the following concrete computation 
\begin{align*}
 V_f\xrightarrow{} U_e\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f)\xrightarrow{} \left(V_f\square_{\mathcal{GL}_m(f)}\mathcal{GL}_m(f,e)\right)\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f)
 \\\xrightarrow{\cong} V_f\square_{\mathcal{GL}_m(f)}(\mathcal{GL}_m(f,e)\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f))
\xrightarrow{\cong} V_f\square_{\mathcal{GL}_m(f)}\mathcal{GL}_m(f)\xrightarrow{\cong }V_f   
\end{align*}
\begin{align*}
   v_j\mapsto \sum_{1\leq i\leq p} u_i\otimes a_{ij}^{e,f}\mapsto \sum_{1\leq i\leq p} \sum_{1\leq k\leq q} v_k\otimes a_{ki}^{f,e}\otimes a_{ij}^{e,f}=\sum_{1\leq k\leq q}v_k\otimes \Delta_{f,f}^e(a_{kj})\mapsto v_j.
\end{align*}
Hence $\nu_f$ is injective and $F(\nu_e)$ is surjective, and $\nu_f$ is surjective by a symmetric argument. So, we can conclude $F(U_e)=V_f$.

Next, to show that $\xi^{-1}F(e)=f$, note that 
\[F(\kk (D^{e,e})^{-1})=\kk (D^{e,e})^{-1}\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f)=\kk (D^{e,e})^{-1}\otimes (D^{e,f})^{-1}\cong \kk (D^{f,f})^{-1}.\]
We claim the diagram 
\[
\xymatrix{
\kk (D^{f,f})^{-1}\ar[r]^-{f}\ar[d]_-{\cong} & V_f^{\otimes m}\ar[r]^-{=} & F(U_e)^{\otimes m}\ar[r]^-{\cong } & (U_e\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f))^{\otimes m}\ar[d]^-{\xi} \\
 \kk (D^{e,e})^{-1} \square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f)\ar[rrr]^-{e\otimes \id} & && (U_e^{\otimes m})\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f) 
}
\]
commutes. By tracing the diagram at the level of elements, we obtain the composition of maps on the top row and right column as 
\begin{align*}
    (D^{f,f})^{-1}&\overset{f}{\mapsto} \sum_{1\leq i_1,\ldots,i_m\leq q} f_{i_1\cdots i_m}v_{i_1}\otimes \cdots \otimes v_{i_m}\overset{\cong }{\mapsto} \sum_{\stackrel{1\leq i_1,\ldots,i_m\leq q}{1\leq j_1,\ldots,j_m\leq p}} f_{i_1\cdots i_m}(u_{j_1}\otimes a_{j_1i_1}^{e,f})\otimes \cdots \otimes (u_{j_m}\otimes a_{j_mi_m}^{e,f})\\
    &\overset{\xi}{\mapsto} \sum_{1\leq j_1,\ldots,j_m\leq p} u_{j_1}\otimes \cdots \otimes u_{j_m}\otimes \Big( \sum_{1\leq i_1,\ldots,i_m\leq q}f_{i_1\cdots i_m}a_{j_1i_1}^{e,f}\cdots a_{j_mi_m}^{e,f} \Big) \\
\overset{\eqref{eq:alg}}&{=}  \sum_{1\leq j_1,\ldots,j_m\leq p} e_{j_1\cdots j_m}u_{j_1}\otimes \cdots \otimes u_{j_m}\otimes (D^{e,f})^{-1}.
\end{align*}
For the composition of maps on the left column and bottom row, we have 
\begin{align*}
    \kk (D^{f,f})^{-1}&\overset{\cong }{\mapsto} (D^{e,e})^{-1}\otimes (D^{e,f})^{-1}\overset{e\otimes \id }{\mapsto}  \sum_{1\leq j_1,\ldots,j_m\leq p}e_{j_1\cdots j_m} u_{j_1}\otimes \cdots \otimes u_{j_m} \otimes (D^{e,f})^{-1}.    
\end{align*}
They are equal, which shows the commutativity of the above diagram. Moreover, it is straightforward to see that the diagram 
\[
\xymatrix{
\kk (D^{f,f})^{-1}\cong F(\kk(D^{e,e})^{-1})\ar[r]^-{F(e)}\ar[d]_-{\cong} & F(U_e^{\otimes m})\ar[r]^-{\xi^{-1}}\ar[d]_-{\cong}& F(U_e)^{\otimes m}\ar[r]^-{\cong}\ar[d]_-{\cong } & V_f^{\otimes m}\ar[dl]_-{\cong}\\
 \kk (D^{e,e})^{-1} \square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f)\ar[r]^-{e\otimes \id} & (U_e^{\otimes m})\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f)\ar[r]^-{\xi^{-1}}& (U_e\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f))^{\otimes m}& 
}
\]
commutes. Thus, we get $\xi^{-1}F(e)=\xi^{-1}(e\otimes \id)=f$. 
\end{proof}



