\subsection{The Artin--Schelter regular component of the cogroupoid $\mc{GL}_m$}

We propose a concept of traceable superpotentials, which allows the converse of \Cref{SQSMTE} to also hold.

\begin{defn}
\label{defn:traceable}
A nondegenerate twisted superpotential $f\in V^{\otimes m}$ is said to be \emph{$L$-traceable} for some $2\leq L\leq m$ if 
\[
\kk f=\bigcap_{i+j=m-L} V^{\otimes i}\otimes \partial^{m-L}(\kk f)\otimes V^{\otimes j}\subset V^{\otimes m}.
\] 
\end{defn}

It is well-known that superpotentials for $N$-Koszul AS-regular algebras are always $N$-traceable. It is an open question whether the converse also holds. 

\begin{lemma}[{\cite[Proposition 2.12]{MS2016}}]
    If $A(f,N)$ is $N$-Koszul AS-regular, then the superpotential $f$ is $N$-traceable. 
\end{lemma}

\begin{proposition}
\label{traceable}
Let $2 \leq N\leq m$ be integers and $e\in U^{\otimes m}$ and $f\in V^{\otimes m}$ be two nondegenerate twisted superpotentials.
If $A(e,N)$ and $A(f,N)$ are $\GLQS$ equivalent, then $A(e,N')$ and $A(f,N')$ are $\GLQS$ equivalent for any $2\leq N'\leq N$. If we additionally assume that $e,f$ are $L$-traceable for some $2\leq L\leq N$, then $A(e,N')$ and $A(f,N')$ are $\GLQS$ equivalent for any $2\leq N'\leq m$. 
\end{proposition}


\begin{proof}
By definition, there is a monoidal equivalence
\begin{align*}
(F,\xi): \comod(\mathcal{GL}_m(e))~\overset{\otimes}{\cong}~ \comod(\mathcal{GL}_m(f)),
\end{align*}
where $F$ sends $A(e,N)=TU/\partial^{m-N}(\kk e)$ to $A(f,N)=TV/\partial^{m-N}(\kk f)$ as comodule algebras. Therefore, we can assume that $F(U)=V$ and $\xi^{-1} F(\partial^{m-N}(\kk e))=\partial^{m-N}(\kk f)\subseteq V^{\otimes N}$.  

Let $\iota: W\subset U^{\otimes n}$ be a subcomodule over $\mathcal{GL}_m(e)$. We claim that $\xi^{-1} F(\partial W)=\partial(\xi^{-1} F(W))\subseteq V^{\otimes (n-1)}$. This follows from the commutativity of the diagram
\[\small
\xymatrix{
F(U^*\otimes W)\ar[r]^-{F(\id \otimes \iota)}\ar[d]_-{\xi^{-1}} & F(U^*\otimes U^{\otimes n})\ar[d]_-{\xi^{-1}}\ar[r]^-{F(\cong)}& F((U^*\otimes U)\otimes U^{n-1})\ar[r]^-{F({\rm ev}\otimes \id)}\ar[d]_-{\xi^{-1}}& F(U^{\otimes (n-1)})\ar@{=}[d]\\
F(U^*)\otimes F(W)\ar[d]_-{\id \otimes F(\iota)}\ar[r]^-{\id \otimes F(\iota)} &F(U^*)\otimes F(U^{\otimes n})\ar[d]_-{\id \otimes \xi^{-1}}&F(U^*\otimes U)\otimes F(U^{\otimes (n-1)})\ar[d]_-{\xi^{-1}\otimes \xi^{-1}}\ar[r]^-{F({\rm ev})\otimes \id}& F(U^{\otimes (n-1)})\ar@{=}[d]\\
F(U^*)\otimes F(U^{\otimes n})\ar[d]_-{\widetilde{\xi}\otimes \id}\ar[r]^-{\id \otimes \xi^{-1}} &F(U^*)\otimes F(U)^{\otimes n}\ar[d]_-{\widetilde{\xi}\otimes \id}\ar[r]^-{\cong}& (F(U^*)\otimes F(U))\otimes F(U)^{\otimes (n-1)}\ar[d]_-{\widetilde{\xi} \otimes \id\otimes \id}&F(U^{\otimes (n-1)})\ar[d]^-{\xi^{-1}}\\
F(U)^*\otimes F(U^{\otimes n})\ar[r]^-{\id \otimes \xi^{-1}} &F(U)^*\otimes F(U)^{\otimes n}\ar[r]^-{\cong}& (F(U)^*\otimes F(U))\otimes F(U)^{\otimes (n-1)}\ar[r]^-{{\rm ev}\otimes \id}& F(U)^{\otimes (n-1)}
}
\]
where $\widetilde{\xi}$ is defined in \eqref{xitilde}. Observe that the compositions of maps appearing on the outer rectangle show that $\xi^{-1} F(\partial W)$ and $\partial(\xi^{-1} F(W))$ share the same image in $V^{\otimes (n-1)}$. By iteration, one can show that for any $2 \leq N' \leq N$,
\begin{align*}
  \xi^{-1}F(\partial^{m-N'}(\kk e))&\,=\xi^{-1}F(\partial^{N-N'}(\partial^{m-N}(\kk e)))=\partial^{N-N'}(\xi^{-1} F(\partial^{m-N}(\kk e)))\\
  &\,=\partial^{N-N'}(\partial^{m-N}(\kk f))=\partial^{m-N'}(\kk f).
 \end{align*}

Consequently, $F$ sends $A(e,N')=TU/\partial^{m-N'}(\kk e)$ to $A(f,N')=TV/\partial^{m-N'}(\kk f)$ as comodule algebras. Therefore, $A(e,N')$ and $A(f,N')$ are $\GLQS$ equivalent for any $2 \leq N' \leq N \leq m$.

For the second statement of the lemma, now we additionally assume $e,f$ are $L$-traceable for some $2\leq L\leq N$. Thus, we have
\begin{align*}
    \xi^{-1} F(\kk e)&\,=\xi^{-1} F\left(\bigcap_{i+j=m-L} U^{\otimes i}\otimes \partial^{m-L}(\kk e)\otimes  U^{\otimes j} \right)=\bigcap_{i+j=m-L} V^{\otimes i}\otimes \xi^{-1} F(\partial^{m-L}(\kk e))\otimes V^{\otimes j}\\
    &\, =\bigcap_{i+j=m-L} V^{\otimes i}\otimes \partial^{m-L}(\kk f)\otimes V^{\otimes j}=\kk f.
\end{align*}
This implies that $A(e,m)=TU/(\kk e)$ and $A(f,m)=TV/(\kk f)$ are $\GLQS$ equivalent. The result follows immediately from our previous discussion. 
\end{proof}


Now assume nondegenerate twisted superpotentials $e\in U^{\otimes m},f\in V^{\otimes m}$ are $L$-traceable for some $2\leq L\leq N\leq m$ and $A(e,N)$ and $A(f,N)$ are $\GLQS$ equivalent via some monoidal equivalence
\begin{align}
\label{MEUQ}
(F,\xi): \comod(\mathcal{GL}_m(e))~\overset{\otimes}{\cong}~ \comod(\mathcal{GL}_m(f)),
\end{align}
where $F$ sends $A(e,N)$ to $A(f,N)$ as comodule algebras. By \Cref{traceable}, $\partial^{m-L}(\kk e)\subseteq U_e^{\otimes L}$ and $\partial^{m-L}(\kk f)\subseteq V_f^{\otimes L}$ are subcomodules over $\mathcal{GL}_m(e)$ and $\mathcal{GL}_m(f)$, respectively.  As a consequence of $e,f$ being $L$-traceable, we have 
\begin{align*}
 \kk (D^{e,e})^{-1}~&\overset{e}{=}~\bigcap_{i+j=m-L} U_e^{\otimes i}\otimes \partial^{m-L}(\kk e)\otimes U_e^{\otimes j}\subset U_e^{\otimes m} \text{ and}\\
\kk (D^{f,f})^{-1}~&\overset{f}{=}~\bigcap_{i+j=m-L} V_f^{\otimes i}\otimes \partial^{m-L}(\kk f)\otimes V_f^{\otimes j}\subset V_f^{\otimes m},   
\end{align*}
are one-dimensional invertible comodules over $\mathcal{GL}_m(e)$ and $\mathcal{GL}_m(f)$, respectively. Moreover, we obtain $\xi^{-1} F(\kk e)=\kk f$ such that 
\begin{align}\label{Tf}
    f~=~\left(\kk (D^{f,f})^{-1}=F(\kk(D^{e,e})^{-1})\xrightarrow{F(e)}F(U_e^{\otimes m})\xrightarrow{\xi^{-1}} F(U_e)^{\otimes m}\xrightarrow{=}V_f^{\otimes m}\right).
\end{align}

\begin{thm}
\label{SQSBG}
If $A(e,N)$ and $A(f,N)$ are $\GLQS$ equivalent for some $L$-traceable nondegenerate twisted superpotentials $e,f$ with $2\leq L\leq N\leq m$, then $\mathcal{GL}_m(e,f)\neq 0$. Moreover, any monoidal equivalence from $\comod(\mathcal{GL}_m(e))$ to $\comod(\mathcal{GL}_m(f))$ that sends $A(e,N)$ to $A(f,N)$ as comodule algebras is naturally isomorphic to $(-)\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f)$. 
\end{thm}


\begin{proof}
    Since any monoidal equivalence $F:\comod(\mathcal{GL}_m(e))\overset{\otimes}{\cong} \comod(\mathcal{GL}_m(f))$ in \eqref{MEUQ} is given by cotensoring with some nonzero $\mathcal{GL}_m(e)$-$\mathcal{GL}_m(f)$-bi-Galois object $T$, it suffices to show that there exists an $\mathcal{GL}_m(e)$-$\mathcal{GL}_m(f)$-bicomodule algebra isomorphism $\pi: \mathcal{GL}_m(e,f)\cong T$. 

Suppose $e \in U^{\otimes m}, f \in V^{\otimes m}$ where $\dim U=p$ and $\dim V=q$. As usual, write bases $\{u_1,\ldots,u_p\}$ and $\{v_1,\ldots,v_q\}$ for $U_e$ and $V_f$ with dual bases $\{u^1,\ldots,u^p\}$ and $\{v^1,\ldots,v^q\}$ for $U_e^*$ and $V_f^*$, respectively. Since $F$ sends $A(e,N)=TU_e/\partial^{m-N}(\kk e)$ to $A(f,N)=TV_f/\partial^{m-N}(\kk f)$ as comodule algebras, we have $F(U_e)=U_e\sq_{\mathcal{SL}_m(e)}T=V_f$.  Then there are elements $(y_{ji})_{1\leq  j\leq p,1\leq i\leq q}$ of $T$ such that $v_i=\sum_{1\leq j\leq p} u_j\otimes y_{ji}$ for all $1 \leq i \leq q$. Because of the duality transformation $\widetilde{\xi}: F(U_e^*)=U_e^*\sq_{\mathcal{SL}_m(e)}T\cong F(U_e)^*=V_f^*$, therefore there are elements  $(z_{ij})_{1\leq i\leq q,1\leq j\leq p}$ such that $v^i=\sum_{1\leq j\leq p} u^j\otimes z_{ij}$. Moreover, since $e,f$ are $L$-traceable, our previous discussion shows that $F(\kk (D^{e,e})^{\pm 1})=(\kk (D^{e,e})^{\pm 1})\sq_{\mathcal{SL}_m(e)}T=\kk (D^{f,f})^{\pm 1}$. So there are invertible elements $d^{\pm 1}\in T$ such that $(D^{f,f})^{\pm 1}=(D^{e,e})^{\pm 1}\otimes d^{\pm 1}$. It is straightforward to check that the right $\mathcal{GL}_m(f)$-comodule structure on $T$ are 
\begin{gather*}
\rho_r(y_{ji})=\sum_{k=1}^q y_{jk}\otimes a^{f,f}_{ki},\quad \rho_r(z_{ij})=\sum_{k=1}^q z_{kj}\otimes b^{f,f}_{ik},\text{ for}\quad 1\leq j\leq p, 1\leq i\leq q,\quad \rho_r(d^{\pm 1})=d^{\pm 1}\otimes (D^{f,f})^{\pm 1}. 
\end{gather*}

Applying the natural isomorphism of monoidal equivalences $F(-)=(-)\square_{\mathcal{GL}_m(e)}T$ to \eqref{Tf}, we get the commutative diagram \[
\xymatrix{
\kk (D^{f,f})^{-1}=F(\kk(D^{e,e})^{-1})\ar[r]^-{F(e)}\ar[d]_-{\cong}\ar@/^20.0pt/[rrr]^-{f} & F(U_e^{\otimes m})\ar[r]^-{\xi^{-1}}\ar[d]_-{\cong}& F(U_e)^{\otimes m}\ar[r]^-{=}\ar[d]_-{\cong } & V_f^{\otimes m}\ar[dl]_-{\cong}\\
 \kk (D^{e,e})^{-1} \square_{\mathcal{GL}_m(e)}T\ar[r]^-{e\otimes \id} & (U_e^{\otimes m})\square_{\mathcal{GL}_m(e)}T& (U_e\square_{\mathcal{GL}_m(e)}T)^{\otimes m}\ar[l]_-{\xi}& 
}
\]
By a straightforward element tracing as in the proof of \Cref{SQSMTE}, we obtain 
the relations in $T$ 
\[\sum_{1\leq i_1,\ldots,i_m\leq q} f_{i_1\cdots i_m}y_{j_1i_1}\cdots y_{j_mi_m}~=~e_{j_1\cdots j_m}d^{-1},\quad \text{$\forall$ $1\leq j_1,\cdots,j_m\leq p$.}\] 

Now, we apply the monoidal equivalence $F(-)=(-)\square_{\mathcal{GL}_m(e)}T$ to the following commutative diagrams 
\[
\xymatrix{
(V_f^*)^{\otimes m}= F(U_e^*)^{\otimes m}\ar@/^25.0pt/[rrrr]^-{f^*} \ar[r]^-{\xi}\ar[d]_-{\cong} & F((U_e^*)^{\otimes m})\ar[r]^-{F(\cong)}\ar[d]_-{\cong}  & F((U_e^{\otimes m})^*)\ar[d]_-{\cong} \ar[r]^-{F(e^*)}\ar[d]_-{\cong}   & F(\kk D^{e,e})\ar[d]_-{\cong} \ar[r]^-{\cong}& \kk D^{f,f}\ar[dl]^-{\cong} \\
 (U_e^*\square_{\mathcal{GL}_m(e)}T)^{\otimes m}\ar[r]^-{\xi} & (U_e^*)^{\otimes m} \square_{\mathcal{GL}_m(e)}T\ar[r]^-{(\cong) \otimes \id} & (U_e^{\otimes m})^* \square_{\mathcal{GL}_m(e)}T\ar[r]^-{e^*\otimes \id}& \kk D^{e,e}\square_{\mathcal{GL}_m(e)}T
}
\]
which yields, for all $1 \leq j_1,\cdots, j_m \leq q$,
\begin{align*}
    D^{e,e}\otimes f_{j_1\cdots j_m}d&\,=f_{j_1\cdots j_m}D^{f,f}\\
    &\,=f^*(v^{j_m}\otimes \cdots \otimes v^{j_1})\\
    &\,=f^*\left((\sum_{i_m} u^{i_m}\otimes z_{j_mi_m})\otimes \cdots \otimes(\sum_{i_1} u^{i_1}\otimes z_{j_1i_1})\right)\\
    &\,=\sum_{1\leq i_1,\ldots,i_m\leq p}e^*(u^{i_m}\otimes \cdots \otimes u^{i_1})\otimes z_{j_mi_m}\cdots z_{j_1i_1}\\
    &\, =D^{e,e} \otimes \left(\sum_{1\leq i_1,\ldots,i_m\leq p} e_{i_1\cdots i_m}z_{j_mi_m}\cdots z_{j_1i_1}\right),
\end{align*}
and 
\[
\xymatrix{
\quad V_f^*\otimes V_f\ar[r]^-{=}\ar[dr]_-{\cong}\ar@/^25.0pt/[rrrr]^-{\rm ev}  & F(U_e^*)\otimes F(U_e)\ar[r]^-{\xi}\ar[d]_-{\cong} & F(U_e^*\otimes U_e)\ar[r]^-{F({\rm ev})} \ar[d]_-{\cong}& F(\kk)\ar[r]^-{=}\ar[d]_-{\cong} & \kk\ar[dl]^-{\cong}\\
& (U_e^*\square_{\mathcal{GL}_m(e)}T)\otimes (U_e\square_{\mathcal{GL}_m(e)}T)\ar[r]^-{\xi}& (U_e^*\otimes U_e)\square_{\mathcal{GL}_m(e)}T\ar[r]^-{{\rm ev}\otimes \id} & \kk \square_{\mathcal{GL}_m(e)}T
}
\]
which yields, for all $1 \leq i,j \leq q$,
\begin{align*}
    \delta_{ij}=\langle v^i,v_j\rangle=\langle \sum_k u^k\otimes z_{ik}, \sum u_l\otimes y_{lj}\rangle=\sum_{k,l}\langle u^k,u_l\rangle z_{ik}y_{lj}=\sum_{k} z_{ik}y_{kj}.
\end{align*}

In summary, the elements $\{y_{ji}\},\{z_{ij}\},\ d^{\pm 1}$ satisfy the following relations in $T$:
\begin{align*}
\sum_{1\leq i_1,\ldots,i_m\leq q} f_{i_1\cdots i_m}y_{j_1i_1}\cdots y_{j_mi_m}~&=~e_{j_1\cdots j_m}d^{-1},\quad \text{$\forall$ $1\leq j_1,\cdots,j_m\leq p$}\\
  \sum_{1\leq i_1,\ldots,i_m\leq p} e_{i_1\cdots i_m}z_{j_mi_m}\cdots z_{j_1i_1}~&=~f_{j_1\cdots j_m}d,\quad \text{$\forall$ $1\leq j_1,\cdots,j_m\leq q$}  \\
  \sum_{1\leq k\leq p} z_{ik}y_{kj}~&=~\delta_{ij},\quad \text{ $\forall$ $1\leq i,j\leq q$. }
\end{align*}
According to \eqref{eq:alg}, there is a well-defined right $\mathcal{GL}_m(f)$-comodule algebra map $\pi: \mathcal{GL}_m(e,f)\to T$ via $a_{ji}^{e,f}\mapsto y_{ji}$, $b_{ij}^{e,f}\mapsto z_{ij}$ and $(D^{e,f})^{\pm 1}\mapsto d^{\pm 1}$, for all $1 \leq j \leq p, 1 \leq i \leq q$. Moreover, since both $\mathcal{GL}_m(e,f)$ and $T$ are right Galois object over $\mathcal{GL}_m(f)$, $\pi$ is indeed an isomorphism \cite[Proposition 1.6]{Bichon2014}. Consequently, $\mathcal{GL}_m(e,f)\neq 0$. It is clear that $\pi$ is also a left $\mathcal{GL}_m(e)$-comodule algebra isomorphism since the left $\mathcal{GL}_m(e)$-comodule structure on $T$ is induced by 
\begin{gather*}
\rho_l(y_{ji})=\sum_{k=1}^p a^{e,e}_{jk}\otimes y_{ki},\quad \rho_l(z_{ij})=\sum_{k=1}^p b^{e,e}_{kj}\otimes z_{ik}, \text{ for}\quad 1\leq j \leq p, 1\leq i \leq q,\quad \rho_l(d^{\pm 1})=(D^{e,e})^{\pm 1}\otimes d^{\pm 1}. 
\end{gather*}
The last assertion about $(-)\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f)$ follows directly from the above argument.
\end{proof}



The following result can be proved similarly to that in \cite[Theorem 5.33]{CWW2019}.

\begin{lemma}
\label{SQSAS}
Let $e\in U^{\otimes m},f\in V^{\otimes m}$ be $L$-traceable nondegenerate twisted superpotentials with $2\leq L\leq N\leq m$, then we have isomorphisms of universal quantum groups
    \[
    \mathcal{GL}_m(e)~\cong~\underline{\rm aut}^r(A(e,N)) \qquad \text{ and } \qquad \mathcal{GL}_m(f)~\cong~\underline{\rm aut}^r(A(f,N)),
    \]
    where the universal coactions of $\mathcal{GL}_m(e)$ and $\mathcal{GL}_m(f)$ on $A(e,N)$ and $A(f,N)$ are induced by those on $U_e$ and $V_f$, respectively. In particular, the following are equivalent.
    \begin{itemize}
    \item[(1)] $\mathcal{GL}_m(e,f)\neq 0$.
        \item[(2)] $A(e,N)$ and $A(f,N)$ are $\GLQS$ equivalent.
        \item[(3)] $A(e,N)$ and $A(f,N)$ are QS equivalent. 
    \end{itemize} 
\end{lemma}

\begin{proof}
For the first part of the lemma, it suffices to show that the Hopf coaction of $\mathcal{GL}_m(e)$ on $A(e,N)$ has the universal property: for any Hopf coaction of $H$ on $A(e,N)$, while preserving its grading, there is a unique Hopf algebra map $\varphi: \mathcal{GL}_m(e)\to H$ such that the $H$-coaction on $A(e,N)$ factors through that of $\mathcal{GL}_m(e)$ via $\varphi$. Since $H$ coacts on $A(e,N)=TU/\partial^{m-N}(\kk e)$ while preserving its grading, $\partial^{m-N}(\kk e)\subset U^{\otimes N}$ is a subcomodule over $H$. Consequently, $\partial^{m-L}(\kk e)=\partial^{N-L}(\partial^{m-N}(\kk e))\subset U^{\otimes L}$ is again an $H$-subcomodule. Because $e\in U^{\otimes m}$ is $L$-traceable, the natural inclusion 
\[
\kk e=\bigcap_{i+j=m-L} U^{\otimes i}\otimes \partial^{m-L}(\kk e)\otimes U^{\otimes j}\subset U^{\otimes m}
\] 
is $H$-colinear. Then we can apply the universal property of $\mathcal{GL}_m(e)$ regarding Hopf coactions on the above embedding $\kk e\hookrightarrow U^{\otimes m}$ (see \cite[Proposition 5.28]{CWW2019}) to get a unique Hopf algebra map $\varphi: \mathcal{GL}_m(e)\to H$ such that the $H$-coaction on $U$ factors through that of $\mathcal{GL}_m(e)$. Consequently, $\varphi$ is the unique Hopf algebra map such that the $H$-coaction on $A(e,N)$ factors through that of $\mathcal{GL}_m(e)$. Thus, by the universal property of Manin's universal quantum groups, we get the isomorphisms between these universal quantum groups $\mathcal{GL}_m(e)~\cong~\underline{\rm aut}^r(A(e,N))$. The same argument holds for the assertion involving $f$.

For the second part of the lemma, (1) $\Rightarrow$ (2) comes from  \Cref{SQSMTE}; (2) $\Leftrightarrow$ (3) is due to the first part of the lemma, and (2) $\Rightarrow$ (1) follows from \Cref{SQSBG}.
\end{proof}




When $m=2$, every nondegenerate twisted superpotential $f\in V^{\otimes 2}$ is given by some invertible matrix $\mathbb F=(f_{ij})_{1\leq i,j\leq q}\in \GL(V)$ such that $f=\sum_{1\leq i,j\leq q} f_{ij}v_i\otimes v_j$ where $\{v_1,\ldots,v_q\}$ is a basis for $V$. We know $A(f,2)\cong \kk\langle v_1,v_2,\cdots,v_q\rangle/(\sum_{1\leq i,j\leq q} f_{ij}v_iv_j)$ is an AS-regular algebra of global dimension two by \cite{Zhang1996}. As a consequence, every nondegenerate twisted superpotential in $V^{\otimes 2}$ is 2-traceable, and the cogroupoid $\mathcal{GL}_2$ is connected \cite[Theorem B]{HNUVVW2024-3}. For any integer $m \geq 2$, the following theorem shows that $\mathcal{GL}_m$ has a connected component consisting of all Koszul AS-regular superpotentials. Recall the notation ${\rm AS}(m,2,q)$ given in \eqref{ASclass} and note that by \cite[Proposition 2.12]{MS2016}, any superpotential $f$ which gives rise to Koszul AS-regular superpotential algebra $A(f,2)$ is $2$-traceable. 


\begin{thm}
\label{ASSuper}
    Let $m\ge 2$ be any integer and $f\in V^{\otimes m}$ be a nondegenerate twisted superpotential with $\dim V = q$. The following are equivalent.
    \begin{itemize}
        \item[(1)] $\kk f\in {\rm AS}(m,2,q)$;
        \item[(2)] $\mathcal{GL}_m(e,f)\neq 0$ for all $\kk e\in\bigsqcup_{p\geq 2} {\rm AS}(m,2,p)$; 
        \item[(3)] $\mathcal{GL}_m(e,f)\neq 0$ for some $\kk e\in\bigsqcup_{p\geq 2} {\rm AS}(m,2,p)$. 
    \end{itemize}
    Consequently, all superpotentials in $\bigsqcup_{p\geq 2} {\rm AS}(m,2,p)$ giving Koszul AS-regular algebras of dimension $m$ form a connected component of the cogroupoid $\mathcal{GL}_m$. 
\end{thm}

\begin{proof}
 (1) $\Rightarrow$ (2): Suppose $f$ is Koszul AS-regular. Let $e\in U^{\otimes m}$ be any Koszul AS-regular twisted superpotential with $\dim U=p$. By \Cref{NKAS}, we know $A(e,2)$ and $A(f,2)$ are Koszul AS-regular algebras of the same global dimension $m$. First, assume $\kk$ to be algebraically closed. Then, by \cite[Theorem 5.1.1]{HNUVVW2024-2}, $A(e,2)$ and $A(f,2)$ are QS equivalent since they share the same global dimension. Since $e,f$ are $2$-traceable, by \Cref{SQSAS}, we have $\mathcal{GL}_m(e,f)\neq 0$. If $\kk$ is not algebraically closed, consider $A(f,2) \otimes \overline{\kk}$, which is now AS-regular over an algebraically closed field. By the above argument, $\mc{GL}_m(e,f) \otimes \overline{\kk}$ is nonzero, which then implies that $\mc{GL}_m(e,f) \not \neq 0$.

 (2) $\Rightarrow$ (3): is routine. 

 (3) $\Rightarrow$ (1): By the assumption of (3) and \Cref{SQSMTE}, $A(e,2)$ and $A(f,2)$ are $\GLQS$ equivalent for some Koszul AS-regular superpotential $e \in U^{\otimes m}$. Let $s\in W^{\otimes m}$ be the twisted superpotential such that $A(s,2)\cong \kk[x_1,\ldots,x_m]$. By the discussion in (1) $\Rightarrow$ (2), we know $\mathcal{GL}_m(s,e)\neq 0$. So $A(s,2)$ and $A(e,2)$ are $\GLQS$ equivalent by \Cref{SQSMTE}. This implies that $A(s,2)$ and $A(f,2)$ are $\GLQS$ equivalent. Note that $A(s,2)$ is just a noetherian polynomial algebra and $\mathcal{GL}_m(s)$ has bijective antipode \cite[Corollary 5.27]{CWW2019}. Then we can conclude that $A(f,2)$ is Koszul AS-regular by \Cref{PQS}. The last statement is clear.
\end{proof}



In the following result, we demonstrate that the class of Koszul AS-regular algebras of the same dimension $m$ forms a single quantum-symmetric class that includes the polynomial algebra in $m$ variables. This observation provides an alternative characterization of Koszul AS-regular algebras as quantum deformations of projective spaces from a quantum-symmetric perspective. This result extends \cite[Theorem H]{HNUVVW2024-2}, where we relax the assumption regarding the base field, which was previously assumed to be algebraically closed due to the categorical approach of the Tannaka--Krein formalism in \cite{RVdB2017}.

\begin{thm}
\label{AS2cocyle}
Let $A$ be a Koszul AS-regular algebra of finite global dimension and $B$ be any connected graded algebra finitely generated in degree one. Then $A$ and $B$ are QS equivalent if and only if $B$ is a Koszul AS-regular algebra of the same global dimension as $A$. In this case, $A$ and $B$ are 2-cocycle twists of each other if and only if they have the same Hilbert series.   
\end{thm}

\begin{proof}
Let $A$ be Koszul AS-regular of finite global dimension $m$. By \Cref{NKAS}, we may write $A=A(e,2)$ for some $\kk e\in {\rm AS}(m,2,p)$ . 

$\Rightarrow$: Supppose that $A,B$ are QS equivalent. Let $\kk s\in {\rm AS}(m,2,m)$ such that $A(s,2)=\kk[x_1,\ldots,x_m]$. By \Cref{ASSuper}, $\mathcal{GL}_m(s,e)\neq 0$. Hence, \Cref{SQSAS} implies that $A(s,2)$ and $A(e,2)$ are QS equivalent and,  so are $A(s,2)$ and $B$. Note that $A(s,2)$ is the noetherian polynomial algebra and $\mathcal{GL}_m(s)$ has a bijective antipode \cite[Corollary 5.27]{CWW2019}. Thus, we can conclude that $B$ is Koszul AS-regular of global dimension $m$, by \Cref{PQS}. 

$\Leftarrow$: Conversely, suppose that $B$ is Koszul AS-regular of global dimension $m$. Again by \Cref{NKAS}, we can write $B=A(f,2)$ with $\mathcal{GL}_m(e,f)\neq 0$ by \Cref{ASSuper}. Hence, $A$ and $B$ are QS equivalent, by \Cref{SQSAS}.

Now, assume that $A$ and $B$ are two Koszul AS-regular algebras of the same global dimension $m$. Without loss of generality, we can write $A=A(e,2)2$ and $B=A(f,2)$ for some $\kk e\in {\rm AS}(m,2,p)$ and $\kk f\in {\rm AS}(m,2,q)$. By \Cref{ASSuper}, $\mathcal{GL}_m(e,f)\neq 0$ and $F(-)=(-)\square_{\mathcal{GL}_m(e)}\mathcal{GL}_m(e,f)$ induces a $\GLQS$ equivalence between $A$ and $B$. By writing $A=TU_e/(R_e)$, one sees that there are comodules $M_A(r_i)$ over $\mathcal{GL}_m(e)$ where $M_A(r_1)=U_e$ and  $M_A(r_k)=\bigcap_{i+j+2=k} U_e^{\otimes i}\otimes R_e\otimes U_e^{\otimes j}$ for $2\leq k\leq  m$, where $M_A(r_m)$ is the invertible comodule given by the grouplike element $(D^{e,e})^{-1}$. We use the same notation $M_B(r_i)$ with $1 \leq i\leq m$ for the corresponding comodules over $\mathcal{GL}_m(f)$. Since $F$ sends $A$ to $B$ as comodule algebras, it follows that $F(M_A(r_i))=M_B(r_i)$, for all $1 \leq i\leq m$. We let $A'$ be a possible base field extension of $A$ and write $A'=A\otimes_\kk \overline{\kk}=A(e',2)$ and $B'=B\otimes_\kk \overline{\kk}=A(f',2)$, where $e'$ and $f'$ are the corresponding nondegenerate twisted superpotentials for $e,f$ after the base field extension. In particular, $M_{A'}(r_i)=M_A(r_i)\otimes_\kk \overline{\kk}$ and $M_{B'}(r_i)=M_B(r_i)\otimes_\kk \overline{\kk}$ become comodules over the corresponding universal quantum groups $\mathcal{GL}_m(e')=\mathcal{GL}_m(e)\otimes_\kk \overline{\kk}$ and $\mathcal{GL}_m(f')=\mathcal{GL}_m(f)\otimes_\kk \overline{\kk}$. Moreover, the $\mathcal{GL}_m(e')$-$\mathcal{GL}_m(f')$-bi-Galois object 
$\mathcal{GL}_m(e',f')=\mathcal{GL}_m(e,f)\otimes_\kk\overline{\kk}$ implies a  $\GLQS$ equivalence, and hence a QS equivalence by \Cref{SQSAS}, between $A'$ and $B'$.

If $A,B$ have the same Hilbert series, then we have 
\begin{equation}\label{eq:dimeq}
  \dim_{\overline{\kk}} M_{A'}(r_i)= \dim_\kk M_A(r_i)=\dim_\kk (A^!)_i=\dim_\kk (B^!)_i=\dim_\kk M_B(r_i) =\dim_{\overline{\kk}} M_{B'}(r_i)
\end{equation} 
for all $1\leq i\leq m$. Since $\mathcal{GL}_{m}(e')$ is the Manin's universal quantum group for $A'=A(e',2)$, by \cite[Corollary 15.43]{Manin2018}, we know that the Grothendieck ring of $\mathcal{GL}_m(e')$  is the free $\mathbb Z$-ring 
\[
\mathbb Z\langle M_{A'}(r_1),\ldots, M_{A'}(r_{m-1}), M_{A'}(r_m)^{\pm 1}\rangle,
\]
and the same is true for $\mathcal{GL}_m(f')$. Consequently, the monoidal equivalence 
\[F': {\rm comod}\left(\mathcal{GL}_m(e')\right)~\overset{\otimes}{\cong}~\comod\left(\mathcal{GL}_m(f')\right)\] induces a ring isomorphism $F'$ (by abuse of notation) between the Grothendieck rings of $\mathcal{GL}_m(e')$ and $\mathcal{GL}_m(f')$ by sending $M_{A'}(r_i)$ to $M_{B'}(r_i)$ for all $1\leq i\leq m$. For any finite-dimensional comodule $W$ over the original $\mathcal{GL}_m(e)$, we can consider $W'=W\otimes_\kk\overline{\kk}$ as an element in the Grothendieck ring of $\mathcal{GL}_m(e')$ and write it as a $\mathbb Z$-linear combination of some tensor products of the free generators  $M_{A'}(r_1),\ldots,M_{A'}(r_m)^{\pm 1}$. By applying $F'$, one can similarly write $F'(W')$ as the $\mathbb Z$-linear combination of the tensor products now in terms of $M_{B'}(r_1),\ldots,M_{B'}(r_m)^{\pm 1}$ in the Grothendieck ring of $\mathcal{GL}_m(f')$.  This implies that $\dim_\kk F(W)=\dim_{\overline{\kk}} F'(W')=\dim_{\overline{\kk}}W'=\dim_\kk W$ due to \eqref{eq:dimeq} and hence $F$ preserves dimensions. As a consequence, $\mathcal{GL}_m(f)$ is a 2-cocycle twist of $\mathcal{GL}_m(e)$ (see \cite[Theorems 1.8 and 1.17]{Bichon2014} and \cite[Proposition 4.2.2]{PavelGelaki2001}), where $F$ is naturally isomorphic to the monoidal equivalence given by the 2-cocycle twist. Since $F$ maps the comodule algebra $A$ over $\mathcal{GL}_m(e)$ to the comodule algebra $B$ over $\mathcal{GL}_m(f)$, we know $B$ is a 2-cocycle twist of $A$. Conversely, if $A$ and $B$ are 2-cocycle twists of each other, they share the same Hilbert series by construction.
\end{proof}



\begin{lemma}\label{isobi-Galois}
Let $e,e'\in U^{\otimes m}$ and $f,f'\in V^{\otimes m}$ be nondegenerate twisted superpotentials. Suppose there are $\phi \in \GL(U)$ and $\psi \in \GL(V)$ such that $\phi^{\otimes m}(\kk e)=\kk e'$ and $\psi^{\otimes m}(\kk f)=\kk f'$. Then $\mathcal{GL}_m(e,f)$ and $\mathcal{GL}_m(e',f')$ are isomorphic as $\kk$-algebras. In particular, $\mathcal{GL}_m(e,f)\cong \mathcal{GL}_m(e,f')$ as left $\mathcal{GL}_m(e)$-comodule algebras and $\mathcal{GL}_m(e,f)\cong \mathcal{GL}_m(e',f)$ as right $\mathcal{GL}_m(f)$-comodule algebras. 
\end{lemma}
\begin{proof}
Choose bases $\{u_1,\ldots,u_p\}$ for $U$ and $\{v_1,\ldots,v_q\}$ for $V$. Write $\phi(u_i)=\sum_{1\leq j\leq p} u_j\phi_{ji}$ and $\psi(v_i)=\sum_{1\leq j\leq q} v_j\psi_{ji}$ for invertible matrices $\phi=(\phi_{ij})\in \GL(U)$ and $\psi=(\psi_{ij})\in \GL(V)$. By our assumption, we also have $\phi^{\otimes m}(e)=\alpha e'$ and $\psi^{\otimes m}(f)=\beta f'$ for some nonzero scalars $\alpha,\beta$. According to \eqref{eq:alg}, we can check that the following map is an algebra isomorphism from $\mathcal{GL}_m(e,f)$ to $\mathcal{GL}_m(e',f')$:
\[
\mathbb A^{e,f}\mapsto \phi \mathbb A^{e',f'} \psi,\qquad \mathbb B^{e,f}\mapsto \psi^{-1}\mathbb B^{e',f'}\phi^{-1},\qquad (D^{e,f})^{\pm 1}\mapsto (D^{e',f'}/\alpha\beta)^{\pm 1}.
\]
For the last in particular statement, whenever, $e=e'$ or $f=f'$, we can choose either $\phi=\mathbb I_{p\times p}$ or $\psi=\mathbb I_{q\times q}$ and the above isomorphism becomes a left $\mathcal{GL}_m(e)$-comodule map or a right $\mathcal{GL}_m(f)$-comodule map.  
\end{proof}

We now reformulate the classification of Koszul AS-regular algebras in terms of the classification of fiber functors from the comodule categories over Manin's universal quantum groups of the polynomial algebras. 


\begin{thm}
\label{IsoAS}
For any integer $m \geq 2$, the following are in one-to-one correspondence with each other.
\begin{itemize}
    \item[(1)] Isomorphism classes of Koszul AS-regular algebras of global dimension $m$.
     \item[(2)] The set of left $\underline{\rm aut}^r(\kk[x_1,\ldots,x_m])$-Galois objects up to isomorphism.
    \item[(3)] The set of fiber functors from $\comod_{\fd}(\underline{\rm aut}^r(\kk[x_1,\ldots,x_m]))$ to ${\rm Vec}(\kk)$ up to natural isomorphism.     
      \item[(4)] Disjoint union of orbits $\bigsqcup_{q\ge 2} {\rm AS}(m,2,q)/\PGL_q(\kk)$, where ${\rm AS}(m,2,q)$ is defined in \eqref{ASclass}.
    \end{itemize}
\end{thm}
\begin{proof}
    (1) $\Leftrightarrow$ (4): Since Koszul AS-regular algebras are connected graded algebras that are finitely generated in degree one, we know that two of them are isomorphic as associative algebras if and only if they are isomorphic as graded algebras \cite[Theorem 1]{BZ2017}. Then by \Cref{NKAS}, it suffices to show two superpotential algebras $A(e,2)$ and $A(f,2)$ given by two nondegenerate twisted superpotentials $\kk e\in {\rm AS}(m,N,p)$ and $\kk f\in {\rm AS}(m,N,q)$ are isomorphic as graded algebras if and only if there is a linear isomorphism $\phi: U\cong V$ such that $\phi^{\otimes m}(\kk e)=\kk f$, which is well-known \cite[Theorem 2.11]{MU2019}.

    (2) $\Leftrightarrow$ (3): This follows from Ulbrich's theorem \cite{Ulbrich1987}, see also \cite[Theorem 1.14]{Bichon2014}.

(1),(4) $\Leftrightarrow$ (2),(3): Let $\kk s\in {\rm AS}(m,2,m)$ such that $A(s,2) \cong \kk[x_1,\ldots,x_m]$. By \Cref{SQSAS}, we have $\underline{\rm aut}^r(\kk[x_1,\ldots,x_m])\cong \mathcal{GL}_m(s)$. For every nondegenerate twisted superpotential $\kk f\in {\rm AS}(m,2,q)$, we know that $\mathcal{GL}_m(s,f)\neq 0$ yields a $\mathcal{GL}_m(s)$-$\mathcal{GL}_m(f)$-bi-Galois object by \Cref{ASSuper}. Hence, we obtain  a fiber functor from $\comod_{\fd}(\underline{\rm aut}^r(\kk[x_1,\ldots,x_m]))$ to ${\rm Vec}(\kk)$ by composing $(-)\square_{\mathcal{GL}_m(s)}\mathcal{GL}_m(s,f)$ with the forgetful functor $\comod_{\fd}(\mathcal{GL}_m(f))\to {\rm Vec}(\kk)$. Conversely, suppose $T$ is a left $\mathcal{GL}_m(s)$-Galois object. By \Cref{Schauenburg}, there is a unique Hopf algebra $K$ where $T$ becomes a $\mathcal{GL}_m(s)$-$K$-bi-Galois object such that $(-)\square_{\mathcal{GL}_m(s)}T$ induces a monoidal equivalence between $\comod(\mathcal{GL}_m(s))$ and $\comod(K)$. Denote by $B=A(s,2)\square_{\mathcal{GL}_m(s)}T$ the comodule algebra in $\comod(K)$, which is Koszul AS-regular of global dimension $m$ by \cite[Corollary 3.2.7 \& Theorem 3.2.10]{HNUVVW2024-2}. We write $B=A(f,2)$ for some nondegenerate twisted superpotential $\kk f\in {\rm AS}(m,2,q)$. Similar to the second part of the proof of \Cref{RQS}, we can show that $K\cong \underline{\rm aut}^r(A(s,2))\cong \mathcal{GL}_m(f)$. Therefore, we know $(-)\square_{\mathcal{GL}_m(s)}T$ induces an $\GLQS$ equivalence between $A(s,2)$ and $A(f,2)$. By \Cref{SQSBG}, we have $T\cong \mathcal{GL}_m(s,f)$ as $\mathcal{GL}_m(s)$-$\mathcal{GL}_m(f)$-bicomodule algebras. It remains to show that for two $f\in {\rm AS}(m,2,q)$ and $f'\in {\rm AS}(m,2,q')$, we have $\mathcal{GL}_m(s,f)$ and $\mathcal{GL}_m(s,f')$ are isomorphic as left $\mathcal{GL}_m(s)$-comodule algebras if and only if $A(f,2)$ and $A(f',2)$ are isomorphic as (graded) algebras. Denote by $F(-)=(-)\square_{\mathcal{GL}_m(s)}\mathcal{GL}_m(e,f)$ and $F'(-)=(-)\square_{\mathcal{GL}_m(s)}\mathcal{GL}_m(e,f')$ the corresponding fiber functors. One direction is clear since $F(A(s,2))=A(f,2)$ and $F'(A(s,2))=A(f',2)$ by \Cref{SQSMTE}. If $F\cong F'$ are isomorphic as monoidal functors, we must have $A(f,2)\cong A(f',2)$ as graded algebras. On the other hand, suppose $A(f,2)=TV/\partial^{m-2}(\kk f)\cong A(f',2)=TV'/\partial^{m-2}(\kk f')$ as graded algebras, we have an isomorphism $\phi: V\cong V'$ such that $\phi^{\otimes m}(\kk f)=\kk f'$. Then, $\mathcal{GL}_m(s,f)\cong \mathcal{GL}_m(s,f')$ as left $\mathcal{GL}_m(s)$-comodule algebras by \Cref{isobi-Galois}.
\end{proof}

The following result identifies the isomorphism classes of all Koszul AS-regular algebras that are deformations of polynomial algebras with left cleft Galois objects over Manin's universal quantum groups of the polynomial algebras. 

\begin{Cor}
For any integer $m \geq 2$, the following are in one-to-one correspondence with each other.
\begin{itemize}
    \item[(1)] Isomorphism classes of Koszul AS-regular algebras with Hilbert series $\frac{1}{(1-t)^m}$.
        \item[(2)] The set of left cleft $\underline{\rm aut}^r(\kk[x_1,\ldots,x_m])$-Galois objects up to isomorphism.
    \item[(3)] The set of fiber functors from $\comod_{\fd}(\underline{\rm aut}^r(\kk[x_1,\ldots,x_m]))$ to ${\rm Vec}(\kk)$ preserving vector space dimensions up to natural isomorphism. 
    \end{itemize}   
\end{Cor}


\begin{proof}
(2) $\Leftrightarrow$ (3) This is due to Etingof-Gelaki \cite{EG2001}, see also \cite[Theorem 1.17]{Bichon2014}.

(1) $\Leftrightarrow$ (2),(3) By the work of Doi-Takeuchi \cite{DT86} and Blattner-Montgomery \cite{BM1989}, we know that every cleft Galois object is given by some 2-cocycle, whose corresponding fiber functor sends comodule algebras to their 2-cocycle twists. Then the sub-correspondence follows from \Cref{AS2cocyle}.
\end{proof}

\begin{remark}
It is clear that any AS-regular algebra of Hilbert series $\frac{1}{(1-t)^m}$ is of the form $A(f,2)$ for some $f\in {\rm AS}(m,2,m)$. However,  it is an open question whether for any $f\in {\rm AS}(m,2,m)$, the corresponding AS-regular algebra $A(f,2)$ always has the Hilbert series $\frac{1}{(1-t)^m}$.
\end{remark}


