\subsection{Some invariants under $\SLQS$ equivalence}
\label{subsec:SLQS}

We can obtain similar results for $\mathcal{SL}_m$ regarding $\SLQS$ equivalence by slightly modifying the arguments for $\mathcal{GL}_m$.

\begin{thm}
\label{thm:SLQS}
Let $m \geq 2$ be any integer and $A(e,N)$ and $A(f,N)$ be two superpotential algebras for some nondegenerate twisted superpotentials $e\in U^{\otimes m}$ and $f\in V^{\otimes m}$, respectively. 
\begin{itemize}
    \item[(1)]If $\mathcal{SL}_m(e,f)\neq 0$, then $A(e,N)$ and $A(f,N)$ are $\SLQS$ equivalent. In particular, they are $\GLQS$ equivalent. 
    \item[(2)]If $A(e,N)$ and $A(f,N)$ are $\SLQS$ equivalent for some $L$-traceable $e,f$ with $2\leq L\leq N\leq m$, then $\mathcal{SL}_m(e,f)\neq 0$. 
\end{itemize} 
\end{thm}


\begin{proof}
    (1): Since $\mathcal{GL}(e,f)=\mathcal{SL}(e,f)/(D^{e,f}-1)$, $\mathcal{GL}(e,f)\neq 0$ provided $\mathcal{SL}(e,f)\neq 0$. Then (1) follows from an analogous proof of \Cref{SQSMTE} for both $\SLQS$ equivalence and $\GLQS$ equivalence conclusions. 

    (2): Suppose $A(e,N)$ and $A(f,N)$ are $\SLQS$ equivalent for some $L$-traceable $e,f$. We can apply a similar argument in \Cref{SQSBG} to conclude that  $\mathcal{SL}_m(e,f)\neq 0$.
\end{proof}

Recall that by \Cref{L:copi} the cogroupoid $\mathcal{SL}_m$ is copivotal such that 
for any nondegnerate twisted superpotential $e\in U^{\otimes m}$ with associated invertible matrix $\mathbb P$, the copivotal character $\Phi_e: \mathcal{SL}_m(e)\to \kk$ is given by $\Phi_e(\mathbb A^{e,e})=\mathbb P^T, \Phi_e(\mathbb B^{e,e})=\mathbb P^{-T}$. Moreover, for another nondegenerate twisted superpotential $f\in V^{\otimes m}$, we have $S_{f,e}\circ S_{e,f}=\Phi_e^{-1}* \id *\Phi_f$ with $\Phi_e^{-1}=\Phi_e\circ S_{e,e}$ denotes the convolution inverse of $\Phi_e$. Let $W\in \comod_{\fd}(\mathcal{SL}_m(e))$. Choose a basis $\{w_1,\ldots,w_r\}$ for $W$ and write the $\mathcal{SL}_m(e)$-comodule structure map on $W$ as $\rho_W(w_i)=\sum_j w_j\otimes h_{ji}$ for some $h_{ji}\in \mathcal{SL}_m(e)$. 

\begin{lemma}[{\cite[Proposition 2.9]{Bichon2001}}]
Retain the above notation. For any $W\in \comod_{\fd}(\mathcal{SL}_m(e))$, there is a natural isomorphism $j_W: W\to W^{**}$ given by 
\begin{align}
\label{jW}
j_W(w_i)~=~(\id \otimes \Phi_e^{-1})(\rho(w_i))~=~\sum_j w_j\,\Phi_e^{-1}(h_{ji}).
\end{align}
\end{lemma}


Moreover, one can extend $j: \id\to (-)^{**}$ to a monoidal isomorphism and is said to be a \emph{pivotal structure} on $\comod_{\fd}(\mathcal{SL}_m(e))$. Using this pivotal structure on $\comod_{\fd}(\mathcal{SL}_m(e))$, we recollect the following notions (see e.g., \cite[Section 4.7]{EGNO2015}), which are shown to be invariant given the non-vanishing of $\mathcal{SL}_m(e,f)$, see \Cref{prop:SameH} and \Cref{equivm2}.
\begin{defn}
\label{defn:qdim}
Suppose $e\in U^{\otimes m}$ is a nondegenerate twisted superpotential. Let $W\in \comod_{\fd}(\mathcal{SL}_m(e))$.
\begin{itemize}
    \item[(1)] The \emph{quantum dimension} of $W$ is defined to be 
    \[d_e(W) \coloneqq \left (\kk\xrightarrow{\rm coev} W\otimes W^*\xrightarrow{j_W\otimes \id} W^{**}\otimes W^*\xrightarrow{\rm ev} \kk\right).\]
    \item[(2)] The quantum group $\mathcal{SL}_m(e)$ is  \emph{cospherical} if $d_e(W)=d_e(W^*)$ for any $W\in \comod_{\fd}(\mathcal{SL}_m(e))$.
    \item[(3)] The \emph{quantum Hilbert series} of the superpotential algebra $A(e,N)=\bigoplus_{i\ge 0}A_i$ is defined to be 
\[q_{A(e,N)}(t) \coloneqq \sum_{i\ge 0} d_e(A_i)\,t^i.\]
\end{itemize}
\end{defn}

For the superpotential algebra $A(e,N)=TU/\partial^{m-N}(\kk e)$, we define 
\[
W_i \coloneqq \begin{cases}
    U^{\otimes i}, &  0\leq i\leq N-1\\
    \bigcap_{s+t=i-N} U^{\otimes s}\otimes \partial^{m-N}(\kk e) \otimes U^{\otimes t}\subseteq U^{\otimes i}, & i\ge N,
\end{cases}
\]
for any $i\ge 0$ and set the integers  
\[
\rho(i) \coloneqq 
\begin{cases}
    jN, & i=2j\\
    jN+1,  & i=2j+1.
\end{cases}
\]
Suppose $A(e,N)$ is $N$-Koszul AS-regular. By \cite[Theorem 2.4]{BM2006} (also see \cite[Theorem 2.8]{MS2016}), we have the minimal graded free resolution of the trivial $A(e,N)$-module $\kk$:
\begin{align}
\label{resolution}
     0\to A(e,N)\otimes W_{\rho(d)}[-\rho(d)]\to \cdots \to A(e,N)\otimes W_{\rho(1)}[-\rho(1)]\to A(e,N)\to \kk,
\end{align}
where $d=2(m-1)/N+1$ is the global dimension of $A(e,N)$. 

\begin{lemma}\label{Le:qd}
  Retain the above notation. Suppose $A(e,N)$ is $N$-Koszul AS-regular of dimension $d$.
  \begin{itemize}
      \item[(1)] The quantum Hilbert series of $A(e,N)$ is 
  \[
  q_{A(e,N)}(t)~=~\frac{1}{\sum\limits_{0\leq i\leq d} (-1)^i\,d_e(W_{\rho(i)})\, t^{\rho(i)}}.
  \]
  \end{itemize}
  Further, assume $A(e,N)$ is Calabi--Yau of dimension $d$, we have:
  \begin{itemize}
      \item[(2)] $d_e(W)=(-1)^{d+1}\dim W$ for any $W\in \comod_{\fd}(\mathcal{SL}_m(e))$ and $\mathcal{SL}_m(e)$ is cospherical; and
\item[(3)] $q_{A(e,N)}(t)=(-1)^{d+1}h_{A(e,N)}(t)$ where $h_{A(e,N)}(t)$ is the Hilbert series of $A(e,N)$. 
  \end{itemize} 
\end{lemma}
\begin{proof}
(1): Since the quantum dimension $d_e$ is additive on exact sequences \cite[Proposition 4.7.5]{EGNO2015}, we can derive the quantum Hilbert series of $A(e,N)$ similar to that of the usual Hilbert series from \eqref{resolution}.


(2)\&(3): When $A(e,N)$ is CY of dimension $d$, \Cref{NKAS} says that $\mathbb P=(-1)^{d+1}\mathbb I$, where $\mathbb P$ is the invertible matrix associated to $e$. Then \Cref{L:copi} implies that the character $\Phi_e$ is given by $\Phi_e(\mathbb A)=(-1)^{d+1}\mathbb I$ and $\Phi_e(\mathbb B)=(-1)^{d+1}\mathbb I$. Thus $\Phi_e^{-1}=\Phi_e=(-1)^{d+1}\varepsilon$. So by \eqref{jW}, we get 
  \begin{align*}
    d_e(W)&\,=\sum_{i} \langle j_W(w_i),w^i\rangle= \sum_{i} \langle \sum_jw_j\Phi_e^{-1}(h_{ji}),w^i\rangle=(-1)^{d+1}\sum_i \langle w_j\varepsilon(h_{ji}),w^i\rangle\\
    &\,=(-1)^{d+1}\sum_i\langle w_i,w^i\rangle=(-1)^{d+1}\dim W.
  \end{align*}
Thus, (2) holds, and (2) clearly implies (3). 
\end{proof}





\begin{proposition}
\label{prop:SameH}
     If $\mathcal{SL}_m(e,f)\neq 0$, then $q_{A(e,N)}(t)=q_{A(f,N)}(t)$.
\end{proposition}

\begin{proof}
By \Cref{thm:SLQS}, there is a monoidal equivalence
\begin{align*}
(F,\xi): \comod(\mathcal{SL}_m(e))~\overset{\otimes}{\cong}~ \comod(\mathcal{SL}_m(f)),
\end{align*} 
sending $A(e,N)$ to $A(f,N)$ as comodule algebras. We show that $F$ preserves the copivotal structures (cf. \cite[\S 1]{Ng-Schauenburg}), that is, the diagram
\begin{align}\label{pivS}
\xymatrix{
F(W)\ar[d]_-{j_{F(W)}}\ar[rr]^-{F(j_W)} && F(W^{**})\ar[d]^-{\widetilde{\xi}}\\
F(W)^{**}\ar[rr]^-{\widetilde{\xi}^*} && F(W^*)^*
}
\end{align}
commutes for any $W\in \comod_{\fd}(\mathcal{SL}_m(e))$, where the natural isomorphism $j_W: W\to W^{**}$ is given in \eqref{jW}, and $\widetilde{\xi}$ is defined in \eqref{xitilde}. We write $F(-)=(-)\sq_{\mathcal{SL}(e)}\mathcal{SL}_m(e,f)$. Fix a basis $\{w_1,\ldots,w_r\}$ for $W$ and write $\rho(w_i)=\sum_j w_j\otimes h_{ji}^{e,e}$ for $(h_{ji}^{e,e})_{1\leq j,i\leq r}\in \mathcal{SL}_m(e)$ satisfying $\Delta_{e,e}^e(h_{ji}^{e,e})=\sum_k h_{jk}^{e,e}\otimes h_{ki}^{e,e}$. Denote $M=F(W)\in \comod_{\fd}(\mathcal{SL}_m(f))$. Similarly, fix basis $\{m_1,\ldots,m_t\}$ for $M$ and write $\rho(m_i)=\sum_j m_j\otimes h_{ji}^{f,f}$ for $(h_{ji}^{f,f})_{1\leq j,i\leq t}\in \mathcal{SL}_m(f)$ satisfying $\Delta_{f,f}^f(h_{ji}^{f,f})=\sum_k h_{jk}^{f,f}\otimes h_{ki}^{f,f}$. Thus, we can write $m_i=\sum_j w_j\otimes h_{ji}^{e,f}\in W\sq_{\mathcal{SL}_m(e)}\mathcal{SL}_m(e,f)$ for some $(h_{ji}^{e,f})_{1\leq j\leq r, 1\leq i\leq t}\in \mathcal{SL}_m(e,f)$ satisfying $\Delta_{e,f}^e(h_{ji}^{e,f})=\sum_k h_{jk}^{e,e}\otimes h_{ki}^{e,f}$ and $\Delta_{e,f}^f(h_{ji}^{e,f})=\sum_k h_{jk}^{e,f}\otimes h_{ki}^{f,f}$.  We write $\{w^1,\ldots,w^r\}$ and $\{m^1,\ldots,m^t\}$ for the dual bases for the left duals of $W$ and $M$ in $\comod_{\fd}(\mathcal{SL}_m(e))$ and in $\comod_{\fd}(\mathcal{SL}_m(f))$, respectively. It is clear to check that $\rho(w^i)=\sum_j w^j\otimes S_{e,e}(h_{ij}^{e,e})$ and $\rho(m^i)=\sum_j m^j\otimes S_{f,f}(h_{ij}^{f,f})$. Similarly, we have $(h_{ij}^{f,e})_{1\leq i\leq t,1\leq j\leq r}\in \mathcal{SL}_m(f,e)$ such that $\sum_j w^j\otimes S_{f,e}(h^{f,e}_{ij})\in W^*\sq_{\mathcal{SL}_m(e)}\mathcal{SL}_m(e,f)$ forms a basis for $F(W^*)$ for $1\leq i\leq t$. 


Before showing \eqref{pivS} commutes, we derive an explicit formula for $\widetilde{\xi}: F(W^*)\cong F(W)^*$ at the basis level. 
Set a $\kk$-linear map $\xi': F(W^*)\to F(W)^*$ via $\sum_{1 \leq j \leq r} w^j\otimes S_{f,e}(h^{f,e}_{ij})\mapsto m^i$ for any $1\leq i\leq t$. We claim the following diagram commutes
\[\small
\xymatrix{
F(W^*)\otimes F(W)\ar[ddd]_-{\xi}\ar[rrr]^-{\xi'\otimes \id }\ar@{=}[dr]&&&F(W)^*\otimes F(W)\ar@{=}[dl]\ar[ddd]^-{{\rm ev}}\\
&(W^*\sq_{\mathcal{SL}_m(e)} \mathcal{SL}_m(e,f))\otimes(W\sq_{\mathcal{SL}_m(e)} \mathcal{SL}_m(e,f))\ar[r]^-{\xi'\otimes \id}\ar[d]_-{\xi} &M^*\otimes M\ar[d]^-{{\rm ev}}&\\
&(W^*\otimes W)\sq_{\mathcal{SL}_m(e)} \mathcal{SL}_m(e,f)\ar[r]^-{{\rm ev}\sq_{\mathcal{SL}_m(e)}\mathcal{SL}_m(e,f)}&\kk &\\
F(W^*\otimes W)\ar@{=}[ur]\ar[rrr]^-{F({\rm ev})}&&& \kk. \ar@{=}[ul]
}
\]
In detail, the left column and bottom row of the inner rectangle yield that, 
\begin{align*}
    F({\rm ev})\xi \left( \left (\sum_k w^k\otimes S_{f,e}(h_{ik}^{f,e}) \right) \otimes \left (\sum_l w_l \otimes h_{lj}^{e,f} \right )\right)&\,=F({\rm ev})\left(\sum_{k,l} (w^k\otimes w_l) \otimes S_{f,e}(h_{ik}^{f,e})h_{lj}^{e,f}\right)\\
    &=\, \sum_{k,l} \langle w^k,w_l\rangle S_{f,e}(h_{ik}^{f,e})h_{lj}^{e,f}\\
    &=\, \sum_k S_{f,e}(h_{ik}^{f,e})h_{kj}^{e,f}=\varepsilon_f(h_{ij}^{f,f})=\delta_{ij}.
\end{align*}
Meanwhile, the top row and right column of the inner rectangle yield that
\begin{align*}
    \left\langle \xi' \left (\sum_k w^k\otimes S_{f,e}(h_{ik}^{f,e}) \right), \sum_l w_l \otimes h_{lj}^{e,f}\right\rangle=\langle m^i,m_j\rangle=\delta_{ij}.
\end{align*}
This proves our claim.  By the definition of the duality transformation \eqref{xitilde}, we observe that $\widetilde{\xi}: F(W^*)\to F(W)^*$ is the unique map that makes the above diagram commute. Hence, $\widetilde{\xi}$ and $\xi'$ coincide and we have $\widetilde{\xi}(\sum_j w^j\otimes S_{f,e}(h^{f,e}_{ij}))=m^i$ for any $1\leq i\leq t$.

Thus, tracing along the left column and bottom row of the above diagram \eqref{pivS}, we have
\begin{align*}
  \left \langle \widetilde{\xi}^*j_{F(W)}(m_i), \sum_l w^l\otimes S_{f,e}(h_{jl}^{f,e})\right\rangle&\,=\left\langle \sum_k m_k\Phi_{f}^{-1}(h_{ki}^{f,f}), \widetilde{\xi}\left(\sum_l w^l\otimes S_{f,e}(h_{jl}^{f,e})\right )\right\rangle \\
  &\,= \left \langle \sum_k m_k\Phi_{f}^{-1}(h_{ki}^{f,f}), m^j \right\rangle=\sum_k\Phi_f^{-1}(h_{ki}^{f,f})\langle m_k,m^j\rangle\\
  &\,=\Phi_f^{-1}(h_{ji}^{f,f}).
\end{align*}
While tracing along the top row and right column of the above diagram \eqref{pivS}, we have
\begin{align*}
&\left\langle \widetilde{\xi}F(j_W)\left (\sum_k w_k\otimes h_{ki}^{e,f}\right), \sum _lw^l\otimes S_{f,e}(h_{jl}^{f,e})\right\rangle \\ 
&\qquad = \left\langle \widetilde{\xi}\left(\sum_{k,s} w_s\otimes \Phi_e^{-1}(h_{sk}^{e,e})h_{ki}^{e,f}\right), \sum _lw^l\otimes S_{f,e}(h_{jl}^{f,e})\right\rangle\\
&\qquad = \left\langle \widetilde{\xi}\left (\sum_{s} w_s\otimes (\Phi_e^{-1}*\id)(h_{si}^{e,f})\right), \sum _lw^l\otimes S_{f,e}(h_{jl}^{f,e})\right\rangle\\
&\qquad = \left\langle \widetilde{\xi}\left (\sum_{s} w_s\otimes (S_{f,e}S_{e,f}*\Phi_f^{-1})(h_{si}^{e,f})\right ), \sum _lw^l\otimes S_{f,e}(h_{jl}^{f,e})\right\rangle\\
&\qquad = \left\langle \widetilde{\xi}\left (\sum_{k,s} w_s\otimes S_{f,e}S_{e,f}(h_{sk}^{e,f})\Phi_f^{-1}(h_{ki}^{f,f}) \right), \sum _lw^l\otimes S_{f,e}(h_{jl}^{f,e})\right\rangle\\
&\qquad = \sum_{k,s,l}\langle w_s,w^l\rangle S_{f,e}S_{e,f}(h_{sk}^{e,f}))\Phi_f^{-1}(h_{ki}^{f,f})S_{f,e}(h_{jl}^{f,e})\\
&\qquad = \sum_{k,s,l}\langle w_s,w^l\rangle S_{f,e}(h_{jl}^{f,e}S_{e,f}(h_{sk}^{e,f}))\Phi_f^{-1}(h_{ki}^{f,f})\\
&\qquad = \sum_{k}S_{f,e} \left (\sum_s h_{js}^{f,e} S_{e,f}(h_{sk}^{e,f})\right)\Phi_f^{-1}(h_{ki}^{f,f})\\
&\qquad = \sum_{k}S_{f,e}(\varepsilon_{f}(h_{jk}^{f,f}))\Phi_f^{-1}(h_{ki}^{f,f}) \\
&\qquad = \Phi_f^{-1}(h_{ji}^{f,f}).
\end{align*}
This shows that $F$ preserves the copivotal structures. As a consequence, $F$ preserves quantum dimensions, that is, $d_e(W)=d_f(F(W))$ for any $W\in \comod_{\fd}(\mathcal{SL}_m(e))$ (see \cite[Lemma 6.1]{Ng-Schauenburg}). Hence, 
\[q_{A(e,N)}(t)=\sum_{i\ge 0} d_e(A(e,N)_i)\,t^i=\sum_{i\ge 0} d_f(F(A(e,N)_i))\,t^i=\sum_{i\ge 0} d_f(A(f,N)_i)\,t^i=q_{A(f,N)}(t).
\]
\end{proof}

\begin{remark}
 Let $\mathcal C$ be any connected copivotal cogroupoid. For any objects $X,Y\in \mathcal C$, one can similarly show that the monoidal equivalence 
 \[
 F(-)=(-)\sq_{\mathcal C(X,X)}\mathcal C(X,Y): \comod_{\fd}(\mathcal C(X,X))~\overset{\otimes}{\cong}~ \comod_{\fd}(\mathcal C(Y,Y))
 \]
 preserves pivotal structures, that is, the diagram
 \begin{align*}
\xymatrix{
F(W)\ar[d]_-{j_{F(W)}}\ar[rr]^-{F(j_W)} && F(W^{**})\ar[d]^-{\widetilde{\xi}}\\
F(W)^{**}\ar[rr]^-{\widetilde{\xi}^*} && F(W^*)^*
}
\end{align*}
commutes for any $W\in \comod_{\fd}(\mathcal C(X,X))$. The pivotal structures on $\comod_{\fd}(\mathcal C(X,X))$ and $\comod_{\fd}(\mathcal C(Y,Y))$ are given by their characters $\Phi_X,\Phi_Y$  as in \eqref{jW}, respectively.

As an application, in \cite{Ng-Schauenburg,NgSchauenburg2010}, higher (generalized) Frobenius--Schur indicators are defined for any $\kk$-linear $\Hom$-finite monoidal category with pivotal structure $j: \Id \to (-)^{**}$. Our result together with \cite[Corollary 4.4]{Ng-Schauenburg} (\cite[Remark 2.2]{NgSchauenburg2010}) shows that the values of those indicators in $\comod_{\fd}(\mathcal{C}(X,X))$ and $\comod_{\fd}(\mathcal{C}(Y,Y))$ are preserved under the monoidal equivalence $F$.   
\end{remark}

We wonder if the converse of the above result holds. We provide evidence for the case when $N=m=2$ and emphasize that $\GLQS$ equivalence generally does not imply $\SLQS$ equivalence. 


\begin{proposition}
\label{equivm2}
For any nondegenerate twisted superpotentials $e\in U^{\otimes 2}$ and $f \in V^{\otimes 2}$, the following are equivalent.
    \begin{itemize}
        \item[(1)] $A(e,2)=TU_e/(\kk e)$ and $A(f,2)=TV_f/(\kk f)$ are $\SLQS$ equivalent;
        \item[(2)] $\mathcal{SL}_2(e,f)\neq 0$;
        \item[(3)] $d_e(U_e)=d_f(V_f)$;
        \item[(4)] $q_{A(e,2)}(t)=q_{A(f,2)}(t)$.
           \end{itemize}
\end{proposition}
\begin{proof}
There is a straightforward presentation of the cogroupoid $\mathcal{SL}_2$. Let $e\in U^{\otimes 2}$ and write $\mathbb E=(e_{ij})\in M_p(\kk)$ with $p=\dim U$. One can check directly that $(e,\mathbb P)$ is a nondegenerate twisted superpotential if and only if $\mathbb E$ is invertible or $\mathbb E\in \GL_p(\kk)$ with $\mathbb P=\mathbb E^T\mathbb E^{-1}$. The same holds for $f \in V^{\otimes 2}$ with $q=\dim V$. So for two nondegenerate superpotentials $e\in U^{\otimes 2}$ and $f\in V^{\otimes 2}$, write $\mathbb E\in \GL(U)$ and $\mathbb F\in \GL(V)$ for their corresponding invertible matrices. We can represent $\mathcal{SL}_2(e,f)$ with generating space $\mathbb A=(a_{ij})_{1\leq i\leq p,1\leq j\leq q}$ subject to relations 
\[
\mathbb A \mathbb F\mathbb A^T\mathbb E^{-1}=\mathbb I_{p\times p}\quad \text{and}\quad \mathbb F \mathbb A^T\mathbb E^{-1}\mathbb A=\mathbb I_{q\times q}
\]
with $\mathbb B$ implicitly given by $\mathbb F\mathbb A^T\mathbb E^{-1}$. Moreover, for any vector spaces $U,V,W$ and any nondegenerate twisted superpotentials $e\in U^{\otimes 2}$, $f\in V^{\otimes 2}$ and $g\in W^{\otimes 2}$, we have algebra maps
\[\Delta_{e,g}^f: \mathcal{SL}_2(e,f)\to \mathcal{SL}_2(f,g)\otimes \mathcal{SL}_2(g,f),\qquad  \varepsilon_e: \mathcal{SL}_2(e,e)\to \kk,\qquad  S_{e,f}: \mathcal{SL}_2(e,f)\to \mathcal{SL}_2(e,f)^{\op},\]
such that 
\begin{gather*}
\Delta_{e,f}^g(a_{ij}^{e,g})=\sum_{k=1}^q a^{e,f}_{ik}\otimes a^{f,g}_{kj},\qquad \varepsilon_{e}(a_{ij}^{e,e})=\delta_{ij},\qquad S_{e,f}\left(\mathbb A^{e,f}\right)=\mathbb E\mathbb A^{f,e}\mathbb F^{-1}
\end{gather*} 
for all possible $i,j$. Then it is straightforard to check that our cogroupoid $\mathcal {SL}_2$ is essentially the same as the cogroupoid $\mathcal B$ constructed in \cite[Definition 3.3]{Bichon2014} with $\mathcal{SL}_2(e,f)=\mathcal B(\mathbb E^{-1},\mathbb F^{-1})$. 

(1) $\Leftrightarrow$ (2): By \cite{Zhang1998}, we know $A(e,2)$ is Koszul AS-regular of dimension two as long as $\mathbb E$ is invertible. Then the equivalence follows from \Cref{thm:SLQS}.

(2) $\Leftrightarrow$ (3): Since $\mathbb P=\mathbb E^T\mathbb E^{-1}$, the character $\Phi_e: \mathcal{SL}_2(e)\to \kk$ is given by $\Phi_e(\mathbb A)=\mathbb P^T=\mathbb E^{-T} \mathbb E$ and $\Phi_e(\mathbb B)=\mathbb P^{-T}=\mathbb E^{-1}\mathbb E^T$. Thus, 
  \begin{align*}
    d_e(U_e)&\,=\sum_{i} \langle j_{U_e}(u_i),u^i\rangle= \sum_{i} \left \langle \sum_ju_j\Phi_e^{-1}(a_{ji}),u^i \right\rangle=\sum_{i,j} \langle u_j\Phi_e(S_{e,e}(a_{ji})),u^i\rangle\\
    &\,=\sum_{i,j} \langle u_j\Phi_e(b_{ji}),u^i\rangle=\sum_{i,j} P^{-T}_{ji}\langle u_j\mathbb ,u^i\rangle=\sum_{i} P^{-T}_{ii}={\rm tr}(\mathbb P^{-1})={\rm tr}(\mathbb E\mathbb E^{-T})={\rm tr}(\mathbb E^{-1}\mathbb E^T).
  \end{align*}
A consequence of \cite[Lemma 3.4]{Bichon2014} shows that $\mathcal{SL}_2(e,f)\neq 0$ if and only if ${\rm tr}(\mathbb E^{-1}\mathbb E^T)={\rm tr}(\mathbb F^{-1}\mathbb F^T)$, and hence if and only if $d_e(U_e)=d_f(V_f)$.


(3) $\Leftrightarrow$ (4): By \Cref{Le:qd}, we get $q_{A(e,2)}(t)=\frac{1}{1-d_e(U_e)t+t^2}$ and $q_{A(f,2)}(t)=\frac{1}{1-d_f(V_f)t+t^2}$. Thus, $q_{A(e,2)}(t)=q_{A(f,2)}(t)$ if and only if $d_e(U_e)=d_f(V_f)$.
\end{proof}



