\title{Defining and classifying models of groups: The social ontology of higher-order networks}

\author[1]{Jonathan St-Onge}
\author[2]{Randall Harp}
\author[1]{Giulio Burgio}
\author[4]{Timothy M. Waring}
\author[1,3]{Juniper Lovato}
