\section{Appendix}

\subsection{Critical lines and points}\label{critical lines}
To find out those points, we need to set the ground state energy to zero, which is possible only if $\chi_y(k)$ and $\chi_z(k)$ shown in Eq.~\ref{spectra} are both simultaneously zero. $\chi_y(k)$ will be zero for $k=0, \pm \pi$ and $k=\cos^{-1}\bigg(\dfrac{-\lambda_1}{2\lambda_2}\bigg)$. If for these points $\chi_z(k)$ is also equal to zero, then these k-points will be phase transition points. 
\begin{itemize}
    \item For $k=0$, $\chi_z(k) = -2\lambda_1 - 2\lambda_2 + 2\mu$. This implies that gap closing points ($\chi_z(k)=0$) will be for $\lambda_1 + \lambda_2 = \mu$ line. See Fig.~\ref{phase}($C_2$)

    \item For $k=\pm \pi$, $\chi_z(k) = 2\lambda_1 - 2\lambda_2 + 2\mu$. This implies that gap closing points ($\chi_z(k)=0$) will be for $\lambda_2 - \lambda_1 = \mu$ line. See Fig.~\ref{phase}($C_1$)

    \item For $k=\cos^{-1}\bigg(\dfrac{-\lambda_1}{2\lambda_2}\bigg)$, $\chi_z(k)=2\lambda_2 + 2\mu$. This implies that gap closing points ($\chi_z(k)=0$) will be for $\lambda_2 + \mu = 0$ line but $\lambda_1\leq 2\lambda_2$ to make argument of cosine less than one. See Fig.~\ref{phase}($C_3$)

    \item Multi critical point $M_1$ will have zeros for $k=0, \pm \pi$ but $M_2$ will be zero only for $k=0$ since $k$ value for zero energy change for critical line $C_3$ with $\lambda_1$ and $\lambda_2$. See Fig.~\ref{phase}
\end{itemize}
\subsection{Majorana basis transformation}
To convert the equation  
\begin{equation}\label{appendix_H_fermionic}
\begin{split}
     H=&-\mu \sum_{j=1}^N (1-2c_j^{\dagger}c_j) -\lambda_1\sum_{j=1}^{N-1}(c_{j}^{\dagger}c_{j+1} + c_{j}^{\dagger}c_{j+1}^{\dagger} + c_{j+1}^{\dagger}c_{j} + c_{j+1}c_{j})\\ &- \lambda_2\sum_{j=2}^{N-1}(c_{j-1}^{\dagger}c_{j+1} + c_{j+1}^{\dagger}c_{j-1}^{\dagger} + c_{j+1}^{\dagger}c_{j-1} + c_{j-1}c_{j+1})
\end{split}
\end{equation}
into the Majorana basis, we use the normalised conversion such that the eigenvalues exactly match in both bases
 $a_i = \dfrac{c_i + c_i^{\dagger}}{\sqrt{2}}$, 
 $b_i= \dfrac{-i(c_i^{\dagger} - c_i)}{\sqrt{2}}$,
Such that
    $a_j^2 = b_j^2 = \frac{1}{2}$, $\{a_i, b_j\} = 0$, and
    $\{a_i, a_j\} = \{b_i, b_j\} = \delta_{i, j}$.

We can write after the inverse transformation
    $c_i = \frac{1}{\sqrt{2}}(a_i - ib_i)$
    $c_i^{\dagger} = \frac{1}{\sqrt{2}}(a_i + ib_i)$.

In both bases, the constant terms are not removed from the Hamiltonian; rather, they are automatically absorbed. The $\mu$ term 
\begin{equation*}
  H=  -\mu \sum_{j=1}^N (1-2c_j^{\dagger}c_j)=-\mu \sum_{j=1}^N (c_jc_j^{\dagger}-c_j^{\dagger}c_j)=-\mu \sum_{j=1}^N ((a_j-ib_j)(a_j+ib_j)-(a_j+ib_j)(a_j-ib_j)
\end{equation*}
After changing the bases
\begin{equation*}
  H=  -\frac{\mu}{2} \sum_{j=1}^N ((a_j-ib_j)(a_j+ib_j)-(a_j+ib_j)(a_j-ib_j)) = -i\mu \sum_{j=1}^{N}(a_jb_j-b_j a_j) 
\end{equation*}
For the other two terms, substituting in Eq.~\ref{appendix_H_fermionic} and using the anti-commutation properties, terms like $a_ia_j$ and $a_ja_i$ cancel out, the same applies for $b_i b_j$ and $b_j b_i$ as well.
\begin{align*}
     H &= -i\mu \sum_{j=1}^{N}(a_jb_j-b_j a_j) - i\lambda_1\sum_{j = 1}^{N-1}(b_j a_{j+1} - a_{j+1}b_j) - i\lambda_2\sum_{j=2}^{N-1}( b_{j-1}a_{j+1} - a_{j+1}b_{j-1}) \\   
     H &= -2i\left[ -\mu\sum_{j=1}^N  b_j a_j +  \lambda_1 \sum_{j=1}^{N-1} b_j a_{j+1} +  \lambda_2\sum_{j=2}^{N-1}b_{j-1}a_{j+1}\right]
\end{align*}

\subsection{Recursion relation and its solution}

\begin{align*}
H = -i
\left(
\begin{array}{cccccc}
0 & \mu & 0 & \cdots &  &  \\
-\mu & 0 & \lambda_1 & 0 & \lambda_2 & \cdots \\
0 & -\lambda_1 & 0 & \mu & 0 & \cdots \\
0 & 0 & -\mu & 0 & \lambda_1 & 0 \\
\vdots &  & \vdots &  & \ddots & \ddots \\
\end{array}
\right).
\label{eq:matrix17}
\end{align*}
If the general eigenvector has the form $\psi=(A_1, A_1^{'}, A_2, A_2^{'}, \cdot\cdot\cdot,A_N,A_N^{'})^T$ then the eiegnvalue equation will be $H\psi=E\psi$ and that will lead to two equations, one from odd rows and other from even
\begin{subequations}
    \begin{align}
    -\mu A_j + \lambda_1A_{j+1} + \lambda_2A_{j+2} = & iE A_{j}^{'} \\
    \mu A_{j}^{'} - \lambda_1A_{j-1}^{'} - \lambda_2A_{j-2}^{'} = &  iE A_{j}
    \end{align}
\end{subequations}
The first equation will have terms like $A_{N+1}$ and $A_{N+2}$ for $j=N$ but those sites are not present inn the chain so $A_{N+1}=0=A_{N+2}$. Similarly, the second equation will have absent sites terms from chain like $A_{-1}$ and $A_{-2}$, so $A_{-1}=0=A_{-2}$. 


\subsection{Number of zero modes}\label{w}
Let us assume $\lambda_1$ and $\mu$ are positive.
\begin{itemize}
    \item Region $G_1$: $\lambda_2>\mu+\lambda_1$. In this case both $|q_{\pm}|<1$, two normalisable modes.

    \item Line $C_1$: $\lambda_2=\mu+\lambda_1$. then $q_+=\dfrac{\mu}{\mu+\lambda_1}$ and $q_-=-1$, only one normalisable mode.

    \item Region $G_4$: $\mu-\lambda_1<\lambda_2<\mu+\lambda_1$. Here, $|q_+|<1$ but $|q_-|>1$, only one normalisable mode.

    \item Point $M_1$: $\lambda_1=0$ and $\lambda_2=\mu$, $q_\pm=\dfrac{|\mu|}{\mu}$. So both $|q_\pm|=1$,  no normalisable modes.

    \item Region $G_2$: $\lambda_2<\mu-\lambda_1$ but greater than $-\mu$. Both $|q_\pm|>1$, no normalisable modes.

    \item Line $C_2$: $\lambda_2=\mu-\lambda_1$, Here, there are three cases: (a) If $\lambda_1<2\mu$ then $|q_+|=1$ and $|q_-|>1$, no normalisable mode. (b) If $\lambda_1>2\mu$ then $|q_+|<1$ and $|q_-|=1$, one normalisable mode (c) If $\lambda_1=2\mu$ which is Point $M_2$, then both $|q_\pm|=1$, no normalisable mode. 

    \item Line $C_3$: $\lambda_2=-\mu$. Here there are two cases: (a) If $\lambda_1<2\mu$ then the term within the square root becomes negative, so $q_\pm$ become complex, but their modulus will always be one, no normalizable mode; (b) If $\lambda_1>2\mu$ then $q_\pm$ will remain real but only $|q_+|$ will be less than one so only one normalizable mode.

    \item Region $G_3$: $\lambda_2<\mu-\lambda_1$ but less than $-\mu$. Here, both $|q_\pm| < 1$, so there are two normalizable modes. 

    \item Dashed curve in Fig.~\ref{phase} shows the parameters for $q_+=q_-$. Both $q$ below the dashed curve will be complex but distinct with $|q_+|=|q_-|$. Above the curve will have real $q$.
\end{itemize}

\subsection{\texorpdfstring{General solution for $w=2$}{}}\label{w2generalsolution}
The recursion relation will have two normalizable roots in the $w=2$ regions. The general solution of amplitude at the $j$-th site can be written in terms of arbitrary coefficients as
\begin{equation*}
    A_j=c_1q_+^j + c_2q_-^j
\end{equation*}
This equation can be converted into two physically realizable terms: $ A_1 = c_1q_+ + c_2q _-$ and $ A_2 = c_2q _ +^2 + c_2q _ -^2$. After solving $c_1=\dfrac{A_1q_- - A_2}{q_+(q_- - q_+)}$ and $c_2=\dfrac{A_1q_+-A_2}{q_-(q_+-q_-)}$ in terms of $A_1$ and $A_2$, the general solution will be
\begin{equation*}
    A_j=\frac{1}{q_+ - q_-}\big[A_1(q_+q_-^{j-1}-q_-q_+^{j-1}) + A_2(q_+^{j-1}-q_-^{j-1})\big]
\end{equation*}

\subsection{\texorpdfstring{General solution in the region $G_3$ }{}}

\subsubsection{\texorpdfstring{$\lambda_1^2+4\mu\lambda_2<0$ and $\lambda_2<-\mu$}{}}\label{w2complexq}
The roots $q_\pm$ are complex and can be written as $q_\pm=Re^{\pm i\theta}$ where $R=\sqrt{\dfrac{\mu}{\lambda_2}}$ and $\theta=\dfrac{\lambda_1}{\sqrt{-4\mu\lambda_2}}$. The terms in the general solution will be $(q_+q_-^{j-1}-q_-q_+^{j-1})=2iR^j\sin{(j-2)\theta}$, $(q_+^{j-1}-q_-^{j-1})=2iR^{j-1}\sin{(j-1)\theta}$, and $q_+ - q_- = 2iR\sin{\theta}$. After using $\sin{(j-2)\theta}=\sin{(j-1)\theta}\cos{\theta}-\cos{(j-1)\theta}\sin{\theta}$, the solution can be written as $A_j=\dfrac{R^{j-2}}{\sin{\theta}}\big[(A_1R\cos{\theta}+A_2)\sin{(j-1)\theta} - A_1R\sin{\theta}\cos{(j-1)\theta}\big]$. After defining $y=\sqrt{(A_1R\cos{\theta}+A_2)^2 + (A_1R\sin{\theta})^2}$ and $\cos{\phi}=\dfrac{A_1R\cos{\theta}+A_2}{y}$, 

\begin{equation*}
    A_j=\dfrac{R^{j-2}}{\sin{\theta}}y\sin{[(j-1)\theta-\phi]}
\end{equation*}

\subsubsection{\texorpdfstring{$\lambda_1^2+4\mu\lambda_2=0$ and $\lambda_2<-\mu$}{}}\label{w2equalq}
The dashed curve in Fig.~\ref{phase} will have both $q$ values the same, $q_+=q=q_-$. The general solution will be $A_j=(c_1+c_2j)q^j$ where $A_1=(c_1+c_2)q$ and $A_2=(c_1+2c_2)q^2$. After replacing the $c_1=\dfrac{2A_1q-A_2}{q^2}$ and $c_2=\dfrac{A_2-A_1q}{q^2}$ in terms of $A_1$ and $A_2$, 
\begin{equation*}
    A_j=\big[(2-j)qA_1+(j-1)A_2\big]q^{j-2}
\end{equation*}

\subsubsection{\texorpdfstring{$\lambda_1^2+4\mu\lambda_2>0$, $\lambda_2<-\mu$, and $\lambda_2<\mu-\lambda_1$}{}}\label{w2realq}
Within this condition, both $ q$'s will be real and $|q|<1$. The terms $q_+^{j}-q_-^{j}=(q_+-q_-)q_+^{j-1}+q_-(q_+^{j-1}-q_-^{j-1})$ can be changed in the general solution $A_j=\frac{1}{q_+ - q_-}\big[-A_1q_+q_-(q_+^{j-2}-q_-^{j-2}) + A_2(q_+^{j-1}-q_-^{j-1})\big]$, the new $A_j$ will be
\begin{equation*}
    A_j=\dfrac{1}{q_+-q_-}\big[-A_1q_+q_-\big((q_+-q_-)q_+^{j-3}+q_-(q_+^{j-3}-q_-^{j-3})\big)+A_2\big((q_+-q_-)q_+^{j-2}+q_-(q_+^{j-2}-q_-^{j-2})\big)\big]
\end{equation*}
After rearranging,
\begin{equation*}
    A_j=\frac{q_-}{q_+ - q_-}\big[-A_1q_+q_-(q_+^{j-3}-q_-^{j-3}) + A_2(q_+^{j-2}-q_-^{j-2})\big] + q_+^{j-2}\big[-A_1q_- + A_2\big]
\end{equation*}
\begin{equation*}
    A_j=q_-A_{j-1}+(A_2-q_-A_1)q_+^{j-2}
\end{equation*}
The solution of the above equation is 
\begin{equation*}
    A_j=q_-^{j-2}A_2 + \sum_{k=1}^{j-2} f(k)q_-^{j-k-2}
\end{equation*}
where, $f(k)=(A_2-A_1q_-)q_+^{j-2}$

