			2k\\
			o\\
			m\\
			q\\
			p\\
			2s\\
			2r\\
			2u\\
			2t\\
			w\\
			v
		\end{array}\right),
	\end{align*}
	where $\tau=\frac{\lambda}{2}\frac{d}{dx}ln|tr(V_{0}^{2})|$. Balancing coefficients of each power of  in the above equality gives rise to
	\begin{align*}
		\frac{\delta}{\delta u}(2a_{n+1}+2b_{n+1}+2c_{n+1})=(\tau-n)
		\left(\begin{array}{c}
			2l_{n}\\
			2k_{n}\\
			o_{n}\\
			m_{n}\\
			q_{n}\\
			p_{n}\\
			2s_{n}\\
			2r_{n}\\
			2u_{n}\\
			2t_{n}\\
			w_{n}\\
			v_{n}
		\end{array}\right),
	\end{align*}
	Taking $n=1$, gives $\tau=-1$. Therefore we establish the following equation:
	\begin{align*}
		P_{1,n+1}=
		\left(\begin{array}{c}
			2l_{n+1}\\
			2k_{n+1}\\
			o_{n+1}\\
			m_{n+1}\\
			q_{n+1}\\
			p_{n+1}\\
			2s_{n+1}\\
			2r_{n+1}\\
			2u_{n+1}\\
			2t_{n+1}\\
			w_{n+1}\\
			v_{n+1}
		\end{array}\right)=\frac{\delta}{\delta u}((\frac{-2}{n+2})(a_{n+2}+b_{n+2}+c_{n+2})).
	\end{align*}
	Thus, we see:
	\begin{align*}
		u_{t}=J_{1}P_{1,n+1}=J_{1}\frac{\delta H_{n+1}^{1}}{\delta u},\  H_{n+1}^{1}=(\frac{-2}{n+2})(a_{n+2}+b_{n+2}+c_{n+2}),\ n\geq0.
	\end{align*}
	It is said that the hierarchy (\ref{eq:2.5}) have the Hamiltonian structure, and it is easy to verity that $J_{1}L_{1}=L_{1}^{*}J_{1}$. Therefore, the hierarchy (\ref{eq:2.5}) is Liouville integrable.


	When $n=1$, the hierarchy (\ref{eq:2.5}) reduces to the first integrable system
