		l_{12,1}'=\frac{1}{2}(-u_{2}'\partial^{-1}u_{5}'+u_{9}'\partial^{-1}u_{7}'+u_{11}'\partial^{-1}u_{1}'),\  l_{12,2}'=-\frac{1}{2}(u_{2}'\partial^{-1}u_{11}'+u_{11}'\partial^{-1}u_{2}'),\ l_{12,3}'=-u_{9}'\partial^{-1}u_{9}',\\& l_{12,4}'=0,\ l_{12,5}'=0,\ l_{12,6}'=u_{2}'\partial^{-1}u_{2}',\ l_{12,7}=0,\ l_{12,8}'=-\frac{1}{2}(u_{2}'\partial^{-1}u_{9}'+u_{9}'\partial^{-1}u_{2}'),\\& l_{12,9}'=-\frac{1}{2}(u_{9}'\partial^{-1}u_{11}'+u_{11}'\partial^{-1}u_{9}'),\ l_{12,10}'=\frac{1}{2}(u_{2}'\partial^{-1}u_{7}'+u_{9}'\partial^{-1}u_{4}'+u_{11}'\partial^{-1}u_{10}'),\ l_{12,11}'=-u_{11}'\partial^{-1}u_{11}',\\& l_{12,12}'=-\frac{1}{2}\partial+u_{2}'\partial^{-1}u_{1}'+u_{9}'\partial^{-1}u_{10}'+u_{11}'\partial^{-1}u_{12}'
	\end{align*}
	To construct the Hamiltonian structure, we employ trace identities \cite{ref13}, and have
	\begin{align*}
		&\left\langle V_{0},\frac{\partial U_{1}}{\partial\lambda}\right\rangle = 2a-2b-2c ,\
		\left\langle V_{0},\frac{\partial U_{1}}{\partial u_{1}'}\right\rangle = 2g ,\
		\left\langle V_{0},\frac{\partial U_{1}}{\partial u_{2}'}\right\rangle = 2f ,\
		\left\langle V_{0},\frac{\partial U_{1}}{\partial u_{3}'}\right\rangle = o ,\\
		&\left\langle V_{0},\frac{\partial U_{1}}{\partial u_{4}'}\right\rangle = m ,\
		\left\langle V_{0},\frac{\partial U_{1}}{\partial u_{5}'}\right\rangle = q ,\
		\left\langle V_{0},\frac{\partial U_{1}}{\partial u_{6}'}\right\rangle = p ,\
		\left\langle V_{0},\frac{\partial U_{1}}{\partial u_{7}'}\right\rangle = 2e ,\
		\left\langle V_{0},\frac{\partial U_{1}}{\partial u_{8}'}\right\rangle = 2d ,\\
		&\left\langle V_{0},\frac{\partial U_{1}}{\partial u_{9}'}\right\rangle = 2u ,\
		\left\langle V_{0},\frac{\partial U_{1}}{\partial u_{10}'}\right\rangle = 2t ,\
		\left\langle V_{0},\frac{\partial U_{1}}{\partial u_{11}'}\right\rangle = w ,\
		\left\langle V_{0},\frac{\partial U_{1}}{\partial u_{12}'}\right\rangle = v.
	\end{align*}
	Substituting the above formulate into the trace identity yields
	\begin{align*}
		\frac{\delta}{\delta u'}(2a-2b-2c)=\lambda^{-\tau}\frac{\partial}{\partial\lambda}\lambda^{\tau}
		\left(\begin{array}{c}
			2g\\
			2f\\
			o\\
			m\\
			q\\
			p\\
			2e\\
			2d\\
			2u\\
			2t\\
			w\\
			v
		\end{array}\right),
	\end{align*}
	where $\tau=\frac{\lambda}{2}\frac{d}{dx}ln|tr(V_{0}^{2})|$. Balancing coefficients of each power of  in the above equality gives rise to
	\begin{align*}
		\frac{\delta}{\delta u'}(2a_{n+1}-2b_{n+1}-2c_{n+1})=(\tau-n)
		\left(\begin{array}{c}
			2g_{n}\\
			2f_{n}\\
			o_{n}\\
			m_{n}\\
			q_{n}\\
			p_{n}\\
			2e_{n}\\
			2d_{n}\\
			2u_{n}\\
			2t_{n}\\
			w_{n}\\
			v_{n}
		\end{array}\right),
	\end{align*}
	Taking $n=1$, gives $\tau=-1$. Therefore we establish the following equation:
	\begin{align*}
		P_{2,n+1}=
		\left(\begin{array}{c}
			2g_{n+1}\\
			2f_{n+1}\\
			o_{n+1}\\
			m_{n+1}\\
			q_{n+1}\\
			p_{n+1}\\
			2e_{n+1}\\
			2f_{n+1}\\
			2u_{n+1}\\
			2t_{n+1}\\
			w_{n+1}\\
			v_{n+1}
		\end{array}\right)=\frac{\delta}{\delta u'}((\frac{-2}{n+2})(a_{n+2}-b_{n+2}-c_{n+2})).
	\end{align*}
	Thus, we see:
	\begin{align*}
		u_{t}'=J_{2}P_{2,n+1}=J_{2}\frac{\delta H_{n+1}^{2}}{\delta u},\  H_{n+1}^{2}=(\frac{-2}{n+2})(a_{n+2}-b_{n+2}-c_{n+2}),\ n\geq0.
	\end{align*}
	It is said that the hierarchy (\ref{eq:2.8}) have the Hamiltonian structure, and it is easy to verity that $J_{2}L_{2}=L_{2}^{*}J_{2}$. Therefore, the hierarchy (\ref{eq:2.8}) is Liouville integrable.

	When $n=1$, the hierarchy (\ref{eq:2.8}) reduces to the first integrable system
	\begin{align*}
		u_{1t}'=&\frac{1}{2}u_{1x}'(\alpha-\gamma)-\frac{1}{2}u_{7}'\partial^{-1}(u_{1}'u_{8}'+u_{3}'u_{10}'+u_{9}'u_{12}')(\beta-\gamma)+\frac{1}{2}u_{12}'\partial^{-1}(-u_{1}'u_{11}'+u_{2}'u_{5}'-u_{7}'u_{9}')(\alpha+\gamma)\\
		&-\frac{1}{2}u_{5}'\partial^{-1}(-u_{1}'u_{6}'+u_{2}'u_{12}'+u_{8}'u_{10}')(\alpha+\gamma)+\frac{1}{2}u_{10}'\partial^{-1}(-u_{1}'u_{9}'-u_{3}'u_{7}'+u_{5}'u_{8}')(\alpha+\beta),\\
		u_{2t}'=&\frac{1}{2}u_{2x}'(\alpha-\gamma)-\frac{1}{2}u_{8}'\partial^{-1}(u_{2}'u_{7}'+u_{4}'u_{9}'+u_{10}'u_{11}')(\beta-\gamma)+\frac{1}{2}u_{6}'\partial^{-1}(-u_{1}'u_{11}'+u_{2}'u_{5}'-u_{7}'u_{9}')(\alpha+\gamma)\\
		&-\frac{1}{2}u_{11}'\partial^{-1}(-u_{1}'u_{6}'+u_{2}'u_{12}'+u_{8}'u_{10}')(\alpha+\gamma)-\frac{1}{2}u_{9}'\partial^{-1}(u_{2}'u_{10}'+u_{4}'u_{8}'-u_{6}'u_{7}')(\alpha+\beta),\\
		u_{3t}'=&-u_{3x}'\beta+\frac{1}{2}u_{8}'\partial^{-1}(-u_{1}'u_{9}'-u_{3}'u_{7}'+u_{5}'u_{8}')(\alpha+\beta)+u_{9}'\partial^{-1}(u_{1}'u_{8}'+u_{3}'u_{10}'+u_{9}'u_{12}')(\beta-\gamma),\\
		u_{4t}'=&-u_{4x}'\beta+\frac{1}{2}u_{10}'\partial^{-1}(u_{2}'u_{7}'+u_{4}'u_{9}'+u_{10}'u_{11}')(\beta-\gamma)+u_{7}'\partial^{-1}(u_{2}'u_{10}'+u_{4}'u_{8}'-u_{6}'u_{7}')(\alpha+\beta),\\
		u_{5t}'=&u_{5x}'\alpha-u_{1}'\partial^{-1}(-u_{1}'u_{11}'+u_{2}'u_{5}'-u_{7}'u_{9}')(\alpha+\gamma)-u_{7}'\partial^{-1}(-u_{1}'u_{9}'-u_{3}'u_{7}'+u_{5}'u_{8}')(\alpha+\beta),\\
		u_{6t}'=&u_{6x}'\alpha-\frac{1}{2}u_{2}'\partial^{-1}(-u_{1}'u_{6}'+u_{2}'u_{12}'+u_{8}'u_{10}')(\alpha+\gamma)+u_{8}'\partial^{-1}(u_{2}'u_{10}'+u_{4}'u_{8}'-u_{6}'u_{7}')(\alpha+\beta),\\
		u_{7t}'=&\frac{1}{2}u_{7x}'(\alpha-\beta)+\frac{1}{2}u_{1}'\partial^{-1}(u_{2}'u_{7}'+u_{4}'u_{9}'+u_{10}'u_{11}')(\beta-\gamma)+\frac{1}{2}u_{10}'\partial^{-1}(-u_{1}'u_{11}'+u_{2}'u_{5}'-u_{7}'u_{9}')(\alpha+\gamma)\\
		&+\frac{1}{2}u_{4}'\partial^{-1}(-u_{1}'u_{9}'-u_{3}'u_{7}'+u_{5}'u_{8}')(\alpha+\beta)-\frac{1}{2}u_{5}'\partial^{-1}(u_{2}'u_{10}'+u_{4}'u_{8}'-u_{6}'u_{7}')(\alpha+\beta),\\
		u_{8t}'=&\frac{1}{2}u_{8x}'(\alpha-\beta)+\frac{1}{2}u_{2}'\partial^{-1}(u_{1}'u_{8}'+u_{3}'u_{10}'+u_{9}'u_{12}')(\beta-\gamma)-\frac{1}{2}u_{9}'\partial^{-1}(-u_{1}'u_{6}'+u_{2}'u_{12}'+u_{8}'u_{10}')(\alpha+\gamma)\\
		&+\frac{1}{2}u_{4}'\partial^{-1}(-u_{1}'u_{9}'-u_{3}'u_{7}'+u_{5}'u_{8}')(\alpha+\beta)-\frac{1}{2}u_{3}'\partial^{-1}(u_{2}'u_{10}'+u_{4}'u_{8}'-u_{6}'u_{7}')(\alpha+\beta),\\
		u_{9t}'=&-\frac{1}{2}u_{9x}'(\beta+\gamma)-\frac{1}{2}u_{8}'\partial^{-1}(-u_{1}'u_{11}'+u_{2}'u_{5}'-u_{7}'u_{9}')(\alpha+\gamma)+\frac{1}{2}u_{11}'\partial^{-1}(u_{1}'u_{8}'+u_{3}'u_{10}'+u_{9}'u_{12}')(\beta-\gamma),\\
		&-\frac{1}{2}u_{3}'\partial^{-1}(u_{2}'u_{7}'+u_{4}'u_{9}'+u_{10}'u_{11}')(\beta-\gamma)-\frac{1}{2}u_{2}'\partial^{-1}(-u_{1}'u_{9}'-u_{3}'u_{7}'+u_{5}'u_{8}')(\alpha+\beta),\\
		u_{10t}'=&-\frac{1}{2}u_{10x}'(\beta+\gamma)-\frac{1}{2}u_{4}'\partial^{-1}(u_{1}'u_{8}'+u_{3}'u_{10}'+u_{9}'u_{12}')(\beta-\gamma)+\frac{1}{2}u_{12}'\partial^{-1}(u_{2}'u_{7}'+u_{4}'u_{9}'+u_{10}'u_{11}')(\beta-\gamma),\\
		&+\frac{1}{2}u_{7}'\partial^{-1}(-u_{1}'u_{6}'+u_{2}'u_{12}'+u_{8}'u_{10}')(\alpha+\gamma)+\frac{1}{2}u_{1}'\partial^{-1}(u_{2}'u_{10}'+u_{4}'u_{8}'-u_{6}'u_{7}')(\alpha+\beta),\\
		u_{11t}'=&-u_{11x}'\gamma-u_{2}'\partial^{-1}(-u_{1}'u_{11}'+u_{2}'u_{5}'-u_{7}'u_{9}')(\alpha+\gamma)-u_{9}'\partial^{-1}(u_{2}'u_{7}'+u_{4}'u_{9}'+u_{10}'u_{11}')(\beta-\gamma),\\
