	Following the approach in Section 2.1, we construct a second integrable soliton hierarchy by selecting different spectral matrices, and similarly present its corresponding integrable system for the case $n=1$ as a concrete example.

	\section{ Integrable Coupling Systems for the Hierarchy of $\mathfrak{sp}(6)$ }\label{Sec:3}
	In this section, we will use Kronecker product to construct integrable coupling systems of Lie algebra $\mathfrak{sp}(6)$.

	Let $U_{3}$ and $V_{3}$ have the forms
	\begin{align*}
		&U_{3}=\left(
		\begin{array}{cc}
			1&0\\
			0&1
		\end{array}\right)\otimes U_0+
		\left(
		\begin{array}{cc}
			0&1\\
			0&0
		\end{array}\right)\otimes U_2,\\
		&V_{3}=\left(
		\begin{array}{cc}
			1&0\\
			0&1
		\end{array}\right)\otimes V_0+
		\left(
		\begin{array}{cc}
			0&1\\
			0&0
		\end{array}\right)\otimes V_2,
	\end{align*}
	where $U_{0}$, $V_{0}$ be defined as (\ref{eq:2.2}), (\ref{eq:2.3}), and $U_{2}$, $V_{2}\in\widetilde{\mathfrak{sp}(6)}$ be defined as follow:
	\begin{align*}
		U_{2}=\left(
		\begin{array}{cccccc}
			0&0&0&u_{5}^{*}&u_{7}^{*}&u_{1}^{*}\\
			0&0&0&u_{7}^{*}&u_{3}^{*}&u_{9}^{*}\\
			0&0&0&u_{1}^{*}&u_{9}^{*}&u_{11}^{*}\\
			u_{6}^{*}&u_{8}^{*}&u_{2}^{*}&0&0&0\\
			u_{8}^{*}&u_{4}^{*}&u_{10}^{*}&0&0&0\\
			u_{2}^{*}&u_{10}^{*}&u_{12}^{*}&0&0&0
		\end{array}\right),
	\end{align*}
	\begin{align*}
		V_{2}=\left(
		\begin{array}{cccccc}
			a^{*}&d^{*}&f^{*}&p^{*}&r^{*}&k^{*}\\
			e^{*}&b^{*}&h^{*}&r^{*}&m^{*}&t^{*}\\
			g^{*}&j^{*}&c^{*}&k^{*}&t^{*}&v^{*}\\
			q^{*}&s^{*}&l^{*}&-a^{*}&-e^{*}&-g^{*}\\
			s^{*}&o^{*}&u^{*}&-d^{*}&-b^{*}&-j^{*}\\
			l^{*}&u^{*}&w^{*}&-f^{*}&-h^{*}&-c^{*}\\
		\end{array}\right)=\sum_{i\geq0}\left(
		\begin{array}{cccccc}
			a^{*}_{i}&d^{*}_{i}&f^{*}_{i}&p^{*}_{i}&r^{*}_{i}&k^{*}_{i}\\
			e^{*}_{i}&b^{*}_{i}&h^{*}_{i}&r^{*}_{i}&m^{*}_{i}&t^{*}_{i}\\
			g^{*}_{i}&j^{*}_{i}&c^{*}_{i}&k^{*}_{i}&t^{*}_{i}&v^{*}_{i}\\
			q^{*}_{i}&s^{*}_{i}&l^{*}_{i}&-a^{*}_{i}&-e^{*}_{i}&-g^{*}_{i}\\
			s^{*}_{i}&o^{*}_{i}&u^{*}_{i}&-d^{*}_{i}&-b^{*}_{i}&-j^{*}_{i}\\
			l^{*}_{i}&u^{*}_{i}&w^{*}_{i}&-f^{*}_{i}&-h^{*}_{i}&-c^{*}_{i}.
		\end{array}\right)
	\end{align*}
	Then we have a new pair of $U_{3}$ and $V_{3}$ as follow:
	\begin{align*}
		U_{3}=\left(\begin{array}{cc}
			U_{0}&U_{2}\\
			0&U_{0}
		\end{array}\right),\quad
		V_{3}=\left(\begin{array}{cc}
			V_{0}&V_{2}\\
			0&V_{0}
		\end{array}\right).
	\end{align*}

	Therefore, the stationary zero curvature representation $V_{3,x}=[U_{3},V_{3}]$ is equivalent to
	\begin{align*}
		\begin{cases}
			V_{0,x}=[U_{0},V_{0}],\\
			V_{3,x}=[U_{0},V_{2}]+[U_{2},V_{0}],
		\end{cases}
	\end{align*}
	and the corresponding enlarged zero curvature equation $U_{3,t}-V_{3,x}+[U_{3},V_{3}]=0$ is equivalent to
	\begin{align*}
		\begin{cases}
			U_{0,t}-V_{0,x}+[U_{0},V_{0}]=0,\\
			U_{2,t}-V_{2,x}+[U_{0},V_{2}]+[U_{2},V_{0}]=0.
		\end{cases}
	\end{align*}


	From the stationary zero curvature equation $V_{3,x}=[U_{3},V_{3}]$, we obtain (\ref{eq:2.4}) and
	\begin{align}
		\begin{cases}
			a_{x}^{*}=u_{1}l^{*}-u_{2}k^{*}+u_{5}q^{*}-u_{6}p^{*}+u_{7}s^{*}-u_{8}r^{*}+u_{1}^{*}l-u_{2}^{*}k+u_{5}^{*}q-u_{6}^{*}p+u_{7}^{*}s-u_{8}^{*}r,\\
			b_{x}^{*}=u_{3}o^{*}-u_{4}m^{*}+u_{7}s^{*}-u_{8}r^{*}+u_{9}u^{*}-u_{10}t^{*}+u_{3}^{*}o-u_{4}^{*}m+u_{7}^{*}s-u_{8}^{*}r+u_{9}^{*}u-u_{10}^{*}t,\\
			c_{x}^{*}=u_{1}l^{*}-u_{2}k^{*}+u_{9}u^{*}-u_{10}t^{*}+u_{11}w^{*}-u_{12}v^{*}+u_{1}^{*}l-u_{2}^{*}k+u_{9}^{*}u-u_{10}^{*}t+u_{11}^{*}w-u_{12}^{*}v,\\
			d_{x}^{*}=u_{1}u^{*}-u_{4}r^{*}+u_{5}s^{*}+u_{7}o^{*}-u_{8}p^{*}-u_{10}k^{*}+u_{1}^{*}u-u_{4}^{*}r+u_{5}^{*}s+u_{7}^{*}o-u_{8}^{*}p-u_{10}^{*}k,\\
			e_{x}^{*}=-u_{2}t^{*}+u_{3}s^{*}-u_{6}r^{*}+u_{7}q^{*}-u_{8}m^{*}+u_{9}l^{*}-u_{2}^{*}t+u_{3}^{*}s-u_{6}^{*}r+u_{7}^{*}q-u_{8}^{*}m+u_{9}^{*}l,\\
			f_{x}^{*}=u_{1}w^{*}-u_{2}p^{*}+u_{5}l^{*}+u_{7}u^{*}-u_{10}r^{*}-u_{12}k^{*}+u_{1}^{*}w-u_{2}^{*}p+u_{5}^{*}l+u_{7}^{*}u-u_{10}^{*}r-u_{12}^{*}k,\\
			g_{x}^{*}=u_{1}q^{*}-u_{2}v^{*}-u_{6}k^{*}-u_{8}t^{*}+u_{9}s^{*}+u_{11}l^{*}+u_{1}^{*}q-u_{2}^{*}v-u_{6}^{*}k-u_{8}^{*}t+u_{9}^{*}s+u_{11}^{*}l,\\
			h_{x}^{*}=-u_{2}r^{*}+u_{3}u^{*}+u_{7}l^{*}+u_{9}w^{*}-u_{10}m^{*}-u_{12}t^{*}-u_{2}^{*}r+u_{3}^{*}u+u_{7}^{*}l+u_{9}^{*}w-u_{10}^{*}m-u_{12}^{*}t,\\
			j_{x}^{*}=u_{1}s^{*}-u_{4}t^{*}-u_{8}k^{*}+u_{9}o^{*}-u_{10}v^{*}+u_{11}u^{*}+u_{1}^{*}s-u_{4}^{*}t-u_{8}^{*}k+u_{9}^{*}o-u_{10}^{*}v+u_{11}^{*}u,\\
			k_{x}^{*}=2\lambda k^{*}-u_{1}a^{*}-u_{1}c^{*}-u_{5}g^{*}-u_{7}j^{*}-u_{9}d^{*}-u_{11}f^{*}-u_{1}^{*}a-u_{1}^{*}c-u_{5}^{*}g-u_{7}^{*}j-u_{9}^{*}d-u_{11}^{*}f,\\
			l_{x}^{*}=-2\lambda l^{*}+u_{2}a^{*}+u_{2}c^{*}+u_{6}f^{*}+u_{8}h^{*}+u_{10}e^{*}+u_{12}g^{*}+u_{2}^{*}a+u_{2}^{*}c+u_{6}^{*}f+u_{8}^{*}h+u_{10}^{*}e+u_{12}^{*}g,\\
			m_{x}^{*}=2\lambda m^{*}-2u_{3}b^{*}-2u_{7}e^{*}-2u_{9}h^{*}-2u_{3}^{*}b-2u_{7}^{*}e-2u_{9}^{*}h,\\
			o_{x}^{*}=-2\lambda o^{*}+2u_{4}b^{*}+2u_{8}d^{*}+2u_{10}j^{*}+2u_{4}^{*}b+2u_{8}^{*}d+2u_{10}^{*}j,\\
			p_{x}^{*}=2\lambda p^{*}-2u_{1}f^{*}-2u_{5}a^{*}-2u_{7}d^{*}-2u_{1}^{*}f-2u_{5}^{*}a-2u_{7}^{*}d,\\
			q_{x}^{*}=-2\lambda q^{*}+2u_{2}g^{*}+2u_{6}a^{*}+2u_{8}e^{*}+2u_{2}^{*}g+2u_{6}^{*}a+2u_{8}^{*}e,\\
			r_{x}^{*}=2\lambda r^{*}-u_{1}h^{*}-u_{3}d^{*}-u_{5}e^{*}-u_{7}a^{*}-u_{7}b^{*}-u_{9}f^{*}-u_{1}^{*}h-u_{3}^{*}d-u_{5}^{*}e-u_{7}^{*}a-u_{7}^{*}b-u_{9}^{*}f,\\
			s_{x}^{*}=-2\lambda s^{*}+u_{2}j^{*}+u_{4}e^{*}+u_{6}d^{*}+u_{8}a^{*}+u_{8}b^{*}+u_{10}g^{*}+u_{2}^{*}j+u_{4}^{*}e+u_{6}^{*}d+u_{8}^{*}a+u_{8}^{*}b+u_{10}^{*}g,\\
			t_{x}^{*}=2\lambda t^{*}-u_{1}e^{*}-u_{3}j^{*}-u_{7}g^{*}-u_{9}b^{*}-u_{9}c^{*}-u_{11}h^{*}-u_{1}^{*}e-u_{3}^{*}j-u_{7}^{*}g-u_{9}^{*}b-u_{9}^{*}c-u_{11}^{*}h,\\
			u_{x}^{*}=-2\lambda u^{*}+u_{2}d^{*}+u_{4}h^{*}+u_{8}f^{*}+u_{10}b^{*}+u_{10}c^{*}+u_{12}j^{*}+u_{2}^{*}d+u_{4}^{*}h+u_{8}^{*}f+u_{10}^{*}b+u_{10}^{*}c+u_{12}^{*}j,\\
			v_{x}^{*}=2\lambda v^{*}-2u_{1}g^{*}-2u_{9}j^{*}-2u_{11}c^{*}-2u_{1}^{*}g-2u_{9}^{*}j-2u_{11}^{*}c,\\
			w_{x}^{*}=-2\lambda w^{*}+2u_{2}f^{*}+2u_{10}h^{*}+2u_{12}c^{*}+2u_{2}^{*}f+2u_{10}^{*}h+2u_{12}^{*}c.
		\end{cases}\label{eq:3.1}
	\end{align}
	Similarly, take the initial values
	\begin{align*}
		a_{0}^{*}=\alpha^{*}, b_{0}^{*}=\beta^{*}, c_{0}^{*}=\gamma^{*}, d_{0}^{*}=e_{0}^{*}=\dots=v_{0}^{*}=w_{0}^{*}=0.
	\end{align*}
