%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{From a pencil of type (v) to the \textit{d}-Painlev\'e equation of the surface type $A_1^{(1)}$}
\label{sect dPE7}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\paragraph{2D QRT map.}
We consider the QRT map corresponding to the pencil of biquadratic curves $\{C_\mu\}$ through eight points $s_i=(a_i,b_i)$, $i=1,\ldots,8$, where
\begin{equation}
b_i=-a_i, \;\; i=1,\ldots,4, \quad {\rm and}\quad b_i=1-a_i,\;\; i=5,\ldots,8. 
\end{equation}
These eight points support a pencil of biquadratic curves if they satisfy the condition 
\begin{equation}\label{dPE7 cond}
   \sum_{i=1}^8 a_i=\sum_{i=1}^8b_i\;\;\Leftrightarrow\;\; \sum_{i=1}^8 a_i=2.
\end{equation}
This pencil contains a reducible curve, consisting of two (1,1)-curves: 
\begin{equation}
C_\infty=\{(x+y)(x+y-1)=0\}.
\end{equation}

