\section{From a pencil of type (iv) to the \textit{q}-Painlev\'e equation of the surface type $A_1^{(1)}$}
\label{sect qPE7}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


\paragraph{2D QRT map.}
Consider the QRT map corresponding to the pencil of biquadratic curves through eight points 
\begin{eqnarray}
&& s_i=(a_i,b_i)=\big(\ka c_i,\ka c_i^{-1}\big), \quad i=1,\ldots,4,\\
&& s_i=(a_i,b_i)=\big(c_i,c_i^{-1}\big), \quad i=5,\ldots,8,
\end{eqnarray}
with $\kappa \neq 0,1$.
These eight points support a pencil of biquadratic curves if they satisfy the condition 
\begin{equation}\label{qPE7 cond}
   \frac{\prod_{i=1}^4 c_i}{\prod_{i=5}^8 c_i}=1\quad\Leftrightarrow\quad \frac{\prod_{i=1}^4 a_i}{\prod_{i=5}^8 a_i}=\ka^{4} \quad\Leftrightarrow\quad \frac{\prod_{i=1}^4 b_i}{\prod_{i=5}^8 b_i}=\ka^{4}.
\end{equation}
They are symmetric with respect to $\sigma(x,y)=(y,x)$ if $c_{2i}=c_{2i-1}^{-1}$, $i=1,\ldots,4$.
See Fig. \ref{fig qPE7} (a).
