The vertical involution $i_1$ can be described by the following equation:
 \begin{align} \label{dPE8 QRT i1}
&  i_1(x,y)=(x,\t y),\nonumber\\ 
& \frac{\big(\t y-\xi(\xi-\ka_2)\big)\big(y-\xi(\xi-\ka_2)\big)}{\big(\t y-(\xi-\ka_1)(\xi-\ka_1+\ka_2)\big)
 \big(y-(\xi-\ka_1)(\xi-\ka_1+\ka_2)\big)}=\frac{U(\xi)}{U(\ka_1-\xi)}, \quad x=\xi(\xi-\ka_1).
 \end{align}
 Here we use the abbreviation 
 \begin{equation}\label{dPE8 U}
 U(z)=\prod_{i=1}^8 (z-z_i).
 \end{equation}
Formula \eqref{dPE8 QRT i1} is understood as follows. Written as a polynomial in $\xi$, it is anti-symmetric with respect to $\xi\leftrightarrow \ka_1-\xi$. Upon division by $\xi-2\ka_1$, the resulting polynomial is symmetric and therefore it can be actually expressed as a polynomial in $x=\xi(\xi-\ka_1)$. This defines $i_1$ as a birational involution (its symmetry w.r.t. $y\leftrightarrow \t y$ is obvious).

Similarly, the horizontal involution $i_2$ can be described by the following equation:
 \begin{align} \label{dPE8 QRT i2}
& i_2(x,y)=(\t x,y),\nonumber\\  
& \frac{\big(\t x-\eta(\eta-\ka_1)\big)\big(x-\eta(\eta-\ka_1)\big)}{\big(\t x-(\eta-\ka_2)(\eta-\ka_2+\ka_1)\big)\big(x-(\eta-\ka_2)(\eta-\ka_2+\ka_1)\big)}=\frac{U(\eta)}{U(\ka_2-\eta)}, \quad y=\eta(\eta-\ka_2).
 \end{align}
The QRT map $F$ is the composition of these two involutions, $F=i_1\circ i_2$. 
The eight points $s_1,\ldots,s_8$ in $\bbP^1\times \bbP^1$ serve as the  indeterminacy set for $i_1$ and for $i_2$. The singularity confinement structure is as in \eqref{sing1}.

{\bf Remark.}
In what follows, we restrict ourselves to the case $\ka_1+\ka_2=0$. This restriction is not essential, but will allow us to shorten some of the formulas. Thus, from now on we set
\begin{equation}\label{dPE8 kappa restr}
\ka_1=-\ka, \quad \ka_2=\ka.
\end{equation} 
If, additionally, the points $z_i$ satisfy the condition
\begin{equation}\label{dPE8 zi restr}
z_{i+4}=-z_i,\quad i=1,\ldots,4,
\end{equation}
then the QRT involutions admits a symmetry $i_1=\sigma\circ i_2\circ \sigma$, where $\sigma(x,y)=(y,x)$, so that one can introduce the QRT root $f=i_1\circ \sigma=\sigma\circ i_2$, such that $F=f\circ f$. 



\paragraph{3D Painlev\'e map.} As usual, we identify $\bbP^1 \times \bbP^1$ with the quadric $Q_0 = \{ X_1 X_2 - X_3 X_4 =0 \} \subset \bbP^3$ via $[X_1 : X_2 : X_3 : X_4] = [x: y: xy: 1]$. The points $s_i$ are lifted to 
$$
S_i=[a_i:b_i:a_ib_i:1].
$$
We declare $Q_\lambda$ to be spanned by $Q_0$ and $Q_\infty=P_\infty = (X_1-X_2)^2-2\ka^2(X_1+X_2)X_4$:
\begin{equation}\label{dPE8 Q lambda}
	Q_\lambda = \Big\{ X_1 X_2 - X_3 X_4 - \lambda \big((X_1-X_2)^2-2\ka^2(X_1+X_2)X_4\big)=0\Big\}.
\end{equation}
The base set of the pencil $Q_\lambda$ is a cuspidal space curve of degree 4, $\{X_1 X_2 - X_3 X_4 =0,\, (X_1-X_2)^2-2\ka^2(X_1+X_2)X_4 =0 \}$, with the cusp at $[0:0:1:0]$. This is a pencil of type (iii).

The matrix $M_\lambda$ of the quadratic form $Q_\lambda$:
\begin{equation}
M_\lambda=\begin{pmatrix}
-2\lambda & 1+2\lambda & 0  & 2\lambda\ka^2\\
1+2\lambda & -2\lambda & 0 & 2\lambda\ka^2 \\
0 & 0 & 0 & -1 \\
2 \lambda\ka^2 & 2\lambda\ka^2 & -1 & 0 
\end{pmatrix}
\end{equation}
The characteristic polynomial of the pencil $\{Q_\lambda\}$ is: $\Delta(\lambda)=\det(M_\lambda)=1+4\lambda$, so that ${\rm Sing}(Q_\lambda)=\{-\frac{1}{4},\infty\}$. We set
\begin{equation}\label{dPE8 unif}
\lambda=\frac{\nu^2-1}{4}, \quad \sqrt{\Delta(\lambda)}=\nu.
\end{equation}
Thus, $\lambda(\nu)=\lambda(-\nu)$, while $ \sqrt{\Delta(\lambda)}$ changes its sign as $\nu\mapsto-\nu$. This gives us a double cover of the original pencil branched at $\nu=0$, corresponding to $\lambda=-1/4$, and at $\nu=\infty$, corresponding to $\lambda=\infty$. The normalizing transformation of $Q_\lambda$ to the canonical form $Q_0$ can be found as follows: 
\begin{equation}\label{dPE8 pencil norm}
\begin{bmatrix} X_1\\X_2\\X_3\\X_4\end{bmatrix} = A_\nu \begin{bmatrix} Y_1 \\ Y_2 \\ Y_3 \\ Y_4\end{bmatrix}, 
\end{equation}
where
\begin{equation}
A_\nu=\begin{pmatrix} \frac{1}{2\nu}(\nu+1) & \frac{1}{2\nu}(\nu-1) & 0 &  0 \\[0.15cm]
\frac{1}{2\nu}(\nu-1) & \frac{1}{2\nu}(\nu+1) & 0 & 0 \\[0.15cm] 
\frac{\ka^2}{2}(\nu^2-1) & \frac{\ka^2}{2}(\nu^2-1) & 1 & 0 \\[0.15cm]
0 & 0 & 0 & 1 \end{pmatrix}.                               
 \end{equation}
 Indeed, one immediately verifies that 
 $$
 A_\nu^{\rm T} M_{\lambda(\nu)} A_\nu=M_0.
 $$
Now, we are in the position to derive a parametrization of the quadric $Q_{\lambda(\nu)}$:
\begin{equation}\label{dPE8 x to X}
\begin{bmatrix} X_1 \\ X_2 \\ X_3 \\ X_4 \end{bmatrix}=A_\nu \begin{bmatrix} x \\ y \\ xy \\ 1 \end{bmatrix}
=\begin{bmatrix} \frac{1}{2\nu}((\nu+1)x+(\nu-1)y) \\[0.15cm]
 \frac{1}{2\nu}((\nu-1)x+(\nu+1)y) \\[0.15cm]
  xy+\frac{\ka^2}{2}(\nu^2-1)(x+y) \\[0.15cm] 1  \end{bmatrix}=:\phi_\nu(x,y).
\end{equation}
Observe that this parametrization is neither valid for $\nu=0$ nor for $\nu=\infty$.
The pencil-adapted coordinates $(x,y,\nu)$ on (the double cover of) $\bbP^3$ are:
\begin{equation}\label{dPE8 X to x}
x = \dfrac{(\nu+1)X_1-(\nu-1)X_2}{2X_4},\quad y = \dfrac{(\nu+1)X_2-(\nu-1)X_1}{2X_4},
\end{equation}
which have to be supplemented with
\begin{equation}\label{dPE8 X to lambda}
\lambda = \dfrac{\nu^2-1}{4} = \dfrac{X_1 X_2-X_3X_4}{(X_1-X_2)^2-2\ka^2(X_1+X_2)X_4}.
\end{equation}
The degenerate quadrics for $\nu = \infty$ and for $\nu=0$ are cones.


\begin{theorem}
For any $\delta\in\mathbb  C\setminus\{0\}$, define the Painlev\'e deformation map corresponding to the translation $\nu\mapsto\widehat\nu=\nu+2\delta$ by 
$$
L:\quad \left\{\begin{array}{ccl} \widehat X_1 & = & X_1X_4, \\ 
\widehat X_2 & = & X_2X_4, \\
\widehat X_3 & = & X_3X_4-\big(\lambda(\widehat\nu)-\lambda(\nu)\big)Q_\infty(X)\\
                      & = & X_3X_4- \beta(\nu+\beta)(X_1-X_2)^2+2\ka^2\beta (\nu+\beta)(X_1+X_2)X_4,\\
\widehat X_4 & = & X_4^2.
\end{array}\right.
$$
Then, in pencil-adapted coordinates, the map $L$ acts as follows:
\begin{equation}\label{dPE8 map L}
L: (x,y,\nu)\mapsto (\widehat x,\widehat y,\widehat \nu), \quad \widehat x =x+\frac{\delta(x-y)}{\nu},\quad \widehat y = y+\frac{\delta(y-x)}{\nu},\quad \widehat\nu=\nu+2\delta.
\end{equation}
For the latter map,  the factorizations \eqref{L fact 1}, \eqref{L fact 2} are given by
\begin{equation}\label{dPE8 L1}
L_1=R_1: (x,y,\nu)\mapsto (x,\widetilde y,\nu+\delta), \quad \t y= y+\dfrac{\delta}{\nu}(y-x),
\end{equation} 
\begin{equation}\label{dPE8 L2}
L_2=R_2:(x,y,\nu)\mapsto (\widetilde x,y, \nu+\delta),\quad \t x= x+\frac{\delta}{\nu}(x-y).
\end{equation}
\end{theorem}


\paragraph{Relation to the $d$-Painlev\'e equation of the surface type $A_0^{(1)}$.} 

In the pencil-adapted coordinates $(x,y,\nu)$, for each fixed $\nu$, the intersection curves $Q_{\lambda(\nu)} \cup P_\mu$ form the pencil through the points
\begin{equation}
s_i(\nu)=(a_i(\nu),b_i(\nu))=\big( z_i(z_i+\ka\nu), z_i(z_i-\ka\nu)\big), \quad i=1,\ldots,8,
\end{equation}
which are just the points $S_i$ expressed in the pencil-adapted coordinates on $Q_{\lambda(\nu)}$. Thus, the 3D QRT involutions $i_1$, $i_2$ act on each quadric $Q_{\lambda(\nu)}$ in the pencil-adapted coordinates via formulas which are obtained from the corresponding 2D formulas by replacing $\ka$ by $\ka \nu$:
\begin{align} \label{dPE8 3D QRT i1 on fiber}
& i_1(x,y)=(x,\t y), \nonumber\\  
& \frac{\big(\t y-\xi(\xi-\ka\nu)\big)\big(y-\xi(\xi-\ka\nu)\big)}{\big(\t y-(\xi+\ka\nu)(\xi+2\ka\nu)\big)\big(y-(\xi+\ka\nu)(\xi+2\ka\nu)\big)}=\frac{U(\xi)}{U(-\ka\nu-\xi)}, 
 \quad x=\xi(\xi+\ka\nu),
 \end{align}
 \begin{align} \label{dPE8 3D QRT i2 on fiber}
& i_2(x,y)=(\t x,y),\nonumber\\
&  \frac{\big(\t x-\eta(\eta+\ka\nu)\big)\big(x-\eta(\eta+\ka\nu)\big)}{\big(\t x-(\eta-\ka\nu)(\eta-2\ka\nu)\big)\big(x-(\eta-\ka\nu)(\eta-2\ka\nu)\big)}=\frac{U(\eta)}{U(\ka\nu-\eta)}, \quad y=\eta(\eta-\ka\nu).
 \end{align}
In notations of  \eqref{dP def eq 1}, \eqref{dP def eq 2}, the latter two equations take the following form:
 \begin{eqnarray} \label{dPE8 aux1}
\frac{\big(\t x-\eta(\eta+\ka\nu_{2n})\big)\big(x-\eta(\eta+\ka\nu_{2n})\big)}{\big(\t x-(\eta-\ka\nu_{2n})(\eta-2\ka\nu_{2n})\big)\big(x-(\eta-\ka\nu_{2n})(\eta-2\ka\nu_{2n})\big)}=\frac{U(\eta)}{U(\ka\nu_{2n}-\eta)},\nonumber\\ 
y_n=\eta(\eta-\ka\nu_{2n}), 
 \end{eqnarray}
\begin{eqnarray} \label{dPE8 aux2}
\frac{\big(\t y-\xi(\xi-\ka\nu_{2n+1})\big)\big(y-\xi(\xi-\ka\nu_{2n+1})\big)}{\big(\t y-(\xi+\ka\nu_{2n+1})(\xi+2\ka\nu_{2n+1})\big)\big(y-(\xi+\ka\nu_{2n+1})(\xi+2\ka\nu_{2n+1})\big)}=\frac{U(\xi)}{U(-\ka\nu_{2n+1}-\xi)},\nonumber\\
 x_{n+1}=\xi(\xi+\ka\nu_{2n+1}).\quad
 \end{eqnarray}
 Recall that here 
$$
\nu_{2n+1}=\nu_{2n+1/2}+\delta=\nu_{2n}+2\delta.
$$
To express in \eqref{dPE8 aux1} the variables $x$, $\t x$ through $x_n$, $y_n$, we observe that 
$$
L_2: (x_n,y_{n},\nu_{2n-1/2})\mapsto (x,y_n,\nu_{2n}), \quad R_2: (\t x,y_n,\nu_{2n})\mapsto (x_{n+1},y_n,\nu_{2n+1/2})
$$ 
can be written, according to \eqref{dPE8 L2}, as follows:
$$
x= x_n+\frac{\delta}{\nu_{2n-1/2}}(x_n-y_{n}),\quad {\rm resp.}\quad  x_{n+1}=\t x+\frac{\delta}{\nu_{2n}}(\t x-y_{n}).
$$
 A simple computation confirms that these relations are equivalent to
\begin{equation}\label{dPE8 aux 1.1}
\frac{x-\eta(\eta+\ka\nu_{2n})}{x-(\eta-\ka\nu_{2n})(\eta-2\ka\nu_{2n})}=
\frac{x_n-\eta(\eta+\ka\nu_{2n-1})}{x_n-(\eta-\ka\nu_{2n})(\eta-\ka\nu_{2n}-\ka\nu_{2n-1})}, \quad 
y_n=\eta(\eta-\ka\nu_{2n}),
\end{equation}
\begin{equation}\label{dPE8 aux 1.2}
\frac{\t x-\eta(\eta+\ka\nu_{2n})}{\t x-(\eta-\ka\nu_{2n})(\eta-2\ka\nu_{2n})}=
\frac{x_{n+1}-\eta(\eta+\ka\nu_{2n+1})}{x_{n+1}-(\eta-\ka\nu_{2n})(\eta-\ka\nu_{2n+1}-\ka\nu_{2n})}, \quad 
y_n=\eta(\eta-\ka\nu_{2n}).
\end{equation}
Similarly, to express in \eqref{dPE8 aux2} the variables $y$, $\t y$ through $x_{n+1}$, $y_n$, we observe that 
$$
L_1:(x_{n+1},y_n,\nu_{2n+1/2})\mapsto (x_{n+1},y,\nu_{2n+1}), \quad R_1:(x_{n+1},\t y,\nu_{2n+1})\mapsto (x_{n+1},y_{n+1},\nu_{2n+3/2}),
$$
which, according to \eqref{dPE8 L1}, can be put as follows:
$$
y=y_{n}+\frac{\delta}{\nu_{2n+1/2}}(y_{n}-x_{n+1}), \quad  y_{n+1}=\t y+\frac{\delta}{\nu_{2n+1}}(\t y-x_{n+1}).
$$
Again, these relations are equivalent to
\begin{eqnarray}\label{dPE8 aux 2.1}
\frac{y-\xi(\xi-\ka\nu_{2n+1})}{y-(\xi+\ka\nu_{2n+1})(\xi+2\ka\nu_{2n+1})}=
\frac{y_n-\xi(\xi-\ka\nu_{2n})}{y_n-(\xi+\ka\nu_{2n+1})(\xi+\ka\nu_{2n+1}+\ka\nu_{2n})}, \nonumber\\
\qquad x_{n+1}=\xi(\xi+\ka\nu_{2n+1})
\end{eqnarray}
\begin{eqnarray}\label{dPE8 aux 2.2}
\frac{\t y-\xi(\xi-\ka\nu_{2n+1})}{\t y-(\xi+\ka\nu_{2n+1})(\xi+2\ka\nu_{2n+1})}=
\frac{y_{n+1}-\xi(\xi-\ka\nu_{2n+2})}{y_{n+1}-(\xi+\ka\nu_{2n+1})(\xi+\ka\nu_{2n+2}+\ka\nu_{2n+1})}, \nonumber\\ 
x_{n+1}=\xi(\xi+\ka\nu_{2n+1}).
\end{eqnarray}
Substituting \eqref{dPE8 aux 1.1}--\eqref{dPE8 aux 2.2} into \eqref{dPE8 aux1}, \eqref{dPE8 aux2}, we arrive at the following system of non-autonomous difference equations for the variables $x_n, y_n$ :
 \begin{eqnarray} \label{dPE8 1}  
 \frac{\big(x_{n+1}-\eta(\eta+\ka\nu_{2n+1})\big)\big(x_n-\eta(\eta+\ka\nu_{2n-1})\big)}
{\big(x_{n+1}-(\eta-\ka\nu_{2n})(\eta-\ka\nu_{2n+1}-\ka\nu_{2n})\big)\big(x_n-(\eta-\ka\nu_{2n})(\eta-\ka\nu_{2n}-\ka\nu_{2n-1})\big)} \nonumber\\
=\frac{U(\eta)}{U(\ka\nu_{2n}-\eta)}, \quad y_n=\eta(\eta-\ka\nu_{2n}),
 \end{eqnarray}
 \begin{eqnarray} \label{dPE8 2}
 \frac{\big(y_{n+1}-\xi(\xi-\ka\nu_{2n+2})\big)\big(y_n-\xi(\xi-\ka\nu_{2n})\big)}
{\big(y_{n+1}-(\xi+\ka\nu_{2n+1})(\xi+\ka\nu_{2n+2}+\ka\nu_{2n+1})\big)\big(y_n-(\xi+\ka\nu_{2n+1})(\xi+\ka\nu_{2n+1}+\ka\nu_{2n})\big)}\nonumber\\
 =\frac{U(\xi)}{U(-\ka\nu_{2n+1}-\xi)}, 
 \quad x_{n+1}=\xi(\xi+\ka\nu_{2n+1}).\quad
 \end{eqnarray}
This is the $d$-Painlev\'e equation of the surface type $A_0^{(1)}$, as given in \cite{Y1}, \cite{KNY}.
\smallskip

{\bf Remark.} In the symmetric situation, when $U(z)=U(-z)$, the system \eqref{dPE8 1}, \eqref{dPE8 2} can be interpreted as a one-field second order difference equation, with $x_n=u_{2n-1}$ and $y_n=u_{2n}$. To see this, one should make  the change $\xi\mapsto -\xi$ in equation \eqref{dPE8 2}, after which it matches \eqref{dPE8 1}.




%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{From a pencil of type (ii) to the \textit{q}-Painlev\'e equation of the surface type $A_0^{(1)}$}
\label{sect qPE8}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\paragraph{2D QRT map.} We consider the QRT map corresponding to the pencil of biquadratic curves through eight points $s_i=(a_i,b_i)$, where
$$
a_i=z_i+\frac{\ka_1}{z_i}, \quad b_i=\frac{1}{z_i}+\frac{z_i}{\ka_2}, \quad i=1,\ldots,8.
$$
These eight points support a pencil of biquadratic curves if they satisfy the condition
$$
\prod_{i=1}^8 z_i=\ka_1^2\ka_2^2.
$$
They belong to the curve with the equation
$$
(x-\ka_2 y)(y-\ka_1^{-1} x)=(\ka_1\ka_2)^{-1}(\ka_1-\ka_2)^2.
$$
This is a biquadratic curve in $\bbP^1\times\bbP^1$ with a simple node at $(\infty,\infty)$, see Fig. \ref{fig qPE8} (a).

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
