ELMs \citep[mathematically formalised and described in][]{schmidt_feedforward_1992, pao_learning_1994, huang_extreme_2004, nan-ying_liang_fast_2006, huang_extreme_2006, deng_regularized_2009} can be considered a subset of neural networks, but differ from traditionally back-propagation-based trained neural networks in their parameter initialisation, whereby parameters controlling the internal network state are untrainable, enabling a gradient-free method of parameter fitting for parameters mapping from the internal network state to the output (as described mathematically in sections below). \cite{mcdonnell_fast_2015, huang_trends_2015} discuss applications of ELMs across different domains. 
%but differ from traditionally back-propagated neural networks in their parameter initialisation and parameter fitting


\subsubsection{Architecture}\label{architecture}

An ELM maps from an input vector $\mathbf {X} \in \mathbb{R}^{N \times d}$ to an output vector $\mathbf {Y} \in \mathbb{R}^{N \times m}$, where $N$ is the number of individual samples inputted to the model, $d$ is the dimensionality of a given sample, and $m$ is the dimensionality of the model output. For the experiments in this work, we consider the values of $N_\text{train}, d, m$ as outlined in Table \ref{tab:nmd}, where $N_\text{train}$ is the number of samples in the training dataset. The mathematics of the ELM are as follows:


\begin{table}
    \centering
    \begin{tabular}{|c|c|c|c|}
       Experiment  & $N_\text{train}$ & $d$ & $m$\\\hline
        1 & 10,000 & 147 & 100\\
        2 & 6,400 & 498,501 & 200 \\
    \end{tabular}
    \caption{The number of samples $N_\text{train}$, sample input dimensionality $d$, and sample output dimensionality $m$, which are considered across Experiment 1 and Experiment 2. Experiments were chosen to cover cases of both $N_\text{train}>>d$, as in Experiment 1, and $N_\text{train}<<d$, as in Experiment 2.}
    \label{tab:nmd}
\end{table}

% via the following mechanism:

We define a fully-connected hidden layer $h$ with $L$ hidden neurons, and a weights matrix 
\begin{equation}
    \mathbf{W} \in \mathbb{R}^{L \times d}
    \label{eq:W}
\end{equation}
The hidden layer output matrix $\mathbf {H} \in \mathbb{R}^{N \times L}$ can then be written as follows: 
\begin{equation}
    \mathbf{H} = g(\mathbf {X} \mathbf{W}^T + \mathbf{b})
    \label{eq:H}
\end{equation}
where $\mathbf{b} \in \mathbb{R}^{L}$ is a biases matrix and $g$ is a non-linear activation function.

The output vector $Y$ is then formulated as follows: 
\begin{equation}
    \mathbf {Y} = \mathbf {H} \bm{\beta}
    \label{eq:Y}
\end{equation}
where $\bm{\beta} \in \mathbb{R}^{L \times m}$.

\subsubsection{Parameter Fitting}\label{sec:elm-parameter-fitting}
The ELM described in Section \ref{architecture} is parametrised by $\mathbf{W}$, $\mathbf{b}$ and $\bm{\beta}$. $\mathbf{W}$ and $\mathbf{b}$ are randomly initialised, and $\bm{\beta}$ is generated using training examples. Given a training set consisting of inputs $\hat{\mathbf {X}} \in \mathbb{R}^{N_{\text{train}} \times d}$ and targets $\hat{\mathbf {Y}} \in \mathbb{R}^{N_{\text{train}} \times m}$, we construct $\bm{\beta}$ as
\begin{equation}
    \bm{\beta} = \mathbf {H}(\hat{\mathbf {X}})^\dagger \hat{\mathbf {Y}}
    \label{eq:training}
\end{equation}
where $\mathbf {H}^\dagger$ is the Moore-Penrose pseudo-inverse of $\mathbf {H}$. 

% For the computation of $\bm{\beta}$ in this work, we assume invertibility of $\mathbf{H}^T\mathbf{H}$ and hence use the least-squares solution to Equation \ref{eq:training} below:

In this work, we compute $\bm{\beta}$ as follows using a Tikhonov regularisation approach:
\begin{equation}
{\boldsymbol {\beta }}= ( {\mathbf {H}}^{T} {\mathbf {H}} + 
\alpha \mathbf{I})^{-1}( {\mathbf {H}}^{T} {\hat{\mathbf {Y}}})
\end{equation}
where $\alpha=10^{-9}$ is a fixed regularisation parameter. 


