%Here we already know that the transform by a permissible blow-up is a lambda marked monomial ideal, we need to mention that it is of the same type, namely toric and commutes with fibers

\subsection{Transforms of toric \texorpdfstring{$\Lambda$}{Λ}-marked monomial ideals}

%This definition should be given more generally for lambda marked monomial ideals
\begin{definition}
    (See \cite[Section 8.1]{BM1}).
    Let $\underline{\mathcal{H}}=(M, N, P, \mathcal{H}, e)$ be a toric $\Lambda$-marked monomial ideal. The \textit{support of $\underline{\mathcal{H}}$} is defined as 
    $
    supp\underline{\mathcal{H}} := supp\underline{\mathcal{H}}_E, 
    $
    the support of the corresponding $\Lambda$-marked monomial ideal
    (see \cite[Definition 4.1.2]{OrderReductionLambdamarkedMonomialIdeals}).
    It follows from \cite[Observation 4.1.15]{OrderReductionLambdamarkedMonomialIdeals} that as sets
    $$
    supp\underline{\mathcal{H}} = \bigsqcup_{(p) \in \textrm{Spec} \, \mathbb{Z}} supp\underline{\mathcal{H}}_p,
    $$
    where $supp\underline{\mathcal{H}}_p$ is as in \cite[Section 8.1]{BM1}. 
\end{definition}

%Transforms have beend defined more generally so can be replaced
\textbf{Transforms of toric $\Lambda$-marked monomial ideals.} Let $\underline{\mathcal{H}}=(M, N, P, \mathcal{H}, e)$ be a toric $\Lambda$-marked monomial ideal. Let $\pi_D:M' \rightarrow M$ be the blowing up with centre $D$  satisfying condition (1) of the main theorem, i.e. a disjoint union of $Z_{\Delta}$'s of $M$ with fibers given by the same $\Delta$'s defining orbit closures of $M_p$. $D$ will be a \textit{permissible centre} for $\underline{\mathcal{H}}$ and the induced $\pi$ will be called \textit{permissible} if in addition, $C:=D \cap N$ has smooth fibers and $C \subset supp \underline{\mathcal{H}}$. By \cref{lemma71141}, $C$ will be a disjoint union of orbit closures of $N$.

\begin{lemma} 
    \label[lemma]{lemma71232}
    A blow-up centre $D \subset M$ satisfying condition (1) is permissible for $\underline{\mathcal{H}}$ if and only if every fiber $D_{p}$ is permissible for $(\underline{\mathcal{H}})_{p}$ (see \cite[Section 8.1]{BM1}).
\end{lemma}

\textit{Proof.} Follows from the decomposition of $supp\underline{\mathcal{H}}$ into supports of fibers. \qedsymbol

\begin{remark}
    Let $\underline{\mathcal{H}}$ be a toric $\Lambda$-marked monomial ideal and $\underline{\mathcal{H}}_E$ the corresponding $\Lambda$-marked monomial ideal. A permissible blow-up centre for $\underline{\mathcal{H}}_E$ (see \cite[Definition 4.1.5]{OrderReductionLambdamarkedMonomialIdeals}) is a permissible centre for $\underline{\mathcal{H}}$. Moreover, each permissible centre for $\underline{\mathcal{H}}$ will be a disjoint union of permissible centres for $\underline{\mathcal{H}}_E$.
\end{remark}

%We can move this definition to earlier on
\begin{definition}
    (See \cite[Definition 8.3]{BM1}).
    Let $\underline{\mathcal{H}}$ be a toric $\Lambda$-marked monomial ideal and $\pi_D: M' \rightarrow M$ be the blow-up by the permissible centre $D$. Let $\underline{\mathcal{H}}_E'=(M', N', P', \mathcal{H}',E', e')$ be the $\Lambda$-marked monomial ideal given by the sequence of permissible blow-ups defined by $D$ (see \cite[Definition 4.1.10]{OrderReductionLambdamarkedMonomialIdeals}). We define the \textit{transform} $\underline{\mathcal{H}}'$ of $\underline{\mathcal{H}}$ by $\pi$ as $\underline{\mathcal{H}}_E'$ without $E'$, i.e. the tuple $(M', N', P', \mathcal{H}', e')$. 
\end{definition}

%This lemma should be proved more generally, but we need to remark that the trasnform is a toric lambda marked monomial ideal, also that an order reduction is the same
\begin{lemma}
    \label[lemma]{lemma71235} 
    $\underline{\mathcal{H}}'$ is a toric $\Lambda$-marked monomial ideal. Moreover, for all prime ideals $(p) \subset \mathbb{Z}$, $(\underline{\mathcal{H}}')_p = (\underline{\mathcal{H}}_p)'$, i.e. taking the transform under a permissible blow-up commutes with taking the fiber then transforming as in \cite[Definition 8.3]{BM1}.
\end{lemma}

\textit{Proof.} It suffices to show the lemma when $D$ is given by a single orbit closure and $\underline{\mathcal{H}}_E'$ is the transform under a single blow-up. $M'$ is a blow-up given by star subdivision and hence corresponds to a smooth toric $\Lambda$-scheme. By \cref{lemma71141} $N'$ is a sequence of blow-ups given by star subdivisions and so is a smooth toric $\Lambda$-scheme. The closed embedding $N' \hookrightarrow M'$ is induced from an unpointed monoid scheme. It follows from the local description of $E'$ on blow-up charts $U_{\sigma'}$ given by cones $\sigma' \in \Sigma_{M'}$ that $E'$ will be the locally toric simple normal crossings divisor given by the codimension one orbit closures of $ M'$. Therefore, by the proof of \cite[Lemma 4.1.9]{OrderReductionLambdamarkedMonomialIdeals}, $P'$ is a single orbit closure of $N'$ and $\mathcal{H}'$ is an ideal given by codimension one orbit closures of $M'$ satisying the required conditions. Commuting with fibers follows from \cite[Lemma 4.1.17]{OrderReductionLambdamarkedMonomialIdeals}. \qedsymbol
\\
\\A \textit{permissible} sequence of blow-ups for $\underline{\mathcal{H}}$ will be a sequence of blow-ups
$$
M=M_0 \xleftarrow[]{\pi_1} M_1 \leftarrow \dots \xleftarrow[]{\pi_{t+1}} M_{t+1},
$$
where each $\pi_{j+1}, j = 0, \dots, t$ is a permissible blow-up for $\underline{\mathcal{H}}_j = (M_j, N_j, P_j, \mathcal{H}_j, e_j)$ and $\underline{\mathcal{H}}_{j+1} = (M_{j+1}, N_{j+1}, P_{j+1}, \mathcal{H}_{j+1}, e_{j+1})$ is the transform of $\underline{\mathcal{H}}_j$ by $\pi_{j+1}$, with $\underline{\mathcal{H}}_0 = \underline{\mathcal{H}}$. It follows from \cref{lemma71232} and \cref{lemma71235} that a sequence of blow-ups satisfying condition (1) of \cref{theorem7201} is permissible for $\underline{\mathcal{H}}$ if and only if for all prime ideals $(p)$ it induces a permissible sequence for the marked monomial ideal $\underline{\mathcal{H}}_p$ (see \cite[Definition 8.3]{BM1}).

\begin{definition}
    \label[definition]{definition71238} 
    A \textit{resolution of singularities} of $\underline{\mathcal{H}}$ is a sequence of permissible blow-ups such that $supp \underline{\mathcal{H}}_{t+1} = \emptyset$. It follows from the decomposition of $supp \underline{\mathcal{H}}$ into its fibers that a sequence of blow-ups satisfying condition (1) of \cref{theorem7201} is a resolution for $\underline{\mathcal{H}}$ if and only if it is a resolution for each 
    ${\underline{\mathcal{H}}}_p$ (\cite[Definition 8.3]{BM1}). Moreover, an order reduction for $\underline{\mathcal{H}}_E$ (see \cite[Definition 4.1.10]{OrderReductionLambdamarkedMonomialIdeals}) is a resolution for $\underline{\mathcal{H}}$ and vice versa.
\end{definition}




