Next, we consider the case where $|G|$ is odd but not a cycle.
Note that we need a different strategy here because the cycle we used in \cref{lem:cartesian-K2-even} (left side of \cref{fig:cartesian-K2-even}) only exists when~$|G|$ is even.

\begin{restatable}{lemma}{lemmacartesianoddnoncycle}\label{lem:cartesian-K2_odd_noncycle}
	Let $G$ be Hamiltonian with $|G|=:k$ odd and $G\neq C_k$. 
	Then $G \bx K_2 \notin \mH$.
\end{restatable}

\begin{proof}
	For the sake of contradiction, assume that $G \bx K_2 \in \mH$.
	Note that $G$ is a cycle of length $k$ with at least one additional edge $e=\{u,v\}$. Since~$k$ is odd, the distance between~$u$ and $v$ along the cycle is even in one direction and odd in the other direction.
	Therefore, we can renumber the vertices of $G$ such that there is an edge between $v_0$ and $v_j$, where~$j\in \{3, \dots, k-2\}$ is odd.

	As a first step, we show the following claim (under the assumption that $G \bx K_2 \in \mH$).

	\begin{claim}
		For every $i \in \{0, \dots, k-1\}$, there is an edge between $v_i$ and $v_{i+j \bmod k}$.
	\end{claim}

	\begin{proof}[Proof of the claim.]
		We consider cycles of the form
		\begin{equation*}
			C^{(i)}:=(u_i, u_{i+1 \bmod k}, \dots, u_{i+k-1 \bmod k}, v_{i+k-1 \bmod k}, v_{i+k-2 \bmod k}, \dots, v_i)
		\end{equation*}
		for $i \in \{0, \dots, k-1\}$ (as illustrated in the middle and on the right of \cref{fig:cartesian-K2-even}).

		Given an edge $e=\{u,v\}$, we say that the distance of vertex $w$ to $e$ is $\min\{d(u,w), d(v,w)\}$. 
		We say that an edge $e$ is a \emph{symmetry edge of a Hamiltonian cycle $C$} if it is contained in~$C$ and, for every $l \in \{0, \dots, k-1\}$, the two vertices that have distance $l$ to $e$ in~$C$ are adjacent in $G\bx K_2$.
		Note that $\{u_i, v_i\}$ and $\{u_{i+k-1 \bmod k}, v_{i+k-1 \bmod k}\}$ are symmetry edges of $C^{(i)}$.
		Moreover, we argue that there are no other symmetry edges of $C^{(i)}$: To see this, fix some other edge~$e$ of~$C^{(i)}$, w.l.o.g., we let $i=0$ and $e=\{v_p, v_{p+1}\}$ for some $p\in\{0, \dots, k-2\}$.
		Since~$k$ is odd, we have $d(v_0, v_p)=p \neq k-p -2 = d(v_{k-1}, v_{p+1})$. Without loss of generality, let $p<k-p -2$, i.e., $p\leq (k-1)/2 -2$ and set $l:=p+1$.
		Then the two vertices at distance $l$ to $e$ are $u_0$ and~$v_{2p+2}\in \{v_{p+1}, \dots, v_{k-1}\}$. Since these are non-adjacent, $e$ is not a symmetry edge of $C^{(0)}$.

		Since we assume that $G\bx K_2 \in \mH$, there is an automorphism mapping $C^{(0)}$ to $C^{(i)}$ for every $i\in \{0, \dots, k-1\}$.
		Note that this automorphism maps the symmetry edges of~$C^{(0)}$ to the symmetry edges of~$C^{(i)}$.
		Recall that there is an edge between $v_0$ and $v_j$, and between $u_0$ and~$u_j$.
		This means that the end vertices of the symmetry edge $\{u_0, v_0\}$ of $C^{(0)}$ are adjacent to the vertices at distance $j$ in the cycle, where the cycle-distance here is measured such that the symmetry edge is not used.
		If there is also an edge between $v_{k-1}$ and $v_{k-1-j}$, the existence of the automorphisms mapping $C^{(0)}$ to $C^{(i)}$ for every $i \in \{1, \dots, k-1\}$ immediately implies that, for every $i$, $v_i$ is adjacent to $v_{i+j\bmod k}$ and $v_{i-j\bmod k}$, i.e., the claim holds.
		If there is no edge between  $v_{k-1}$ and $v_{k-1-j}$, 
		the existence of the automorphism mapping $C^{(0)}$ to~$C^{(j+1)}$ implies~$v_{j+1}$ is not connected to $v_{2j+1 \bmod k}$ as $v_0$ is connected to $v_j$. Iteratively, the automorphism from $C^{(0)}$ to $C^{(l(j+1))}$ yields $v_{l(j+1) \bmod k}$ and $v_{(l+1)(j+1)-1 \bmod k}$ are connected if and only if $l$ is even. 
		Thus, for $l=k-1$ we derive $v_{k-j-1}$ and $v_{k-1}$ are connected, contradicting our assumption.
		This completes the proof of the claim.
	\end{proof}

	Now that we have established the claim, we construct a second Hamiltonian cycle and argue that it cannot be mapped via an automorphism to $C^{(0)}$.
	We set
	\begin{equation*}
		C= (u_0, v_0, v_1, u_1, u_2 \dots, v_{j-1}, v_j, v_{j+1}, \dots v_{k-1}, u_{k-1}, \dots, u_j),
	\end{equation*}
	where we have used that $j$ is odd. This cycle is illustrated in \cref{fig:cartesian-K2_odd_noncycle}.

	Note that the cycle $C^{(0)}$ has the property that every vertex $v$ is adjacent to some other vertex $v'$ with $d_{C^{(0)}}(v,v')=j$.
	We argue that vertex $w=u_{(j+1)/2}$ does not have this property in $C$: 
	If $j \bmod 4=1$ (i.e., $(j+1)/2$ is odd), the two adjacent vertices to $w$ are $v_1$ and~$v_{j+2 \bmod k}$ (the latter is $v_{j+2}$ if $j+2<k$ or it is $v_0$ in case $j+2=k$, note that $j+1=k$ is not possible as $k$ and $j$ are both odd). Both of these vertices are not adjacent to $w$.
	In case $j \bmod 4=3$ (i.e., $(j+1)/2$ is even), the two vertices at distance $j$ in $C$ are $v_0$ and $v_{j+1}$, both of which are not adjacent to $w$.
	This proves that there is no automorphism mapping $C$ to~$C^{(0)}$, which gives a contradiction.
