			% Edges of the outer cycle
			\foreach \i in {1,...,9} {
				\pgfmathtruncatemacro{\nexti}{mod(\i,9)+1}
				\draw[very thin, gray] (B\i) -- (B\nexti);
			}
			% Connecting the two cycles
			\foreach \i in {1,...,9} {
				\draw[very thin, gray] (A\i) -- (B\i);
			}
			%the Hamiltonian cycle
			\draw[very thick, blue] (A1) to (B1) to (B2) to (A2) to (A3) to (B3) to (B4) to (A4) to (A5) to (B5) to (B6) to (B7) to (B8) to (B9) to (A9) to (A8) to (A7) to (A6) to (A1);
