The following lemma is a direct consequence of the definition and shows that, by suitably choosing $\vec{a}$, many desirable values for $\mu(C)$ for a zigzag cycle $C$ can be achieved.

\begin{restatable}{lemma}{lemzigzag}\label{lem:zigzag_mu}
	Let $G$ be a graph with $K$-$l$-layer structure, where $l\geq 5$ is odd, let $k:=|K|$, and let $C$ be the $C_K$-$\vec{a}$-zigzag cycle for some choice of $C_K$ and $\vec{a}$. Then we have
	\begin{equation*}
	\mu(C)=2k-1+2\sum_{i=1}^{(l-3)/2} (a_i+1).
	\end{equation*}

	In particular, we obtain that $\mu(C)$ is odd. 
	Even further, for any odd number $\mu^*\in \N$ with~$2k-1+(l-3)\leq \mu^* \leq 2k-1+(l-3)(k-1)$, there is a choice for $\vec{a}$ such that the~$C_K$-$\vec{a}$-zigzag cycle $C$ fulfills~$\mu(C)=\mu^*$.
\end{restatable}
\begin{proof}
	Note that the length of the green segment at the top is $k$ and the length of the green segment at the bottom is $k-1$.
	Moreover, the length of each pink segment is $a_i+1$ and the length of the following orange segment is also $a_i+1$.
	Together, we obtain that $\mu(C)$ is as stated.
	The given bounds follow from $0\leq a_i \leq k-2$ for all $i \in \{1, \dots (l-3)/2\}$ and from the observation that, increasing one of the $a_i$ by 1, increases the value of $\mu(C)$ by 2.
\end{proof}

Now, we have all the prerequisites in place to prove the main result of this subsection.

\begin{restatable}{theorem}{layerstructuretheorem}\label{thm:layerstructure}
	Let $G \in \mH$ be a graph of odd order that has $K$-$l$-layer structure and let~$k:=|K|$.
	Assume that one of the following conditions holds
	\begin{enumerate}
		\item $k,l\geq 7$ and $\kappa(G)\geq 5$
		\item $k,l \geq 5$ and, for every prime $p$ with $p|n:=|G|$, we have $p|\kappa(G)$.
	\end{enumerate}
	Then~$K$ is isomorphic to $C_k$ or $K_k$.
\end{restatable}

\begin{proof}
	The strategy is to show that, for every Hamiltonian cycle $C_K$ of $K$, we have \hbox{$\kappa(C_K) = k$}. 
	By~\cite[Section~1.4]{GRE24}, this implies that $K$ is the Cayley graph of a cyclic group and the generating set contains an element of order $k$.
	The assertion then follows from Theorem~\ref{thm:cyclic_generator}.

	Fix a Hamiltonian cycle $C_K$ of $K$.
	To prove that $\kappa(C_K) = k$, we first show the following claim.
	\begin{restatable}{claim}{zigzagclaim}\label{claim:zigzag_multiple}
	There is a choice for~$\vec{a}$ such that the~$C_K$-$\vec{a}$-zigzgag cycle $C$ fulfills that $\mu(C)$ is a multiple of $\alpha:=n/\kappa(G)$.
	\end{restatable}
	\begin{proof}[Proof of \cref{claim:zigzag_multiple}]
		Since $n$ is odd, $\alpha$ is odd as well.
		By \cref{lem:zigzag_mu}, it suffices to show that there is some odd $m \in \N$ such that $m \alpha \in [\mu_{\text{min}}, \mu_{\text{max}}]$, where
		$\mu_{\text{min}}:=2k-1+l-3$ and~$\mu_{\text{max}}=2k-1+(l-3)\cdot(k-1)=(l-1)(k-1)+1$.

		First, assume that condition (1) in the Theorem statement is fulfilled.
		Note that then $\alpha=n/\kappa(G)\leq n/5$. We have
		\begin{align*}
			\mu_{\text{max}}-\mu_{\text{min}}=(l-3)\cdot (k-2)
			\geq \frac{4}{7}l \cdot \frac{5}{7}k
			= \frac{20}{49} n \geq \frac{2}{5} n \geq 2 \alpha.
		\end{align*}
		In other words, the interval $[\mu_{\text{min}}, \mu_{\text{max}}]$ contains at least two multiples of $\alpha$, in particular an odd multiple, which completes the proof in case that condition (1) holds.

		Now, assume that condition (2) holds, but (1) does not.
		This means that one of $k,l$ equals~5, or that $\kappa(G)=3$ (note that $k,l,\kappa(G)$ are odd and $\kappa(G)=1$ is not possible, because there is some prime number that divides $\kappa(G)$).
		We begin with the case that one of $k,l$ equals 5.
		Then $5|n$ so that~$\kappa(G)=5m'$ for some odd $m'\in \N$ such that $\alpha \cdot m' = n/5$.
		We show that for $m=3m'$, we have $m\alpha=3m'\alpha=3n/5=3kl/5 \in [\mu_{\text{min}},\mu_{\text{max}}]$. For this, note that	
		\begin{align*}
			\mu_{\text{min}}=2k+l-4 \leq 3 \max(k,l) \leq \frac{3}{5} kl
			\leq \frac{4}{5} k \cdot \frac{4}{5} l
			\leq (k-1)(l-1)+1=\mu_{\text{max}}.
		\end{align*}
		Now, it only remains to investigate the case in (2) where $\kappa(G)=3$.
		Since every prime number that divides $n=kl$ also divides $\kappa(G)$, note that $\kappa(G)=3$ is only possible if $k$ and $l$ are powers of~3.
		In particular, $k,l\geq 9$.
		If $k=l=9$, we have $\alpha=27$, $\mu_{\text{min}}=23, \mu_{\text{max}}=65$, so that the assertion holds with $m=1$.
		Therefore, assume that one of $k,l$ is greater than 9, i.e., at least~27.
		Note that then
		\begin{equation}\label{eq:mumax}
			\mu_{\text{max}}\geq (l-3)(k-1)\geq \frac{6}{9}l \cdot \frac{7}{9} k \geq \frac{1}{3} kl = \frac{1}{3} n \geq \alpha
		\end{equation}
		and	
		\begin{align}\label{eq:3mumin}
			3\cdot \mu_{\text{min}}&=3(2k-1+l-3)=6k+3l-12\leq 6k+3l\nonumber\\ 
			&\leq  9 \max(k,l) - 3\left(\max(k,l)-\min(k,l)\right) \leq kl-k-l+1=\mu_{\text{max}},
		\end{align}
		where the last inequality holds for $\max(k,l)\geq 27$ and $\min(k,l)\geq 9$.
		The inequalities \eqref{eq:mumax} and \eqref{eq:3mumin} together show that one can choose $m$ to be a power of~3.
		This completes the proof of the claim.
	\end{proof}
	Since $G\in \mH$, every Hamiltonian cycle of $G$, in particular~$C$, is $\kappa(G)$-symmetric.
	Therefore, rotating $C$ by a multiple of~$\alpha$ defines an automorphism of~$G$.
	Together with \cref{claim:zigzag_multiple}, this means that~$C$ can be rotated by $\mu(C)$ (in counter-clockwise direction in \cref{fig:zigzag}).
	This maps the first layer of $G$ bijectively to the last, inducing an automorphism of $K$.
	More precisely, $v_{0,j}$ is mapped to~$v_{l-1,j+1 \bmod k}$. 
	The induced automorphism of $K$ then maps $v_j$ to~$v_{j+1 \bmod k}$, i.e., it rotates~$C_K$ by 1. Therefore, $\kappa(C_K)=k$.
\end{proof}

