\begin{restatable}{lemma}{lemmacayleyevenlthree}\label{lemma:l=3}
	Let $\Gamma$ be an abelian group of even order with generating set $S$ and~${G= \Cay(\Gamma,S)}$. Suppose that there exists an $s \in S$ such that \(l = |\Gamma:\langle S \setminus \{\pm s\} \rangle| =3.\) Then $G \notin \mH$.
\end{restatable}

\begin{proof}
	As in the proof of \cref{lemma:l=2}, let $S' = S \setminus \langle \pm s \rangle$, $K:=\Cay(\langle S' \rangle, S')$ and ${k = |K|}$. Then~$G$ has a $K$-$l$-layer structure.
	Since $|\Gamma|=lk=3k$ is even, we obtain that $k = 2k'$ for some~\(k' \in \N\). The case $k' = 1$ is covered by Lemma~\ref{lemma:small-groups}, so assume $k' \geq 2$. 
	Consider the Hamiltonian cycle $C$ depicted in Figure~\ref{fig:graphenl=3_kreis}. 
	Since $|G|$ is even, also $\kappa(G)$ is even by Lemma~\ref{lemma:divisibilitylemma}.
	Thus, $C$ is $2$-symmetric. 
	The corresponding rotation by $3k'$	maps the edge~$\{v_{k'}, u_{k'}\}$ to~$\{w_{k-1},u_0\}$. 
	Since the only neighbor of $u_0$ on the third layer is $w_0$, this is a contradiction.
\end{proof}

