	\begin{prop}
		Let $\Gamma$ be a special mixed graph. For $i\geq 2$, let $n_i$ be the number of $i$-cliques containing a negative vertex. Then, the Poincaré series of $\mf a(\Gamma)$, i.e., the Hilbert series of $H^\bu(\mf a(\Gamma))$, is \[\sum_{i\geq 0}\dim H^i(\mf a(\Gamma))z^i=\operatorname{C_{\Gamma^\circ}}(z)+\sum_{i\geq 2}n_iz^i\]
		where $C_\Delta(z)$ denotes the clique polynomial of the simplicial graph $\Delta$.
	\end{prop}
	\begin{proof}
		Consider the natural surjection $\pi^\ast:H^\bu(\mf a(\Gamma))\to H^\bu(\mf a(\Gamma^\circ))$. Recall that the restricted cohomology of $\mf a(\Gamma^\circ)$ is isomorphic to the Chevalley-Eilenberg cohomology of the ordinary Lie subalgebra $\li_{\Gamma^\circ}$ of $\mf a(\Gamma^\circ)$ generated by its elements of degree $1$ (cf. the restrictification functor in \cite{sb_kosz}).  It follows that \[\sum_{i\geq 0}\dim H^i(\mf a(\Gamma))z^i=\sum_{i\geq 0}\left(\dim H^i(\mf a(\Gamma^\circ))+\dim(\ker\pi^\ast)_i\right)z^i.\]
		From the computations performed above, we get $\dim (\ker\pi^\ast)_i=n_i$, which gives the desired formula, as the Poincaré polynomial of an ordinary RAAG Lie algebra is the clique polynomial of the defining graph. 
	\end{proof}
	The next result thus follows at once. 
\begin{thm}
	Let $\Gamma$ be a special mixed graph, and let $\mf a(\Gamma)$ be the associated T-RAAG Lie algebra. Then, the Poincaré series of $\mf a(\Gamma)$ is the clique polynomial of the underlying simple graph $\bar\Gamma$.
\end{thm}


	Since the restricted envelope $u(\mf a(\Gamma))$ is Koszul, it follows from Froberg's formula that the Hilbert series of $u(\mf a(\Gamma))$ is
%	\begin{equation}\label{eq:hilbu}
%		\sum_{i\geq 0}\dim (u(\mf a(\Gamma))_i) z^i=\left(\operatorname{C_{\Gamma^\circ}}(-z)+\sum_{i\geq 2}(-1)^in_iz^i\right)^{-1}\end{equation}where the $n_i$'s are as above.

\begin{equation}\label{eq:hilbu}
		\sum_{i\geq 0}\dim (u(\mf a(\Gamma))_i) z^i=C_{\bar\Gamma}(-z)^{-1}
	\end{equation}


	By the main theorem of Petrogradsky \cite{restrwitt}, the Hilbert series of the T-RAAG $\mf a(\Gamma)$ is 
	\[\sum_{i\geq 1}\dim\mf (a(\Gamma)_i)z^i=\mathcal{L}_2(\phi):=\sum_{n\geq 1}\frac{\mu_2(n)}{n}\ln \phi(z^n)\]
	where $\phi$ is the formal power series of the Hilbert series (\ref{eq:hilbu}) of $u(\mf a(\Gamma))$, and $\mu_2$ is the mod-$2$ M\"obius function described in \S \ref{sec:witt}. 

	\section{Subalgebras of T-RAAGs}
	In this section we provide a complete characterization of Bloch-Kato T-RAAGs in terms of the structure of the defining graph. 

	To begin with, we exclude non-special graphs from the discussion.

	\begin{prop}\label{prop:nonspecial}
		Let $\Gamma$ be a non-special mixed graph. Then, $\mf a(\Gamma)$ contains a non-quadratic, standard subalgebra. 
	\end{prop}
	\begin{proof}
		Since $\Gamma$ is not special, it contains an induced subgraph $\Lambda$ on three vertices $u,v,w$ such that $\vec{uv}\in D$ and either $\vec{vw}\in D$ or $\overline{vw}\in E\setminus D$. We put $\theta=1$ in the first case, and $\theta=0$ otherwise, so that $[v,w]=\theta v\2$. 
		Consider the subalgebra $\mf b$ of $\mf a(\Gamma)$ generated by the vertices of $\Lambda$. We can assume that $\mf b$ is quadratic, and hence isomorphic to $\mf a(\Lambda)$. 

		Let $\mf m$ be the subalgebra of $\mf a(\Lambda)$ generated by $u+w$ and $v$. Since $[u+w,v]=u\2+\theta v\2$, the quadratic cover $\q\mf m$ is a free restricted Lie algebra, and hence it is a proper extension of $\mf m$ as $[u+w,v\2]=0$.
	\end{proof}




		\begin{exam}\label{ex:nonBKgraphs}
		Let $\Gamma=(V,E,D,o,t)$ be a special mixed graph, and let $\mf a(\Gamma)$ be the associated T-RAAG over $k$.

		\begin{enumerate}
			\item\label{ex:LambdaS} Let $\Gamma=\Lambda_s$, i.e., $V=\{1,2,3\}$ and $E=D=\{\vec{12},\vec{32}\}$. Denote the canonical generator of $\mf a(\Lambda_s)$ corresponding to $i\in V$ by $x_i$. 

			%		\begin{center}
				%				\begin{tikzpicture}[->, node distance=2cm, draw]
					%				\node (1) {1};
					%				\node (2) [right of=1] {2};
					%				\node (3) [right of=2] {3};
					%				
					%				\draw (1) -- (2);
					%				\draw (3) -- (2);
					%			\end{tikzpicture}
				%		\end{center}

			Consider the subalgebra $\mc b$ generated by $x_1+x_3$ and $x_2$. Then, \[[x_2,x_1+x_3]=x_1\2+x_3\2\qquad\mbox{and}\qquad(x_1+x_3)\2=x_1\2+x_3\2+[x_1,x_3],\] proving that $\q\mf b$ is free. Since for $i\in \{1,3\}$ \[[x_2\2,x_i]=[x_2,[x_2,x_i]]=[x_2,x_i\2]=[[x_2,x_i],x_i]=[x_i\2,x_i]=0,\] it follows that $[x_2\2,x_1+x_3]=0$, and hence $\mf b$ is not quadratic. Notice that, for RAAG Lie algebras associated to simple graphs, the existence of non-quadratic standard subalgebras generated by $2$ elements is prevented by \cite{sb_kosz}.
			\item 	Let $\bar\Gamma$ be the square graph, i.e. $V=\{1,2,3,4\}$ and $E=\{\{1,2\},\{2,3\},\{3,4\},\{1,4\}\}$.
			\begin{enumerate}
				\item\label{ex:square} If $D=\emptyset$, then the subalgebra $\mf b$ of $\mf a(\Gamma)$ generated by $x_1+x_2,x_3,x_4$ is not quadratic. Indeed, the only degree-$2$ relation of $\mf b$ is $[x_3,x_4]=0$, and one has $[[x_1+x_2,x_3],x_4]=0$.
				\item Suppose that $\vec{12}\in D$. Since the graph $\Gamma$ is special, also $\vec{32}\in D$. Then the subgraph $\Lambda$ on $\{1,2,3\}$ is the same mixed graph of (\ref{ex:LambdaS}), and $\mf a(\Lambda_s)$ is a standard subalgebra of $\mf a(\Gamma)$.
			\end{enumerate}
			\item Suppose that $\bar\Gamma=P_4$ is the path of length $3$, i.e., $V=\{1,2,3,4\}$ and $E=\{\{2,3\},\{3,4\},\{4,1\}\}$. 
			\begin{enumerate}
				\item If $D=\emptyset$, then, the same computations as in (\ref{ex:square}) prove that the subalgebra $\mf b$ of $\mf a(\Gamma)$ generated by $x_1+x_2,x_3,x_4$ is not quadratic. 
				\item If $D$ is nonempty, then either $\Gamma$ contains an induced $\Lambda_s$, or $V_-\subseteq\{1,2\}$. In the latter case, let $\theta:V\to k$ be the associated signature. 
				One has \begin{align*}
					[[x_1+x_2,x_3],x_4]&=[[x_1,x_3]+\theta(x_2)x_3\2,x_4]=\\
					&=[[x_1,x_4],x_3]+[x_1,[x_3,x_4]]+\theta(x_2)[x_3\2,x_4]=\\
					&=\theta(x_1)[x_4\2,x_3]+0+0=0
				\end{align*}


				On the other hand, the only degree-$2$ relation involving the elements $x_1+x_2,x_3,x_4$ are $[x_1,x_2]=x_i\2$, for $\theta(x_i)=0$ ($i=1,2$), and  $[x_3,x_4]=0$, proving that the standard subalgebra generated by those elements is not quadratic.
