	It follows that if $\Gamma$ is not a Droms mixed graph, then $\mf a(\Gamma)$ contains a non-quadratic standard subalgebra. 


	\begin{lem}\label{lem:simpleBK}
		If $\Gamma$ is a simple graph, i.e., $D=\emptyset$, then all standard restricted subalgebras of $\mf a(\Gamma)$ are RAAG Lie algebras if, and only if, $\Gamma$ is a Droms graph. 
	\end{lem}
	\begin{proof}
		Let $\li_\Gamma$ be the ordinary RAAG Lie algebra over $k$. The restrictification of $\li_\Gamma$ is $\mf a(\Gamma)$, which is Bloch-Kato precisely when so is $\li_\Gamma$. Hence, the result follows from \cite[Ex. 4.4]{sb}.
	\end{proof}

%	Moreover, Example \ref{ex:nonBKgraphs} shows that $\mf a(\Gamma)$ has non-quadratic, standard subalgebras whenever $\Gamma$ is not a Droms mixed graph.
	\subsection{The prime field $\F_2$}
	%	\begin{lem}
		%		Let $\Gamma$ be a special graph, and let $\mf b$ be a standard subalgebra of $\mf a(\Gamma)$. If $v\notin \mf b$ is a positive vertex, then $\mf b\cap \gen v=0$.
		%	\end{lem}

	For $k=\F_2$ the prime field of characteristic $2$, the situation is identical to that of the group theoretic one given in \cite{sb_droms}.

	\begin{prop}
		If $\Gamma$ is a mixed graph and $\mf a(\Gamma)$ is the associated T-RAAG restricted Lie algebra over the prime field $\mathbb F_2$, then the following are equivalent: 
		\begin{enumerate}
			\item $\Gamma$ is a mixed Droms graph;
			\item All standard restricted subalgebras of $\mf a(\Gamma)$ are T-RAAGs;
			\item $\mf a(\Gamma)$ is weakly BK, i.e., all standard restricted subalgebras of $\mf a(\Gamma)$ are quadratic restricted Lie algebras;
			\item $\mf a(\Gamma)$ is BK, i.e., all standard restricted subalgebras of $\mf a(\Gamma)$ are Koszul restricted Lie algebras;
			\item The cohomology ring of $\mf a(\Gamma)$ is universally Koszul.
		\end{enumerate}
	\end{prop}
	\begin{proof}
		The equivalence (4)$\iff$(5) is clear, and obviously (4) implies (3). Example \ref{ex:nonBKgraphs}, together with Proposition \ref{prop:nonspecial}, shows that (3) implies (1). Moreover, by Corollary \ref{cor:TRAAGkosz}, (2) implies (4). It remains to prove that (1) implies (2) .
		The proof is based on that of the group theoretic analogue \cite{sb_droms}. Suppose that $\Gamma$ is a Droms mixed graph. We argue by induction on the number of its vertices $\abs V$. 

		The case $\abs{V}=1$ is trivial, so suppose that $\abs V>1$. If $\Gamma$ is disconnected, say $\Gamma=\Gamma_1\sqcup \Gamma_2$, then $\mf a(\Gamma)$ is the free product $\mf a(\Gamma)=\mf a(\Gamma_1)\amalg\mf a(\Gamma_2)$ of restricted Lie algebras. In particular, the cohomology ring of $\mf a(\Gamma)$ is the direct sum of those of the $\mf a(\Gamma_i)$'s, and hence, by induction, it is universally Koszul, proving that $\mf a(\Gamma)$ is BK. From the Kurosh subalgebra theorem \cite{sb}, $(3)$ follows. 

		Now suppose that $\Gamma$ is connected, and hence a cone $\nabla_{\theta'}(\Gamma')$, where $\theta'$ is the signature of $\Gamma'$ and $v$ is the tip of the cone, i.e., $V=V(\Gamma')\cup \{v\}$. The unique signature $\theta$ for $V$ is the extension of $\theta'$ with $\theta(v)=0$.
		Hence, $\mf a(\Gamma)$ is the semidirect product $\gen v\rtimes \mf a(\Gamma')$. By induction, we suppose that all the standard subalgebras $\mf c$ of $\mf a(\Gamma')$ are T-RAAG restricted Lie algebras with signature $\theta'\vert_{\mf c}$. Let $\pi:\mf a(\Gamma)\to \mf a(\Gamma')$ be the natural projection.
		% Since $\mf a(\Gamma)$ is a Koszul restricted Lie algebra, its bigraded cohomology ring is concentrated on the diagonal, and isomorphic to the quadratic dual $\mf a(\Gamma)^!$, which is then a twisted extension of $\mf a(\Gamma')$ (see \cite{MPPT}) {\color{red} Is it a twisted extension? IT IS NOT!} By induction, $\mf a(\Gamma')$ is BK with universally Koszul cohomology ring, and hence so is $\mf a(\Gamma)$ by \cite[Prop. 31]{MPPT}. 
		If $\mf b$ is a standard subalgebra of $\mf a(\Gamma)$, then the image $\pi(\mf b)$ in $\mf a(\Gamma')$ is a standard subalgebra of $\mf a(\Gamma')$, and hence a T-RAAG Lie algebra by induction, i.e., there exists a mixed graph $\Lambda=(V(\Lambda),E(\Lambda),D(\Lambda),o_\Lambda,t_\Lambda)$ such that $\pi(\mf b)\simeq \mf a(\Lambda)$, with signature $\theta'\vert_{\pi(\mf b)}$. Put $V(\Lambda)=\{v_1,\dots,v_r\}$, and let $x_i\in \mf b$ such that $\pi(x_i)=v_i$. 
		For all $i$, since $\pi\vert_{\mf a(\Gamma')}$ is the identity map, there exists a scalar $\alpha_i\in \F_2$ such that $v_i+x_i=\alpha_i v$. 
		We need to show that the assignment $\sigma(v_i)=v_i+\alpha_iv$ extends to a restricted Lie map $\pi(\mf b)\to \mf b$ giving a split exact sequence 
		\begin{equation}\label{eq:ses}
			\begin{tikzcd}
				0 \arrow{r} & \mf b \cap \gen v \arrow{r} & \mf b \arrow{r}{\pi} & \pi(\mf b) \arrow{r} \arrow[bend left=33, dashed]{l}{\sigma} & 0
			\end{tikzcd}
		\end{equation}

		Let $v_i$ and $v_j$ be two different vertices of $\Lambda$. There are two cases to consider. 

		(i) If $\e{v_iv_j}\in E(\Lambda)$, then $[v_i,v_j]=0$ and $\theta'(v_i)=\theta'(v_j)=0$. Hence, $[v_i,v]=[v_j,v]=0$, proving that $[\sigma(v_i),\sigma(v_j)]=0$. 

		(ii) If $\vec{v_iv_j}\in D(\Lambda)$, then $\theta'(v_i)=0$ and $\theta'(v_j)=1$. 
		One has \[[v_i+\alpha_iv,v_j+\alpha_j v]=v_i\2+\alpha_i v\2.\]
		Since $\alpha_i\in \F_2$, one has $\alpha_i^2=\alpha_i$, and hence $[\sigma(v_i),\sigma(v_j)]=\sigma(v_i)\2$.

		Therefore, $\sigma:\pi(\mf b)\to \mf b$ is a homomorphism, and $\pi\sigma$ is the identity on $\pi(\mf b)$, proving that the exact sequence (\ref{eq:ses}) splits. We deduce that $\mf b=(\mf b\cap \gen v)\rtimes \pi(\mf b)$ is a T-RAAG Lie algebra with canonical generators $x_i$ ($i=1,\dots,r$), and possibly $x\in \mf b_1\cap \gen v$. 
		Finally, the map $\tilde\theta(x_i)=\theta'(v_i)$, $\tilde\theta(x)=0$, for $x\in \mf b_1\cap \gen v$, is a signature for the defining graph of $\mf b$ and is the restriction of $\theta$. Since $\mf b$ is a T-RAAG Lie algebra, we deduce that $\mf a(\Gamma)$ is BK, and hence its cohomology ring is universally Koszul.
	\end{proof}

