		For this we introduce a new class of restricted Lie algebras interpolating between RAAG and RACG Lie algebras.

		If $\Gamma$ is a graph, and $\theta:V\to \F_2$ is a vertex labelling of $\Gamma$, the \textbf{extended right-angled} Lie algebra (or ERA) over $k$ associated to the pair $(\Gamma,\theta)$ is the restricted Lie $k$-algebra with presentation \[\mf e(\Gamma,\theta)=\pres{V}{\theta(v)v\2, [v_1,v_2]:\ v\in V,\ \{v_1,v_2\}\in E}\]

		For instance, if $\theta\equiv 1\in \F_2$, then $\mf e(\Gamma,1)=\mf c(\Gamma)$. On the contrary, when $\theta\equiv 0$, then $\mf e(\Gamma,0)$ is the (restricted) RAAG Lie algebra $\mf a(\Gamma)$.


		\begin{prop}\label{prop:ERAembed}
			 Let $\Gamma=(V,E)$ be a simple graph and $\theta:V\to \F_2$ a $2$-labelling of $\Gamma$. Let $\mf e(\Gamma)$ be the associated ERA Lie $k$-algebra.
			\begin{enumerate}
				\item If $W\subset V$, then the subalgebra of $\mf e(\Gamma)$ generated by $W$ is the ERA Lie algebra associated to the induced subgraph spanned by $W$, with signature $\theta\vert_W$; 
				\item The ERA Lie algebra $\mf e(\Gamma)$ is Koszul.
			\end{enumerate} 
		\end{prop}
		\begin{proof}
			Let $W$ be a proper subset of $V$. Clearly, the map induced by $v\in W\mapsto v$ and $v\in V\setminus W\mapsto 0$ is a retraction of that induced by the inclusion $W\hookrightarrow V$; hence (1) follows.

			We argue by induction on the number of vertices.
			If $\Gamma$ is complete, then $\mf e(\Gamma)$ is the abelian restricted Lie algebra $k^n\times \mf k^m$, where $n=\abs{\theta^{-1}(1_{\F_2})}$. In particular, $H^\bu(\mf e(\Gamma))$ is the symmetric tensor product of a symmetric algebra and an exterior algebra, which is thus Koszul. Moreover, the subalgebra of $e(\Gamma)$ generated by $W$ is the ERA Lie algebra on the induced subgraph of $\Gamma$ spanned by $W$. 

			So, suppose $\Gamma$ is not complete, and let $v\in V\setminus W$. Denote by $\Gamma_v$ the induced subgraph of $\Gamma$ spanned by the vertices $\neq v$. By induction, $\mf e(\Gamma_v)$ is a Koszul restricted Lie algebra.

			If $v$ is a central vertex of $\Gamma$, then $\mf e(\Gamma)\simeq \mf e(\Gamma_v)\times \gen{v}$, proving that $\mf e(\Gamma_v)$ naturally embeds into $\mf e(\Gamma)$. Moreover, $H^\bu(\mf e(\Gamma))$ is the symmetric tensor product of $H^\bu(\mf e(\Gamma_v))$ and $H^\bu(\gen{v})$ --- which are generated in degree $1$ by induction---, implying that $\mf e(\Gamma)$ is Koszul by \cite{pp}. 

			If $v$ is not a central vertex, let $\Delta$ be the induced subgraph of $\Gamma$ spanned by the link of $v$, i.e., $V(\Delta)$ consists of the elements $v'\in V\setminus \{v\}$ such that $\{v,v'\}\in E$. Let $w$ be a vertex of $\Gamma_v$ that does not lie in $\Delta$. 
			By induction, $\mf e(\Delta)$ naturally embeds into $\mf e(\Gamma_v)$. Moreover, the map $\phi:\mf e(\Delta)\to \mf e(\Gamma_v)$ defined on the canonical generators by $\phi(u)=[w,u]$ is a derivation of degree $1$, and the associated HNN-extension is isomorphic with $\mf e(\Gamma)$. This proves both that $\mf e(\Gamma_v)$ naturally embeds into $\mf e(\Gamma)$, and that, by induction and Theorem \ref{thm:hnn}, $\mf e(\Gamma)$ is Koszul.
		\end{proof}

		This allows us to compute the cohomology ring of ERA Lie algebras. 

		\begin{cor}
			Let $\Gamma=(V,E)$ be a finite simple graph, and let $\theta:V\to \F_2\subseteq k$ be a vertex $2$-labelling of $\Gamma$.
			Then, \[H^\bu(\mf e(\Gamma,\theta),k)\simeq k[V^\ast]/(v^\ast w^\ast, (u^\ast)^2:\ \{v,w\}\notin E,\ v\neq w,\ u\in V\text{ s.t. } \theta(u)=0)\]
		\end{cor}

		In particular, for $\theta\equiv 1$, we get the cohomology ring of RACG Lie algebras.

		\begin{cor}
			Let $\Gamma=(V,E)$ be a simple graph. Then, the cohomology ring of $\mf c(\Gamma)$ is the Stanley-Reisner ring of $\Gamma$, i.e., \[H^\bu(\mf c(\Gamma),k)=\mf c(\Gamma)^!\simeq k[\Gamma]:= k[V^\ast]/(v^\ast w^\ast:\ \{v,w\}\notin E, v\neq w)\]
		\end{cor}

		Since the RACG Lie algebras (of non-empty graphs) contain non-trivial torsion elements, their cohomological dimension is infinite. 

