		\begin{thm}
			Let $\Gamma$ be a graph with a $2$-labelling map $\theta:V\to \F_2$. Then the following are equivalent: 
			\begin{enumerate}
				\item $\Gamma$ is a Droms $2$-labelled graph;
				\item The graph $\Gamma$ is Droms, and, for all connected induced subgraphs $\Lambda$ of $\Gamma$, either $\theta\vert_{V(\Lambda)}\equiv 0$, or there exists a central vertex $v$ of $\Lambda$ with $\theta(v)=1$;
				\item The ERA Lie algebra $\mf e(\Gamma)$ is BK;
				\item The ERA Lie algebra $\mf e(\Gamma)$ is weakly BK;
				\item All the standard subalgebras of the ERA Lie algebra $\mf e(\Gamma)$ are ERA Lie algebras; 
			\end{enumerate}
		\end{thm}
		\begin{proof}
			The implication (1)$\implies$(2) is Lemma \ref{lem:labelDroms}.


			Clearly, (5) implies both (3) and (4) by Proposition \ref{prop:ERAembed}(2).
			If $\Gamma$ is not a Droms labelled graph, then $\mf e(\Gamma)$ contains a non-quadratic standard subalgebra by Examples \ref{ex:nonBKRACG}, \ref{ex:nonBKERA}. This proves that any one of (3)-(5) implies (1). 

			It remains to show that (2) implies (5). 

			We argue by induction on the number of vertices of $\Gamma$. The base case being trivial, we suppose that $\Gamma$ has at least two vertices.

		 	Let $\Gamma$ be disconnected with one connected component $\Gamma_1$, and disjoint decomposition $\Gamma=\Gamma_1\sqcup \Gamma_2$. By induction, both the $\mf e(\Gamma_i)$'s satisfy (2) and (3), and $\mf e(\Gamma)=\mf e(\Gamma_1)\amalg\mf e(\Gamma_2)$. 
			It thus follows from the Kurosh subalgebra theorem \cite{sb} that if $\mf m$ is a standard restricted subalgebra of $\mf e(\Gamma)$, then there exist graphs $\Lambda_1$ and $\Lambda_2$, maps $\theta_i:V(\Lambda_i)\to \F_2$, and a free Lie algebra $\mf f$, such that $\mf m=\mf f\amalg\mf e(\Lambda_1,\theta_1)\amalg\mf e(\Lambda_2,\theta_2)$. Finally, notice that $\mf f$ is the ERA Lie algebra associated to a discrete graph $\Delta$ with $\theta_\Delta:V(\Delta)\to \{0\}\subset\F_2$, and hence the disjoint union $\Delta\sqcup\Lambda_1\sqcup\Lambda_2$ is a defining graph of $\mf m$, where the signature is defined in the obvious way.

			Suppose now $\Gamma$ is connected. If $\theta\equiv 0$, then $\mf e(\Gamma)$ is the RAAG Lie algebra $\mf a(\Gamma)$, which is BK when $\Gamma$ is a Droms graph. 
			On the other hand, if $\theta\not\equiv 0$, then there exists a central vertex $v$ of $\Gamma$ with $\theta(v)=1$, and hence $\mf e(\Gamma,\theta)\simeq\mf e(\Gamma_v,\theta')\times \mf k/\mf k\2$, where $\theta'$ is the restriction of $\theta$ to the induced subgraph $\Gamma_v$ spanned by the vertices $\neq v$. 
			If $\mf m$ is a standard subalgebra of $\mf e(\Gamma,\theta)\simeq \mf c(\Gamma_v,\theta')\times \mf k/\mf k\2$, then we argue as in Lemma \ref{lem:directbk}, and prove that there exists a standard subalgebra $\mf h$ of $\mf g:=\mf e(\Gamma_v,\theta')$ such that $\mf m$ is isomorphic to either $\mf h$ or $\mf h\times \mf k/\mf k\2$. By induction, $\mf h$ is an ERA Lie algebra, proving that the same is true for $\mf m$.
		\end{proof}
	In particular, this applies to RACG Lie algebras.

			\begin{cor}\label{prop:dromsRACG}
		Let $\mf c(\Gamma)$ be the RACG Lie algebra over $k$ associated to a simple graph $\Gamma$. Then, the following are equivalent:
			\begin{enumerate}
				\item 	$\Gamma$ is a Droms graph;
				\item $\mf c(\Gamma)$ is a BK restricted Lie algebra;
				\item All the standard restricted subalgebras of $\mf c(\Gamma)$ are ERA Lie algebras.
				\item All the ordinary standard subalgebras of $\mf c(\Gamma)$ are RAAG Lie algebras (\cite{sb}).
			\end{enumerate}
		\end{cor}



		\begin{cor}
			Let $V$ be a $k$-vector space with basis $(v_i)_{1\leq i\leq n}$, and let $\lambda:T(V)\to \Lambda(V)$ and $\sigma:T(V)\to S(V)$ be the natural projections. Let $E\subseteq\set{v_i\otimes v_j}{1\leq i,j\leq n}$. Then,

			\begin{center}
				$\Lambda(V)/\lambda(E)$ is universally Koszul iff $S(V)/\sigma(E)$ is universally Koszul.
			\end{center}
			\begin{proof}
				Let $\Gamma=(V,E')$, where $E'=\set{\{v_i,v_j\}}{v_i\otimes v_j\in E }$. Then, the RACG $\mf c(\Gamma)$ is a Bloch-Kato restricted Lie algebra if, and only if, the RAAG $\li_\Gamma$ is a Bloch-Kato (ordinary) Lie algebra. In other words, the restricted cohomology of $\mf c(\Gamma)$ is universally Koszul precisely when the Chevalley-Eilenberg cohomology of $\li_\Gamma$ is universally Koszul. 
			\end{proof}
		\end{cor}




