\section{Cusp bifurcation condition}
\label{sec:2}


For the cusp bifurcation, we consider the two-parameter case 
in eqs.(\ref{eqn:ODE}) and (\ref{eqn:TDE}):
%
\begin{eqnarray}
    \alpha=(\alpha_1,\alpha_2),
    \;\;\text{where }\;\; \alpha_1,\alpha_2>0.
    \label{eqn:parameter}
\end{eqnarray}
%
At the bifurcation point $(x,\alpha)=(\bar x, \bar \alpha)$, 
where $\bar\alpha =(\bar\alpha_1,\bar\alpha_2)$, 
$F(\bar x,\bar{\alpha})=0$ is satisfied, 
and the following relations are obtained 
regarding $F(\bar{x},\bar{\alpha})$ and $F_\tau (\bar{x}, \bar{\alpha})$:  
%
\begin{eqnarray}
    \displaystyle \frac{\partial F_\tau (\bar x, \bar{\alpha})}{\partial x}
    & = & 1+Z_\tau (\bar x, \bar \alpha)D(\bar x,\bar \alpha), 
    \label{eqn:dftau_dx} \\
    \displaystyle \frac{\partial F_{\tau}(\bar x, \bar \alpha)}{\partial \alpha_i} 
    & = & Z_\tau (\bar x, \bar \alpha)\frac{\partial F(\bar x, \bar \alpha)}{\partial \alpha_i}, \;\;\; (i=1,2),  
    \label{eqn:diff.relations1}
\end{eqnarray}
%
where 
%	
\begin{eqnarray}
    Z_\tau (\bar x, \bar \alpha)
    & = & \frac{\tau \bar x}{\bar x +\tau f(\bar x, \bar \alpha)},
    \label{eqn:Z-function} \\
    D(\bar{x},\bar \alpha)
    & = & \frac{\partial f}{\partial x}(\bar{x},\bar \alpha)-\frac{\partial g}{\partial x}(\bar{x},\bar \alpha).
    \label{eqn:D-function}
\end{eqnarray}
%
In eq.(\ref{eqn:Z-function}), 
$Z_\tau(\bar x,\bar \alpha)>0$ always holds, 
since $\bar{x}$, $f$, and $\tau$ are positive. 
%
In the case where eq.(\ref{eqn:ODE}) has the nonhyperbolic fixed point, 
$F(\bar x,\bar{\alpha})=0$ 
and $\displaystyle\frac{\partial F(\bar x, \bar \alpha)}{\partial x}=D(\bar{x},\bar{\alpha})=0$ hold, 
and we obtain 
%
\begin{eqnarray}
    \displaystyle\frac{\partial^2 F_{\tau}(\bar x, \bar \alpha)}{\partial^2 x} = Z_\tau (\bar x, \bar \alpha)\frac{\partial^2 F(\bar x, \bar \alpha)}{\partial^2 x}
    \label{eqn:diff.relations2}
\end{eqnarray}
%
and
%
\begin{eqnarray}
    & & \displaystyle\frac{\partial F_{\tau}(\bar x, \bar \alpha)}{\partial \alpha_1}\displaystyle\frac{\partial^2 F_{\tau}(\bar x, \bar \alpha)}{\partial x\partial \alpha_2}-\displaystyle\frac{\partial F_{\tau}(\bar x, \bar \alpha)}{\partial \alpha _2}\displaystyle\frac{\partial^2 F_{\tau}(\bar x, \bar \alpha)}{\partial x\partial \alpha_1}\nonumber \\
    &  & =
    Z_\tau ^2(\bar x, \bar \alpha)\left(   
    \displaystyle\frac{\partial F(\bar x, \bar \alpha)}{\partial \alpha_1}\displaystyle\frac{\partial^2 F(\bar x, \bar \alpha)}{\partial x\partial \alpha_2}-\displaystyle\frac{\partial F(\bar x, \bar \alpha)}{\partial \alpha _2}\displaystyle\frac{\partial^2 F(\bar x, \bar \alpha)}{\partial x\partial \alpha_1}\right).
    \label{eqn:diff.relations4}
\end{eqnarray}
%
Furthermore, when $\displaystyle\frac{\partial^2 F(\bar x, \bar \alpha)}{\partial^2 x}=0$ is satisfied, we obtain  
%
\begin{eqnarray}
    \displaystyle\frac{\partial^3 F_\tau(\bar x, \bar \alpha)}{\partial x^3} = Z_\tau (\bar x, \bar \alpha)\frac{\partial^3 F(\bar x, \bar \alpha)}{\partial x^3}.
    \label{eqn:diff.relation3}
\end{eqnarray}
%
% 
Based on eqs.(\ref{eqn:diff.relations2})-(\ref{eqn:diff.relation3}),  
the following proposition about the cusp bifurcation holds.
%
\begin{description}
%	
%
	\item[Proposition: cusp bifurcation condition]
%
		\ \\
		When eq.(\ref{eqn:ODE}) satisfies the condition 
		for the continuous cusp bifurcation 
        at the bifurcation point $(\bar x, \bar \alpha)$, which is 
        \[ 
          \displaystyle F(\bar x, \bar \alpha) = 0, 
		 \displaystyle \frac{\partial F(\bar x, \bar \alpha)}{\partial x}=0, 
          \displaystyle \frac{\partial^2 F(\bar x, \bar \alpha)}{\partial x^2} =0, 
          \displaystyle \frac{\partial^3 F(\bar x, \bar \alpha)}{\partial x^3} \not=0, \text{ and}
        \]
%
        \[
          \displaystyle \frac{\partial F(\bar x, \bar \alpha)}{\partial \alpha_1}\frac{\partial^2 F(\bar x, \bar \alpha)}{\partial x\partial \alpha_2}-\frac{\partial F(\bar x, \bar \alpha)}{\partial \alpha _2}\frac{\partial^2 F(\bar x, \bar \alpha)}{\partial x\partial \alpha_1} \not =0, 
        \]
%
		eq.(\ref{eqn:TDE}) also satisfies 
        the discrete cusp bifurcation condition \cite{Kuznetsov2023}
        at the cusp bifurcation point $(\bar x,\bar \alpha)$, 
        which is given as 
        \[ 
          \displaystyle F_\tau(\bar x, \bar \alpha) = \bar x, 	  \displaystyle \frac{\partial F_\tau(\bar x, \bar \alpha)}{\partial x}=1,  
          \displaystyle \frac{\partial^2 F_\tau(\bar x, \bar \alpha)}{\partial x^2} =0,  
          \displaystyle \frac{\partial^3 F_\tau(\bar x, \bar \alpha)}{\partial x^3} \not=0, \text{ and}
        \]
%
        \[ 
          \displaystyle \frac{\partial F_{\tau}(\bar x, \bar \alpha)}{\partial \alpha_1}\frac{\partial^2 F_{\tau}(\bar x, \bar \alpha)}{\partial x\partial \alpha_2}-\frac{\partial F_{\tau}(\bar x, \bar \alpha)}{\partial \alpha _2}\frac{\partial^2 F_{\tau}(\bar x, \bar \alpha)}{\partial x\partial \alpha_1} \not =0.
        \]
%
%
\end{description}
%
In the case of $\tau \to \infty$, 
eqs.(\ref{eqn:TDE}) and (\ref{eqn:Z-function}) become  
%
\begin{eqnarray}
    x_{n+1}=x_n\frac{f(x_n,\alpha)}{g(x_n,\alpha)}
    \label{eqn:TDE_tau_inf}
\end{eqnarray}
%
and 
%	
\begin{eqnarray}
    Z_\infty (\bar x, \bar \alpha)=\frac{\bar x}{f(\bar x, \bar \alpha)}, 
    \label{eqn:Z-function_infinity}
\end{eqnarray}
%
respectively.
%
Note that the above proposition 
for the cusp bifurcation condition holds 
even in the case of $\tau \to \infty$.
%
In other words, the cusp bifurcation 
of the original continuous dynamical system is retained  
in the discrete dynamical system 
obtained by the tropical discretization for any $\tau$.




