\begin{eqnarray}
    x_{n+1}=\displaystyle \frac{x_n+\tau r x_n}{1+\tau\left( \displaystyle\frac{r}{k}x_n+\frac{x_n}{1+x_n^2}\right)},
    \label{eqn:tropical_Ludwing}
\end{eqnarray}
%
where we set  
%
\begin{eqnarray}
    f(x,r,k)=rx~~
    \text{and}~~
    g(x,r,k)=\displaystyle\frac{rx^2}{k}+\frac{x^2}{1+x^2}.
    \label{eqn:f_and_g}
\end{eqnarray}
%
%
From the above proposition, eq.(\ref{eqn:tropical_Ludwing}) 
