  \end{minipage}
  \caption{ The graphs of eq.(\ref{eqn:UD_Ludwing}) for $R>K$. 
    (a) $K>0$ and (b) $K<0$.
    %
  }
  \label{Fig.1}
\end{figure}
%
%
Next we consider the case $R<K$, where
eq.(\ref{eqn:UD_Ludwing}) can be rewritten as
%
\begin{equation}
    X_{n+1} = \begin{cases}
        R & \left( X_{n} < 0 \right), \\
        2X_{n} + R & \left( 0 \leq X_{n} < \displaystyle \frac{K-R}{2} \right), \\
        K & \left( X_{n} \geq \displaystyle \frac{K-R}{2} \right).
    \end{cases}
    \label{eqn:UD_Ludwing_2}
\end{equation}
%
Equation (\ref{eqn:UD_Ludwing_2}) is piecewise linear and can be divided into the five cases according to the type of intersection 
with the identity line $X_{n+1} = X_n$, as shown in Fig.\ref{Fig.3}.
%
Specifically, Fig.\ref{Fig.3} illustrates the following five cases: 
(a) $R>0$, (b) $R=0$, (c) $R<0$ and $K>-R$, 
(d) $R<0$ and $K = -R$, and (e) $R<0$ and $K<-R$.
%
%
(a) For $R > 0$, 
it is clear that $X_n=K$ is a stable fixed point.
%
(b) For $R=0$, 
eq.(\ref{eqn:UD_Ludwing_2}) intersects the identity line 
at $X_n=K$ and $X_n=0$.
%
It is found that $X_n=K$ is a stable fixed point 
and $X_n=0$ is a half-stable fixed point.
%
(c) For $R<0$ and $K>-R$, eq.(\ref{eqn:UD_Ludwing_2}) has 
the three fixed points $X_{n} = K, \pm R$, 
where $X_n = +R,K$ are stable and $X_n = -R$ is unstable.
%
(d) For $R<0$ and $K = -R$, 
eq.(\ref{eqn:UD_Ludwing_2}) intersects the identity line 
at $X_n=R$ and $X_n=K$.
%
It is found that $X_n=R$ is a stable fixed point 
and $X_n=K$ is a half-stable fixed point.
%
(e) For $R<0$ and $K<-R$, 
it is clear that $X_n=R$ is a stable fixed point.
%
Therefore from above, the dynamical properties 
of eq.(\ref{eqn:UD_Ludwing}) are summarized as follows.
%
\begin{description}
%
%
%
\item [(1)] When $R>K$, $X_n=K$ is the unique fixed point and is stable.
%
\item [(2)]	When $R<K$,  
%
    \begin{description}
        \item[(2-i)] if $R>0$, 
        $X_n=K$ is the unique fixed point that is stable,
    %
        \item[(2-ii)] if $R<0$ and $K>-R$, 
        $X_n=\pm R$ $X_n=K$ are the fixed points.
        $+R$ and $K$ are stable (bistable) and $-R$ is unstable.
    %
        \item[(2-iii)] if $R<0$ and $K<-R$, 
        $X_n=R$ is the unique fixed point that is stable.
    \end{description}

%
\end{description}
%
%
%
