\subsubsection{Scope sequences and fully tilted terms} \label{subsubsec:fully_tilted_terms}
The \Def{scope sequence} of an $\Signature$-term $\TermT$ is the word $\Scope \App \TermT$
on $\N$ of length $\Deg \App \TermT$ such that for any $i \in \InternalNodes \App \TermT$,
$\Scope \App \TermT \App i$ is the number descendants of $i$ in $\TermT$. For instance,
\begin{equation}
    \GenA_4
    \GenA_0
    \ULine{
        \GenA_2 \ULine{\GenA_1 \LeafSimple} \ULine{\GenA_2 \LeafSimple \LeafSimple}
    }
    \ULine{
        \GenA_1 \ULine{\GenA_2 \LeafSimple \LeafSimple}
    }
    = 6 0 2 0 0 1 0.
\end{equation}

\begin{Statement}{Lemma}{lem:scope_sequence_parent}
    Let $\Signature$ be a signature and $\TermT$ be an $\Signature$-term. For any internal
    node $i$ of $\TermT$ different from the root, the parent of $i$ in $\TermT$ is the
    greatest internal node $i'$ of $\TermT$ such that $i' < i$ and $i' + \Scope \App \TermT
    \App i' \geq i$.
\end{Statement}
\begin{Proof}
    By definition of the word $\Scope \App \TermT$, in $\TermT$, an internal node $i$ is a
    descendant of an internal node $i'$ if and only if $i' + 1 \leq i \leq i' + \Scope \App
    \TermT \App i'$. Therefore, each ancestor $i'$ of $i$ in $\TermT$ satisfies $i' < i$ and
    $i' + \Scope \App \TermT \App i' \geq i$. The parent of $i$ in $\TermT$ is the greatest
    internal node among the ancestors of $i$. The statement of the lemma follows.
\end{Proof}

An $\Signature$-term $\TermT$ is \Def{fully tilted} if $\TermT$ is $\N \setminus
\Bra{0}$-tilted.

\begin{Statement}{Proposition}{prop:scope_sequence_fully_tilted}
    Let $\Signature$ be a signature, and $\TermT_1$ and $\TermT_2$ be two fully tilted
    $\Signature$-terms of the same degree $n$. We have $\TermT_1 \EasterlyWindLeq \TermT_2$
    if and only if, for any $i \in [n]$, $\Scope \App \TermT_1 \App i \leq \Scope \App
    \TermT_2 \App i$.
\end{Statement}
\begin{Proof}
    Assume that $\TermT_1$ and $\TermT_2$ are two fully tilted $\Signature$-terms such that
    $\TermT_1 \EasterlyWindLeq \TermT_2$. By Lemmas~\ref{lem:covering_edge_properties}
    and~\ref{lem:partial_order_sequence_rewrites}, for any internal node $i$ of both
    $\TermT_1$ and $\TermT_2$, the number of descendants of $i$ in $\TermT_1$ is smaller
    than or equal to the number of descendants of $i$ in $\TermT_2$. This implies that
    $\Scope \App \TermT_1 \App i \leq \Scope \App \TermT_2 \App i$.

    Conversely, assume that for any $i \in [n]$, $\Scope \App \TermT_1 \App i \leq \Scope
    \App \TermT_2 \App i$. Let $i \in [n]$ and $i_1$ (resp.\ $i_2$) be the parent of $i$ in
    $\TermT_1$ (resp.\ $\TermT_2$). Lemma~\ref{lem:scope_sequence_parent} together with the
    fact that each letter of $\Scope \App \TermT_2$ is greater than or equal to the letter
    at the same position of $\Scope \App \TermT_1$ imply that $i_2 \geq i_1$. Hence, the
    parent edge of $i$ in $\TermT_1$ (resp.\ $\TermT_2$) is $\Par{i_1, j_1, i}$ (resp.\
    $\Par{i_2, j_2, i}$) for some integer $j_1$ (resp.\ $j_2$). Since $\TermT_1$ (resp.\
    $\TermT_2$) is fully tilted, $j_1 = \LeftBrothers \App \TermT_1 \App i$ (resp.\ $j_2 =
    \LeftBrothers \App \TermT_2 \App i$). This implies that $i_1 < i_2$, or both $i_1 = i_2$
    and $j_1 \geq j_2$, so that the edge $\Par{i_1, j_1, i}$ is dominated by the edge
    $\Par{i_2, j_2, i}$. By Lemma~\ref{lem:order_domination}, we have $\TermT_1
    \EasterlyWindLeq \TermT_2$, as expected.
\end{Proof}

For any fully tilted $\Signature$-term $\TermT$, the \Def{fully tilted $\Signature$-easterly
wind poset of $\TermT$} is the $\N \setminus \Bra{0}$-tilted $\Signature$-easterly wind
poset of~$\TermT$.

