Finally, let $\BinaryTreesImage \App m$ be the set of $m$-binary trees $\TermR$ such that
from any internal node of $\TermR$ decorated by an $m - 1$-tree $\TermS$ of degree $k \geq
1$, there is a right branch consisting in $k - 1$ internal nodes decorated by $\LeafSimple$,
and each internal node decorated by $\LeafSimple$ in $\TermR$ is a part of such right
branch.

\begin{Statement}{Lemma}{lem:to_binary_tree_bijection}
    For any $m \in \N$, from the domain consisting in the set of $m$-trees and on the
    codomain $\BinaryTreesImage \App m$, the map $\ToBinaryTree$ is a bijection.
\end{Statement}
\begin{Proof}
    Let $\phi : \BinaryTreesImage \App m \to \SetTerms \App \Bra{m + 1}$ be the map defined
    recursively, for any $\TermR \in \BinaryTreesImage \App m$ of degree $n$, as follows.
    First, if $n = 0$, then $\TermR = \LeafSimple$. In this case, set $\phi \App \TermR :=
    \LeafSimple$. Otherwise, we have $n \geq 1$ and, from the description of
    $\BinaryTreesImage \App m$, $\TermR$ is the right comb $\TermR'$ of an $m - 1$-tree
    $\TermS$ of degree $k \geq 1$ such that for any $i \in [k]$, the $i$-th leaf of
    $\TermR'$ is attached to a subterm $\TermR_i$ of $\TermR$. Since for any $i \in [k]$,
    $\TermR_i$ belongs to $\BinaryTreesImage \App m$, the $m$-tree $\TermT_i := \phi \App
    \TermR_i$ is, by induction, well-defined. Let also $\TermT'$ be the $m$-tree obtained by
    adding to each internal node of $\TermS$ a leaf as first child. We define $\phi \App
    \TermR$ as the $m$-tree obtained by replacing, for any $i \in [k]$, the first leaf of
    the internal node $i$ of $\TermT'$ by $\TermT_i$. It follows by induction on $n$ that
    $\phi$ is a well-defined map. Again by induction on $n$, it is straightforward to show
    that $\phi$ is the inverse map of $\ToBinaryTree$.
\end{Proof}

The \Def{inorder traversal} of an $m$-binary tree $\TermR$ is defined recursively as
follows. It $\TermR = \LeafSimple$, then the inorder traversal of $\TermR$ is empty.
Otherwise, we have $\TermR = \TermS \, \TermR_1 \TermR_2$ where $\TermS$ is an $m - 1$-tree,
and $\TermR_1$ and $\TermR_2$ are two $m$-binary trees. In this case, $\TermR_1$ is visited
according to the inorder traversal, then the root of $\TermR$, and finally, $\TermR_2$ is
visited according to the inorder traversal. This procedure induces a total order on the
internal nodes of $\TermR$ where the first visited internal node is the smallest one. Now,
let the map $\ToForest$ from the set of $m$-binary trees to the set of balanced $\N$-forests
such that, for any $m$-binary tree $\TermR$ of degree $n$, $\ToForest \App \TermR$ is the
$\N$-forest $n \, \TermS_1 \dots \TermS_n$ where for any $i \in [n]$, $\TermS_i$ is the
decoration of the $i$-th visited internal node of $\TermR$ w.r.t.\ the inorder traversal of
$\TermR$. For instance, by considering the $3$-binary tree $\TermR$ of the right-hand side
of~\eqref{equ:example_to_binary_tree},
\begin{equation}
    \ToForest \App \TermR
    =
    7 \,
    \ULine{\Corolla \App 3}
    \ULine{
        3 \,
        \ULine{\Corolla \App 3}
        \LeafSimple
        \ULine{\Corolla \App 3}
    }
    \LeafSimple
    \ULine{\Corolla \App 3}
    \ULine{3 \, \LeafSimple \LeafSimple \ULine{\Corolla \App 3}}
    \LeafSimple
    \LeafSimple.
\end{equation}

\begin{Statement}{Lemma}{lem:to_forest_bijection}
    For any $m \in \N$, from the domain $\BinaryTreesImage \App m$ and on the codomain
    $\bigcup_{n \in \N} \TerminalInterval \App \Par{\ForestMin \App m^n}$, the map
    $\ToForest $ is a bijection.
\end{Statement}
\begin{Proof}
    Let $\phi : \bigcup_{n \in \N} \TerminalInterval \App \Par{\ForestMin \App m^n} \to
    \BinaryTreesImage \App m$ be the map defined recursively, for any $\ForestF \in
    \TerminalInterval \App \Par{\ForestMin \App m^n}$, $n \in \N$, as follows. First,
    if $n = 0$, then $\ForestF = 0$. In this case, set $\phi \App \ForestF := \LeafSimple$.
    Otherwise, we have $n \geq 1$ and by Lemma~\ref{lem:fuss_catalan_posets_objects}, it
    follows by induction on $n$ that $\ForestF$ decomposes as
    \begin{equation}
        \ForestF =
        \ForestF_1 \; \Conc \;
        1 \, \TermS
        \; \Conc \; k - 1 \, \underbrace{\LeafSimple \dots \LeafSimple}_{k - 1}
        \; \Conc \; \ForestF_2
    \end{equation}
    where $\ForestF_1$ and $\ForestF_2$ are two $\N$-forests and $\TermS$ is an $m - 1$-tree
    $\TermS$ of degree $k \geq 1$. Let us consider this decomposition when the size $\ell
    \geq 0$ of $\ForestF_1$ is minimal. Since $\ForestF_1 \Conc \ForestF_2$ satisfies the
    conditions described in Lemma~\ref{lem:fuss_catalan_posets_objects}, the $m$-binary tree
    $\TermR := \phi \App \ULine{\ForestF_1 \Conc \ForestF_2}$ is, by induction,
    well-defined. Let also $\TermR'$ be the right comb of $\TermS$. We define $\phi \App
    \ForestF$ as the $m$-binary tree obtained by inserting the root of $\TermR'$ onto the
    unique edge of $\TermR$ such that, w.r.t.\ the inorder traversal, the internal nodes
    coming from $\ForestF_1$ are visited first, then the ones of $\TermR'$ are visited, and
    finally the ones coming from $\ForestF_2$ are visited. It follows by induction on $n$
    that $\phi$ is a well-defined map. Again by induction on $n$, it is straightforward to
    show that $\phi$ is the inverse map of~$\ToForest$.
\end{Proof}

\begin{Statement}{Theorem}{thm:fuss_catalan_posets}
    For any $m, n \in \N$, the underlying set of the $m$-Fuss-Catalan easterly wind poset of
    order $n$ is in one-to-one correspondence with the set of $m$-trees of degree $n$. The
    map $\ToForest \circ \ToBinaryTree$ is such a one-to-one correspondence.
\end{Statement}
\begin{Proof}
    By Lemma~\ref{lem:to_binary_tree_bijection}, $\ToBinaryTree$ is a bijection between the
    set of $m$-trees and $\BinaryTreesImage \App m$. Moreover, By
    Lemma~\ref{lem:to_forest_bijection}, $\ToForest$ is a bijection between
    $\BinaryTreesImage \App m$ and $\bigcup_{n \in \N} \TerminalInterval \App
    \ULine{\ForestMin \App m^n}$. Since these two bijections preserve the degree, the
    composition $\ToForest \circ \ToBinaryTree$ satisfies the property described in the
    statement of the theorem.
\end{Proof}

By Theorem~\ref{thm:fuss_catalan_posets}, the $m$-Fuss-Catalan easterly wind posets involve
the combinatorial family of Fuss-Catalan objects. Hence, the cardinality of such posets of
order $n$ is
\begin{equation}
    \frac{1}{mn + 1} \binom{mn + n}{n}.
\end{equation}
Many other posets involving this family of objects exist~\cite{BPR12,CG22}, and our posets
differ from those presented in the cited works.

