            \draw[Edge](1)--(5);
            \draw[Edge](2)--(3);
            \draw[Edge](2)--(4);
            \draw[Edge](5)--(6);
        \end{tikzpicture}
    }.
\end{equation}
Moreover, the \Def{fully tilted term} $\ToFullyTiltedTerm \App \TermR$ of a rooted tree
$\TermR$ is the fully tilted $\N$-term obtained by labelling from $n - 1$ to $0$ the nodes
of $\TermR$ w.r.t.\ the preorder traversal and then, by grafting to each node some leaves as
rightmost children such that each node labeled by $k$ has $k$ children. This ensures that
$\ToFullyTiltedTerm \App \TermR$ is fully tilted. For instance,
\begin{equation}
    \ToFullyTiltedTerm
    \App
    \scalebox{.65}{
        \begin{tikzpicture}[Centering,xscale=0.6,yscale=0.60]
            \node[Node](1)at(1.25,0){};
            \node[Node](2)at(0.5,-1){};
