    =
    5 \,
    \ULine{
        4 \,
        \ULine{3 \, \LeafSimple \LeafSimple \LeafSimple}
        \ULine{2 \, \LeafSimple \LeafSimple}
        \LeafSimple
        \LeafSimple
    }
    \ULine{1 \, 0}
    \LeafSimple
    \LeafSimple
    \LeafSimple.
\end{equation}

\begin{Statement}{Lemma}{lem:rooted_trees_bijection}
    For any $n \in \N$, the map $\ToRootedTree$ is a  one-to-one correspondence from the
    underlying set of the rooted tree easterly wind poset of order $n$ and the set of
    rooted trees of size~$n$.
\end{Statement}
\begin{Proof}
    Let $T$ be the underlying set of the rooted tree easterly wind poset of order $n$. The
    fact that the map $\ToRootedTree$ on the domain $T$ is injective is a consequence of the
    fact that all $\N$-terms of $T$ are fully tilted. Let us show that each rooted tree
    $\TermR$ admits an antecedent in $T$ for the map $\ToRootedTree$. By setting $\TermT :=
    \ToFullyTiltedTerm \App \TermR$, from the definitions of the maps $\ToRootedTree$ and
    $\ToFullyTiltedTerm$, it follows immediately that $\ToRootedTree \App \TermT = \TermR$.
    It remains to prove that $\TermT$ belongs to $T$. By construction of the $\N$-term
    $\ForestMin \App \ULine{\DecreasingWord \App n}$, for any internal node $i$ of $\TermT$,
    the parent edge of $i$ in $\ForestMin \App \ULine{\DecreasingWord \App n}$ is dominated
    by that of $i$ in $\TermT$. Hence, by Lemma~\ref{lem:order_domination}, $\ForestMin \App
    \ULine{\DecreasingWord \App n} \EasterlyWindLeq \TermT$. This shows that $\TermT \in T$
    and implies the statement of the lemma.
\end{Proof}

The \Def{scope sequence} of a rooted tree $\TermR$ of size $n$ is the word $\Scope \App
\TermR$ of length $n$ such that for any $i \in [n]$, $\Scope \App \TermR \App i$ is the
number descendants of the $i$-th visited node in the preorder traversal of $\TermR$. For
instance,
\begin{equation}
    \Scope
    \App
    \scalebox{.65}{
        \begin{tikzpicture}[Centering,xscale=0.6,yscale=0.60]
            \node[Node](1)at(1.25,0){};
            \node[Node](2)at(0.5,-1){};
            \node[Node](3)at(0,-2){};
            \node[Node](4)at(1,-2){};
            \node[Node](5)at(2,-1){};
            \node[Node](6)at(2,-2){};
            \draw[Edge](1)--(2);
            \draw[Edge](1)--(5);
            \draw[Edge](2)--(3);
            \draw[Edge](2)--(4);
            \draw[Edge](5)--(6);
        \end{tikzpicture}
    }
    =
    5 2 0 0 1 0.
\end{equation}
Observe that the scope sequence of an $\Signature$-term $\TermT$ as defined in
Section~\ref{subsubsec:fully_tilted_terms} and the scope sequence of the rooted tree
$\ToRootedTree \App \TermT$ coincide, that is $\Scope \App \ULine{\ToRootedTree \App \TermT}
= \Scope \App \TermT$.

The \Def{Tamari partial order}~\cite{Tam62} is a partial order $\TamariLeq$ defined on the
family of Catalan objects of a given size. We consider here the following description of
this order involving rooted trees~\cite{Knu04}. Given two rooted trees $\TermR_1$ and
$\TermR_2$ of the same size $n$, $\TermR_1 \TamariLeq \TermR_2$ holds if and only if for any
$i \in [n]$, $\Scope \App \TermR_1 \App i \leq \Scope \App \TermR_2 \App i$.

\begin{Statement}{Proposition}{prop:rooted_tree_lattices}
    For any $n \in \N$, the map $\ToRootedTree$ is a poset isomorphism between the rooted
    tree easterly wind poset of order $n$ and the Tamari poset of order~$n$.
\end{Statement}
\begin{Proof}
    Let $T$ be the underlying set of the rooted tree easterly wind poset of order $n$. First
    of all, by Lemma~\ref{lem:rooted_trees_bijection}, the map $\ToRootedTree$ is a
    bijection between $T$ and the underlying set of the Tamari poset of order $n$. It
    remains to prove that $\ToRootedTree$ is an order embedding, that is, for any $\TermT_1,
    \TermT_2 \in T$, $\TermT_1 \EasterlyWindLeq \TermT_2$ if and only if $\ToRootedTree \App
    \TermT_1 \TamariLeq \ToRootedTree \App \TermT_2$. This property is a consequence of
    Proposition~\ref{prop:scope_sequence_fully_tilted} and the fact that, as noticed above,
    for any $\N$-term $\TermT$, $\Scope \App \TermT = \Scope \App \ULine{\ToRootedTree \App
    \TermT}$.
\end{Proof}

