%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Fundamental and homogeneous bases} \label{subsec:basis_f_h}
We introduce a two new bases of the natural Hopf algebra of a free operad. These bases mimic
well-known constructions of bases in combinatorial Hopf algebras defined by summing on
intervals of particular posets. Here, the posets intervening in this new basis are the
leaning forest $\Signature$-easterly wind posets.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Fundamental basis}
Let us use the leaning forest $\Signature$-easterly wind posets to build a new basis of
$\NaturalHopfAlgebra \App \ULine{\SetTerms \App \Signature}$. For any leaning
$\Signature$-forest $\ForestF$, let
\begin{equation}
    \BasisF_\ForestF :=
    \sum_{\ForestF' \in \SetLeaningForests \App \Signature}
    \Iverson{\ForestF \EasterlyWindLeq \ForestF'} \;
    \ULine{\Mobius \App \Bra{1} \App \ForestF \App  \ForestF'} \;
    \BasisE_{\ForestF'},
\end{equation}
where $\SetLeaningForests \App \Signature$ is the set defined in
Section~\ref{subsubsec:leaning_forests}, $\EasterlyWindLeq$ is the partial order relation of
the leaning forest $\Signature$-easterly wind posets, and, in accordance with the notations
introduced at the end of Section~\ref{subsubsec:el_shellability}, $\Mobius \App \Bra{1}$ is
the Möbius function of these lattices. For instance, in $\NaturalHopfAlgebra \App
\ULine{\SetTerms \App \SignatureExample}$,
\begin{equation}
    \BasisF_{
        3 \,
        \ULine{\GenA_3 \LeafSimple \ULine{\GenA_1 \LeafSimple} \LeafSimple}
        \ULine{\GenA_2 \LeafSimple \LeafSimple} \LeafSimple
    }
    =
    \BasisE_{
        3 \,
        \ULine{\GenA_3 \LeafSimple \ULine{\GenA_1 \LeafSimple} \LeafSimple}
        \ULine{\GenA_2 \LeafSimple \LeafSimple} \LeafSimple
    }
    -
    \BasisE_{
        3 \, \ULine{\GenA_3 \LeafSimple \ULine{\GenA_1 \LeafSimple}
        \ULine{\GenA_2 \LeafSimple \LeafSimple}} \LeafSimple \LeafSimple
    }
    -
    \BasisE_{
        3 \, \ULine{\GenA_3 \ULine{\GenA_1 \LeafSimple} \LeafSimple \LeafSimple}
        \ULine{\GenA_2 \LeafSimple \LeafSimple} \LeafSimple
    }
    -
    \BasisE_{
        3 \, \ULine{\GenA_3 \ULine{\GenA_1 \LeafSimple} \LeafSimple
        \ULine{\GenA_2 \LeafSimple \LeafSimple}} \LeafSimple \LeafSimple
    }.
\end{equation}
By Möbius inversion and triangularity, for any leaning $\Signature$-forest~$\ForestF$,
\begin{equation}
    \BasisE_\ForestF =
    \sum_{\ForestF' \in \SetLeaningForests \App \Signature}
    \Iverson{\ForestF \EasterlyWindLeq \ForestF'} \; \BasisF_{\ForestF'},
\end{equation}
so that the set $\Bra{\BasisF_\ForestF : \ForestF \in \SetLeaningForests \App
\Signature}$ is a basis of $\NaturalHopfAlgebra \App \ULine{\SetTerms \App \Signature}$,
called the \Def{fundamental basis} (or \Def{$\BasisF$-basis} for short).

We can now state one of the main results of this work.

\begin{Statement}{Theorem}{thm:product_fundamental_basis}
    For any signature $\Signature$ and any leaning $\Signature$-forests $\ForestF_1$ and
    $\ForestF_2$,
    \begin{equation} \label{equ:product_fundamental_basis_1}
        \BasisF_{\ForestF_1} \Product \BasisF_{\ForestF_2}
        = \sum_{\ForestF \in \SetLeaningForests \App \Signature}
        \Iverson{
            \ForestF_1 \Over \ForestF_2 \EasterlyWindLeq \ForestF
            \EasterlyWindLeq \ForestF_1 \Under \ForestF_2
        }
        \; \BasisF_\ForestF.
    \end{equation}
\end{Statement}
\begin{Proof}
    Let $\Product'$ be the product on $\NaturalHopfAlgebra \App \ULine{\SetTerms \App
    \Signature}$ such that for any $\Signature$-forests $\ForestF_1$ and $\ForestF_2$,
    $\BasisF_{\ForestF_1} \Product' \BasisF_{\ForestF_2}$ is the right-hand side
    of~\eqref{equ:product_fundamental_basis_1}. For any leaning $\Signature$-forests
    $\ForestF_1$ and $\ForestF_2$, by denoting by $n_1$ the size of $\ForestF_1$ and by
    using Proposition~\ref{prop:leaning_forest_shuffle_interval} and
    Lemma~\ref{lem:over_under_restriction}, we have
    \begin{align}
        \BasisE_{\ForestF_1} \Product' \BasisE_{\ForestF_2}
        & =
        \sum_{\ForestF_1' \in \SetLeaningForests \App \Signature}
        \sum_{\ForestF_2' \in \SetLeaningForests \App \Signature}
        \Iverson{\ForestF_1 \EasterlyWindLeq \ForestF_1'}
        \Iverson{\ForestF_2 \EasterlyWindLeq \ForestF_2'}
        \;
        \BasisF_{\ForestF_1'} \Product' \BasisF_{\ForestF_2'}
        \\
        & =
        \sum_{\ForestF_1' \in \SetLeaningForests \App \Signature}
        \sum_{\ForestF_2' \in \SetLeaningForests \App \Signature}
        \sum_{\ForestF \in \SetLeaningForests \App \Signature}
        \Iverson{\ForestF_1 \EasterlyWindLeq \ForestF_1'}
        \Iverson{\ForestF_2 \EasterlyWindLeq \ForestF_2'}
        \Iverson{
            \ForestF_1' \Over \ForestF_2' \EasterlyWindLeq \ForestF
            \EasterlyWindLeq \ForestF_1' \Under \ForestF_2'
        }
        \;
        \BasisF_\ForestF
        \notag
        \\
        & =
        \sum_{\ForestF_1' \in \SetLeaningForests \App \Signature}
        \sum_{\ForestF_2' \in \SetLeaningForests \App \Signature}
        \Iverson{\ForestF_1 \EasterlyWindLeq \ForestF_1'}
        \Iverson{\ForestF_2 \EasterlyWindLeq \ForestF_2'}
        \sum_{\ForestF \in \ForestF_1' \cshuffle \ForestF_2'}
        \BasisF_\ForestF
        \notag
        \\
        & =
        \sum_{\ForestF_1' \in \SetLeaningForests \App \Signature}
        \sum_{\ForestF_2' \in \SetLeaningForests \App \Signature}
        \Iverson{\ForestF_1 \EasterlyWindLeq \ForestF_1'}
        \Iverson{\ForestF_2 \EasterlyWindLeq \ForestF_2'}
        \sum_{\ForestF \in \SetLeaningForests \App \Signature}
        \Iverson{\Top \App n_1 \App \ForestF = \ForestF_1'}
        \Iverson{\Bottom \App n_1 \App \ForestF = \ForestF_2'}
        \;
        \BasisF_\ForestF
        \notag
        \\
        & =
        \sum_{\ForestF \in \SetLeaningForests \App \Signature}
        \Iverson{\ForestF_1 \EasterlyWindLeq \Top \App n_1 \App \ForestF}
        \Iverson{\ForestF_2 \EasterlyWindLeq \Bottom \App n_1 \App \ForestF}
        \;
        \BasisF_\ForestF
        \notag
        \\
        & =
        \sum_{\ForestF \in \SetLeaningForests \App \Signature}
        \Iverson{\ForestF_1 \Over \ForestF_2 \EasterlyWindLeq \ForestF}
        \;
        \BasisF_\ForestF
        \notag
        \\
        & =
        \BasisE_{\ForestF_1 \Over \ForestF_2}.
        \notag
    \end{align}
    This shows that
    \begin{math}
        \BasisE_{\ForestF_1} \Product' \BasisE_{\ForestF_2}
        =
        \BasisE_{\ForestF_1} \Product \BasisE_{\ForestF_2},
    \end{math}
    so that $\Product'$ and $\Product$ are the same products. Therefore,
    \eqref{equ:product_fundamental_basis_1} holds.
\end{Proof}

The product of $\NaturalHopfAlgebra \App \ULine{\SetTerms \App \Signature}$ on the
$\BasisF$-basis is akin to a shuffle of reduced $\Signature$-forests. For instance, in
$\NaturalHopfAlgebra \App \ULine{\SetTerms \App \SignatureExample}$, we have
\begin{align}
    \BasisF_{
        \ColA{
            3 \,
            \ULine{\GenA_3 \LeafSimple \LeafSimple \LeafSimple}
            \ULine{\GenA_2 \LeafSimple \ULine{\GenA_2 \LeafSimple \LeafSimple}}
            \LeafSimple
        }
    }
    \Product
    \BasisF_{
        \ColB{
            4 \,
            \ULine{\GenA_3 \LeafSimple \ULine{\GenA_2 \LeafSimple \LeafSimple} \LeafSimple}
            \ULine{\GenA_1 \LeafSimple}
            \ULine{\GenA_2 \LeafSimple \LeafSimple}
            \LeafSimple
        }
    }
    & =
    \BasisF_{
        7 \,
        \ColA{
            \ULine{\GenA_3 \LeafSimple \LeafSimple \LeafSimple}
            \ULine{\GenA_2 \LeafSimple \ULine{\GenA_2 \LeafSimple \LeafSimple}}
        }
        \ColB{
            \ULine{\GenA_3 \LeafSimple \ULine{\GenA_2 \LeafSimple \LeafSimple} \LeafSimple}
            \ULine{\GenA_1 \LeafSimple}
            \ULine{\GenA_2 \LeafSimple \LeafSimple}
        }
        \LeafSimple
        \LeafSimple
    }
    \\
    & \quad +
    \BasisF_{
        7 \,
        \ColA{
            \ULine{\GenA_3 \LeafSimple \LeafSimple \LeafSimple}
            \ULine{
                \GenA_2 \LeafSimple \ULine{\GenA_2 \LeafSimple
                \ColB{\ULine{\GenA_3 \LeafSimple \ULine{\GenA_2 \LeafSimple \LeafSimple}
                \LeafSimple}}
            }}
        }
        \ColB{
            \ULine{\GenA_1 \LeafSimple}
            \ULine{\GenA_2 \LeafSimple \LeafSimple}
        }
        \LeafSimple
        \LeafSimple
        \LeafSimple
    }
    \notag
    \\
    & \quad +
    \BasisF_{
        7 \,
        \ColA{
            \ULine{\GenA_3 \LeafSimple \LeafSimple \LeafSimple}
            \ULine{
                \GenA_2 \LeafSimple \ULine{\GenA_2
                \ColB{\ULine{\GenA_3 \LeafSimple \ULine{\GenA_2 \LeafSimple \LeafSimple}
                \LeafSimple}}
                \LeafSimple
            }}
        }
        \ColB{
            \ULine{\GenA_1 \LeafSimple}
            \ULine{\GenA_2 \LeafSimple \LeafSimple}
        }
        \LeafSimple
        \LeafSimple
        \LeafSimple
    }
    \notag
    \\
    & \quad +
    \BasisF_{
        7 \,
        \ColA{
            \ULine{\GenA_3 \LeafSimple \LeafSimple \LeafSimple}
            \ULine{
                \GenA_2 \LeafSimple \ULine{\GenA_2
                \ColB{\ULine{\GenA_3 \LeafSimple \ULine{\GenA_2 \LeafSimple \LeafSimple}
                \LeafSimple}}
                \ColB{\ULine{\GenA_1 \LeafSimple}}
            }}
        }
        \ColB{
            \ULine{\GenA_2 \LeafSimple \LeafSimple}
        }
        \LeafSimple
        \LeafSimple
        \LeafSimple
        \LeafSimple
    }.
    \notag
\end{align}

Observe that the fundamental basis of $\NaturalHopfAlgebra \App \ULine{\SetTerms \App
\Signature}$ coincides with the ribbon basis of $\NCSF$~\cite{GKLLRT95}. Indeed, by
employing the notation introduced in Section~\ref{subsubsec:ncsf}, for any integer
compositions $\Par{r_1, \dots, r_k}$, $k \geq 0$, and $\Par{r'_1, \dots, r'_{k'}}$, $k' \geq
0$, we have
\begin{equation}
    \BasisF_{\Par{r_1, \dots, r_k}}
    \Product
    \BasisF_{\Par{r'_1, \dots, r'_{k'}}}
    =
    \BasisF_{\Par{r_1, \dots, r_k, r'_1, \dots, r'_{k'}}}
    +
    \BasisF_{\Par{r_1, \dots, r_k + r'_1, \dots, r'_{k'}}}.
\end{equation}
This product is the one of $\NCSF$ through its ribbon basis.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Homogeneous basis}
Let us use again the leaning forest $\Signature$-easterly wind posets to build a new basis
of $\NaturalHopfAlgebra \App \ULine{\SetTerms \App \Signature}$. For any leaning
$\Signature$-forest $\ForestF$, let
\begin{equation}
    \BasisH_\ForestF :=
    \sum_{\ForestF' \in \SetLeaningForests \App \Signature}
    \Iverson{\ForestF' \EasterlyWindLeq \ForestF} \;
    \BasisF_{\ForestF'}.
\end{equation}
For instance, in $\NaturalHopfAlgebra \App \ULine{\SetTerms \App \SignatureExample}$,
\begin{equation}
    \BasisH_{
        3 \, \ULine{\GenA_3 \LeafSimple \ULine{\GenA_1 \LeafSimple} \LeafSimple}
        \ULine{\GenA_2 \LeafSimple \LeafSimple} \LeafSimple
    }
    =
    \BasisF_{
        3 \, \ULine{\GenA_3 \LeafSimple \LeafSimple \LeafSimple} \ULine{\GenA_1 \LeafSimple}
        \ULine{\GenA_2 \LeafSimple \LeafSimple}
    }
    +
    \BasisF_{
        3 \, \ULine{\GenA_3 \LeafSimple \LeafSimple \ULine{\GenA_1 \LeafSimple}}
        \ULine{\GenA_2 \LeafSimple \LeafSimple} \LeafSimple
    }
    +
    \BasisF_{
        3 \, \ULine{\GenA_3 \LeafSimple \ULine{\GenA_1 \LeafSimple} \LeafSimple}
        \ULine{\GenA_2 \LeafSimple \LeafSimple} \LeafSimple
    }.
\end{equation}
By Möbius inversion and triangularity, for any leaning $\Signature$-forest $\ForestF$,
\begin{equation}
    \BasisF_\ForestF =
    \sum_{\ForestF' \in \SetLeaningForests \App \Signature}
    \Iverson{\ForestF' \EasterlyWindLeq \ForestF} \;
    \ULine{\Mobius \App \Bra{1} \App \ForestF' \App \ForestF} \;
    \BasisH_{\ForestF'},
\end{equation}
so that the set $\Bra{\BasisH_\ForestF : \ForestF \in \SetLeaningForests \App \Signature}$
is a basis of $\NaturalHopfAlgebra \App \ULine{\SetTerms \App \Signature}$, called the
\Def{homogeneous basis} (or \Def{$\BasisH$-basis} for short).

We can now state one of the main results of this work.

\begin{Statement}{Theorem}{thm:product_homogeneous_basis}
    For any signature $\Signature$ and any leaning $\Signature$-forests $\ForestF_1$ and
    $\ForestF_2$,
    \begin{equation} \label{equ:product_homogeneous_basis_1}
        \BasisH_{\ForestF_1} \Product \BasisH_{\ForestF_2}
        = \BasisH_{\ForestF_1 \Under \ForestF_2}.
    \end{equation}
\end{Statement}
\begin{Proof}
    For any leaning $\Signature$-forests $\ForestF_1$ and $\ForestF_2$, by denoting by $n_1$
    the size of $\ForestF_1$ and by using Theorem~\ref{thm:product_fundamental_basis},
    Proposition~\ref{prop:leaning_forest_shuffle_interval}, and
    Lemma~\ref{lem:over_under_restriction}, we have
    \begin{align}
        \BasisH_{\ForestF_1} \Product \BasisH_{\ForestF_2}
        & =
        \sum_{\ForestF_1' \in \SetLeaningForests \App \Signature}
        \sum_{\ForestF_2' \in \SetLeaningForests \App \Signature}
        \Iverson{\ForestF_1' \EasterlyWindLeq \ForestF_1}
        \Iverson{\ForestF_2' \EasterlyWindLeq \ForestF_2}
        \;
        \BasisF_{\ForestF_1'} \Product \BasisF_{\ForestF_2'}
        \\
        & =
        \sum_{\ForestF_1' \in \SetLeaningForests \App \Signature}
        \sum_{\ForestF_2' \in \SetLeaningForests \App \Signature}
        \sum_{\ForestF \in \SetLeaningForests \App \Signature}
        \Iverson{\ForestF_1' \EasterlyWindLeq \ForestF_1}
        \Iverson{\ForestF_2' \EasterlyWindLeq \ForestF_2}
        \Iverson{
            \ForestF_1' \Over \ForestF_2' \EasterlyWindLeq \ForestF
            \EasterlyWindLeq \ForestF_1' \Under \ForestF_2'
        }
        \;
        \BasisF_\ForestF
        \notag
        \\
        & =
        \sum_{\ForestF_1' \in \SetLeaningForests \App \Signature}
        \sum_{\ForestF_2' \in \SetLeaningForests \App \Signature}
        \Iverson{\ForestF_1' \EasterlyWindLeq \ForestF_1}
        \Iverson{\ForestF_2' \EasterlyWindLeq \ForestF_2}
        \sum_{\ForestF \in \ForestF_1' \cshuffle \ForestF_2'}
        \BasisF_\ForestF
        \notag
        \\
        & =
        \sum_{\ForestF_1' \in \SetLeaningForests \App \Signature}
        \sum_{\ForestF_2' \in \SetLeaningForests \App \Signature}
        \Iverson{\ForestF_1' \EasterlyWindLeq \ForestF_1}
        \Iverson{\ForestF_2' \EasterlyWindLeq \ForestF_2}
        \sum_{\ForestF \in \SetLeaningForests \App \Signature}
        \Iverson{\Top \App n_1 \App \ForestF = \ForestF_1'}
        \Iverson{\Bottom \App n_1 \App \ForestF = \ForestF_2'}
        \;
        \BasisF_\ForestF
        \notag
        \\
        & =
        \sum_{\ForestF \in \SetLeaningForests \App \Signature}
        \Iverson{\Top \App n_1 \App \ForestF \EasterlyWindLeq \ForestF_1}
        \Iverson{\Bottom \App n_1 \App \ForestF \EasterlyWindLeq \ForestF_2}
        \;
        \BasisF_\ForestF
        \notag
        \\
        & =
        \sum_{\ForestF \in \SetLeaningForests \App \Signature}
        \Iverson{\ForestF \EasterlyWindLeq \ForestF_1 \Under \ForestF_2}
        \;
        \BasisF_\ForestF
        \notag
        \\
        & =
        \BasisH_{\ForestF_1 \Under \ForestF_2}.
        \notag
    \end{align}
    This shows that~\eqref{equ:product_homogeneous_basis_1} holds.
\end{Proof}

By employing the notation introduced at the end of
Section~\ref{subsubsec:hopf_algebras_forests}, the $\BasisH$-basis of $\NCSF$ admits the
following expression for its product. For any integer compositions $\Par{r_1,
\dots, r_k}$, $k \geq 0$, and $\Par{r'_1, \dots, r'_{k'}}$, $k' \geq 0$, we have
\begin{equation}
    \BasisH_{\Par{r_1, \dots, r_k}}
    \Product
    \BasisH_{\Par{r'_1, \dots, r'_{k'}}}
    =
    \BasisH_{\Par{r_1, \dots, r_k + r'_1, \dots, r'_{k'}}}.
\end{equation}

